-- Pediatrics question bank: exactly 1250 hand-written NCLEX-style
-- questions (single-best-answer + select-all-that-apply), 50 per note. Every answer is grounded in
-- (and its rationale limited to) the source note listed for its topic:
--   Notes/Pediatrics/Kawasaki-Disease.html
--   Notes/Pediatrics/Amblyopia.html
--   Notes/Pediatrics/Congenital-Cataracts.html
--   Notes/Pediatrics/Pediatric-Conjunctivitis.html
--   Notes/Pediatrics/Retinopathy-of-Prematurity.html
--   Notes/Pediatrics/Strabismus.html
--   Notes/Pediatrics/Pediatric-Developmental-Stages.html
--   Notes/Pediatrics/Rickets.html
--   Notes/Pediatrics/Pediatric-Ortho.html
--   Notes/Pediatrics/Omphalocele.html
--   Notes/Pediatrics/Pediatric-Medication-Administration.html
--   Notes/Pediatrics/Care-of-the-Newborn.html
--   Notes/Pediatrics/Pediatric-Respiratory-Disorders.html
--   Notes/Pediatrics/Pediatric-Cardiovascular-Nursing.html
--   Notes/Pediatrics/Pediatric-Neuro-Psych-Disorders.html
--   Notes/Pediatrics/Pediatric-Diabetes.html
--   Notes/Pediatrics/Pediatric-Fever-Dehydration-PKU.html
--   Notes/Pediatrics/Pediatric-GI-Disorders.html
--   Notes/Pediatrics/Pediatric-Hematological-Oncological.html
--   Notes/Pediatrics/Pediatric-Infectious-Diseases.html
--   Notes/Pediatrics/Pediatric-Renal-GU.html
--   Notes/Pediatrics/Pediatric-Musculoskeletal.html
--   Notes/Pediatrics/Pediatric-Integumentary.html
--   Notes/Pediatrics/Pediatric-Eye-Ear-Throat.html
--   Notes/Pediatrics/Pediatric-Cognitive-Neuro-Psych.html
--
-- Maps each source path through note_catalog.note_id to the published test_topics
-- row(s) for that note (matching test.html's note-level topic grouping). All
-- missing/ambiguous mappings are reported before any deletion or insertion.
-- Safe to rerun: only rows carrying this script's category labels are replaced,
-- and the transaction aborts unless exactly 50 rows per topic (1250) exist after insert.
BEGIN;

CREATE TEMP TABLE _peds_sources (
  source_key text PRIMARY KEY,
  source_path text NOT NULL UNIQUE,
  category text NOT NULL UNIQUE
) ON COMMIT DROP;

INSERT INTO _peds_sources (source_key, source_path, category) VALUES
