  ('rop', 'Notes/Pediatrics/Retinopathy-of-Prematurity.html', 'Pediatrics NCLEX seed v1 - retinopathy of prematurity'),
  ('strabismus', 'Notes/Pediatrics/Strabismus.html', 'Pediatrics NCLEX seed v1 - strabismus'),
  ('development', 'Notes/Pediatrics/Pediatric-Developmental-Stages.html', 'Pediatrics NCLEX seed v1 - pediatric developmental stages'),
  ('rickets', 'Notes/Pediatrics/Rickets.html', 'Pediatrics NCLEX seed v1 - rickets'),
  ('ortho', 'Notes/Pediatrics/Pediatric-Ortho.html', 'Pediatrics NCLEX seed v1 - pediatric ortho'),
  ('omphalocele', 'Notes/Pediatrics/Omphalocele.html', 'Pediatrics NCLEX seed v1 - omphalocele'),
  ('meds', 'Notes/Pediatrics/Pediatric-Medication-Administration.html', 'Pediatrics NCLEX seed v1 - pediatric medication administration'),
  ('newborn', 'Notes/Pediatrics/Care-of-the-Newborn.html', 'Pediatrics NCLEX seed v1 - care of the newborn'),
  ('respiratory', 'Notes/Pediatrics/Pediatric-Respiratory-Disorders.html', 'Pediatrics NCLEX seed v1 - pediatric respiratory disorders'),
  ('cardio', 'Notes/Pediatrics/Pediatric-Cardiovascular-Nursing.html', 'Pediatrics NCLEX seed v1 - pediatric cardiovascular nursing'),
  ('neuro_disorders', 'Notes/Pediatrics/Pediatric-Neuro-Psych-Disorders.html', 'Pediatrics NCLEX seed v1 - pediatric neuro psych disorders'),
  ('diabetes', 'Notes/Pediatrics/Pediatric-Diabetes.html', 'Pediatrics NCLEX seed v1 - pediatric diabetes'),
