  ('renal', 'Notes/Pediatrics/Pediatric-Renal-GU.html', 'Pediatrics NCLEX seed v1 - pediatric renal gu'),
  ('msk', 'Notes/Pediatrics/Pediatric-Musculoskeletal.html', 'Pediatrics NCLEX seed v1 - pediatric musculoskeletal'),
  ('integumentary', 'Notes/Pediatrics/Pediatric-Integumentary.html', 'Pediatrics NCLEX seed v1 - pediatric integumentary'),
