CREATE TEMP TABLE _peds_seed_map (
  source_key text PRIMARY KEY,
  source_path text NOT NULL,
  category text NOT NULL,
  note_id uuid NOT NULL,
  note_title text NOT NULL,
  topic_id uuid NOT NULL,
  topic_aliases text[] NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE _peds_seed_config (test_id bigint NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  v_subject_id uuid;
  v_subject_count integer;
  v_note_count integer;
  v_topic_count integer;
  v_note_id uuid;
  v_note_title text;
  v_topic_id uuid;
  v_aliases text[];
  v_test_id bigint;
  v_errors text[] := ARRAY[]::text[];
  r record;
BEGIN
  SELECT count(*)
    INTO v_subject_count
    FROM test_subjects
   WHERE lower(btrim(name)) = 'pediatrics'
     AND is_active = true;
  IF v_subject_count <> 1 THEN
    v_errors := array_append(v_errors,
      format('Expected exactly one active test_subjects row named "Pediatrics"; found %s.', v_subject_count));
  ELSE
    SELECT id INTO v_subject_id
      FROM test_subjects
     WHERE lower(btrim(name)) = 'pediatrics'
       AND is_active = true;
  END IF;

  SELECT id INTO v_test_id
    FROM tests
   WHERE is_active = true
   ORDER BY id
   LIMIT 1;
  IF v_test_id IS NULL THEN
    v_errors := array_append(v_errors, 'No active tests row is available for test_questions.test_id.');
  END IF;

  FOR r IN SELECT source_key, source_path, category FROM _peds_sources ORDER BY source_key LOOP
    SELECT count(*)
      INTO v_note_count
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_note_count = 0 THEN
      v_errors := array_append(v_errors,
        format('Missing active note_catalog mapping for %s.', r.source_path));
      CONTINUE;
    ELSIF v_note_count > 1 THEN
      v_errors := array_append(v_errors,
        format('Ambiguous active note_catalog mapping for %s (%s rows).', r.source_path, v_note_count));
      CONTINUE;
    END IF;

    SELECT note_id, title
      INTO v_note_id, v_note_title
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_subject_count <> 1 THEN
      v_errors := array_append(v_errors,
        format('Cannot resolve test_topics aliases for %s because the active Pediatrics subject mapping is not unique.',
               r.source_path));
      CONTINUE;
    END IF;

    SELECT count(*)
      INTO v_topic_count
      FROM test_topics
     WHERE subject_id = v_subject_id
       AND note_id = v_note_id
       AND (status = 'published' OR status IS NULL);

    IF v_topic_count = 0 THEN
      v_errors := array_append(v_errors,
        format('No published test_topics row in Pediatrics points to note %s (%s).',
               v_note_title, r.source_path));
      CONTINUE;
    END IF;

    -- Sibling topics are expected aliases in test.html's note-level merged row.
    -- Insert all 50 for this source under one deterministic sibling topic_id.
    SELECT t.id
      INTO v_topic_id
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL)
     ORDER BY t.display_order NULLS LAST, t.created_at, t.name, t.id
     LIMIT 1;

    -- Collect the actual underlying aliases for the mapping check/report context.
    SELECT array_agg(t.name ORDER BY t.display_order NULLS LAST, t.name, t.id)
      INTO v_aliases
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL);

    INSERT INTO _peds_seed_map
      (source_key, source_path, category, note_id, note_title, topic_id, topic_aliases)
    VALUES
      (r.source_key, r.source_path, r.category, v_note_id, v_note_title, v_topic_id, v_aliases);
  END LOOP;

  IF cardinality(v_errors) > 0 THEN
    RAISE EXCEPTION E'Pediatrics seed mapping validation failed before any deletion/insertion:\n - %',
      array_to_string(v_errors, E'\n - ');
  END IF;

  IF (SELECT count(*) FROM _peds_seed_map) <> 25 THEN
    RAISE EXCEPTION 'Internal mapping check failed: expected 25 note mappings, found %.',
      (SELECT count(*) FROM _peds_seed_map);
  END IF;

  INSERT INTO _peds_seed_config (test_id) VALUES (v_test_id);
END $$;

-- Only rows from this script's unique category names are replaced.
DELETE FROM test_questions q
 USING _peds_seed_map m
 WHERE q.category = m.category;

INSERT INTO test_questions
  (test_id, topic_id, question, question_stem, options, correct_answer, rationale,
   category, is_multiple_choice, display_order, points, is_active)
SELECT c.test_id, m.topic_id, v.stem, v.stem, v.options, v.correct_answer, v.rationale,
       m.category, v.is_multi, v.display_order, 1, true
  FROM (VALUES
  ('kawasaki', 1, 'A 2-year-old boy has had a high fever unresponsive to medications for 3 days. He has bilateral conjunctivitis with no pus, a polymorphous rash, red cracked lips, and a 2-cm cervical lymph node. The parent asks whether this is Kawasaki disease. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "The criteria are met because 4 of the 5 findings are present"}, {"id": "b", "text": "A child must have fever ≥ 5 days PLUS 4 of the 5 criteria"}, {"id": "c", "text": "The conjunctivitis would need pus present to count as a criterion"}, {"id": "d", "text": "Swollen hands and feet must be present before it can be confirmed"}]'::jsonb, '["b"]', 'The criteria require fever ≥ 5 days plus 4 of the 5 findings; this child has 4 findings but only 3 days of fever. The conjunctivitis of Kawasaki disease is non-purulent, and hands/feet changes are only one of the five criteria, not a requirement.', false),
  ('kawasaki', 2, 'A 20-month-old boy of Asian descent is admitted in early spring with 6 days of high fever unresponsive to medications, a strawberry tongue, non-purulent conjunctivitis, swollen red palms and soles, and a polymorphous rash. Which prescription should the nurse anticipate implementing FIRST?', '[{"id": "a", "text": "Obtain an echocardiogram and wait for the result to treat"}, {"id": "b", "text": "Begin high-dose aspirin alone and reassess in 48 hours"}, {"id": "c", "text": "Give acetaminophen and recheck the temperature in 24 hours"}, {"id": "d", "text": "Start IVIG and monitor for an allergic reaction"}]'::jsonb, '["d"]', 'Fever ≥ 5 days plus 4 of the 5 criteria indicates Kawasaki disease, and the first action is to start IVIG and monitor for allergic reaction; IVIG must be given within 10 days of fever onset, so treatment is not held for an echocardiogram. Aspirin is given with IVIG rather than alone, and the fever is typically unresponsive to medications.', false),
  ('kawasaki', 3, 'A 3-year-old with Kawasaki disease has had a high fever for 7 days and is in the second day of hospitalization. Which findings would the nurse expect during the current phase of this child''s illness? Select all that apply.', '[{"id": "a", "text": "Irritability"}, {"id": "b", "text": "Skin peeling (desquamation) of the hands"}, {"id": "c", "text": "Swollen hands/feet"}, {"id": "d", "text": "Joint pain (arthralgia)"}, {"id": "e", "text": "Red eyes, mouth, lips"}]'::jsonb, '["a", "c", "e"]', 'Day 7 falls in the acute phase (1–2 weeks), which includes irritability (a), swollen hands/feet (c), and red eyes, mouth, lips (e). Skin peeling (b) and joint pain (d) are findings of the subacute phase (2–4 weeks), not the acute phase.', true),
  ('kawasaki', 4, 'A 4-year-old was transferred from a rural clinic and is diagnosed with Kawasaki disease. The fever began 9 days ago. The parent asks the nurse to postpone the IVIG infusion for 3 days until another family member can arrive. Which response by the nurse is BEST?', '[{"id": "a", "text": "IVIG must be given within 10 days of fever onset"}, {"id": "b", "text": "IVIG works equally well at any point in the illness"}, {"id": "c", "text": "High-dose aspirin will protect the heart until then"}, {"id": "d", "text": "IVIG can wait until the fever goes away on its own"}]'::jsonb, '["a"]', 'IVIG must be given within 10 days of fever onset; a 3-day delay would move the infusion to day 12. Aspirin is part of treatment but does not replace the time-sensitive IVIG, and the fever in Kawasaki disease is unresponsive to medications rather than self-limited.', false),
  ('kawasaki', 5, 'The nurse reviews discharge teaching with the parent of a 3-year-old who received IVIG for Kawasaki disease 2 days ago and has been afebrile for 24 hours. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"We will keep the follow-up echocardiogram appointments.\""}, {"id": "b", "text": "\"I will watch for bleeding and stomach upset from the aspirin.\""}, {"id": "c", "text": "\"The aspirin therapy ends when the fever subsides.\""}, {"id": "d", "text": "\"We need to delay the MMR and varicella vaccines for now.\""}]'::jsonb, '["c"]', 'Aspirin therapy continues even after the fever subsides, so believing it ends when the child is afebrile is incorrect. Echocardiogram follow-up, watching for bleeding and GI upset, and delaying live vaccines are all correct discharge teaching.', false),
  ('kawasaki', 6, 'A 22-month-old with Kawasaki disease is beginning an IVIG infusion on day 6 of fever. High-dose aspirin is also prescribed. Which actions by the nurse are appropriate at this time? Select all that apply.', '[{"id": "a", "text": "Give the MMR vaccine that is due during this admission"}, {"id": "b", "text": "Watch for allergy or reaction during the infusion"}, {"id": "c", "text": "Give acetaminophen in place of the high-dose aspirin"}, {"id": "d", "text": "Maintain strict I&O to monitor cardiac status"}, {"id": "e", "text": "Delay the infusion until the fever reaches day 10"}]'::jsonb, '["b", "d"]', 'During IVIG the nurse watches for allergy or reaction (b) and keeps strict I&O for cardiac status (d). The MMR vaccine (a) is delayed because IVIG may interfere with live vaccines. High-dose aspirin is an anti-inflammatory and antiplatelet exception to the usual rule, so it is not replaced (c). IVIG must be given within 10 days of fever onset, so waiting until day 10 (e) risks missing the window.', true),
  ('kawasaki', 7, 'A 15-month-old is seen for a well-child visit. The child received IVIG for Kawasaki disease 4 months ago and is now due for the MMR and varicella vaccines. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Give both vaccines today because the child is now afebrile"}, {"id": "b", "text": "Delay the MMR/Varicella because IVIG may interfere"}, {"id": "c", "text": "Give the MMR today and delay only the varicella vaccine"}, {"id": "d", "text": "Give both vaccines once the echocardiogram is normal"}]'::jsonb, '["b"]', 'IVIG may interfere with live vaccines, so MMR and varicella are delayed for 11 months; only 4 months have passed. Being afebrile or having a normal echocardiogram does not change the 11-month delay, and both live vaccines are delayed, not just one.', false),
  ('kawasaki', 8, 'The parent of a 3-year-old taking high-dose aspirin after Kawasaki disease calls the clinic. The child''s older sibling was just diagnosed with influenza, and the 3-year-old now has a cough and runny nose. Which instruction by the nurse is the PRIORITY?', '[{"id": "a", "text": "Stop the aspirin on your own and restart it next week"}, {"id": "b", "text": "Give an extra aspirin dose to treat the new fever"}, {"id": "c", "text": "Keep the child home and continue routine care only"}, {"id": "d", "text": "Have the child seen for possible Reye''s syndrome"}]'::jsonb, '["d"]', 'A child on aspirin who develops a viral illness must be watched for Reye''s syndrome, so the provider needs to evaluate the child. The parent should not change the aspirin on their own because therapy continues even after fever subsides, and extra doses add to aspirin side effects such as bleeding.', false),
  ('kawasaki', 9, 'A 3-year-old has had a high fever unresponsive to medications for 6 days. The nurse is evaluating the child for the diagnostic criteria of an acute systemic vasculitis. Which additional findings count toward these criteria? Select all that apply.', '[{"id": "a", "text": "Conjunctivitis with thick yellow pus"}, {"id": "b", "text": "Cervical lymph node swelling of 2 cm"}, {"id": "c", "text": "Red, bumpy tongue; red cracked lips"}, {"id": "d", "text": "Cervical lymph node swelling of 1 cm"}, {"id": "e", "text": "Swelling, redness of palms/soles"}]'::jsonb, '["b", "c", "e"]', 'Adenopathy counts when a cervical lymph node is swollen >1.5 cm, so 2 cm qualifies (b) and 1 cm does not (d). A red, bumpy tongue with red cracked lips is the strawberry tongue criterion (c), and swelling and redness of palms/soles is the hands/feet criterion (e). The conjunctivitis criterion is non-purulent, so pus (a) does not fit.', true),
  ('kawasaki', 10, 'A 4-year-old is receiving high-dose aspirin during the third week after the onset of Kawasaki disease. Which finding reported by the parent requires the nurse''s IMMEDIATE follow-up?', '[{"id": "a", "text": "Peeling skin on the fingertips and toes"}, {"id": "b", "text": "Mild aching in the knees after playing"}, {"id": "c", "text": "New bleeding from the mouth and nose"}, {"id": "d", "text": "Irritability that improves with comfort care"}]'::jsonb, '["c"]', 'Bleeding is a side effect of aspirin that the nurse must monitor for, so new bleeding from the mouth and nose needs follow-up. Peeling skin and joint pain are expected findings in the subacute phase (2–4 weeks), and irritability is managed with comfort care.', false),
  ('kawasaki', 11, 'The parent of a 2-year-old just diagnosed with Kawasaki disease sees high-dose aspirin on the medication record and says, "I was told children should not take aspirin." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Kawasaki is an exception; aspirin is anti-inflammatory and antiplatelet.\""}, {"id": "b", "text": "\"You are right; I will ask the provider to change it to acetaminophen today.\""}, {"id": "c", "text": "\"Aspirin is safe in children as long as the fever stays above the normal range.\""}, {"id": "d", "text": "\"Aspirin is given until the IVIG infusion has been completely finished.\""}]'::jsonb, '["a"]', 'High-dose aspirin is an anti-inflammatory and antiplatelet drug and is an exception to the no-aspirin-in-kids rule in Kawasaki disease. Therapy continues even after the fever subsides, so it is not limited to the febrile period or to the IVIG infusion.', false),
  ('kawasaki', 12, 'The nurse evaluates discharge teaching with the parents of a 4-year-old who was treated with IVIG and high-dose aspirin for Kawasaki disease. Which statements by the parents indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"We will continue aspirin after discharge.\""}, {"id": "b", "text": "\"We will delay the MMR and varicella shots.\""}, {"id": "c", "text": "\"We can stop aspirin once the fever is gone.\""}, {"id": "d", "text": "\"We will watch for chest pain, vomiting, or restlessness.\""}, {"id": "e", "text": "\"We will monitor for coronary aneurysms with an echo.\""}]'::jsonb, '["a", "b", "d", "e"]', 'Discharge teaching includes continuing aspirin (a), delaying live vaccines such as MMR and varicella (b), and monitoring for cardiac issues, including MI signs of chest pain, vomiting, and restlessness (d) and follow-up echocardiograms to check for coronary aneurysms (e). Aspirin therapy continues even after fever subsides, so (c) is incorrect.', true),
  ('kawasaki', 13, 'The nurse receives report on four children being treated for Kawasaki disease. Which child should the nurse assess FIRST?', '[{"id": "a", "text": "A 3-year-old on day 16 whose fingertips are peeling and raw"}, {"id": "b", "text": "A 2-year-old on day 18 whose platelets are higher than on admission"}, {"id": "c", "text": "A 1-year-old on day 5 with a high fever despite acetaminophen"}, {"id": "d", "text": "A 4-year-old on day 20 who has vomited twice and is restless"}]'::jsonb, '["d"]', 'Vomiting and restlessness are MI signs, which are unusual in children and signal a coronary complication after Kawasaki disease. Peeling skin and thrombocytosis are expected in the subacute phase, and a high fever unresponsive to medications is expected in the acute phase.', false),
  ('kawasaki', 14, 'A 3-year-old has had a high fever unresponsive to medications for 6 days. Findings include non-purulent conjunctivitis, a strawberry tongue, a polymorphous rash, a single cervical lymph node measuring 1.2 cm, and normal-appearing hands and feet. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Four of the 5 criteria are present, so the criteria are met"}, {"id": "b", "text": "Only 3 of the 5 criteria are present; the node is not >1.5 cm"}, {"id": "c", "text": "The criteria are not met because the fever has not lasted 10 days"}, {"id": "d", "text": "The criteria are met because any palpable cervical node counts"}]'::jsonb, '["b"]', 'Adenopathy counts only when the cervical lymph node is >1.5 cm, so this child has 3 of 5 criteria (conjunctivitis, strawberry tongue, rash) and does not meet the 4-of-5 requirement. The fever requirement is ≥ 5 days, which has been met; 10 days is the IVIG time limit.', false),
  ('kawasaki', 15, 'A 2-year-old is seen at a clinic 3 weeks after the onset of Kawasaki disease. The child was treated with IVIG and is taking aspirin. Which findings would the nurse interpret as expected during this phase? Select all that apply.', '[{"id": "a", "text": "Skin peeling, especially of the hands/feet"}, {"id": "b", "text": "High fever that is unresponsive to medications"}, {"id": "c", "text": "Joint pain (arthralgia) when walking"}, {"id": "d", "text": "Thrombocytosis (increased platelet count)"}, {"id": "e", "text": "Inflammation markers that have returned to normal"}]'::jsonb, '["a", "c", "d"]', 'Three weeks after onset is the subacute phase (2–4 weeks), which includes skin peeling of the hands/feet (a), joint pain (c), and thrombocytosis (d). High fever unresponsive to medications (b) belongs to the acute phase, and normal inflammation markers (e) occur in the convalescent phase.', true),
  ('kawasaki', 16, 'A 3-year-old with Kawasaki disease started an IVIG infusion 10 minutes ago. The child''s parent is at the bedside, and an echocardiogram is scheduled for later today. Which nursing assessment is the PRIORITY at this time?', '[{"id": "a", "text": "Watching for an allergic reaction to the IVIG"}, {"id": "b", "text": "Checking the hands and feet for skin peeling"}, {"id": "c", "text": "Asking the parent about the child''s vaccine record"}, {"id": "d", "text": "Measuring the size of the cervical lymph nodes"}]'::jsonb, '["a"]', 'Starting IVIG is the first action, and the nurse must monitor for an allergic reaction during the infusion. Peeling is a later subacute finding, and lymph node size and vaccine history do not take priority over infusion safety.', false),
  ('kawasaki', 17, 'On day 15 after the onset of fever, the parent of a 2-year-old treated for Kawasaki disease reports that the skin on the child''s fingers and toes is peeling and asks if the disease is getting worse. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Peeling means the IVIG did not work and must be given again.\""}, {"id": "b", "text": "\"Peeling means the illness is over and no more follow-up is needed.\""}, {"id": "c", "text": "\"Peeling is part of this phase, as is risk for coronary aneurysms.\""}, {"id": "d", "text": "\"Peeling is a sign of an allergic reaction to the high-dose aspirin.\""}]'::jsonb, '["c"]', 'Day 15 is in the subacute phase (2–4 weeks), when skin peeling of the hands/feet is expected and the risk for coronary aneurysms is present. Peeling is not a sign of treatment failure, and symptoms resolve gradually only later in the convalescent phase.', false),
  ('kawasaki', 18, 'Before discharge, the nurse teaches the parents of a 3-year-old recovering from Kawasaki disease about MI signs, which are unusual in children. Which signs should the parents be taught to report IMMEDIATELY? Select all that apply.', '[{"id": "a", "text": "Peeling skin of fingertips"}, {"id": "b", "text": "Chest pain"}, {"id": "c", "text": "Vomiting"}, {"id": "d", "text": "Restlessness"}, {"id": "e", "text": "Mild joint pain"}]'::jsonb, '["b", "c", "d"]', 'MI signs to monitor for in Kawasaki disease are chest pain (b), vomiting (c), and restlessness (d). Peeling skin (a) and joint pain (e) are expected findings of the subacute phase rather than signs of MI.', true),
  ('kawasaki', 19, 'Six weeks after treatment for Kawasaki disease, a 4-year-old has follow-up labs. The nurse is evaluating whether the child has entered the convalescent phase. Which result BEST supports this?', '[{"id": "a", "text": "A platelet count that is higher than at the last visit"}, {"id": "b", "text": "ESR and CRP that have returned to normal"}, {"id": "c", "text": "A new 2-cm cervical lymph node"}, {"id": "d", "text": "A rising ESR with a persistent high fever"}]'::jsonb, '["b"]', 'In the convalescent phase, symptoms resolve gradually and inflammation markers return to normal; ESR and CRP are among the labs monitored. A rising platelet count (thrombocytosis) is a subacute finding, and fever with lymphadenopathy belongs to the acute phase.', false),
  ('kawasaki', 20, 'A 2-year-old on day 5 of a high fever has a red, bumpy tongue and red cracked lips and is refusing meals. The child has been diagnosed with Kawasaki disease. Which meal choice should the nurse offer FIRST?', '[{"id": "a", "text": "Warm oatmeal with warm cocoa"}, {"id": "b", "text": "Cool juice with crunchy toast"}, {"id": "c", "text": "Crunchy cereal with cool milk"}, {"id": "d", "text": "Soft foods with cool fluids"}]'::jsonb, '["d"]', 'For the red, bumpy tongue and red cracked lips of Kawasaki disease, the nursing priority is soft foods and cool fluids for the oral mucosa. Options that are warm or crunchy meet only half of this need and would irritate the inflamed mouth.', false),
  ('kawasaki', 21, 'Each child below has had a high fever unresponsive to medications for 5 days. Which children have characteristics of the group MOST commonly affected by Kawasaki disease? Select all that apply.', '[{"id": "a", "text": "A 15-month-old boy of Asian descent"}, {"id": "b", "text": "A 9-year-old girl during mid-summer"}, {"id": "c", "text": "A 20-month-old boy during winter or spring"}, {"id": "d", "text": "A 7-year-old girl during late summer"}, {"id": "e", "text": "A 12-year-old boy of Asian descent"}]'::jsonb, '["a", "c"]', 'Kawasaki disease is most common in children <5 years, with a peak age of 1–2 years, and is more common in boys, in children of Asian descent, and in winter or spring, so (a) and (c) fit. The 9-year-old (b), 7-year-old (d), and 12-year-old (e) are older than 5 years; (b) and (d) are also seen in summer.', true),
  ('kawasaki', 22, 'A UAP caring for a 3-year-old with Kawasaki disease asks why every diaper and drink must be recorded, since the child is not dehydrated. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"Strict I&O helps us monitor the child''s cardiac status.\""}, {"id": "b", "text": "\"Strict I&O shows whether the IVIG infusion has finished.\""}, {"id": "c", "text": "\"Strict I&O is needed only while the fever is above normal.\""}, {"id": "d", "text": "\"Strict I&O shows whether the aspirin dose can be stopped.\""}]'::jsonb, '["a"]', 'Strict I&O is a nursing priority in Kawasaki disease because it reflects cardiac status. It is not used to time the IVIG or decide when to stop aspirin, which continues after the fever subsides.', false),
  ('kawasaki', 23, 'The parent of a 2-year-old with Kawasaki disease asks why the child needs heart testing when the main problems are fever, rash, and red eyes. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "\"The rash spreads to the lining of the heart in most young children.\""}, {"id": "b", "text": "\"The high fever damages the heart valves if it lasts longer than 5 days.\""}, {"id": "c", "text": "\"The inflammation targets arteries, especially the coronary arteries.\""}, {"id": "d", "text": "\"Heart testing is routine for any young child with a fever and rash.\""}]'::jsonb, '["c"]', 'Kawasaki disease is a systemic vasculitis in which inflammation targets medium-sized arteries, especially coronary arteries, which can lead to coronary artery aneurysms. The heart testing is not because of the rash or valve damage from fever.', false),
  ('kawasaki', 24, 'A 2-year-old in the acute phase of Kawasaki disease has a high fever, is irritable and crying, and has red cracked lips and a strawberry tongue. Which interventions should the nurse include in the plan of care? Select all that apply.', '[{"id": "a", "text": "Offer crunchy crackers and pretzels"}, {"id": "b", "text": "Offer warm soup to soothe the mouth"}, {"id": "c", "text": "Comfort care for fever, irritability"}, {"id": "d", "text": "Soft foods, cool fluids for the mouth"}, {"id": "e", "text": "Delay IVIG until irritability settles"}]'::jsonb, '["c", "d"]', 'Nursing priorities include comfort care for fever and irritability (c) and soft foods with cool fluids for the oral mucosa (d). Crunchy (a) or warm (b) foods irritate the red, cracked oral mucosa, and IVIG is the first action and must be given within 10 days of fever onset, so it is not delayed for irritability (e).', true),
  ('kawasaki', 25, 'A 4-year-old treated for Kawasaki disease is afebrile, playful, and eating well on the day of discharge. The parent asks whether the follow-up echocardiogram can be skipped because the child looks healthy. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"It can be skipped once the platelet count is normal.\""}, {"id": "b", "text": "\"It checks for coronary aneurysms, so it should be kept.\""}, {"id": "c", "text": "\"It is needed only if the child develops a new rash.\""}, {"id": "d", "text": "\"It can be skipped because the IVIG prevents all heart effects.\""}]'::jsonb, '["b"]', 'The heart is monitored with an echocardiogram because coronary artery aneurysms are the key complication; monitoring for cardiac issues is part of discharge teaching. A normal appearance or platelet count does not rule out aneurysms.', false),
  ('kawasaki', 26, 'A 3-year-old has had a high fever for 6 days with findings that meet the criteria for Kawasaki disease. The parent wants to take the child home and "wait for the fever to break." Which response by the nurse is MOST important?', '[{"id": "a", "text": "\"The fever usually responds to medicine given at home.\""}, {"id": "b", "text": "\"Treatment can start anytime once the rash has faded.\""}, {"id": "c", "text": "\"Home care is fine if the child keeps drinking fluids.\""}, {"id": "d", "text": "\"Untreated, it can cause aneurysms or myocarditis.\""}]'::jsonb, '["d"]', 'Kawasaki disease is a pediatric emergency; if untreated it can cause aneurysms or myocarditis. The fever is high and unresponsive to medications, and IVIG must be given within 10 days of fever onset.', false),
  ('kawasaki', 27, 'A 3-year-old is receiving IVIG and high-dose aspirin for Kawasaki disease. Which results should the nurse track to monitor the course of the disease and its treatment? Select all that apply.', '[{"id": "a", "text": "ESR"}, {"id": "b", "text": "CRP"}, {"id": "c", "text": "Blood cultures to find the cause"}, {"id": "d", "text": "Platelets"}, {"id": "e", "text": "Echocardiogram"}]'::jsonb, '["a", "b", "d", "e"]', 'The labs monitored in Kawasaki disease are ESR (a), CRP (b), and platelets (d), along with an echocardiogram (e) to monitor the heart. Blood cultures (c) are not used to find the cause because Kawasaki disease is a vasculitis of unknown cause.', true),
  ('kawasaki', 28, 'The tearful parent of a 2-year-old newly diagnosed with Kawasaki disease asks, "What did I do to cause this? Did my child catch it from a bacterial infection?" Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"It is caused by a bacterial infection that antibiotics will treat.\""}, {"id": "b", "text": "\"It is caused by giving aspirin to a child with a viral illness.\""}, {"id": "c", "text": "\"The cause is unknown; immune activation causes the inflammation.\""}, {"id": "d", "text": "\"It is caused by a delay in receiving the MMR and varicella vaccines.\""}]'::jsonb, '["c"]', 'Kawasaki disease is an acute systemic vasculitis of unknown cause in which immune system activation leads to widespread inflammation. Aspirin with a viral illness is linked to Reye''s syndrome, not to Kawasaki disease.', false),
  ('kawasaki', 29, 'Three weeks after the onset of Kawasaki disease, the parent of a 4-year-old reports that the child complains that the knees hurt and is limping slightly. The child is afebrile. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Joint pain (arthralgia) is expected in the subacute phase"}, {"id": "b", "text": "Joint pain means the acute phase of the illness has started again"}, {"id": "c", "text": "Joint pain is a sign of a delayed allergic reaction to the IVIG"}, {"id": "d", "text": "Joint pain is a sign of Reye''s syndrome from aspirin"}]'::jsonb, '["a"]', 'Three weeks after onset is the subacute phase (2–4 weeks), which includes joint pain (arthralgia). The acute phase is characterized by high fever, and an allergic reaction is watched for during the IVIG infusion, not weeks later.', false),
  ('kawasaki', 30, 'The nurse is preparing discharge instructions for the parent of a 2-year-old who will go home on high-dose aspirin after Kawasaki disease. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Stop the aspirin once the fever is gone"}, {"id": "b", "text": "Report any bleeding or stomach upset"}, {"id": "c", "text": "Watch for Reye''s syndrome if a viral illness occurs"}, {"id": "d", "text": "Give the varicella vaccine at the next visit"}, {"id": "e", "text": "Continue aspirin even after the fever subsides"}]'::jsonb, '["b", "c", "e"]', 'Aspirin side effects to monitor include bleeding and GI upset (b), the child must be watched for Reye''s syndrome if a viral illness occurs (c), and therapy continues even after fever subsides (e), which is why (a) is wrong. Live vaccines such as varicella are delayed for 11 months after IVIG (d).', true),
  ('kawasaki', 31, 'A 3-year-old with Kawasaki disease has been afebrile for 3 days, and the platelet count is rising. A nursing student asks why high-dose aspirin is still being given. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"It is given to keep the fever from returning.\""}, {"id": "b", "text": "\"It is anti-inflammatory and antiplatelet.\""}, {"id": "c", "text": "\"It prevents an allergic reaction to the IVIG.\""}, {"id": "d", "text": "\"It allows the live vaccines to be given sooner.\""}]'::jsonb, '["b"]', 'High-dose aspirin is both an anti-inflammatory and an antiplatelet drug, and therapy continues even after the fever subsides. It is not given to prevent IVIG reactions or to change the live-vaccine delay caused by IVIG.', false),
  ('kawasaki', 32, 'On day 4 of a high fever, a 2-year-old with Kawasaki disease has swelling and redness of the palms and soles. The parent asks what will happen to the child''s hands and feet. Which finding should the nurse teach the parent to expect NEXT?', '[{"id": "a", "text": "Clubbing of the fingers and toes"}, {"id": "b", "text": "Blisters filled with pus on the palms"}, {"id": "c", "text": "Permanent swelling of the ankles"}, {"id": "d", "text": "Peeling skin of the hands and feet"}]'::jsonb, '["d"]', 'The hands/feet criterion progresses from swelling and redness of the palms/soles to peeling skin, which is expected in the subacute phase. The other changes are not described for Kawasaki disease.', false),
  ('kawasaki', 33, 'The parents of a 20-month-old with Kawasaki disease ask questions before the IVIG infusion begins on day 7 of fever. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "\"IVIG decreases inflammation.\""}, {"id": "b", "text": "\"It must be given within 10 days of fever onset.\""}, {"id": "c", "text": "\"IVIG replaces the need for aspirin.\""}, {"id": "d", "text": "\"IVIG may interfere with live vaccines.\""}, {"id": "e", "text": "\"It is given only after the fever is gone.\""}]'::jsonb, '["a", "b", "d"]', 'IVIG decreases inflammation (a), must be given within 10 days of fever onset (b), and may interfere with live vaccines, which are delayed for 11 months (d). Treatment includes both IVIG and high-dose aspirin, which is continued even after the fever subsides, so IVIG does not replace aspirin (c), and IVIG is not delayed until the fever resolves (e).', true),
  ('kawasaki', 34, 'A 3-year-old has a high fever for 5 days that is unresponsive to medications. The nurse is documenting the skin assessment to support the suspected acute systemic vasculitis. Which rash description is the MOST consistent with this child''s condition?', '[{"id": "a", "text": "Polymorphous rash of many shapes"}, {"id": "b", "text": "Rash limited to the palms only"}, {"id": "c", "text": "Rash of pus-filled blisters"}, {"id": "d", "text": "Rash that appears after the skin peels"}]'::jsonb, '["a"]', 'The rash criterion in Kawasaki disease is a polymorphous rash, meaning a rash of many shapes, and it appears in the acute phase. Peeling follows the acute phase, and the conjunctivitis and other findings are non-purulent.', false),
  ('kawasaki', 35, 'The nurse is reviewing the histories of four 2-year-olds with fever, rash, and red eyes. Which fever history is MOST consistent with Kawasaki disease?', '[{"id": "a", "text": "Fever for 2 days that returns to normal with acetaminophen"}, {"id": "b", "text": "Fever for 3 days that resolves after one dose of ibuprofen"}, {"id": "c", "text": "High fever for 6 days that is unresponsive to medications"}, {"id": "d", "text": "Low-grade fever for 4 days that responds to cool fluids"}]'::jsonb, '["c"]', 'The Burn criterion is a fever ≥ 5 days that is high and unresponsive to medications. Fevers lasting fewer than 5 days or responding to antipyretics do not fit this pattern.', false),
  ('kawasaki', 36, 'A 3-year-old with Kawasaki disease received IVIG yesterday and is taking high-dose aspirin. Which complications of the disease itself should the nurse monitor for? Select all that apply.', '[{"id": "a", "text": "Reye''s syndrome from IVIG"}, {"id": "b", "text": "Coronary artery aneurysms"}, {"id": "c", "text": "Myocarditis"}, {"id": "d", "text": "Pericardial effusion"}, {"id": "e", "text": "Thrombosis"}]'::jsonb, '["b", "c", "d", "e"]', 'The key complication is coronary artery aneurysms (b), and the nurse also watches for myocarditis (c), pericardial effusion (d), thrombosis (e), and shock. Reye''s syndrome (a) is a risk of aspirin when a viral illness occurs, not of IVIG.', true),
  ('kawasaki', 37, 'Five weeks after the onset of Kawasaki disease, the parent of a 3-year-old asks when the child will be back to normal. The child is afebrile, the peeling has stopped, and the platelet count is falling. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"All symptoms will be gone within 1 week of the IVIG.\""}, {"id": "b", "text": "\"Peeling and joint pain will now return for 2 more weeks.\""}, {"id": "c", "text": "\"The fever will return before the illness ends.\""}, {"id": "d", "text": "\"Symptoms resolve gradually over weeks to months.\""}]'::jsonb, '["d"]', 'After the subacute phase (2–4 weeks), the convalescent phase lasts weeks to months, as symptoms resolve gradually and inflammation markers return to normal. Fever belongs to the acute phase, and peeling and joint pain to the subacute phase.', false),
  ('kawasaki', 38, 'A 2-year-old has had a high fever unresponsive to medications for 6 days, a polymorphous rash, and a strawberry tongue. The nurse examines the child''s eyes. Which eye finding would the nurse expect if this child has Kawasaki disease?', '[{"id": "a", "text": "Bilateral red eyes with no pus"}, {"id": "b", "text": "Red eye on one side with thick drainage"}, {"id": "c", "text": "Both eyes red with yellow crusted pus"}, {"id": "d", "text": "Swollen eyelids with green discharge"}]'::jsonb, '["a"]', 'The conjunctivitis of Kawasaki disease is non-purulent, meaning red eyes with no pus. Any eye finding with pus or drainage does not fit this criterion.', false),
  ('kawasaki', 39, 'The nurse is reviewing teaching with the parents of a 3-year-old in the subacute phase of Kawasaki disease. Which statements by the parents indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "\"The peeling hands mean the illness is getting worse.\""}, {"id": "b", "text": "\"No one knows exactly what causes this illness.\""}, {"id": "c", "text": "\"The cause of this illness is a bacterial infection.\""}, {"id": "d", "text": "\"The main concern is the arteries of the heart.\""}, {"id": "e", "text": "\"There is a no aspirin in kids rule, so we will stop it.\""}]'::jsonb, '["a", "c", "e"]', 'Peeling of the hands is an expected subacute finding, not a sign of worsening (a). Kawasaki disease has an unknown cause, so blaming a bacterial infection (c) is incorrect, while (b) is correct. High-dose aspirin is an exception to the no-aspirin-in-kids rule and is continued, so stopping it (e) needs correction. The inflammation targets the coronary arteries, so (d) is correct.', true),
  ('kawasaki', 40, 'A 2-year-old is seen 14 days after the onset of Kawasaki disease. The child is afebrile, and the platelet count is higher than it was on admission. The parent is worried the child is getting sicker. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The rising platelets mean the acute phase is beginning again"}, {"id": "b", "text": "Thrombocytosis is expected in the subacute phase"}, {"id": "c", "text": "The rising platelets mean the IVIG must be repeated now"}, {"id": "d", "text": "Thrombocytosis shows the convalescent phase is complete"}]'::jsonb, '["b"]', 'Thrombocytosis (an increased platelet count) is a feature of the subacute phase (2–4 weeks), and day 14 falls in this phase. In the convalescent phase, inflammation markers return to normal rather than rise.', false),
  ('kawasaki', 41, 'A 2-year-old who received IVIG for Kawasaki disease 12 months ago is at a well-child visit. The MMR and varicella vaccines were postponed after the IVIG. The child is well, and the last echocardiogram was normal. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Postpone the vaccines for another 11 months"}, {"id": "b", "text": "Give the varicella vaccine only and postpone the MMR"}, {"id": "c", "text": "Give the MMR and varicella vaccines as prescribed"}, {"id": "d", "text": "Postpone the vaccines until aspirin is stopped forever"}]'::jsonb, '["c"]', 'IVIG may interfere with live vaccines, so MMR and varicella are delayed for 11 months; 12 months have now passed, so the postponed vaccines can be given. A second 11-month delay is not needed, and both vaccines fall under the same delay.', false),
  ('kawasaki', 42, 'The nurse reviews the findings of five toddlers evaluated in an emergency department. Which toddlers meet the diagnostic criteria for Kawasaki disease? Select all that apply.', '[{"id": "a", "text": "Fever 6 days; no-pus conjunctivitis, rash, strawberry tongue, red swollen palms"}, {"id": "b", "text": "Fever 4 days; no-pus conjunctivitis, rash, strawberry tongue, 2-cm cervical node"}, {"id": "c", "text": "Fever 7 days; rash, strawberry tongue, 1-cm cervical node, pus from both eyes"}, {"id": "d", "text": "Fever 5 days; rash, 2-cm cervical node, red cracked lips, peeling of the palms"}, {"id": "e", "text": "Fever 8 days; pus from both eyes, rash, red cracked lips, 1.4-cm cervical node"}]'::jsonb, '["a", "d"]', 'The criteria are fever ≥ 5 days plus 4 of 5 findings. Toddler (a) has 6 days of fever with conjunctivitis, rash, strawberry tongue, and hands/feet changes; toddler (d) has 5 days of fever with rash, adenopathy >1.5 cm, red cracked lips, and palm peeling. Toddler (b) has only 4 days of fever; (c) has only rash and strawberry tongue because the node is not >1.5 cm and the conjunctivitis is purulent; (e) has only rash and red cracked lips for the same reasons.', true),
  ('kawasaki', 43, 'A nurse is teaching the parents of a 2-year-old newly diagnosed with Kawasaki disease about how the illness usually progresses. Which sequence of findings should the nurse describe as MOST expected?', '[{"id": "a", "text": "Peeling and joint pain → high fever and rash → markers normalize"}, {"id": "b", "text": "Markers normalize → peeling and joint pain → high fever and rash"}, {"id": "c", "text": "High fever and rash → markers normalize → peeling and joint pain"}, {"id": "d", "text": "High fever and rash → peeling and joint pain → markers normalize"}]'::jsonb, '["d"]', 'The acute phase (1–2 weeks) brings high fever and rash, the subacute phase (2–4 weeks) brings peeling and joint pain, and in the convalescent phase inflammation markers return to normal. The other sequences place the phases out of order.', false),
  ('kawasaki', 44, 'During discharge teaching, the parent of a 4-year-old treated for Kawasaki disease says, "Children don''t have heart attacks, so I don''t need to worry about that." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"MI is unusual in kids; report chest pain, vomiting, restlessness.\""}, {"id": "b", "text": "\"That is correct; heart attacks happen in adults but not in children.\""}, {"id": "c", "text": "\"Heart attacks happen only while the fever is still high in this illness.\""}, {"id": "d", "text": "\"Report heart attack signs once the skin on the hands begins to peel.\""}]'::jsonb, '["a"]', 'MI signs are unusual in children, but after Kawasaki disease the parent must monitor for chest pain, vomiting, and restlessness because coronary aneurysms are the key complication. Peeling is an expected subacute finding, not an MI sign.', false),
  ('kawasaki', 45, 'The nurse is delegating care of a 3-year-old receiving high-dose aspirin for Kawasaki disease to a UAP. The child has red cracked lips. Which instructions should the nurse give the UAP? Select all that apply.', '[{"id": "a", "text": "Offer crunchy snacks to boost the appetite"}, {"id": "b", "text": "Keep strict I&O for cardiac status"}, {"id": "c", "text": "Stop recording intake once the fever breaks"}, {"id": "d", "text": "Offer hot drinks to soothe the sore mouth"}, {"id": "e", "text": "Report signs of bleeding or GI upset"}]'::jsonb, '["b", "e"]', 'Strict I&O is kept for cardiac status (b), and bleeding and GI upset are aspirin side effects that must be reported (e). Crunchy snacks (a) and hot drinks (d) irritate the oral mucosa, which needs soft foods and cool fluids, and I&O is not stopped just because the fever breaks (c).', true),
  ('kawasaki', 46, 'On day 18 after the onset of fever, a 3-year-old treated for Kawasaki disease is afebrile and playful. The parent asks to cancel the cardiology visit scheduled for next week. Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "\"The visit can be canceled since the fever is gone.\""}, {"id": "b", "text": "\"This phase carries a risk for coronary aneurysms.\""}, {"id": "c", "text": "\"The visit is needed only if the rash comes back.\""}, {"id": "d", "text": "\"The visit can be canceled once the peeling stops.\""}]'::jsonb, '["b"]', 'Day 18 is in the subacute phase (2–4 weeks), which carries a risk for coronary aneurysms, so heart monitoring with echocardiogram is still needed. An absent fever or rash does not remove this risk.', false),
  ('kawasaki', 47, 'The nurse on a pediatric unit is caring for four children with Kawasaki disease. Which child should the nurse see FIRST?', '[{"id": "a", "text": "A 3-year-old on day 16 whose platelet count has risen"}, {"id": "b", "text": "A 2-year-old on day 20 who has mild knee pain"}, {"id": "c", "text": "A 4-year-old who started IVIG 15 minutes ago"}, {"id": "d", "text": "A 1-year-old on day 5 with a fever despite acetaminophen"}]'::jsonb, '["c"]', 'The nurse must watch for allergy or reaction during the IVIG infusion, so the child who just started the infusion is assessed first. A rising platelet count and joint pain are expected subacute findings, and a fever unresponsive to medications is expected in the acute phase.', false),
  ('kawasaki', 48, 'The parent of a 2-year-old with Kawasaki disease asks why the child needs an IVIG infusion when no infection has been found. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"IVIG treats the bacteria that caused the rash.\""}, {"id": "b", "text": "\"IVIG prevents a reaction to the aspirin.\""}, {"id": "c", "text": "\"IVIG replaces the vaccines the child missed.\""}, {"id": "d", "text": "\"IVIG decreases the inflammation.\""}]'::jsonb, '["d"]', 'IVIG (intravenous immune globulin) decreases inflammation in Kawasaki disease, which has an unknown cause. It does not treat a bacterial cause or replace vaccines; in fact, it may interfere with live vaccines.', false),
  ('kawasaki', 49, 'A 1-year-old on day 5 of Kawasaki disease is febrile, crying, and pulling away from the parent, who asks if something new is wrong. Vital signs are unchanged from the morning. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Provide comfort care for the fever and irritability"}, {"id": "b", "text": "Prepare the parent for the child''s heart surgery today"}, {"id": "c", "text": "Delay the IVIG infusion until the child stops crying"}, {"id": "d", "text": "Hold the aspirin dose until the child is calm and quiet"}]'::jsonb, '["a"]', 'Irritability is an expected finding in the acute phase, and comfort care for fever and irritability is a nursing priority. IVIG is not delayed for irritability, and aspirin therapy is continued.', false),
  ('kawasaki', 50, 'A parent calls the clinic about a 3-year-old who has had a high fever unresponsive to medications for 5 days, with red eyes without pus, a rash, red cracked lips, and swollen red hands and feet. Which instruction by the nurse is the PRIORITY?', '[{"id": "a", "text": "\"Keep giving fever medicine and call if it lasts 10 days.\""}, {"id": "b", "text": "\"Bring your child in now; this can be a pediatric emergency.\""}, {"id": "c", "text": "\"Offer soft foods and cool fluids and call back tomorrow.\""}, {"id": "d", "text": "\"Watch for peeling of the hands before you bring your child in.\""}]'::jsonb, '["b"]', 'Fever ≥ 5 days plus 4 of 5 criteria suggests Kawasaki disease, which can lead to coronary artery aneurysms and is a pediatric emergency; IVIG must be given within 10 days of fever onset. Soft foods and cool fluids are comfort measures, not the priority, and waiting for peeling delays treatment.', false),
  ('amblyopia', 1, 'During a preschool vision screening, a 4-year-old shows poor vision in the right eye. The parent is surprised and says, "She has never once complained that she can''t see." Which response by the nurse is BEST?', '[{"id": "a", "text": "Since she has not complained, the loss is mild and can be rechecked at school entry."}, {"id": "b", "text": "Children may not complain, so poor vision in one eye is often discovered on screening."}, {"id": "c", "text": "Preschool screening is often inaccurate, so the test will be repeated at about age 6 to 8."}, {"id": "d", "text": "Glasses will bring the right eye to normal vision, so no other follow-up is needed."}]'::jsonb, '["b"]', 'Children with amblyopia may not complain, and poor vision in one eye is typically discovered on screening; early detection is critical because vision loss can become permanent. Waiting because there are no complaints is unsafe, and the eye may not reach normal acuity even with glasses.', false),
  ('amblyopia', 2, 'A school nurse is preparing an in-service for kindergarten teachers about amblyopia in 5-year-olds. Which classroom observations should the nurse teach the teachers to report? Select all that apply.', '[{"id": "a", "text": "Squinting or closing one eye to see the board"}, {"id": "b", "text": "Frequent eye rubbing or blinking in class"}, {"id": "c", "text": "Reads the board easily with either eye covered"}, {"id": "d", "text": "Tilting head to see books"}, {"id": "e", "text": "Poor performance in school despite effort"}]'::jsonb, '["a", "b", "d", "e"]', 'Squinting or closing one eye (a), frequent eye rubbing or blinking (b), tilting the head to see (d), and poor performance in school when vision is uncorrected (e) are listed signs of amblyopia, which children may not complain about. Reading easily with either eye covered (c) shows clear vision in each eye, the opposite of poor vision in one eye.', true),
  ('amblyopia', 3, 'A 4-year-old has high farsightedness in the left eye and normal vision in the right eye. The eyes are aligned on the cover-uncover test. The parent asks why the left eye is not seeing well when it "looks perfectly normal." Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "The brain ignores the left eye''s image because that eye is slightly misaligned."}, {"id": "b", "text": "The brain favors the eye with clearer vision and ignores the blurred image."}, {"id": "c", "text": "The brain gets no clear input because vision in the left eye is blocked."}, {"id": "d", "text": "The left eye will catch up on its own once the visual pathways mature."}]'::jsonb, '["b"]', 'Unequal refractive error, such as high farsightedness in one eye, causes refractive amblyopia: the brain favors the eye with clearer vision. The eyes are aligned, so the strabismic explanation (brain ignores the misaligned eye) does not fit, and nothing is blocking vision as in deprivation amblyopia.', false),
  ('amblyopia', 4, 'A 6-month-old infant has a drooping left eyelid that covers the pupil, and the pediatric ophthalmologist is concerned about amblyopia. Which intervention should the nurse anticipate as the PRIORITY to protect the infant''s vision?', '[{"id": "a", "text": "Patching the left eye several hours a day so the eye can rest"}, {"id": "b", "text": "Eye exercises as the main therapy until the child is older"}, {"id": "c", "text": "Correcting the ptosis so the brain gets clear input from that eye"}, {"id": "d", "text": "Waiting to start any treatment until routine vision screening at age 3"}]'::jsonb, '["c"]', 'Ptosis blocks vision (deprivation amblyopia), so the brain doesn''t get clear input from that eye; treating the underlying cause, such as correcting ptosis (drooping eyelid), is the priority. Patching the affected eye would further deprive it, and vision therapy is only an optional adjunct.', false),
  ('amblyopia', 5, 'A 3-year-old is referred to a pediatric ophthalmologist after failing a vision screening. The parent asks what each test will show. Which explanations by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "The cover-uncover test measures how farsighted each eye is."}, {"id": "b", "text": "The visual acuity test measures clarity in each eye."}, {"id": "c", "text": "The cover-uncover test detects eye misalignment."}, {"id": "d", "text": "The autorefractor detects whether the eyes are misaligned."}, {"id": "e", "text": "Retinoscopy checks for refractive errors."}]'::jsonb, '["b", "c", "e"]', 'The visual acuity test measures clarity in each eye (b), the cover-uncover test detects eye misalignment (c), and retinoscopy or an autorefractor checks refractive errors (e). The cover-uncover test does not measure farsightedness (a), and the autorefractor checks refractive errors rather than misalignment (d).', true),
  ('amblyopia', 6, 'The parent of a 5-year-old newly diagnosed with amblyopia says, "We''d rather wait until she''s 9 and old enough to understand why she has to wear a patch." Which response by the nurse is BEST?', '[{"id": "a", "text": "Waiting is reasonable because treatment works about equally well at any age during childhood."}, {"id": "b", "text": "Treatment is most effective before age 6–8, while the visual pathways are still developing."}, {"id": "c", "text": "At age 9 she can start glasses, which will fully correct the vision in her weaker eye."}, {"id": "d", "text": "Starting at 9 is acceptable as long as the patch is then worn all day, every single day."}]'::jsonb, '["b"]', 'Amblyopia treatment is most effective before age 6–8, when visual pathways are still developing; delaying to age 9 risks permanent vision loss. Glasses alone do not restore acuity, because the eye fails to achieve normal acuity even with prescription lenses.', false),
  ('amblyopia', 7, 'A 5-year-old has amblyopia of the LEFT eye. The parent asks how to use the prescribed eye patch at home. Which instruction by the nurse is MOST appropriate?', '[{"id": "a", "text": "Cover the left eye for several hours a day so it can rest and recover."}, {"id": "b", "text": "Cover each eye on alternate days so that both of the eyes develop equally well."}, {"id": "c", "text": "Cover the right eye only while the child sleeps to prevent teasing."}, {"id": "d", "text": "Cover the right eye for several hours a day so the left eye works harder."}]'::jsonb, '["d"]', 'Patching (occlusion therapy) covers the stronger eye — here the right eye — for several hours a day so the weaker left eye works harder. Covering the weaker left eye would deprive it further, and patching during sleep does not make the weaker eye work.', false),
  ('amblyopia', 8, 'Atropine eye drops are prescribed for a 4-year-old whose RIGHT eye has amblyopia. The parent asks which eye gets the drops and why. Which response by the nurse is BEST?', '[{"id": "a", "text": "In the left eye, to temporarily blur the stronger eye''s vision."}, {"id": "b", "text": "In the right eye, to sharpen the focus of the weaker eye."}, {"id": "c", "text": "In both eyes, to relax the muscles that misalign them."}, {"id": "d", "text": "In the left eye, to permanently weaken it so the eyes match."}]'::jsonb, '["a"]', 'Atropine drops go in the stronger eye (the left eye here) and temporarily blur its vision to stimulate the weaker one. The drops are not placed in the weaker eye, and the blurring is temporary, not permanent.', false),
  ('amblyopia', 9, 'A nurse is reviewing the charts of four young children with amblyopia to classify each by type. Which pairings of amblyopia type and cause are correct? Select all that apply.', '[{"id": "a", "text": "Deprivation — high farsightedness in one eye"}, {"id": "b", "text": "Strabismic — misalignment of the eyes"}, {"id": "c", "text": "Refractive — congenital cataract in one eye"}, {"id": "d", "text": "Refractive — unequal refractive error"}, {"id": "e", "text": "Deprivation — ptosis blocking vision"}]'::jsonb, '["b", "d", "e"]', 'Strabismic amblyopia results from strabismus (misalignment of eyes) (b), refractive amblyopia from unequal refractive error (d), and deprivation amblyopia from blocked vision such as ptosis or congenital cataract (e). High farsightedness in one eye is refractive, not deprivation (a), and a congenital cataract causes deprivation, not refractive, amblyopia (c).', true),
  ('amblyopia', 10, 'A 2-month-old infant with a dense congenital cataract in one eye is at risk for amblyopia. The parent asks why the surgeon plans to remove the cataract instead of just patching the other eye. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "Patching can begin only at age 3, when vision screening normally starts."}, {"id": "b", "text": "Removal of the cataract treats the underlying cause so the brain gets clear input."}, {"id": "c", "text": "The cataract eye should be patched first so that the clear eye can rest."}, {"id": "d", "text": "The cataract will gradually clear by itself once the brain begins to favor that eye."}]'::jsonb, '["b"]', 'A congenital cataract blocks vision, so the brain doesn''t get clear input from that eye; treating the underlying cause, such as removal of the cataract, is necessary. Screening at age 3 is not a reason to delay, and patching the cataract eye would deprive it further.', false),
  ('amblyopia', 11, 'A 6-year-old who wears an eye patch for amblyopia now cries before school and says classmates laugh at the patch. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Advise the parent to stop patching until teasing has ended"}, {"id": "b", "text": "Tell the child the eye will stay lazy if the patch comes off"}, {"id": "c", "text": "Assess the psychological effects and social impact of the patch"}, {"id": "d", "text": "Recommend eye exercises alone in place of wearing the eye patch"}]'::jsonb, '["c"]', 'The nurse should monitor for psychological effects, including the social impact of eye patching, before planning interventions. Stopping patching threatens success because adherence is essential, and calling it a "lazy eye" in a shaming way should be avoided.', false),
  ('amblyopia', 12, 'A nurse is observing assistive personnel interact with a 4-year-old being treated for amblyopia with a patch. Which statement by the assistive personnel requires intervention by the nurse?', '[{"id": "a", "text": "Keeping your patch on helps your other eye get stronger."}, {"id": "b", "text": "You can choose a sticker each time the patch stays on."}, {"id": "c", "text": "The patch covers your strong eye for a few hours each day."}, {"id": "d", "text": "You wear that patch because of your lazy eye, lazybones!"}]'::jsonb, '["d"]', 'Staff should avoid calling it "lazy eye" in a way that shames the child. Offering stickers is an appropriate reward system, and covering the strong eye so the other eye works is accurate teaching.', false),
  ('amblyopia', 13, 'A nurse teaches the parents of a 4-year-old who is starting treatment for amblyopia. Which statements by the parents indicate understanding of the teaching? Select all that apply.', '[{"id": "a", "text": "We can stop the patch once her glasses arrive, since glasses fix it."}, {"id": "b", "text": "Treatment may continue for months to years, depending on severity."}, {"id": "c", "text": "Eye exercises can be used instead of the patch if she resists it."}, {"id": "d", "text": "Sticking with the patching schedule is essential for success."}, {"id": "e", "text": "A reward system may help her tolerate wearing the patch."}]'::jsonb, '["b", "d", "e"]', 'Treatment usually continues for months to years (b), adherence to patching is essential for success (d), and reward systems may help children tolerate patching (e). Glasses alone do not fix amblyopia because the eye fails to reach normal acuity even with prescription glasses (a), and vision therapy is only an optional adjunct, not a replacement (c).', true),
  ('amblyopia', 14, 'At a well-child visit, the parent of a 4-year-old reports that the child tilts the head and closes one eye when looking at books. The eyes appear straight. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Reassure the parent that this is a normal preschool habit"}, {"id": "b", "text": "Teach the parent to patch the eye the child keeps closing"}, {"id": "c", "text": "Plan to recheck the child''s vision at the next yearly visit"}, {"id": "d", "text": "Test visual acuity to measure clarity in each eye"}]'::jsonb, '["d"]', 'Squinting, closing one eye, or tilting the head to see are signs of amblyopia even when the eyes look straight, so the first step is a visual acuity test, which measures clarity in each eye. Patching before diagnosis is premature, and waiting a year delays early detection, which is critical.', false),
  ('amblyopia', 15, 'A 3-year-old''s parent says the child''s eyes "don''t seem to work together," especially when the child is tired. Which test should the nurse anticipate as MOST useful to detect eye misalignment?', '[{"id": "a", "text": "Retinoscopy"}, {"id": "b", "text": "Cover-uncover test"}, {"id": "c", "text": "Autorefractor reading"}, {"id": "d", "text": "Visual acuity test"}]'::jsonb, '["b"]', 'Eyes that do not appear to work together suggest misalignment, and the cover-uncover test detects eye misalignment. Retinoscopy and the autorefractor check refractive errors, and the visual acuity test measures clarity in each eye.', false),
  ('amblyopia', 16, 'A 5-year-old has poor vision in the left eye on screening, and the cover-uncover test shows no misalignment. Which test should the nurse anticipate NEXT to check for unequal refractive error?', '[{"id": "a", "text": "Retinoscopy or autorefractor"}, {"id": "b", "text": "A repeat cover-uncover test"}, {"id": "c", "text": "A trial of eye exercises first"}, {"id": "d", "text": "A one-week patching trial"}]'::jsonb, '["a"]', 'Retinoscopy or an autorefractor checks refractive errors, which is needed when unequal refractive error is suspected and the eyes are aligned. Repeating the cover-uncover test only re-checks misalignment, and patching or exercises are treatments, not diagnostic tests.', false),
  ('amblyopia', 17, 'The parent of a 4-year-old with amblyopia asks what could happen if the family stops treatment. Which outcomes should the nurse include in the response? Select all that apply.', '[{"id": "a", "text": "Visual disability later in life"}, {"id": "b", "text": "Weaker eye recovering by itself at age 8"}, {"id": "c", "text": "Permanent vision loss"}, {"id": "d", "text": "Gradual weakening of the stronger eye"}, {"id": "e", "text": "Poor depth perception"}]'::jsonb, '["a", "c", "e"]', 'Untreated amblyopia can lead to permanent vision loss (c), poor depth perception (e), and visual disability later in life (a). The weaker eye does not recover on its own (b) — the ignored eye fails to develop proper vision — and weakening of the stronger eye (d) is not a listed complication.', true),
  ('amblyopia', 18, 'A 2-year-old had a congenital cataract removed from the right eye in infancy. The parent asks when the child''s vision screening should begin. Which response by the nurse is BEST?', '[{"id": "a", "text": "At age 3, the same as other preschool-aged children"}, {"id": "b", "text": "At school entry, when the child is able to read an eye chart"}, {"id": "c", "text": "At age 6–8, once the visual pathways finish developing"}, {"id": "d", "text": "Now, earlier than age 3, because a risk factor is present"}]'::jsonb, '["d"]', 'Screening starts at age 3 or earlier if risk factors are present; a congenital cataract is a cause of deprivation amblyopia, so this child should be screened now. Waiting until age 3 or later ignores the risk factor and wastes the period when treatment is most effective.', false),
  ('amblyopia', 19, 'An 11-year-old whose amblyopia was never treated wants to join a baseball team. Which teaching point is MOST important for the nurse to discuss with the family?', '[{"id": "a", "text": "The weaker eye will regain vision now that he is older."}, {"id": "b", "text": "Impaired binocular vision increases the risk of injury."}, {"id": "c", "text": "Depth perception stays normal when one eye sees well."}, {"id": "d", "text": "The stronger eye will begin to fail from overuse."}]'::jsonb, '["b"]', 'Untreated amblyopia increases the risk of injury due to impaired binocular vision and causes poor depth perception, which matters for a ball sport. Vision loss from untreated amblyopia is permanent, so the weaker eye will not recover with age.', false),
  ('amblyopia', 20, 'A 4-year-old with refractive amblyopia received new glasses. A month later the parent says, "Now that she wears glasses, her weak eye should see normally, so we can skip the patch." Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes, once the glasses correct the refractive error, the patch is no longer needed."}, {"id": "b", "text": "The patch can stop, but the glasses should be worn all day and night."}, {"id": "c", "text": "Even with glasses the weaker eye may not reach normal acuity, so keep patching."}, {"id": "d", "text": "Patching is needed only if she starts to complain about her vision."}]'::jsonb, '["c"]', 'In amblyopia, one eye fails to achieve normal visual acuity even with prescription glasses or contact lenses, so patching must continue to force the brain to use the weaker eye. Children may not complain, so waiting for complaints is unsafe.', false),
  ('amblyopia', 21, 'A community health nurse is planning a vision program for a preschool. Which statements should the nurse include when teaching staff about amblyopia? Select all that apply.', '[{"id": "a", "text": "Early detection is critical because vision loss can become permanent."}, {"id": "b", "text": "Children reliably tell an adult when one eye is seeing poorly."}, {"id": "c", "text": "Screening starts at age 3, or earlier if risk factors are present."}, {"id": "d", "text": "Screening can wait until age 8, when the visual pathways finish."}, {"id": "e", "text": "It is the leading cause of vision impairment in children."}]'::jsonb, '["a", "c", "e"]', 'Early detection is critical because vision loss can become permanent (a), screening starts at age 3 or earlier if risk factors are present (c), and amblyopia is the leading cause of vision impairment in children (e). Children may not complain (b), and treatment is most effective before age 6–8, so waiting until 8 is unsafe (d).', true),
  ('amblyopia', 22, 'A school nurse reviews preschool vision screening results. Which child should the nurse refer for an exam by a pediatric ophthalmologist FIRST?', '[{"id": "a", "text": "A 4-year-old who wears glasses and has clear, equal vision in both eyes"}, {"id": "b", "text": "A 4-year-old with poor vision in one eye who tilts the head to see"}, {"id": "c", "text": "A 3-year-old whose eyes work together and who passed the screening"}, {"id": "d", "text": "A 5-year-old with poor vision in one eye who already wears a patch daily"}]'::jsonb, '["b"]', 'Poor vision in one eye discovered on screening, combined with tilting the head to see, suggests untreated amblyopia and warrants exam by a pediatric ophthalmologist. The child who already wears a patch is under treatment, and the others have equal vision or passed screening.', false),
  ('amblyopia', 23, 'A 5-year-old has completed 3 months of patching the stronger right eye for amblyopia of the left eye. Which finding BEST indicates that treatment is effective?', '[{"id": "a", "text": "Improved vision in the weaker eye on visual acuity test"}, {"id": "b", "text": "Improved vision in the stronger eye on visual acuity test"}, {"id": "c", "text": "The child no longer protests when the patch goes on"}, {"id": "d", "text": "The parent reports the child no longer complains"}]'::jsonb, '["a"]', 'The goal of treatment is to force the brain to use the weaker eye and improve its vision, so improved acuity in the weaker left eye shows effectiveness. Better tolerance of the patch reflects adherence, not improved vision, and children may not complain even when vision is poor.', false),
  ('amblyopia', 24, 'The parent of a 4-year-old with amblyopia reports that the child pulls off the prescribed eye patch after about 10 minutes each day. Which response by the nurse is BEST?', '[{"id": "a", "text": "Ten minutes is enough as long as the patch goes on every day."}, {"id": "b", "text": "Patch the weaker eye instead, since she may tolerate that better."}, {"id": "c", "text": "Stop the patch and use vision therapy exercises in its place."}, {"id": "d", "text": "Patching needs several hours a day; a reward system may help."}]'::jsonb, '["d"]', 'Patching covers the stronger eye for several hours a day, adherence is essential for success, and reward systems may help children tolerate patching. Ten minutes falls far short of several hours, and vision therapy is only an optional adjunct.', false),
  ('amblyopia', 25, 'The parent of a 3-year-old with amblyopia asks how the condition developed when the eye itself "looks fine." Which explanations by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "In early childhood, the brain learns to process visual information from both eyes."}, {"id": "b", "text": "The brain starts to favor the weaker eye so that it can catch up over time."}, {"id": "c", "text": "If one eye gives a blurred or misaligned image, the brain starts to ignore that eye."}, {"id": "d", "text": "Over time, the ignored eye fails to develop proper vision."}, {"id": "e", "text": "The brain favors the stronger eye when the images do not match."}]'::jsonb, '["a", "c", "d", "e"]', 'During early childhood the brain learns to process visual information from both eyes (a); if one eye provides a blurred or misaligned image, the brain starts to ignore that eye (c) and favors the stronger one (e); over time the ignored eye fails to develop proper vision (d). The brain favors the stronger eye, not the weaker one (b).', true),
  ('amblyopia', 26, 'Two weeks after atropine drops are started in the stronger left eye, the parent of a 5-year-old calls to report that vision in the child''s left eye is blurry. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The drops belong in the right eye, so they must have been placed into the wrong eye."}, {"id": "b", "text": "This is permanent damage, so the drops must be stopped right away."}, {"id": "c", "text": "The amblyopia has now spread from the right eye into the left eye."}, {"id": "d", "text": "This is expected; atropine blurs the strong eye so the brain uses the weaker eye."}]'::jsonb, '["d"]', 'Atropine drops temporarily blur vision in the strong eye so the brain uses the weaker eye, so blurring of the treated left eye is the intended effect. The blur is temporary, not permanent damage, and the drops belong in the stronger eye.', false),
  ('amblyopia', 27, 'The nurse reviews atropine drop therapy with the parent of a 4-year-old with amblyopia of the right eye. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "The drops go in his weaker right eye."}, {"id": "b", "text": "The drops go in his left eye, his stronger eye."}, {"id": "c", "text": "The blurring from the drops will be temporary."}, {"id": "d", "text": "The drops make his brain use his weaker right eye."}]'::jsonb, '["a"]', 'Atropine drops go in the stronger eye (the left eye here) to temporarily blur it and stimulate the weaker eye; placing them in the weaker right eye shows a need for further teaching. The other statements correctly describe the eye, the temporary blur, and the purpose.', false),
  ('amblyopia', 28, 'A 6-year-old who has never had a vision screening is struggling with schoolwork, and the teacher notes frequent eye rubbing and blinking. Which action by the school nurse is the PRIORITY?', '[{"id": "a", "text": "Refer the child for a learning evaluation before any eye testing"}, {"id": "b", "text": "Tell the parent that eye rubbing is a sign of being overtired"}, {"id": "c", "text": "Screen visual acuity in each eye and refer for an eye exam"}, {"id": "d", "text": "Move the child to the front row and recheck next school year"}]'::jsonb, '["c"]', 'Poor performance in school (if vision is uncorrected) and frequent eye rubbing or blinking are signs of amblyopia, and this child is still within the age when treatment is most effective, so vision screening and referral come first. Delaying until next year risks permanent vision loss.', false),
  ('amblyopia', 29, 'A nurse is reviewing a teaching sheet for parents of children with amblyopia. Which treatment descriptions on the sheet are accurate? Select all that apply.', '[{"id": "a", "text": "Vision therapy replaces patching as the main treatment."}, {"id": "b", "text": "Patching covers the weaker eye so that it can rest."}, {"id": "c", "text": "Corrective lenses correct the refractive error."}, {"id": "d", "text": "Treatment usually lasts only a few days to weeks."}, {"id": "e", "text": "Vision therapy eye exercises are an optional adjunct."}]'::jsonb, '["c", "e"]', 'Corrective lenses (glasses or contacts) correct refractive error (c), and vision therapy eye exercises are an optional adjunct (e). Vision therapy does not replace patching (a), patching covers the stronger eye (b), and treatment usually continues for months to years (d).', true),
  ('amblyopia', 30, 'The parent of a 3-year-old with amblyopia says, "The doctor said both eyes are healthy, so why can''t we wait a few years before treating it?" Which response by the nurse is BEST?', '[{"id": "a", "text": "Waiting is safe because the brain uses both of the eyes equally until about age 8."}, {"id": "b", "text": "The stronger eye will eventually push the weaker eye to catch up on its own."}, {"id": "c", "text": "Vision loss from amblyopia can be fully reversed at any age once the treatment starts."}, {"id": "d", "text": "Over time the ignored eye fails to develop vision, and the loss can become permanent."}]'::jsonb, '["d"]', 'The ignored eye fails to develop proper vision over time, leading to permanent vision loss if untreated, so early detection and treatment are critical. The brain favors the stronger eye rather than using both equally, and treatment is most effective before age 6–8, not at any age.', false),
  ('amblyopia', 31, 'A nurse is writing a care plan for a 4-year-old with strabismic amblyopia of the left eye who is starting occlusion therapy. Which expected outcome BEST reflects the goal of treatment?', '[{"id": "a", "text": "The brain uses the weaker eye, and its vision improves."}, {"id": "b", "text": "The child''s right eye vision improves with daily patching."}, {"id": "c", "text": "The child''s left eye rests until the visual pathways mature."}, {"id": "d", "text": "The child stops squinting, so further therapy can be stopped."}]'::jsonb, '["a"]', 'The goal of amblyopia treatment is to force the brain to use the weaker eye and improve its vision. Patching the right (stronger) eye is not meant to improve the right eye, and resting the weaker eye defeats the purpose.', false),
  ('amblyopia', 32, 'A 5-year-old being treated for amblyopia refuses to wear the eye patch and hides it before preschool. Which actions by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Suggest skipping the patch on preschool days"}, {"id": "b", "text": "Help the parent set up a reward system for patching"}, {"id": "c", "text": "Explain that a lazy eye comes from not trying hard"}, {"id": "d", "text": "Monitor for psychological effects of the eye patch"}, {"id": "e", "text": "Suggest patching the weaker eye during preschool"}]'::jsonb, '["b", "d"]', 'Reward systems may help children tolerate patching (b), and the nurse should monitor for psychological effects such as the social impact of eye patching (d). Skipping patching undermines adherence, which is essential (a); shaming the child about a "lazy eye" should be avoided (c); and the stronger eye, not the weaker eye, is patched (e).', true),
  ('amblyopia', 33, 'A 3-year-old''s left eye turns inward, and the parent asks how this eye turn could affect the child''s vision. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "The turned eye is farsighted, so the brain will favor it."}, {"id": "b", "text": "The turned eye''s lens is blocked, so light cannot reach it."}, {"id": "c", "text": "The brain may ignore the image from the misaligned eye."}, {"id": "d", "text": "The eye turn protects vision until it straightens with age."}]'::jsonb, '["c"]', 'In strabismic amblyopia, the brain ignores the image from the misaligned eye, and over time that eye fails to develop proper vision. Farsightedness and blocked vision describe the refractive and deprivation types, not an eye turn.', false),
  ('amblyopia', 34, 'A 5-year-old with untreated poor vision in one eye keeps missing when catching a ball and misjudges the bottom step on the stairs. The parent asks whether this could be related to the eyes. Which response by the nurse is BEST?', '[{"id": "a", "text": "No, this is a motor delay that is unrelated to vision."}, {"id": "b", "text": "Yes, difficulty with depth perception is a sign of amblyopia."}, {"id": "c", "text": "No, depth perception is normal when one eye sees well."}, {"id": "d", "text": "Yes, this means the stronger eye is also losing vision."}]'::jsonb, '["b"]', 'Difficulty with depth perception is a sign of amblyopia, and poor depth perception is a complication if it goes untreated. Having one eye that sees well does not preserve normal depth perception.', false),
  ('amblyopia', 35, 'A nurse performs a vision assessment on a 3-year-old at a well-child visit. Which findings should the nurse report to the health care provider as possible signs of amblyopia? Select all that apply.', '[{"id": "a", "text": "Poor vision in one eye on screening"}, {"id": "b", "text": "Eyes that move together on tracking"}, {"id": "c", "text": "Eyes that do not appear to work together"}, {"id": "d", "text": "No complaints about vision from the child"}, {"id": "e", "text": "A wandering eye noted by the parent"}]'::jsonb, '["a", "c", "e"]', 'Poor vision in one eye discovered on screening (a), eyes that do not appear to work together (c), and strabismus such as a wandering eye (e) are signs of amblyopia. Eyes that move together (b) are not a sign, and the absence of complaints (d) is not reassuring because children may not complain.', true),
  ('amblyopia', 36, 'The parent of a 10-month-old infant reports that the infant''s right eye has been wandering outward in photos for several weeks. Which action by the nurse is BEST?', '[{"id": "a", "text": "Arrange an exam by a pediatric ophthalmologist now"}, {"id": "b", "text": "Wait for routine vision screening at age 3"}, {"id": "c", "text": "Teach the parent to patch the right eye daily"}, {"id": "d", "text": "Recheck the eyes at the 18-month visit"}]'::jsonb, '["a"]', 'A wandering eye (strabismus) is a risk factor for amblyopia, and screening starts at age 3 or earlier if risk factors are present, so this infant needs an exam by a pediatric ophthalmologist now. Patching before diagnosis is inappropriate, and waiting delays early detection.', false),
  ('amblyopia', 37, 'A pediatric eye clinic nurse has four messages from parents requesting eye appointments. Which child''s referral should the nurse arrange FIRST?', '[{"id": "a", "text": "A 3-year-old who passed screening and is due for a routine checkup"}, {"id": "b", "text": "A 12-year-old with poor vision in one eye who wants contact lenses"}, {"id": "c", "text": "A 5-year-old with poor vision in one eye not yet seen by a pediatric ophthalmologist"}, {"id": "d", "text": "A 14-year-old with poor vision in one eye who wants a gym class excuse"}]'::jsonb, '["c"]', 'Amblyopia treatment is most effective before age 6–8, when visual pathways are still developing, so the 5-year-old with poor vision in one eye is the priority for referral. The older children are past the window when treatment has the best outcomes, and the 3-year-old passed screening.', false),
  ('amblyopia', 38, 'The parent of a 4-year-old asks how atropine drops can be used instead of a patch for amblyopia. Which statements by the nurse correctly describe what the two treatments have in common? Select all that apply.', '[{"id": "a", "text": "Both permanently reduce vision in the treated eye."}, {"id": "b", "text": "Both are applied to the weaker eye to help it focus."}, {"id": "c", "text": "Both are used on the stronger eye."}, {"id": "d", "text": "Both remove the need for corrective lenses."}, {"id": "e", "text": "Both force the brain to use the weaker eye."}]'::jsonb, '["c", "e"]', 'Patching covers the stronger eye and atropine drops go in the stronger eye (c), and both serve the goal of forcing the brain to use the weaker eye (e). Atropine blurs the strong eye only temporarily (a), neither is applied to the weaker eye (b), and corrective lenses are a separate treatment for refractive error (d).', true),
  ('amblyopia', 39, 'The parent of a 5-year-old with amblyopia found eye exercises online and asks whether they can be done instead of patching. Which response by the nurse is BEST?', '[{"id": "a", "text": "Eye exercises are an optional adjunct and do not replace patching."}, {"id": "b", "text": "Yes, eye exercises are the main treatment and can replace patching."}, {"id": "c", "text": "Eye exercises work only after the visual pathways finish developing."}, {"id": "d", "text": "Yes, as long as the exercises are done for several hours each day."}]'::jsonb, '["a"]', 'Vision therapy (eye exercises to improve coordination and focus) is an optional adjunct, while patching and atropine force the brain to use the weaker eye. Replacing patching with exercises undermines adherence, which is essential for success.', false),
  ('amblyopia', 40, 'A public health nurse has limited funds for an amblyopia vision screening program. Which group should the nurse make the PRIORITY for screening?', '[{"id": "a", "text": "Adolescents preparing to apply for a driver''s permit"}, {"id": "b", "text": "School-age children ages 10 to 12 in middle school"}, {"id": "c", "text": "Preschool-aged children starting at about age 3"}, {"id": "d", "text": "Adults with a history of childhood eye problems"}]'::jsonb, '["c"]', 'Nurses should screen vision in preschool-aged children, with screening starting at age 3, because treatment is most effective before age 6–8. Screening older children or adults misses the window when vision loss can still be prevented.', false),
  ('amblyopia', 41, 'After 6 weeks of patching, the vision in a 4-year-old''s weaker eye has improved. The parent says, "It''s working, so we''ll stop the patch this weekend." Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "Stopping now is fine because the improvement is permanent."}, {"id": "b", "text": "Treatment usually continues for months to years, so keep patching."}, {"id": "c", "text": "Switch the patch to the weaker eye now that it can see better."}, {"id": "d", "text": "Stop the patch now and restart it only if she starts to squint."}]'::jsonb, '["b"]', 'Treatment usually continues for months to years depending on severity and age, and adherence is essential for success. Stopping after 6 weeks risks loss of the gains, and the patch always goes on the stronger eye.', false),
  ('amblyopia', 42, 'A 4-year-old was prescribed glasses for poor vision in the left eye 4 months ago and has worn them daily. Vision in the left eye remains poorer than in the right eye even with the glasses. Which conclusion by the nurse is MOST accurate?', '[{"id": "a", "text": "The left eye has not achieved normal acuity with glasses, which fits amblyopia."}, {"id": "b", "text": "The glasses are working, and the left eye simply needs a bit more time to adjust."}, {"id": "c", "text": "The right eye is now the weaker eye and should be the focus of treatment."}, {"id": "d", "text": "The difference is expected and will resolve once the child reaches age 8."}]'::jsonb, '["a"]', 'Amblyopia is a vision development disorder in which one eye fails to achieve normal visual acuity even with prescription glasses or contact lenses. Waiting until age 8 is unsafe because treatment is most effective before age 6–8.', false),
  ('amblyopia', 43, 'A parent of a 3-year-old newly diagnosed with amblyopia says, "It''s just a lazy eye. It isn''t a real vision problem, so we''re in no hurry." Which response by the nurse is BEST?', '[{"id": "a", "text": "You''re right; a lazy eye is mostly cosmetic, so the follow-up can wait a few years."}, {"id": "b", "text": "It is a lazy eye, so the child must try harder to use that eye at home."}, {"id": "c", "text": "It is the leading cause of vision impairment in children, so early care matters."}, {"id": "d", "text": "It is a minor issue unless the eye also begins to turn inward or outward."}]'::jsonb, '["c"]', 'Amblyopia is the leading cause of vision impairment in children, and early detection is critical because vision loss can become permanent. Implying the child must try harder shames the child, which should be avoided.', false),
  ('amblyopia', 44, 'A 4-year-old has amblyopia of the RIGHT eye due to unequal refractive error. Which elements of the treatment plan should the nurse expect? Select all that apply.', '[{"id": "a", "text": "Glasses or contacts to correct the refractive error"}, {"id": "b", "text": "Patch over the left eye for several hours a day"}, {"id": "c", "text": "Atropine drops placed in the left eye"}, {"id": "d", "text": "Patch over the right eye for several hours a day"}, {"id": "e", "text": "Eye exercises as an optional adjunct"}]'::jsonb, '["a", "b", "c", "e"]', 'Treatment for refractive amblyopia of the right eye includes corrective lenses for refractive error (a), patching the stronger left eye (b), atropine drops in the stronger left eye (c), and vision therapy as an optional adjunct (e). Patching the weaker right eye (d) is incorrect because the stronger eye is covered.', true),
  ('amblyopia', 45, 'A clinic nurse reviews the records of several 2-year-olds. For which children should the nurse recommend vision screening now rather than waiting until age 3? Select all that apply.', '[{"id": "a", "text": "A child with no eye concerns and normal development"}, {"id": "b", "text": "A child with ptosis of the left eyelid since birth"}, {"id": "c", "text": "A child with crossed eyes noted by the parent"}, {"id": "d", "text": "A child with equal refractive error in both eyes"}, {"id": "e", "text": "A child who had a congenital cataract removed"}]'::jsonb, '["b", "c", "e"]', 'Screening starts at age 3 or earlier if risk factors are present; ptosis (b) and congenital cataract (e) block vision and cause deprivation amblyopia, and strabismus (c) causes strabismic amblyopia. A child without concerns (a) follows routine screening at age 3, and refractive amblyopia results from unequal, not equal, refractive error (d).', true),
  ('amblyopia', 46, 'A nurse is calling parents of preschoolers being treated for amblyopia. Which parent statements require follow-up by the nurse? Select all that apply.', '[{"id": "a", "text": "Patching is skipped when she doesn''t tolerate it."}, {"id": "b", "text": "We give her a sticker each day the patch stays on."}, {"id": "c", "text": "Calling it a lazy eye shames her into wearing it."}, {"id": "d", "text": "We put the atropine drops in her weaker eye."}, {"id": "e", "text": "The patch goes over her stronger eye for several hours."}]'::jsonb, '["a", "c", "d"]', 'Removing the patch whenever the child complains undermines adherence, which is essential for success (a); teasing about a "lazy eye" shames the child (c); and atropine drops belong in the stronger eye (d). A sticker reward system (b) and patching the stronger eye for several hours (e) are correct.', true),
  ('amblyopia', 47, 'A 3-year-old is diagnosed with deprivation amblyopia of the left eye. Which findings in the child''s history could explain this type of amblyopia? Select all that apply.', '[{"id": "a", "text": "Strabismus with the left eye turning inward"}, {"id": "b", "text": "Congenital cataract in the left eye"}, {"id": "c", "text": "High farsightedness in the left eye"}, {"id": "d", "text": "Ptosis of the left eyelid"}, {"id": "e", "text": "Unequal refractive error between eyes"}]'::jsonb, '["b", "d"]', 'Deprivation amblyopia is caused by blocked vision, such as congenital cataract (b) or ptosis (d), so the brain doesn''t get clear input from that eye. Strabismus causes strabismic amblyopia (a), and high farsightedness or unequal refractive error causes refractive amblyopia (c, e).', true),
  ('amblyopia', 48, 'The nurse is reviewing follow-up reports for four 6-year-olds being treated for amblyopia. Which finding requires follow-up by the nurse?', '[{"id": "a", "text": "Improved acuity in the weaker eye after 4 months of patching"}, {"id": "b", "text": "Blurring in the stronger eye since atropine drops were started"}, {"id": "c", "text": "Social impact of the eye patch, with teasing and withdrawal"}, {"id": "d", "text": "Wearing the patch for several hours a day with a sticker chart"}]'::jsonb, '["c"]', 'Nurses should monitor for psychological effects of the social impact of eye patching, so teasing and withdrawal related to the patch require follow-up. Improved acuity in the weaker eye shows effectiveness, and blurring of the stronger eye is the expected atropine effect.', false),
  ('amblyopia', 49, 'A school nurse screens a 4-year-old whose eyes look straight. Vision in the right eye is clear, but vision in the left eye is poor. The parent says the child "sees just fine." Which action by the nurse is the BEST?', '[{"id": "a", "text": "Rescreen the child at next year''s visit"}, {"id": "b", "text": "Start patching the left eye at home now"}, {"id": "c", "text": "Reassure the parent because the eyes are straight"}, {"id": "d", "text": "Refer for an exam by a pediatric ophthalmologist"}]'::jsonb, '["d"]', 'Poor vision in one eye discovered on screening is a sign of amblyopia even when the child does not complain or the eyes look straight, and diagnosis includes an exam by a pediatric ophthalmologist. Patching the weaker left eye is incorrect, and waiting a year delays early detection.', false),
  ('amblyopia', 50, 'A pediatric eye clinic nurse is returning calls about children with amblyopia. Which child should the nurse address FIRST?', '[{"id": "a", "text": "A 5-year-old due for a routine patch check next month"}, {"id": "b", "text": "A 4-year-old whose parent stopped patching 2 months ago"}, {"id": "c", "text": "A 7-year-old with blur in the stronger eye on atropine"}, {"id": "d", "text": "A 12-year-old with untreated amblyopia wanting a sports note"}]'::jsonb, '["b"]', 'Adherence to patching or drops is essential for success, and this 4-year-old is within the period when treatment is most effective, so the lapse in therapy needs to be addressed first. Blur in the stronger eye is an expected atropine effect, and the routine check is not urgent.', false),
  ('cataracts', 1, 'During the initial newborn assessment of a 1-day-old, the nurse sees a red reflex in the right eye but no red reflex in the left eye. The newborn is otherwise stable. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Document the finding and recheck it at the 2-month well-baby visit"}, {"id": "b", "text": "Patch the right eye to stimulate the left eye before discharge"}, {"id": "c", "text": "Reassure the parents that the reflex develops during the first weeks"}, {"id": "d", "text": "Notify the health care provider immediately about the absent reflex"}]'::jsonb, '["d"]', 'An absent red reflex in a newborn requires immediate referral; the health care provider should be notified immediately because it may indicate congenital cataract or retinoblastoma. Waiting for the 2-month visit delays care during the first 6–8 weeks, when intervention must occur to prevent permanent vision loss.', false),
  ('cataracts', 2, 'A 3-week-old''s red reflex exam shows a normal red reflex in the left eye and a white reflex in the right eye. Which explanation for this finding is MOST likely?', '[{"id": "a", "text": "The right eye''s lens is opaque, so light cannot reach the retina properly."}, {"id": "b", "text": "The right eye is misaligned, so its reflection is off-center in the pupil."}, {"id": "c", "text": "The right eye has normal newborn clouding that clears by 2 months."}, {"id": "d", "text": "The right eye is affected by nystagmus, which scatters the reflected light."}]'::jsonb, '["a"]', 'In congenital cataracts the lens is partially or completely opaque, so light cannot reach the retina properly, and the red reflex is absent or white (leukocoria). A white reflex is never a normal newborn finding, since normally both eyes reflect red.', false),
  ('cataracts', 3, 'A 6-week-old infant has dense bilateral congenital cataracts. Which findings would the nurse expect when assessing this infant? Select all that apply.', '[{"id": "a", "text": "Nystagmus (involuntary eye movement)"}, {"id": "b", "text": "Does not follow objects"}, {"id": "c", "text": "Delayed visual development"}, {"id": "d", "text": "Less response to faces and toys"}, {"id": "e", "text": "Bright red reflex in both eyes"}]'::jsonb, '["a", "b", "c", "d"]', 'In bilateral cases the infant may appear less responsive to visual stimuli such as faces and toys (d); nystagmus (a), poor visual tracking — does not follow objects (b), and delayed visual development (c) are also signs. In cataracts the red reflex is absent or white, not bright red (e).', true),
  ('cataracts', 4, 'A 5-week-old was diagnosed with a dense congenital cataract that blocks vision in one eye. The parents ask to postpone surgery until the infant is 6 months old so that relatives can visit first. Which response by the nurse is BEST?', '[{"id": "a", "text": "Waiting until 6 months is reasonable, because the infant''s eye is still developing."}, {"id": "b", "text": "Intervention is urgent in the first 6–8 weeks to prevent permanent vision loss."}, {"id": "c", "text": "Surgery can wait as long as the other eye is patched during the delay."}, {"id": "d", "text": "Surgery is usually delayed until the infant can wear contact lenses safely."}]'::jsonb, '["b"]', 'Congenital cataracts require urgent intervention, especially in the first 6–8 weeks of life, to prevent permanent visual loss; this infant is already 5 weeks old. Delaying to 6 months risks irreversible amblyopia.', false),
  ('cataracts', 5, 'A nurse is reviewing newborn eye assessment findings on the postpartum unit. Which findings require IMMEDIATE referral? Select all that apply.', '[{"id": "a", "text": "White pupil reflex in the right eye"}, {"id": "b", "text": "Eyelids swollen after a vaginal birth"}, {"id": "c", "text": "Red reflex present and equal in both eyes"}, {"id": "d", "text": "Absent red reflex in the left eye"}, {"id": "e", "text": "Newborn blinks when a light is shined"}]'::jsonb, '["a", "d"]', 'An absent red reflex (d) or a white pupil reflex (leukocoria) (a) can indicate congenital cataract and requires immediate referral. Normally both eyes reflect red (c), and blinking to light (e) and eyelid swelling (b) are not signs of cataract.', true),
  ('cataracts', 6, 'A nurse in a pediatric clinic reviews four infants'' charts. Which infant should the nurse refer to a pediatric ophthalmologist FIRST?', '[{"id": "a", "text": "A 6-week-old with a red reflex present in both eyes"}, {"id": "b", "text": "A 2-month-old who blinks at light and follows faces"}, {"id": "c", "text": "A 3-week-old whose red reflex is absent in one eye"}, {"id": "d", "text": "A 4-month-old who tracks a toy across the visual field"}]'::jsonb, '["c"]', 'An absent red reflex suggests congenital cataract and requires immediate referral, and intervention must occur within the first 6–8 weeks of life. The other infants show a normal red reflex or normal visual tracking.', false),
  ('cataracts', 7, 'A nurse is reviewing a newborn''s history. Which findings are risk factors for congenital cataracts? Select all that apply.', '[{"id": "a", "text": "Galactosemia"}, {"id": "b", "text": "Down syndrome"}, {"id": "c", "text": "Family history of congenital cataracts"}, {"id": "d", "text": "Maternal rubella during pregnancy"}, {"id": "e", "text": "Newborn has nystagmus"}]'::jsonb, '["a", "b", "c", "d"]', 'Risk factors include TORCH infections during pregnancy such as rubella (d), metabolic disorders such as galactosemia (a), chromosomal abnormalities such as Down syndrome (b), and family history of congenital cataracts (c). Nystagmus (e) is a sign of congenital cataracts, not a cause.', true),
  ('cataracts', 8, 'A 4-week-old has bilateral congenital cataracts. There is no family history, the prenatal course was uncomplicated, and no infection occurred during pregnancy. Which test should the nurse anticipate NEXT to help identify the cause?', '[{"id": "a", "text": "Red reflex test at the next well-baby visit"}, {"id": "b", "text": "Visual tracking test with a toy"}, {"id": "c", "text": "Repeat slit-lamp examination in 6 months"}, {"id": "d", "text": "Genetic or metabolic testing"}]'::jsonb, '["d"]', 'Genetic or metabolic testing is done if the cause of the cataracts is unclear, as in this infant without family history or prenatal infection. The red reflex and slit-lamp exam help detect and view the cataract but do not identify its cause.', false),
  ('cataracts', 9, 'The parent of a 3-week-old with an abnormal red reflex asks what the upcoming slit-lamp examination will show. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "It measures how far the infant can see."}, {"id": "b", "text": "It checks whether the eyes are aligned."}, {"id": "c", "text": "It gives a detailed view of the lens."}, {"id": "d", "text": "It tests whether the infant can track."}]'::jsonb, '["c"]', 'Slit-lamp examination provides a detailed view of the lens to evaluate the cataract. Tracking and alignment are assessed by observation, not by the slit-lamp exam.', false),
  ('cataracts', 10, 'A nurse is preparing to care for a 7-week-old returning from lensectomy for a congenital cataract. Which prescribed medications should the nurse expect to administer?', '[{"id": "a", "text": "Eye drops: antibiotics, corticosteroids"}, {"id": "b", "text": "Atropine eye drops in the operated eye"}, {"id": "c", "text": "Oral antibiotics instead of eye drops"}, {"id": "d", "text": "Eye drops only if discharge appears"}]'::jsonb, '["a"]', 'Postoperative nursing care includes administering prescribed eye drops (antibiotics, corticosteroids). Waiting for discharge to appear before giving drops is incorrect, because adherence to eye drops is key to successful treatment.', false),
  ('cataracts', 11, 'A nurse on a pediatric unit receives reports on four infants who had lensectomy for congenital cataracts. Which infant should the nurse assess FIRST?', '[{"id": "a", "text": "A 2-month-old who is fussy before a scheduled feeding"}, {"id": "b", "text": "A 7-week-old with an eye shield in place who is sleeping"}, {"id": "c", "text": "A 3-month-old with fever and discharge from the operated eye"}, {"id": "d", "text": "A 2-month-old whose parent is due for contact lens teaching today"}]'::jsonb, '["c"]', 'After surgery the nurse monitors for signs of infection: redness, swelling, discharge, fever. Fever with discharge from the operated eye suggests infection and takes priority over a sleeping infant with a shield or routine teaching.', false),
  ('cataracts', 12, 'A nurse is teaching the parents of a 2-month-old who had lensectomy. Which signs of infection should the nurse teach the parents to watch for? Select all that apply.', '[{"id": "a", "text": "Swelling around the eye"}, {"id": "b", "text": "Infant follows faces with the eyes"}, {"id": "c", "text": "Discharge from the eye"}, {"id": "d", "text": "Fever"}, {"id": "e", "text": "Redness of the operated eye"}]'::jsonb, '["a", "c", "d", "e"]', 'Postoperative signs of infection include redness (e), swelling (a), discharge (c), and fever (d). An infant who follows faces (b) shows visual tracking, which is a desired finding, not infection.', true),
  ('cataracts', 13, 'A 2-month-old is recovering from lensectomy and keeps rubbing at the operated eye with a fist. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Place the eye shield to prevent injury to the eye"}, {"id": "b", "text": "Apply mittens and let the infant rub the other eye"}, {"id": "c", "text": "Give the next eye drop dose early to soothe the eye"}, {"id": "d", "text": "Patch the operated eye tightly until the next visit"}]'::jsonb, '["a"]', 'An eye shield or protective eyewear is used to prevent injury to the operated eye. Giving drops early is not a prescribed action, and the patch in cataract treatment covers the stronger eye to prevent amblyopia rather than the operated eye.', false),
  ('cataracts', 14, 'Three weeks after cataract surgery, the parent of a 3-month-old calls to report that the operated eye now seems to turn inward. Which response by the nurse is BEST?', '[{"id": "a", "text": "This change in eye alignment should be reported to the provider."}, {"id": "b", "text": "This is expected while the eye heals and needs no special follow-up."}, {"id": "c", "text": "Patch the eye that turns inward until it straightens again."}, {"id": "d", "text": "Wait and mention this at the next routine well-baby visit."}]'::jsonb, '["a"]', 'Caregivers should report any decrease in vision or eye alignment changes after surgery; strabismus is also a complication of congenital cataracts. Waiting or patching the turned eye delays evaluation.', false),
  ('cataracts', 15, 'After lensectomy, a 2-month-old is fitted with a contact lens. The parent asks, "The surgery removed the cataract, so why does she still need a lens?" Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "The contact lens protects the eye from injury until it heals."}, {"id": "b", "text": "Corrective lenses are needed to focus light on the retina."}, {"id": "c", "text": "The lens keeps the cataract from growing back after surgery."}, {"id": "d", "text": "The contact lens blurs the stronger eye to prevent amblyopia."}]'::jsonb, '["b"]', 'Post-op visual rehabilitation uses corrective lenses or glasses to focus light on the retina, and infants may wear contact lenses or glasses after surgery. Protection from injury is the role of an eye shield or protective eyewear.', false),
  ('cataracts', 16, 'A 3-month-old had a cataract removed from the right eye. The left eye is normal. The ophthalmologist orders patching therapy. Which instruction by the nurse is MOST appropriate?', '[{"id": "a", "text": "Patch the right eye to protect it while it heals."}, {"id": "b", "text": "Patch the right eye only while the infant sleeps."}, {"id": "c", "text": "Patch each eye on alternating days for balance."}, {"id": "d", "text": "Patch the left eye so the right eye is stimulated."}]'::jsonb, '["d"]', 'Patching therapy patches the stronger eye — here the normal left eye — to stimulate the weaker eye and prevent amblyopia. Protection of the operated eye is provided by an eye shield or protective eyewear, not the patch.', false),
  ('cataracts', 17, 'The parent of a 1-month-old with a dense congenital cataract asks why the cataract affects vision even though the eye itself is healthy. Which explanations by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "The lens clears by itself as the visual cortex matures"}, {"id": "b", "text": "The opaque lens keeps light from reaching the retina properly"}, {"id": "c", "text": "The cataract makes the eye turn inward from birth"}, {"id": "d", "text": "The cataract causes the retina to detach from the eye"}, {"id": "e", "text": "The visual cortex doesn''t receive proper stimulation"}]'::jsonb, '["b", "e"]', 'The lens is partially or completely opaque, so light cannot reach the retina properly (b), and the visual cortex doesn''t receive proper stimulation, so vision development is impaired and leads to amblyopia (e). Strabismus is a sign or complication, not the mechanism (c); retinal detachment is not described (d); and the lens does not clear on its own (a).', true),
  ('cataracts', 18, 'A 4-month-old''s dense congenital cataract was not removed until this week because the family missed several appointments. Which explanation of the infant''s prognosis is MOST accurate?', '[{"id": "a", "text": "Vision will be normal once the lens is removed"}, {"id": "b", "text": "Amblyopia from the delay may now be irreversible"}, {"id": "c", "text": "The delay matters only if both eyes are affected"}, {"id": "d", "text": "Surgery after 8 weeks fully prevents amblyopia"}]'::jsonb, '["b"]', 'If treatment is delayed beyond the first 6–8 weeks, complications include permanent vision loss and amblyopia (irreversible). Removing the lens late does not guarantee normal vision, because the window for preventing permanent loss is the first 6–8 weeks.', false),
  ('cataracts', 19, 'The parent of a 3-month-old says, "She''s such a calm baby. She doesn''t really look at our faces or reach for her toys." Both eyes have a gray pupil reflex. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "This is a normal calm temperament, and her vision will develop with time."}, {"id": "b", "text": "Reduced interest in faces is expected until about 6 months of age."}, {"id": "c", "text": "The infant is likely tired and needs to be assessed after a nap."}, {"id": "d", "text": "Bilateral cataracts may make an infant less responsive to faces and toys."}]'::jsonb, '["d"]', 'In bilateral cataracts, an infant may appear less responsive to visual stimuli such as faces and toys, and a gray pupil reflex (leukocoria) is a key sign. Attributing this to temperament delays urgent intervention.', false),
  ('cataracts', 20, 'The parent of a 2-month-old reports several changes noticed at home. Which findings should the nurse recognize as possible signs of a congenital cataract? Select all that apply.', '[{"id": "a", "text": "Eyes that seem misaligned"}, {"id": "b", "text": "Bright red eyes in flash photos"}, {"id": "c", "text": "Excessive squinting or blinking"}, {"id": "d", "text": "Sleeping 15 hours a day"}, {"id": "e", "text": "A white pupil in flash photos"}]'::jsonb, '["a", "c", "e"]', 'A white or gray pupil reflex (leukocoria) (e), strabismus (misaligned eyes) (a), and excessive squinting or blinking (c) are signs of congenital cataract. Normally both eyes reflect red (b), and sleep patterns (d) are not a listed sign.', true),
  ('cataracts', 21, 'A 2-month-old had a normal red reflex in both eyes at birth. At today''s well-baby visit, the parent asks why the nurse is checking the red reflex again. Which response by the nurse is BEST?', '[{"id": "a", "text": "It is repeated only because the newborn exam is often done incorrectly."}, {"id": "b", "text": "It is required only for infants whose mothers had an infection while they were pregnant."}, {"id": "c", "text": "Cataracts can develop during infancy, so the red reflex is checked at well-baby visits."}, {"id": "d", "text": "The red reflex first becomes visible at 2 months, so the newborn check is not reliable."}]'::jsonb, '["c"]', 'Congenital cataracts may be present at birth or develop during infancy, so the red reflex test is done at birth and at well-baby checks. Screening at birth and well-child visits is critical for every infant, not only those with risk factors.', false),
  ('cataracts', 22, 'Two 5-week-old infants have congenital cataracts. Infant A has a large, dense cataract blocking vision in the left eye. Infant B has a cataract that is not blocking vision. Which plan should the nurse anticipate?', '[{"id": "a", "text": "Surgery for both infants after 6 months"}, {"id": "b", "text": "Surgical lens removal for Infant B only"}, {"id": "c", "text": "Surgical lens removal for Infant A"}, {"id": "d", "text": "Patching alone for Infant A until age 3"}]'::jsonb, '["c"]', 'Surgical lens removal (lensectomy) is performed if the cataract is large or blocking vision, and dense cataracts need surgery ideally within weeks. Delaying until 6 months or relying on patching alone risks permanent vision loss.', false),
  ('cataracts', 23, 'A parent of a newborn with an absent red reflex asks, "Why is everyone in such a hurry? Can''t the eye doctor see her next month?" Which response by the nurse is BEST?', '[{"id": "a", "text": "Most newborns have an absent reflex, so the hurry is mainly for reassurance."}, {"id": "b", "text": "The red reflex often returns within a few weeks, so the visit is mainly a precaution."}, {"id": "c", "text": "Surgery cannot be done until 6 months, but the doctor wants a baseline exam."}, {"id": "d", "text": "It may indicate a cataract or retinoblastoma, so it needs immediate referral."}]'::jsonb, '["d"]', 'An absent red reflex may indicate congenital cataract or retinoblastoma and requires immediate referral; for cataracts, intervention must occur within the first 6–8 weeks of life. Normally both eyes reflect red, so an absent reflex is not a common normal finding.', false),
  ('cataracts', 24, 'A nurse explains the diagnostic workup to the parents of a 2-week-old with leukocoria. Which components should the nurse expect? Select all that apply.', '[{"id": "a", "text": "Waiting to test until vision can be measured"}, {"id": "b", "text": "Slit-lamp examination of the lens"}, {"id": "c", "text": "Corneal light reflex test only"}, {"id": "d", "text": "Referral to a pediatric ophthalmologist"}, {"id": "e", "text": "Genetic or metabolic testing if the cause is unclear"}]'::jsonb, '["b", "d", "e"]', 'Diagnosis includes slit-lamp examination for a detailed view of the lens (b), ophthalmologic referral so a pediatric ophthalmologist confirms the diagnosis (d), and genetic or metabolic testing if the cause is unclear (e). A light reflex test alone is not the workup (c), and waiting delays urgent intervention (a).', true),
  ('cataracts', 25, 'Two weeks after lensectomy, the parent of a 10-week-old says, "The eye looks so much better, so I''m going to stop the eye drops early." Which response by the nurse is BEST?', '[{"id": "a", "text": "Stopping early is fine once the eye looks clear and white again."}, {"id": "b", "text": "Adherence to the eye drops is key to successful treatment."}, {"id": "c", "text": "You can stop the drops but keep the eye shield on at night."}, {"id": "d", "text": "Use the drops only on days when the eye looks red to you."}]'::jsonb, '["b"]', 'Adherence to eye drops, follow-ups, and patching is key to successful treatment, so the prescribed drops should be continued. Using drops only when the eye looks red is not the prescribed plan.', false),
  ('cataracts', 26, 'The parents of a 2-month-old ask what can happen if treatment of a congenital cataract is delayed. Which complications should the nurse include? Select all that apply.', '[{"id": "a", "text": "Blindness"}, {"id": "b", "text": "Return of a normal red reflex"}, {"id": "c", "text": "Irreversible amblyopia"}, {"id": "d", "text": "Strabismus"}, {"id": "e", "text": "Lens that clears without surgery"}]'::jsonb, '["a", "c", "d"]', 'Complications of untreated or delayed treatment include amblyopia (irreversible) (c), strabismus (d), and blindness (a). The opaque lens does not clear without surgery (e), and an absent or white reflex does not return to normal on its own (b).', true),
  ('cataracts', 27, 'A nurse is teaching the parents of a 3-month-old who will go home with a contact lens and protective eyewear after cataract surgery. Which statement by a parent indicates understanding?', '[{"id": "a", "text": "We''ll leave off the eyewear at home because she won''t bump it there."}, {"id": "b", "text": "We''ll learn to handle her contact lens and eye protection safely."}, {"id": "c", "text": "We can skip the contact lens on days when she seems fussy or tired."}, {"id": "d", "text": "We''ll take the eyewear off whenever she starts rubbing her eye."}]'::jsonb, '["b"]', 'Parents are taught safe handling of eye protection and contact lenses or glasses post-surgery. Removing protective eyewear defeats its purpose of preventing injury, and skipping the lens interrupts visual rehabilitation.', false),
  ('cataracts', 28, 'A 3-month-old has poor visual tracking and does not follow a bright toy or the parent''s face. Which assessment should the nurse perform FIRST?', '[{"id": "a", "text": "Developmental milestone survey"}, {"id": "b", "text": "Hearing screen of both ears"}, {"id": "c", "text": "Red reflex test of both eyes"}, {"id": "d", "text": "Measurement of head circumference"}]'::jsonb, '["c"]', 'Poor visual tracking — does not follow objects — is a sign of congenital cataract, and the red reflex test normally shows red in both eyes but is absent or white in cataracts. The other assessments do not evaluate the lens.', false),
  ('cataracts', 29, 'The parent of a 2-month-old asks why the surgeon has not placed an artificial lens during the planned lensectomy. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "IOL implant is sometimes delayed; infants may wear contact lenses or glasses."}, {"id": "b", "text": "An intraocular lens is never used in infants or in young children of any age."}, {"id": "c", "text": "The natural lens grows back after surgery, so an artificial lens is unnecessary."}, {"id": "d", "text": "An implant is placed only if patching therapy fails after age 3."}]'::jsonb, '["a"]', 'An intraocular lens (IOL) implant is sometimes delayed, and infants may wear contact lenses or glasses post-op. The natural lens does not grow back after surgical lens removal.', false),
  ('cataracts', 30, 'A nurse is teaching the parents of a 2-month-old after lensectomy about visual rehabilitation. Which parts of the plan should the nurse include? Select all that apply.', '[{"id": "a", "text": "Patch the stronger eye to prevent amblyopia"}, {"id": "b", "text": "Regular ophthalmology follow-up"}, {"id": "c", "text": "Glasses only after the child turns 3"}, {"id": "d", "text": "Corrective lenses to focus light on the retina"}, {"id": "e", "text": "Patch over the operated eye all day"}]'::jsonb, '["a", "b", "d"]', 'Rehabilitation includes corrective lenses or glasses to focus light on the retina (d), patching the stronger eye to stimulate the weaker eye and prevent amblyopia (a), and regular ophthalmology follow-up to monitor visual development (b). The operated (weaker) eye is not patched (e), and lenses are needed post-op, not years later (c).', true),
  ('cataracts', 31, 'A 6-week-old''s mother says she noticed the baby''s eyes "jiggle" side to side and one pupil looks gray in photos. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "These are normal newborn eye movements that resolve by 3 months."}, {"id": "b", "text": "Nystagmus with leukocoria suggests a congenital cataract."}, {"id": "c", "text": "The gray pupil is a camera artifact and needs no follow-up."}, {"id": "d", "text": "This suggests the infant has had too much screen exposure."}]'::jsonb, '["b"]', 'Nystagmus (involuntary eye movement) and a white or gray pupil reflex (leukocoria) are signs of congenital cataract, and at 6 weeks the infant is within the window when urgent intervention is required. Dismissing these findings delays treatment.', false),
  ('cataracts', 32, 'A nurse is planning parent teaching for an infant diagnosed with a dense congenital cataract at 2 weeks of age. Which teaching point should the nurse emphasize as MOST important?', '[{"id": "a", "text": "Surgery is best delayed until the eye is fully developed in early childhood."}, {"id": "b", "text": "Glasses alone usually clear a dense cataract within a few months."}, {"id": "c", "text": "Early surgery, ideally within weeks, is important for dense cataracts."}, {"id": "d", "text": "Patching should be tried for a year before surgery is considered."}]'::jsonb, '["c"]', 'Parents should understand the importance of early surgery, ideally within weeks for dense cataracts, because intervention must occur within the first 6–8 weeks to prevent permanent vision loss. Glasses do not clear a cataract.', false),
  ('cataracts', 33, 'Four months after cataract surgery, the parent of a 7-month-old says, "Her glasses keep falling off, so we stopped using them. She seems fine." Which response by the nurse is BEST?', '[{"id": "a", "text": "That''s fine, since the surgery already removed the cataract."}, {"id": "b", "text": "She only needs the glasses if her eye starts to turn inward."}, {"id": "c", "text": "Glasses can wait until she is old enough to keep them on."}, {"id": "d", "text": "Vision rehabilitation with glasses is needed to prevent amblyopia."}]'::jsonb, '["d"]', 'Parents should understand the risk of amblyopia and the importance of vision rehabilitation; corrective lenses or glasses focus light on the retina after lens removal. Waiting risks irreversible amblyopia.', false),
  ('cataracts', 34, 'A newborn''s red reflex is absent in the right eye. The parent asks who will confirm whether this is a cataract. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "The diagnosis will be confirmed at the 2-month well-baby visit."}, {"id": "b", "text": "The nurse can confirm it by repeating the red reflex test tomorrow."}, {"id": "c", "text": "A pediatric ophthalmologist will examine the eye to confirm it."}, {"id": "d", "text": "Genetic testing alone will confirm the diagnosis of a cataract."}]'::jsonb, '["c"]', 'Ophthalmologic referral is needed, and a pediatric ophthalmologist confirms the diagnosis. Genetic or metabolic testing is done only if the cause is unclear, not to confirm the cataract.', false),
  ('cataracts', 35, 'The parents of a 2-month-old are preparing for discharge after lensectomy. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Give prescribed eye drops (antibiotics, corticosteroids)"}, {"id": "b", "text": "Use the eye shield or protective eyewear"}, {"id": "c", "text": "Keep all ophthalmology follow-up appointments"}, {"id": "d", "text": "Remove the eye shield whenever the infant rubs"}, {"id": "e", "text": "Handle contact lenses or glasses safely"}]'::jsonb, '["a", "b", "c", "e"]', 'Discharge teaching includes giving prescribed eye drops (antibiotics, corticosteroids) (a), using an eye shield or protective eyewear to prevent injury (b), adherence to follow-ups (c), and safe handling of contact lenses or glasses (e). Removing the shield when the infant rubs (d) exposes the eye to injury.', true),
  ('cataracts', 36, 'A 1-week-old newborn has been diagnosed with galactosemia, and the parent asks why an eye exam was ordered. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "Galactosemia is a chromosomal abnormality like Down syndrome."}, {"id": "b", "text": "Galactosemia is a TORCH infection that spreads to the eyes in the weeks after birth."}, {"id": "c", "text": "Galactosemia causes the eyes to turn, which is checked by eye exam."}, {"id": "d", "text": "Galactosemia is a metabolic disorder that is a risk factor for cataracts."}]'::jsonb, '["d"]', 'Metabolic disorders such as galactosemia are risk factors for congenital cataracts. Galactosemia is not a TORCH infection or a chromosomal abnormality such as Down syndrome.', false),
  ('cataracts', 37, 'The parent of a 2-month-old asks why the surgeon insists on operating soon on a dense cataract. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "Intervention is urgent in the first 6–8 weeks of life"}, {"id": "b", "text": "Surgery works best after age 6 months"}, {"id": "c", "text": "Early surgery prevents permanent vision loss"}, {"id": "d", "text": "Waiting allows the lens to clear naturally"}, {"id": "e", "text": "Glasses can replace surgery for dense cataracts"}]'::jsonb, '["a", "c"]', 'Urgent intervention is required in the first 6–8 weeks of life (a) to prevent permanent vision loss (c). Delaying to 6 months risks irreversible amblyopia (b), the opaque lens does not clear naturally (d), and lensectomy is performed when the cataract is large or blocking vision (e).', true),
  ('cataracts', 38, 'A nurse observes assistive personnel caring for a 2-month-old the day after lensectomy. Which action by the assistive personnel requires intervention by the nurse?', '[{"id": "a", "text": "Removing the eye shield so the infant can rub the eye"}, {"id": "b", "text": "Reporting redness and discharge from the operated eye"}, {"id": "c", "text": "Placing protective eyewear back on after a feeding"}, {"id": "d", "text": "Telling the nurse that the infant now feels warm"}]'::jsonb, '["a"]', 'An eye shield or protective eyewear is used to prevent injury, so removing it to let the infant rub the eye requires intervention. Reporting redness, discharge, or warmth is appropriate, because these are signs of infection.', false),
  ('cataracts', 39, 'A nurse is calling parents of infants who recently had cataract surgery. Which parent statements require follow-up by the nurse? Select all that apply.', '[{"id": "a", "text": "No more follow-ups, since she looks fine"}, {"id": "b", "text": "Her eye alignment has changed since surgery"}, {"id": "c", "text": "We watch her eye for redness and discharge"}, {"id": "d", "text": "No more eye drops; the eye looks clear now"}, {"id": "e", "text": "We put her eye shield back on after each bath"}]'::jsonb, '["a", "b", "d"]', 'Stopping drops early (d) and skipping follow-up (a) conflict with the teaching that adherence to eye drops, follow-ups, and patching is key, and eye alignment changes (b) are something caregivers should report. Replacing the shield (e) and watching for redness and discharge (c) are correct.', true),
  ('cataracts', 40, 'A nurse reviews the prenatal record of a newborn whose left pupil appears white. Which maternal history finding is MOST relevant to the newborn''s eye finding?', '[{"id": "a", "text": "Intention to breastfeed after birth"}, {"id": "b", "text": "Gestational weight gain within normal range"}, {"id": "c", "text": "Planned cesarean birth at 39 weeks"}, {"id": "d", "text": "Rubella infection during the pregnancy"}]'::jsonb, '["d"]', 'TORCH infections during pregnancy, including rubella, are associated with congenital cataracts, which cause a white pupil reflex (leukocoria). The other findings are not listed causes or risk factors.', false),
  ('cataracts', 41, 'After cataract surgery, a parent asks which changes in the infant''s eyes need to be reported right away. Which findings should the nurse tell the parent to report? Select all that apply.', '[{"id": "a", "text": "A change in eye alignment"}, {"id": "b", "text": "Infant reaching for bright toys"}, {"id": "c", "text": "A decrease in the infant''s vision"}, {"id": "d", "text": "Wearing glasses as prescribed"}, {"id": "e", "text": "Eye shield in place during sleep"}]'::jsonb, '["a", "c"]', 'Caregivers should report any decrease in vision (c) or eye alignment changes (a). Wearing glasses (d) and the eye shield (e) are prescribed care, and reaching for toys (b) shows visual responsiveness.', true),
  ('cataracts', 42, 'A 2-month-old had lensectomy 6 days ago. Which finding during a home visit requires IMMEDIATE follow-up by the nurse?', '[{"id": "a", "text": "The infant has fever and swelling around the operated eye"}, {"id": "b", "text": "The infant is wearing a contact lens in the operated eye"}, {"id": "c", "text": "The parent gives the eye drops at the prescribed times"}, {"id": "d", "text": "The infant has protective eyewear on while napping"}]'::jsonb, '["a"]', 'Fever and swelling are signs of infection after surgery, which the nurse must monitor for and act on. A contact lens, prescribed drops, and protective eyewear are all expected parts of postoperative care.', false),
  ('cataracts', 43, 'The parents of a 2-month-old ask about the plan for their infant''s surgery and lens. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "Glasses are not needed after the lens is removed"}, {"id": "b", "text": "Infants may wear contact lenses or glasses post-op"}, {"id": "c", "text": "Every cataract needs surgery regardless of its size"}, {"id": "d", "text": "Lensectomy is done if the cataract is large or blocking vision"}, {"id": "e", "text": "The IOL is always placed during the first surgery"}]'::jsonb, '["b", "d"]', 'Surgical lens removal (lensectomy) is performed if the cataract is large or blocking vision (d), and infants may wear contact lenses or glasses post-op because an IOL implant is sometimes delayed (b). The IOL is not always placed at the first surgery (e), corrective lenses are needed to focus light on the retina (a), and surgery depends on size or blocking of vision (c).', true),
  ('cataracts', 44, 'A 2-month-old has a confirmed congenital cataract. The parent asks whether the cataract could affect anything besides the eye. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "No, a cataract affects only how the eye looks in photographs."}, {"id": "b", "text": "Yes, untreated or delayed treatment can lead to delayed development."}, {"id": "c", "text": "No, the cataract will clear on its own before it can affect development."}, {"id": "d", "text": "Yes, a cataract can cause galactosemia if it is not removed."}]'::jsonb, '["b"]', 'Complications of untreated or delayed treatment include delayed development, along with amblyopia, strabismus, and blindness. Galactosemia is a cause of congenital cataracts, not a complication.', false),
  ('cataracts', 45, 'A nurse is caring for a 6-week-old on the day of lensectomy. Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Use an eye shield to prevent injury"}, {"id": "b", "text": "Teach the parents to apply eye drops safely"}, {"id": "c", "text": "Remove the shield so the infant can rub freely"}, {"id": "d", "text": "Delay drop teaching until the 6-month follow-up"}, {"id": "e", "text": "Administer prescribed eye drops (antibiotics)"}]'::jsonb, '["a", "b", "e"]', 'Postoperative nursing care includes administering prescribed eye drops (antibiotics, corticosteroids) (e), using an eye shield to prevent injury (a), and teaching parents how to apply eye drops safely (b). Removing the shield exposes the eye to injury (c), and delaying teaching undermines adherence to eye drops, which is key (d).', true),
  ('cataracts', 46, 'A 2-month-old''s nystagmus is noted at a well-baby visit. Which additional finding would MOST strongly suggest a congenital cataract?', '[{"id": "a", "text": "Red reflex equal in both eyes"}, {"id": "b", "text": "Gray pupil reflex in one eye"}, {"id": "c", "text": "Infant follows the parent''s face"}, {"id": "d", "text": "Eyes aligned when looking ahead"}]'::jsonb, '["b"]', 'A white or gray pupil reflex (leukocoria) together with nystagmus suggests congenital cataract. A red reflex in both eyes and following faces are normal findings.', false),
  ('cataracts', 47, 'Two months after cataract surgery, the parent of a 4-month-old says, "Her eye looks perfect now, so we''re canceling the eye doctor visits." Which response by the nurse is BEST?', '[{"id": "a", "text": "Regular follow-up monitors visual development and prevents complications."}, {"id": "b", "text": "That''s fine because the cataract was removed and cannot cause problems."}, {"id": "c", "text": "Follow-up is needed only if the eye becomes red or develops discharge."}, {"id": "d", "text": "Visits can resume when she is old enough for a vision chart test at school."}]'::jsonb, '["a"]', 'Regular ophthalmology follow-up monitors visual development and prevents complications, and adherence to follow-ups is key to successful treatment. Waiting for infection signs or school age misses developing amblyopia.', false),
  ('cataracts', 48, 'A 7-week-old with a dense congenital cataract has not yet had surgery scheduled because of insurance paperwork. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Schedule a routine follow-up visit in 3 months"}, {"id": "b", "text": "Teach the parents to patch the affected eye at home"}, {"id": "c", "text": "Advocate for urgent surgery within the first 6–8 weeks"}, {"id": "d", "text": "Arrange genetic testing before any surgery is planned"}]'::jsonb, '["c"]', 'Urgent intervention is required within the first 6–8 weeks of life to prevent permanent vision loss, and this infant is 7 weeks old. Patching the affected eye would further deprive it, and routine follow-up delays care.', false),
  ('cataracts', 49, 'A 3-month-old with a congenital cataract in the left eye is noted to squint and blink excessively. The parent believes the infant is just sensitive to light. Which response by the nurse is BEST?', '[{"id": "a", "text": "Light sensitivity is common, so the infant needs sunglasses outdoors."}, {"id": "b", "text": "Excessive squinting or blinking can be a sign of the cataract."}, {"id": "c", "text": "The squinting is from the infant''s eye drops and will stop soon."}, {"id": "d", "text": "Blinking means the eye is healing and the cataract is clearing."}]'::jsonb, '["b"]', 'Excessive squinting or blinking is listed among the signs of congenital cataracts. The cataract does not clear on its own.', false),
  ('cataracts', 50, 'A nurse is caring for a newborn with Down syndrome. Which assessment should the nurse make a PRIORITY related to the infant''s eyes?', '[{"id": "a", "text": "Checking the red reflex in both eyes"}, {"id": "b", "text": "Testing visual acuity with a chart"}, {"id": "c", "text": "Measuring eye alignment with a cover test"}, {"id": "d", "text": "Deferring eye exams until 6 months"}]'::jsonb, '["a"]', 'Chromosomal abnormalities such as Down syndrome are risk factors for congenital cataracts, and the nurse should always assess the red reflex in newborns. Deferring the exam risks missing the 6–8 week window.', false),
  ('conjunctivitis', 1, 'A parent calls about a 4-year-old who woke with both eyelids crusted shut and thick yellow-green drainage. The child is afebrile and has had no cold symptoms. Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "Apply cool compresses and artificial tears until the redness fades."}, {"id": "b", "text": "Arrange a provider visit for antibiotic eye drops or ointment."}, {"id": "c", "text": "Use antihistamine drops such as olopatadine and remove the allergen."}, {"id": "d", "text": "Irrigate both eyes with saline and avoid further exposure."}]'::jsonb, '["b"]', 'Thick yellow or green pus with crusty eyelids in the morning points to bacterial conjunctivitis, which is treated with antibiotic eye drops or ointment. Cool compresses and artificial tears are supportive care for viral conjunctivitis and would not treat a bacterial infection.', false),
  ('conjunctivitis', 2, 'A 6-year-old has red, gritty eyes with watery discharge and a swollen preauricular lymph node. The child had a runny nose and cough last week. The parent plans to use a sibling''s leftover antibiotic eye drops. Which response by the nurse is BEST?', '[{"id": "a", "text": "Use the drops, because this type of pink eye is highly contagious."}, {"id": "b", "text": "Use the drops until the morning crusting of the eyelids stops."}, {"id": "c", "text": "No antibiotics; cool compresses and artificial tears will help."}, {"id": "d", "text": "Use antihistamine drops instead, since itching is the main concern."}]'::jsonb, '["c"]', 'Watery discharge, gritty eyes, preauricular lymph node swelling and a preceding cold suggest viral conjunctivitis, which receives supportive care with cool compresses and artificial tears and no antibiotics. Viral pink eye is highly contagious, but that does not make antibiotics useful, and eye drops should not be shared.', false),
  ('conjunctivitis', 3, 'A school nurse assesses five children who have red eyes. Based on the findings, which children should be kept home from school because their conjunctivitis is contagious? Select all that apply.', '[{"id": "a", "text": "A 7-year-old with thick green pus and crusty eyelids in the morning"}, {"id": "b", "text": "A 9-year-old with watery discharge and gritty eyes that began after a cold"}, {"id": "c", "text": "An 8-year-old with clear, stringy mucus, itching, and sneezing"}, {"id": "d", "text": "A 10-year-old with burning, watery eyes after swimming in a chlorinated pool"}, {"id": "e", "text": "A 6-year-old with mucous discharge and preauricular lymph node swelling"}]'::jsonb, '["a", "b", "e"]', 'Thick green pus with morning crusting is bacterial and highly contagious. Watery discharge with gritty eyes after a cold, and mucous discharge with preauricular lymph node swelling, are viral and highly contagious; viral and bacterial types stay home until criteria are met. Clear, stringy mucus with itching and sneezing is allergic, and burning, watery eyes after chlorine exposure is chemical/irritant; neither type is contagious.', true),
  ('conjunctivitis', 4, 'A 3-day-old newborn whose mother had no prenatal care develops marked swelling of both eyelids and thick, purulent discharge from both eyes. Vital signs are within normal limits. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Notify the provider immediately for urgent evaluation."}, {"id": "b", "text": "Clean each eye with warm water and a cotton ball, then reassess."}, {"id": "c", "text": "Apply erythromycin ointment and recheck at the next feeding."}, {"id": "d", "text": "Reassure the parents that drainage is expected after prophylaxis."}]'::jsonb, '["a"]', 'Thick discharge on day 3 falls in the 2–5 day window for Neisseria gonorrhoeae, which can cause blindness; neonatal eye discharge is an emergency requiring immediate referral, urgent evaluation and systemic antibiotics. Erythromycin ointment at birth is prevention, and cleaning the eye first only delays care.', false),
  ('conjunctivitis', 5, 'A 10-day-old infant is brought to the clinic with red eyes and discharge that began yesterday. The eyes were clear at the 3-day newborn visit. Based on the timing, which organism is the MOST likely cause?', '[{"id": "a", "text": "Adenovirus"}, {"id": "b", "text": "Neisseria gonorrhoeae"}, {"id": "c", "text": "Haemophilus influenzae"}, {"id": "d", "text": "Chlamydia trachomatis"}]'::jsonb, '["d"]', 'Chlamydia trachomatis neonatal conjunctivitis appears 5–14 days after birth, so onset on day 9–10 fits. Neisseria gonorrhoeae presents earlier, 2–5 days after birth, and the eyes were clear on day 3.', false),
  ('conjunctivitis', 6, 'A nurse in a pediatric clinic receives four phone messages about children with eye symptoms. Which child should the nurse call back FIRST?', '[{"id": "a", "text": "A 5-year-old with green discharge who started antibiotic drops yesterday"}, {"id": "b", "text": "A 7-year-old with itchy, watery eyes and sneezing during pollen season"}, {"id": "c", "text": "A 4-day-old with swollen eyelids and thick discharge from both eyes"}, {"id": "d", "text": "A 9-year-old with burning eyes after swimming in a chlorinated pool"}]'::jsonb, '["c"]', 'Neonatal conjunctivitis is an emergency: discharge 2–5 days after birth fits Neisseria gonorrhoeae, which can cause blindness, so the newborn must be referred immediately. The child on day 1 of antibiotics has not reached the 2–3 days after which lack of improvement needs reevaluation.', false),
  ('conjunctivitis', 7, 'The nurse teaches the parent of a 14-year-old with bacterial conjunctivitis who wears eye makeup and contact lenses. Which statements by the parent indicate understanding of the teaching? Select all that apply.', '[{"id": "a", "text": "\"I will use hand hygiene before and after her eye drops.\""}, {"id": "b", "text": "\"She can share a towel with her sister if we wash it daily.\""}, {"id": "c", "text": "\"I will place the drops into the conjunctival sac, not on the eye.\""}, {"id": "d", "text": "\"We will dispose of the eye makeup and contacts used during the infection.\""}, {"id": "e", "text": "\"I will use one cotton ball to wipe back and forth across both eyes.\""}]'::jsonb, '["a", "c", "d"]', 'Hand hygiene is the most important prevention; drops go into the conjunctival sac rather than directly on the eye; and eye makeup or contact lenses used during infection are disposed of. Towels are not shared even if washed, and eyes are cleaned with one wipe per swipe of the cotton ball, not back and forth.', true),
  ('conjunctivitis', 8, 'A 6-year-old with bacterial conjunctivitis is prescribed antibiotic eye drops and an antibiotic eye ointment, both scheduled at 0900. Which administration plan by the nurse is BEST?', '[{"id": "a", "text": "Apply the ointment, then instill the drops right away."}, {"id": "b", "text": "Instill the drops, wait 5–10 minutes, then apply the ointment."}, {"id": "c", "text": "Apply the ointment, wait 5–10 minutes, then instill the drops."}, {"id": "d", "text": "Instill the drops and the ointment together onto the cornea."}]'::jsonb, '["b"]', 'When both drops and ointment are used, drops are given first, followed by a 5–10 minute wait before the ointment. Reversing the order uses the right wait time in the wrong sequence, and medication goes into the conjunctival sac rather than directly on the eye.', false),
  ('conjunctivitis', 9, 'A 7-year-old whose conjunctivitis followed a cold still has watery discharge on day 4; the provider recommended cool compresses only. The parent asks when the child can return to school. Which response by the nurse is BEST?', '[{"id": "a", "text": "Right away, because this type of pink eye is not contagious."}, {"id": "b", "text": "After the child has received antibiotic drops for 24 hours."}, {"id": "c", "text": "Once the itching stops, since itching means it is still active."}, {"id": "d", "text": "When the discharge resolves, because this type is contagious."}]'::jsonb, '["d"]', 'Conjunctivitis following a cold and treated with supportive care is viral; viral conjunctivitis is highly contagious, and the child returns when the discharge resolves. The 24-hour antibiotic rule applies to bacterial conjunctivitis, and antibiotics are not given for viral pink eye.', false),
  ('conjunctivitis', 10, 'A 5-year-old was diagnosed with bacterial conjunctivitis this morning, received the first antibiotic dose 2 hours ago, and still has thick yellow discharge. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll keep a separate towel and washcloth just for him at home.\""}, {"id": "b", "text": "\"I''ll clean his eye gently with warm water and a cotton ball.\""}, {"id": "c", "text": "\"He can return to school today because the drops have started.\""}, {"id": "d", "text": "\"I''ll wash my hands each time after I put in his eye drops.\""}]'::jsonb, '["c"]', 'A child with bacterial conjunctivitis returns to school only after 24 hours on antibiotics, and this child still has discharge after a single dose. Separate towels, gentle cleaning with warm water and a cotton ball, and hand hygiene are all correct.', false),
  ('conjunctivitis', 11, 'The school nurse reviews follow-up notes on five children being treated for conjunctivitis. Which children should the nurse refer to the provider for reevaluation? Select all that apply.', '[{"id": "a", "text": "An 8-year-old on day 1 of cool compresses for watery discharge after a cold"}, {"id": "b", "text": "A 10-year-old with no improvement after 3 days of antibiotic eye drops"}, {"id": "c", "text": "A 7-year-old with recurrent infections of bacterial conjunctivitis"}, {"id": "d", "text": "A 9-year-old with itchy eyes that improve after the allergen is removed"}, {"id": "e", "text": "A 6-year-old who now reports severe eye pain and light sensitivity"}]'::jsonb, '["b", "c", "e"]', 'No improvement after 2–3 days of treatment, recurrent infections, and severe pain with photophobia (light sensitivity) are all reasons to refer or reevaluate. A child on day 1 of supportive care for viral conjunctivitis has not had time to fail treatment, and improvement after removing the allergen is the expected response in allergic conjunctivitis.', true),
  ('conjunctivitis', 12, 'A 6-year-old is on day 2 of antibiotic eye drops for bacterial conjunctivitis. Which finding reported by the parent requires IMMEDIATE follow-up?', '[{"id": "a", "text": "He reports light sensitivity and vision changes since last night."}, {"id": "b", "text": "His eyelids are less crusty this morning than yesterday."}, {"id": "c", "text": "The discharge has changed from thick green to thin and scant."}, {"id": "d", "text": "His other eye is now pink with a small amount of discharge."}]'::jsonb, '["a"]', 'Photophobia (light sensitivity) and vision changes are reasons to refer or reevaluate right away. Less crusting and thinner discharge show improvement, and bacterial conjunctivitis can involve one or both eyes.', false),
  ('conjunctivitis', 13, 'The nurse is reviewing new prescriptions for four children with eye conditions on a pediatric unit. Which prescription should the nurse implement FIRST?', '[{"id": "a", "text": "Olopatadine drops for a child with itchy eyes and seasonal allergies"}, {"id": "b", "text": "Cool compresses for a child with watery discharge after a cold"}, {"id": "c", "text": "Polymyxin B/trimethoprim drops for a child with crusty eyelids"}, {"id": "d", "text": "An antiviral for a child with suspected herpes simplex virus"}]'::jsonb, '["d"]', 'Suspected herpes simplex virus needs an antiviral immediately. Olopatadine, cool compresses and polymyxin B/trimethoprim are appropriate for allergic, viral and bacterial conjunctivitis, but none carries the same urgency.', false),
  ('conjunctivitis', 14, 'At a pool party, an 8-year-old develops burning, watery, irritated eyes shortly after swimming in a heavily chlorinated pool. There is no itching and no pus. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Instill an antihistamine drop such as olopatadine."}, {"id": "b", "text": "Irrigate the eyes with saline and avoid further exposure."}, {"id": "c", "text": "Apply antibiotic ointment into the conjunctival sac."}, {"id": "d", "text": "Send the child home until the discharge has resolved."}]'::jsonb, '["b"]', 'Watery, burning eyes after recent chlorine exposure suggest chemical/irritant conjunctivitis, treated with saline irrigation and avoiding exposure. It is not contagious, so sending the child home is unnecessary, and antibiotics or antihistamines do not remove the irritant.', false),
  ('conjunctivitis', 15, 'A 5-year-old is brought to the clinic with red eyes. Which assessment findings would lead the nurse to suspect a viral cause? Select all that apply.', '[{"id": "a", "text": "Watery or mucous discharge"}, {"id": "b", "text": "Crusty eyelids especially in the morning"}, {"id": "c", "text": "Symptoms that began after a cold"}, {"id": "d", "text": "Clear, stringy mucus with itching and sneezing"}, {"id": "e", "text": "A red eye with a gritty feeling"}]'::jsonb, '["a", "c", "e"]', 'Viral conjunctivitis has watery or mucous discharge, red and gritty eyes, and often follows a cold. Crusty eyelids especially in the morning indicate bacterial conjunctivitis, and clear, stringy mucus with itching and sneezing indicates allergic conjunctivitis.', true),
  ('conjunctivitis', 16, 'A 10-year-old has redness in both eyes with itching, clear, stringy mucus, sneezing, and a runny nose every spring. Which treatment plan does the nurse anticipate as MOST appropriate?', '[{"id": "a", "text": "Antibiotic eye drops and staying home from school for a full 24 hours"}, {"id": "b", "text": "Cool compresses and artificial tears, with no medicated drops"}, {"id": "c", "text": "Antihistamine drops such as olopatadine plus removing the allergen"}, {"id": "d", "text": "Saline irrigation followed by an antiviral eye medication"}]'::jsonb, '["c"]', 'Itching in both eyes with clear, stringy mucus and seasonal sneezing is allergic conjunctivitis, treated with antihistamine or mast cell stabilizer drops such as olopatadine and removal of the allergen. Allergic conjunctivitis is not contagious, so antibiotics and school exclusion are not indicated.', false),
  ('conjunctivitis', 17, 'Two toddlers in the same daycare classroom develop red eyes with thick green discharge. The director asks the nurse how to prevent further spread. Which measure should the nurse identify as MOST important?', '[{"id": "a", "text": "Frequent hand hygiene by staff and children"}, {"id": "b", "text": "Separate towels and washcloths for each child"}, {"id": "c", "text": "Cleaning eyes with warm water and a cotton ball"}, {"id": "d", "text": "Erythromycin ointment for each exposed child"}]'::jsonb, '["a"]', 'Hand hygiene is the most important prevention for contagious conjunctivitis. Separate towels help but are secondary, and erythromycin ointment is newborn prophylaxis given at birth, not prevention for exposed toddlers.', false),
  ('conjunctivitis', 18, 'The nurse watches the parent of a 3-year-old with crusted eyelids clean the child''s eyes before instilling drops. Which action by the parent indicates a need for further teaching?', '[{"id": "a", "text": "Moistens the cotton ball with warm water first"}, {"id": "b", "text": "Uses one cotton ball for more than one swipe across the eye"}, {"id": "c", "text": "Cleans the eye gently using warm water"}, {"id": "d", "text": "Uses a washcloth kept separate for the infected child"}]'::jsonb, '["b"]', 'The eye is cleaned gently with warm water and a cotton ball using one wipe per swipe, so reusing the same cotton ball for several swipes needs correction. Warm water and a separate washcloth for the infected child are correct.', false),
  ('conjunctivitis', 19, 'The nurse takes histories from the parents of five children with red, irritated eyes. Which histories suggest a cause that is NOT contagious? Select all that apply.', '[{"id": "a", "text": "Recovered from a cold with a cough last week"}, {"id": "b", "text": "Recent exposure to chlorine in a pool this morning"}, {"id": "c", "text": "Sister has thick green pus and crusty eyelids"}, {"id": "d", "text": "Born 6 days ago and now has eye discharge"}, {"id": "e", "text": "Seasonal allergies with symptoms when pollen is high"}]'::jsonb, '["b", "e"]', 'Chlorine in pools causes chemical/irritant conjunctivitis and pollen or seasonal allergies cause allergic conjunctivitis; neither is contagious. Symptoms after a cold suggest viral (adenovirus) conjunctivitis, a sister with thick green pus suggests bacterial spread, and discharge in a 6-day-old suggests neonatal infection such as Chlamydia — all infectious causes.', true),
  ('conjunctivitis', 20, 'The nurse observes a parent instill prescribed antibiotic eye drops for a 7-year-old with bacterial conjunctivitis. Which observation BEST indicates correct technique?', '[{"id": "a", "text": "Places the drop directly onto the center of the eye"}, {"id": "b", "text": "Gives the ointment first and the drops right after"}, {"id": "c", "text": "Wipes the eye back and forth with one cotton ball first"}, {"id": "d", "text": "Places each drop into the child''s conjunctival sac"}]'::jsonb, '["d"]', 'Eye drops and ointment are applied to the conjunctival sac, not directly on the eye. Drops are given before ointment with a 5–10 minute wait, and the eye is cleaned with one wipe per swipe of the cotton ball.', false),
  ('conjunctivitis', 21, 'A mother in labor asks why her newborn will receive eye ointment shortly after birth even though the baby''s eyes will look normal. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "It helps prevent a newborn eye infection that can cause blindness."}, {"id": "b", "text": "It treats viral pink eye that is passed on during the birth."}, {"id": "c", "text": "It is an antihistamine that prevents itching and tearing."}, {"id": "d", "text": "It is used only if eye discharge appears in the first 30 days."}]'::jsonb, '["a"]', 'Neonatal conjunctivitis is prevented with prophylactic erythromycin ointment at birth; Neisseria gonorrhoeae infection can cause blindness. The ointment is prophylaxis given at birth, not treatment reserved for later discharge.', false),
  ('conjunctivitis', 22, 'A nurse in a pediatric urgent care center triages five children with eye discharge. Which children''s findings should the nurse treat as an emergency requiring immediate referral? Select all that apply.', '[{"id": "a", "text": "A 3-day-old with thick discharge from both eyes"}, {"id": "b", "text": "A 12-day-old with new eye discharge"}, {"id": "c", "text": "A 3-year-old with watery eyes after a cold"}, {"id": "d", "text": "A 25-day-old with new eye discharge"}, {"id": "e", "text": "A 4-year-old with itchy eyes every spring"}]'::jsonb, '["a", "b", "d"]', 'Neonatal conjunctivitis occurs in the first 30 days of life and is an emergency: the 3-day-old fits Neisseria gonorrhoeae, the 12-day-old fits Chlamydia trachomatis, and the 25-day-old is still within 30 days, so all are referred immediately. Watery eyes after a cold (viral) and itchy eyes every spring (allergic) in older children are not neonatal emergencies.', true),
  ('conjunctivitis', 23, 'A 9-year-old has itching in both eyes with clear, stringy mucus and sneezing whenever the family''s cat is nearby. The parent asks whether the child must stay home from school. Which response by the nurse is BEST?', '[{"id": "a", "text": "Stay home until the discharge has completely resolved."}, {"id": "b", "text": "Stay home until 24 hours after starting antibiotic drops."}, {"id": "c", "text": "School is fine; this type of pink eye is not contagious."}, {"id": "d", "text": "Stay home until the itching has stopped for a full day."}]'::jsonb, '["c"]', 'Itching in both eyes with clear, stringy mucus triggered by pet dander is allergic conjunctivitis, which is not contagious. Staying home applies to viral and bacterial types, and the 24-hour antibiotic rule applies only to bacterial conjunctivitis.', false),
  ('conjunctivitis', 24, 'A 6-year-old with bacterial conjunctivitis shares a bedroom with a 4-year-old sibling. The parent asks how to protect the sibling. In addition to hand hygiene, which instruction is MOST important to include?', '[{"id": "a", "text": "Share the eye drops with the sibling if the sibling''s eyes turn red."}, {"id": "b", "text": "Do not let the children share towels, pillows, or eye drops."}, {"id": "c", "text": "Apply cool compresses to the sibling''s eyes each night."}, {"id": "d", "text": "Keep the sibling home from school until the discharge resolves."}]'::jsonb, '["b"]', 'Bacterial conjunctivitis is highly contagious, so towels, pillows and eye drops are not shared. Keeping a well sibling home is not indicated, and cool compresses are supportive care for viral conjunctivitis, not prevention.', false),
  ('conjunctivitis', 25, 'A 5-year-old has thick yellow discharge in one eye and eyelids that are crusted shut each morning. Which medications should the nurse anticipate the provider may prescribe? Select all that apply.', '[{"id": "a", "text": "Olopatadine drops"}, {"id": "b", "text": "Erythromycin ointment"}, {"id": "c", "text": "Artificial tears alone"}, {"id": "d", "text": "Polymyxin B/trimethoprim drops"}, {"id": "e", "text": "An antiviral medication"}]'::jsonb, '["b", "d"]', 'Thick yellow pus with crusty eyelids is bacterial conjunctivitis, treated with antibiotic eye drops or ointment such as erythromycin or polymyxin B/trimethoprim. Olopatadine treats allergic conjunctivitis, artificial tears are supportive care for viral conjunctivitis, and an antiviral is for suspected herpes simplex virus.', true),
  ('conjunctivitis', 26, 'A 6-year-old developed red, watery eyes with a gritty feeling 3 days after the start of a cold. Which organism does the nurse recognize as the MOST likely cause?', '[{"id": "a", "text": "Staph"}, {"id": "b", "text": "Adenovirus"}, {"id": "c", "text": "Chlamydia"}, {"id": "d", "text": "Neisseria gonorrhoeae"}]'::jsonb, '["b"]', 'Viral conjunctivitis is usually caused by adenovirus and often follows a cold or respiratory illness. Staph is a bacterial cause that produces thick pus, and Chlamydia and Neisseria gonorrhoeae are causes in newborns.', false),
  ('conjunctivitis', 27, 'A 9-year-old has redness in both eyes every April along with sneezing and a runny nose. Which additional finding would the nurse MOST expect?', '[{"id": "a", "text": "Thick green pus with eyelids crusted in the morning"}, {"id": "b", "text": "Burning eyes after recent exposure to smoke"}, {"id": "c", "text": "A swollen lymph node in front of the ear"}, {"id": "d", "text": "Itching with clear, stringy mucus"}]'::jsonb, '["d"]', 'Seasonal redness in both eyes with sneezing or runny nose is allergic conjunctivitis, which causes itching and clear, stringy mucus. Preauricular lymph node swelling is a viral feature, and morning crusting with green pus is bacterial.', false),
  ('conjunctivitis', 28, 'The nurse prepares home-care teaching for the parent of a 4-year-old with watery eye discharge that began 2 days after a cold. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Apply cool compresses to the eyes."}, {"id": "b", "text": "Use artificial tears for comfort."}, {"id": "c", "text": "Start antibiotic eye drops before daycare."}, {"id": "d", "text": "Keep the child home until discharge resolves."}, {"id": "e", "text": "Use separate towels and washcloths for the child."}]'::jsonb, '["a", "b", "d", "e"]', 'Watery discharge after a cold is viral conjunctivitis: supportive care is cool compresses and artificial tears, the child stays home until discharge resolves, and separate towels and washcloths limit spread. Antibiotics are not given for viral pink eye.', true),
  ('conjunctivitis', 29, 'A 4-year-old got shampoo in both eyes during a bath and now has watery, burning, irritated eyes with no pus. The parent calls asking whether the child needs antibiotic drops. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "Begin antibiotic drops and keep the child home for 24 hours."}, {"id": "b", "text": "Start olopatadine drops and remove the allergen from the home."}, {"id": "c", "text": "Irrigate the eyes with saline and avoid further exposure."}, {"id": "d", "text": "Apply erythromycin ointment into both eyes at bedtime."}]'::jsonb, '["c"]', 'Watery, burning eyes after recent shampoo exposure suggest chemical/irritant conjunctivitis, treated with saline irrigation and avoiding exposure. It is not bacterial, so antibiotics are not needed, and olopatadine treats allergic conjunctivitis.', false),
  ('conjunctivitis', 30, 'A 16-year-old who wears contact lenses has used antibiotic eye drops for bacterial conjunctivitis for 3 days, and the discharge has resolved. The teen asks about the lenses worn when symptoms began. Which response by the nurse is BEST?', '[{"id": "a", "text": "Clean those lenses well and start wearing them again tomorrow."}, {"id": "b", "text": "Wear those lenses only at school until the drops are finished."}, {"id": "c", "text": "Put the drops directly onto the lenses before inserting them."}, {"id": "d", "text": "Dispose of the contact lenses you used during the infection."}]'::jsonb, '["d"]', 'Eye makeup or contact lenses used during the infection are disposed of. Cleaning and reusing them risks reinfection, and drops are applied to the conjunctival sac, not onto lenses or directly on the eye.', false),
  ('conjunctivitis', 31, 'Eye culture results return for five children seen in clinic for red eyes. Which results indicate the child should receive antibiotic eye drops or ointment? Select all that apply.', '[{"id": "a", "text": "Staph"}, {"id": "b", "text": "Adenovirus"}, {"id": "c", "text": "Haemophilus influenzae"}, {"id": "d", "text": "Strep"}, {"id": "e", "text": "No organism; symptoms follow pet dander exposure"}]'::jsonb, '["a", "c", "d"]', 'Staph, Strep and Haemophilus influenzae cause bacterial conjunctivitis, which is treated with antibiotic eye drops or ointment. Adenovirus causes viral conjunctivitis, which receives no antibiotics, and pet dander causes allergic conjunctivitis.', true),
  ('conjunctivitis', 32, 'A 7-year-old has used antibiotic eye drops for bacterial conjunctivitis for 3 days. The parent reports the thick yellow discharge and morning crusting are unchanged. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Arrange reevaluation by the provider."}, {"id": "b", "text": "Continue the drops and recheck in a week."}, {"id": "c", "text": "Switch to cool compresses and artificial tears."}, {"id": "d", "text": "Add olopatadine drops to the current drops."}]'::jsonb, '["a"]', 'No improvement after 2–3 days of treatment is a reason to refer or reevaluate. Waiting another week delays care, and cool compresses and olopatadine treat viral and allergic conjunctivitis rather than bacterial infection.', false),
  ('conjunctivitis', 33, 'The nurse teaches the parent of an 11-year-old whose red, itchy eyes with clear, stringy mucus flare each pollen season. Which statements by the parent indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"She can keep going to school because this is not contagious.\""}, {"id": "b", "text": "\"The olopatadine drops will help control the itching.\""}, {"id": "c", "text": "\"We will remove the allergen, such as pollen, as much as we can.\""}, {"id": "d", "text": "\"She needs antibiotic drops for 24 hours before going back to school.\""}, {"id": "e", "text": "\"Both eyes are often affected with this type.\""}]'::jsonb, '["a", "b", "c", "e"]', 'Allergic conjunctivitis is not contagious, so school attendance continues; it is treated with antihistamine or mast cell stabilizer drops such as olopatadine plus removing the allergen; and it typically affects both eyes. The 24-hour antibiotic rule applies to bacterial conjunctivitis only.', true),
  ('conjunctivitis', 34, 'A 4-year-old with bacterial conjunctivitis on day 1 of antibiotic drops now has redness and discharge in the second eye. The parent fears the drops are failing. Which response by the nurse is BEST?', '[{"id": "a", "text": "Stop the drops and start cool compresses instead."}, {"id": "b", "text": "Go to the emergency department for systemic antibiotics."}, {"id": "c", "text": "Switch to olopatadine drops for the second eye."}, {"id": "d", "text": "Continue the drops; call if no improvement in 2–3 days."}]'::jsonb, '["d"]', 'Bacterial conjunctivitis can involve one or both eyes, and reevaluation is needed when there is no improvement after 2–3 days of treatment. Systemic antibiotics and urgent evaluation are required for neonatal conjunctivitis, not for this child.', false),
  ('conjunctivitis', 35, 'A nurse is administering both antibiotic eye drops and antibiotic eye ointment to a 3-year-old with bacterial conjunctivitis. Which actions by the nurse are correct? Select all that apply.', '[{"id": "a", "text": "Applies the medication to the conjunctival sac"}, {"id": "b", "text": "Places the ointment directly on the surface of the eye"}, {"id": "c", "text": "Instills the drops before the ointment"}, {"id": "d", "text": "Applies the ointment, then waits 5–10 minutes for the drops"}, {"id": "e", "text": "Wipes both eyes with one cotton ball before instilling"}]'::jsonb, '["a", "c"]', 'Medication is applied to the conjunctival sac, and drops are given first with a 5–10 minute wait before the ointment. Placing ointment directly on the eye is incorrect, giving the ointment first reverses the order, and the cotton ball is used for one wipe per swipe.', true),
  ('conjunctivitis', 36, 'The nurse reviews five children''s charts during a busy clinic morning. Which findings point to a bacterial cause of the child''s conjunctivitis? Select all that apply.', '[{"id": "a", "text": "Watery discharge that started after a cold"}, {"id": "b", "text": "Thick yellow or green pus"}, {"id": "c", "text": "Clear, stringy mucus with sneezing"}, {"id": "d", "text": "Burning after recent smoke exposure"}, {"id": "e", "text": "Crusty eyelids especially in the morning"}]'::jsonb, '["b", "e"]', 'Bacterial conjunctivitis produces thick yellow or green pus and crusty eyelids especially in the morning. Watery discharge after a cold is viral, clear stringy mucus with sneezing is allergic, and burning after smoke exposure is chemical/irritant.', true),
  ('conjunctivitis', 37, 'A 3-day-old has copious purulent discharge from both eyes, and the provider suspects Neisseria gonorrhoeae. Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Notify the provider immediately"}, {"id": "b", "text": "Prepare to give systemic antibiotics"}, {"id": "c", "text": "Teach the parents that this infection can cause blindness"}, {"id": "d", "text": "Perform hand hygiene before and after eye care"}, {"id": "e", "text": "Observe for 2–3 days to see if the discharge resolves"}]'::jsonb, '["a", "b", "c", "d"]', 'Neonatal gonococcal conjunctivitis is an emergency that can cause blindness, so it requires immediate provider communication, urgent evaluation and systemic antibiotics, and hand hygiene prevents spread. Waiting 2–3 days applies to judging response to treatment in older children, not to an untreated newborn emergency.', true),
  ('conjunctivitis', 38, 'A 12-year-old''s eye is red and painful, and the provider suspects herpes simplex virus. The parent asks to try leftover antibiotic drops for a few days before starting anything new. Which response by the nurse is BEST?', '[{"id": "a", "text": "Try the antibiotic drops and return if no improvement in 2–3 days."}, {"id": "b", "text": "This needs an antiviral right away, not antibiotic drops."}, {"id": "c", "text": "Use cool compresses and artificial tears for a few days first."}, {"id": "d", "text": "Use olopatadine drops first to see if the redness settles."}]'::jsonb, '["b"]', 'Suspected herpes simplex virus needs an antiviral immediately. The 2–3 day reevaluation window applies to conjunctivitis already on the correct treatment, and antibiotics, compresses or olopatadine do not treat herpes simplex virus.', false),
  ('conjunctivitis', 39, 'The nurse reviews new prescriptions for five children with conjunctivitis. Which prescriptions require follow-up with the provider before the nurse implements them? Select all that apply.', '[{"id": "a", "text": "Antibiotic eye drops for watery eyes that began after a cold"}, {"id": "b", "text": "Olopatadine drops for itchy eyes with clear, stringy mucus"}, {"id": "c", "text": "Erythromycin ointment for thick yellow pus and crusted eyelids"}, {"id": "d", "text": "Topical drops only for a 4-day-old with thick eye discharge"}, {"id": "e", "text": "Saline irrigation for burning eyes after a chlorinated pool"}]'::jsonb, '["a", "d"]', 'Antibiotics are not given for viral pink eye, which often follows a cold, and a 4-day-old with thick discharge needs urgent evaluation and systemic antibiotics, not topical drops alone. Olopatadine for allergic, erythromycin for bacterial, and saline irrigation for chemical conjunctivitis are all appropriate.', true),
  ('conjunctivitis', 40, 'A 9-year-old with allergic conjunctivitis from seasonal pollen develops thick yellow pus and eyelids crusted shut in the morning. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Increase the olopatadine drops and keep removing the allergen."}, {"id": "b", "text": "Apply cool compresses and artificial tears for comfort only."}, {"id": "c", "text": "Have the child seen by a provider for possible antibiotics."}, {"id": "d", "text": "Irrigate the eyes with saline to wash out the pollen."}]'::jsonb, '["c"]', 'The change to thick yellow pus with morning crusting signals bacterial conjunctivitis, so the child should see a provider for antibiotics. Olopatadine and allergen removal treat the allergic component only.', false),
  ('conjunctivitis', 41, 'A parent reports that an 8-year-old has had bacterial conjunctivitis for the fourth time this school year; the current episode is improving on day 2 of antibiotic drops. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Recommend reevaluation because of the recurrent infections."}, {"id": "b", "text": "Tell the parent that repeated episodes are expected at school."}, {"id": "c", "text": "Plan to stop the drops once the crusting has lessened."}, {"id": "d", "text": "Suggest olopatadine drops to prevent the next episode."}]'::jsonb, '["a"]', 'Recurrent infections are a reason to refer or reevaluate, even when the current episode is improving. Olopatadine treats allergic conjunctivitis and would not prevent bacterial infection.', false),
  ('conjunctivitis', 42, 'The nurse teaches the parent of a 2-year-old how to clean and medicate the child''s crusted, draining eye at home. Which steps should the nurse include? Select all that apply.', '[{"id": "a", "text": "Use hand hygiene before and after eye care."}, {"id": "b", "text": "Clean the eye gently with warm water."}, {"id": "c", "text": "Use the sibling''s washcloth if it is clean."}, {"id": "d", "text": "Use a new cotton ball for each swipe."}, {"id": "e", "text": "Apply ointment into the conjunctival sac."}]'::jsonb, '["a", "b", "d", "e"]', 'Hand hygiene is the most important prevention, the eye is cleaned gently with warm water and a cotton ball using one wipe per swipe, and ointment is applied to the conjunctival sac. The infected child uses separate towels and washcloths, so a sibling''s washcloth is not used.', true),
  ('conjunctivitis', 43, 'A school nurse is deciding which children with red eyes may stay in class today. Which child may remain in school?', '[{"id": "a", "text": "A child with bacterial conjunctivitis on antibiotics for 12 hours"}, {"id": "b", "text": "A child with watery discharge after a cold that has not resolved"}, {"id": "c", "text": "A child with thick green pus who has not yet seen a provider"}, {"id": "d", "text": "A child with itchy eyes and clear, stringy mucus during pollen season"}]'::jsonb, '["d"]', 'Itchy eyes with clear, stringy mucus during pollen season indicate allergic conjunctivitis, which is not contagious. Bacterial conjunctivitis requires 24 hours on antibiotics, and viral conjunctivitis requires the discharge to resolve.', false),
  ('conjunctivitis', 44, 'A 5-year-old with conjunctivitis that followed a cold complains of red, gritty, uncomfortable eyes. Which comfort measure should the nurse recommend FIRST?', '[{"id": "a", "text": "Cool compresses and artificial tears"}, {"id": "b", "text": "Leftover antibiotic eye ointment"}, {"id": "c", "text": "Olopatadine eye drops twice daily"}, {"id": "d", "text": "Saline irrigation of both eyes"}]'::jsonb, '["a"]', 'Conjunctivitis that follows a cold with red, gritty eyes is viral and is managed with supportive care: cool compresses and artificial tears. Antibiotics are not given for viral pink eye, and olopatadine and irrigation are for allergic and chemical types.', false),
  ('conjunctivitis', 45, 'A 7-year-old has burning, watery eyes after sitting near a smoky campfire. Which statement by the parent indicates understanding of the nurse''s teaching?', '[{"id": "a", "text": "\"He must stay home until he has had antibiotics for 24 hours.\""}, {"id": "b", "text": "\"His sister might catch this, so they cannot share pillows.\""}, {"id": "c", "text": "\"He needs olopatadine drops because this is an allergy.\""}, {"id": "d", "text": "\"This is from the smoke, so it is not contagious to others.\""}]'::jsonb, '["d"]', 'Burning, watery eyes after smoke exposure indicate chemical/irritant conjunctivitis, which is not contagious; treatment is saline irrigation and avoiding exposure. Antibiotics and school exclusion apply to bacterial conjunctivitis.', false),
  ('conjunctivitis', 46, 'Four children with red eyes are waiting in the clinic. Which child should the nurse see FIRST?', '[{"id": "a", "text": "A 10-year-old with severe eye pain and new vision changes"}, {"id": "b", "text": "A 6-year-old with crusty eyelids on day 1 of antibiotic drops"}, {"id": "c", "text": "An 8-year-old with watery eyes and a gritty feeling after a cold"}, {"id": "d", "text": "A 9-year-old with itchy eyes and clear mucus during allergy season"}]'::jsonb, '["a"]', 'Severe pain and vision changes are reasons to refer or reevaluate and take priority. Bacterial conjunctivitis on day 1 of antibiotics, viral conjunctivitis after a cold, and allergic conjunctivitis are expected presentations.', false),
  ('conjunctivitis', 47, 'A 15-year-old with bacterial conjunctivitis is improving on antibiotic drops and asks whether she can keep using the mascara she wore the day symptoms started. Which response by the nurse is BEST?', '[{"id": "a", "text": "Keep it, but do not share it with friends."}, {"id": "b", "text": "Throw it away, since it was used during infection."}, {"id": "c", "text": "Wipe the brush with warm water before reuse."}, {"id": "d", "text": "Keep it once you have had 24 hours of drops."}]'::jsonb, '["b"]', 'Eye makeup used during the infection is disposed of. Cleaning it or waiting 24 hours on antibiotics does not make reuse safe.', false),
  ('conjunctivitis', 48, 'A 6-year-old has red, watery eyes. Which question by the nurse during the history is MOST helpful in identifying a viral cause?', '[{"id": "a", "text": "Has your child been swimming in a pool or near smoke?"}, {"id": "b", "text": "Does your child''s eye itch along with sneezing in spring?"}, {"id": "c", "text": "Has your child recently had a cold or respiratory illness?"}, {"id": "d", "text": "Are the eyelids crusted shut when your child wakes up?"}]'::jsonb, '["c"]', 'Viral conjunctivitis is usually caused by adenovirus and often follows a cold or respiratory illness. Pool or smoke exposure points to an irritant, seasonal itching to allergy, and morning crusting to bacterial infection.', false),
  ('conjunctivitis', 49, 'The nurse supervises unlicensed assistive personnel (UAP) caring for two children with bacterial conjunctivitis in a shared room. Which action by the UAP requires IMMEDIATE intervention?', '[{"id": "a", "text": "Performs hand hygiene after removing the gloves"}, {"id": "b", "text": "Uses the same washcloth to clean both children''s eyes"}, {"id": "c", "text": "Gives each child a separate pillow and towel"}, {"id": "d", "text": "Discards a used cotton ball after a single swipe"}]'::jsonb, '["b"]', 'Separate towels and washcloths are used for each infected child, so sharing one washcloth spreads a highly contagious infection. Hand hygiene, separate pillows and towels, and one wipe per cotton ball are correct.', false),
  ('conjunctivitis', 50, 'A parent calls about a 3-week-old who developed eye redness and discharge this morning and plans to wait until the 1-month well visit. Which response by the nurse is BEST?', '[{"id": "a", "text": "Waiting is fine if you clean the eye with a cotton ball."}, {"id": "b", "text": "Waiting is fine if the discharge is clear and watery."}, {"id": "c", "text": "Use cool compresses and call if it lasts 2–3 days."}, {"id": "d", "text": "Bring the baby in now; newborn eye discharge is urgent."}]'::jsonb, '["d"]', 'Neonatal conjunctivitis occurs in the first 30 days of life and requires urgent evaluation, so newborn eye discharge is referred immediately. Home cleaning, waiting 2–3 days, or cool compresses delay care.', false),
  ('rop', 1, 'A NICU nurse is assigned four infants who are all receiving supplemental oxygen. Which infant is at HIGHEST risk for retinopathy of prematurity?', '[{"id": "a", "text": "Born at 33 weeks, 1,900 g, on nasal cannula for 2 days"}, {"id": "b", "text": "Born at 31 weeks, 1,600 g, on room air after 1 day of oxygen"}, {"id": "c", "text": "Born at 28 weeks, 980 g, on oxygen and a ventilator"}, {"id": "d", "text": "Born at 36 weeks, 2,400 g, on oxygen for transient tachypnea"}]'::jsonb, '["c"]', 'The younger the gestational age and the lower the birth weight, the greater the risk; this infant is under 31 weeks, under 1500 g, and receives oxygen and mechanical ventilation. The 31-week, 1,600-g infant does not meet either the <31 weeks or the <1500 g cut-off and is off oxygen.', false),
  ('rop', 2, 'A 29-week infant receiving blended oxygen in the NICU has a prescribed oxygen saturation target of 90–95%. Continuous pulse oximetry now reads 99%. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Document the reading as an expected finding for a preterm infant."}, {"id": "b", "text": "Increase the oxygen to keep the saturation near 100%."}, {"id": "c", "text": "Switch to unblended oxygen to give a more stable delivery."}, {"id": "d", "text": "Adjust the blended oxygen to reach the prescribed range."}]'::jsonb, '["d"]', 'A saturation of 99% is above the 90–95% target and represents hyperoxia, which damages fragile retinal vessels; the nurse keeps oxygen within the prescribed range using blended oxygen. Increasing oxygen or using unblended oxygen worsens hyperoxia.', false),
  ('rop', 3, 'The nurse reviews the history of a premature infant in the NICU. Which factors in the history increase the infant''s risk for retinopathy of prematurity? Select all that apply.', '[{"id": "a", "text": "Breastfeeding every 3 hours"}, {"id": "b", "text": "Birth at 27 weeks gestation"}, {"id": "c", "text": "Birth weight of 1,150 g"}, {"id": "d", "text": "Treatment for sepsis"}, {"id": "e", "text": "Episodes of apnea and bradycardia"}]'::jsonb, '["b", "c", "d", "e"]', 'Prematurity <31 weeks and birth weight <1500 g increase vulnerability, sepsis increases stress and inflammation, and apnea or bradycardia cause fluctuations in oxygenation. Feeding pattern is not listed among the risk factors.', true),
  ('rop', 4, 'The parent of a 5-week-old infant born at 27 weeks asks why an eye exam is scheduled when the baby''s eyes "look perfectly normal." Which response by the nurse is BEST?', '[{"id": "a", "text": "The exam is done only if the baby develops a white pupil reflex."}, {"id": "b", "text": "Early stages usually show no signs, so screening is needed."}, {"id": "c", "text": "The exam is needed because the baby''s eyes are already crossing."}, {"id": "d", "text": "The exam checks for allergies caused by the oxygen therapy."}]'::jsonb, '["b"]', 'ROP is usually asymptomatic in early stages, so routine screening is essential. Leukocoria and strabismus are late signs of advanced disease, and waiting for them misses the window for treatment.', false),
  ('rop', 5, 'An infant was born at 24 weeks gestation. Using the recommended timing, when should the nurse expect the FIRST retinopathy of prematurity eye exam to occur?', '[{"id": "a", "text": "At 31–33 weeks postmenstrual age"}, {"id": "b", "text": "At 4–6 weeks after birth"}, {"id": "c", "text": "At 32–40 weeks postmenstrual age"}, {"id": "d", "text": "Just before discharge home"}]'::jsonb, '["a"]', 'The first exam is at 4–6 weeks after birth or 31–33 weeks postmenstrual age, whichever is later. For a 24-week infant, 4–6 weeks after birth is only 28–30 weeks postmenstrual age, so 31–33 weeks postmenstrual age is later and determines timing. Weeks 32–40 describe when the retina normally finishes developing.', false),
  ('rop', 6, 'An infant born at 30 weeks gestation weighing 1,350 g is in the NICU. When should the nurse ensure the FIRST retinopathy of prematurity eye exam is scheduled?', '[{"id": "a", "text": "At 31–33 weeks postmenstrual age"}, {"id": "b", "text": "Only if the infant needs oxygen therapy"}, {"id": "c", "text": "At 4–6 weeks after birth"}, {"id": "d", "text": "At the first well-child visit after discharge"}]'::jsonb, '["c"]', 'The first exam occurs at 4–6 weeks after birth or 31–33 weeks postmenstrual age, whichever is later. For a 30-week infant, 4–6 weeks after birth equals 34–36 weeks postmenstrual age, which is later than 31–33 weeks. Gestation <31 weeks and weight <1500 g make the infant at risk regardless of oxygen use.', false),
  ('rop', 7, 'The nurse is caring for a 26-week infant on mechanical ventilation. Which nursing actions help reduce the infant''s risk for retinopathy of prematurity? Select all that apply.', '[{"id": "a", "text": "Keep oxygen saturation at 98–100% at all times"}, {"id": "b", "text": "Monitor pulse oximetry continuously"}, {"id": "c", "text": "Use blended oxygen rather than unblended oxygen"}, {"id": "d", "text": "Check oxygen saturation once every 4 hours"}, {"id": "e", "text": "Maintain saturation within the prescribed target range"}]'::jsonb, '["b", "c", "e"]', 'Continuous pulse oximetry, blended oxygen to avoid hyperoxia, and keeping saturation within the prescribed target range (typically 90–95%) protect the retina. A target of 98–100% invites hyperoxia, and checking every 4 hours misses fluctuations in oxygenation.', true),
  ('rop', 8, 'An ophthalmology report for a 7-week-old former 26-week infant reads: "thin demarcation line between normal and abnormal retina, both eyes; no plus disease." The parent asks whether surgery is needed. Which response by the nurse is BEST?', '[{"id": "a", "text": "Laser therapy is usually done right away to stop new vessels."}, {"id": "b", "text": "Many mild cases resolve, so follow-up exams are planned."}, {"id": "c", "text": "A scleral buckle is needed because the retina has detached."}, {"id": "d", "text": "This finding means the baby will have permanent blindness."}]'::jsonb, '["b"]', 'A thin demarcation line is Stage 1 (mild), and many mild Stage 1–2 cases resolve on their own with observation. Laser therapy treats abnormal vessel growth, and scleral buckle is for retinal detachment in Stages 4–5.', false),
  ('rop', 9, 'An eye exam on a former 25-week infant shows dilated, tortuous retinal vessels. The ophthalmologist''s note says "plus disease present." Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Schedule a routine repeat exam for the next month."}, {"id": "b", "text": "Reassure the parents that mild cases resolve alone."}, {"id": "c", "text": "Prepare the infant for urgent treatment."}, {"id": "d", "text": "Teach the parents to watch for a white pupil reflex."}]'::jsonb, '["c"]', 'Plus disease is a more aggressive form with vessel dilation and tortuosity that requires urgent treatment. Routine follow-up and reassurance fit mild Stage 1–2 disease, not plus disease.', false),
  ('rop', 10, 'A retinal exam on a premature infant documents a ridge at the junction between normal and abnormal retina with no new vessels and no detachment. How should the nurse interpret this finding?', '[{"id": "a", "text": "Stage 2, moderate disease"}, {"id": "b", "text": "Stage 1, mild disease"}, {"id": "c", "text": "Stage 3, severe disease"}, {"id": "d", "text": "Stage 4, partial detachment"}]'::jsonb, '["a"]', 'A ridge forming at the junction is Stage 2 (moderate). Stage 1 is only a thin demarcation line, and Stage 3 involves abnormal blood vessel growth (neovascularization).', false),
  ('rop', 11, 'The nurse reviews eye exam reports for five premature infants. Which findings indicate the infant needs treatment beyond observation? Select all that apply.', '[{"id": "a", "text": "Thin demarcation line with no plus disease"}, {"id": "b", "text": "Vessel dilation and tortuosity (plus disease)"}, {"id": "c", "text": "Ridge at the junction with no plus disease"}, {"id": "d", "text": "Partial retinal detachment"}, {"id": "e", "text": "Total retinal detachment"}]'::jsonb, '["b", "d", "e"]', 'Plus disease is an aggressive form requiring urgent treatment, and partial (Stage 4) and total (Stage 5) retinal detachment require surgical treatment such as scleral buckle or vitrectomy. A thin demarcation line (Stage 1) and a ridge (Stage 2) are mild-to-moderate stages in which many cases resolve on their own.', true),
  ('rop', 12, 'A 9-week-old former 27-week infant has partial retinal detachment in one eye. Which treatment should the nurse anticipate teaching the parents about?', '[{"id": "a", "text": "Observation, because many cases resolve on their own"}, {"id": "b", "text": "Blended oxygen to keep saturation at 90–95%"}, {"id": "c", "text": "Eye patching of the stronger eye"}, {"id": "d", "text": "Scleral buckle or vitrectomy surgery"}]'::jsonb, '["d"]', 'Partial retinal detachment is Stage 4, treated surgically with scleral buckle or vitrectomy. Observation is used for mild Stage 1–2 disease, and blended oxygen is a prevention measure, not treatment of detachment.', false),
  ('rop', 13, 'The parent of an infant scheduled for laser photocoagulation asks why the doctor would "burn part of the retina." Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "It destroys abnormal peripheral retina to stop new vessel growth."}, {"id": "b", "text": "It reattaches a retina that has already fully detached from the eye."}, {"id": "c", "text": "It speeds up normal retinal development so it finishes by 32 weeks."}, {"id": "d", "text": "It freezes the central retina so the vessels stop leaking blood."}]'::jsonb, '["a"]', 'Laser therapy (photocoagulation) destroys abnormal peripheral retina to stop new vessel growth and is the most common treatment. Reattaching a detached retina is done surgically by scleral buckle or vitrectomy, and freezing describes cryotherapy of the peripheral retina.', false),
  ('rop', 14, 'At a 6-month well visit, the nurse assesses an infant born at 26 weeks who missed outpatient eye follow-up. Which findings require IMMEDIATE referral to a pediatric ophthalmologist? Select all that apply.', '[{"id": "a", "text": "White pupil reflex (leukocoria)"}, {"id": "b", "text": "Strabismus (eyes not aligned)"}, {"id": "c", "text": "Poor visual tracking of faces"}, {"id": "d", "text": "Nystagmus (rhythmic eye movements)"}, {"id": "e", "text": "Steady gaze that follows a toy"}]'::jsonb, '["a", "b", "c", "d"]', 'Leukocoria, strabismus, absent or poor visual tracking, and nystagmus are signs of advanced ROP and need urgent ophthalmology evaluation. Following a toy with a steady gaze is normal visual tracking.', true),
  ('rop', 15, 'A newly hired NICU nurse is caring for a 28-week infant on oxygen. Which action by the new nurse requires IMMEDIATE intervention by the preceptor?', '[{"id": "a", "text": "Leaves continuous pulse oximetry in place during a feeding"}, {"id": "b", "text": "Gives high oxygen that is not blended during care"}, {"id": "c", "text": "Checks that the saturation target is 90–95%"}, {"id": "d", "text": "Reminds the parents about follow-up eye exams"}]'::jsonb, '["b"]', 'Blended oxygen is used to avoid hyperoxia, which harms immature retinal vessels, so giving high oxygen that is not blended must be corrected. Continuous pulse oximetry, a 90–95% target, and parent teaching about follow-up eye exams are correct.', false),
  ('rop', 16, 'A NICU nurse reviews four infants at discharge planning. For which infant is it MOST important to confirm that retinopathy of prematurity screening has been scheduled?', '[{"id": "a", "text": "38-week infant, 3,100 g, never needed oxygen"}, {"id": "b", "text": "35-week infant, 2,300 g, on room air since birth"}, {"id": "c", "text": "37-week infant, 2,900 g, treated for jaundice"}, {"id": "d", "text": "30-week infant, 1,400 g, who received oxygen"}]'::jsonb, '["d"]', 'Prematurity <31 weeks, birth weight <1500 g and oxygen therapy are risk factors, so screening must be scheduled for this at-risk infant. The other infants are near term, above 1500 g, and did not receive oxygen.', false),
  ('rop', 17, 'The nurse identifies which NICU infants require retinopathy of prematurity screening. Which infants meet the risk criteria? Select all that apply.', '[{"id": "a", "text": "Born at 29 weeks, 1,300 g"}, {"id": "b", "text": "Born at 35 weeks, 2,400 g, room air"}, {"id": "c", "text": "Born at 32 weeks, 1,400 g"}, {"id": "d", "text": "Born at 30 weeks, 1,700 g"}, {"id": "e", "text": "Born at 38 weeks, 3,200 g, room air"}]'::jsonb, '["a", "c", "d"]', 'Prematurity <31 weeks or birth weight <1500 g places an infant at risk: the 29-week, 1,300-g infant meets both, the 32-week, 1,400-g infant meets the weight criterion, and the 30-week, 1,700-g infant meets the gestational age criterion. The 35-week and 38-week infants exceed both thresholds and are on room air.', true),
  ('rop', 18, 'The parent of a 3-week-old born at 27 weeks asks how oxygen can harm the eyes. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "Oxygen makes the retina finish developing too early."}, {"id": "b", "text": "Oxygen causes an allergic reaction in the eye lining."}, {"id": "c", "text": "High oxygen makes fragile vessels grow abnormally."}, {"id": "d", "text": "Oxygen dries the cornea and leaves scars on its surface."}]'::jsonb, '["c"]', 'In premature infants retinal vessels are underdeveloped, and high oxygen levels, rapid changes in blood flow or stress cause the fragile vessels to grow abnormally, leak or bleed, and form scar tissue. The retina normally finishes developing at 32–40 weeks; oxygen does not speed this up.', false),
  ('rop', 19, 'The nurse explains to a parent what can happen when immature retinal vessels are exposed to high oxygen levels or rapid changes in blood flow. Which processes should the nurse include? Select all that apply.', '[{"id": "a", "text": "The retina matures ahead of schedule"}, {"id": "b", "text": "Vessels leak or bleed"}, {"id": "c", "text": "The lens becomes cloudy at birth"}, {"id": "d", "text": "Vessels constrict and stop growing"}, {"id": "e", "text": "Scar tissue pulls the retina away"}]'::jsonb, '["b", "e"]', 'Fragile vessels leak or bleed and form scar tissue that can pull the retina away (retinal detachment). The vessels grow abnormally rather than constricting and stopping, the retina does not mature early, and cataracts are a possible complication later in life, not an effect at birth.', true),
  ('rop', 20, 'A mother of a former 26-week infant being discharged from the NICU says, "Her eyes look fine, so we will skip the eye appointment next week." Which response by the nurse is BEST?', '[{"id": "a", "text": "That is reasonable once the oxygen has been stopped."}, {"id": "b", "text": "Early disease has no signs, so keeping the exam is vital."}, {"id": "c", "text": "You can wait until she is due for her first vaccines."}, {"id": "d", "text": "Watch for crossed eyes and come in only if you see it."}]'::jsonb, '["b"]', 'ROP is usually asymptomatic in early stages, and the nurse educates parents about the importance of follow-up eye exams. Waiting for strabismus means waiting for a late sign of advanced disease.', false),
  ('rop', 21, 'An ophthalmology note on a former 25-week infant reports abnormal blood vessels growing into the retina (neovascularization) without detachment. The parents ask about treatment. Which statement by the parents indicates understanding of anti-VEGF therapy?', '[{"id": "a", "text": "\"The injection reattaches the retina that has pulled away.\""}, {"id": "b", "text": "\"The injection inhibits abnormal blood vessel formation.\""}, {"id": "c", "text": "\"The injection freezes the peripheral retina.\""}, {"id": "d", "text": "\"The injection replaces the need for any future eye exams.\""}]'::jsonb, '["b"]', 'Anti-VEGF injections such as bevacizumab inhibit abnormal blood vessel formation, which fits Stage 3 neovascularization. Reattachment is surgical (scleral buckle or vitrectomy), freezing describes cryotherapy, and follow-up exams continue.', false),
  ('rop', 22, 'The provider documents that laser photocoagulation is not feasible for an infant with retinopathy of prematurity who needs peripheral retinal treatment. Which alternative procedure should the nurse anticipate?', '[{"id": "a", "text": "Scleral buckling"}, {"id": "b", "text": "Vitrectomy"}, {"id": "c", "text": "Observation only"}, {"id": "d", "text": "Cryotherapy"}]'::jsonb, '["d"]', 'Cryotherapy (freezing of peripheral retina) is used when laser is not feasible. Scleral buckling and vitrectomy are surgical treatments for retinal detachment, and observation is for mild stages.', false),
  ('rop', 23, 'Four premature infants in the NICU are all on oxygen. Which infant should the nurse assess FIRST for factors that worsen retinopathy of prematurity risk?', '[{"id": "a", "text": "A 27-week infant with repeated apnea and bradycardia this shift"}, {"id": "b", "text": "A 29-week infant with stable saturation of 92% all shift"}, {"id": "c", "text": "A 30-week infant feeding well with saturation of 94%"}, {"id": "d", "text": "A 28-week infant sleeping with saturation steady at 91%"}]'::jsonb, '["a"]', 'Apnea and bradycardia cause fluctuations in oxygenation, which stress fragile retinal vessels. The other infants have stable saturations within the typical 90–95% target range.', false),
  ('rop', 24, 'The parents of a 4-month-old former 25-week infant who had laser treatment for ROP ask about the future. Which long-term complications should the nurse teach them to watch for? Select all that apply.', '[{"id": "a", "text": "Hearing loss from the laser"}, {"id": "b", "text": "Allergic conjunctivitis"}, {"id": "c", "text": "Amblyopia (lazy eye)"}, {"id": "d", "text": "Myopia (nearsightedness)"}, {"id": "e", "text": "Glaucoma or cataracts later in life"}]'::jsonb, '["c", "d", "e"]', 'Complications of ROP include amblyopia, strabismus, myopia, and glaucoma or cataracts later in life, so the nurse stays aware of long-term visual complications. Hearing loss and allergic conjunctivitis are not complications of ROP.', true),
  ('rop', 25, 'A 34-week infant weighing 2,200 g needed oxygen for 6 hours after birth, while a 26-week infant weighing 820 g has required oxygen and mechanical ventilation for 3 weeks. The student nurse asks why the 26-week infant''s risk is greater. Which explanation is BEST?', '[{"id": "a", "text": "Longer oxygen use is the main risk; gestation adds little."}, {"id": "b", "text": "Mechanical ventilation is the main risk; weight adds little."}, {"id": "c", "text": "Younger gestational age and lower weight mean greater risk."}, {"id": "d", "text": "Infants over 2,000 g have retinas fully developed at birth."}]'::jsonb, '["c"]', 'The younger the gestational age and the lower the birth weight, the greater the risk, and prolonged oxygen and mechanical ventilation add to it. The retina normally finishes developing in the last weeks of gestation (32–40 weeks), so weight alone does not mean a fully developed retina.', false),
  ('rop', 26, 'A parent asks why the baby born at 37 weeks in the next NICU bay does not need ROP eye exams while their 27-week infant does. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "The retina finishes developing in the last weeks of gestation."}, {"id": "b", "text": "Babies born at 37 weeks do not receive oxygen therapy."}, {"id": "c", "text": "Eye exams are only needed when a baby has a white pupil reflex."}, {"id": "d", "text": "The retina is fully developed by 24 weeks gestation."}]'::jsonb, '["a"]', 'The retina normally finishes developing in the last weeks of gestation (32–40 weeks), so in premature infants retinal vessels are underdeveloped at birth. Leukocoria is a late sign; screening must not wait for it.', false),
  ('rop', 27, 'A parent asks who will examine the baby''s eyes for retinopathy of prematurity and how. Which statement by the parent indicates understanding of the nurse''s teaching?', '[{"id": "a", "text": "\"The NICU nurse will check her eyes with a penlight each shift.\""}, {"id": "b", "text": "\"Her pediatrician will check her red reflex at discharge.\""}, {"id": "c", "text": "\"A pediatric ophthalmologist will do a dilated eye exam.\""}, {"id": "d", "text": "\"An eye exam is only needed if she has a white pupil.\""}]'::jsonb, '["c"]', 'Diagnosis requires a dilated eye exam by a pediatric ophthalmologist, using ophthalmoscopy to visualize the retina. Early ROP is asymptomatic, so waiting for leukocoria or relying on a penlight check would miss disease.', false),
  ('rop', 28, 'The nurse reviews a 30-week infant''s oxygen saturation trends. Which readings require the nurse to adjust the blended oxygen per the prescribed target range of 90–95%? Select all that apply.', '[{"id": "a", "text": "92%"}, {"id": "b", "text": "98%"}, {"id": "c", "text": "94%"}, {"id": "d", "text": "100%"}, {"id": "e", "text": "91%"}]'::jsonb, '["b", "d"]', 'Readings of 98% and 100% are above the 90–95% target and represent hyperoxia, which is avoided to protect developing retinal vessels. Readings of 91%, 92% and 94% are within the prescribed target range.', true),
  ('rop', 29, 'A 7-month-old born at 25 weeks has a white pupil reflex in the right eye noted on a flash photograph. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Reassure the parent that early ROP is asymptomatic."}, {"id": "b", "text": "Recheck the eyes at the 9-month well visit."}, {"id": "c", "text": "Arrange urgent pediatric ophthalmology evaluation."}, {"id": "d", "text": "Teach the parent about blended oxygen use."}]'::jsonb, '["c"]', 'A white pupil reflex (leukocoria) is a late sign of advanced ROP and may signal retinal detachment, so urgent ophthalmology evaluation is the priority. Early disease is asymptomatic, but this child is showing a late sign.', false),
  ('rop', 30, 'The NICU nurse teaches the parents of a 28-week infant on oxygen about retinopathy of prematurity. Which statements by the parents indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"More oxygen is always safer for her eyes.\""}, {"id": "b", "text": "\"Keeping her oxygen in the prescribed range helps protect her eyes.\""}, {"id": "c", "text": "\"If her eyes look normal, she does not have ROP.\""}, {"id": "d", "text": "\"She will need follow-up eye exams after discharge.\""}, {"id": "e", "text": "\"Her eye exam can wait until she is off oxygen.\""}]'::jsonb, '["b", "d"]', 'Oxygen is kept within the prescribed saturation range to avoid hyperoxia, and parents are taught the importance of follow-up eye exams. Too much oxygen harms retinal vessels, early ROP is asymptomatic so normal-looking eyes do not rule it out, and screening is scheduled for all at-risk infants rather than delayed until oxygen stops.', true),
  ('rop', 31, 'An infant''s retinal exam report states "total retinal detachment, right eye." The parents ask what this means for vision in that eye. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "This is Stage 5, which leads to blindness in that eye."}, {"id": "b", "text": "This is Stage 1, which often resolves on its own."}, {"id": "c", "text": "This is Stage 2, which needs routine observation only."}, {"id": "d", "text": "This is Stage 3, in which vessels grow abnormally."}]'::jsonb, '["a"]', 'Total retinal detachment is Stage 5 and leads to blindness. Stage 1 is a thin demarcation line, Stage 2 a ridge, and Stage 3 neovascularization without detachment.', false),
  ('rop', 32, 'A NICU nurse notices that a 27-week infant''s saturation swings between 84% and 99% throughout the shift. Which statement BEST explains why this pattern concerns the nurse in relation to the eyes?', '[{"id": "a", "text": "Fluctuations in oxygenation stress fragile retinal vessels."}, {"id": "b", "text": "Low readings alone are harmful; high readings protect the retina."}, {"id": "c", "text": "Saturation changes only affect the lungs, not the retina."}, {"id": "d", "text": "The retina is fully formed by 27 weeks and is not at risk."}]'::jsonb, '["a"]', 'Fluctuations in oxygenation (as with apnea or bradycardia) and rapid changes in blood flow stress fragile retinal vessels, which then grow abnormally. High oxygen levels are also harmful, and the retina normally finishes developing at 32–40 weeks.', false),
  ('rop', 33, 'A 28-week infant on mechanical ventilation develops sepsis. The parent asks whether the infection affects the baby''s eyes. Which response by the nurse is BEST?', '[{"id": "a", "text": "Sepsis only affects the lungs and blood, not the eyes."}, {"id": "b", "text": "Sepsis increases stress and inflammation, raising ROP risk."}, {"id": "c", "text": "Sepsis lowers ROP risk because oxygen needs decrease."}, {"id": "d", "text": "Sepsis matters if the baby weighs over 1500 g."}]'::jsonb, '["b"]', 'Sepsis is a risk factor for ROP because it increases stress and inflammation; this infant also has prematurity and mechanical ventilation as risk factors. Weight under 1500 g increases, not decreases, vulnerability.', false),
  ('rop', 34, 'The nurse explains to a parent why a premature infant on a ventilator is at increased risk for retinopathy of prematurity. Which statement BEST reflects the reason?', '[{"id": "a", "text": "Mechanical ventilation can affect oxygen levels."}, {"id": "b", "text": "Mechanical ventilation dilates the retinal vessels directly."}, {"id": "c", "text": "Mechanical ventilation prevents routine eye screening."}, {"id": "d", "text": "Mechanical ventilation causes allergic eye reactions."}]'::jsonb, '["a"]', 'Mechanical ventilation is a risk factor because it can affect oxygen levels, and high or fluctuating oxygen damages fragile retinal vessels. Ventilation does not prevent screening, which is scheduled for all at-risk infants.', false),
  ('rop', 35, 'The nurse reviews eye exam reports with a parent. Which findings describe stages of retinopathy of prematurity in which the retina has NOT yet detached? Select all that apply.', '[{"id": "a", "text": "Partial retinal detachment"}, {"id": "b", "text": "Thin demarcation line between normal and abnormal retina"}, {"id": "c", "text": "Ridge forming at the junction"}, {"id": "d", "text": "Total retinal detachment"}, {"id": "e", "text": "Abnormal blood vessels growing (neovascularization)"}]'::jsonb, '["b", "c", "e"]', 'Stage 1 (thin demarcation line), Stage 2 (ridge at the junction) and Stage 3 (neovascularization) occur before detachment. Stage 4 is partial retinal detachment and Stage 5 is total retinal detachment leading to blindness.', true),
  ('rop', 36, 'A NICU uses a special camera to photograph the retina of infants during ROP screening. A parent asks the purpose of the pictures. Which response by the nurse is BEST?', '[{"id": "a", "text": "The pictures replace the dilated eye exam."}, {"id": "b", "text": "The pictures treat abnormal vessels with light."}, {"id": "c", "text": "The pictures help document the eye findings."}, {"id": "d", "text": "The pictures are taken only after detachment."}]'::jsonb, '["c"]', 'Ocular imaging (RetCam) is used in some NICUs to document findings; it does not replace the dilated eye exam by a pediatric ophthalmologist. Treatment of abnormal vessels is by laser photocoagulation, not photography.', false),
  ('rop', 37, 'A 26-week infant has Stage 3 ROP with plus disease. The parents ask which treatment is used MOST often to stop abnormal vessel growth. Which response by the nurse is BEST?', '[{"id": "a", "text": "Scleral buckling of the eye"}, {"id": "b", "text": "Laser photocoagulation"}, {"id": "c", "text": "Vitrectomy surgery"}, {"id": "d", "text": "Observation with repeat exams"}]'::jsonb, '["b"]', 'Laser photocoagulation destroys abnormal peripheral retinal vessels and is the most common treatment. Scleral buckling and vitrectomy treat retinal detachment (Stage 4–5), and observation is for mild stages, not plus disease.', false),
  ('rop', 38, 'The parent of a 2-week-old born at 30 weeks gestation is worried because no retinopathy of prematurity eye exam has been done yet. Which response by the nurse is BEST?', '[{"id": "a", "text": "The exam is overdue, so I will request it for today."}, {"id": "b", "text": "The exam is done once the baby reaches 40 weeks."}, {"id": "c", "text": "No exam is needed because she was born after 29 weeks."}, {"id": "d", "text": "Her first exam is due at 4–6 weeks after birth."}]'::jsonb, '["d"]', 'For a 30-week infant, 4–6 weeks after birth (34–36 weeks postmenstrual age) is later than 31–33 weeks postmenstrual age, so the first exam is due at 4–6 weeks after birth and is not yet overdue at 2 weeks. Birth before 31 weeks places the infant at risk.', false),
  ('rop', 39, 'The nurse plans care for a 27-week, 900-g infant receiving oxygen. Which actions are nursing responsibilities related to retinopathy of prematurity? Select all that apply.', '[{"id": "a", "text": "Delay screening until the infant is off oxygen"}, {"id": "b", "text": "Ensure screening is scheduled"}, {"id": "c", "text": "Perform laser photocoagulation if vessels grow"}, {"id": "d", "text": "Use blended oxygen"}, {"id": "e", "text": "Monitor pulse oximetry continuously"}]'::jsonb, '["b", "d", "e"]', 'Nurses ensure screening is scheduled for at-risk infants, use blended oxygen to avoid hyperoxia, and monitor pulse oximetry continuously. Screening timing follows age, not oxygen status, and laser photocoagulation is a treatment, not a nursing action.', true),
  ('rop', 40, 'A parent of a 2-year-old born at 26 weeks with a history of treated ROP asks whether the child still needs regular eye care. Which response by the nurse is BEST?', '[{"id": "a", "text": "No, treated ROP does not affect vision later in life."}, {"id": "b", "text": "When the child develops a white pupil reflex."}, {"id": "c", "text": "Yes, problems such as myopia and glaucoma can occur later."}, {"id": "d", "text": "Only until the child reaches 40 weeks corrected age."}]'::jsonb, '["c"]', 'Nurses are aware of long-term visual complications of ROP, including myopia, amblyopia, strabismus, and glaucoma or cataracts later in life. The 32–40 week figure refers to normal retinal development, not the end of eye follow-up.', false),
  ('rop', 41, 'A parent asks what can happen if ROP progresses without treatment. Which outcomes should the nurse include? Select all that apply.', '[{"id": "a", "text": "Faster retinal maturation"}, {"id": "b", "text": "Retinal detachment"}, {"id": "c", "text": "Permanent blindness"}, {"id": "d", "text": "Strabismus"}, {"id": "e", "text": "Amblyopia"}]'::jsonb, '["b", "c", "d", "e"]', 'Complications of ROP include retinal detachment, permanent blindness, strabismus and amblyopia. The disease does not speed retinal maturation; immature retinal vessels instead grow abnormally.', true),
  ('rop', 42, 'An infant born at 29 weeks weighs 1,450 g. A parent asks what the weight cut-off for ROP risk is in pounds. Which response by the nurse is BEST?', '[{"id": "a", "text": "Under 2.2 lbs; your baby is above it and not at risk."}, {"id": "b", "text": "Under 4.5 lbs; weight does not matter after 29 weeks."}, {"id": "c", "text": "Under 3.3 lbs (1500g); this weight is within the risk range."}, {"id": "d", "text": "Under 5.5 lbs; only weight, not gestation, is used."}]'::jsonb, '["c"]', 'Low birth weight <1500 g (3.3 lbs) increases vulnerability; 1,450 g is just under that cut-off, and 29 weeks is also under 31 weeks. Gestation and weight are both risk factors.', false),
  ('rop', 43, 'A 6-week-old former 26-week infant had a dilated eye exam showing Stage 2 ROP without plus disease. Which nursing action is MOST appropriate NEXT?', '[{"id": "a", "text": "Prepare the infant for scleral buckle surgery."}, {"id": "b", "text": "Prepare the infant for urgent laser therapy."}, {"id": "c", "text": "Cancel further exams since Stage 2 often resolves."}, {"id": "d", "text": "Ensure follow-up eye exams are scheduled."}]'::jsonb, '["d"]', 'Stage 1–2 disease is managed with observation because many mild cases resolve on their own, so follow-up exams must be ensured. Cancelling exams risks missing progression, and urgent treatment is reserved for plus disease.', false),
  ('rop', 44, 'A 5-month-old former 27-week infant who had ROP is brought to the clinic. Which findings during the eye assessment should the nurse report to the provider? Select all that apply.', '[{"id": "a", "text": "Strabismus noted in one eye"}, {"id": "b", "text": "Nystagmus noted in both eyes"}, {"id": "c", "text": "Pupils that both reflect red light"}, {"id": "d", "text": "Eyes that follow a moving face"}, {"id": "e", "text": "Blinks when a light is shone"}]'::jsonb, '["a", "b"]', 'Strabismus and nystagmus are signs of advanced ROP and are reported. Normal red reflexes, following a face and blinking to light do not indicate advanced ROP; absent or poor visual tracking would.', true),
  ('rop', 45, 'A 29-week infant on oxygen has a saturation of 93% on continuous pulse oximetry with a prescribed target of 90–95%. The parent asks for more oxygen "to be safe." Which response by the nurse is BEST?', '[{"id": "a", "text": "More oxygen is safer, so I will raise it to reach 100%."}, {"id": "b", "text": "Her level is in range; too much oxygen can harm her eyes."}, {"id": "c", "text": "Her level is low, so I will switch her to unblended oxygen."}, {"id": "d", "text": "Oxygen does not affect her eyes once screening is scheduled."}]'::jsonb, '["b"]', 'A saturation of 93% is within the 90–95% target range, and extra oxygen would risk hyperoxia, which damages fragile retinal vessels. Unblended oxygen is avoided, and oxygen management continues to matter regardless of screening.', false),
  ('rop', 46, 'The nurse reviews treatment options with the parents of infants at different ROP stages. Which matches of stage to treatment are correct? Select all that apply.', '[{"id": "a", "text": "Stage 1–2: observation"}, {"id": "b", "text": "Plus disease: routine follow-up only"}, {"id": "c", "text": "Stage 1: immediate vitrectomy"}, {"id": "d", "text": "Stage 3: total retinal detachment"}, {"id": "e", "text": "Laser not feasible: cryotherapy"}]'::jsonb, '["a", "e"]', 'Mild Stage 1–2 cases are observed because many resolve on their own, and cryotherapy is used when laser is not feasible. Plus disease needs urgent treatment, vitrectomy is for Stage 4–5 detachment rather than Stage 1, and Stage 3 is neovascularization, not detachment.', true),
  ('rop', 47, 'The nurse is teaching the parents of a 27-week infant receiving bevacizumab for ROP. Which statement by the parents indicates a need for further teaching?', '[{"id": "a", "text": "\"This medicine inhibits abnormal blood vessel formation.\""}, {"id": "b", "text": "\"She still needs follow-up eye exams after the injection.\""}, {"id": "c", "text": "\"This is one of the treatments for abnormal vessel growth.\""}, {"id": "d", "text": "\"This injection treats total retinal detachment.\""}]'::jsonb, '["d"]', 'Bevacizumab is an anti-VEGF injection that inhibits abnormal blood vessel formation; total retinal detachment (Stage 5) requires surgical treatment such as scleral buckle or vitrectomy. Follow-up eye exams remain important.', false),
  ('rop', 48, 'A charge nurse reviews four NICU infants on oxygen. Which infant''s situation requires IMMEDIATE intervention to reduce ROP risk?', '[{"id": "a", "text": "A 28-week infant with saturation 92% on blended oxygen"}, {"id": "b", "text": "A 30-week infant with saturation 99% on unblended oxygen"}, {"id": "c", "text": "A 29-week infant with saturation 94% on continuous oximetry"}, {"id": "d", "text": "A 27-week infant whose eye exam is scheduled at 31 weeks"}]'::jsonb, '["b"]', 'A saturation of 99% on unblended oxygen indicates hyperoxia, which must be corrected by using blended oxygen and returning saturation to the prescribed range. The other infants are within range or appropriately scheduled for screening.', false),
  ('rop', 49, 'The nurse teaches a group of NICU parents about ROP. Which statements by the parents indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"Babies born before 31 weeks are at risk.\""}, {"id": "b", "text": "\"Early ROP is usually seen as a white pupil.\""}, {"id": "c", "text": "\"Low birth weight under 1500g raises the risk.\""}, {"id": "d", "text": "\"Unregulated high oxygen raises the risk.\""}, {"id": "e", "text": "\"Sepsis can increase the risk.\""}]'::jsonb, '["a", "c", "d", "e"]', 'Prematurity <31 weeks, birth weight <1500 g, especially prolonged or unregulated high oxygen, and sepsis are risk factors. Early ROP is usually asymptomatic; leukocoria is a late sign.', true),
  ('rop', 50, 'A NICU infant born at 31 weeks weighing 1,250 g never required oxygen. A float nurse asks whether ROP screening is still needed. Which response by the charge nurse is BEST?', '[{"id": "a", "text": "No, screening is needed only for infants who received oxygen."}, {"id": "b", "text": "No, the infant was born at exactly 31 weeks and is not at risk."}, {"id": "c", "text": "Yes, but after a white pupil reflex is seen."}, {"id": "d", "text": "Yes, a weight under 1500 g alone places the infant at risk."}]'::jsonb, '["d"]', 'Low birth weight <1500 g is a risk factor on its own, so screening is ensured for this at-risk infant. Waiting for leukocoria would miss the asymptomatic early stages.', false),
  ('strabismus', 1, 'During a well-child visit, the nurse notes that a 3-year-old''s left eye turns inward in every photo the parent shows and throughout the exam, while the right eye focuses normally. How should the nurse MOST accurately document this finding?', '[{"id": "a", "text": "Intermittent esotropia of the left eye"}, {"id": "b", "text": "Constant hypotropia of the left eye"}, {"id": "c", "text": "Constant exotropia of the left eye"}, {"id": "d", "text": "Constant esotropia of the left eye"}]'::jsonb, '["d"]', 'An eye that turns inward is esotropia, and an eye that is always misaligned is constant strabismus. Intermittent strabismus is misalignment that happens only occasionally, and exotropia is an outward turn.', false),
  ('strabismus', 2, 'The parent of a 4-year-old reports that the child''s right eye drifts outward when the child is tired, but the eyes look straight the rest of the day. Which description of this finding is MOST accurate?', '[{"id": "a", "text": "Intermittent exotropia"}, {"id": "b", "text": "Intermittent esotropia"}, {"id": "c", "text": "Constant exotropia"}, {"id": "d", "text": "Intermittent hypertropia"}]'::jsonb, '["a"]', 'An eye that turns outward (wall-eyed) is exotropia, and misalignment that happens only occasionally is intermittent. Esotropia is an inward turn, and hypertropia is an upward turn.', false),
  ('strabismus', 3, 'A nurse is assessing a 4-year-old with newly diagnosed strabismus. Which findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "Frequent eye rubbing or blinking"}, {"id": "b", "text": "Eyes that do not move together"}, {"id": "c", "text": "Squinting or head tilting to see better"}, {"id": "d", "text": "Symmetric reflection on the corneal light reflex test"}, {"id": "e", "text": "Poor depth perception"}]'::jsonb, '["a", "b", "c", "e"]', 'Eyes that do not move together (b), squinting or head tilting to see better (c), poor depth perception (e), and frequent eye rubbing or blinking (a) are listed signs of strabismus. The corneal light reflex test checks symmetry of reflection, so a symmetric reflection (d) does not suggest misalignment.', true),
  ('strabismus', 4, 'A 12-year-old who developed strabismus after an injury complains of seeing two of everything, but the child''s 3-year-old sibling with long-standing strabismus has never reported this. The parent asks why. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "Double vision appears only after the eye has been patched."}, {"id": "b", "text": "The younger child has a milder form of it that does not affect vision."}, {"id": "c", "text": "The younger child''s brain ignores one image to prevent confusion."}, {"id": "d", "text": "The older child''s other eye has also started to turn inward."}]'::jsonb, '["c"]', 'When the eyes are misaligned, the brain receives two different images; older children and adults experience double vision (diplopia), whereas in young children the brain suppresses (ignores) one image to prevent confusion. The absence of complaints in the younger child does not mean vision is unaffected.', false),
  ('strabismus', 5, 'While screening a 3-year-old, the nurse shines a penlight toward both eyes. The reflection is centered in the right pupil but falls toward the outer edge of the left pupil. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Document the finding as normal for a 3-year-old"}, {"id": "b", "text": "Refer to an ophthalmologist for eye movement evaluation"}, {"id": "c", "text": "Teach the parent to patch the left eye each day"}, {"id": "d", "text": "Repeat the corneal light reflex test at age 7"}]'::jsonb, '["b"]', 'The corneal light reflex (Hirschberg) test shines light in the eyes to check symmetry of reflection; an asymmetric reflection suggests misalignment, so the child needs referral to an ophthalmologist for detailed eye movement evaluation. Patching before evaluation is premature, and waiting until age 7 delays treatment that should start as early as possible.', false),
  ('strabismus', 6, 'A 3-year-old is referred for suspected strabismus. Which components of the diagnostic evaluation should the nurse explain to the parent? Select all that apply.', '[{"id": "a", "text": "Cover-uncover test of each eye"}, {"id": "b", "text": "Botox injection to confirm which muscle is weak"}, {"id": "c", "text": "Visual acuity testing to compare the two eyes"}, {"id": "d", "text": "Referral to an ophthalmologist for eye movement evaluation"}, {"id": "e", "text": "Corneal light reflex test to check symmetry of reflection"}]'::jsonb, '["a", "c", "d", "e"]', 'Diagnosis includes the corneal light reflex (Hirschberg) test, which checks symmetry of reflection (e), the cover-uncover test (a), visual acuity testing for differences in vision between eyes (c), and referral to an ophthalmologist for detailed eye movement evaluation (d). Botox injection (b) is a treatment that temporarily paralyzes overactive muscles, not a diagnostic test.', true),
  ('strabismus', 7, 'A 4-year-old with an eye that intermittently drifts outward undergoes vision screening. Which screening result should the nurse report to the health care provider as MOST concerning for developing amblyopia?', '[{"id": "a", "text": "Eyes that appear straight during the visit"}, {"id": "b", "text": "Decreased vision in the drifting eye on acuity testing"}, {"id": "c", "text": "Equal vision in both eyes on acuity testing"}, {"id": "d", "text": "A symmetric corneal light reflex in both eyes"}]'::jsonb, '["b"]', 'Visual acuity testing checks for differences in vision between eyes, and amblyopia is decreased vision in the misaligned eye if untreated. Equal acuity and a symmetric light reflex are reassuring findings.', false),
  ('strabismus', 8, 'The parent of a 4-year-old with esotropia says, "His eye turns in, so why does he need a patch? A patch won''t straighten his eye." Which response by the nurse is BEST?', '[{"id": "a", "text": "The patch strengthens the muscle that turns the eye inward."}, {"id": "b", "text": "The patch rests the turned eye so it is ready when surgery can be done."}, {"id": "c", "text": "The patch is used only until he no longer has double vision."}, {"id": "d", "text": "The patch makes the weaker eye work, which helps prevent amblyopia."}]'::jsonb, '["d"]', 'Patching covers the stronger eye to stimulate the weaker one, and a goal of strabismus treatment is to prevent amblyopia. Patching the turned eye would not stimulate it, and young children usually suppress one image rather than report double vision.', false),
  ('strabismus', 9, 'A nurse reviews patching instructions with the parent of a 3-year-old with strabismus whose left eye turns outward. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "I''ll apply the patch to his left eye since it is weaker."}, {"id": "b", "text": "Covering his good eye makes his weaker eye do the work."}, {"id": "c", "text": "Wearing the patch as directed helps prevent amblyopia."}, {"id": "d", "text": "I''ll put the patch on his right eye, which is the stronger eye."}]'::jsonb, '["a"]', 'The patch is applied to the stronger eye to force the weaker eye to work, so patching the weaker left eye shows a need for further teaching. The other statements correctly describe covering the stronger eye and preventing amblyopia.', false),
  ('strabismus', 10, 'The nurse is reviewing strabismus treatments with a family. Which descriptions of treatment purpose are accurate? Select all that apply.', '[{"id": "a", "text": "Corrective lenses fix refractive errors that may cause strabismus"}, {"id": "b", "text": "Atropine drops permanently blur the good eye"}, {"id": "c", "text": "Botox injection temporarily paralyzes overactive muscles"}, {"id": "d", "text": "Patching covers the weaker eye to let it rest"}, {"id": "e", "text": "Surgery realigns the extraocular muscles"}]'::jsonb, '["a", "c", "e"]', 'Corrective lenses fix refractive errors such as farsightedness that may cause strabismus (a), Botox temporarily paralyzes overactive muscles in select cases (c), and surgery realigns extraocular muscles (e). Atropine blurs the good eye only temporarily (b), and patching covers the stronger eye, not the weaker one (d).', true),
  ('strabismus', 11, 'The ophthalmologist recommends eye alignment surgery for a 3-year-old with constant esotropia. The parent asks, "Can''t we wait until he''s 10 and can decide for himself?" Which response by the nurse is BEST?', '[{"id": "a", "text": "Waiting until 10 is fine because alignment surgery works the same at any age."}, {"id": "b", "text": "He can wait if he wears glasses, because glasses will realign his eye muscles."}, {"id": "c", "text": "Surgery is usually postponed until the eye muscles stop growing in adolescence."}, {"id": "d", "text": "Surgery is typically done around ages 2–5, and treatment should start before age 7."}]'::jsonb, '["d"]', 'Surgery to realign extraocular muscles is typically done around ages 2–5 if needed, and treatment should start as early as possible, ideally before age 7. Delaying to age 10 risks amblyopia and permanent vision loss in one eye.', false),
  ('strabismus', 12, 'The mother of a 2-year-old newly diagnosed with strabismus is tearful and says, "I must have done something wrong to cause this." Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "It most likely developed from letting him sit too close to the television."}, {"id": "b", "text": "Let''s focus on the treatment plan instead of how it started."}, {"id": "c", "text": "Strabismus is not caused by poor parenting, and it can be treated."}, {"id": "d", "text": "It developed because his eyes were not patched early enough."}]'::jsonb, '["c"]', 'Nurses should reassure parents that strabismus is not caused by poor parenting. Redirecting away from the mother''s feelings ignores her concern, and patching is a treatment, not something whose absence causes strabismus.', false),
  ('strabismus', 13, 'The parent of a 4-year-old scheduled for strabismus surgery says, "I''m terrified. Eye surgery on a child sounds so dangerous." Which response by the nurse is BEST?', '[{"id": "a", "text": "Eye alignment surgery is common and safe, and it realigns the eye muscles."}, {"id": "b", "text": "You''re right to worry; it is risky, so it is used only after all else fails."}, {"id": "c", "text": "The surgery is dangerous, but it is the only way to prevent amblyopia."}, {"id": "d", "text": "You could choose eye drops instead, since they permanently fix the eye."}]'::jsonb, '["a"]', 'Eye alignment surgery is common and safe, and it realigns the extraocular muscles. Atropine drops blur the good eye only temporarily and do not fix alignment, and patching and glasses also help prevent amblyopia, so surgery is not the only option.', false),
  ('strabismus', 14, 'A pediatric eye clinic nurse reviews four new referrals. Which child should the nurse schedule for evaluation FIRST?', '[{"id": "a", "text": "A 6-year-old with untreated eye misalignment"}, {"id": "b", "text": "A 4-year-old in glasses whose eyes have stayed aligned"}, {"id": "c", "text": "A 12-year-old with long-standing untreated eye misalignment"}, {"id": "d", "text": "A 9-year-old due for a routine check of stable eye alignment"}]'::jsonb, '["a"]', 'Treatment should start as early as possible, ideally before age 7, so the untreated 6-year-old, who is nearest the cutoff, is the priority to prevent amblyopia. The 12-year-old is untreated but past the window, and the other children are treated or stable.', false),
  ('strabismus', 15, 'The parent of a 5-year-old with untreated strabismus asks what could happen if the family does not follow through with treatment. Which outcomes should the nurse include? Select all that apply.', '[{"id": "a", "text": "Loss of depth perception"}, {"id": "b", "text": "Spontaneous realignment by age 7"}, {"id": "c", "text": "Permanent vision loss in one eye"}, {"id": "d", "text": "Self-esteem issues and teasing"}, {"id": "e", "text": "Amblyopia (lazy eye)"}]'::jsonb, '["a", "c", "d", "e"]', 'Complications of untreated strabismus include amblyopia (e), loss of depth perception (a), permanent vision loss in one eye (c), and psychosocial issues such as self-esteem and teasing (d). Strabismus does not resolve on its own (b); over time it leads to amblyopia if untreated, and treatment should start before age 7.', true),
  ('strabismus', 16, 'A nurse is taking a history from an 8-year-old being treated for exotropia. Which finding from the interview requires follow-up by the nurse?', '[{"id": "a", "text": "Wears glasses every day as prescribed by the doctor"}, {"id": "b", "text": "Patches the stronger eye after school each day"}, {"id": "c", "text": "Reports teasing about the eye and low self-esteem"}, {"id": "d", "text": "Keeps scheduled visits with the ophthalmologist"}]'::jsonb, '["c"]', 'Untreated strabismus can cause psychosocial issues such as low self-esteem and teasing, so reported teasing and low self-esteem require follow-up. Wearing glasses, patching the stronger eye, and keeping visits show adherence to treatment.', false),
  ('strabismus', 17, 'A 3-year-old with cerebral palsy develops an eye that turns inward. The parent asks whether the eye problem is related to the child''s other diagnosis. Which response by the nurse is BEST?', '[{"id": "a", "text": "No, strabismus is caused only by a direct injury to the eye itself."}, {"id": "b", "text": "No, it is caused by not wearing glasses early enough."}, {"id": "c", "text": "Yes, neurological conditions such as cerebral palsy can cause it."}, {"id": "d", "text": "Yes, cerebral palsy weakens the lens so the eye drifts."}]'::jsonb, '["c"]', 'Neurological conditions such as cerebral palsy or a brain tumor are listed causes of strabismus. Trauma is only one of several causes, and the problem involves the extraocular muscles, not the lens.', false),
  ('strabismus', 18, 'A 6-year-old who is being followed for a brain tumor arrives for a routine visit. The parent reports that over the past week the child''s right eye has begun to drift outward. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Schedule a vision screening at the next routine visit"}, {"id": "b", "text": "Teach the parent to patch the left eye for several hours"}, {"id": "c", "text": "Reassure the parent that wandering eyes are common in children"}, {"id": "d", "text": "Report the new misalignment for referral and evaluation"}]'::jsonb, '["d"]', 'Tumors or lesions affecting the brain or eye nerves can cause strabismus, so a new eye deviation in a child with a brain tumor must be reported to the health care provider. Patching or waiting delays evaluation of a possible change in the tumor.', false),
  ('strabismus', 19, 'A 4-year-old with severe farsightedness is diagnosed with esotropia. Which treatment should the nurse anticipate FIRST?', '[{"id": "a", "text": "Corrective lenses to fix the refractive error"}, {"id": "b", "text": "Surgery to realign the extraocular muscles"}, {"id": "c", "text": "Botox injection into the overactive eye muscle"}, {"id": "d", "text": "Eye patch over the eye that turns inward"}]'::jsonb, '["a"]', 'Uncorrected refractive error such as severe farsightedness can cause strabismus, and corrective lenses fix refractive errors that may cause strabismus. Botox is reserved for select cases, and the patch goes over the stronger eye, not the turned eye.', false),
  ('strabismus', 20, 'The nurse is reviewing the histories of several toddlers. Which findings place a child at risk for strabismus? Select all that apply.', '[{"id": "a", "text": "Caregiver with inconsistent parenting"}, {"id": "b", "text": "Brain tumor"}, {"id": "c", "text": "Severe uncorrected farsightedness"}, {"id": "d", "text": "A parent with strabismus"}, {"id": "e", "text": "Cerebral palsy"}]'::jsonb, '["b", "c", "d", "e"]', 'Causes of strabismus include uncorrected refractive error such as severe farsightedness (c), family history (d), and neurological conditions such as cerebral palsy or a brain tumor (b, e). Strabismus is not caused by poor parenting (a).', true),
  ('strabismus', 21, 'The parent of a healthy 3-year-old with no eye concerns asks whether the child needs an eye screening at today''s well-child visit. Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes, but only if a family member has had strabismus surgery."}, {"id": "b", "text": "No, screening is needed only if a parent notices an eye turn."}, {"id": "c", "text": "No, screening is usually delayed until about age 7 years."}, {"id": "d", "text": "Yes, early screening is encouraged in all children by age 3."}]'::jsonb, '["d"]', 'Nurses should encourage early screening in all children by age 3, not only those with visible signs or risk factors. Waiting until age 7 misses the window, because treatment should ideally start before age 7.', false),
  ('strabismus', 22, 'A 5-year-old with strabismus is scheduled to receive a Botox injection. The parent asks how the injection will help. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "It strengthens the weak eye muscle so the eye can turn."}, {"id": "b", "text": "It blurs the good eye so the weaker eye must work."}, {"id": "c", "text": "It temporarily paralyzes an overactive eye muscle."}, {"id": "d", "text": "It permanently relaxes all of the muscles of the eye."}]'::jsonb, '["c"]', 'Botox injection temporarily paralyzes overactive muscles in select cases of strabismus. Blurring the good eye describes atropine drops, and the effect of Botox is temporary, not permanent.', false),
  ('strabismus', 23, 'A 4-year-old is being treated for strabismus with glasses, patching, and planned surgery. Which outcomes indicate the treatment goals are being met? Select all that apply.', '[{"id": "a", "text": "The weaker eye is patched all day"}, {"id": "b", "text": "Binocular vision is restored"}, {"id": "c", "text": "Amblyopia does not develop"}, {"id": "d", "text": "The good eye stays permanently blurred"}, {"id": "e", "text": "Proper eye alignment is restored"}]'::jsonb, '["b", "c", "e"]', 'The goals of strabismus treatment are to restore proper eye alignment (e) and binocular vision (b) and to prevent amblyopia (c). The stronger eye, not the weaker eye, is patched (a), and atropine blurs the good eye only temporarily (d).', true),
  ('strabismus', 24, 'A 10-year-old with a new eye deviation says, "I keep seeing two of the board at school." The parent asks what is causing this. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "The brain is ignoring one image to prevent confusion."}, {"id": "b", "text": "The stronger eye is now weaker because of the eye turn."}, {"id": "c", "text": "The lens of one eye is clouding and scattering the light."}, {"id": "d", "text": "The brain receives two different images from the eyes."}]'::jsonb, '["d"]', 'When one or more extraocular muscles are weak or uncoordinated, the brain receives two different images, causing double vision (diplopia) in older children. Suppression of one image occurs in young children, not in this 10-year-old reporting diplopia.', false),
  ('strabismus', 25, 'The parent of a 2-year-old with an eye that wanders says, "He never complains about his vision, so his eyes must be working fine." Which response by the nurse is BEST?', '[{"id": "a", "text": "Young children usually report double vision, so his vision is likely fine."}, {"id": "b", "text": "His brain may be ignoring one image, which can lead to amblyopia."}, {"id": "c", "text": "Since he has no symptoms, screening can wait until he is 7."}, {"id": "d", "text": "A wandering eye in toddlers will straighten without treatment."}]'::jsonb, '["b"]', 'In young children the brain suppresses (ignores) one image to prevent confusion, so they may not complain, and over time this leads to amblyopia if untreated. Diplopia is reported by older children, and treatment should start early, ideally before age 7.', false),
  ('strabismus', 26, 'The nurse is teaching the parents of a 3-year-old newly diagnosed with strabismus. Which points should the nurse include? Select all that apply.', '[{"id": "a", "text": "The eye usually corrects itself if patching is skipped"}, {"id": "b", "text": "Start treatment as early as possible, ideally before age 7"}, {"id": "c", "text": "Eye alignment surgery is risky and rarely done"}, {"id": "d", "text": "Compliance with patching is important"}, {"id": "e", "text": "Watch for signs of amblyopia and vision loss"}]'::jsonb, '["b", "d", "e"]', 'Teaching points include starting treatment as early as possible, ideally before age 7 (b), the importance of compliance with patching (d), and monitoring for signs of amblyopia and vision loss (e). Eye alignment surgery is common and safe (c), and untreated strabismus leads to amblyopia rather than correcting itself (a).', true),
  ('strabismus', 27, 'At a follow-up visit, a 5-year-old with strabismus is found to have a new decrease in vision in the misaligned eye on visual acuity testing. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The stronger eye is now the eye that needs the patch."}, {"id": "b", "text": "The child now has double vision from suppression."}, {"id": "c", "text": "This is an expected effect of patching the stronger eye daily."}, {"id": "d", "text": "The child is developing amblyopia in the misaligned eye."}]'::jsonb, '["d"]', 'Amblyopia is decreased vision in the misaligned eye if strabismus is untreated, and nurses should monitor for signs of amblyopia and vision loss. Suppression is the brain ignoring one image, not double vision.', false),
  ('strabismus', 28, 'A nurse reviews a type-of-deviation chart with a nursing student. Which pairings of strabismus type and eye deviation are correct? Select all that apply.', '[{"id": "a", "text": "Hypertropia — eye turns downward"}, {"id": "b", "text": "Esotropia — eye turns inward"}, {"id": "c", "text": "Constant — misalignment happens occasionally"}, {"id": "d", "text": "Exotropia — eye turns outward"}, {"id": "e", "text": "Hypotropia — eye turns downward"}]'::jsonb, '["b", "d", "e"]', 'Esotropia is an inward turn (b), exotropia is an outward turn (d), and hypotropia is a downward turn (e). Hypertropia is an upward turn (a), and constant strabismus means the eye is always misaligned, whereas intermittent means it happens occasionally (c).', true),
  ('strabismus', 29, 'A 3-year-old with esotropia has been wearing an eye patch. The parent says, "He''s having surgery next month to straighten his eye, so the patch doesn''t matter anymore." Which response by the nurse is BEST?', '[{"id": "a", "text": "You''re right; surgery corrects both the eye turn and any vision loss."}, {"id": "b", "text": "Compliance with patching still matters to prevent amblyopia."}, {"id": "c", "text": "You can stop the patch now and restart it only after the surgery."}, {"id": "d", "text": "Switch the patch to the turned eye so it can rest before the surgery."}]'::jsonb, '["b"]', 'Surgery realigns the extraocular muscles, but patching covers the stronger eye to stimulate the weaker one and prevent amblyopia, so compliance with patching remains important. Patching the turned eye would not stimulate it.', false),
  ('strabismus', 30, 'The parent of a 2-year-old with strabismus asks what is actually wrong with the child''s eye. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "The lens inside the eye is cloudy, so light cannot reach the back."}, {"id": "b", "text": "The brain has stopped receiving any image from the turned eye."}, {"id": "c", "text": "One or more extraocular muscles are weakened or uncoordinated."}, {"id": "d", "text": "The eyeball is shaped so that it is unable to focus on objects."}]'::jsonb, '["c"]', 'In strabismus, one or more extraocular muscles are weakened or uncoordinated, so the brain receives two different images. The brain still receives an image from the turned eye; in young children it suppresses that image.', false),
  ('strabismus', 31, 'A nurse screens a 3-year-old. The light reflection falls off-center in the left pupil, and vision is poorer in the left eye than in the right. Which conclusions by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "The results are normal for a 3-year-old"}, {"id": "b", "text": "The child will be expected to report double vision"}, {"id": "c", "text": "The left eye should be patched before referral"}, {"id": "d", "text": "The difference in vision between eyes may signal amblyopia"}, {"id": "e", "text": "The asymmetric light reflection suggests misalignment"}]'::jsonb, '["d", "e"]', 'The corneal light reflex test checks symmetry of reflection, so an asymmetric reflection suggests misalignment (e), and visual acuity testing checks for differences in vision between eyes, which may signal amblyopia (d). These findings are abnormal (a), young children suppress one image rather than report diplopia (b), and the weaker left eye should not be patched (c).', true),
  ('strabismus', 32, 'A 4-year-old with strabismus refuses to wear an eye patch, and the provider prescribes atropine eye drops instead. The parent asks how drops can help the turned eye. Which response by the nurse is BEST?', '[{"id": "a", "text": "The drops strengthen the weak muscles of the turned eye over time."}, {"id": "b", "text": "The drops temporarily blur the good eye so the weaker eye works."}, {"id": "c", "text": "The drops realign the eye muscles without surgery."}, {"id": "d", "text": "The drops permanently weaken the good eye''s focus."}]'::jsonb, '["b"]', 'Atropine eye drops temporarily blur the good eye so the weaker eye is forced to work. The blur is temporary, and realigning the extraocular muscles is the purpose of surgery.', false),
  ('strabismus', 33, 'A parent asks why both glasses and a patch were prescribed for a 3-year-old with esotropia and severe farsightedness. Which explanations by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "The patch covers the weaker eye so it can rest"}, {"id": "b", "text": "The glasses fix farsightedness that may cause strabismus"}, {"id": "c", "text": "The patch realigns the extraocular muscles over time"}, {"id": "d", "text": "The patch covers the stronger eye to stimulate the weaker one"}, {"id": "e", "text": "The glasses strengthen the weak eye muscles over time"}]'::jsonb, '["b", "d"]', 'Corrective lenses fix refractive errors such as farsightedness that may cause strabismus (b), and patching covers the stronger eye to stimulate the weaker one (d). Glasses do not strengthen eye muscles (e), the weaker eye is not patched (a), and realigning the extraocular muscles is the role of surgery (c).', true),
  ('strabismus', 34, 'A 4-year-old frequently tilts the head and squints while watching television. On inspection the eyes sometimes appear not to move together. Which action by the nurse is MOST appropriate NEXT?', '[{"id": "a", "text": "Tell the parent the child will outgrow these habits"}, {"id": "b", "text": "Advise limiting screen time and recheck in one year"}, {"id": "c", "text": "Perform the corneal light reflex test to check symmetry"}, {"id": "d", "text": "Teach the parent to patch the eye that squints"}]'::jsonb, '["c"]', 'Squinting or head tilting to see better and eyes that do not move together are signs of strabismus; the corneal light reflex test shines light in the eyes to check symmetry of reflection. Waiting a year or reassuring delays treatment, which should start as early as possible.', false),
  ('strabismus', 35, 'A pediatric eye clinic nurse is triaging four children. Which child should the nurse see FIRST?', '[{"id": "a", "text": "A 9-year-old with a new eye turn and double vision after a fall"}, {"id": "b", "text": "A 2-year-old with stable esotropia who is awaiting surgery"}, {"id": "c", "text": "A 5-year-old in glasses whose eyes have remained aligned"}, {"id": "d", "text": "A 4-year-old with intermittent exotropia who is on patching"}]'::jsonb, '["a"]', 'Trauma and muscle or nerve problems can cause strabismus, and older children with misalignment experience diplopia; a new deviation after an injury needs prompt evaluation. The other children have known, stable, or treated strabismus.', false),
  ('strabismus', 36, 'The nurse is caring for the parents of a 2-year-old with strabismus. Which statements by the nurse are therapeutic and accurate? Select all that apply.', '[{"id": "a", "text": "Treatment can safely wait until he is 8"}, {"id": "b", "text": "Strabismus is not caused by poor parenting"}, {"id": "c", "text": "He will most likely outgrow it by school age"}, {"id": "d", "text": "Eye alignment surgery is common and safe"}, {"id": "e", "text": "Glasses alone will straighten any eye turn"}]'::jsonb, '["b", "d"]', 'Nurses reassure parents that strabismus is not caused by poor parenting (b) and that eye alignment surgery is common and safe (d). Untreated strabismus leads to amblyopia rather than resolving (c), glasses fix refractive errors that may cause strabismus but are one of several treatments (e), and treatment should start before age 7 (a).', true),
  ('strabismus', 37, 'A 5-year-old''s eyes were successfully aligned with surgery last month. The parent says, "Now that his eyes are straight, we can skip his eye checkups." Which response by the nurse is BEST?', '[{"id": "a", "text": "That''s right; once the eyes are straight, follow-up is unnecessary."}, {"id": "b", "text": "Continue checkups to monitor for signs of amblyopia and vision loss."}, {"id": "c", "text": "Follow-up is needed only if his eye begins to turn inward again."}, {"id": "d", "text": "Follow-up is needed only to check whether he will need glasses."}]'::jsonb, '["b"]', 'Nurses should monitor for signs of amblyopia and vision loss, which can develop in strabismus, so ongoing follow-up is needed even after alignment. Waiting for the eye to turn again could miss vision loss.', false),
  ('strabismus', 38, 'A 4-year-old with constant exotropia has been treated with glasses for farsightedness. Which finding BEST indicates the glasses are effective?', '[{"id": "a", "text": "The child reports double vision when wearing the glasses"}, {"id": "b", "text": "The child tilts the head more to see through the lenses"}, {"id": "c", "text": "Proper eye alignment while wearing the glasses"}, {"id": "d", "text": "Vision in the turned eye is lower than at the last visit"}]'::jsonb, '["c"]', 'Corrective lenses fix refractive errors such as farsightedness that may cause strabismus, and the goal is proper eye alignment. Head tilting and decreasing vision in the turned eye are signs of strabismus and amblyopia, not improvement.', false),
  ('strabismus', 39, 'At a well-child visit, the parent of a 3-year-old says the doctor told them the child has "esotropia." Which explanation by the nurse BEST describes this finding to the parent?', '[{"id": "a", "text": "One of your child''s eyes turns outward."}, {"id": "b", "text": "One of your child''s eyes turns upward."}, {"id": "c", "text": "One of your child''s eyes turns downward."}, {"id": "d", "text": "One of your child''s eyes turns inward."}]'::jsonb, '["d"]', 'Esotropia means one of the child''s eyes turns inward (crossed eyes). Exotropia is an outward turn, hypertropia is upward, and hypotropia is downward.', false),
  ('strabismus', 40, 'The nurse documents that a 4-year-old''s right eye deviates downward while the left eye focuses normally on a toy. Which documentation is MOST accurate?', '[{"id": "a", "text": "Right hypotropia"}, {"id": "b", "text": "Right exotropia"}, {"id": "c", "text": "Right hypertropia"}, {"id": "d", "text": "Right esotropia"}]'::jsonb, '["a"]', 'An eye that turns downward is hypotropia, while the other eye focuses normally. Hypertropia is an upward turn, exotropia outward, and esotropia inward.', false),
  ('strabismus', 41, 'A nursing student tells the parent of a 2-year-old with crossed eyes, "Don''t worry, lots of kids outgrow this." Which action by the supervising nurse is MOST appropriate?', '[{"id": "a", "text": "Agree, because crossed eyes resolve once vision matures"}, {"id": "b", "text": "Clarify that untreated strabismus leads to amblyopia"}, {"id": "c", "text": "Add that surgery is avoided until after age 10"}, {"id": "d", "text": "Suggest a patch on the crossed eye until it straightens"}]'::jsonb, '["b"]', 'Over time strabismus leads to amblyopia if untreated, and treatment should start as early as possible, ideally before age 7, so the student''s statement needs correction. Surgery is typically done around ages 2–5, and the patch covers the stronger eye.', false),
  ('strabismus', 42, 'The nurse is reviewing statements made by parents of children with strabismus. Which statements require follow-up by the nurse? Select all that apply.', '[{"id": "a", "text": "Her glasses fix the farsightedness causing the turn"}, {"id": "b", "text": "She''ll outgrow it, so we''re skipping the patch"}, {"id": "c", "text": "Treatment can start when she is 9"}, {"id": "d", "text": "Her surgery will realign her eye muscles"}, {"id": "e", "text": "The drops will permanently blur her good eye"}]'::jsonb, '["b", "c", "e"]', 'Treatment should start as early as possible, ideally before age 7, so starting at age 9 needs follow-up (c); atropine blurs the good eye only temporarily (e); and skipping patching ignores that untreated strabismus leads to amblyopia and that compliance with patching is important (b). Surgery realigns extraocular muscles (d), and corrective lenses fix refractive errors that may cause strabismus (a).', true),
  ('strabismus', 43, 'A 6-year-old with untreated strabismus repeatedly misjudges the distance when reaching for a cup and bumps into door frames. Which complication does the nurse MOST likely suspect?', '[{"id": "a", "text": "Double vision from suppression"}, {"id": "b", "text": "Psychosocial issues from teasing"}, {"id": "c", "text": "Loss of depth perception"}, {"id": "d", "text": "Paralysis of an eye muscle"}]'::jsonb, '["c"]', 'Loss of depth perception is a complication of untreated strabismus and explains misjudging distance. Suppression is the brain ignoring one image in young children, and muscle paralysis is the temporary effect of a Botox injection.', false),
  ('strabismus', 44, 'A parent of a 4-year-old asks about strabismus surgery. Which statements by the parent indicate understanding of the nurse''s teaching? Select all that apply.', '[{"id": "a", "text": "The surgery realigns the eye muscles"}, {"id": "b", "text": "Surgery is done only after age 10"}, {"id": "c", "text": "After surgery he won''t need eye checkups"}, {"id": "d", "text": "Eye alignment surgery is common and safe"}, {"id": "e", "text": "Botox is a permanent substitute for surgery"}]'::jsonb, '["a", "d"]', 'Surgery realigns extraocular muscles (a), and eye alignment surgery is common and safe (d). Surgery is typically done around ages 2–5 (b), monitoring for amblyopia and vision loss continues (c), and Botox only temporarily paralyzes overactive muscles (e).', true),
  ('strabismus', 45, 'A school nurse sees a 7-year-old whose teacher reports frequent eye rubbing and blinking. On inspection, one eye wanders when the child looks at distant objects. Which action by the nurse is BEST?', '[{"id": "a", "text": "Refer to an ophthalmologist for eye movement evaluation"}, {"id": "b", "text": "Recommend eye drops to soothe the rubbing and blinking"}, {"id": "c", "text": "Recheck the eyes at next year''s school screening"}, {"id": "d", "text": "Send a note telling the parent the child is simply tired"}]'::jsonb, '["a"]', 'Frequent eye rubbing or blinking and an eye that wanders or drifts are signs of strabismus, which needs referral to an ophthalmologist for detailed eye movement evaluation. Waiting a year risks amblyopia and permanent vision loss.', false),
  ('strabismus', 46, 'A 3-year-old has strabismus. Which explanations should the nurse give a parent about how vision is affected over time? Select all that apply.', '[{"id": "a", "text": "In young children the brain ignores one image"}, {"id": "b", "text": "Young children usually report double vision"}, {"id": "c", "text": "The turned eye''s lens slowly becomes cloudy"}, {"id": "d", "text": "The eyes realign without treatment by age 5"}, {"id": "e", "text": "The brain receives two different images"}]'::jsonb, '["a", "e"]', 'With misalignment the brain receives two different images (e), and in young children the brain suppresses (ignores) one image to prevent confusion (a), which over time leads to amblyopia. Double vision is reported by older children and adults (b), lens clouding is not part of strabismus (c), and untreated strabismus does not resolve on its own (d).', true),
  ('strabismus', 47, 'A nurse is preparing a 4-year-old with esotropia for treatment. The parent asks what the overall aim of treatment is. Which response by the nurse is BEST?', '[{"id": "a", "text": "To strengthen the lens so the eye can focus on near objects"}, {"id": "b", "text": "To make the weaker eye rest so the stronger eye does the work"}, {"id": "c", "text": "To permanently blur the good eye so that both eyes see the same"}, {"id": "d", "text": "To restore eye alignment and binocular vision and prevent amblyopia"}]'::jsonb, '["d"]', 'The goals of strabismus treatment are to restore proper eye alignment and binocular vision and to prevent amblyopia. Treatment makes the weaker eye work, and atropine blurs the good eye only temporarily.', false),
  ('strabismus', 48, 'A 2-year-old with constant esotropia has a parent who also had strabismus as a child. The parent asks whether the condition is related. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "No, strabismus results from how a child is raised at home."}, {"id": "b", "text": "Yes, a family history is a known cause of strabismus."}, {"id": "c", "text": "No, strabismus appears only after an injury to the eye."}, {"id": "d", "text": "Yes, but only if both parents had eye surgery as children."}]'::jsonb, '["b"]', 'Family history is listed among the causes of strabismus. Strabismus is not caused by poor parenting, and trauma is only one of several causes.', false),
  ('strabismus', 49, 'A grandparent brings a 3-year-old to clinic and says, "Ever since she was a baby, people have said she looks wall-eyed." Which finding would the nurse MOST likely observe on inspection?', '[{"id": "a", "text": "One eye turns inward toward the nose"}, {"id": "b", "text": "One eye turns outward while the other focuses"}, {"id": "c", "text": "One eye turns upward above the level of the other"}, {"id": "d", "text": "One eye turns downward below the other"}]'::jsonb, '["b"]', 'Wall-eye is a common name for exotropia, in which the eye turns outward while the other eye focuses normally. Crossed eyes describes esotropia, an inward turn.', false),
  ('strabismus', 50, 'The nurse is planning care for an 8-year-old with long-standing exotropia who avoids team sports and says, "Everyone stares at my eye." Which nursing focus is the PRIORITY?', '[{"id": "a", "text": "Self-esteem and psychosocial effects of strabismus"}, {"id": "b", "text": "Teaching the child to apply the atropine drops"}, {"id": "c", "text": "Scheduling a Botox injection for the turned eye"}, {"id": "d", "text": "Teaching the parent to patch the turned eye daily"}]'::jsonb, '["a"]', 'Psychosocial issues such as self-esteem and teasing are complications of untreated strabismus, and the child''s statements show this concern. The patch goes over the stronger eye, and Botox is used only in select cases.', false),
  ('development', 1, 'During a well-child visit, the nurse assesses a 10-month-old infant who was born at term. The parent reports the infant cries to show needs but makes no other sounds. Which finding requires IMMEDIATE follow-up with the health care provider?', '[{"id": "a", "text": "Not yet walking alone"}, {"id": "b", "text": "Anterior fontanel still open"}, {"id": "c", "text": "No babbling"}, {"id": "d", "text": "No first words yet"}]'::jsonb, '["c"]', 'No babbling by 9 months is a developmental red flag, so a 10-month-old who does not babble needs provider follow-up. Walking alone (~12–15 months), first words (by 12 months), and fontanel closure (12–18 months) are not yet expected at 10 months.', false),
  ('development', 2, 'A parent brings a 20-month-old toddler for a well-child visit. The nurse gathers the following history and observations. Which findings require follow-up with the health care provider? Select all that apply.', '[{"id": "a", "text": "Is not walking yet"}, {"id": "b", "text": "Used to say words but now can''t speak"}, {"id": "c", "text": "Plays alongside, not with, other children"}, {"id": "d", "text": "Is not yet using 2-word phrases"}, {"id": "e", "text": "Has a pot belly and wide stance"}]'::jsonb, '["a", "b"]', 'Not walking by 18 months is a red flag, so a 20-month-old who does not walk needs follow-up. Loss of milestones (used to speak but now can''t) is also a red flag. Parallel play is expected in toddlers. 2-word phrases are expected by age 2, so their absence at 20 months is not yet a red flag. A pot belly and wide stance are normal in toddlers.', true),
  ('development', 3, 'A nurse in a pediatric clinic reviews the motor assessments of four infants born at term. Which finding should the nurse report to the health care provider FIRST?', '[{"id": "a", "text": "Head lag at 3 months"}, {"id": "b", "text": "Not yet crawling at 7 months"}, {"id": "c", "text": "Not yet sitting up at 5 months"}, {"id": "d", "text": "Head lag at 5 months"}]'::jsonb, '["d"]', 'Head lag should disappear by 4 months; persistence at 5 months may signal neurologic delay. Head lag at 3 months is still expected, sitting up occurs at 6–8 months, and crawling occurs at ~9 months.', false),
  ('development', 4, 'A 2-year-old hospitalized for dehydration pushes the nurse''s hand away at snack time and shouts, "Me do it!" Which nursing action BEST supports this toddler''s developmental needs?', '[{"id": "a", "text": "Offer a safe choice, such as \"red cup or blue?\""}, {"id": "b", "text": "Explain the snack using cause and effect"}, {"id": "c", "text": "Have the child keep a chart to master a skill"}, {"id": "d", "text": "Provide privacy and arrange for peers to visit"}]'::jsonb, '["a"]', 'Toddlers are in Autonomy vs. Shame/Doubt and want independence, so the nurse should let them make safe choices such as "red cup or blue?". Mastering skills and involvement in care fit school-age children, and privacy and peers matter most to teens.', false),
  ('development', 5, 'A 4-year-old admitted with pneumonia tells the nurse, "I got sick because I was mean to my baby sister yesterday." Which interpretation of this statement by the nurse is MOST accurate?', '[{"id": "a", "text": "Animism, believing objects are alive"}, {"id": "b", "text": "Egocentric thinking of the toddler"}, {"id": "c", "text": "Magical thinking, believing thoughts cause events"}, {"id": "d", "text": "Regression that is normal during stress"}]'::jsonb, '["c"]', 'Preschoolers show magical thinking (believing thoughts cause events), so they may blame themselves for illness. Animism is believing objects are alive, which this statement does not show.', false),
  ('development', 6, 'A 4-year-old with an IV infusion points at the IV pole and tells the nurse, "That pole is mean, and it wants to hurt me." The nurse identifies this statement as which expected finding of the preschooler''s thinking?', '[{"id": "a", "text": "Magical thinking"}, {"id": "b", "text": "Animism"}, {"id": "c", "text": "Concrete operational thinking"}, {"id": "d", "text": "Egocentric thinking"}]'::jsonb, '["b"]', 'Animism, believing objects are alive, is expected in preschoolers, and the child is giving the IV pole feelings. Magical thinking is believing thoughts cause events, which is not what the child describes.', false),
  ('development', 7, 'The parent of a 15-month-old who began walking alone last month asks the nurse whether it is time to begin toilet training. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Readiness usually starts around 18 to 24 months.\""}, {"id": "b", "text": "\"Start now, since walking alone begins at 12 to 15 months.\""}, {"id": "c", "text": "\"Wait until about age 3, when full sentences develop.\""}, {"id": "d", "text": "\"Begin now, since the toddler stage starts at 1 year.\""}]'::jsonb, '["a"]', 'Toilet training readiness starts around 18–24 months, so a 15-month-old is usually not yet ready. Walking alone at 12–15 months is a motor milestone and does not signal toilet training readiness.', false),
  ('development', 8, 'A 3-year-old who was fully toilet trained has started wetting the bed on day 3 of a hospital stay for a fractured femur. The worried parent asks if this is a serious problem. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Loss of milestones is a red flag, so I will call the provider.\""}, {"id": "b", "text": "\"Regression is normal during stress, like a hospital stay.\""}, {"id": "c", "text": "\"Readiness starts at 18 to 24 months, so restart training today.\""}, {"id": "d", "text": "\"This shows guilt from being scolded, which is typical at this age.\""}]'::jsonb, '["b"]', 'Regression is normal during stress; a toddler may start wetting again when hospitalized. Loss of milestones (used to speak/walk but now can''t) is the red flag, not stress-related wetting during a hospital stay.', false),
  ('development', 9, 'A nurse on a pediatric unit is planning developmentally appropriate care for several hospitalized children. Which plans are appropriate? Select all that apply.', '[{"id": "a", "text": "Let a toddler make safe choices, such as red cup or blue"}, {"id": "b", "text": "Expect a preschooler to understand conservation"}, {"id": "c", "text": "Involve a school-age child in care to master skills"}, {"id": "d", "text": "Reassure a preschooler that thoughts did not cause the illness"}, {"id": "e", "text": "Allow privacy and control for teens"}]'::jsonb, '["a", "c", "d", "e"]', 'Toddlers should be allowed safe choices (red cup or blue). School-age kids want to master skills, so involve them in care. Preschoolers'' magical thinking may lead them to blame themselves for illness, so reassurance is needed. Teens care most about peers, privacy, and control. Conservation is a school-age (concrete operational) ability, so it is not expected in a 4-year-old.', true),
  ('development', 10, 'A parent of a 30-month-old asks the nurse to recommend a play activity for the child to use while waiting in the clinic. Which activity is MOST appropriate for this child''s developmental level?', '[{"id": "a", "text": "Child-safe scissors and shapes to copy"}, {"id": "b", "text": "A team board game played cooperatively"}, {"id": "c", "text": "A hopping and skipping game"}, {"id": "d", "text": "Blocks so the child builds a tower"}]'::jsonb, '["d"]', 'Building a tower is expected at about 2–3 years, so blocks fit a 30-month-old. Using scissors, copying shapes, hopping, and skipping are preschool skills, and cooperative play is a school-age pattern.', false),
  ('development', 11, 'The parent of a 2-year-old tells the nurse, "At daycare my son sits next to the other kids and plays with his own trucks, but he never plays with them." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"This parallel play, alongside other children, is expected.\""}, {"id": "b", "text": "\"Cooperative play should begin by age 2, so I''ll tell the provider.\""}, {"id": "c", "text": "\"This egocentric thinking is a red flag that needs follow-up.\""}, {"id": "d", "text": "\"Peer approval matters now, so arrange more group playdates.\""}]'::jsonb, '["a"]', 'Toddlers engage in parallel play (alongside, not with, other children). Cooperative play and the importance of peer approval are school-age characteristics, and egocentric thinking is expected in toddlers rather than a red flag.', false),
  ('development', 12, 'A 9-year-old has been hospitalized for 5 days with osteomyelitis and is receiving IV antibiotics. The child appears bored and tells the nurse, "I''m not good at anything in here." Which nursing action BEST supports this child''s development?', '[{"id": "a", "text": "Offer simple choices, such as red cup or blue cup"}, {"id": "b", "text": "Reassure the child that thoughts did not cause the illness"}, {"id": "c", "text": "Involve the child in care to master new skills"}, {"id": "d", "text": "Make privacy and peer visits the top priority"}]'::jsonb, '["c"]', 'School-age children are in Industry vs. Inferiority and want to master skills, so the nurse should involve them in care. Offering simple safe choices is the approach for toddlers, and peers and privacy are the top priority for teens.', false),
  ('development', 13, 'A 15-year-old admitted after an appendectomy asks that a parent step out of the room during the dressing assessment. The parent refuses to leave. Which action by the nurse is BEST?', '[{"id": "a", "text": "Have the parent stay, since teens often question rules"}, {"id": "b", "text": "Respect privacy and control, which teens care about most"}, {"id": "c", "text": "Explain that thoughts did not cause the appendicitis"}, {"id": "d", "text": "Offer the teen a choice of red cup or blue cup instead"}]'::jsonb, '["b"]', 'Teens care most about peers, privacy, and control, so the nurse should support the adolescent''s request for privacy. Questioning rules is an expected adolescent behavior and is not a reason to override privacy.', false),
  ('development', 14, 'A nurse pours the same amount of juice from a short, wide cup into a tall, thin cup in front of four children. Which child is MOST likely to say the amount of juice stayed the same?', '[{"id": "a", "text": "A preschooler aged 3 years"}, {"id": "b", "text": "A preschooler aged 5 years"}, {"id": "c", "text": "A school-age child aged 8 years"}, {"id": "d", "text": "A toddler aged 2 years"}]'::jsonb, '["c"]', 'Conservation is part of concrete operational thinking in the school-age child (6–12 years), so the 8-year-old is most likely to understand it. A 5-year-old is still a preschooler (3–6 years) with magical thinking.', false),
  ('development', 15, 'A nurse wants to discuss how health choices made today might affect a client''s future, using hypothetical situations. Each client has asthma. With which client is this approach MOST likely to be effective?', '[{"id": "a", "text": "A school-age child aged 10 years"}, {"id": "b", "text": "An adolescent aged 15 years"}, {"id": "c", "text": "A school-age child aged 7 years"}, {"id": "d", "text": "A preschooler aged 5 years"}]'::jsonb, '["b"]', 'Abstract thinking develops in adolescence (12–18 years), so the 15-year-old can reason about hypothetical future outcomes. A 10-year-old is still in concrete operational thinking, reasoning logically about real things.', false),
  ('development', 16, 'A nurse reviews findings from several well-child visits for children born at term. Which findings should the nurse report to the health care provider? Select all that apply.', '[{"id": "a", "text": "No babbling at 10 months"}, {"id": "b", "text": "Not walking at 16 months"}, {"id": "c", "text": "No 2-word phrases at 26 months"}, {"id": "d", "text": "Head lag at 3 months"}, {"id": "e", "text": "Not walking at 19 months"}]'::jsonb, '["a", "c", "e"]', 'No babbling by 9 months, not walking by 18 months, and no 2-word phrases by 2 years are red flags, so findings at 10, 19, and 26 months must be reported. Walking alone occurs around 12–15 months, so not walking at 16 months has not yet reached the 18-month red flag. Head lag should disappear by 4 months, so it is still expected at 3 months.', true),
  ('development', 17, 'The parent of a 13-month-old who stands and cruises along furniture is concerned that the child is not walking alone yet. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Walking alone usually begins around 12 to 15 months.\""}, {"id": "b", "text": "\"Babies should walk by 12 months, so I''ll tell the provider.\""}, {"id": "c", "text": "\"Most babies walk right after they sit up at 6 months.\""}, {"id": "d", "text": "\"Walking alone isn''t expected until about 2 years.\""}]'::jsonb, '["a"]', 'Toddlers walk alone at ~12–15 months, so a 13-month-old who cruises is within the expected range. Not walking becomes a red flag only at 18 months, so waiting until 2 years is also incorrect.', false),
  ('development', 18, 'A nurse is assessing a healthy 7-month-old infant during a routine visit. Which finding should the nurse document as an expected finding?', '[{"id": "a", "text": "Stands and cruises"}, {"id": "b", "text": "Sits up"}, {"id": "c", "text": "Says first words"}, {"id": "d", "text": "Head lag when pulled to sit"}]'::jsonb, '["b"]', 'Infants sit up at 6–8 months, so this is expected at 7 months. Standing and cruising occurs at ~10–12 months, first words by 12 months, and head lag should have disappeared by 4 months.', false),
  ('development', 19, 'The parent of a 4-month-old reports that when a toy is hidden under a blanket, the infant stops looking for it. The parent asks whether this is a problem. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"This may signal neurologic delay, so I''ll call the provider.\""}, {"id": "b", "text": "\"This finding is a red flag in infants older than 3 months.\""}, {"id": "c", "text": "\"Infants this age should crawl to find the hidden toy.\""}, {"id": "d", "text": "\"Object permanence usually develops at about 6 to 9 months.\""}]'::jsonb, '["d"]', 'Object permanence develops at about 6–9 months, so a 4-month-old not searching for a hidden toy is expected. The neurologic-delay concern applies to head lag persisting past 4 months, not to object permanence.', false),
  ('development', 20, 'The parent of a 7-month-old states, "My baby rolls over and sits up, but my friend''s baby was crawling at this age. Is something wrong?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Rolling over should have led to crawling by 6 months.\""}, {"id": "b", "text": "\"Not crawling by 7 months is a red flag to report.\""}, {"id": "c", "text": "\"Crawling usually begins at around 9 months.\""}, {"id": "d", "text": "\"Babies usually crawl after they stand and cruise.\""}]'::jsonb, '["c"]', 'Infants crawl at ~9 months, so a 7-month-old who rolls over and sits is on track. Crawling comes before standing and cruising (~10–12 months), and not crawling at 7 months is not a listed red flag.', false),
  ('development', 21, 'A nurse is assessing an 8-week-old infant born at term during a well-baby visit. Which finding should the nurse document as an expected finding?', '[{"id": "a", "text": "Babbles"}, {"id": "b", "text": "Rolls over"}, {"id": "c", "text": "Coos"}, {"id": "d", "text": "Sits up"}]'::jsonb, '["c"]', 'Infants coo by 6 weeks, so cooing is expected at 8 weeks. Babbling and rolling over are expected at 4–6 months, and sitting up at 6–8 months.', false),
  ('development', 22, 'While assessing a healthy 15-month-old who walks alone and says several words, the nurse palpates an open anterior fontanel. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Notify the provider, since it should close by 6 months"}, {"id": "b", "text": "Document it as expected, since it closes by 12–18 months"}, {"id": "c", "text": "Assess for head lag, which signals neurologic delay"}, {"id": "d", "text": "Report it to the provider as a loss of milestones"}]'::jsonb, '["b"]', 'The anterior fontanel closes by 12–18 months, so an open fontanel at 15 months is expected. There is no indication of head lag or loss of milestones in this child.', false),
  ('development', 23, 'The parent of a healthy 2-year-old is concerned that the child has a protruding belly and stands and walks with the feet wide apart. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Toddlers should be losing baby fat, so the belly needs evaluation.\""}, {"id": "b", "text": "\"A wide stance suggests delayed walking, so I''ll notify the provider.\""}, {"id": "c", "text": "\"Toddlers grow rapidly, so a large belly is expected right now.\""}, {"id": "d", "text": "\"A pot belly and wide stance are normal findings for toddlers.\""}]'::jsonb, '["d"]', 'Toddlers have slower growth, and a pot belly and wide stance are normal. Losing baby fat occurs in preschoolers, and rapid growth describes infancy, not the toddler years.', false),
  ('development', 24, 'A nurse is assessing a 4-year-old at a preschool health screening. Which finding requires follow-up with the health care provider?', '[{"id": "a", "text": "Asks \"why?\" constantly throughout the visit"}, {"id": "b", "text": "Believes the stuffed toys are alive"}, {"id": "c", "text": "Spoke in full sentences, now says only single words"}, {"id": "d", "text": "Believes a bad wish caused a sibling''s illness"}]'::jsonb, '["c"]', 'Loss of milestones (used to speak but now can''t) is a developmental red flag. Asking "why?" constantly, animism, and magical thinking are all expected preschool findings.', false),
  ('development', 25, 'A nurse is talking with a 15-year-old during a sports physical. Which statement by the adolescent BEST reflects the expected psychosocial task for this age?', '[{"id": "a", "text": "\"I''m figuring out my identity and who I am.\""}, {"id": "b", "text": "\"I want to be the best in my class at schoolwork.\""}, {"id": "c", "text": "\"Let me do it all by myself!\""}, {"id": "d", "text": "\"I feel guilty when I get scolded for trying new things.\""}]'::jsonb, '["a"]', 'Adolescents (12–18 years) are in Identity vs. Role Confusion, figuring out who they are. Focusing on success and schoolwork reflects Industry vs. Inferiority in the school-age child.', false),
  ('development', 26, 'A 5-year-old in the playroom starts a new painting project, spills the paint, is scolded by an older sibling, and begins to cry and hide the painting. The nurse recognizes the child''s MOST likely psychosocial conflict as which stage?', '[{"id": "a", "text": "Autonomy vs. Shame/Doubt"}, {"id": "b", "text": "Industry vs. Inferiority"}, {"id": "c", "text": "Initiative vs. Guilt"}, {"id": "d", "text": "Trust vs. Mistrust"}]'::jsonb, '["c"]', 'Preschoolers (3–6 years) are in Initiative vs. Guilt; they want to try new things and feel guilt when scolded. Autonomy vs. Shame/Doubt belongs to the toddler (1–3 years).', false),
  ('development', 27, 'A 6-month-old is hospitalized for several days while the parents work. Which nursing action BEST supports the infant''s psychosocial development during the stay?', '[{"id": "a", "text": "Offer simple choices to promote independence"}, {"id": "b", "text": "Encourage the infant to master new skills"}, {"id": "c", "text": "Place the infant near other infants for parallel play"}, {"id": "d", "text": "Meet the baby''s needs so the baby learns needs will be met"}]'::jsonb, '["d"]', 'Infants (birth–1 year) are in Trust vs. Mistrust; the baby learns if needs will be met. Choices for independence fit toddlers, and mastering skills fits school-age children.', false),
  ('development', 28, 'A hospitalized 16-year-old is admitted for 1 week of IV therapy for osteomyelitis. Which nursing actions are MOST appropriate for this client''s developmental stage? Select all that apply.', '[{"id": "a", "text": "Explain that thoughts did not cause the illness"}, {"id": "b", "text": "Plan for peer relationships as a top priority"}, {"id": "c", "text": "Give privacy, which teens care most about"}, {"id": "d", "text": "Plan parallel play activities with other teens"}, {"id": "e", "text": "Plan cooperative play as the main social focus"}]'::jsonb, '["b", "c"]', 'Peer relationships are top priority for teens, so friends'' visits are appropriate, and teens care most about privacy, so privacy during the exam is appropriate. Reassurance about thoughts causing illness addresses preschool magical thinking. Parallel play is a toddler pattern, and cooperative play is the school-age pattern.', true),
  ('development', 29, 'A nurse is performing a health assessment on a healthy 9-year-old. Which findings should the nurse identify as expected for this child''s age? Select all that apply.', '[{"id": "a", "text": "Magical thinking about illness"}, {"id": "b", "text": "Cooperative play with peers"}, {"id": "c", "text": "Begins to lose baby teeth"}, {"id": "d", "text": "Abstract thinking about the future"}, {"id": "e", "text": "Understands cause and effect"}]'::jsonb, '["b", "c", "e"]', 'School-age children (6–12 years) show cooperative play, begin to lose baby teeth, and understand cause and effect through concrete operational thinking. Magical thinking is a preschool finding, and abstract thinking develops in adolescence.', true),
  ('development', 30, 'The mother of 11-year-old twins, a girl and a boy, tells the nurse that her daughter is showing early signs of puberty but her son shows none. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Girls usually start puberty earlier than boys.\""}, {"id": "b", "text": "\"Puberty belongs to adolescence, so your daughter needs an evaluation.\""}, {"id": "c", "text": "\"Boys usually start earlier, so your son needs an evaluation.\""}, {"id": "d", "text": "\"Puberty signs before age 12 are a red flag in either child.\""}]'::jsonb, '["a"]', 'Girls usually start puberty earlier than boys, and puberty signs may start near the end of the school-age years, especially in girls. Neither finding is a red flag.', false),
  ('development', 31, 'A 5-year-old scheduled for a tonsillectomy quietly asks the nurse, "Is my throat sick because I was bad and yelled at Mommy?" Which response by the nurse is BEST?', '[{"id": "a", "text": "Explain the surgery using hypothetical, abstract terms"}, {"id": "b", "text": "Explain that her thoughts did not cause the illness"}, {"id": "c", "text": "Offer a choice of red cup or blue cup and change the subject"}, {"id": "d", "text": "Explain the surgery using conservation of amounts"}]'::jsonb, '["b"]', 'Because of magical thinking, preschoolers may blame themselves for illness, so the nurse should reassure the child that thoughts did not cause it. Abstract thinking does not develop until adolescence, and conservation is a school-age ability.', false),
  ('development', 32, 'When pulling a 6-month-old infant born at term from a supine to a sitting position, the nurse observes that the infant''s head falls backward. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Recheck for head lag at the 9-month visit"}, {"id": "b", "text": "Document head lag as expected until 6 months"}, {"id": "c", "text": "Call the provider about possible neurologic delay"}, {"id": "d", "text": "Teach that head lag resolves once sitting up begins"}]'::jsonb, '["c"]', 'Head lag should disappear by 4 months; if not, it may signal neurologic delay, so persistence at 6 months must be reported. Waiting until the next visit delays evaluation of a possible neurologic delay.', false),
  ('development', 33, 'The parent of a 26-month-old reports that the child says about 15 single words but has never put 2 words together. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Reassure that the vocabulary explosion happens after age 3"}, {"id": "b", "text": "Reassure that full sentences are not expected until preschool"}, {"id": "c", "text": "Reassure that first words were expected by 12 months"}, {"id": "d", "text": "Call the provider, since 2-word phrases are expected by 2"}]'::jsonb, '["d"]', 'No 2-word phrases by 2 years is a red flag, so a 26-month-old using only single words needs follow-up. Full sentences are indeed a preschool skill, but that does not excuse the missing 2-word phrases.', false),
  ('development', 34, 'The parent of a 30-month-old reports that over the past few months the child has suddenly started using many new words every week. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Rapid language change is a red flag needing evaluation"}, {"id": "b", "text": "This is a vocabulary explosion expected after 2 years"}, {"id": "c", "text": "This is regression related to a stressful event"}, {"id": "d", "text": "This shows full sentences and constant \"why?\" questions"}]'::jsonb, '["b"]', 'A vocabulary explosion after 2 years is expected in toddlers. Full sentences and constant "why?" questions are preschool findings, and a gain in words is not a red flag.', false),
  ('development', 35, 'The parent of an 11-month-old says, "She babbles all day but hasn''t said a real word yet. Should I be worried?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"No first words by 9 months is a red flag, so I''ll notify the provider.\""}, {"id": "b", "text": "\"Words aren''t expected until 2-word phrases appear at age 2.\""}, {"id": "c", "text": "\"First words are expected by 12 months, and she is babbling.\""}, {"id": "d", "text": "\"Babbling should stop by 6 months, when first words begin.\""}]'::jsonb, '["c"]', 'First words are expected by 12 months, and the red flag at 9 months is no babbling, which this infant does not have. 2-word phrases are expected by 2 years, but first words come earlier.', false),
  ('development', 36, 'A nurse is assessing a healthy 5-month-old infant born at term. Which findings should the nurse identify as expected? Select all that apply.', '[{"id": "a", "text": "Rolls over"}, {"id": "b", "text": "Crawls"}, {"id": "c", "text": "Babbles"}, {"id": "d", "text": "Anterior fontanel closed"}, {"id": "e", "text": "No head lag"}]'::jsonb, '["a", "c", "e"]', 'Rolling over and babbling are expected at 4–6 months, and head lag should disappear by 4 months, so it should be absent at 5 months. Crawling occurs at ~9 months, and the anterior fontanel closes by 12–18 months.', true),
  ('development', 37, 'A nurse is performing a developmental screening on a healthy 4-year-old. Which findings should the nurse document as expected? Select all that apply.', '[{"id": "a", "text": "Uses scissors and copies shapes"}, {"id": "b", "text": "Knows name, age, and colors"}, {"id": "c", "text": "Concrete operational thinking"}, {"id": "d", "text": "Runs well, hops, and skips"}, {"id": "e", "text": "Plays alongside, not with, others"}]'::jsonb, '["a", "b", "d"]', 'Preschoolers use scissors and copy shapes, know name, age, and colors, and run well, hop, and skip. Concrete operational thinking is a school-age finding, and parallel play (alongside, not with, others) is the toddler pattern.', true),
  ('development', 38, 'A nurse is assessing a healthy 15-year-old during an annual visit. Which findings should the nurse identify as expected for this client''s age? Select all that apply.', '[{"id": "a", "text": "Magical thinking about illness"}, {"id": "b", "text": "Questions rules and identity"}, {"id": "c", "text": "Peer relationships are top priority"}, {"id": "d", "text": "Growth spurts and sexual maturity"}, {"id": "e", "text": "Abstract thinking develops"}]'::jsonb, '["b", "c", "d", "e"]', 'Adolescents question rules and identity, make peer relationships top priority, go through puberty with growth spurts and sexual maturity, and develop abstract thinking. Magical thinking is a preschool finding.', true),
  ('development', 39, 'The parent of a 20-month-old asks how to help the toddler through an upcoming hospital admission. Which statements by the parent indicate understanding of the nurse''s teaching? Select all that apply.', '[{"id": "a", "text": "\"I''ll let her make safe choices, like red cup or blue.\""}, {"id": "b", "text": "\"She should share and take turns with other children.\""}, {"id": "c", "text": "\"Wetting again in the hospital can be normal with stress.\""}, {"id": "d", "text": "\"Toilet training readiness starts around 18 to 24 months.\""}, {"id": "e", "text": "\"I''ll call if she isn''t speaking in full sentences yet.\""}]'::jsonb, '["a", "c", "d"]', 'Toddlers should be allowed safe choices such as red cup or blue, regression such as wetting again is normal during the stress of hospitalization, and toilet training readiness starts around 18–24 months. Sharing and cooperative play are school-age patterns (toddlers use parallel play), and full sentences are a preschool skill.', true),
  ('development', 40, 'A nurse reviews findings recorded for several 14-month-old toddlers at a pediatric clinic. Which findings require follow-up with the health care provider? Select all that apply.', '[{"id": "a", "text": "No babbling"}, {"id": "b", "text": "Not yet walking alone"}, {"id": "c", "text": "Anterior fontanel still open"}, {"id": "d", "text": "Not yet using 2-word phrases"}, {"id": "e", "text": "Used to say words but now can''t"}]'::jsonb, '["a", "e"]', 'No babbling by 9 months is a red flag, and loss of milestones (used to speak but now can''t) is a red flag. Walking alone is expected ~12–15 months, the anterior fontanel closes by 12–18 months, and 2-word phrases are expected by 2 years, so these are not yet concerns at 14 months.', true),
  ('development', 41, 'A nurse is reviewing behaviors observed in children on a pediatric unit. Which behaviors reflect the expected Erikson psychosocial stage for the child''s age group? Select all that apply.', '[{"id": "a", "text": "Toddler insists \"Me do it!\" and wants independence"}, {"id": "b", "text": "School-age child focuses on success and schoolwork"}, {"id": "c", "text": "Preschooler is figuring out who they are"}, {"id": "d", "text": "Adolescent feels guilt when scolded for trying new things"}, {"id": "e", "text": "Infant learns if needs will be met"}]'::jsonb, '["a", "b", "e"]', 'Toddlers (Autonomy vs. Shame/Doubt) want independence ("Me do it!"), school-age children (Industry vs. Inferiority) focus on success and schoolwork, and infants (Trust vs. Mistrust) learn if needs will be met. Figuring out who they are belongs to adolescents, and guilt when scolded for trying new things belongs to preschoolers.', true),
  ('development', 42, 'A nurse is assessing a healthy 12-month-old born at term at a well-child visit. Which findings should the nurse document as expected? Select all that apply.', '[{"id": "a", "text": "Stands and cruises"}, {"id": "b", "text": "Uses 2-word phrases"}, {"id": "c", "text": "Climbs stairs and kicks a ball"}, {"id": "d", "text": "Says first words"}, {"id": "e", "text": "Uses scissors and copies shapes"}]'::jsonb, '["a", "d"]', 'Infants stand and cruise at ~10–12 months and say first words by 12 months. 2-word phrases are expected by 2 years, climbing stairs and kicking a ball at ~2 years, and scissors and copying shapes in the preschool years.', true),
  ('development', 43, 'The parent of a 2½-year-old asks the nurse which play activities fit the child''s current development. Which activities should the nurse recommend? Select all that apply.', '[{"id": "a", "text": "Builds a tower with blocks"}, {"id": "b", "text": "Uses scissors to copy shapes"}, {"id": "c", "text": "Throws a ball"}, {"id": "d", "text": "Play alongside other children"}, {"id": "e", "text": "Cooperative play with team rules"}]'::jsonb, '["a", "c", "d"]', 'Toddlers build towers and throw a ball at ~2–3 years and engage in parallel play (alongside, not with, other children). Using scissors and copying shapes is a preschool skill, and cooperative team play is a school-age pattern.', true),
  ('development', 44, 'A 2-year-old has been hospitalized for 4 days with pneumonia. Which findings should the nurse recognize as expected for this child? Select all that apply.', '[{"id": "a", "text": "Has started wetting again after toilet training"}, {"id": "b", "text": "Thinking is egocentric"}, {"id": "c", "text": "Plays alongside, not with, other children"}, {"id": "d", "text": "Used to walk but now cannot walk"}, {"id": "e", "text": "Has a pot belly and wide stance"}]'::jsonb, '["a", "b", "c", "e"]', 'Regression is normal during stress, so a hospitalized toddler may start wetting again. Egocentric thinking, parallel play, and a pot belly with a wide stance are expected toddler findings. Loss of milestones (used to walk but now can''t) is a red flag, not an expected finding.', true),
  ('development', 45, 'A school nurse teaches a group of parents about development of school-age children (6–12 years). Which statements by the parents indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"My 11-year-old daughter may start showing signs of puberty.\""}, {"id": "b", "text": "\"My 7-year-old''s loose baby teeth are expected.\""}, {"id": "c", "text": "\"My 8-year-old should already think abstractly about the future.\""}, {"id": "d", "text": "\"Peer approval is becoming important to my 9-year-old.\""}, {"id": "e", "text": "\"My 10-year-old will mostly prefer parallel play.\""}]'::jsonb, '["a", "b", "d"]', 'Puberty signs may start near the end of the school-age years, especially in girls; school-age children begin to lose baby teeth; and peer approval becomes important. Abstract thinking develops in adolescence, and school-age children use cooperative play rather than the toddler''s parallel play.', true),
  ('development', 46, 'A 9-year-old with a long leg cast tells the nurse, "I''m scared I''ll fall behind my class and everyone will think I''m dumb." The nurse recognizes this concern as MOST consistent with which psychosocial stage?', '[{"id": "a", "text": "Identity vs. Role Confusion"}, {"id": "b", "text": "Initiative vs. Guilt"}, {"id": "c", "text": "Trust vs. Mistrust"}, {"id": "d", "text": "Industry vs. Inferiority"}]'::jsonb, '["d"]', 'School-age children are in Industry vs. Inferiority and focus on success, schoolwork, and learning skills, so this worry is typical. Identity vs. Role Confusion belongs to adolescence (12–18 years).', false),
  ('development', 47, 'The parent of a 1-month-old asks in what order the baby will likely reach motor milestones over the next 15 months. Which sequence should the nurse describe as the MOST accurate?', '[{"id": "a", "text": "Sits up, rolls over, crawls, walks alone, stands and cruises"}, {"id": "b", "text": "Rolls over, crawls, sits up, stands and cruises, walks alone"}, {"id": "c", "text": "Rolls over, sits up, crawls, stands and cruises, walks alone"}, {"id": "d", "text": "Sits up, crawls, rolls over, stands and cruises, walks alone"}]'::jsonb, '["c"]', 'Infants roll over at 4–6 months, sit up at 6–8 months, crawl at ~9 months, stand and cruise at ~10–12 months, and walk alone at ~12–15 months. Option b reverses sitting and crawling.', false),
  ('development', 48, 'A nurse is preparing a 7-year-old for a cast change. Which teaching approach is BEST for this child''s cognitive level?', '[{"id": "a", "text": "Show cause and effect logically with real things"}, {"id": "b", "text": "Discuss abstract, hypothetical risks of the procedure"}, {"id": "c", "text": "Explain that the cast change is not punishment for bad thoughts"}, {"id": "d", "text": "Avoid explanations and offer a choice of red cup or blue cup"}]'::jsonb, '["a"]', 'School-age children use concrete operational thinking, reasoning logically about real things, so explaining with real equipment fits a 7-year-old. Abstract thinking does not develop until adolescence.', false),
  ('development', 49, 'A 4-year-old in the hospital keeps trying to help the nurse with the dressing change and asks to push the bed buttons. Which nursing approach BEST supports this child''s psychosocial development?', '[{"id": "a", "text": "Focus the child on schoolwork to prevent inferiority"}, {"id": "b", "text": "Let the child try new things without being scolded"}, {"id": "c", "text": "Meet the child''s needs consistently to build trust"}, {"id": "d", "text": "Encourage the child to figure out who they are"}]'::jsonb, '["b"]', 'Preschoolers are in Initiative vs. Guilt; they want to try new things and feel guilt when scolded, so the nurse should allow safe new tasks without scolding. Schoolwork and inferiority relate to school-age children.', false),
  ('development', 50, 'A 2-year-old who climbs stairs is in the clinic playroom for a 1-hour wait. The parent asks for an activity to promote large-muscle skills. Which activity is MOST appropriate?', '[{"id": "a", "text": "Hops and skips in games"}, {"id": "b", "text": "Kicks a ball"}, {"id": "c", "text": "Uses scissors on shapes"}, {"id": "d", "text": "Plays team sports with peers"}]'::jsonb, '["b"]', 'Climbing stairs and kicking a ball are expected at ~2 years. Hopping, skipping, and using scissors are preschool skills, and team play with peers reflects school-age cooperative play.', false),
  ('rickets', 1, 'A 20-month-old has bowing of the legs, delayed walking, and irritability. Initial labs show low serum calcium. The nurse anticipates a test to confirm the child''s vitamin D status. Which test is the MOST accurate for this purpose?', '[{"id": "a", "text": "Serum alkaline phosphatase"}, {"id": "b", "text": "Serum phosphate"}, {"id": "c", "text": "25-hydroxyvitamin D"}, {"id": "d", "text": "X-ray of the wrists"}]'::jsonb, '["c"]', '25-hydroxyvitamin D is the most accurate test for vitamin D levels. Alkaline phosphatase is elevated in active bone turnover, phosphate is decreased, and X-rays show bone changes, but none of these measures vitamin D itself.', false),
  ('rickets', 2, 'An 8-month-old with rickets is admitted with severe hypocalcemia. The infant is irritable, has a soft skull, and has bowed legs. Which nursing action is the PRIORITY?', '[{"id": "a", "text": "Monitor for seizures"}, {"id": "b", "text": "Measure the head circumference"}, {"id": "c", "text": "Teach the parents about fortified cereals"}, {"id": "d", "text": "Schedule follow-up labs for next month"}]'::jsonb, '["a"]', 'Nurses monitor for seizures in severe hypocalcemia, which is the safety priority. Growth monitoring, diet teaching, and follow-up labs are part of rickets care but are not the priority when calcium is severely low.', false),
  ('rickets', 3, 'A 2-year-old with bowed legs, enlarged wrists, and a rachitic rosary is being evaluated for rickets caused by vitamin D deficiency. Which laboratory results would the nurse expect? Select all that apply.', '[{"id": "a", "text": "↓ Serum calcium"}, {"id": "b", "text": "↑ Serum calcium"}, {"id": "c", "text": "↓ Serum phosphate"}, {"id": "d", "text": "↑ Alkaline phosphatase"}, {"id": "e", "text": "↓ 25-hydroxyvitamin D"}]'::jsonb, '["a", "c", "d", "e"]', 'Rickets is diagnosed with decreased serum calcium (a), decreased serum phosphate (c), elevated alkaline phosphatase from active bone turnover (d), and decreased 25-hydroxyvitamin D (e). An elevated serum calcium (b) is the opposite of the expected finding.', true),
  ('rickets', 4, 'A 3-year-old being treated for rickets is choosing breakfast from the hospital menu with a parent. Which meal should the nurse recommend as the BEST choice to support bone growth?', '[{"id": "a", "text": "Yogurt, white toast, and apple juice"}, {"id": "b", "text": "Fortified milk, an egg, and fortified cereal"}, {"id": "c", "text": "Scrambled egg, white toast, and apple juice"}, {"id": "d", "text": "Fortified cereal with water and a banana"}]'::jsonb, '["b"]', 'Fortified milk, egg, and cereal are rich in vitamin D and calcium and best support bone growth in rickets. The other meals each contain only one of the recommended foods (dairy, eggs, or fortified cereal) rather than the full combination.', false),
  ('rickets', 5, 'At a 2-month well visit, the mother of an exclusively breastfed infant says she is not giving any supplements because "breastmilk is all the baby needs." Which teaching by the nurse is the PRIORITY to prevent rickets?', '[{"id": "a", "text": "Switch the infant to fortified cereal now"}, {"id": "b", "text": "Add calcium and phosphate supplements now"}, {"id": "c", "text": "Stop breastfeeding and use dairy milk instead"}, {"id": "d", "text": "Give vitamin D supplementation as prescribed"}]'::jsonb, '["d"]', 'Exclusive breastfeeding without vitamin D supplementation is a cause of rickets, so the infant needs vitamin D supplements as prescribed. Calcium and phosphate are added only as needed, and breastfeeding itself is not the problem.', false),
  ('rickets', 6, 'A school nurse reviews health records to identify children who may be at risk for rickets. Which children have risk factors for this condition? Select all that apply.', '[{"id": "a", "text": "A child who plays outdoors in the sun daily"}, {"id": "b", "text": "A dark-skinned child with limited sunlight"}, {"id": "c", "text": "A child who eats eggs, fish, and dairy daily"}, {"id": "d", "text": "A child on a vegan diet"}, {"id": "e", "text": "A child in a northern climate"}]'::jsonb, '["b", "d", "e"]', 'Risk factors include dark skin, which reduces skin production of vitamin D, and limited sunlight exposure (b); poor dietary intake such as vegan diets (d); and living in northern climates (e). Daily outdoor play in the sun (a) and a diet with eggs, fish, and dairy (c) support vitamin D and bone health.', true),
  ('rickets', 7, 'A 4-month-old who was born at 30 weeks'' gestation is seen in the clinic. The parent asks why the provider is concerned about rickets when the full-term older sibling never had a problem. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"Premature birth means lower stores of vitamin D.\""}, {"id": "b", "text": "\"Premature infants absorb too much calcium from milk.\""}, {"id": "c", "text": "\"Premature infants make too much vitamin D in the skin.\""}, {"id": "d", "text": "\"Premature birth causes chronic kidney disease.\""}]'::jsonb, '["a"]', 'Premature birth is a cause of rickets because premature infants have lower stores of vitamin D. Chronic kidney disease is a separate cause that interferes with vitamin D activation.', false),
  ('rickets', 8, 'A 6-year-old with chronic kidney disease has developed bowed legs and bone pain. The parent says the child drinks fortified milk daily and asks how vitamin D could still be a problem. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Fortified milk blocks vitamin D absorption in the gut.\""}, {"id": "b", "text": "\"The kidneys make the skin produce less vitamin D.\""}, {"id": "c", "text": "\"Kidney disease interferes with vitamin D activation.\""}, {"id": "d", "text": "\"Kidney disease causes the body to store too much calcium.\""}]'::jsonb, '["c"]', 'Chronic kidney disease causes rickets because it interferes with vitamin D activation, even when intake is adequate. Reduced skin production of vitamin D is the risk for dark-skinned children, and absorption problems are seen with malabsorption syndromes.', false),
  ('rickets', 9, 'A 2-year-old is being assessed for suspected rickets. Which physical findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "Swelling at costochondral junctions"}, {"id": "b", "text": "Indented chest (Harrison''s groove)"}, {"id": "c", "text": "Early eruption of the teeth"}, {"id": "d", "text": "Enlarged wrists and ankles"}, {"id": "e", "text": "Firm, hard skull bones"}]'::jsonb, '["a", "b", "d"]', 'The RICKETS signs include rachitic rosary, or swelling at the costochondral junctions (a); an indented chest, Harrison''s groove (b); and enlarged wrists and ankles (d). Teeth issues are delayed eruption, not early eruption (c), and the skull is soft (craniotabes), not firm (e).', true),
  ('rickets', 10, 'A 5-year-old with cystic fibrosis takes a daily multivitamin, plays outside, and eats a balanced diet, yet has low 25-hydroxyvitamin D and bowed legs. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "\"The child is getting far too much sunlight exposure.\""}, {"id": "b", "text": "\"Malabsorption syndromes reduce vitamin D uptake.\""}, {"id": "c", "text": "\"The kidneys are not activating the vitamin D.\""}, {"id": "d", "text": "\"The child was born with lower stores of vitamin D.\""}]'::jsonb, '["b"]', 'Malabsorption syndromes such as celiac disease and cystic fibrosis are causes of rickets because vitamin D is poorly absorbed despite adequate intake. Failure of vitamin D activation is the mechanism in chronic kidney disease, and lower stores relate to premature birth.', false),
  ('rickets', 11, 'While examining a 4-month-old with low serum calcium and low 25-hydroxyvitamin D, the nurse presses gently on the infant''s skull and notes that the bone feels soft and gives way. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Harrison''s groove from defective mineralization"}, {"id": "b", "text": "Rachitic rosary from defective mineralization"}, {"id": "c", "text": "Enlarged growth plates of the wrists"}, {"id": "d", "text": "Craniotabes from defective mineralization"}]'::jsonb, '["d"]', 'A soft skull is craniotabes, one of the RICKETS signs caused by defective mineralization of growing bones. Harrison''s groove is an indented chest, and the rachitic rosary is swelling at the costochondral junctions.', false),
  ('rickets', 12, 'A 3-year-old is diagnosed with nutritional rickets. The nurse is developing a plan of care with the family. Which nursing interventions should be included? Select all that apply.', '[{"id": "a", "text": "Educate on vitamin D sources (sunlight, food, supplements)"}, {"id": "b", "text": "Limit outdoor play to protect the soft bones"}, {"id": "c", "text": "Monitor growth and development regularly"}, {"id": "d", "text": "Check labs again only if the legs stay bowed"}, {"id": "e", "text": "Administer supplements as prescribed"}]'::jsonb, '["a", "c", "e"]', 'Nursing care includes educating caregivers on vitamin D sources (a), monitoring growth and development regularly (c), and administering supplements as prescribed (e). Outdoor play with safe sun exposure is encouraged, not limited (b), and follow-up labs are reinforced to check treatment progress regardless of how the legs look (d).', true),
  ('rickets', 13, 'A 2-year-old with low serum calcium and low 25-hydroxyvitamin D is examined. The nurse notes a horizontal indentation along the lower chest wall. Which finding should the nurse document?', '[{"id": "a", "text": "Rachitic rosary"}, {"id": "b", "text": "Craniotabes"}, {"id": "c", "text": "Harrison''s groove"}, {"id": "d", "text": "Knock-knees (genu valgum)"}]'::jsonb, '["c"]', 'An indented chest in rickets is Harrison''s groove. The rachitic rosary is swelling at the costochondral junctions, craniotabes is a soft skull, and genu valgum is knock-knees.', false),
  ('rickets', 14, 'The nurse palpates the anterior chest of an 18-month-old with delayed walking and bowed legs and feels a row of bead-like swellings where the ribs meet the cartilage. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Rachitic rosary at the costochondral junctions"}, {"id": "b", "text": "Harrison''s groove from an indented chest wall"}, {"id": "c", "text": "Enlarged growth plates seen in the ankles"}, {"id": "d", "text": "Craniotabes extending from the skull to the chest"}]'::jsonb, '["a"]', 'Swelling at the costochondral junctions is the rachitic rosary (rosary chest) of rickets. Harrison''s groove is an indented chest rather than swelling, and craniotabes refers to a soft skull.', false),
  ('rickets', 15, 'A 2-year-old with bowed legs and low 25-hydroxyvitamin D has wrist X-rays. The parent asks the nurse what the images are likely to show. Which findings should the nurse expect the X-rays to show? Select all that apply.', '[{"id": "a", "text": "Narrowed growth plates"}, {"id": "b", "text": "Cupping/fraying of metaphysis"}, {"id": "c", "text": "Widened growth plates"}, {"id": "d", "text": "Increased bone hardness"}, {"id": "e", "text": "Bone softening"}]'::jsonb, '["b", "c", "e"]', 'X-rays in rickets show cupping/fraying of the metaphysis (b), widened growth plates (c), and bone softening (e). Narrowed growth plates (a) and increased bone hardness (d) are the opposite of the defective mineralization seen in rickets.', true),
  ('rickets', 16, 'The parent of a 3-year-old with rickets reviews the lab report and asks why one result is high when the calcium, phosphate, and vitamin D results are all low. Which explanation about the alkaline phosphatase by the nurse is BEST?', '[{"id": "a", "text": "\"It is high because the child drinks fortified milk.\""}, {"id": "b", "text": "\"It is elevated in active bone turnover.\""}, {"id": "c", "text": "\"It is high because the kidneys activate vitamin D.\""}, {"id": "d", "text": "\"It is high only when seizures have occurred.\""}]'::jsonb, '["b"]', 'Alkaline phosphatase is elevated in active bone turnover, which is why it rises while calcium, phosphate, and 25-hydroxyvitamin D fall in rickets. It is not caused by diet or seizures.', false),
  ('rickets', 17, 'A 4-year-old has taken vitamin D supplements for rickets for 6 weeks. The parent says the child seems more active and asks to cancel the lab appointment scheduled for next week. Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "\"Labs are needed only if the child has a seizure.\""}, {"id": "b", "text": "\"The appointment can be canceled if the legs look straighter.\""}, {"id": "c", "text": "\"Feeling better means the supplements can be stopped.\""}, {"id": "d", "text": "\"Follow-up labs check how well the treatment is working.\""}]'::jsonb, '["d"]', 'Nurses reinforce follow-up labs to check treatment progress; improved activity alone does not show that levels have recovered. Supplements are given as prescribed rather than stopped based on how the child feels.', false),
  ('rickets', 18, 'The nurse is teaching the parent of a 2-year-old with rickets about foods that support bone healing. Which foods should the nurse include in the teaching? Select all that apply.', '[{"id": "a", "text": "Dairy"}, {"id": "b", "text": "Fortified cereals"}, {"id": "c", "text": "Fruit-flavored soda"}, {"id": "d", "text": "Eggs"}, {"id": "e", "text": "Fish"}]'::jsonb, '["a", "b", "d", "e"]', 'Balanced nutrition for rickets includes dairy (a), fortified cereals (b), eggs (d), and fish (e), which provide vitamin D and calcium. Fruit-flavored soda (c) is not a source of vitamin D or calcium and does not support bone growth.', true),
  ('rickets', 19, 'The parents of a 2-year-old follow a strict vegan diet and rarely take the child outdoors. The toddler has bowed legs and delayed walking. Which statement by the nurse BEST explains the child''s risk?', '[{"id": "a", "text": "\"A vegan diet causes the kidneys to stop activating vitamin D.\""}, {"id": "b", "text": "\"A vegan diet leads to an excess of phosphate in the bones.\""}, {"id": "c", "text": "\"A vegan diet and limited sunlight both reduce vitamin D.\""}, {"id": "d", "text": "\"A vegan diet increases the skin''s production of vitamin D.\""}]'::jsonb, '["c"]', 'Poor dietary intake, such as a vegan diet, and limited sunlight exposure are both risk factors for rickets from vitamin D deficiency. Failure of vitamin D activation is the mechanism in chronic kidney disease, not diet.', false),
  ('rickets', 20, 'A 3-year-old with lactose intolerance avoids all milk and has low 25-hydroxyvitamin D. The parent asks which foods can provide vitamin D. Which choice should the nurse recommend FIRST from the foods that support bone growth?', '[{"id": "a", "text": "Eggs, fish, and fortified cereals"}, {"id": "b", "text": "Fruit juice and white bread with jam"}, {"id": "c", "text": "Plain rice and boiled potatoes"}, {"id": "d", "text": "Crackers and apple slices"}]'::jsonb, '["a"]', 'Lactose intolerance is a risk factor for poor dietary intake. Eggs, fish, and fortified cereals are part of balanced nutrition for rickets and do not depend on dairy.', false),
  ('rickets', 21, 'The nurse reviews the history of a 5-month-old being evaluated for soft skull bones and low serum calcium. Which findings in the history are causes of rickets? Select all that apply.', '[{"id": "a", "text": "Born at full term"}, {"id": "b", "text": "Daily stroller walks outdoors"}, {"id": "c", "text": "Premature birth"}, {"id": "d", "text": "Exclusive breastfeeding without vitamin D supplementation"}, {"id": "e", "text": "Fortified infant cereal started"}]'::jsonb, '["c", "d"]', 'Premature birth causes lower stores of vitamin D (c), and exclusive breastfeeding without vitamin D supplementation (d) is a cause of rickets. A term birth (a), outdoor time in sunlight (b), and fortified cereal (e) do not cause vitamin D deficiency.', true),
  ('rickets', 22, 'A dark-skinned 2-year-old who lives in a sunny area plays outside daily but has bowed legs and low 25-hydroxyvitamin D. The parent asks how the child could be deficient. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"Dark skin interferes with vitamin D activation in the kidneys.\""}, {"id": "b", "text": "\"Dark skin has reduced skin production of vitamin D.\""}, {"id": "c", "text": "\"Dark skin blocks the absorption of vitamin D from food.\""}, {"id": "d", "text": "\"Dark skin leads to lower stores of vitamin D at birth.\""}]'::jsonb, '["b"]', 'Dark-skinned children are at risk for rickets because of reduced skin production of vitamin D. Vitamin D activation is impaired in chronic kidney disease, absorption is impaired in malabsorption syndromes, and lower stores are linked to premature birth.', false),
  ('rickets', 23, 'A family recently moved from a tropical country to a northern city. The 3-year-old daughter wears clothing that covers her skin for cultural reasons and has started limping with bowed legs. Which nursing action is MOST appropriate?', '[{"id": "a", "text": "Reassure the family that limping is normal after a move"}, {"id": "b", "text": "Teach the family to restrict dairy until the legs straighten"}, {"id": "c", "text": "Report the bowing as a sign of chronic kidney disease"}, {"id": "d", "text": "Educate the family on vitamin D sources and supplements"}]'::jsonb, '["d"]', 'Children in northern climates or with covered skin for cultural reasons are at risk for rickets, so the nurse educates caregivers on vitamin D sources such as sunlight, food, and supplements. Dairy supports bone growth and should not be restricted.', false),
  ('rickets', 24, 'The nurse evaluates teaching with the parent of a 2-year-old who started treatment for rickets. Which statements by the parent indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "\"We will limit outdoor play since the bones are soft.\""}, {"id": "b", "text": "\"I will give the vitamin D supplement as prescribed.\""}, {"id": "c", "text": "\"Eggs, fish, and fortified cereals are good choices.\""}, {"id": "d", "text": "\"Follow-up labs are not needed once the bowed legs improve.\""}, {"id": "e", "text": "\"I will watch for bone pain and delays in walking.\""}]'::jsonb, '["a", "d"]', 'Outdoor play with safe sun exposure is encouraged, so limiting outdoor play (a) needs correction, and follow-up labs are reinforced to check treatment progress whatever the legs look like (d). Giving supplements as prescribed (b), choosing eggs, fish, and fortified cereals (c), and watching for bone pain or delayed milestones (e) are correct.', true),
  ('rickets', 25, 'The parent of a 15-month-old with rickets is worried because the child''s cousin of the same age has many more teeth. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Fewer teeth means the child also has kidney disease.\""}, {"id": "b", "text": "\"Fewer teeth means the vitamin D dose is too high.\""}, {"id": "c", "text": "\"Delayed eruption of teeth can occur with rickets.\""}, {"id": "d", "text": "\"Fewer teeth means the child needs surgery soon.\""}]'::jsonb, '["c"]', 'Teeth issues in rickets include delayed eruption and enamel defects. Surgery is rare and reserved for severe deformities, and dental delay does not indicate kidney disease.', false),
  ('rickets', 26, 'A 2-year-old with rickets has visibly widened wrists and thickened ankles. The parent asks whether the child has arthritis. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"The enlargement is due to growth plate abnormalities.\""}, {"id": "b", "text": "\"The enlargement is due to swelling of the joint lining.\""}, {"id": "c", "text": "\"The enlargement is a sign of fluid from the kidneys.\""}, {"id": "d", "text": "\"The enlargement is due to a fracture that is healing.\""}]'::jsonb, '["a"]', 'Enlarged wrists and ankles in rickets are due to bone growth plate abnormalities. X-rays in rickets likewise show widened growth plates.', false),
  ('rickets', 27, 'A 3-year-old is being treated for rickets. Which assessments should the nurse include at each follow-up visit? Select all that apply.', '[{"id": "a", "text": "Growth and development"}, {"id": "b", "text": "Bone pain"}, {"id": "c", "text": "Early tooth eruption"}, {"id": "d", "text": "Delayed milestones"}, {"id": "e", "text": "Skull hardness as a sign of worsening"}]'::jsonb, '["a", "b", "d"]', 'Nursing care includes monitoring growth and development regularly (a) and assessing for bone pain (b) and delayed milestones (d). Rickets causes delayed rather than early tooth eruption (c), and a soft skull (craniotabes), not a hard skull, is the sign of rickets (e).', true),
  ('rickets', 28, 'The parent of a 4-year-old newly diagnosed with rickets with mildly bowed legs asks if the child will need an operation to straighten the legs. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Surgery is needed before vitamin D can be started.\""}, {"id": "b", "text": "\"Surgery is rare and used only in severe deformities.\""}, {"id": "c", "text": "\"Surgery is the main treatment for bowed legs in rickets.\""}, {"id": "d", "text": "\"Surgery is done once calcium and phosphate are normal.\""}]'::jsonb, '["b"]', 'Treatment of rickets is vitamin D supplementation with calcium and phosphate as needed, sunlight exposure, and balanced nutrition; surgery is rare and used in severe deformities.', false),
  ('rickets', 29, 'A 3-year-old with rickets has been treated for 4 months. On the growth chart, the child''s height remains well below that of peers. Which nursing action is the PRIORITY?', '[{"id": "a", "text": "Stop the supplements because they are not working"}, {"id": "b", "text": "Reassure the parent that height is not affected"}, {"id": "c", "text": "Recommend surgery to correct the child''s height"}, {"id": "d", "text": "Monitor growth and development regularly"}]'::jsonb, '["d"]', 'Stunted growth is one of the signs of rickets, and the nurse monitors growth and development regularly. Supplements are given as prescribed, and surgery is rare and reserved for severe deformities.', false),
  ('rickets', 30, 'A nurse is documenting the leg findings of children with rickets. Which entries are accurate? Select all that apply.', '[{"id": "a", "text": "Bowed legs (genu valgum)"}, {"id": "b", "text": "Knock-knees (genu varum)"}, {"id": "c", "text": "Bowed legs (genu varum)"}, {"id": "d", "text": "Knock-knees (varus deformity)"}, {"id": "e", "text": "Knock-knees (genu valgum)"}]'::jsonb, '["c", "e"]', 'In rickets, bowed legs are genu varum (c) and knock-knees are genu valgum (e), a valgus deformity. Bowed legs are not genu valgum (a), knock-knees are not genu varum (b), and knock-knees are a valgus, not varus, deformity (d).', true),
  ('rickets', 31, 'The mother of a 2-year-old diagnosed with rickets says her own provider recently told her she has soft bones from vitamin D deficiency called osteomalacia. She asks if the conditions are related. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Osteomalacia is a kidney disease that causes rickets in children.\""}, {"id": "b", "text": "\"Osteomalacia is a childhood form; rickets occurs in adults.\""}, {"id": "c", "text": "\"In adults, the same condition is called osteomalacia.\""}, {"id": "d", "text": "\"The conditions are unrelated, since they affect different bones.\""}]'::jsonb, '["c"]', 'Rickets is soft bones in children due to vitamin D deficiency; in adults, the same condition is called osteomalacia. Osteomalacia is not the childhood form, and chronic kidney disease is a separate cause of rickets.', false),
  ('rickets', 32, 'A 2-year-old with rickets is prescribed vitamin D2. The parent says the pharmacy at home only sells vitamin D3 and asks whether D2 is a mistake. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Vitamin D supplementation may be given as D2 or D3.\""}, {"id": "b", "text": "\"Only D3 treats rickets, so the order is a mistake.\""}, {"id": "c", "text": "\"Vitamin D2 is given only to children with seizures.\""}, {"id": "d", "text": "\"Vitamin D2 is used only after surgery for deformities.\""}]'::jsonb, '["a"]', 'Treatment of rickets includes vitamin D supplementation in the form of D2 or D3, given as prescribed. Neither form is limited to seizures or surgery, and the nurse should not change the prescribed form without the provider.', false),
  ('rickets', 33, 'A 7-year-old has bowed legs and low 25-hydroxyvitamin D despite a diet that includes dairy, eggs, and fish. The nurse reviews the medical history. Which conditions in the history can cause rickets? Select all that apply.', '[{"id": "a", "text": "Celiac disease"}, {"id": "b", "text": "Daily outdoor play in sunlight"}, {"id": "c", "text": "Chronic kidney disease"}, {"id": "d", "text": "Cystic fibrosis"}, {"id": "e", "text": "Daily intake of fortified cereals"}]'::jsonb, '["a", "c", "d"]', 'Malabsorption syndromes such as celiac disease (a) and cystic fibrosis (d) and chronic kidney disease (c), which interferes with vitamin D activation, are causes of rickets. Outdoor play in sunlight (b) and fortified cereals (e) are part of treatment and prevention.', true),
  ('rickets', 34, 'A 4-year-old with rickets spends most of the day indoors watching television. The parent asks whether the child should avoid outdoor activity because the bones are soft. Which recommendation by the nurse is BEST?', '[{"id": "a", "text": "\"Keep the child indoors until the bones harden.\""}, {"id": "b", "text": "\"Encourage outdoor play with safe sun exposure.\""}, {"id": "c", "text": "\"Allow outdoor play only after surgery is done.\""}, {"id": "d", "text": "\"Outdoor play matters only for dark-skinned children.\""}]'::jsonb, '["b"]', 'Nurses encourage outdoor play with safe sun exposure because lack of sun exposure causes vitamin D deficiency. Surgery is rare, and limited sunlight is a risk factor for all children, not only dark-skinned children.', false),
  ('rickets', 35, 'A 2-year-old with rickets has low 25-hydroxyvitamin D, low serum calcium, and low serum phosphate. Vitamin D supplementation has been prescribed. Which additional treatment should the nurse anticipate as MOST likely?', '[{"id": "a", "text": "Surgery to correct the child''s bowed legs"}, {"id": "b", "text": "A diet that is low in dairy and eggs"}, {"id": "c", "text": "Avoiding sunlight until the bones harden"}, {"id": "d", "text": "Calcium and phosphate supplements"}]'::jsonb, '["d"]', 'Treatment of rickets includes vitamin D supplementation plus calcium and phosphate supplements as needed when these levels are low. Surgery is rare and only for severe deformities, and dairy, eggs, and sunlight support treatment.', false),
  ('rickets', 36, 'A 3-year-old has received vitamin D and calcium supplements for rickets for 3 months, and follow-up labs were drawn. Which changes from the baseline results indicate that treatment is progressing? Select all that apply.', '[{"id": "a", "text": "Alkaline phosphatase rising"}, {"id": "b", "text": "Serum calcium rising"}, {"id": "c", "text": "25-hydroxyvitamin D rising"}, {"id": "d", "text": "Serum phosphate falling"}, {"id": "e", "text": "Alkaline phosphatase falling"}]'::jsonb, '["b", "c", "e"]', 'Rickets presents with low serum calcium, low serum phosphate, low 25-hydroxyvitamin D, and elevated alkaline phosphatase from active bone turnover. Progress is shown by calcium rising (b), 25-hydroxyvitamin D rising (c), and alkaline phosphatase falling (e). A rising alkaline phosphatase (a) and falling phosphate (d) move further from normal.', true),
  ('rickets', 37, 'A 2-year-old with bowed legs has a low serum calcium and low phosphate. The parent asks why another blood test is being drawn when "the calcium already shows the problem." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"The new test checks how fast the bones are turning over.\""}, {"id": "b", "text": "\"The new test checks for chronic kidney disease first.\""}, {"id": "c", "text": "\"The 25-hydroxyvitamin D test is the most accurate one.\""}, {"id": "d", "text": "\"The new test is needed before an X-ray can be taken.\""}]'::jsonb, '["c"]', '25-hydroxyvitamin D is the most accurate test for vitamin D levels, so it confirms the vitamin D deficiency suggested by low calcium and phosphate. Bone turnover is reflected by alkaline phosphatase.', false),
  ('rickets', 38, 'The parent of a newly diagnosed 18-month-old asks the nurse what "defective mineralization" in the child''s rickets diagnosis means. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Growing bones do not harden with calcium and phosphate.\""}, {"id": "b", "text": "\"The bones are breaking down because of a bacterial infection.\""}, {"id": "c", "text": "\"The bones are growing too quickly for the child''s age.\""}, {"id": "d", "text": "\"The muscles are too weak to hold the bones straight.\""}]'::jsonb, '["a"]', 'Mineralization is the process of hardening bones with minerals like calcium and phosphate; in rickets this is defective in the growing bones, leading to soft bones.', false),
  ('rickets', 39, 'The nurse evaluates discharge teaching with the parents of a 2-year-old with rickets. Which statements by the parents indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"Fortified milk, eggs, and cereal help the bones grow.\""}, {"id": "b", "text": "\"We will stop the vitamin D once the child walks.\""}, {"id": "c", "text": "\"We will give the supplements as prescribed.\""}, {"id": "d", "text": "\"We will go to follow-up labs to check treatment progress.\""}, {"id": "e", "text": "\"Sunlight, food, and supplements all give vitamin D.\""}]'::jsonb, '["a", "c", "d", "e"]', 'Fortified milk, egg, and cereal support bone growth (a), supplements are given as prescribed (c), follow-up labs check treatment progress (d), and sunlight, food, and supplements are vitamin D sources (e). Stopping vitamin D once the child walks (b) is incorrect because supplements are given as prescribed and labs track progress.', true),
  ('rickets', 40, 'A toddler presents with bowing of the legs, delayed walking, and irritability. Labs show low calcium and low vitamin D. Which prescription should the nurse anticipate FIRST?', '[{"id": "a", "text": "Surgical correction of the bowed legs"}, {"id": "b", "text": "Vitamin D supplementation"}, {"id": "c", "text": "Restriction of outdoor activity"}, {"id": "d", "text": "Low-phosphate diet"}]'::jsonb, '["b"]', 'These findings indicate rickets, which is treated first with vitamin D supplementation, plus calcium and phosphate as needed. Surgery is rare and only for severe deformities, and outdoor play with safe sun exposure is encouraged.', false),
  ('rickets', 41, 'A 6-year-old who was treated for rickets as a toddler is seen by the school nurse. The parent reports that the child''s new adult teeth look chalky and pitted. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The teeth findings mean the rickets has become osteomalacia"}, {"id": "b", "text": "The teeth findings are caused by vitamin D supplements"}, {"id": "c", "text": "The teeth findings mean surgery is needed for deformity"}, {"id": "d", "text": "Enamel defects are among the teeth issues seen in rickets"}]'::jsonb, '["d"]', 'Teeth issues in rickets include delayed eruption and enamel defects. Osteomalacia is the name for the same condition in adults, and surgery is reserved for severe bone deformities.', false),
  ('rickets', 42, 'A 7-month-old with rickets has severe hypocalcemia on admission labs. The infant is jittery and irritable. Which nursing actions are appropriate at this time? Select all that apply.', '[{"id": "a", "text": "Encourage outdoor play this afternoon"}, {"id": "b", "text": "Monitor for seizures"}, {"id": "c", "text": "Delay labs until supplements are finished"}, {"id": "d", "text": "Withhold all supplements until calcium is normal"}, {"id": "e", "text": "Administer calcium supplements as prescribed"}]'::jsonb, '["b", "e"]', 'Nurses monitor for seizures in severe hypocalcemia (b) and administer supplements, including calcium, as prescribed (e). Outdoor play (a) is part of long-term care, not the priority during severe hypocalcemia; follow-up labs track progress rather than being delayed (c); and supplements are given, not withheld, when calcium is low (d).', true),
  ('rickets', 43, 'A 3-year-old with rickets cries when picked up under the arms and refuses to walk across the room. The child had been walking well for months. Which nursing action is the PRIORITY?', '[{"id": "a", "text": "Encourage the child to walk to build strength"}, {"id": "b", "text": "Reassure the parent that crying is normal at this age"}, {"id": "c", "text": "Assess for bone pain and report the findings"}, {"id": "d", "text": "Offer a snack of fortified cereal and milk first"}]'::jsonb, '["c"]', 'Nurses assess for bone pain or delayed milestones in rickets; a child who cries with handling and refuses to walk needs this assessment reported. Nutrition is important but does not take priority over a new pain finding.', false),
  ('rickets', 44, 'At an 18-month follow-up visit, a child being treated for rickets is not yet walking, and the parent says the child stopped trying to pull up to stand. Which nursing action is MOST appropriate?', '[{"id": "a", "text": "Assess for delayed milestones and report them"}, {"id": "b", "text": "Tell the parent to wait until the child is 3 years old"}, {"id": "c", "text": "Stop the vitamin D because it is not helping"}, {"id": "d", "text": "Recommend surgery to straighten the child''s legs"}]'::jsonb, '["a"]', 'Delayed walking is a delayed milestone, which the nurse assesses for and reports along with monitoring growth and development regularly. Supplements are continued as prescribed, and surgery is rare and reserved for severe deformities.', false),
  ('rickets', 45, 'The nurse is teaching the caregivers of a 2-year-old with rickets about vitamin D. Which statements about sources of vitamin D should the nurse include? Select all that apply.', '[{"id": "a", "text": "\"Sunlight is a source of vitamin D.\""}, {"id": "b", "text": "\"Supplements are not needed if the child eats fish.\""}, {"id": "c", "text": "\"Food such as eggs and fish provides vitamin D.\""}, {"id": "d", "text": "\"Supplements are a source of vitamin D.\""}, {"id": "e", "text": "\"Sunlight should be avoided while bones are soft.\""}]'::jsonb, '["a", "c", "d"]', 'Caregivers are educated on vitamin D sources: sunlight (a), food such as eggs and fish (c), and supplements (d). Supplements are administered as prescribed regardless of a single food choice (b), and outdoor play with safe sun exposure is encouraged rather than avoided (e).', true),
  ('rickets', 46, 'A 3-year-old with rickets stands with the knees touching while the ankles are spread apart. The parent asks what this is called. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"These are bowed legs, which are called genu varum.\""}, {"id": "b", "text": "\"These are knock-knees, a valgus deformity.\""}, {"id": "c", "text": "\"This is Harrison''s groove in the legs.\""}, {"id": "d", "text": "\"This is craniotabes affecting the legs.\""}]'::jsonb, '["b"]', 'Knees touching with the ankles apart are knock-knees (genu valgum), a valgus deformity of rickets. Bowed legs are genu varum, Harrison''s groove is an indented chest, and craniotabes is a soft skull.', false),
  ('rickets', 47, 'The nurse is caring for four children with rickets. Which child should the nurse see FIRST?', '[{"id": "a", "text": "A 3-year-old with bowed legs and enlarged wrists"}, {"id": "b", "text": "A 2-year-old with a rachitic rosary and irritability"}, {"id": "c", "text": "A 4-year-old with knock-knees and stunted growth"}, {"id": "d", "text": "A 9-month-old with severe hypocalcemia on new labs"}]'::jsonb, '["d"]', 'Severe hypocalcemia puts the infant at risk for seizures, so this child is seen first. Bowed legs, enlarged wrists, rachitic rosary, knock-knees, and stunted growth are expected signs of rickets.', false),
  ('rickets', 48, 'The parent of a 2-year-old with rickets is shown the child''s knee X-ray and asks why the ends of the bones look wide and irregular. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"The X-ray shows healing fractures in both knees.\""}, {"id": "b", "text": "\"The X-ray shows bones that have hardened too much.\""}, {"id": "c", "text": "\"Rickets causes widened growth plates and fraying.\""}, {"id": "d", "text": "\"The X-ray shows an infection near the growth plates.\""}]'::jsonb, '["c"]', 'X-rays in rickets show cupping/fraying of the metaphysis, widened growth plates, and bone softening. The bones are soft from defective mineralization, not over-hardened.', false),
  ('rickets', 49, 'A 5-year-old born at term, with normal kidney function and no digestive disorders, has spent 4 months indoors recovering from a long illness. The child now has bone pain, and the 25-hydroxyvitamin D is low. Which factor MOST likely contributed to this finding?', '[{"id": "a", "text": "Lack of sun exposure"}, {"id": "b", "text": "Lower stores of vitamin D at birth"}, {"id": "c", "text": "Impaired vitamin D activation"}, {"id": "d", "text": "Malabsorption of vitamin D"}]'::jsonb, '["a"]', 'Vitamin D deficiency from lack of sun exposure is a cause of rickets, and limited sunlight exposure is a risk factor. Lower stores relate to premature birth, impaired activation to chronic kidney disease, and malabsorption to disorders such as celiac disease and cystic fibrosis, none of which this child has.', false),
  ('rickets', 50, 'A clinic nurse reviews the charts of four 3-month-old infants. Which infant is at the HIGHEST risk for developing rickets?', '[{"id": "a", "text": "Light-skinned, sunny area, gets vitamin D drops"}, {"id": "b", "text": "Dark-skinned, northern climate, breastfed, no vitamin D"}, {"id": "c", "text": "Term, daily outdoor walks, gets vitamin D drops"}, {"id": "d", "text": "Term, exclusively breastfed, gets vitamin D supplementation"}]'::jsonb, '["b"]', 'Dark skin (reduced skin production of vitamin D), a northern climate, and exclusive breastfeeding without vitamin D supplementation are all risk factors or causes of rickets. The other infants receive vitamin D supplementation and lack these risks.', false),
  ('ortho', 1, 'During the newborn examination of a 1-day-old girl born in breech position, the nurse adducts the hip with gentle pressure and the hip dislocates. Which finding is the nurse MOST likely to document?', '[{"id": "a", "text": "Positive Ortolani sign"}, {"id": "b", "text": "Positive Trendelenburg sign"}, {"id": "c", "text": "Positive Barlow sign"}, {"id": "d", "text": "Limited hip abduction"}]'::jsonb, '["c"]', 'A hip that dislocates when adducted with pressure is a positive Barlow sign. The Ortolani sign is a click felt or heard when the hip is gently abducted, and the Trendelenburg sign is seen in older infants/children who stand on the affected leg.', false),
  ('ortho', 2, 'The nurse is assessing a 3-week-old girl, first-born, who was in breech position. Which findings would support developmental dysplasia of the hip? Select all that apply.', '[{"id": "a", "text": "Limited hip abduction"}, {"id": "b", "text": "Positive Ortolani sign"}, {"id": "c", "text": "Asymmetrical gluteal/thigh folds"}, {"id": "d", "text": "Uneven leg length"}, {"id": "e", "text": "Waddling gait"}]'::jsonb, '["a", "b", "c", "d"]', 'Correct: in infants under 2–3 months, DDH shows asymmetrical gluteal/thigh folds (c), uneven leg length (d), limited hip abduction (a), and a positive Ortolani sign — a click when the hip is gently abducted (b). Wrong: a waddling gait is seen in older infants/children who are walking (e).', true),
  ('ortho', 3, 'A 3-year-old with late-diagnosed developmental dysplasia of the hip is asked to stand on the left leg, and the nurse observes the right hip drop. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Positive Trendelenburg sign; the right hip is the affected hip"}, {"id": "b", "text": "Positive Barlow sign; the left hip dislocates on adduction"}, {"id": "c", "text": "Positive Ortolani sign; the right hip clicks on abduction"}, {"id": "d", "text": "Positive Trendelenburg sign; the left hip is the affected hip"}]'::jsonb, '["d"]', 'In a positive Trendelenburg sign, the hip drops on the unaffected side when the child stands on the affected leg — so standing on the left with the right hip dropping means the left hip is affected. Barlow and Ortolani are infant examination maneuvers.', false),
  ('ortho', 4, 'The parent of a 2-month-old in a Pavlik harness for DDH says, ''The straps look tight after her growth spurt.'' Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "I''ll keep the harness on until the HCP says otherwise."}, {"id": "b", "text": "I''ll adjust the harness straps myself if they''re tight."}, {"id": "c", "text": "I''ll place her diaper under the harness straps."}, {"id": "d", "text": "I''ll call the HCP to have the straps checked."}]'::jsonb, '["b"]', 'Pavlik harness straps are not adjusted by parents — HCP only. Keeping the harness on and placing the diaper under the harness are correct care.', false),
  ('ortho', 5, 'The nurse observes the parent of a 6-week-old in a Pavlik harness change a diaper. Which parent action indicates understanding of harness care?', '[{"id": "a", "text": "Placing the new diaper over the top of the harness straps"}, {"id": "b", "text": "Taking the harness off to change the diaper"}, {"id": "c", "text": "Placing the new diaper under the harness straps"}, {"id": "d", "text": "Putting two diapers on under the harness"}]'::jsonb, '["c"]', 'The diaper is placed under the harness. The harness is not removed unless ordered, and double-diapering is avoided.', false),
  ('ortho', 6, 'A 3-month-old in a Pavlik harness has a red area of skin near the shoulder strap. The nurse observes the parent preparing to rub baby powder under the strap. Which action by the nurse is BEST?', '[{"id": "a", "text": "Allow the powder, since it keeps the skin dry"}, {"id": "b", "text": "Stop the parent; no lotions or powders under straps"}, {"id": "c", "text": "Tell the parent to use lotion instead of powder"}, {"id": "d", "text": "Remove the harness for an hour so the skin can air out"}]'::jsonb, '["b"]', 'No lotions or powders are used under the straps, and skin under the straps is assessed for breakdown. Removing the harness is not done unless ordered.', false),
  ('ortho', 7, 'The nurse checks a 4-month-old who has been in a Pavlik harness for 2 weeks. Which observation BEST indicates the harness is positioning the hips correctly?', '[{"id": "a", "text": "Hips extended and legs held together"}, {"id": "b", "text": "Hips flexed and thighs abducted"}, {"id": "c", "text": "Hips extended and thighs abducted"}, {"id": "d", "text": "Hips flexed and thighs adducted"}]'::jsonb, '["b"]', 'The Pavlik harness is a soft brace holding the hips in a flexed and abducted position. Abduction (movement away from the body) is important for DDH correction.', false),
  ('ortho', 8, 'The parents of a 1-month-old who was just fitted with a Pavlik harness ask how long treatment will last. Which statement by a parent indicates understanding?', '[{"id": "a", "text": "It is worn at night for 6–12 weeks."}, {"id": "b", "text": "It is worn 24/7 for 6–12 weeks."}, {"id": "c", "text": "It is worn 24/7 for 6–12 months."}, {"id": "d", "text": "It is worn 18–23 hours a day for a year."}]'::jsonb, '["b"]', 'The Pavlik harness is worn 24/7 for 6–12 weeks. Wearing a brace 18–23 hrs/day is the Boston brace schedule for moderate scoliosis.', false),
  ('ortho', 9, 'A 4-month-old has worn a Pavlik harness 24/7 for 12 weeks, but the follow-up examination shows the hip is still unstable. Which treatment should the nurse anticipate NEXT?', '[{"id": "a", "text": "A spica cast holding the hips and legs"}, {"id": "b", "text": "Continuing the Pavlik harness at night only"}, {"id": "c", "text": "Serial casting of the feet changed weekly"}, {"id": "d", "text": "A Boston brace worn 18–23 hrs/day"}]'::jsonb, '["a"]', 'A spica cast is used if the Pavlik harness fails or for older infants; it is a rigid cast holding the hips and legs in position. Serial casting changed weekly is the Ponseti method for clubfoot.', false),
  ('ortho', 10, 'A 7-month-old with DDH is being discharged in a spica cast that extends from the chest to the legs. Which item is the PRIORITY to confirm before the family leaves?', '[{"id": "a", "text": "A standard rear-facing infant car seat"}, {"id": "b", "text": "A special car seat for the spica cast"}, {"id": "c", "text": "Baby powder to use at the cast edges"}, {"id": "d", "text": "A second diaper to layer under the cast"}]'::jsonb, '["b"]', 'A spica cast is a rigid cast from chest to legs and requires a special car seat. Powder is not used under DDH devices, and double-diapering is avoided.', false),
  ('ortho', 11, 'An infant with DDH is being treated in a Pavlik harness. Which assessments are part of the neurovascular check performed every shift? Select all that apply.', '[{"id": "a", "text": "Sensation and movement"}, {"id": "b", "text": "Color"}, {"id": "c", "text": "Temperature"}, {"id": "d", "text": "Ortolani click"}, {"id": "e", "text": "Cap refill"}]'::jsonb, '["a", "b", "c", "e"]', 'Correct: neurovascular checks every shift include color (b), temperature (c), cap refill (e), and sensation and movement (a). Wrong: the Ortolani click is a hip examination finding for DDH diagnosis, not a neurovascular check (d).', true),
  ('ortho', 12, 'At a weekly visit, the nurse examines a 2-month-old in a Pavlik harness. Which finding requires follow-up FIRST?', '[{"id": "a", "text": "Hips held flexed and abducted by the harness"}, {"id": "b", "text": "Diaper placed under the harness straps"}, {"id": "c", "text": "Skin breakdown under the leg straps"}, {"id": "d", "text": "Toes pink and warm with brisk cap refill"}]'::jsonb, '["c"]', 'The skin under the straps is assessed for breakdown, so skin breakdown needs follow-up. Flexed and abducted hips and a diaper placed under the harness are correct.', false),
  ('ortho', 13, 'The nurse observes the mother of a 1-week-old girl swaddle the infant with both legs wrapped tightly straight and together. Which response by the nurse is BEST?', '[{"id": "a", "text": "Tight swaddling helps keep her hips stable in place."}, {"id": "b", "text": "Tight swaddling is a risk factor for hip dysplasia."}, {"id": "c", "text": "Tight swaddling is fine once a hip exam is normal."}, {"id": "d", "text": "Tight swaddling is a risk factor for clubfoot."}]'::jsonb, '["b"]', 'Tight swaddling is a risk factor for DDH. Clubfoot is associated with neuromuscular disorders or oligohydramnios, not swaddling.', false),
  ('ortho', 14, 'The nurse reviews four newborn histories. Which newborn is at HIGHEST risk for developmental dysplasia of the hip?', '[{"id": "a", "text": "First-born girl in breech position"}, {"id": "b", "text": "Second-born boy delivered head-first"}, {"id": "c", "text": "Second-born girl with loose swaddling"}, {"id": "d", "text": "First-born boy with no family history"}]'::jsonb, '["a"]', 'DDH mostly occurs in girls, first-born infants, breech position, or with family history. The first-born girl in breech position has the most risk factors.', false),
  ('ortho', 15, 'The parent of a 5-week-old in a Pavlik harness says, ''She smells, so I''d like to take the harness off for a full bath each evening.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Never remove the harness unless it is ordered."}, {"id": "b", "text": "That is fine if you put it back on right after the bath."}, {"id": "c", "text": "You can remove it at night since she is lying still."}, {"id": "d", "text": "Remove it for baths, but not for more than an hour."}]'::jsonb, '["a"]', 'Never remove the harness unless ordered; it is worn 24/7 for 6–12 weeks. Removing it for baths or at night interrupts treatment.', false),
  ('ortho', 16, 'A 3-week-old with clubfoot had a new cast applied 2 hours ago. The nurse finds the toes pale with a cap refill of 4 seconds. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Recheck the toes at the next scheduled assessment"}, {"id": "b", "text": "Elevate the foot and recheck in a few hours"}, {"id": "c", "text": "Report the findings to the HCP immediately"}, {"id": "d", "text": "Teach the parent to check the toes every shift"}]'::jsonb, '["c"]', 'If toes are pale or cap refill is >3 seconds after clubfoot casting, report immediately. Waiting or rechecking later delays care for compromised circulation.', false),
  ('ortho', 17, 'The parent of a 6-week-old with clubfoot asks why the infant needs an Achilles tenotomy after several weeks of serial casting. Which response by the nurse is BEST?', '[{"id": "a", "text": "The tendon is cut so a spica cast can be applied."}, {"id": "b", "text": "The tendon is cut because casting has damaged it."}, {"id": "c", "text": "The tendon is cut to replace the need for later bracing."}, {"id": "d", "text": "The tendon is cut to allow correction of the foot."}]'::jsonb, '["d"]', 'An Achilles tenotomy is a tendon cut to allow correction, and it may be required during Ponseti treatment. Bracing (e.g., Denis Browne bar) still follows.', false),
  ('ortho', 18, 'A newborn''s right foot is twisted inward and downward and cannot be moved to a neutral position. The parent asks why the foot will not straighten. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "The tendons and ligaments of the foot are shortened."}, {"id": "b", "text": "The hip socket did not develop normally before birth."}, {"id": "c", "text": "The spine has a sideways curve with rotation."}, {"id": "d", "text": "The foot bones are fractured from a breech birth."}]'::jsonb, '["a"]', 'Clubfoot (talipes equinovarus) is a congenital deformity with the foot twisted inward and downward that involves shortened tendons and ligaments. Abnormal hip socket development describes DDH.', false),
  ('ortho', 19, 'The nurse reviews the history of a newborn with talipes equinovarus. Which findings are associated with this deformity? Select all that apply.', '[{"id": "a", "text": "Adolescent girl in the family"}, {"id": "b", "text": "Positive Barlow sign"}, {"id": "c", "text": "Oligohydramnios"}, {"id": "d", "text": "Tight swaddling"}, {"id": "e", "text": "Neuromuscular disorders"}]'::jsonb, '["c", "e"]', 'Correct: clubfoot is associated with oligohydramnios — low amniotic fluid (c) — and neuromuscular disorders (e). Wrong: tight swaddling is a DDH risk factor (d); idiopathic scoliosis is most common in adolescent girls (a); a positive Barlow sign is a DDH finding (b).', true),
  ('ortho', 20, 'The nurse explains the treatment plan to the parents of a 5-day-old with clubfoot. Which sequence of treatment is MOST accurate?', '[{"id": "a", "text": "Serial casting, Achilles tenotomy if needed, then bracing"}, {"id": "b", "text": "Bracing first, then serial casting, then tenotomy if needed"}, {"id": "c", "text": "Achilles tenotomy first, then bracing, then serial casting"}, {"id": "d", "text": "Spica cast first, then serial casting, then bracing"}]'::jsonb, '["a"]', 'Ponseti serial casting begins within the first 1–2 weeks, an Achilles tenotomy may be required, and bracing (e.g., Denis Browne bar) follows. A spica cast is used for DDH.', false),
  ('ortho', 21, 'The parent of a 3-week-old with clubfoot asks why the infant gets a new cast every week instead of one cast. Which response by the nurse is BEST?', '[{"id": "a", "text": "A new cast each week keeps the old cast from smelling bad."}, {"id": "b", "text": "Weekly casts let the hip stay flexed and abducted as it grows."}, {"id": "c", "text": "Each new cast is larger because the foot is swelling."}, {"id": "d", "text": "Repeated casting over time gradually corrects the deformity."}]'::jsonb, '["d"]', 'Serial casting means repeated casting over time to gradually correct deformity; Ponseti casts are changed weekly. Flexed and abducted hips relate to the Pavlik harness for DDH.', false),
  ('ortho', 22, 'The parent of a 4-week-old in a clubfoot cast is learning when to call. Which findings should the parent report IMMEDIATELY? Select all that apply.', '[{"id": "a", "text": "Toes that wiggle when touched"}, {"id": "b", "text": "Infant fussy during the cast change"}, {"id": "c", "text": "Toes that look pale"}, {"id": "d", "text": "Toes pink with cap refill of 2 seconds"}, {"id": "e", "text": "Cap refill of 4 seconds"}]'::jsonb, '["c", "e"]', 'Correct: pale toes (c) or cap refill >3 seconds, such as 4 seconds (e), are reported immediately. Wrong: pink toes with a 2-second cap refill (d) and toes that move (a) indicate good circulation and movement; fussiness during a cast change (b) is not a listed reason to report.', true),
  ('ortho', 23, 'The nurse is preparing discharge teaching for the parents of a 2-week-old who just received the first Ponseti cast for clubfoot. Which teaching plan is MOST appropriate?', '[{"id": "a", "text": "How to loosen and reapply the cast at home"}, {"id": "b", "text": "How to apply lotions or powders inside the cast"}, {"id": "c", "text": "When to switch from the cast to a Pavlik harness"}, {"id": "d", "text": "Proper skin care, cast care, and bracing schedules"}]'::jsonb, '["d"]', 'Parents of an infant with clubfoot are taught proper skin care, cast care, and bracing schedules. Nothing is put inside the cast, and the Pavlik harness is DDH treatment.', false),
  ('ortho', 24, 'During a school screening, a 12-year-old girl performs the Adam''s Forward Bend Test. Which finding suggests scoliosis and requires follow-up?', '[{"id": "a", "text": "A rib hump on one side when bending forward"}, {"id": "b", "text": "Hips level and spine straight when bending forward"}, {"id": "c", "text": "Hip drops when standing on one leg"}, {"id": "d", "text": "Both shoulders level when standing"}]'::jsonb, '["a"]', 'The Adam''s Forward Bend Test looks for asymmetry, rib hump, or shoulder/hip elevation as signs of scoliosis. A hip that drops when standing on one leg is a Trendelenburg sign of hip instability.', false),
  ('ortho', 25, 'The school nurse is performing the Adam''s Forward Bend Test on a 13-year-old. Which findings suggest scoliosis and should be referred? Select all that apply.', '[{"id": "a", "text": "Hip elevation"}, {"id": "b", "text": "Foot turned inward"}, {"id": "c", "text": "Rib hump"}, {"id": "d", "text": "Shoulder elevation"}, {"id": "e", "text": "Hip drops on one side"}]'::jsonb, '["a", "c", "d"]', 'Correct: the test looks for asymmetry, rib hump (c), and shoulder (d) or hip (a) elevation. Wrong: a hip that drops when standing on one leg is the Trendelenburg sign, which suggests hip instability rather than scoliosis (e); a foot twisted inward and downward is clubfoot (b).', true),
  ('ortho', 26, 'A school nurse is planning a scoliosis screening program. Which group of students should the nurse PRIORITIZE for screening with the Adam''s Forward Bend Test?', '[{"id": "a", "text": "Preschoolers starting kindergarten"}, {"id": "b", "text": "School-age and early adolescent students"}, {"id": "c", "text": "Older adolescents finishing their final year of high school"}, {"id": "d", "text": "Toddlers beginning to walk"}]'::jsonb, '["b"]', 'Scoliosis screening is performed during school-age or early adolescence. Idiopathic scoliosis, the most common type, occurs in adolescent girls.', false),
  ('ortho', 27, 'A spine X-ray is reviewed for four adolescents referred after screening. Which result is MOST consistent with scoliosis?', '[{"id": "a", "text": "Lateral curve of 8° without rotation"}, {"id": "b", "text": "Forward curve of 15° without rotation"}, {"id": "c", "text": "Lateral curve of 12° with rotation"}, {"id": "d", "text": "Lateral curve of 6° with rotation"}]'::jsonb, '["c"]', 'Scoliosis is a lateral (sideways) curvature of the spine >10°, often accompanied by rotation. Curves of 6° and 8° do not exceed 10°, and a forward curve is not lateral.', false),
  ('ortho', 28, 'The nurse reviews referrals from a school screening. Which student is MOST likely to have idiopathic scoliosis?', '[{"id": "a", "text": "Preschool boy with a waddling gait"}, {"id": "b", "text": "Infant girl with uneven leg length"}, {"id": "c", "text": "Newborn boy with a foot turned inward"}, {"id": "d", "text": "Adolescent girl with shoulder elevation"}]'::jsonb, '["d"]', 'Idiopathic scoliosis is the most common type and occurs in adolescent girls; shoulder elevation is an asymmetry finding. A waddling gait and uneven leg length are DDH findings.', false),
  ('ortho', 29, 'The nurse reviews spinal curve measurements for five adolescents with idiopathic scoliosis. Which adolescents does the nurse anticipate will be managed with a Boston brace? Select all that apply.', '[{"id": "a", "text": "45° curvature"}, {"id": "b", "text": "15° curvature"}, {"id": "c", "text": "22° curvature"}, {"id": "d", "text": "35° curvature"}, {"id": "e", "text": "40° curvature"}]'::jsonb, '["c", "d", "e"]', 'Correct: moderate curves of 20–40°, including 22° (c), 35° (d), and 40° (e), are managed with bracing (e.g., Boston brace). Wrong: a mild curve <20° such as 15° is managed with observation and exercises (b); a severe curve >40° such as 45° needs surgery (a).', true),
  ('ortho', 30, 'A 14-year-old with a 28° curve has worn a Boston brace for 1 month. Which statement by the adolescent indicates understanding?', '[{"id": "a", "text": "I wear it 12 hours a day, mostly while I sleep at night."}, {"id": "b", "text": "I keep it on about 20 hrs/day and remove it only for bathing."}, {"id": "c", "text": "I take it off for school and put it back on after dinner."}, {"id": "d", "text": "I''ll stop wearing it once my spine is straight again."}]'::jsonb, '["b"]', 'The Boston brace is worn 18–23 hrs/day and removed only for bathing; 20 hours falls within that range. Twelve hours is too little, and bracing is not curative, so the spine will not become straight.', false),
  ('ortho', 31, 'A 13-year-old with a 30° curve has worn a Boston brace as directed for 6 months. Which follow-up X-ray result BEST indicates the brace is achieving its expected goal?', '[{"id": "a", "text": "Curvature now measures 10°"}, {"id": "b", "text": "Curvature unchanged at 30°"}, {"id": "c", "text": "Curvature now measures 42°"}, {"id": "d", "text": "Curvature now measures 36°"}]'::jsonb, '["b"]', 'Bracing is not curative — it prevents worsening, so a curve that has not progressed shows the expected effect. A curve that worsens to >40° would need surgery.', false),
  ('ortho', 32, 'A 14-year-old with a 26° curve has been wearing a Boston brace for 2 months. Which statements by the adolescent indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "I wear it 18 to 23 hours every day."}, {"id": "b", "text": "It is meant to keep my curve from getting worse."}, {"id": "c", "text": "The brace will correct my curvature completely."}, {"id": "d", "text": "I take it off when I shower."}, {"id": "e", "text": "The brace is worn only at night."}]'::jsonb, '["c", "e"]', 'Correct (need teaching): bracing is not curative, so the curve will not be gone (c); wearing it only at night is less than 18–23 hrs/day (e). Wrong (correct understanding): the brace is removed only for bathing (d), worn 18–23 hrs/day (a), and prevents worsening (b).', true),
  ('ortho', 33, 'A 15-year-old is 1 day post-op after spinal fusion with rods. The nurse observes the unlicensed assistive personnel (UAP) repositioning the adolescent. Which action by the UAP requires IMMEDIATE intervention?', '[{"id": "a", "text": "Turning the teen with a second staff member"}, {"id": "b", "text": "Keeping the shoulders and hips aligned while turning"}, {"id": "c", "text": "Asking the teen to twist to the side using the rails"}, {"id": "d", "text": "Placing a pillow between the knees after the turn is done"}]'::jsonb, '["c"]', 'After spinal fusion, the child is log-rolled when repositioning so the spine stays aligned; twisting by pulling on the rails defeats log-rolling. Turning with help and keeping shoulders and hips aligned are consistent with log-rolling.', false),
  ('ortho', 34, 'A 14-year-old is 1 day post-op after spinal fusion for a 48° curve. Vital signs are stable and pain is controlled, but the teen says, ''I just want to stay in bed today.'' Which action by the nurse is BEST?', '[{"id": "a", "text": "Encourage ambulation and deep breathing as planned"}, {"id": "b", "text": "Allow the teen to stay in bed until the pain is gone"}, {"id": "c", "text": "Delay ambulation until the rods have fully healed"}, {"id": "d", "text": "Teach the teen to sit up by twisting at the waist"}]'::jsonb, '["a"]', 'After spinal fusion, the nurse encourages ambulation and deep breathing. Delaying activity is not part of post-op care, and twisting conflicts with log-rolling.', false),
  ('ortho', 35, 'A 15-year-old is 8 hours post-op after spinal fusion with rods. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Pain 3/10 after the scheduled analgesic"}, {"id": "b", "text": "Pale toes with slow cap refill"}, {"id": "c", "text": "Sitting at the edge of the bed with help"}, {"id": "d", "text": "Asks to be log-rolled onto the side"}, {"id": "e", "text": "Cannot move the toes on either foot"}]'::jsonb, '["b", "e"]', 'Correct: inability to move the toes may signal spinal cord compromise (e), and pale toes with slow cap refill reflect impaired neurovascular status (b). Wrong: pain 3/10 after analgesia shows pain is managed (a); sitting up with help supports ambulation (c); log-rolling is the correct repositioning method (d).', true),
  ('ortho', 36, 'A 13-year-old who started wearing a Boston brace 3 weeks ago has stopped going to lunch with friends and wears oversized sweatshirts. Which statement by the adolescent BEST indicates that psychosocial support has been effective?', '[{"id": "a", "text": "I stay home from school on days my brace feels most noticeable."}, {"id": "b", "text": "I only wear my brace when nobody can see me."}, {"id": "c", "text": "I would rather have surgery right now than keep wearing this brace."}, {"id": "d", "text": "I talked with friends about my brace and went back to lunch."}]'::jsonb, '["d"]', 'Bracing requires psychosocial support because body image concerns are common; returning to peer activities while wearing the brace shows effective coping. Wearing the brace only when unseen reduces wear time below 18–23 hrs/day.', false),
  ('ortho', 37, 'The parent of a 2-month-old newly placed in a Pavlik harness asks why the harness holds the baby''s thighs spread apart. Which response by the nurse is BEST?', '[{"id": "a", "text": "Holding the thighs together keeps the hip from dislocating."}, {"id": "b", "text": "Spreading the thighs stretches the shortened tendons in the feet."}, {"id": "c", "text": "Movement away from the body is important for DDH correction."}, {"id": "d", "text": "Spreading the thighs helps prevent a sideways curve of the spine."}]'::jsonb, '["c"]', 'Abduction — movement away from the body — is important for DDH correction, which is why the Pavlik harness maintains hip flexion/abduction. Shortened tendons describe clubfoot.', false),
  ('ortho', 38, 'The nurse receives report on four children on a pediatric orthopedic unit. Which child should the nurse assess FIRST?', '[{"id": "a", "text": "Pavlik harness; diaper placed under the straps"}, {"id": "b", "text": "Late DDH; walks with a limping, waddling gait"}, {"id": "c", "text": "Post-op spinal fusion; cannot move toes or legs"}, {"id": "d", "text": "Boston brace; body image concerns about her looks"}]'::jsonb, '["c"]', 'Loss of movement after spinal fusion suggests spinal cord compromise and neurovascular change, so this teen is seen first. A waddling gait is expected with late DDH, the diaper is correctly placed, and body image concerns need support but are not urgent.', false),
  ('ortho', 39, 'The parent of a 1-week-old diagnosed with DDH asks, ''What exactly is wrong with her hip?'' Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "The hip socket or femoral head developed abnormally."}, {"id": "b", "text": "The tendons and ligaments around the hip are too short to move."}, {"id": "c", "text": "The hip bone broke during the breech delivery and needs a cast."}, {"id": "d", "text": "The spine curved sideways and pulled the hip out of position."}]'::jsonb, '["a"]', 'DDH means the hip joint is dislocated or unstable at birth due to abnormal development of the acetabulum (hip socket) or femoral head. Shortened tendons and ligaments describe clubfoot.', false),
  ('ortho', 40, 'A 3-week-old in a new clubfoot cast is fussy after the weekly cast change. The toes are pink and warm with a cap refill of 2 seconds. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Report the findings to the HCP immediately"}, {"id": "b", "text": "Ask the HCP to remove the cast early"}, {"id": "c", "text": "Continue toe checks and support the infant"}, {"id": "d", "text": "Place a soft cloth inside the cast near the toes"}]'::jsonb, '["c"]', 'Toes are reported immediately only if they are pale or cap refill is >3 seconds; pink, warm toes with a 2-second refill are reassuring. Nothing is ever placed inside the cast.', false),
  ('ortho', 41, 'The nurse is reviewing infants referred for DDH. Which infants are candidates for a Pavlik harness? Select all that apply.', '[{"id": "a", "text": "A 5-month-old with a positive Ortolani sign"}, {"id": "b", "text": "A 7-month-old in whom earlier treatment failed"}, {"id": "c", "text": "An 18-month-old with a waddling gait"}, {"id": "d", "text": "A 2-month-old with a positive Barlow sign"}, {"id": "e", "text": "A 9-month-old with limited hip abduction"}]'::jsonb, '["a", "d"]', 'Correct: the Pavlik harness is used for infants <6 months, such as the 2-month-old (d) and the 5-month-old (a). Wrong: the 9-month-old (e) and 18-month-old (c) are older infants, and the 7-month-old whose treatment failed (b) needs a spica cast, used if Pavlik fails or for older infants.', true),
  ('ortho', 42, 'A 6-week-old has asymmetrical thigh folds. With the infant supine and the hips and knees flexed, the nurse notes one knee is lower than the other. Which additional finding would the nurse MOST likely expect?', '[{"id": "a", "text": "Rib hump when the infant is held prone"}, {"id": "b", "text": "Foot twisted inward and downward"}, {"id": "c", "text": "Hip drops when standing on one leg at a time"}, {"id": "d", "text": "Limited hip abduction on the affected side"}]'::jsonb, '["d"]', 'In infants under 2–3 months, DDH shows asymmetrical gluteal/thigh folds, uneven leg length, and limited hip abduction. The Trendelenburg sign requires standing, so it is seen in older infants/children.', false),
  ('ortho', 43, 'The parent of a 3-month-old in a Pavlik harness asks the nurse to tighten a strap that seems loose after the infant''s bath. Which action by the nurse is BEST?', '[{"id": "a", "text": "Do not adjust straps; report to the HCP to adjust"}, {"id": "b", "text": "Tighten the strap to the parent''s preferred fit"}, {"id": "c", "text": "Have the parent tighten the strap while the nurse observes"}, {"id": "d", "text": "Remove the harness until the HCP can refit it"}]'::jsonb, '["a"]', 'Pavlik harness straps are adjusted by the HCP only. The harness is never removed unless ordered.', false),
  ('ortho', 44, 'The nurse is teaching the parents of a 3-month-old being discharged in a Pavlik harness. Which statements by the parents indicate understanding? Select all that apply.', '[{"id": "a", "text": "We''ll put her diaper under the harness."}, {"id": "b", "text": "We''ll loosen the straps when she fusses."}, {"id": "c", "text": "We''ll assess her skin under the straps for breakdown."}, {"id": "d", "text": "We''ll take it off each evening for a bath."}, {"id": "e", "text": "We''ll use no lotions or powders under straps."}]'::jsonb, '["a", "c", "e"]', 'Correct: the diaper goes under the harness (a), skin under the straps is assessed for breakdown (c), and no lotions or powders are used under straps (e). Wrong: straps are adjusted by the HCP only (b); the harness is never removed unless ordered (d).', true),
  ('ortho', 45, 'The parent of a 1-week-old with clubfoot asks what treatment will involve. Which elements should the nurse include? Select all that apply.', '[{"id": "a", "text": "Pavlik harness worn 24/7"}, {"id": "b", "text": "Serial casting by the Ponseti method"}, {"id": "c", "text": "Casts changed weekly"}, {"id": "d", "text": "Possible Achilles tenotomy"}, {"id": "e", "text": "Bracing with a Denis Browne bar"}]'::jsonb, '["b", "c", "d", "e"]', 'Correct: clubfoot treatment is Ponseti serial casting (b) begun within the first 1–2 weeks with casts changed weekly (c), possibly an Achilles tenotomy (d), followed by bracing such as a Denis Browne bar (e). Wrong: the Pavlik harness is DDH treatment for infants <6 months (a).', true),
  ('ortho', 46, 'A 3-year-old is diagnosed with DDH after the parents noticed a limp. Which findings would the nurse expect in this child? Select all that apply.', '[{"id": "a", "text": "Positive Trendelenburg sign"}, {"id": "b", "text": "Rib hump on forward bend"}, {"id": "c", "text": "Limping"}, {"id": "d", "text": "Foot twisted inward and downward"}, {"id": "e", "text": "Waddling gait"}]'::jsonb, '["a", "c", "e"]', 'Correct: older infants/children with DDH show limping (c), a waddling gait (e), and a positive Trendelenburg sign (a). Wrong: a rib hump on forward bending is a scoliosis screening finding (b); a foot twisted inward and downward is clubfoot (d).', true),
  ('ortho', 47, 'A 6-month-old is going home in a spica cast after Pavlik harness treatment failed. Which statements should the nurse include in discharge teaching? Select all that apply.', '[{"id": "a", "text": "It requires a special car seat"}, {"id": "b", "text": "It is used because the Pavlik harness failed"}, {"id": "c", "text": "It is a rigid cast holding the hips and legs"}, {"id": "d", "text": "It extends from the chest to the legs"}, {"id": "e", "text": "Parents may adjust it like harness straps"}]'::jsonb, '["a", "b", "c", "d"]', 'Correct: a spica cast is a rigid cast holding hips and legs in position (c) from chest to legs (d), requires a special car seat (a), and is used if the Pavlik harness fails or for older infants (b). Wrong: parents do not adjust DDH devices — even Pavlik straps are adjusted by the HCP only (e).', true),
  ('ortho', 48, 'A newborn girl born after a breech delivery is examined. When the nurse gently abducts the left hip, a ''click'' is felt. Which finding is the nurse MOST likely to document?', '[{"id": "a", "text": "Positive Barlow sign"}, {"id": "b", "text": "Positive Trendelenburg sign"}, {"id": "c", "text": "Uneven leg length"}, {"id": "d", "text": "Positive Ortolani sign"}]'::jsonb, '["d"]', 'A click felt or heard when the hip is gently abducted is a positive Ortolani sign. The Barlow sign is a hip that dislocates when adducted with pressure.', false),
  ('ortho', 49, 'The nurse in an orthopedic clinic reviews the day''s findings. Which findings require follow-up? Select all that apply.', '[{"id": "a", "text": "Positive Barlow sign in a 2-week-old"}, {"id": "b", "text": "Rib hump on forward bend in a 12-year-old"}, {"id": "c", "text": "Pink toes, cap refill 2 seconds, in a clubfoot cast"}, {"id": "d", "text": "Hips flexed and abducted in a Pavlik harness"}, {"id": "e", "text": "Open skin under a Pavlik harness strap"}]'::jsonb, '["a", "b", "e"]', 'Correct: skin under straps is assessed for breakdown, so open skin needs follow-up (e); a positive Barlow sign indicates DDH needing treatment (a); a rib hump on the Adam''s Forward Bend Test suggests scoliosis (b). Wrong: pink toes with a 2-second cap refill are reassuring (c); flexed and abducted hips show correct harness position (d).', true),
  ('ortho', 50, 'The parents of a 4-day-old with clubfoot of the left foot are reviewing teaching before the first casting appointment. Which statements by the parents indicate understanding? Select all that apply.', '[{"id": "a", "text": "We''ll wait until she walks to start the casts."}, {"id": "b", "text": "We won''t stick anything inside the cast."}, {"id": "c", "text": "Bracing comes first, and then the casts."}, {"id": "d", "text": "Casting should begin within the first 1–2 weeks of life."}, {"id": "e", "text": "Clubfoot can be unilateral or bilateral."}]'::jsonb, '["b", "d", "e"]', 'Correct: Ponseti serial casting begins within the first 1–2 weeks of life (d); clubfoot can be unilateral or bilateral (e); nothing is stuck inside the cast (b). Wrong: waiting until walking delays treatment that should begin in the first 1–2 weeks (a); bracing (e.g., Denis Browne bar) follows serial casting rather than coming first (c).', true),
  ('omphalocele', 1, 'A term newborn has just been delivered with intestines protruding through the umbilical ring inside a thin, transparent sac. The infant is already under a radiant warmer and crying vigorously. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Cover the sac with sterile saline-soaked gauze and plastic wrap"}, {"id": "b", "text": "Cover the sac with dry sterile gauze and then tape it to the abdomen"}, {"id": "c", "text": "Place the newborn skin-to-skin on the mother''s bare abdomen"}, {"id": "d", "text": "Offer the first breastfeeding to stabilize blood glucose"}]'::jsonb, '["a"]', 'The sac is protected with sterile saline-soaked gauze plus plastic wrap to prevent drying and rupture. Dry gauze lets the sac dry out, and the infant is NPO before surgical repair.', false),
  ('omphalocele', 2, 'A newborn with a membrane-covered defect at the umbilicus has been placed in an open bassinet in the delivery room while the parents hold the infant''s hand. Which action is the nurse''s PRIORITY to prevent a complication related to the exposed organs?', '[{"id": "a", "text": "Insert an NG tube to decompress the stomach"}, {"id": "b", "text": "Obtain blood for lab/genetic workup"}, {"id": "c", "text": "Move the newborn to a radiant warmer or incubator"}, {"id": "d", "text": "Position the newborn supine with knees slightly flexed"}]'::jsonb, '["c"]', 'Organs outside the body cause high heat loss, so the newborn is placed under a radiant warmer or incubator immediately to prevent hypothermia. NG insertion, positioning, and genetic workup are needed but do not address the immediate heat loss in an open bassinet.', false),
  ('omphalocele', 3, 'A 1-hour-old newborn with intestines and part of the liver protruding into a membrane-covered sac at the umbilicus is awaiting surgical repair. Which prescriptions should the nurse expect to implement before surgery? Select all that apply.', '[{"id": "a", "text": "Cover the sac with sterile saline-soaked gauze + plastic wrap"}, {"id": "b", "text": "Place under a radiant warmer or incubator"}, {"id": "c", "text": "Offer small, frequent breastfeedings"}, {"id": "d", "text": "Start IV fluids"}, {"id": "e", "text": "Insert an NG tube"}]'::jsonb, '["a", "b", "d", "e"]', 'Pre-surgical care includes protecting the sac with saline-soaked gauze and plastic wrap (a), preventing hypothermia with a radiant warmer or incubator (b), IV fluids for high fluid/heat loss (d), and an NG tube to decompress the stomach and prevent aspiration (e). The newborn is NPO before surgical repair, so breastfeeding (c) is not offered.', true),
  ('omphalocele', 4, 'The nurse is positioning a newborn with an intact omphalocele sac while awaiting transfer to the operating room. Which position is BEST?', '[{"id": "a", "text": "Prone with a soft roll under the hips"}, {"id": "b", "text": "Supine with knees slightly flexed"}, {"id": "c", "text": "Upright in an infant seat with a lap strap"}, {"id": "d", "text": "Held tummy-to-chest by a parent"}]'::jsonb, '["b"]', 'The newborn is positioned supine with knees slightly flexed, and no pressure is applied on the sac. Prone, a lap strap, or tummy-to-chest holding all place pressure on the sac.', false),
  ('omphalocele', 5, 'In the delivery room, the nurse notes loops of bowel protruding to the right of the umbilicus with no covering membrane, so the organs are exposed directly. Which statement about this newborn''s condition is MOST accurate?', '[{"id": "a", "text": "A sac of peritoneum and amnion covers the organs"}, {"id": "b", "text": "Associated cardiac defects are common"}, {"id": "c", "text": "The defect is located midline at the umbilicus"}, {"id": "d", "text": "Chromosomal anomalies are rarely associated"}]'::jsonb, '["d"]', 'Organs exposed directly with no sac to the right of the umbilicus describe gastroschisis, which is rarely associated with chromosomal anomalies. A sac, a midline umbilical location, and common cardiac defects are features of omphalocele.', false),
  ('omphalocele', 6, 'A nursing student is comparing two newborns with abdominal wall defects in the NICU. Which findings indicate that a newborn has an omphalocele rather than gastroschisis? Select all that apply.', '[{"id": "a", "text": "Organs are exposed directly"}, {"id": "b", "text": "A membrane covers the organs"}, {"id": "c", "text": "The defect is midline at the umbilicus"}, {"id": "d", "text": "The defect is right of the umbilicus"}, {"id": "e", "text": "Associated cardiac defects are found"}]'::jsonb, '["b", "c", "e"]', 'Omphalocele is covered by a membrane (b), is midline at the umbilicus (c), and commonly has associated defects such as cardiac defects (e). Organs exposed directly (a) and a defect right of the umbilicus (d) describe gastroschisis.', true),
  ('omphalocele', 7, 'The nurse is reviewing the prenatal record of a newborn who was born with abdominal organs protruding into a membrane-covered sac at the umbilicus. Which prenatal screening result is an expected finding in this record?', '[{"id": "a", "text": "Elevated maternal serum alpha-fetoprotein (MSAFP)"}, {"id": "b", "text": "Decreased maternal serum alpha-fetoprotein (MSAFP)"}, {"id": "c", "text": "Fetal organs seen to the right of the umbilicus"}, {"id": "d", "text": "Fetal organs seen with no covering membrane"}]'::jsonb, '["a"]', 'Elevated maternal serum alpha-fetoprotein (MSAFP) is the prenatal marker for omphalocele. Organs to the right of the umbilicus without a membrane would describe gastroschisis.', false),
  ('omphalocele', 8, 'A 2-day-old with a large omphalocele is NPO with IV fluids infusing and an NG tube in place while awaiting a silo. During the morning assessment, which finding requires IMMEDIATE follow-up?', '[{"id": "a", "text": "Thin, transparent sac over the intestines"}, {"id": "b", "text": "Liver visible through the sac at the umbilicus"}, {"id": "c", "text": "Foul odor and redness around the sac"}, {"id": "d", "text": "Gastric contents draining from the NG tube"}]'::jsonb, '["c"]', 'Foul odor and redness around the sac are signs of infection that must be reported. A thin, transparent sac with intestines and liver visible is the expected presentation, and NG drainage reflects decompression of the stomach.', false),
  ('omphalocele', 9, 'A 3-day-old with an omphalocele is awaiting staged repair. Which assessment findings should the nurse report as possible signs of infection? Select all that apply.', '[{"id": "a", "text": "Fever"}, {"id": "b", "text": "Thin, transparent sac"}, {"id": "c", "text": "Tachycardia"}, {"id": "d", "text": "Foul odor"}, {"id": "e", "text": "Redness around the sac"}]'::jsonb, '["a", "c", "d", "e"]', 'Fever (a), tachycardia (c), foul odor (d), and redness around the sac (e) are the signs of infection to monitor. A thin, transparent sac (b) is the normal covering of an omphalocele, made of peritoneum and amnion.', true),
  ('omphalocele', 10, 'The nurse is teaching the parent of a newborn with an omphalocele about the nasogastric (NG) tube inserted before surgery. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "''The tube keeps air and fluid out of his stomach for now.''"}, {"id": "b", "text": "''The tube is how he will get my milk before surgery.''"}, {"id": "c", "text": "''The tube helps keep him from breathing in vomit.''"}, {"id": "d", "text": "''He gets IV fluids because he cannot eat right now.''"}]'::jsonb, '["b"]', 'The NG tube decompresses the stomach and prevents aspiration; the newborn is NPO, with nothing by mouth before surgical repair, so the tube is not used for feeding. IV fluids replace the high fluid loss while the infant is NPO.', false),
  ('omphalocele', 11, 'A 6-hour-old with an intact omphalocele is rooting and crying. The parent asks to breastfeed briefly before the infant goes to surgery later today. Which response by the nurse is BEST?', '[{"id": "a", "text": "''A short feeding is fine if he stays supine.''"}, {"id": "b", "text": "''You can give 10 mL of pumped milk by bottle.''"}, {"id": "c", "text": "''Breastfeed now, then he will be NPO for surgery.''"}, {"id": "d", "text": "''Nothing by mouth before surgical repair.''"}]'::jsonb, '["d"]', 'The newborn must remain NPO, with nothing by mouth before surgical repair, and IV fluids replace the high fluid loss from organs outside the body. Any oral feeding, even a small amount, violates NPO status.', false),
  ('omphalocele', 12, 'During transport to the operating room, the membrane covering a newborn''s protruding intestines tears and serous fluid leaks onto the dressing. Which complications should the nurse be MOST concerned about?', '[{"id": "a", "text": "Contamination and massive fluid/heat loss"}, {"id": "b", "text": "Respiratory compromise from abdominal pressure"}, {"id": "c", "text": "Aspiration from a decompressed stomach"}, {"id": "d", "text": "Elevated MSAFP and chromosomal anomalies"}]'::jsonb, '["a"]', 'A ruptured sac means contamination risk plus massive fluid and heat loss. Respiratory compromise from abdominal pressure is a post-op concern when organs are returned to the abdomen.', false),
  ('omphalocele', 13, 'A newborn has a large omphalocele containing the liver and most of the intestines. The surgeon plans a silo. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "''A plastic pouch will be placed around his organs.''"}, {"id": "b", "text": "''His organs will go back in gradually over days to weeks.''"}, {"id": "c", "text": "''All his organs will be put back in one surgery tomorrow.''"}, {"id": "d", "text": "''They will close his belly once all the organs are back in.''"}]'::jsonb, '["c"]', 'A large defect is repaired by a staged repair with a silo, in which organs are gradually reduced over days to weeks and final closure occurs when all organs are returned. Returning organs in one surgery describes primary closure, which is used for small defects.', false),
  ('omphalocele', 14, 'A newborn has a small omphalocele containing only a few loops of intestine. The parent asks what type of surgery to expect. Which surgical approach should the nurse anticipate?', '[{"id": "a", "text": "Silo with gradual reduction over weeks"}, {"id": "b", "text": "Primary closure in one surgery"}, {"id": "c", "text": "Staged repair with a plastic pouch"}, {"id": "d", "text": "No repair until the sac dries out"}]'::jsonb, '["b"]', 'Primary closure is used for small defects: organs are returned and the abdominal wall is closed in one surgery. A silo/staged repair is used for large defects, and the sac must never be allowed to dry out.', false),
  ('omphalocele', 15, 'Two hours after primary closure of an omphalocele, the newborn''s abdomen is firm and distended after the organs were returned. Which finding requires the nurse''s IMMEDIATE follow-up?', '[{"id": "a", "text": "NPO status with IV fluids infusing"}, {"id": "b", "text": "Placement under a radiant warmer"}, {"id": "c", "text": "NG tube draining to decompress the stomach"}, {"id": "d", "text": "Grunting with a falling SpO₂ reading"}]'::jsonb, '["d"]', 'After organs are returned, abdominal pressure can cause respiratory compromise, so grunting with a falling SpO₂ needs immediate follow-up. NPO status, warming, and NG decompression are expected parts of care.', false),
  ('omphalocele', 16, 'A newborn has just had final closure after the last of the organs in the silo were reduced back into the abdomen. Which nursing actions are PRIORITY in the immediate post-op period? Select all that apply.', '[{"id": "a", "text": "Watch for respiratory compromise"}, {"id": "b", "text": "Re-cover the sac with plastic wrap"}, {"id": "c", "text": "Reduce the remaining organs slowly"}, {"id": "d", "text": "Continuous vital signs and SpO₂"}, {"id": "e", "text": "Apply pressure to the abdomen"}]'::jsonb, '["a", "d"]', 'After organs are returned, watch for respiratory compromise from abdominal pressure (a) and continue continuous vital sign and SpO₂ monitoring (d). There is no sac to cover after final closure (b), all organs were already returned before final closure (c), and pressure on the abdomen (e) is avoided.', true),
  ('omphalocele', 17, 'The parents of a newborn with a membrane-covered defect midline at the umbilicus ask why blood is being drawn for additional testing before surgery. Which diagnostic plan does the nurse MOST likely anticipate?', '[{"id": "a", "text": "Lab/genetic workup for Trisomy 13/18"}, {"id": "b", "text": "Serial MSAFP levels in the newborn"}, {"id": "c", "text": "No genetic workup; anomalies are rare"}, {"id": "d", "text": "Serial blood cultures for sac infection"}]'::jsonb, '["a"]', 'Omphalocele is often associated with chromosomal anomalies, so a lab/genetic workup for Trisomy 13/18 is anticipated. MSAFP is a prenatal maternal marker, and rarely associated chromosomal anomalies describe gastroschisis.', false),
  ('omphalocele', 18, 'A newborn with an omphalocele containing the intestines and liver is admitted to the NICU. For which associated conditions should the nurse anticipate an evaluation? Select all that apply.', '[{"id": "a", "text": "Trisomy 13 (Patau syndrome)"}, {"id": "b", "text": "Trisomy 18 (Edwards syndrome)"}, {"id": "c", "text": "Beckwith-Wiedemann syndrome"}, {"id": "d", "text": "An isolated defect with no anomalies"}, {"id": "e", "text": "Cardiac defects"}]'::jsonb, '["a", "b", "c", "e"]', 'Omphalocele is associated with Trisomy 13 (a), Trisomy 18 (b), Beckwith-Wiedemann syndrome (c), and common cardiac defects (e). Expecting an isolated defect (d) is wrong because chromosomal anomalies are often associated and associated defects are common.', true),
  ('omphalocele', 19, 'The parent of a newborn with an omphalocele asks the nurse how the defect happened. After the nurse explains, which statement by the parent indicates understanding?', '[{"id": "a", "text": "''It formed because the sac dried out after he was born.''"}, {"id": "b", "text": "''It happened from an infection during the vaginal delivery.''"}, {"id": "c", "text": "''His organs pushed out of his belly right after birth.''"}, {"id": "d", "text": "''His intestines did not return to his abdomen by week 10.''"}]'::jsonb, '["d"]', 'Omphalocele is caused by failure of the intestines to return to the abdomen during embryonic development by week 10, so it is present at birth. It is not caused by events after birth or during delivery.', false),
  ('omphalocele', 20, 'A nursing student is describing a newborn''s omphalocele during clinical conference. Which statement by the student requires follow-up by the nurse?', '[{"id": "a", "text": "''The sac covering the organs is thin and transparent.''"}, {"id": "b", "text": "''The thin sac is composed of skin and muscle.''"}, {"id": "c", "text": "''The liver can protrude along with the intestines.''"}, {"id": "d", "text": "''The organs protrude through the umbilical ring.''"}]'::jsonb, '["b"]', 'The thin, transparent sac is composed of peritoneum and amnion, not skin and muscle. The intestines, liver, and other abdominal organs protrude through the umbilical ring.', false),
  ('omphalocele', 21, 'A nurse in the NICU receives report on four newborns. Which newborn should the nurse assess FIRST?', '[{"id": "a", "text": "An omphalocele with dried gauze and a dry, dull sac"}, {"id": "b", "text": "A 4-day-old after primary closure with stable SpO₂"}, {"id": "c", "text": "An omphalocele with NPO status, IV fluids, and NG tube"}, {"id": "d", "text": "An omphalocele with lab/genetic workup pending"}]'::jsonb, '["a"]', 'The sac must never dry out or rupture; a drying sac risks rupture with contamination and massive fluid/heat loss. The other newborns are receiving expected care or are stable.', false),
  ('omphalocele', 22, 'The nurse observes an unlicensed assistive personnel (UAP) caring for a newborn with an intact omphalocele awaiting surgery. Which actions by the UAP require IMMEDIATE intervention? Select all that apply.', '[{"id": "a", "text": "Keeps the newborn under the radiant warmer"}, {"id": "b", "text": "Places the newborn prone for comfort"}, {"id": "c", "text": "Keeps the newborn NPO"}, {"id": "d", "text": "Leaves the continuous SpO₂ monitor on"}, {"id": "e", "text": "Removes the plastic wrap so the sac can air-dry"}]'::jsonb, '["b", "e"]', 'Prone positioning (b) applies pressure on the sac, and removing the plastic wrap to air-dry (e) lets the sac dry out, risking rupture. A radiant warmer (a), NPO status (c), and continuous SpO₂ monitoring (d) are correct pre-surgical care.', true),
  ('omphalocele', 23, 'The parent of a 4-hour-old with an omphalocele says, ''He isn''t sick and he isn''t vomiting, so why does he need an IV?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "''The IV fluids help keep the sac moist until surgery.''"}, {"id": "b", "text": "''The IV fluids are treating an infection in the sac.''"}, {"id": "c", "text": "''Organs outside the body cause high fluid and heat loss.''"}, {"id": "d", "text": "''The IV fluids lower the pressure on his lungs and heart.''"}]'::jsonb, '["c"]', 'IV fluids are needed because organs outside the body cause high fluid/heat loss, and electrolyte/fluid replacement is essential. The sac is kept moist with sterile saline-soaked gauze, not by IV fluids.', false),
  ('omphalocele', 24, 'A newborn with an intact omphalocele will wait several hours for the operating room. The nurse is planning the monitoring schedule. Which plan is BEST?', '[{"id": "a", "text": "Vital signs every 4 hours with SpO₂ spot checks"}, {"id": "b", "text": "Continuous vital signs and SpO₂ monitoring"}, {"id": "c", "text": "Vital signs once per shift while the newborn is NPO"}, {"id": "d", "text": "SpO₂ checks only during NG tube insertion"}]'::jsonb, '["b"]', 'Vital signs and SpO₂ require continuous monitoring before surgical repair. Intermittent checks could miss infection signs such as tachycardia or a sudden change in condition.', false),
  ('omphalocele', 25, 'Thirty minutes after birth, the nurse assesses a newborn with an omphalocele who is under a radiant warmer with the sac covered in saline-soaked gauze and plastic wrap. Which assessment finding is an expected finding?', '[{"id": "a", "text": "A thin, transparent sac over the liver and intestines"}, {"id": "b", "text": "A foul odor from the gauze covering the sac"}, {"id": "c", "text": "Organs at the umbilicus with no covering membrane present"}, {"id": "d", "text": "Fever and tachycardia since the last assessment"}]'::jsonb, '["a"]', 'In omphalocele, the intestines, liver, and other organs protrude through the umbilical ring covered by a thin, transparent sac. Organs with no membrane suggest a ruptured sac, and foul odor, fever, and tachycardia are infection signs.', false),
  ('omphalocele', 26, 'A newborn with an omphalocele awaiting repair has a distended stomach and has spit up a small amount of clear fluid. Which intervention should the nurse anticipate as BEST to prevent aspiration?', '[{"id": "a", "text": "Position prone so fluid drains from the mouth"}, {"id": "b", "text": "Offer smaller oral feedings more often"}, {"id": "c", "text": "Hold upright against the parent''s chest"}, {"id": "d", "text": "Insert an NG tube to decompress the stomach"}]'::jsonb, '["d"]', 'An NG tube is inserted to decompress the stomach and prevent aspiration. Prone or chest-to-chest positions put pressure on the sac, and oral feedings violate NPO status.', false),
  ('omphalocele', 27, 'The nurse is teaching the parents of a newborn with an omphalocele about care before surgical repair. Which statements by the parents indicate understanding? Select all that apply.', '[{"id": "a", "text": "''He can''t have anything by mouth before surgery.''"}, {"id": "b", "text": "''I can hold him tummy-to-tummy to comfort him.''"}, {"id": "c", "text": "''The warmer keeps him from losing too much heat.''"}, {"id": "d", "text": "''The IV replaces fluid lost from his exposed organs.''"}, {"id": "e", "text": "''The wrap can come off so the sac can get air.''"}]'::jsonb, '["a", "c", "d"]', 'The newborn is NPO before surgical repair (a), a radiant warmer prevents hypothermia from exposed organs (c), and IV fluids replace the high fluid loss (d). Holding tummy-to-tummy (b) applies pressure on the sac, and removing the wrap (e) lets the sac dry out.', true),
  ('omphalocele', 28, 'The nurse reviews the diagnosis with the parents of a newborn with an omphalocele. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "''This defect was present at birth.''"}, {"id": "b", "text": "''He will need operative repair.''"}, {"id": "c", "text": "''Surgical repair will not be needed.''"}, {"id": "d", "text": "''He will have a genetic workup.''"}]'::jsonb, '["c"]', 'Omphalocele is present at birth and operative repair is needed, so the sac will not close on its own. A lab/genetic workup for Trisomy 13/18 is part of care.', false),
  ('omphalocele', 29, 'On day 5 after silo placement for a large omphalocele, the parent asks, ''Why don''t they just push all of his organs back in now?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "''The silo stays until the sac dries and closes over.''"}, {"id": "b", "text": "''Organs are reduced gradually over days to weeks.''"}, {"id": "c", "text": "''They will go back in once he can breastfeed.''"}, {"id": "d", "text": "''Large defects are closed in one surgery later.''"}]'::jsonb, '["b"]', 'In staged repair for large defects, organs are gradually reduced back into the abdomen over days to weeks, with final closure when all organs are returned. Closure in one surgery is primary closure for small defects.', false),
  ('omphalocele', 30, 'A newborn with a large omphalocele is scheduled for a staged repair. Which statements about this surgical approach should the nurse include when reinforcing teaching? Select all that apply.', '[{"id": "a", "text": "It is used for small defects"}, {"id": "b", "text": "A plastic pouch is placed around the organs"}, {"id": "c", "text": "All organs are returned in one surgery"}, {"id": "d", "text": "Organs are gradually reduced over days to weeks"}, {"id": "e", "text": "Final closure is done before organs are returned"}]'::jsonb, '["b", "d"]', 'In staged repair a plastic pouch (silo) is placed around the protruding organs (b), and the organs are gradually reduced over days to weeks (d). Staged repair is for large defects, not small ones (a); returning all organs in one surgery (c) is primary closure; and final closure happens when all organs are returned (e).', true),
  ('omphalocele', 31, 'A newborn''s covering membrane ruptured during a difficult delivery, leaving loops of intestine exposed. Which finding BEST helps the nurse identify the defect as an omphalocele rather than gastroschisis?', '[{"id": "a", "text": "The intestines have no covering membrane"}, {"id": "b", "text": "The defect is located right of the umbilicus"}, {"id": "c", "text": "No associated defects are found on workup"}, {"id": "d", "text": "The defect is located midline at the umbilicus"}]'::jsonb, '["d"]', 'Omphalocele is located midline at the umbilicus, while gastroschisis is right of the umbilicus. Once the sac has ruptured, the absence of a membrane no longer distinguishes the two.', false),
  ('omphalocele', 32, 'The parents of a newborn with a sac-covered defect at the umbilicus say their friend''s baby had gastroschisis and did not need genetic testing. They ask why their baby does. Which response by the nurse is BEST?', '[{"id": "a", "text": "''Omphalocele is often associated with chromosomal anomalies.''"}, {"id": "b", "text": "''Both defects are rarely linked to chromosomal anomalies.''"}, {"id": "c", "text": "''Gastroschisis is more often linked to chromosomal anomalies.''"}, {"id": "d", "text": "''Genetic testing is needed only if the sac ruptures.''"}]'::jsonb, '["a"]', 'Chromosomal anomalies are often associated with omphalocele but rarely with gastroschisis, so a lab/genetic workup is part of omphalocele care. Rupture of the sac does not determine the need for genetic testing.', false),
  ('omphalocele', 33, 'A pregnant client at 18 weeks'' gestation has an elevated maternal serum alpha-fetoprotein (MSAFP), and ultrasound shows fetal abdominal organs in a membrane-covered sac at the umbilicus. Which plan for the newborn should the nurse MOST likely anticipate?', '[{"id": "a", "text": "Primary closure in one surgery for all sizes"}, {"id": "b", "text": "Repeat MSAFP on the newborn to confirm"}, {"id": "c", "text": "Genetic workup for Trisomy 13/18"}, {"id": "d", "text": "No workup, since other anomalies are rare"}]'::jsonb, '["c"]', 'Elevated MSAFP is the prenatal marker for omphalocele, and the newborn is monitored for genetic anomalies (Trisomy 13/18). Primary closure is only for small defects, and associated anomalies are common, not rare.', false),
  ('omphalocele', 34, 'A newborn''s omphalocele sac tears while the infant is being moved from the radiant warmer to a transport incubator. Which complications should the nurse anticipate as a direct result of the rupture? Select all that apply.', '[{"id": "a", "text": "Contamination risk"}, {"id": "b", "text": "Respiratory compromise from returned organs"}, {"id": "c", "text": "Massive fluid loss"}, {"id": "d", "text": "Massive heat loss"}, {"id": "e", "text": "Decreased MSAFP"}]'::jsonb, '["a", "c", "d"]', 'A ruptured sac causes contamination risk (a) and massive fluid (c) and heat (d) loss. Respiratory compromise (b) is a post-op concern when organs are returned, and MSAFP (e) is a prenatal maternal marker, which is elevated rather than decreased.', true),
  ('omphalocele', 35, 'A 2-day-old with an omphalocele awaiting staged repair was stable overnight. This morning the newborn is warm to the touch with a heart rate well above the previous readings; the sac is intact and covered. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "An expected stress response before surgery"}, {"id": "b", "text": "Possible infection shown by fever and tachycardia"}, {"id": "c", "text": "Respiratory compromise from abdominal pressure"}, {"id": "d", "text": "Hypothermia from heat loss through exposed organs"}]'::jsonb, '["b"]', 'Fever and tachycardia are signs of infection to monitor in the newborn awaiting repair. Respiratory compromise from abdominal pressure is a post-op concern when organs are returned, and hypothermia would not cause a warm newborn.', false),
  ('omphalocele', 36, 'Shortly after a newborn with an omphalocele is admitted to the NICU, the nurse completes a head-to-toe assessment. Besides the abdominal defect, which body system should the nurse assess MOST closely for an associated defect?', '[{"id": "a", "text": "Respiratory system, for pre-op respiratory compromise"}, {"id": "b", "text": "Renal system, for decreased urine output"}, {"id": "c", "text": "Skin, for breakdown around the umbilical ring"}, {"id": "d", "text": "Cardiac system, for associated cardiac defects"}]'::jsonb, '["d"]', 'Cardiac defects are common with omphalocele, and associated defects such as cardiac are common. Respiratory compromise is a post-op concern when organs are returned to the abdomen.', false),
  ('omphalocele', 37, 'A 1-day-old with an omphalocele is awaiting surgery. During rounds, the nurse reviews the newborn''s status. Which findings require IMMEDIATE intervention? Select all that apply.', '[{"id": "a", "text": "A small tear in the sac with fluid leaking"}, {"id": "b", "text": "Placement under a radiant warmer"}, {"id": "c", "text": "Foul odor and redness around the sac"}, {"id": "d", "text": "NG tube draining gastric contents"}, {"id": "e", "text": "IV fluids infusing at the prescribed rate"}]'::jsonb, '["a", "c"]', 'A tear in the sac (a) means rupture with contamination risk and massive fluid/heat loss, and foul odor with redness around the sac (c) signals infection. A radiant warmer (b), NG decompression (d), and IV fluids (e) are expected pre-surgical care.', true),
  ('omphalocele', 38, 'A nursing student asks why a newborn with an omphalocele loses body heat faster than the other newborns in the nursery. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "''Organs exposed outside the body increase heat loss.''"}, {"id": "b", "text": "''Being NPO keeps him from producing enough heat.''"}, {"id": "c", "text": "''The NG tube removes warm fluid from the stomach.''"}, {"id": "d", "text": "''His cardiac defect reduces blood flow to the skin.''"}]'::jsonb, '["a"]', 'Hypothermia risk comes from organs exposed outside the body, which causes high fluid/heat loss. NPO status and the NG tube are pre-surgical care measures, not the cause of heat loss.', false),
  ('omphalocele', 39, 'The nurse reviews the admission prescriptions for a newborn with an intact omphalocele who is awaiting surgery. Which prescription requires follow-up with the health care provider?', '[{"id": "a", "text": "Place under a radiant warmer"}, {"id": "b", "text": "Insert an NG tube to decompress the stomach"}, {"id": "c", "text": "Apply dry sterile gauze to the sac"}, {"id": "d", "text": "Continuous vital signs and SpO₂"}]'::jsonb, '["c"]', 'The sac must be covered with sterile saline-soaked gauze plus plastic wrap to prevent drying and rupture, so a dry gauze prescription should be questioned. A radiant warmer, NG decompression, and continuous monitoring are correct.', false),
  ('omphalocele', 40, 'The nurse performs the initial inspection of a newborn with an omphalocele in the delivery room. Which findings should the nurse expect? Select all that apply.', '[{"id": "a", "text": "Organs protruding right of the umbilicus"}, {"id": "b", "text": "Intestines protruding through the umbilical ring"}, {"id": "c", "text": "A thin, transparent covering sac"}, {"id": "d", "text": "Organs exposed directly with no membrane"}, {"id": "e", "text": "Liver protruding within the sac"}]'::jsonb, '["b", "c", "e"]', 'In omphalocele the intestines (b), liver (e), and other organs protrude through the umbilical ring covered by a thin, transparent sac (c). A defect right of the umbilicus (a) with organs exposed directly (d) describes gastroschisis.', true),
  ('omphalocele', 41, 'The genetic workup for a newborn with an omphalocele shows Trisomy 18. The parent asks whether the two findings are related. Which response by the nurse is BEST?', '[{"id": "a", "text": "''Trisomy 18 is rarely seen with omphalocele.''"}, {"id": "b", "text": "''Trisomy 18 (Edwards) is associated with it.''"}, {"id": "c", "text": "''Only Beckwith-Wiedemann is associated.''"}, {"id": "d", "text": "''Trisomy 18 occurs after the sac ruptures.''"}]'::jsonb, '["b"]', 'Trisomy 18 (Edwards syndrome) is an associated condition of omphalocele, along with Trisomy 13 and Beckwith-Wiedemann syndrome. Chromosomal anomalies are rarely associated with gastroschisis, not omphalocele.', false),
  ('omphalocele', 42, 'The NICU nurse is caring for four newborns with omphaloceles. Which defect is the nurse MOST likely to prepare for primary closure?', '[{"id": "a", "text": "A large defect containing the liver and intestines"}, {"id": "b", "text": "A silo reduction in progress"}, {"id": "c", "text": "A large defect in a plastic pouch"}, {"id": "d", "text": "A small defect containing intestines"}]'::jsonb, '["d"]', 'Primary closure is used for small defects, with organs returned and the abdominal wall closed in one surgery. Large defects are managed with a staged repair using a plastic pouch (silo).', false),
  ('omphalocele', 43, 'After final closure of an omphalocele, a newborn needs increased respiratory support. The parent asks why breathing is harder now that the organs are back inside. Which response by the nurse is BEST?', '[{"id": "a", "text": "''The NG tube is causing him to aspirate.''"}, {"id": "b", "text": "''Hypothermia from surgery slows his breathing.''"}, {"id": "c", "text": "''Returned organs raise his abdominal pressure.''"}, {"id": "d", "text": "''An infection in the sac spread to his lungs.''"}]'::jsonb, '["c"]', 'Post-op respiratory compromise results from abdominal pressure when the organs are returned. The NG tube is used to prevent aspiration, not cause it.', false),
  ('omphalocele', 44, 'The nurse reinforces teaching for the parents of a newborn with an omphalocele who is awaiting surgery. Which statements by the parents indicate understanding? Select all that apply.', '[{"id": "a", "text": "''His organs came out through the umbilical ring.''"}, {"id": "b", "text": "''This defect was present at birth.''"}, {"id": "c", "text": "''It is less often linked to other defects than gastroschisis.''"}, {"id": "d", "text": "''Surgical repair is needed.''"}, {"id": "e", "text": "''His intestines did not return by week 10.''"}]'::jsonb, '["a", "b", "d", "e"]', 'Organs protrude through the umbilical ring (a), the defect is present at birth (b), operative repair is needed (d), and it results from failure of the intestines to return to the abdomen by week 10 (e). Associated defects are common with omphalocele and uncommon with gastroschisis, so (c) is incorrect.', true),
  ('omphalocele', 45, 'An unlicensed assistive personnel (UAP) is helping care for a newborn with an intact omphalocele awaiting surgery and describes the plan for the shift. Which plan requires IMMEDIATE correction by the nurse?', '[{"id": "a", "text": "Keep the radiant warmer turned on"}, {"id": "b", "text": "Vital signs and SpO₂ every 4 hours"}, {"id": "c", "text": "Keep the newborn NPO until surgery"}, {"id": "d", "text": "Report any redness near the sac"}]'::jsonb, '["b"]', 'Vital signs and SpO₂ require continuous monitoring before surgery, so checks every 4 hours are inadequate. A radiant warmer, NPO status, and reporting redness around the sac are correct.', false),
  ('omphalocele', 46, 'A newborn in the next warmer, beside an infant with an omphalocele, has gastroschisis. Which findings would the nurse expect in the newborn with gastroschisis? Select all that apply.', '[{"id": "a", "text": "Organs exposed directly"}, {"id": "b", "text": "A covering membrane"}, {"id": "c", "text": "Defect right of the umbilicus"}, {"id": "d", "text": "Chromosomal anomalies rarely associated"}, {"id": "e", "text": "Associated cardiac defects common"}]'::jsonb, '["a", "c", "d"]', 'Gastroschisis has no sac with organs exposed directly (a), is located right of the umbilicus (c), and is rarely associated with chromosomal anomalies (d). A covering membrane (b) and common associated cardiac defects (e) describe omphalocele.', true),
  ('omphalocele', 47, 'Just before transfer to the operating room, the nurse notes that the gauze over a newborn''s omphalocele sac has dried at the edges. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Re-moisten with sterile saline and keep covered"}, {"id": "b", "text": "Remove the gauze and leave the sac open to the air"}, {"id": "c", "text": "Replace it with dry sterile gauze to absorb fluid"}, {"id": "d", "text": "Proceed to the OR, since surgery is imminent"}]'::jsonb, '["a"]', 'The sac must never dry out; it is kept moist and covered until the OR. Leaving it open to air or using dry gauze allows drying and rupture.', false),
  ('omphalocele', 48, 'A new graduate nurse caring for newborns with omphaloceles asks the preceptor about surgical repair. Which statements by the preceptor are accurate? Select all that apply.', '[{"id": "a", "text": "Primary closure is used for small defects"}, {"id": "b", "text": "A silo is used for large defects"}, {"id": "c", "text": "Final closure is done before organs return"}, {"id": "d", "text": "Post-op, watch for respiratory compromise"}, {"id": "e", "text": "Surgery waits until the sac dries out"}]'::jsonb, '["a", "b", "d"]', 'Primary closure is used for small defects (a), staged repair with a silo for large defects (b), and post-op the nurse watches for respiratory compromise (d). Final closure occurs when all organs are returned (c), and the sac must never dry out (e).', true),
  ('omphalocele', 49, 'A newborn with a large omphalocele had a silo placed 3 days ago. Which finding is an expected finding at this stage of the staged repair?', '[{"id": "a", "text": "Final closure of the abdominal wall is complete"}, {"id": "b", "text": "All organs were returned during the first surgery"}, {"id": "c", "text": "Organs are being gradually reduced into the abdomen"}, {"id": "d", "text": "The silo has been removed and the sac is drying"}]'::jsonb, '["c"]', 'In staged repair, organs are gradually reduced back into the abdomen over days to weeks, and final closure happens only when all organs are returned. Returning all organs in one surgery is primary closure.', false),
  ('omphalocele', 50, 'A pregnant client''s 20-week ultrasound shows a fetal omphalocele. The client asks the nurse several questions about the finding. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "The organs are exposed with no sac"}, {"id": "b", "text": "It is located right of the umbilicus"}, {"id": "c", "text": "Elevated MSAFP is a prenatal marker"}, {"id": "d", "text": "Chromosomal anomalies are rarely associated"}, {"id": "e", "text": "The intestines failed to return by week 10"}]'::jsonb, '["c", "e"]', 'Elevated maternal serum alpha-fetoprotein (MSAFP) is the prenatal marker (c), and omphalocele results from failure of the intestines to return to the abdomen by week 10 (e). No sac (a), a right-sided location (b), and rare chromosomal anomalies (d) describe gastroschisis.', true),
  ('meds', 1, 'A 2-year-old who weighs 33 lb is prescribed amoxicillin 15 mg/kg per dose. The oral suspension on hand is 250 mg/5 mL. Which volume should the nurse draw up in the oral syringe?', '[{"id": "a", "text": "0.9 mL"}, {"id": "b", "text": "4.5 mL"}, {"id": "c", "text": "9.9 mL"}, {"id": "d", "text": "22.5 mL"}]'::jsonb, '["b"]', '33 lb ÷ 2.2 = 15 kg; 15 mg/kg × 15 kg = 225 mg; Volume = Dose ÷ Concentration = 225 ÷ (250/5 = 50 mg/mL) = 4.5 mL. 9.9 mL comes from using pounds instead of kg, and 0.9 mL from dividing by 250 instead of the 50 mg/mL concentration.', false),
  ('meds', 2, 'An 18-month-old who still drinks from a bottle keeps pushing away a cup of liquid antibiotic. Which actions by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Measure the dose in an oral syringe"}, {"id": "b", "text": "Mix the dose into a full bottle of formula"}, {"id": "c", "text": "Tell the toddler the medicine is candy"}, {"id": "d", "text": "Aim the oral syringe at the inner cheek"}, {"id": "e", "text": "Check allergies before administering"}]'::jsonb, '["a", "d", "e"]', 'Correct: (a) an oral syringe, not a kitchen spoon or cup, is used for liquid doses; (d) the syringe is aimed at the inner cheek; (e) allergies are always checked before administering. Wrong: (b) the dose is NOT mixed in a full bottle (the child may not finish it); (c) medicine is never called "candy" — a safety and honesty issue.', true),
  ('meds', 3, 'A school-age child who weighs 48.4 lb has an order for 240 mg of an oral antibiotic. The drug reference lists a maximum safe dose of 10 mg/kg per dose. Which action by the nurse is BEST?', '[{"id": "a", "text": "Give it, because it is below the 484-mg maximum"}, {"id": "b", "text": "Give 220 mg, the maximum safe dose for this child"}, {"id": "c", "text": "Give the ordered dose and watch for adverse reactions"}, {"id": "d", "text": "Do NOT give the dose and call the provider"}]'::jsonb, '["d"]', '48.4 lb ÷ 2.2 = 22 kg, so the maximum is 10 mg/kg × 22 kg = 220 mg; 240 mg exceeds the safe range, so the nurse does NOT give it and calls the provider. The 484-mg figure comes from using pounds; the nurse also may not change the dose on their own.', false),
  ('meds', 4, 'A 7-month-old is due for a 0.5-mL intramuscular (IM) injection. The parent asks that it be given "in the arm, like my shots." Which site should the nurse select as the BEST choice?', '[{"id": "a", "text": "Vastus lateralis (thigh)"}, {"id": "b", "text": "Deltoid (upper arm)"}, {"id": "c", "text": "Abdomen, rotating sites"}, {"id": "d", "text": "Upper arm, subcutaneous layer"}]'::jsonb, '["a"]', 'The vastus lateralis (thigh) is the safest IM injection site in infants, so the parent''s request for the arm is not followed for a 7-month-old. The abdomen and upper arm are subcutaneous rotation sites, not the infant IM site.', false),
  ('meds', 5, 'A nurse is reviewing handwritten medication orders for several children on the unit. Which dose notations should the nurse question because of a decimal-point safety risk? Select all that apply.', '[{"id": "a", "text": ".5 mg"}, {"id": "b", "text": "2.0 mg"}, {"id": "c", "text": "0.25 mg"}, {"id": "d", "text": "5 mg"}, {"id": "e", "text": "12 mg"}]'::jsonb, '["a", "b"]', 'Correct: (a) ".5 mg" lacks a leading zero and can be misread as 5 mg; (b) "2.0 mg" has a trailing zero and can be misread as 20 mg (0.1 ≠ 1.0). Wrong: (c) "0.25 mg" correctly uses a leading zero; (d) "5 mg" and (e) "12 mg" are whole numbers with no trailing zero, so they follow the rule.', true),
  ('meds', 6, 'A nurse receives an order for a single 1.5-mL intramuscular (IM) injection into the vastus lateralis of a 5-month-old. Which action is MOST appropriate?', '[{"id": "a", "text": "Give the full volume into the vastus lateralis as ordered"}, {"id": "b", "text": "Give the full volume into the deltoid to protect the thigh"}, {"id": "c", "text": "Hold the injection and clarify the volume with the provider"}, {"id": "d", "text": "Give the injection, then document the volume given to the infant"}]'::jsonb, '["c"]', 'IM volume is limited to less than 1 mL in infants, so 1.5 mL is not safe even though the vastus lateralis is the correct site; when in doubt about dose safety, the nurse does not give it and calls the provider.', false),
  ('meds', 7, 'A nurse is about to instill prescribed ear drops for a 20-month-old who is held securely on the parent''s lap. Which technique should the nurse use for the BEST result?', '[{"id": "a", "text": "Pull the pinna UP and back"}, {"id": "b", "text": "Pull the pinna DOWN and back"}, {"id": "c", "text": "Pull the pinna down and forward"}, {"id": "d", "text": "Pull the pinna straight up"}]'::jsonb, '["b"]', 'For children under 3 years, the pinna is pulled DOWN and back; UP and back is the technique for children 3 years and older, which is the classic mix-up.', false),
  ('meds', 8, 'A nurse precepting a new graduate observes several medication administrations on a pediatric unit. Which actions by the new graduate are correct? Select all that apply.', '[{"id": "a", "text": "Pulls the pinna down and back for ear drops in a 2-year-old"}, {"id": "b", "text": "Pulls the pinna up and back for ear drops in a 7-year-old"}, {"id": "c", "text": "Rests the dropper tip on the lashes to steady the eye drops"}, {"id": "d", "text": "Pulls the lower eyelid down to create a pouch for eye drops"}, {"id": "e", "text": "Pulls the pinna up and back for ear drops in a 1-year-old"}]'::jsonb, '["a", "b", "d"]', 'Correct: (a) under 3 years the pinna goes down and back; (b) 3 years and older the pinna goes up and back; (d) the lower eyelid is pulled down to create a pouch. Wrong: (c) the dropper tip must NOT touch the eye or lashes; (e) a 1-year-old is under 3, so up and back is the wrong direction.', true),
  ('meds', 9, 'Two 3-year-olds with similar names share a room. One answers "yes" when the nurse reads the name on the medication label aloud. Which action should the nurse take FIRST before giving the medication?', '[{"id": "a", "text": "Verify the ID band using 2 identifiers"}, {"id": "b", "text": "Accept the child''s answer and give it"}, {"id": "c", "text": "Ask the roommate''s parent to confirm"}, {"id": "d", "text": "Check the name on the bed and door card"}]'::jsonb, '["a"]', 'Right patient requires verifying the ID band and at least 2 patient identifiers before any medication; a young child''s "yes" to a name is not reliable verification, and a roommate''s parent or a bed card does not replace the ID band.', false),
  ('meds', 10, 'A nurse checked a medication label when taking the bottle from the drawer and again while pouring a 5-mL dose for a 6-year-old. When should the NEXT required label check occur?', '[{"id": "a", "text": "When documenting the dose after giving it"}, {"id": "b", "text": "When the pharmacy sends the next bottle"}, {"id": "c", "text": "At the bedside, just before administering"}, {"id": "d", "text": "Only if the child asks questions about the medicine"}]'::jsonb, '["c"]', 'The label is checked 3 times: at prep, at pour, and at administer. Prep and pour are done, so the third check is just before administering, not at documentation.', false),
  ('meds', 11, 'A nurse is caring for a 6-year-old who is receiving an IV antibiotic through a peripheral line. Which actions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Run the medication on an infusion pump"}, {"id": "b", "text": "Monitor the site for infiltration"}, {"id": "c", "text": "Let it run by gravity if the pump alarms often"}, {"id": "d", "text": "Monitor for phlebitis and extravasation"}, {"id": "e", "text": "Base the dose on the child''s weight in kg"}]'::jsonb, '["a", "b", "d", "e"]', 'Correct: (a) IV medications always use an infusion pump; (b) and (d) the IV site is monitored for infiltration, phlebitis, and extravasation; (e) doses are weight-based and always calculated in kg. Wrong: (c) running by gravity contradicts "always use infusion pump," even when alarms are frequent.', true),
  ('meds', 12, 'A 3-year-old with an oral medication due has vomited three times in the past hour and cannot keep anything down. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Give the oral dose and recheck in 30 minutes"}, {"id": "b", "text": "Mix the oral dose into a full bottle of juice"}, {"id": "c", "text": "Give the oral dose by IM injection instead"}, {"id": "d", "text": "Contact the provider about the rectal route"}]'::jsonb, '["d"]', 'The rectal route is used when a child is vomiting or unable to take orally, but right route means the order must match the route, so the nurse contacts the provider rather than giving the oral dose or changing the route alone.', false),
  ('meds', 13, 'During safety rounds, a nurse finds that a parent turned off a 4-year-old''s IV pump because the alarm was disturbing, and the fluid is now running by gravity. Which action is the PRIORITY?', '[{"id": "a", "text": "Return the infusion to the infusion pump"}, {"id": "b", "text": "Count the drip rate once every hour"}, {"id": "c", "text": "Document the rate at the end of the shift"}, {"id": "d", "text": "Lower the IV bag to slow the flow rate"}]'::jsonb, '["a"]', 'Pediatric IV infusions always use an infusion pump; counting drips or lowering the bag still leaves the child on an unsafe gravity infusion, and documentation does not correct the hazard.', false),
  ('meds', 14, 'A charge nurse reviews the medication practices of a nurse assigned to four children on a busy day shift. Which action by the nurse requires follow-up?', '[{"id": "a", "text": "Recorded a 1000 dose right after giving it"}, {"id": "b", "text": "Waited until 1200 to record the 0900 doses"}, {"id": "c", "text": "Documented the reason a dose was withheld"}, {"id": "d", "text": "Verified the ID band with 2 identifiers"}]'::jsonb, '["b"]', 'Right documentation means recording immediately after giving, so batching 0900 doses until 1200 requires follow-up. Documenting the reason for a withheld dose and using 2 identifiers are correct practices.', false),
  ('meds', 15, 'A nurse on the night shift is preparing scheduled medications for several children. For which medications should the nurse obtain a double-check from another nurse? Select all that apply.', '[{"id": "a", "text": "Insulin"}, {"id": "b", "text": "Amoxicillin suspension"}, {"id": "c", "text": "Digoxin"}, {"id": "d", "text": "Heparin"}, {"id": "e", "text": "Ear drops"}]'::jsonb, '["a", "c", "d"]', 'Correct: (a) insulin, (c) digoxin, and (d) heparin are high-alert medications that need a double-check with another nurse. Wrong: (b) amoxicillin suspension and (e) ear drops are not listed as high-alert; they still need the usual rights checks but not a second nurse.', true),
  ('meds', 16, 'The parent of a 5-year-old being discharged on an oral antibiotic every 8 hours makes several statements. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "I will give it at the same three times each day"}, {"id": "b", "text": "I will check the label before every dose"}, {"id": "c", "text": "If she is asleep at dose time, I will skip it"}, {"id": "d", "text": "I will use the syringe instead of a spoon"}]'::jsonb, '["c"]', 'Right time means adhering to the schedule and not skipping doses, so skipping because the child is asleep needs correction. Giving doses on schedule, checking the label, and using the oral syringe rather than a kitchen spoon are correct.', false),
  ('meds', 17, 'A second nurse has just double-checked a heparin infusion dose calculated for a 9-year-old and confirmed it is within the safe range. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Infuse by gravity and count the drip rate"}, {"id": "b", "text": "Document the infusion before starting it"}, {"id": "c", "text": "Recalculate the dose using weight in pounds"}, {"id": "d", "text": "Start the infusion on an infusion pump"}]'::jsonb, '["d"]', 'After the high-alert double-check, the IV is started on an infusion pump (always used for IV). Gravity is unsafe, documentation is done immediately after giving (not before), and dose calculation always uses kg, not lbs.', false),
  ('meds', 18, 'A nurse is giving a scheduled oral medication to a 7-year-old. Which actions by the nurse follow the rights of medication administration? Select all that apply.', '[{"id": "a", "text": "Verifies the ID band and uses 2 identifiers"}, {"id": "b", "text": "Checks the label at prep, pour, and administer"}, {"id": "c", "text": "Gives the dose 2 hours late so the child can nap"}, {"id": "d", "text": "Double-checks the math and checks the safe range"}, {"id": "e", "text": "Records the dose immediately after giving it"}]'::jsonb, '["a", "b", "d", "e"]', 'Correct: (a) right patient = ID band + 2 identifiers; (b) right medication = label checked 3× (prep, pour, administer); (d) right dose = double-check math and check the safe range; (e) right documentation = record immediately after giving. Wrong: (c) right time means adhering to the schedule, not delaying a dose for a nap.', true),
  ('meds', 19, 'The parent of a 10-month-old asks why the infant cannot simply take a small amount of the parent''s own liquid medicine. Which response by the nurse is BEST?', '[{"id": "a", "text": "All doses are weight-based; her liver and kidneys are immature"}, {"id": "b", "text": "Infants have a lower body water ratio, so drugs stay concentrated"}, {"id": "c", "text": "An adult dose is safe if it is divided by her age in years"}, {"id": "d", "text": "Her kidneys clear drugs faster, so she needs more frequent doses"}]'::jsonb, '["a"]', 'All pediatric doses are weight-based (never adult doses) because an immature liver and kidneys alter drug metabolism and excretion. Infants have a HIGHER, not lower, body water ratio.', false),
  ('meds', 20, 'A nursing student is explaining to a preceptor why a 3-month-old''s drug distribution differs from an adult''s. Which statement by the student indicates understanding?', '[{"id": "a", "text": "Infants have a lower body water ratio than adults"}, {"id": "b", "text": "Infants have a higher body water ratio than adults"}, {"id": "c", "text": "Infants have mature kidneys that excrete drugs faster"}, {"id": "d", "text": "Infants distribute drugs like adults, in less volume"}]'::jsonb, '["b"]', 'A higher body water ratio leads to different drug distribution in children. The kidneys (and liver) are immature, not mature, which alters excretion rather than speeding it.', false),
  ('meds', 21, 'A nurse is giving prescribed ear drops to several children on a pediatric unit. For which children should the nurse pull the pinna DOWN and back? Select all that apply.', '[{"id": "a", "text": "A 6-month-old"}, {"id": "b", "text": "A 4-year-old"}, {"id": "c", "text": "A 30-month-old"}, {"id": "d", "text": "A 9-year-old"}, {"id": "e", "text": "A 5-year-old"}]'::jsonb, '["a", "c"]', 'Correct: (a) a 6-month-old and (c) a 30-month-old (2½ years) are under 3 years, so the pinna is pulled down and back. Wrong: (b) the 4-year-old, (d) the 9-year-old, and (e) the 5-year-old are 3 years or older, so the pinna is pulled up and back.', true),
  ('meds', 22, 'Before the first dose of amoxicillin for a 4-year-old, the parent says the child "broke out in a rash the last time he took amoxicillin." Which action by the nurse is BEST?', '[{"id": "a", "text": "Give the dose and watch closely for a rash"}, {"id": "b", "text": "Give half the dose to test for a reaction"}, {"id": "c", "text": "Do NOT give the dose and call the provider"}, {"id": "d", "text": "Document the history and give it as ordered"}]'::jsonb, '["c"]', 'Allergies are always checked before administering; a reported reaction to this drug creates doubt about safety, so the nurse does NOT give the dose and calls the provider rather than test-dosing or giving it as ordered.', false),
  ('meds', 23, 'A nurse is giving 3 mL of an oral liquid medication to a 9-month-old held upright on the parent''s lap. Where should the nurse aim the oral syringe for the BEST technique?', '[{"id": "a", "text": "At the back of the throat"}, {"id": "b", "text": "At the tip of the tongue"}, {"id": "c", "text": "At the roof of the mouth"}, {"id": "d", "text": "At the inner cheek"}]'::jsonb, '["d"]', 'Oral liquid doses are given with an oral syringe aimed at the inner cheek; aiming at the back of the throat or other spots is not the technique taught.', false),
  ('meds', 24, 'The parent of a 10-year-old who needs daily subcutaneous injections at home describes the technique being used. Which statement by the parent requires follow-up?', '[{"id": "a", "text": "I give every injection in the same thigh spot"}, {"id": "b", "text": "I rotate the abdomen, thigh, and upper arm"}, {"id": "c", "text": "I use the small gauge needle from the clinic"}, {"id": "d", "text": "I write down each dose right after I have given it"}]'::jsonb, '["a"]', 'Subcutaneous sites must be rotated among the abdomen, thigh, and upper arm, so using one thigh spot every time requires follow-up. A small gauge needle and recording right after giving are correct.', false),
  ('meds', 25, 'A nursing student shows a calculation for a 55-lb child prescribed 8 mg/kg of an oral medication supplied as 125 mg/5 mL. Which steps in the student''s work are correct? Select all that apply.', '[{"id": "a", "text": "55 ÷ 2.2 = 25 kg"}, {"id": "b", "text": "8 mg/kg × 55 = 440 mg"}, {"id": "c", "text": "8 mg/kg × 25 kg = 200 mg"}, {"id": "d", "text": "200 mg ÷ 125 mg = 1.6 mL"}, {"id": "e", "text": "200 mg ÷ 25 mg/mL = 8 mL"}]'::jsonb, '["a", "c", "e"]', 'Correct: (a) lbs ÷ 2.2 = kg gives 25 kg; (c) ordered mg/kg × weight in kg = 200 mg; (e) Volume = Dose ÷ Concentration, and 125 mg/5 mL = 25 mg/mL, so 8 mL. Wrong: (b) uses pounds instead of kg; (d) divides by 125 mg instead of the concentration per mL.', true),
  ('meds', 26, 'A nurse receives four reports at the start of a shift on a pediatric unit. Which child should the nurse see FIRST?', '[{"id": "a", "text": "A 4-year-old due for an oral antibiotic in 30 minutes"}, {"id": "b", "text": "A 6-year-old with new hives after a first IV antibiotic dose"}, {"id": "c", "text": "A 2-year-old whose parent asks how to give ear drops at home"}, {"id": "d", "text": "An 8-year-old whose subcutaneous site needs rotation teaching"}]'::jsonb, '["b"]', 'Adverse reactions are reported immediately, so the child with new hives after an IV antibiotic is seen first. A dose due in 30 minutes and home teaching are important but can wait.', false),
  ('meds', 27, 'A nurse withholds a scheduled dose for a 5-year-old after calculating that it exceeds the safe range, and calls the provider, who will review the order. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Give the dose if the provider does not call back"}, {"id": "b", "text": "Give half the dose to stay within the safe range"}, {"id": "c", "text": "Document the reason the dose was withheld"}, {"id": "d", "text": "Wait to document until the provider gives orders"}]'::jsonb, '["c"]', 'The reason for any withheld dose is documented. The nurse does not give a dose in doubt or alter it without the provider, and documentation is not delayed.', false),
  ('meds', 28, 'A nurse orienting to a pediatric unit reviews route-specific practices with the preceptor. Which statements by the orienting nurse are correct? Select all that apply.', '[{"id": "a", "text": "An oral dose can be mixed into a full bottle of formula"}, {"id": "b", "text": "The rectal route is used when a child is vomiting"}, {"id": "c", "text": "IV fluids can run by gravity for small children"}, {"id": "d", "text": "A kitchen spoon is fine for liquid doses at home"}, {"id": "e", "text": "Subcutaneous sites rotate among abdomen, thigh, and upper arm"}]'::jsonb, '["b", "e"]', 'Correct: (b) rectal is used when the child is vomiting or unable to take orally; (e) subcutaneous sites are rotated (abdomen, thigh, upper arm). Wrong: (a) oral doses are NOT mixed in a full bottle; (c) IV always uses an infusion pump; (d) an oral syringe is used, not a kitchen spoon.', true),
  ('meds', 29, 'A 3-year-old refuses a liquid medication. The parent says, "Just tell him it''s candy—that is how we get him to take it at home." Which response by the nurse is BEST?', '[{"id": "a", "text": "Calling it candy is fine if we use an oral syringe"}, {"id": "b", "text": "That works best if we mix it into her full bottle of milk"}, {"id": "c", "text": "We can call it candy just this one time today"}, {"id": "d", "text": "Calling medicine candy is a safety and honesty issue"}]'::jsonb, '["d"]', 'Medicine is never called "candy" because it is a safety and honesty issue. Using an oral syringe does not make the practice acceptable, and doses are not mixed into a full bottle.', false),
  ('meds', 30, 'A nurse enters to give the second dose of an IV antibiotic to a 7-year-old and finds new raised hives on the trunk that the parent says appeared overnight. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Withhold the dose and report the reaction immediately"}, {"id": "b", "text": "Give the dose on time to adhere to the schedule"}, {"id": "c", "text": "Give the dose, then document the hives in detail"}, {"id": "d", "text": "Recheck the label 3 times, then give the dose as ordered"}]'::jsonb, '["a"]', 'The child is assessed before administering, and adverse reactions are reported immediately; giving the dose to stay on schedule or after a label check ignores the reaction.', false),
  ('meds', 31, 'A nurse is preparing to give an intramuscular (IM) injection to a 6-month-old. Which actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Select the deltoid if the arm looks large"}, {"id": "b", "text": "Inject into the abdomen, rotating sites"}, {"id": "c", "text": "Select the vastus lateralis (thigh)"}, {"id": "d", "text": "Give up to 1.5 mL in a single site"}, {"id": "e", "text": "Limit the volume to <1 mL in infants"}]'::jsonb, '["c", "e"]', 'Correct: (c) the vastus lateralis (thigh) is the safest IM site in infants; (e) IM volume is limited to less than 1 mL in infants. Wrong: (a) the deltoid is not the infant site; (b) the abdomen is a subcutaneous rotation site; (d) 1.5 mL exceeds the infant limit.', true),
  ('meds', 32, 'The parent of a 6-year-old who weighs about half as much as the parent plans to give the child half of the parent''s own prescription tablet. Which statement by the nurse BEST addresses this plan?', '[{"id": "a", "text": "Half a tablet is fine if she can swallow it"}, {"id": "b", "text": "Doses are weight-based; never use adult doses"}, {"id": "c", "text": "Crush it and mix it into a full bottle of juice"}, {"id": "d", "text": "Give it rectally if she cannot swallow tablets"}]'::jsonb, '["b"]', 'All pediatric doses are weight-based and adult doses are never used, even halved. The bottle and rectal options address how to give the drug, not the unsafe dose.', false),
  ('meds', 33, 'A nurse transcribing new pediatric orders reviews four dose entries. Which entry requires follow-up because of a decimal-point risk?', '[{"id": "a", "text": "0.5 mg"}, {"id": "b", "text": "0.25 mg"}, {"id": "c", "text": "5.0 mg"}, {"id": "d", "text": "5 mg"}]'::jsonb, '["c"]', 'Trailing zeros are not used (5.0 mg can be misread as 50 mg). 0.5 mg and 0.25 mg correctly use leading zeros, and 5 mg has no trailing zero.', false),
  ('meds', 34, 'A nurse is teaching the parent of a 2-year-old to give a liquid antibiotic at home every 6 hours. Which statements by the parent indicate understanding? Select all that apply.', '[{"id": "a", "text": "I''ll tell him it''s candy so he takes it"}, {"id": "b", "text": "I''ll use the oral syringe, not a kitchen spoon"}, {"id": "c", "text": "I won''t skip doses on the schedule"}, {"id": "d", "text": "I''ll report adverse reactions immediately"}, {"id": "e", "text": "I''ll mix it into his full bottle of milk"}]'::jsonb, '["b", "c", "d"]', 'Correct: (b) an oral syringe is used, not a kitchen spoon; (c) right time means adhering to the schedule and not skipping doses; (d) adverse reactions are reported immediately. Wrong: (a) medicine is never called candy; (e) doses are not mixed in a full bottle.', true),
  ('meds', 35, 'The parent of a 4-month-old asks to mix a prescribed oral antibiotic into the infant''s 8-oz bottle of formula so the infant will not taste it. Which response by the nurse is BEST?', '[{"id": "a", "text": "That is fine if the bottle is finished within an hour"}, {"id": "b", "text": "Tell her it is candy so that she will take it"}, {"id": "c", "text": "Use a kitchen spoon so that it goes in slowly"}, {"id": "d", "text": "Do NOT mix it in a full bottle; use an oral syringe"}]'::jsonb, '["d"]', 'Oral doses are given with an oral syringe and are NOT mixed into a full bottle; a kitchen spoon is not used, and medicine is never called candy.', false),
  ('meds', 36, 'A 4-kg infant is prescribed an oral medication 10 mg/kg per dose. The suspension on hand is 250 mg/5 mL. Which preparation is BEST?', '[{"id": "a", "text": "0.8 mL measured in an oral syringe"}, {"id": "b", "text": "0.8 mL measured in a kitchen spoon"}, {"id": "c", "text": "1.6 mL measured in an oral syringe"}, {"id": "d", "text": "0.16 mL measured in an oral syringe"}]'::jsonb, '["a"]', '10 mg/kg × 4 kg = 40 mg; 40 ÷ 50 mg/mL = 0.8 mL. Small or liquid doses are measured in an oral syringe, not a kitchen spoon; 0.16 mL comes from dividing by 250 instead of the concentration per mL.', false),
  ('meds', 37, 'An 8-kg infant is prescribed an intramuscular (IM) medication 5 mg/kg. The vial contains 50 mg/mL. Which preparation and site is MOST appropriate?', '[{"id": "a", "text": "0.8 mL in the deltoid"}, {"id": "b", "text": "0.8 mL in the vastus lateralis"}, {"id": "c", "text": "1.6 mL in the vastus lateralis (thigh)"}, {"id": "d", "text": "0.4 mL in the vastus lateralis"}]'::jsonb, '["b"]', '5 mg/kg × 8 kg = 40 mg; 40 ÷ 50 mg/mL = 0.8 mL, which is under the infant limit of less than 1 mL, and the vastus lateralis (thigh) is the safest infant IM site.', false),
  ('meds', 38, 'A nurse is teaching the parent of an 8-year-old who will need subcutaneous injections at home. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Rotate sites between the abdomen and thigh"}, {"id": "b", "text": "Use the same thigh site for every dose"}, {"id": "c", "text": "Include the upper arm in site rotation"}, {"id": "d", "text": "Use a small gauge needle for injections"}, {"id": "e", "text": "Choose the site that hurts least each time"}]'::jsonb, '["a", "c", "d"]', 'Correct: (a) and (c) subcutaneous sites are rotated among the abdomen, thigh, and upper arm; (d) a small gauge needle is used. Wrong: (b) and (e) using the same or a favorite site defeats site rotation.', true),
  ('meds', 39, 'A 30-kg child has an order for 250 mg of an oral medication. The drug reference lists a safe range of 5–10 mg/kg per dose. Which action by the nurse is BEST?', '[{"id": "a", "text": "Hold the dose; it exceeds the safe range"}, {"id": "b", "text": "Give 150 mg, the low end of the safe range"}, {"id": "c", "text": "Give the dose; it is within the safe range"}, {"id": "d", "text": "Call the provider; the dose is below the range"}]'::jsonb, '["c"]', '5–10 mg/kg × 30 kg = 150–300 mg, so 250 mg is within the safe range from the drug reference and can be given; changing the dose or calling for a safe dose is not needed.', false),
  ('meds', 40, 'A nurse is preparing a weight-based oral dose for a child whose weight is recorded in pounds and whose medication is a liquid suspension. In which order should the nurse perform the steps?', '[{"id": "a", "text": "Calculate dose, then convert to kg, compare to range, calculate volume"}, {"id": "b", "text": "Convert to kg, calculate volume, calculate dose, compare to range"}, {"id": "c", "text": "Compare to range, convert to kg, calculate dose, calculate volume"}, {"id": "d", "text": "Convert to kg, calculate dose, compare to range, calculate volume"}]'::jsonb, '["d"]', 'The steps are: convert weight (lbs ÷ 2.2 = kg), calculate dose (mg/kg × kg), compare to the safe dose range, then calculate volume if needed. Calculating the dose before converting would use pounds.', false),
  ('meds', 41, 'Thirty minutes after a first oral dose of a new antibiotic, a 5-year-old develops hives and the parent is upset. Which actions should the nurse take? Select all that apply.', '[{"id": "a", "text": "Give the next dose on schedule to avoid a gap"}, {"id": "b", "text": "Report the adverse reaction immediately"}, {"id": "c", "text": "Wait until morning rounds to tell the provider"}, {"id": "d", "text": "Document everything about the reaction"}, {"id": "e", "text": "Tell the child the next dose is candy"}]'::jsonb, '["b", "d"]', 'Correct: (b) adverse reactions are reported immediately; (d) everything is documented. Wrong: (a) giving the next dose ignores the reaction; (c) waiting delays an immediate report; (e) medicine is never called candy.', true),
  ('meds', 42, 'A nurse observes a parent practicing eye drop administration for a 4-year-old before discharge. Which action by the parent requires follow-up?', '[{"id": "a", "text": "Touches the dropper tip to the lashes"}, {"id": "b", "text": "Pulls the lower eyelid down to form a pouch"}, {"id": "c", "text": "Places the drops into the lower lid pouch"}, {"id": "d", "text": "Checks the label before the dose"}]'::jsonb, '["a"]', 'The dropper tip must NOT touch the eye or lashes. Pulling the lower eyelid down to create a pouch and placing drops there is correct.', false),
  ('meds', 43, 'The parent of a 6-year-old is taught to give ear drops at home. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "I will pull his ear up and back"}, {"id": "b", "text": "I will pull his ear down and back"}, {"id": "c", "text": "I will check the label before each dose"}, {"id": "d", "text": "I will report any adverse reactions"}]'::jsonb, '["b"]', 'At 3 years and older, the pinna is pulled UP and back; down and back is for children under 3. Checking the label and reporting reactions are correct.', false),
  ('meds', 44, 'The parent of a newborn asks why the infant''s medication must be dosed so carefully. Which explanations by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "Her liver is immature, so drug metabolism is altered"}, {"id": "b", "text": "Her kidneys are immature, so drug excretion is altered"}, {"id": "c", "text": "She has a lower body water ratio than an adult"}, {"id": "d", "text": "She has a higher body water ratio, so distribution differs"}, {"id": "e", "text": "Adult doses are safe if cut in half for infants"}]'::jsonb, '["a", "b", "d"]', 'Correct: (a) and (b) an immature liver and kidneys alter drug metabolism and excretion; (d) a higher body water ratio causes different drug distribution. Wrong: (c) the ratio is higher, not lower; (e) all doses are weight-based — never adult doses.', true),
  ('meds', 45, 'At 2100, a nurse working alone at the medication cart has drawn up bedtime insulin for a 12-year-old and has checked the label at prep and pour. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Give the insulin, then record it at once"}, {"id": "b", "text": "Ask the child to read the syringe dose"}, {"id": "c", "text": "Have another nurse double-check the dose"}, {"id": "d", "text": "Check the label again, then give the dose"}]'::jsonb, '["c"]', 'Insulin is a high-alert medication that requires a double-check with another nurse before it is given; the child reading the syringe does not replace this check, and a third label check alone is not enough.', false),
  ('meds', 46, 'A nurse is instilling prescribed eye drops for a cooperative 5-year-old who is lying supine and looking up. Which technique is BEST?', '[{"id": "a", "text": "Pull the upper eyelid up and drop on the iris"}, {"id": "b", "text": "Rest the dropper tip on the lower lashes"}, {"id": "c", "text": "Pull the pinna up and back to open the eye"}, {"id": "d", "text": "Pull the lower eyelid down to create a pouch"}]'::jsonb, '["d"]', 'Eye drops are placed by pulling the lower eyelid down to create a pouch; the dropper tip must not touch the eye or lashes. Pulling the pinna is the ear-drop technique.', false),
  ('meds', 47, 'A nurse is preparing several pediatric doses on a medical unit. In which situations should the nurse withhold the dose and call the provider? Select all that apply.', '[{"id": "a", "text": "The calculated dose exceeds the safe range"}, {"id": "b", "text": "The child is asleep at the scheduled time"}, {"id": "c", "text": "The ordered IM volume for an infant is 1.5 mL"}, {"id": "d", "text": "The dose is within the safe range for the kg weight"}, {"id": "e", "text": "The child had adverse reactions to the last dose"}]'::jsonb, '["a", "c", "e"]', 'Correct: (a) when in doubt about dose safety, do NOT give and call the provider; (c) infant IM volume is limited to less than 1 mL; (e) allergies are checked before administering and adverse reactions are reported immediately. Wrong: (b) right time means not skipping doses; (d) a dose within the safe range can be given.', true),
  ('meds', 48, 'A nurse discovers that a toddler''s weight of 22 lb was entered as 22 kg. The order is 10 mg/kg per dose. Which dose is correct for this toddler?', '[{"id": "a", "text": "100 mg"}, {"id": "b", "text": "220 mg"}, {"id": "c", "text": "484 mg"}, {"id": "d", "text": "48.4 mg"}]'::jsonb, '["a"]', '22 lb ÷ 2.2 = 10 kg; 10 mg/kg × 10 kg = 100 mg. 220 mg is the dose that the weight-entry error (using the pound value as kg) would produce, so dose calculation must always use kg.', false),
  ('meds', 49, 'A nurse documents the 1000 oral antibiotic for a 4-year-old as given at 0950, then walks to the room to give it. Which statement BEST describes this practice?', '[{"id": "a", "text": "It is acceptable if the dose is given within 1 hour"}, {"id": "b", "text": "It requires correction; record immediately after giving"}, {"id": "c", "text": "It is acceptable because it saves time for other children"}, {"id": "d", "text": "It requires correction; record at the end of the shift"}]'::jsonb, '["b"]', 'Right documentation is recording immediately after giving, not before; charting before giving or at the end of the shift does not meet this standard.', false),
  ('meds', 50, 'A nurse is reviewing which children on the unit may need a different route for their scheduled medications. For which child is a request for the rectal route MOST appropriate?', '[{"id": "a", "text": "A 5-year-old who dislikes the taste of the liquid medicine"}, {"id": "b", "text": "A 10-month-old who is sleeping at the dose time"}, {"id": "c", "text": "A 2-year-old who is vomiting and unable to take orally"}, {"id": "d", "text": "An 8-year-old who prefers liquids over tablets"}]'::jsonb, '["c"]', 'The rectal route is used when a child is vomiting or unable to take orally. Dislike of taste, sleep, or a preference for liquids does not make the child unable to take orally.', false),
  ('newborn', 1, 'At 1 minute after birth, a newborn has a heart rate of 90 bpm, a pink body with blue extremities, a grimace when the soles are flicked, some flexion of the extremities, and slow, irregular respirations. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Begin resuscitation with O₂ and possible intubation"}, {"id": "b", "text": "Continue routine care; this is a stable newborn"}, {"id": "c", "text": "Stimulate the newborn and reassess"}, {"id": "d", "text": "Wait for the 5-minute score before taking action"}]'::jsonb, '["c"]', 'Each finding scores 1 (pulse <100 bpm, blue extremities with pink body, grimace, some flexion, slow/irregular respirations), for an APGAR of 5; a score of 4–6 means moderate distress — stimulate and reassess. Resuscitation with O₂ and possible intubation is for a score of 0–3.', false),
  ('newborn', 2, 'The nurse observes care in the newborn nursery. Which situations place a newborn at risk for heat loss? Select all that apply.', '[{"id": "a", "text": "Placing the newborn on a cold surface (scale)"}, {"id": "b", "text": "Newborn left with wet skin after birth"}, {"id": "c", "text": "Placing a knit cap on the newborn''s head"}, {"id": "d", "text": "Crib in an air current from a fan"}, {"id": "e", "text": "Bassinet placed by nearby cold objects (window)"}]'::jsonb, '["a", "b", "d", "e"]', 'Newborns lose heat by conduction (cold surface such as a scale), evaporation (wet skin), convection (air current such as a fan), and radiation (nearby cold objects such as a window) — so those four are risks. A knit cap is a nursing action that prevents heat loss.', true),
  ('newborn', 3, 'A term newborn is delivered vaginally and placed on the mother''s abdomen. The newborn is crying vigorously, is pink with blue hands and feet, and is wet with amniotic fluid. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Dry the newborn immediately and place skin-to-skin"}, {"id": "b", "text": "Give vitamin K (phytonadione) IM into the vastus lateralis"}, {"id": "c", "text": "Apply erythromycin ointment to both eyes"}, {"id": "d", "text": "Perform the heel stick for the metabolic screen"}]'::jsonb, '["a"]', 'Thermoregulation is the #1 priority at birth, so a wet, stable newborn is dried immediately and placed skin-to-skin. Vitamin K and erythromycin are given within the first hour, after warmth is ensured, and the heel stick is done after 24 hours of feeding.', false),
  ('newborn', 4, 'A breastfed newborn weighed 3,500 g at birth and weighs 3,200 g on day 3. The parent is worried the baby is "starving." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"She has lost more than 10%, so formula supplements are needed.\""}, {"id": "b", "text": "\"Losing up to 10% is normal; she should regain it by 2 weeks.\""}, {"id": "c", "text": "\"Any weight loss in the first week should be reported today.\""}, {"id": "d", "text": "\"She should be back to her birth weight within the next 3 days.\""}]'::jsonb, '["b"]', 'A 300-g loss from 3,500 g is about 8.6%, and it is normal to lose up to 10% of birth weight in the first few days and regain it by 2 weeks. The tempting response that she has lost more than 10% misreads the calculation.', false),
  ('newborn', 5, 'A nurse reviews the assessment data for several newborns in the nursery. Which findings should be reported to the provider IMMEDIATELY? Select all that apply.', '[{"id": "a", "text": "Jaundice noted at 18 hours of age"}, {"id": "b", "text": "Green, bilious vomiting after a feeding"}, {"id": "c", "text": "Yellow, seedy, loose stools in a breastfed newborn"}, {"id": "d", "text": "Cyanosis of the lips and tongue"}, {"id": "e", "text": "Lethargy; difficult to arouse for feedings"}]'::jsonb, '["a", "b", "d", "e"]', 'Danger signs to report immediately include jaundice in the first 24 hours (pathological), green/bilious vomiting (suggests obstruction), central cyanosis of the lips and tongue, and lethargy or being difficult to arouse — so those four are correct. Yellow, seedy, loose stools are the expected breastfed stool pattern.', true),
  ('newborn', 6, 'The nurse is preparing to give vitamin K (phytonadione) to a newborn who is 30 minutes old and is skin-to-skin with the mother. Which route and site is BEST?', '[{"id": "a", "text": "Orally, mixed with a small amount of colostrum"}, {"id": "b", "text": "IM into the deltoid"}, {"id": "c", "text": "Subcutaneously in the abdomen"}, {"id": "d", "text": "IM into the vastus lateralis"}]'::jsonb, '["d"]', 'Vitamin K is given as an IM injection into the vastus lateralis within the first hour of birth. An oral dose mixed with colostrum is not the route used for this newborn medication.', false),
  ('newborn', 7, 'During well-baby visits, the nurse assesses reflexes in four infants. Which finding requires follow-up?', '[{"id": "a", "text": "A 2-month-old whose arms extend wide and then flex inward after a loud noise"}, {"id": "b", "text": "A 3-month-old who turns toward a cheek touch and opens the mouth"}, {"id": "c", "text": "A 7-month-old whose arms extend wide then flex inward after a loud noise"}, {"id": "d", "text": "A 10-month-old whose toes fan out when the outer sole is stroked"}]'::jsonb, '["c"]', 'The Moro (startle) reflex disappears at about 4 months, so it persisting at 7 months requires follow-up. Rooting at 3 months (disappears ~4 months) and Babinski at 10 months (disappears ~12–18 months) are expected.', false),
  ('newborn', 8, 'A breastfed newborn is 4 days old. The nurse reviews the elimination record the parents have kept since birth. Which entries are expected findings? Select all that apply.', '[{"id": "a", "text": "Thick, greenish-black stool at 14 hours of age"}, {"id": "b", "text": "1 wet diaper on day 1"}, {"id": "c", "text": "Green-yellow-brown stools on day 3"}, {"id": "d", "text": "2 wet diapers on day 4"}, {"id": "e", "text": "First stool passed at 30 hours of age"}]'::jsonb, '["a", "b", "c"]', 'Meconium is thick and greenish-black within the first 24 hours, 1 wet diaper is expected on day 1, and transitional green-yellow-brown stool appears by days 2–4 — so those three are expected. Wet diapers should increase to 6–8/day by day 4–5, so 2 on day 4 is too few, and no meconium in 24 hours must be reported.', true),
  ('newborn', 9, 'A formula-fed newborn began feeding at 2 hours of age. The parents request early discharge, and the heel stick metabolic screen is drawn at 16 hours of age. Which action is MOST important for the nurse?', '[{"id": "a", "text": "Arrange a repeat heel stick after 24h of feeding"}, {"id": "b", "text": "Reassure the parents an early screen is more accurate"}, {"id": "c", "text": "Replace the heel stick with a transcutaneous bilirubin"}, {"id": "d", "text": "Document the result as final for PKU and galactosemia"}]'::jsonb, '["a"]', 'The heel stick for PKU, congenital hypothyroidism, and galactosemia must be done after 24h of feeding; one drawn after only 14 hours of feeding can give a false negative, so it is repeated. Treating it as final ignores the false-negative risk.', false),
  ('newborn', 10, 'The nurse assesses four quietly resting newborns at 6 hours of age. Which finding requires follow-up?', '[{"id": "a", "text": "Temperature 98.4°F (36.9°C)"}, {"id": "b", "text": "Heart rate 172 bpm"}, {"id": "c", "text": "Respiratory rate 52 breaths/min"}, {"id": "d", "text": "SpO₂ 97% on room air"}]'::jsonb, '["b"]', 'Normal newborn heart rate is 110–160 bpm, so 172 bpm at rest is outside the range. A temperature of 98.4°F is within 97.7–99.5°F, respirations of 52 are within 30–60, and SpO₂ 97% meets ≥95%.', false),
  ('newborn', 11, 'The nurse reviews safe sleep with the parents of a newborn before discharge. Which statements by the parents indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"We''ll lay her on her back for every sleep.\""}, {"id": "b", "text": "\"Bumper pads will keep her from hitting the crib.\""}, {"id": "c", "text": "\"She''ll sleep in her own bassinet in our room.\""}, {"id": "d", "text": "\"She can nap on her tummy when we''re watching.\""}, {"id": "e", "text": "\"Her crib mattress will be firm and flat.\""}]'::jsonb, '["a", "c", "e"]', 'Safe sleep means back to sleep, a firm, flat mattress in the infant''s own crib or bassinet, and room-sharing (not bed-sharing) for the first 6–12 months — so those three statements are correct. Bumper pads are not allowed in the crib, and the infant always sleeps on the back, never prone.', true),
  ('newborn', 12, 'At 5 minutes, a newborn has a heart rate of 132 bpm, a pink body with blue hands and feet, cries when the soles are flicked, shows active motion, and has a strong cry. Which APGAR score and interpretation is the nurse MOST likely to document?', '[{"id": "a", "text": "10 — stable newborn"}, {"id": "b", "text": "8 — stable newborn"}, {"id": "c", "text": "7 — moderate distress"}, {"id": "d", "text": "9 — stable newborn"}]'::jsonb, '["d"]', 'Pulse ≥100 bpm (2), blue extremities with pink body (1), cry (2), active motion (2), and strong cry (2) total 9, and 7–10 is a stable newborn. A score of 10 would require pink color all over.', false),
  ('newborn', 13, 'The parent of a 5-day-old whose umbilical cord stump is still attached makes the following statements. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll give her tub baths so the cord stays clean.\""}, {"id": "b", "text": "\"I''ll fold her diaper down below the cord stump.\""}, {"id": "c", "text": "\"I''ll let the stump fall off on its own.\""}, {"id": "d", "text": "\"I''ll call if I notice redness or a foul odor at the cord.\""}]'::jsonb, '["a"]', 'No tub baths are given until the cord falls off naturally in 1–2 weeks. Folding the diaper below the stump, letting it fall off without pulling, and reporting redness or foul odor are correct.', false),
  ('newborn', 14, 'A 2-hour-old newborn''s axillary temperature is 97.2°F (36.2°C) after the newborn was left unwrapped during an assessment. The mother asks to hold her baby. Which action by the nurse is BEST?', '[{"id": "a", "text": "Give a warm tub bath to raise the temperature"}, {"id": "b", "text": "Place skin-to-skin with warm blankets and a knit cap"}, {"id": "c", "text": "Feed formula mixed with extra warm water"}, {"id": "d", "text": "Leave the newborn unwrapped and recheck the temperature in 4 hours"}]'::jsonb, '["b"]', 'A temperature below 97.7°F means the newborn is losing heat; skin-to-skin contact, warm blankets, and a knit cap are nursing actions for thermoregulation. A tub bath is not given until the cord falls off and wet skin causes evaporative heat loss.', false),
  ('newborn', 15, 'The nurse is giving routine medications to a newborn within 1 hour of birth. Which actions by the nurse are correct? Select all that apply.', '[{"id": "a", "text": "Give vitamin K IM into the vastus lateralis"}, {"id": "b", "text": "Flush the eyes with saline after the ointment"}, {"id": "c", "text": "Apply erythromycin ointment to both eyes"}, {"id": "d", "text": "Wipe excess ointment after 1 minute"}, {"id": "e", "text": "Delay vitamin K until after the first bath"}]'::jsonb, '["a", "c", "d"]', 'Vitamin K is given IM into the vastus lateralis within the first hour, and erythromycin ointment is applied to both eyes within 1 hour, with excess wiped after 1 minute — so those three are correct. The eyes are not flushed, and vitamin K is not delayed past the first hour of birth.', true),
  ('newborn', 16, 'A newborn weighed 3,400 g at birth and weighs 3,020 g on day 4. The parent reports the newborn is sleepy at the breast. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Reassure the parent this loss is within normal limits"}, {"id": "b", "text": "Advise feeding every 4 hours to let the newborn rest"}, {"id": "c", "text": "Report the weight loss of more than 10% to the provider"}, {"id": "d", "text": "Recheck the weight in 2 weeks, when it should be regained"}]'::jsonb, '["c"]', 'A 380-g loss from 3,400 g is about 11.2%, which exceeds the normal loss of up to 10%, and poor feeding is a danger sign. Reassurance would apply only to a loss of 10% or less.', false),
  ('newborn', 17, 'The nurse observes a UAP performing the critical congenital heart defect (CCHD) screen on a 26-hour-old newborn. Which action by the UAP requires IMMEDIATE correction?', '[{"id": "a", "text": "Applying the pulse oximeter to the right hand"}, {"id": "b", "text": "Performing the screen before the newborn''s discharge"}, {"id": "c", "text": "Waiting until the newborn was 24 hours old"}, {"id": "d", "text": "Placing the second probe on the left hand"}]'::jsonb, '["d"]', 'The CCHD screen uses pulse oximetry on the right hand and a foot, so a second reading on the left hand is incorrect. Doing the screen at 24 hours or before discharge is correct.', false),
  ('newborn', 18, 'The nurse assigns a 5-minute APGAR score to a newborn. Which findings each earn a score of 2? Select all that apply.', '[{"id": "a", "text": "Heart rate of 96 bpm"}, {"id": "b", "text": "Pink body with blue extremities"}, {"id": "c", "text": "Cry, cough, or sneeze to stimulation"}, {"id": "d", "text": "Some flexion of the extremities"}, {"id": "e", "text": "Heart rate of 104 bpm"}]'::jsonb, '["c", "e"]', 'A cry, cough, or sneeze earns 2 for grimace, and a pulse of ≥100 bpm earns 2, so those two findings score 2. A heart rate of 96 is <100 bpm (1), blue extremities with a pink body score 1, and some flexion scores 1.', true),
  ('newborn', 19, 'The parent of a 4-day-old breastfed newborn reports 2 wet diapers in the past 24 hours. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Output is below expected and needs follow-up"}, {"id": "b", "text": "This output is expected on the fourth day of life"}, {"id": "c", "text": "Wet diapers increase only after the first 2 weeks"}, {"id": "d", "text": "Breastfed newborns normally have 1 wet diaper a day"}]'::jsonb, '["a"]', 'Wet diapers increase from 1 on day 1 to 6–8/day by day 4–5, so 2 on day 4 is below the expected pattern. One wet diaper is expected only on day 1.', false),
  ('newborn', 20, 'A newly hired nurse is giving eye prophylaxis to a 40-minute-old newborn. Which action by the new nurse requires IMMEDIATE correction?', '[{"id": "a", "text": "Applying erythromycin ointment to both eyes"}, {"id": "b", "text": "Giving the ointment within 1 hour of birth"}, {"id": "c", "text": "Flushing the ointment from the eyes"}, {"id": "d", "text": "Wiping away excess ointment after 1 minute"}]'::jsonb, '["c"]', 'Erythromycin ointment is applied to both eyes within 1 hour of birth, and excess is wiped after 1 minute; it is not flushed from the eyes. All the other actions are correct.', false),
  ('newborn', 21, 'The nurse assesses a healthy 3-month-old at a well-baby visit. Which reflexes are expected findings at this age? Select all that apply.', '[{"id": "a", "text": "Moro (startle)"}, {"id": "b", "text": "Rooting"}, {"id": "c", "text": "Stepping"}, {"id": "d", "text": "Palmar grasp"}, {"id": "e", "text": "Babinski"}]'::jsonb, '["a", "b", "d", "e"]', 'At 3 months, the Moro (~4 months), rooting (~4 months), palmar grasp (~5–6 months), and Babinski (~12–18 months) reflexes are still present, so those four are expected. The stepping reflex disappears at about 2 months.', true),
  ('newborn', 22, 'A newborn''s bassinet is placed against the outside wall beside a cold window. The newborn is swaddled and is not touching the wall or window. Which mechanism of heat loss is MOST likely occurring?', '[{"id": "a", "text": "Evaporation"}, {"id": "b", "text": "Conduction"}, {"id": "c", "text": "Convection"}, {"id": "d", "text": "Radiation"}]'::jsonb, '["d"]', 'Radiation is heat loss to nearby cold objects that the newborn is not touching. Conduction requires contact with a cold surface, and convection involves an air current.', false),
  ('newborn', 23, 'A lightly dressed 3-day-old newborn has an axillary temperature of 100.4°F (38°C). The newborn is feeding well. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Remove a layer and recheck in 1 hour before reporting"}, {"id": "b", "text": "Report the temperature to the provider"}, {"id": "c", "text": "Document it as normal newborn temperature variation"}, {"id": "d", "text": "Give a tepid sponge bath and recheck in 30 minutes"}]'::jsonb, '["b"]', 'A fever of ≥100.4°F (38°C) in a newborn must always be reported. Normal newborn temperature is 97.7–99.5°F, so this is not normal variation, and delaying the report to recheck is unsafe.', false),
  ('newborn', 24, 'The parent of a formula-fed 1-week-old makes the following statements during a follow-up visit. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I add a little extra water so each can lasts longer.\""}, {"id": "b", "text": "\"I feed him about every 3 to 4 hours.\""}, {"id": "c", "text": "\"I follow the mixing instructions on the can exactly.\""}, {"id": "d", "text": "\"He should be back to his birth weight by 2 weeks.\""}]'::jsonb, '["a"]', 'Formula must be mixed exactly according to the instructions to give the correct concentration, so adding extra water needs correction. Feeding every 3–4 hours and regaining birth weight by 2 weeks are correct.', false),
  ('newborn', 25, 'The nurse teaches cord care to the parents of a newborn going home at 2 days of age. Which instructions are appropriate? Select all that apply.', '[{"id": "a", "text": "Keep the cord stump dry and clean"}, {"id": "b", "text": "Give a tub bath daily until the stump falls off"}, {"id": "c", "text": "Cover the stump with the top of the diaper"}, {"id": "d", "text": "Fold the diaper below the cord stump"}, {"id": "e", "text": "Gently pull the stump off once it loosens"}]'::jsonb, '["a", "d"]', 'Cord care is to keep the stump dry and clean and fold the diaper below it, so those two are correct. Tub baths are avoided until the cord falls off, covering it with the diaper contradicts folding the diaper below it, and the stump is never pulled or removed forcefully.', true),
  ('newborn', 26, 'A nurse is assessing several newborns during the night shift. Which finding should the nurse report to the provider IMMEDIATELY?', '[{"id": "a", "text": "Meconium stool passed at 12 hours of age"}, {"id": "b", "text": "One wet diaper on the first day of life"}, {"id": "c", "text": "Jaundice noted at 20 hours of age"}, {"id": "d", "text": "Toes fanning out when the outer sole is stroked"}]'::jsonb, '["c"]', 'Jaundice in the first 24 hours is pathological and must be reported immediately. Meconium within 24 hours, 1 wet diaper on day 1, and a Babinski response with toes fanning out are expected.', false),
  ('newborn', 27, 'At 1 minute, a newborn is limp and pale all over, has no response to stimulation, has a heart rate of 70 bpm, and has slow, irregular respirations. Which action is the PRIORITY?', '[{"id": "a", "text": "Dry the newborn, place skin-to-skin, and continue routine care"}, {"id": "b", "text": "Stimulate and reassess at the 5-minute APGAR"}, {"id": "c", "text": "Give vitamin K and erythromycin, then reassess"}, {"id": "d", "text": "Begin resuscitation with warmth, stimulation, and O₂"}]'::jsonb, '["d"]', 'Pale (0), no response (0), limp (0), pulse <100 bpm (1), and slow/irregular respirations (1) give an APGAR of 2; a score of 0–3 is an emergency requiring resuscitation (warmth, stimulate, O₂, possible intubation). Stimulating and reassessing is the plan for a score of 4–6.', false),
  ('newborn', 28, 'The nurse assesses a 12-hour-old term newborn who is resting quietly. Which findings are within normal limits? Select all that apply.', '[{"id": "a", "text": "Respiratory rate 66 breaths/min"}, {"id": "b", "text": "Temperature 98.6°F (37°C)"}, {"id": "c", "text": "Heart rate 148 bpm"}, {"id": "d", "text": "SpO₂ 93% on room air"}, {"id": "e", "text": "Blood pressure 70/45 mmHg"}]'::jsonb, '["b", "c", "e"]', 'Normal newborn values are temperature 97.7–99.5°F (36.5–37.5°C), heart rate 110–160 bpm, and BP about 60–80/40–50 mmHg, so those three are normal. Respirations should be 30–60/min, so 66 is high, and SpO₂ should be ≥95% after the first few hours, so 93% is low.', true),
  ('newborn', 29, 'The parents of a healthy newborn ask why their baby needs a vitamin K injection when no one in the family has a bleeding problem. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"It prevents eye infection from gonorrhea and chlamydia.\""}, {"id": "b", "text": "\"Newborns lack the gut flora to make it, so it prevents VKDB.\""}, {"id": "c", "text": "\"It is needed so the heel stick for PKU is accurate.\""}, {"id": "d", "text": "\"It protects the newborn from cold stress and hypoglycemia.\""}]'::jsonb, '["b"]', 'Newborns lack gut flora to produce vitamin K, so the injection prevents Vitamin K Deficiency Bleeding (VKDB) regardless of family history. Preventing eye infection from gonorrhea and chlamydia is the purpose of erythromycin ointment.', false),
  ('newborn', 30, 'The nurse makes a home visit to a 2-week-old. Which observation requires IMMEDIATE intervention by the nurse?', '[{"id": "a", "text": "Pillows and stuffed animals are in the crib with the infant"}, {"id": "b", "text": "The sleeping infant is on the back in a crib in the parents'' room"}, {"id": "c", "text": "The crib has a firm, flat mattress with a fitted sheet"}, {"id": "d", "text": "The parent places the infant on the back after a feeding"}]'::jsonb, '["a"]', 'No pillows, stuffed animals, bumper pads, or loose blankets should be in the crib. Sleeping on the back in the infant''s own crib in the parents'' room on a firm, flat mattress is safe sleep.', false),
  ('newborn', 31, 'During a well-baby visit, the nurse strokes the outer sole of a 10-month-old''s foot, and the toes fan out. Which interpretation is MOST accurate?', '[{"id": "a", "text": "Abnormal; this reflex should disappear by about 4 months"}, {"id": "b", "text": "Abnormal; the stepping reflex should be absent by now"}, {"id": "c", "text": "Expected; this reflex disappears at about 12–18 months"}, {"id": "d", "text": "Expected; it shows the palmar grasp is still present"}]'::jsonb, '["c"]', 'Stroking the outer sole elicits the Babinski reflex (toes fan out), which disappears at about 12–18 months, so it is expected at 10 months. Disappearance at about 4 months applies to the Moro, rooting, and sucking reflexes.', false),
  ('newborn', 32, 'A newborn is found with a below-normal temperature after being left unwrapped on a cold surface. Which complications of cold stress should the nurse assess for? Select all that apply.', '[{"id": "a", "text": "Hyperglycemia"}, {"id": "b", "text": "Hypoglycemia"}, {"id": "c", "text": "Increased O₂ demand"}, {"id": "d", "text": "Respiratory distress"}, {"id": "e", "text": "Decreased O₂ demand"}]'::jsonb, '["b", "c", "d"]', 'Cold stress causes hypoglycemia, increased O₂ demand, and respiratory distress, so those three are correct. Hyperglycemia and decreased O₂ demand are the opposite of what cold stress causes.', true),
  ('newborn', 33, 'A breastfeeding parent''s log for the past 24 hours shows 6 feedings for a 2-day-old newborn. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "This meets the expected 6–8 feedings per day"}, {"id": "b", "text": "Breastfed newborns need to feed every 3–4 hours"}, {"id": "c", "text": "Feedings are adequate as long as there is meconium"}, {"id": "d", "text": "This is fewer than the expected 8–12 feedings in 24 hours"}]'::jsonb, '["d"]', 'Breastfed newborns feed every 2–3 hours, 8–12 times in 24 hours, so 6 feedings is too few. The 6–8 figure is the number of wet diapers per day by day 4–5, and every 3–4 hours is the formula-feeding schedule.', false),
  ('newborn', 34, 'At a 1-week follow-up visit, the nurse assesses the cord stumps of four newborns. Which finding requires follow-up?', '[{"id": "a", "text": "A dry stump that is still attached at 7 days"}, {"id": "b", "text": "Redness around the stump with a foul odor"}, {"id": "c", "text": "A stump that the parent keeps clean and dry"}, {"id": "d", "text": "A stump with the diaper folded below it"}]'::jsonb, '["b"]', 'Redness, foul odor, and drainage at the cord are signs of omphalitis (infection) and must be reported. A dry stump still attached at 7 days is expected because the cord falls off in 1–2 weeks.', false),
  ('newborn', 35, 'Before discharge, a parent asks what the heel stick blood test will check for. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"It screens for PKU, congenital hypothyroidism, and galactosemia.\""}, {"id": "b", "text": "\"It checks oxygen levels in the hand and foot to find heart defects.\""}, {"id": "c", "text": "\"It measures how well your baby can hear sounds.\""}, {"id": "d", "text": "\"It checks for bleeding problems from low vitamin K.\""}]'::jsonb, '["a"]', 'The heel stick metabolic screen tests for PKU, congenital hypothyroidism, and galactosemia. Pulse oximetry on the right hand and foot is the CCHD screen for critical heart defects.', false),
  ('newborn', 36, 'A healthy term newborn is being prepared for discharge at 30 hours of age after 28 hours of breastfeeding. Which screening actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Pulse oximetry on the right hand and a foot"}, {"id": "b", "text": "Heel stick metabolic screen drawn now"}, {"id": "c", "text": "Pulse oximetry on both hands"}, {"id": "d", "text": "Hearing screen deferred to the 2-month visit"}, {"id": "e", "text": "Serum bilirubin only if the newborn is pale"}]'::jsonb, '["a", "b"]', 'The CCHD screen uses pulse oximetry on the right hand plus a foot, and the heel stick is done after 24h of feeding, which this newborn has completed — so both are correct. Both hands is the wrong site, the hearing screen (OAE or ABR) is done before discharge, and bilirubin is checked if jaundice is suspected, not pallor.', true),
  ('newborn', 37, 'A term newborn is 26 hours old and has not passed meconium, although the newborn is feeding well. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Document as expected, since meconium may take up to 48 hours"}, {"id": "b", "text": "Offer more frequent feedings and recheck at 48 hours"}, {"id": "c", "text": "Reassure the parent that breastfed stools come later"}, {"id": "d", "text": "Report it; it may suggest Hirschsprung''s disease or CF"}]'::jsonb, '["d"]', 'Meconium is expected within the first 24 hours; no meconium in 24 hours suggests Hirschsprung''s disease or cystic fibrosis and is reported to the provider. Waiting until 48 hours ignores this threshold.', false),
  ('newborn', 38, 'At 5 minutes, a newborn has a heart rate of 100 bpm, a pink body with blue extremities, a grimace to stimulation, some flexion, and a strong cry. Which interpretation is MOST accurate?', '[{"id": "a", "text": "Score of 6; moderate distress — stimulate and reassess"}, {"id": "b", "text": "Score of 5; moderate distress — stimulate and reassess"}, {"id": "c", "text": "Score of 7; stable newborn"}, {"id": "d", "text": "Score of 3; emergency — begin resuscitation"}]'::jsonb, '["c"]', 'A pulse of 100 is ≥100 bpm (2); blue extremities with pink body (1), grimace (1), some flexion (1), and strong cry (2) total 7, which is a stable newborn. Scoring the heart rate as 1 gives 6, the tempting but wrong answer.', false),
  ('newborn', 39, 'A parent asks why ointment is being put in the newborn''s eyes within an hour of birth when the parent has no symptoms of infection. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"It prevents bleeding, because newborns lack vitamin K.\""}, {"id": "b", "text": "\"It prevents ophthalmia neonatorum from gonorrhea and chlamydia.\""}, {"id": "c", "text": "\"It keeps the eyes moist and clean until the tear ducts open.\""}, {"id": "d", "text": "\"It treats the jaundice that often starts in the eyes.\""}]'::jsonb, '["b"]', 'Erythromycin eye ointment is applied to both eyes within 1 hour of birth to prevent ophthalmia neonatorum from gonorrhea and chlamydia. Preventing bleeding is the purpose of vitamin K.', false),
  ('newborn', 40, 'At 1 minute, a newborn has an APGAR score of 3. Which interventions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Delay action until the 5-minute score"}, {"id": "b", "text": "Warmth"}, {"id": "c", "text": "Stimulate the newborn"}, {"id": "d", "text": "O₂"}, {"id": "e", "text": "Possible intubation"}]'::jsonb, '["b", "c", "d", "e"]', 'An APGAR of 0–3 is an emergency: begin resuscitation with warmth, stimulation, O₂, and possible intubation — so those four are correct. Delaying action until the 5-minute score wastes time in an emergency.', true),
  ('newborn', 41, 'A parent asks why the nurse keeps a knit cap on the newborn and keeps the room warm. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"Newborns shiver easily, so they waste energy to stay warm.\""}, {"id": "b", "text": "\"Newborns have extra brown fat, but they burn it quickly.\""}, {"id": "c", "text": "\"Newborns have thick skin but a small body surface area.\""}, {"id": "d", "text": "\"Newborns have thin skin, large surface area, and can''t shiver.\""}]'::jsonb, '["d"]', 'Newborns lose heat rapidly because of thin skin, a large body surface area, no shivering mechanism, and limited brown fat stores. They do not shiver and have limited, not extra, brown fat.', false),
  ('newborn', 42, 'A breastfeeding parent is having trouble getting the newborn to open the mouth and turn toward the breast. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "\"Touch her cheek; she''ll turn toward it and open her mouth.\""}, {"id": "b", "text": "\"Stroke the outer sole of her foot so she wakes and starts to feed.\""}, {"id": "c", "text": "\"Make a sudden sound so she startles and opens her mouth.\""}, {"id": "d", "text": "\"Press on her palm so her fingers curl and she starts to suck.\""}]'::jsonb, '["a"]', 'The rooting reflex is elicited by touching the cheek; the newborn turns the head toward the stimulus and opens the mouth. A sudden sound elicits the Moro (startle) reflex, which produces a cry rather than latching.', false),
  ('newborn', 43, 'The nurse receives report on four newborns who are resting quietly. Which newborn should the nurse assess FIRST?', '[{"id": "a", "text": "A 6-hour-old with a heart rate of 150 bpm"}, {"id": "b", "text": "A 12-hour-old with a respiratory rate of 26 breaths/min"}, {"id": "c", "text": "A 1-day-old with 1 wet diaper since birth"}, {"id": "d", "text": "A 2-day-old with green-yellow-brown stools"}]'::jsonb, '["b"]', 'Normal newborn respirations are 30–60 breaths/min, so 26 is below normal and needs assessment first. A heart rate of 150 (110–160), 1 wet diaper on day 1, and transitional stools by days 2–4 are expected.', false),
  ('newborn', 44, 'The nurse teaches the parent of a breastfed newborn about feeding and weight. Which statements by the parent indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"Six feedings in 24 hours is enough for her.\""}, {"id": "b", "text": "\"I''ll breastfeed every 2 to 3 hours.\""}, {"id": "c", "text": "\"I''ll wait to feed until she has gone 4 hours.\""}, {"id": "d", "text": "\"Losing up to 10% of her birth weight is normal.\""}, {"id": "e", "text": "\"She should regain her birth weight within 3 days.\""}]'::jsonb, '["b", "d"]', 'Breastfed newborns feed every 2–3 hours, and losing up to 10% of birth weight in the first few days is normal, so those two are correct. Six feedings is fewer than the 8–12 needed, waiting 4 hours exceeds the q2–3h schedule, and birth weight is regained by 2 weeks, not 3 days.', true),
  ('newborn', 45, 'At a 10-day visit, a parent is worried that the newborn''s umbilical cord stump has not fallen off. The stump is dry, with no redness, odor, or drainage. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"It should have fallen off within a week, so I''ll notify the provider.\""}, {"id": "b", "text": "\"Gently pull it off now so it doesn''t get infected.\""}, {"id": "c", "text": "\"It falls off on its own in 1–2 weeks; keep it dry and clean.\""}, {"id": "d", "text": "\"Start tub baths to help soften and loosen the stump.\""}]'::jsonb, '["c"]', 'The cord falls off naturally in 1–2 weeks, so a dry stump at 10 days is expected; care is to keep it dry and clean. It must not be pulled or removed forcefully.', false),
  ('newborn', 46, 'A 2-day-old breastfed newborn vomits a large amount of green fluid after a feeding. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Reposition the newborn upright and resume feeding"}, {"id": "b", "text": "Document the emesis as normal newborn spitting up"}, {"id": "c", "text": "Switch to formula feedings every 3–4 hours"}, {"id": "d", "text": "Report the bilious vomiting to the provider"}]'::jsonb, '["d"]', 'Green/bilious vomiting suggests obstruction and is a danger sign to report immediately. Resuming feeding or documenting it as normal delays needed evaluation.', false),
  ('newborn', 47, 'The nurse reviews reflex findings documented at several well-baby visits. Which findings require follow-up? Select all that apply.', '[{"id": "a", "text": "Stepping movements present in a 1-month-old"}, {"id": "b", "text": "Moro reflex present in an 8-month-old"}, {"id": "c", "text": "Palmar grasp present in a 4-month-old"}, {"id": "d", "text": "Rooting reflex present in a 9-month-old"}, {"id": "e", "text": "Sucking reflex present in a 2-month-old"}]'::jsonb, '["b", "d"]', 'The Moro and rooting reflexes disappear at about 4 months, so their presence at 8 and 9 months requires follow-up. Stepping lasts until about 2 months, palmar grasp until about 5–6 months, and sucking until about 4 months, so those findings are expected.', true),
  ('newborn', 48, 'The parent of a 6-day-old breastfed newborn calls, worried because the baby has several yellow, seedy, loose stools each day. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"That is the expected stool pattern for a breastfed baby.\""}, {"id": "b", "text": "\"Loose stools mean diarrhea, so bring her in today.\""}, {"id": "c", "text": "\"At this age the stools should still be thick and greenish-black.\""}, {"id": "d", "text": "\"Switch to formula until the stools become formed.\""}]'::jsonb, '["a"]', 'Breastfed stool is yellow, seedy, and loose, with multiple stools per day. Thick, greenish-black stool is meconium, expected within the first 24 hours, not at 6 days.', false),
  ('newborn', 49, 'Right after a vaginal birth, the newborn is placed on the mother''s chest. Which nursing actions help prevent heat loss in this newborn? Select all that apply.', '[{"id": "a", "text": "Dry the newborn"}, {"id": "b", "text": "Skin-to-skin contact"}, {"id": "c", "text": "Knit cap"}, {"id": "d", "text": "Radiant warmer"}, {"id": "e", "text": "Bathe the newborn right away"}]'::jsonb, '["a", "b", "c", "d"]', 'Nursing actions for thermoregulation are drying immediately after birth, skin-to-skin contact, warm blankets, a knit cap, and a radiant warmer — so those four are correct. Bathing right away leaves the skin wet, causing evaporative heat loss.', true),
  ('newborn', 50, 'The parents of a newborn plan to have the baby sleep in their bed so breastfeeding at night will be easier. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Bed-sharing is safe if your mattress is firm.\""}, {"id": "b", "text": "\"Place her on her back in your bed between you.\""}, {"id": "c", "text": "\"Room-share instead: her own bassinet in your room.\""}, {"id": "d", "text": "\"Bed-sharing is fine once she is 6 months old.\""}]'::jsonb, '["c"]', 'The AAP recommendation is to room-share, not bed-share, for the first 6–12 months, with the infant in its own crib or bassinet. A firm mattress or back positioning does not make bed-sharing safe.', false),
  ('respiratory', 1, 'A 4-year-old is brought to the emergency department with a fever that began suddenly this afternoon. The child is sitting upright leaning forward on the hands, is drooling, and speaks in a muffled voice. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Inspect the throat with a tongue blade to assess swelling"}, {"id": "b", "text": "Keep the child calm and notify the provider STAT"}, {"id": "c", "text": "Give cool mist and oral dexamethasone, then reassess"}, {"id": "d", "text": "Begin nebulized racemic epinephrine and observe"}]'::jsonb, '["b"]', 'Sudden high fever, drooling, tripod position, and a muffled voice indicate epiglottitis, an emergency: keep the child calm and notify the provider STAT. Inspecting the throat can trigger complete airway spasm, and cool mist/dexamethasone and racemic epinephrine are croup treatments.', false),
  ('respiratory', 2, 'The emergency department nurse is triaging four children who arrived overnight with breathing difficulty. Which presentation is MOST consistent with laryngotracheobronchitis?', '[{"id": "a", "text": "5-month-old with wheezing, tachypnea, poor feeding, and low-grade fever"}, {"id": "b", "text": "4-year-old with sudden high fever, drooling, and a muffled voice"}, {"id": "c", "text": "18-month-old with a barking cough, hoarse voice, and inspiratory stridor"}, {"id": "d", "text": "9-year-old with expiratory wheezing and chest tightness after exercise"}]'::jsonb, '["c"]', 'Laryngotracheobronchitis (croup) affects ages 6 months to 3 years and causes a barking cough, hoarse voice, and inspiratory stridor. The 5-month-old has bronchiolitis findings, the 4-year-old has epiglottitis findings, and the 9-year-old has asthma findings.', false),
  ('respiratory', 3, 'A 2-year-old is brought to urgent care at 2 a.m. with a barking, seal-like cough, a hoarse voice, and inspiratory stridor that began after 2 days of a runny nose. The child is not drooling. Which prescription is the nurse MOST likely to anticipate?', '[{"id": "a", "text": "Dexamethasone to reduce airway swelling"}, {"id": "b", "text": "Albuterol by metered-dose inhaler and spacer"}, {"id": "c", "text": "IV antibiotics given in the operating room"}, {"id": "d", "text": "Palivizumab (Synagis) injection this month"}]'::jsonb, '["a"]', 'Barking cough, hoarse voice, and inspiratory stridor worse at night point to croup, which is treated with cool mist and dexamethasone (a steroid to reduce swelling). IV antibiotics in the OR are for bacterial epiglottitis, and albuterol is the asthma rescue drug.', false),
  ('respiratory', 4, 'A 5-year-old arrives at triage with a sudden high fever, severe sore throat, drooling, and stridor and is sitting in the tripod position. Which actions should the nurse take at this time? Select all that apply.', '[{"id": "a", "text": "Inspect the throat with a tongue blade and penlight"}, {"id": "b", "text": "Keep the child calm"}, {"id": "c", "text": "Notify the provider STAT"}, {"id": "d", "text": "Give oral dexamethasone and cool mist"}, {"id": "e", "text": "Prepare for intubation"}]'::jsonb, '["b", "c", "e"]', 'These findings indicate epiglottitis. Keeping the child calm (b), notifying the provider STAT (c), and preparing for intubation (e) are the required actions because the swelling can completely obstruct the airway. Inspecting the throat (a) can trigger complete airway spasm. Oral dexamethasone and cool mist (d) are croup treatments and delay airway management.', true),
  ('respiratory', 5, 'A 20-month-old with laryngotracheobronchitis received oral dexamethasone in the emergency department 30 minutes ago. The child now has inspiratory stridor at rest, retractions, and increasing distress despite humidified air. Which prescription should the nurse anticipate NEXT?', '[{"id": "a", "text": "Inhaled fluticasone through a spacer"}, {"id": "b", "text": "IV antibiotics for a bacterial cause"}, {"id": "c", "text": "Chest physiotherapy with vest therapy"}, {"id": "d", "text": "Nebulized racemic epinephrine"}]'::jsonb, '["d"]', 'Croup that has become severe despite humidified air and dexamethasone is treated with nebulized racemic epinephrine. Croup is viral, so antibiotics are not the answer, and fluticasone is a daily asthma controller, not a treatment for acute upper airway swelling.', false),
  ('respiratory', 6, 'A newly hired nurse picks up a tongue blade to look into the throat of a 4-year-old who developed drooling, a severe sore throat, a muffled voice, and stridor over a few hours. The charge nurse stops the nurse. Which rationale BEST supports the charge nurse''s action?', '[{"id": "a", "text": "The swelling is viral and will respond to cool mist"}, {"id": "b", "text": "A throat exam is safe only after racemic epinephrine"}, {"id": "c", "text": "Throat inspection can trigger complete airway spasm"}, {"id": "d", "text": "A throat exam is unnecessary because the cause is RSV"}]'::jsonb, '["c"]', 'This child has epiglottitis; throat inspection can trigger complete airway spasm, so the throat must NOT be examined. Epiglottitis is bacterial (Haemophilus influenzae type b), not viral or RSV, and racemic epinephrine does not make an exam safe.', false),
  ('respiratory', 7, 'A 3-year-old who never received any immunizations is recovering in the ICU after emergency intubation for epiglottitis. The parent asks how to protect the 2-month-old sibling from the same illness. Which response by the nurse is BEST?', '[{"id": "a", "text": "Ask the provider about monthly Synagis (palivizumab) injections for the baby."}, {"id": "b", "text": "Start a daily inhaled corticosteroid as a controller medicine."}, {"id": "c", "text": "Use a cool mist humidifier in the baby''s room every night."}, {"id": "d", "text": "The Hib vaccine has dramatically reduced cases of this illness."}]'::jsonb, '["d"]', 'Epiglottitis is caused by Haemophilus influenzae type b, and the Hib vaccine has dramatically reduced cases. Synagis prevents RSV in high-risk infants, not epiglottitis, and inhaled corticosteroids and cool mist do not prevent a bacterial infection.', false),
  ('respiratory', 8, 'A 7-month-old who attends daycare is admitted with a viral lower airway infection caused by respiratory syncytial virus. Which findings are expected findings for this infant? Select all that apply.', '[{"id": "a", "text": "Tachypnea and retractions"}, {"id": "b", "text": "Barking, seal-like cough"}, {"id": "c", "text": "Greasy, bulky stools"}, {"id": "d", "text": "Poor feeding"}, {"id": "e", "text": "Nasal congestion and low-grade fever"}]'::jsonb, '["a", "d", "e"]', 'Bronchiolitis (RSV) causes tachypnea and retractions (a), poor feeding (d), and nasal congestion with low-grade fever (e), along with wheezing and cough. A barking, seal-like cough (b) is a croup finding, and greasy, bulky stools (c) are a cystic fibrosis finding.', true),
  ('respiratory', 9, 'A 6-month-old is admitted with bronchiolitis caused by RSV. Findings include wheezing, tachypnea, nasal congestion, and a low-grade fever. Which prescription requires follow-up with the health care provider before the nurse carries it out?', '[{"id": "a", "text": "Nasal suctioning before each feeding"}, {"id": "b", "text": "Oral antibiotic every 12 hours"}, {"id": "c", "text": "Oxygen as needed for low saturation"}, {"id": "d", "text": "Elevate the head for upright positioning"}]'::jsonb, '["b"]', 'Treatment of bronchiolitis (RSV) is supportive only, with no antibiotics because the illness is viral, so the antibiotic order should be clarified. Nasal suctioning, O₂, and upright positioning are all part of supportive care.', false),
  ('respiratory', 10, 'A clinic nurse assesses four infants with RSV bronchiolitis during the same afternoon. Which infant should the nurse report to the health care provider FIRST for possible hospitalization?', '[{"id": "a", "text": "SpO₂ 88%, mild wheezing, feeding well"}, {"id": "b", "text": "SpO₂ 93%, low-grade fever, nasal congestion"}, {"id": "c", "text": "SpO₂ 92%, cough, taking full feedings"}, {"id": "d", "text": "SpO₂ 95%, wheezing, wet diapers every 3 hours"}]'::jsonb, '["a"]', 'Infants with bronchiolitis are hospitalized if SpO₂ is <90%, they are dehydrated, or they have respiratory distress; an SpO₂ of 88% meets this criterion even though the infant is feeding well. Saturations of 92% to 95% with adequate feeding and wet diapers do not meet the criteria.', false),
  ('respiratory', 11, 'The nurse teaches the mother of a 2-month-old born prematurely at 30 weeks about palivizumab (Synagis) before RSV season begins. Which statement by the mother indicates understanding of the teaching?', '[{"id": "a", "text": "This medicine will cure RSV if my baby catches it."}, {"id": "b", "text": "My baby will get this antibiotic only if wheezing begins this winter."}, {"id": "c", "text": "My baby will get these injections monthly to help prevent RSV."}, {"id": "d", "text": "One injection now will protect my baby for life."}]'::jsonb, '["c"]', 'Synagis (palivizumab) is given as monthly injections to prevent RSV in high-risk infants such as premature infants. It is prevention, not a cure or an antibiotic, and it is not a single lifelong dose.', false),
  ('respiratory', 12, 'At 2 a.m., the parent of a 2-year-old diagnosed with croup yesterday calls the nurse line. The child woke with a louder barking cough and a hoarse voice but is not drooling. The parent says, ''He was fine all day, so he must be getting much worse.'' Which response is BEST?', '[{"id": "a", "text": "Croup is typically worse at night; use humidified air and keep him calm."}, {"id": "b", "text": "Croup is typically worse in the morning; give his albuterol inhaler now."}, {"id": "c", "text": "Night symptoms suggest asthma; give the steroid inhaler before he sleeps."}, {"id": "d", "text": "Night symptoms suggest a bacterial cause; start leftover antibiotics now."}]'::jsonb, '["a"]', 'Croup symptoms are worse at night, and treatment includes cool mist or humidified air and keeping the child calm. Croup is viral (parainfluenza most common), so antibiotics are not indicated, and asthma inhalers are not croup treatments.', false),
  ('respiratory', 13, 'A 9-year-old with asthma comes to the school nurse after outdoor recess on a cold morning with expiratory wheezing, chest tightness, and a prolonged expiratory phase. The child''s labeled fluticasone and albuterol inhalers are in the office. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Give the fluticasone inhaler, then have the child rinse the mouth"}, {"id": "b", "text": "Give the albuterol inhaler using a spacer"}, {"id": "c", "text": "Give a montelukast tablet with a glass of water"}, {"id": "d", "text": "Call the parent to pick up the child for an office visit"}]'::jsonb, '["b"]', 'This is an acute asthma episode triggered by cold air and exercise; albuterol is the rescue SABA that bronchodilates within minutes, given with a spacer. Fluticasone is a controller steroid inhaler and is not for acute attacks, and montelukast is a daily controller.', false),
  ('respiratory', 14, 'At a 2-month follow-up visit, a 7-year-old who uses inhaled fluticasone daily has white patches on the tongue and inner cheeks. The child''s asthma symptoms are well controlled. Which question by the nurse is MOST important?', '[{"id": "a", "text": "Is anyone in the home smoking tobacco around your child?"}, {"id": "b", "text": "How often has your child needed albuterol this month?"}, {"id": "c", "text": "Does your child take montelukast at the same time each day?"}, {"id": "d", "text": "Does your child rinse the mouth after using fluticasone?"}]'::jsonb, '["d"]', 'White patches in a child using an inhaled corticosteroid suggest oral candidiasis (thrush), which is prevented by rinsing the mouth after each dose. Tobacco smoke is an asthma trigger and albuterol use reflects control, but neither explains the oral patches.', false),
  ('respiratory', 15, 'The nurse is reviewing the history of a 10-year-old with asthma who has had three episodes this month. Which situations should the nurse identify as likely triggers? Select all that apply.', '[{"id": "a", "text": "Taking the daily fluticasone dose each morning"}, {"id": "b", "text": "Exposure to tobacco smoke in the family car"}, {"id": "c", "text": "Exercise outdoors in cold air during soccer"}, {"id": "d", "text": "A viral infection the week before"}, {"id": "e", "text": "Using a spacer with the albuterol inhaler"}]'::jsonb, '["b", "c", "d"]', 'Asthma triggers include allergens, cold air, exercise, tobacco smoke, and viral infections, so tobacco smoke (b), exercise in cold air (c), and a recent viral infection (d) are likely triggers. The daily fluticasone dose (a) is a controller that reduces chronic inflammation, and using a spacer (e) is the recommended way to take a metered-dose inhaler; neither is a trigger.', true),
  ('respiratory', 16, 'The nurse teaches the parent of a 6-year-old who is newly prescribed inhaled fluticasone and albuterol. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "I''ll give the fluticasone during an attack to open the airways fast."}, {"id": "b", "text": "Albuterol is the rescue inhaler my child uses for an acute episode."}, {"id": "c", "text": "My child will use a spacer every time with the metered-dose inhaler."}, {"id": "d", "text": "My child will rinse the mouth after each dose of the steroid inhaler."}]'::jsonb, '["a"]', 'Fluticasone is an inhaled corticosteroid controller taken daily to reduce chronic inflammation; the steroid inhaler is not for acute attacks. Albuterol as rescue, using a spacer, and rinsing the mouth after the steroid inhaler are all correct.', false),
  ('respiratory', 17, 'The parent of an 8-year-old with asthma calls and says, ''He started wheezing an hour ago, so I gave his montelukast tablet early and we are waiting for it to work.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Give a second montelukast tablet if he is still wheezing."}, {"id": "b", "text": "Montelukast is a rescue drug, so it should work in minutes."}, {"id": "c", "text": "Montelukast is a daily controller; use albuterol for an acute episode."}, {"id": "d", "text": "Give his fluticasone inhaler now because it works faster than the tablet."}]'::jsonb, '["c"]', 'Montelukast (Singulair) is a leukotriene receptor antagonist controller taken daily; albuterol is the rescue drug for an acute episode, with bronchodilation in minutes. Fluticasone is also a controller and is not for acute attacks.', false),
  ('respiratory', 18, 'A 7-year-old is evaluated for a 3-month history of breathing problems that keep waking the child at night. Which findings would support a diagnosis of asthma? Select all that apply.', '[{"id": "a", "text": "Persistent cough at night and with exercise"}, {"id": "b", "text": "Wheezing heard on expiration"}, {"id": "c", "text": "Inspiratory stridor with a hoarse voice"}, {"id": "d", "text": "Prolonged expiratory phase"}, {"id": "e", "text": "Chest tightness"}]'::jsonb, '["a", "b", "d", "e"]', 'Asthma signs include persistent cough especially at night or with exercise (a), expiratory wheezing (b), a prolonged expiratory phase (d), and chest tightness (e). Inspiratory stridor with a hoarse voice (c) is an upper airway (croup) finding.', true),
  ('respiratory', 19, 'While assessing a 3-year-old with a barking cough, the nurse hears a high-pitched sound that occurs mainly during inspiration. Which interpretation of this finding is MOST accurate?', '[{"id": "a", "text": "Lower airway narrowing, as seen in asthma"}, {"id": "b", "text": "Lower airway infection, as seen in bronchiolitis"}, {"id": "c", "text": "Thick, sticky mucus, as seen in cystic fibrosis"}, {"id": "d", "text": "Upper airway stridor, as seen in croup"}]'::jsonb, '["d"]', 'Stridor is an inspiratory upper airway sound found in croup and epiglottitis. Lower airway disorders (bronchiolitis, asthma, CF) produce expiratory wheezing instead.', false),
  ('respiratory', 20, 'The parent of an 18-month-old with croup asks why the child developed noisy breathing and retractions when the provider described the airway swelling as ''mild.'' Which explanation by the nurse is BEST?', '[{"id": "a", "text": "Toddlers have longer tracheas, so the swelling extends much farther down."}, {"id": "b", "text": "Smaller airway diameter: even small swelling causes significant obstruction."}, {"id": "c", "text": "Toddlers have smaller tongues that easily fall back and block the airway."}, {"id": "d", "text": "A toddler''s respiratory muscles tire more slowly, so distress shows up later."}]'::jsonb, '["b"]', 'Children have a smaller airway diameter, so even small swelling causes significant obstruction. Children actually have shorter tracheas, larger tongues relative to the airway, and respiratory muscles that tire faster.', false),
  ('respiratory', 21, 'A 3-month-old with RSV bronchiolitis has thick nasal secretions and tachypnea and is taking only small amounts of formula at each feeding. Which nursing action is the PRIORITY before each feeding?', '[{"id": "a", "text": "Give albuterol by metered-dose inhaler with a spacer"}, {"id": "b", "text": "Perform chest physiotherapy with a vest device"}, {"id": "c", "text": "Perform nasal suctioning to clear the nose"}, {"id": "d", "text": "Place the infant in a cool mist tent during feeds"}]'::jsonb, '["c"]', 'Infants are obligate nose breathers, so nasal congestion interferes with feeding; nasal suctioning is part of supportive bronchiolitis care. Chest physiotherapy and vest therapy are CF airway clearance methods, and cool mist is a croup treatment.', false),
  ('respiratory', 22, 'A 5-month-old with RSV bronchiolitis has an SpO₂ of 88% on room air and retractions and has refused most feedings for 24 hours. Which interventions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Nasal suctioning"}, {"id": "b", "text": "O₂ therapy"}, {"id": "c", "text": "Antibiotics for the infection"}, {"id": "d", "text": "IV fluids"}, {"id": "e", "text": "Upright positioning"}]'::jsonb, '["a", "b", "d", "e"]', 'Supportive bronchiolitis care includes nasal suctioning (a), O₂ for this low saturation (b), IV fluids because the infant is unable to feed (d), and upright positioning (e). Antibiotics (c) are not used because RSV is viral.', true),
  ('respiratory', 23, 'A 9-month-old has had three lung infections since birth, has dropped from the 50th to the 5th percentile for weight, and has frequent greasy, bulky stools. Which laboratory result would be an expected finding for the suspected disorder?', '[{"id": "a", "text": "Sweat chloride test of 72 mEq/L"}, {"id": "b", "text": "Sweat chloride test of 52 mEq/L"}, {"id": "c", "text": "Nasal swab positive for RSV"}, {"id": "d", "text": "Nasal swab positive for parainfluenza"}]'::jsonb, '["a"]', 'Recurrent lung infections, failure to thrive, and steatorrhea suggest cystic fibrosis, confirmed by a positive sweat chloride test >60 mEq/L; 72 mEq/L is positive, while 52 mEq/L is below that threshold. RSV and parainfluenza cause bronchiolitis and croup.', false),
  ('respiratory', 24, 'A 4-year-old with cystic fibrosis eats breakfast, lunch, and dinner and also has a midmorning and an afternoon snack each day. Based on this schedule, which pancreatic enzyme plan is MOST appropriate?', '[{"id": "a", "text": "1 dose, with breakfast"}, {"id": "b", "text": "2 doses, morning and bedtime, with water"}, {"id": "c", "text": "3 doses, with the three meals"}, {"id": "d", "text": "5 doses, with every meal and snack"}]'::jsonb, '["d"]', 'Pancreatic enzyme replacement is given with every meal and snack, so 3 meals plus 2 snacks equals 5 doses. Giving enzymes only with the three meals misses the snacks.', false),
  ('respiratory', 25, 'A 7-year-old with cystic fibrosis has poor weight gain. The dietitian estimates the child''s normal daily intake for age at 1,600 kcal. Which daily calorie goal is MOST appropriate for the nurse to reinforce?', '[{"id": "a", "text": "1,400 kcal with a low-fat diet to reduce greasy stools"}, {"id": "b", "text": "2,200 kcal with a high-calorie, high-protein diet"}, {"id": "c", "text": "1,600 kcal with a high-calorie, high-protein diet"}, {"id": "d", "text": "3,000 kcal with a low-protein, high-fat diet"}]'::jsonb, '["b"]', 'Children with CF need a high-calorie, high-protein diet of up to 120–150% of normal daily intake; 120–150% of 1,600 kcal is 1,920–2,400 kcal, so 2,200 kcal fits. 1,600 kcal is only 100% of normal, 1,400 kcal is below normal, and 3,000 kcal (about 188%) is low in protein.', false),
  ('respiratory', 26, 'A 12-year-old with cystic fibrosis is admitted with an increased chronic productive cough and thick sputum, and the sputum culture grows Pseudomonas. Which treatments should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Antibiotics"}, {"id": "b", "text": "Monthly Synagis (palivizumab) injections"}, {"id": "c", "text": "Inhaled DNase (dornase alfa)"}, {"id": "d", "text": "Chest physiotherapy (CPT) or vest therapy"}, {"id": "e", "text": "Bronchodilators"}]'::jsonb, '["a", "c", "d", "e"]', 'Recurrent lung infections (Pseudomonas common) in CF are managed with antibiotics (a), inhaled DNase (dornase alfa) (c), airway clearance with CPT or vest therapy (d), and bronchodilators (e). Monthly Synagis (b) is RSV prevention for high-risk infants, not CF treatment.', true),
  ('respiratory', 27, 'The parents of a 6-month-old newly diagnosed with cystic fibrosis tell the nurse, ''Neither of us has this disease, so we don''t understand how our baby got it.'' Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "It develops after early Pseudomonas lung infections."}, {"id": "b", "text": "It is caused by exposure to tobacco smoke in infancy."}, {"id": "c", "text": "It is an autosomal recessive genetic disorder."}, {"id": "d", "text": "It is a viral illness most often caused by RSV."}]'::jsonb, '["c"]', 'CF is an autosomal recessive genetic disorder causing a defective CFTR protein, so parents without the disease can have an affected child. Pseudomonas infections are a consequence of CF, not its cause.', false),
  ('respiratory', 28, 'The nurse receives handoff report at 7 p.m. on four children on the pediatric unit. Which child should the nurse assess FIRST?', '[{"id": "a", "text": "4-year-old with sudden high fever, drooling, and tripod position"}, {"id": "b", "text": "2-year-old with croup whose barking cough is worse tonight"}, {"id": "c", "text": "10-year-old with cystic fibrosis who has greasy, bulky stools"}, {"id": "d", "text": "6-month-old with RSV who has nasal congestion and low-grade fever"}]'::jsonb, '["a"]', 'Sudden high fever, drooling, and tripod position indicate epiglottitis, an emergency that can completely obstruct the airway within hours. A croup cough worse at night, steatorrhea in CF, and congestion with low-grade fever in RSV are expected findings.', false),
  ('respiratory', 29, 'A 10-year-old arrives in the emergency department with a severe asthma episode: loud expiratory wheezing, chest tightness, and a prolonged expiratory phase that did not improve with home treatment. Which treatment combination should the nurse anticipate FIRST?', '[{"id": "a", "text": "Montelukast and inhaled fluticasone"}, {"id": "b", "text": "Racemic epinephrine and cool mist"}, {"id": "c", "text": "IV antibiotics and inhaled DNase"}, {"id": "d", "text": "Albuterol and steroids"}]'::jsonb, '["d"]', 'The emergency treatment for severe asthma is albuterol plus steroids. Montelukast and inhaled fluticasone are daily controllers, racemic epinephrine and cool mist treat croup, and DNase is a CF therapy.', false),
  ('respiratory', 30, 'The parent of a 6-year-old whose wheezing resolved within minutes of albuterol asks, ''Does this mean my child''s lungs are permanently damaged?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Thick, sticky mucus from a defective CFTR protein is blocking the airways."}, {"id": "b", "text": "Asthma involves reversible bronchoconstriction with chronic inflammation."}, {"id": "c", "text": "A virus is causing temporary swelling of the larynx and the trachea now."}, {"id": "d", "text": "A bacterial infection is causing swelling of the epiglottis."}]'::jsonb, '["b"]', 'Asthma is a chronic inflammatory airway disease with reversible bronchoconstriction, which is why albuterol relieved the wheezing within minutes. A defective CFTR protein describes cystic fibrosis, and larynx/trachea swelling describes croup.', false),
  ('respiratory', 31, 'A 6-month-old is evaluated for failure to thrive, and the parent reports frequent coughing. Which additional findings would MOST strongly suggest cystic fibrosis? Select all that apply.', '[{"id": "a", "text": "Hoarse voice that is worse at night"}, {"id": "b", "text": "Salty skin when the infant is kissed"}, {"id": "c", "text": "Sudden high fever with drooling"}, {"id": "d", "text": "Greasy, bulky stools"}, {"id": "e", "text": "Nasal congestion with low-grade fever"}]'::jsonb, '["b", "d"]', 'CF signs include salty skin (b) and greasy, bulky stools (steatorrhea) (d), along with poor weight gain and chronic productive cough. A hoarse voice worse at night (a) suggests croup, sudden high fever with drooling (c) suggests epiglottitis, and nasal congestion with low-grade fever (e) suggests bronchiolitis.', true),
  ('respiratory', 32, 'The nurse observes a student nurse assisting a 6-year-old who is wheezing after recess. Which action by the student nurse requires follow-up by the nurse?', '[{"id": "a", "text": "Choosing the albuterol inhaler for the acute wheezing"}, {"id": "b", "text": "Telling the child albuterol works within minutes"}, {"id": "c", "text": "Giving the albuterol metered-dose inhaler without a spacer"}, {"id": "d", "text": "Planning to have the child rinse after any steroid inhaler dose"}]'::jsonb, '["c"]', 'Children should always use a spacer with metered-dose inhalers, so this action needs correction. Albuterol is the correct rescue drug for acute wheezing, it bronchodilates in minutes, and rinsing after steroid inhalers prevents thrush.', false),
  ('respiratory', 33, 'The nurse provides discharge teaching to the parent of a 2-year-old treated in the emergency department with dexamethasone for croup. Which statement by the parent indicates understanding of the teaching?', '[{"id": "a", "text": "I''ll use cool mist or humidified air and keep my child calm."}, {"id": "b", "text": "I''ll give antibiotics until the barking cough goes away."}, {"id": "c", "text": "The cough should be worse in the morning and better at night."}, {"id": "d", "text": "I''ll use the albuterol rescue inhaler for the barking cough."}]'::jsonb, '["a"]', 'Croup care includes cool mist or humidified air and keeping the child calm. Croup is viral, its symptoms are worse at night (not in the morning), and albuterol is an asthma rescue drug.', false),
  ('respiratory', 34, 'A 6-year-old with suspected epiglottitis is quiet and sitting upright on the parent''s lap in the emergency department. The parent asks whether the child can rest for a few hours before transfer to the ICU. Which response by the nurse is BEST?', '[{"id": "a", "text": "Resting is fine; this is a mild viral illness that improves with time."}, {"id": "b", "text": "The swelling can completely obstruct the airway within hours."}, {"id": "c", "text": "Resting is fine once a cool mist humidifier is set up at the bedside."}, {"id": "d", "text": "We will look at the throat after your child wakes up to decide."}]'::jsonb, '["b"]', 'Epiglottitis causes rapid, severe swelling that can completely obstruct the airway within hours, so transfer for IV antibiotics in a controlled setting cannot wait. It is bacterial, not viral, and the throat must not be examined.', false),
  ('respiratory', 35, 'A 2-year-old with a barking cough now has inspiratory stridor at rest and severe distress in the emergency department. Which interventions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Albuterol by metered-dose inhaler with a spacer"}, {"id": "b", "text": "Cool mist or humidified air"}, {"id": "c", "text": "Dexamethasone"}, {"id": "d", "text": "Nebulized racemic epinephrine"}, {"id": "e", "text": "Keep the child calm"}]'::jsonb, '["b", "c", "d", "e"]', 'Severe croup is treated with cool mist or humidified air (b), dexamethasone to reduce swelling (c), nebulized racemic epinephrine for severe cases (d), and keeping the child calm (e). Albuterol (a) is the asthma rescue drug for lower airway wheezing, not croup.', true),
  ('respiratory', 36, 'A 2-month-old with RSV bronchiolitis has taken only a few sips of formula in 12 hours, has had one wet diaper today, and has an SpO₂ of 93%. Which prescription should the nurse anticipate NEXT?', '[{"id": "a", "text": "An oral antibiotic to treat the lower airway infection"}, {"id": "b", "text": "Palivizumab (Synagis) to treat the RSV"}, {"id": "c", "text": "Oral dexamethasone to reduce swelling"}, {"id": "d", "text": "IV fluids because the infant is unable to feed"}]'::jsonb, '["d"]', 'Bronchiolitis care is supportive, including IV fluids if the infant is unable to feed; this infant is barely feeding. Antibiotics are not used because RSV is viral, and Synagis is monthly prevention for high-risk infants, not treatment.', false),
  ('respiratory', 37, 'A 3-year-old is brought to the emergency department with stridor. Which additional findings would MOST strongly suggest epiglottitis rather than croup? Select all that apply.', '[{"id": "a", "text": "Drooling"}, {"id": "b", "text": "Barking, seal-like cough"}, {"id": "c", "text": "Tripod position, leaning forward on the hands"}, {"id": "d", "text": "Hoarse voice and symptoms worse at night"}, {"id": "e", "text": "Muffled \"hot potato\" voice"}]'::jsonb, '["a", "c", "e"]', 'Epiglottitis signs include drooling (a), the tripod position (c), and a muffled "hot potato" voice (e), with sudden high fever and severe sore throat. A barking, seal-like cough (b) and a hoarse voice worse at night (d) are croup findings.', true),
  ('respiratory', 38, 'A nursing student caring for a 1-year-old with bronchiolitis asks why young children develop respiratory distress so quickly. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "Their airway diameter is smaller, so small swelling obstructs it."}, {"id": "b", "text": "Their tracheas are longer than an adult''s."}, {"id": "c", "text": "Their tongues are larger relative to the airway."}, {"id": "d", "text": "Their respiratory muscles tire faster."}, {"id": "e", "text": "Infants are obligate mouth breathers."}]'::jsonb, '["a", "c", "d"]', 'Children have a smaller airway diameter, so even small swelling causes significant obstruction (a); larger tongues relative to the airway (c); and respiratory muscles that tire faster (d). Children have shorter, not longer, tracheas (b), and infants are obligate nose breathers, not mouth breathers (e).', true),
  ('respiratory', 39, 'A 4-month-old with RSV bronchiolitis had a respiratory rate of 72 with retractions on admission. Four hours later the rate is 30, retractions are less visible, the infant is less active, and the SpO₂ is 86%. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The infant is improving and can resume oral feedings"}, {"id": "b", "text": "The infant''s respiratory muscles may be tiring"}, {"id": "c", "text": "The infant now has upper airway stridor from croup"}, {"id": "d", "text": "The infant needs a dose of antibiotics for bacteria"}]'::jsonb, '["b"]', 'Children''s respiratory muscles tire faster; a slowing rate with falling SpO₂ (86%, below the <90% hospitalization threshold) signals fatigue, not improvement. Antibiotics are not used for viral RSV bronchiolitis.', false),
  ('respiratory', 40, 'The provider suspects epiglottitis in a 4-year-old who is drooling, has a muffled voice, and is sitting in the tripod position. Which plan of care should the nurse anticipate as MOST appropriate?', '[{"id": "a", "text": "Obtain a throat culture in triage, then start oral antibiotics"}, {"id": "b", "text": "Give oral dexamethasone and observe in the waiting area"}, {"id": "c", "text": "Give IV antibiotics in a controlled setting such as the OR/ICU"}, {"id": "d", "text": "Begin cool mist therapy at home and recheck tomorrow"}]'::jsonb, '["c"]', 'For epiglottitis, IV antibiotics are given immediately in a controlled setting (OR/ICU) while preparing for intubation. A throat culture requires throat inspection, which can trigger complete airway spasm, and dexamethasone or cool mist are croup treatments.', false),
  ('respiratory', 41, 'During RSV season, the nurse reviews the records of five infants at a clinic visit. Which infants should the nurse identify as candidates for monthly palivizumab (Synagis)? Select all that apply.', '[{"id": "a", "text": "Full-term 3-month-old with no health problems"}, {"id": "b", "text": "Premature infant, now 2 months old"}, {"id": "c", "text": "Full-term 6-month-old who attends daycare"}, {"id": "d", "text": "4-month-old with heart disease"}, {"id": "e", "text": "Full-term 18-month-old recovering from croup"}]'::jsonb, '["b", "d"]', 'Synagis monthly injections are for high-risk infants: premature infants (b) and those with heart or lung disease (d). A healthy full-term infant (a), a full-term infant in daycare (c), and a toddler recovering from croup (e) do not meet the high-risk criteria.', true),
  ('respiratory', 42, 'A 9-year-old started daily inhaled fluticasone 2 months ago. The child previously coughed most nights and used albuterol 4 days a week; now the child sleeps through the night and used albuterol once this month. Which evaluation by the nurse is MOST accurate?', '[{"id": "a", "text": "The controller is reducing chronic airway inflammation."}, {"id": "b", "text": "Fluticasone can now be saved for acute asthma attacks."}, {"id": "c", "text": "Albuterol should now be taken daily as a controller."}, {"id": "d", "text": "The spacer is no longer needed with metered-dose inhalers."}]'::jsonb, '["a"]', 'Inhaled corticosteroids (fluticasone) are daily controllers that reduce chronic inflammation; fewer night coughs and less rescue albuterol show the controller is working. The steroid inhaler is not for acute attacks, and albuterol is the rescue drug, not a controller.', false),
  ('respiratory', 43, 'After teaching, a 10-year-old with asthma describes the home medication plan to the nurse. Which statements by the child indicate understanding? Select all that apply.', '[{"id": "a", "text": "I use my fluticasone inhaler when I start wheezing."}, {"id": "b", "text": "I can stop montelukast on days I feel fine."}, {"id": "c", "text": "I use albuterol when I have an acute episode."}, {"id": "d", "text": "I take montelukast every day, even when I feel fine."}, {"id": "e", "text": "I rinse my mouth after my fluticasone inhaler."}]'::jsonb, '["c", "d", "e"]', 'Albuterol is the rescue drug for an acute episode (c), montelukast is a daily controller (d), and rinsing the mouth after inhaled corticosteroids prevents thrush (e). Fluticasone is a controller, not for acute wheezing (a), and montelukast is taken daily, not stopped on good days (b).', true),
  ('respiratory', 44, 'The mother of a 3-month-old says, ''My baby tastes salty when I kiss him, he coughs a lot, and he isn''t gaining weight.'' Which diagnostic test should the nurse anticipate the provider will order FIRST?', '[{"id": "a", "text": "Nasal swab for RSV"}, {"id": "b", "text": "Throat culture for Haemophilus influenzae type b"}, {"id": "c", "text": "Sweat chloride test"}, {"id": "d", "text": "Nasal swab for parainfluenza"}]'::jsonb, '["c"]', 'Salty skin, chronic cough, and poor weight gain suggest cystic fibrosis, which is identified by a positive sweat chloride test (>60 mEq/L). RSV and parainfluenza swabs evaluate bronchiolitis and croup, and Hib causes epiglottitis.', false),
  ('respiratory', 45, 'A 9-month-old is evaluated at an urgent care clinic for bronchiolitis caused by RSV. Which findings indicate a need for hospitalization? Select all that apply.', '[{"id": "a", "text": "SpO₂ of 89% on room air"}, {"id": "b", "text": "SpO₂ of 92% on room air"}, {"id": "c", "text": "Signs that the infant is dehydrated"}, {"id": "d", "text": "Nasal congestion with low-grade fever"}, {"id": "e", "text": "Respiratory distress"}]'::jsonb, '["a", "c", "e"]', 'Infants with bronchiolitis are hospitalized if SpO₂ is <90% (a), they are dehydrated (c), or they have respiratory distress (e). An SpO₂ of 92% (b) is above the threshold, and nasal congestion with low-grade fever (d) are expected bronchiolitis signs.', true),
  ('respiratory', 46, 'The parent of a 14-month-old with a barking, seal-like cough and inspiratory stridor asks what caused the illness and whether the child''s missed Hib vaccine is to blame. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "It is bacterial, caused by Haemophilus influenzae type b."}, {"id": "b", "text": "It is a lower airway infection most often caused by RSV."}, {"id": "c", "text": "It results from a defective CFTR protein causing thick mucus."}, {"id": "d", "text": "It is viral, and parainfluenza is the most common cause."}]'::jsonb, '["d"]', 'This is croup, an upper airway illness that is viral, with parainfluenza most common. Haemophilus influenzae type b causes epiglottitis, and RSV causes bronchiolitis, a lower airway infection.', false),
  ('respiratory', 47, 'A 5-year-old with suspected epiglottitis is awaiting transfer to the OR. The child is sitting forward, drooling, and has inspiratory stridor. Which item is MOST important for the nurse to have IMMEDIATELY available at the bedside?', '[{"id": "a", "text": "Intubation equipment"}, {"id": "b", "text": "Tongue blade and penlight"}, {"id": "c", "text": "Cool mist tent"}, {"id": "d", "text": "Vest therapy device"}]'::jsonb, '["a"]', 'Epiglottitis can completely obstruct the airway, so the nurse prepares for intubation. A tongue blade and penlight must not be used because throat inspection can trigger complete airway spasm; cool mist is for croup and vest therapy for CF.', false),
  ('respiratory', 48, 'The nurse is caring for five children on a pediatric unit. Which children would the nurse expect to have expiratory wheezing as a lower airway finding? Select all that apply.', '[{"id": "a", "text": "5-month-old with RSV bronchiolitis"}, {"id": "b", "text": "8-year-old during an asthma episode"}, {"id": "c", "text": "11-year-old with cystic fibrosis"}, {"id": "d", "text": "2-year-old with croup and a barking cough"}, {"id": "e", "text": "4-year-old with epiglottitis and drooling"}]'::jsonb, '["a", "b", "c"]', 'Lower airway disorders, which produce expiratory wheezing, are bronchiolitis (a), asthma (b), and CF (c). Croup (d) and epiglottitis (e) are upper airway disorders that produce inspiratory stridor.', true),
  ('respiratory', 49, 'An 8-month-old has tachypnea, retractions, and wheezing heard on expiration after 3 days of nasal congestion. The parent asks, ''Is this croup like my older child had?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes, wheezing is the classic sound of croup in infants."}, {"id": "b", "text": "No, wheezing points to a lower airway illness such as bronchiolitis."}, {"id": "c", "text": "Yes, croup and bronchiolitis both cause inspiratory stridor."}, {"id": "d", "text": "No, wheezing points to epiglottitis, an upper airway illness."}]'::jsonb, '["b"]', 'Expiratory wheezing is a lower airway sound seen in bronchiolitis, asthma, and CF. Croup and epiglottitis are upper airway disorders that cause inspiratory stridor, not wheezing.', false),
  ('respiratory', 50, 'The nurse reviews home care with the parents of a 3-year-old with cystic fibrosis. Which statements by the parents indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "We skip the enzymes with snacks because snacks are small."}, {"id": "b", "text": "We give vitamins A, D, E, and K every day."}, {"id": "c", "text": "We use the flutter valve or vest therapy for airway clearance."}, {"id": "d", "text": "We limit fat and calories so the stools are less greasy."}, {"id": "e", "text": "We aim for a high-calorie, high-protein diet."}]'::jsonb, '["a", "d"]', 'Pancreatic enzymes must be given with every meal and snack, so skipping snack doses (a) needs correction, and children with CF need a high-calorie, high-protein diet, so limiting fat and calories (d) is incorrect. Fat-soluble vitamins A, D, E, K (b), flutter valve or vest therapy (c), and a high-calorie, high-protein diet (e) are all correct.', true),
  ('cardio', 1, 'A 5-month-old with heart failure is due for a scheduled dose of digoxin. The nurse counts an apical pulse of 88 bpm for 1 full minute. The infant is feeding and has no vomiting. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Give digoxin; HR is above the 70 bpm cut-off"}, {"id": "b", "text": "Give half the digoxin dose and recheck in an hour"}, {"id": "c", "text": "Hold digoxin; HR is <90 bpm in infants"}, {"id": "d", "text": "Give digoxin; the infant shows no vomiting"}]'::jsonb, '["c"]', 'Digoxin is held if the heart rate is <90 bpm in infants, so an apical rate of 88 bpm requires holding the dose. The <70 bpm cut-off applies to children, not infants, and the absence of GI toxicity signs does not override the heart rate check.', false),
  ('cardio', 2, 'A 4-year-old with heart failure is due for digoxin. The nurse counts an apical pulse of 74 bpm for 1 full minute. The child is alert, eating well, and denies nausea or blurred vision. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Give digoxin; HR is not <70 bpm in children"}, {"id": "b", "text": "Hold digoxin; HR is <90 bpm in infants"}, {"id": "c", "text": "Hold digoxin; HR is under the normal 100 bpm"}, {"id": "d", "text": "Recheck the HR in 4 hours before any dose"}]'::jsonb, '["a"]', 'For children, digoxin is held if the heart rate is <70 bpm; 74 bpm is above that cut-off and the child has no toxicity signs, so the dose is given. The <90 bpm cut-off applies to infants, and 100 bpm is the low end of the normal infant heart rate.', false),
  ('cardio', 3, 'The nurse is teaching the parents of a 3-year-old who will take digoxin and captopril at home for heart failure. Which findings should the parents report because they may indicate digoxin toxicity? Select all that apply.', '[{"id": "a", "text": "Persistent dry cough"}, {"id": "b", "text": "Vomiting and loss of appetite"}, {"id": "c", "text": "Yellow/green vision or halos"}, {"id": "d", "text": "Clubbing of fingers/toes"}, {"id": "e", "text": "Slow or irregular pulse"}]'::jsonb, '["b", "c", "e"]', 'Digoxin toxicity includes vomiting and loss of appetite (b), yellow/green vision or halos (c), and a slow, fast, or irregular pulse (e). A persistent dry cough (a) is an effect of captopril, and clubbing (d) is a sign of tetralogy of Fallot from chronic hypoxia.', true),
  ('cardio', 4, 'A new graduate nurse prepares to give digoxin to an 8-month-old and places a pulse oximeter on the infant''s toe to read the heart rate. Which action by the preceptor is BEST?', '[{"id": "a", "text": "Have the nurse count a radial pulse for 15 seconds"}, {"id": "b", "text": "Check an apical pulse for 1 full minute"}, {"id": "c", "text": "Allow the dose if the oximeter rate is above 70 bpm"}, {"id": "d", "text": "Allow the dose if the oximeter reading is ≥95%"}]'::jsonb, '["b"]', 'Before giving digoxin, the nurse checks the apical pulse for 1 full minute and holds the dose if it is <90 bpm in infants. The 70 bpm cut-off is for children, and SpO₂ does not determine whether digoxin is given.', false),
  ('cardio', 5, 'A 10-month-old with tetralogy of Fallot begins crying hard during a diaper change after a bowel movement. The infant suddenly becomes deeply blue and breathes rapidly. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Prepare to give the prescribed IV propranolol"}, {"id": "b", "text": "Lay the infant flat and elevate the head"}, {"id": "c", "text": "Obtain a full set of vital signs and an SpO₂"}, {"id": "d", "text": "Place the infant in knee-to-chest position"}]'::jsonb, '["d"]', 'This is a tet spell (hypercyanotic episode) triggered by crying and defecation; the first action is knee-to-chest position, which increases SVR and forces blood through the pulmonary circulation. O₂, morphine, and IV propranolol follow, and assessment should not delay positioning.', false),
  ('cardio', 6, 'The nurse is teaching the parents of a 6-month-old with tetralogy of Fallot about hypercyanotic (tet) spells. Which events should the nurse identify as possible triggers? Select all that apply.', '[{"id": "a", "text": "Crying"}, {"id": "b", "text": "Knee-to-chest position"}, {"id": "c", "text": "Feeding"}, {"id": "d", "text": "Defecation"}, {"id": "e", "text": "Calming the child"}]'::jsonb, '["a", "c", "d"]', 'Tet spells are triggered by crying (a), feeding (c), and defecation (d). Knee-to-chest position (b) and calming the child (e) are actions used to treat a tet spell, not triggers.', true),
  ('cardio', 7, 'A 2-year-old with unrepaired tetralogy of Fallot has clubbing of the fingers and toes. The nurse reviews the complete blood count. Which result would the nurse interpret as an expected finding for this child?', '[{"id": "a", "text": "High RBC count from chronic hypoxia"}, {"id": "b", "text": "Low RBC count from the chronic hypoxia"}, {"id": "c", "text": "Low platelet count from the shunt"}, {"id": "d", "text": "High platelet count from the shunt"}]'::jsonb, '["a"]', 'Children with tetralogy of Fallot develop polycythemia, a high RBC count from chronic hypoxia, along with cyanosis and clubbing. A low RBC count is the opposite of the expected finding, and platelet changes are not described for this defect.', false),
  ('cardio', 8, 'A premature infant in the NICU has a continuous "machine-like" murmur. The infant''s oxygen saturation is normal. Which medication should the nurse MOST likely anticipate to treat this infant''s condition?', '[{"id": "a", "text": "IV propranolol"}, {"id": "b", "text": "Morphine"}, {"id": "c", "text": "Indomethacin"}, {"id": "d", "text": "Furosemide"}]'::jsonb, '["c"]', 'A continuous machine-like murmur in a premature infant indicates PDA, which is treated with indomethacin to close the PDA or with surgical ligation. Morphine and IV propranolol are used for tet spells in TOF.', false),
  ('cardio', 9, 'A 3-month-old is being evaluated for poor feeding. Which findings would the nurse interpret as signs of heart failure that should be reported to the health care provider? Select all that apply.', '[{"id": "a", "text": "Tachycardia at rest"}, {"id": "b", "text": "Diaphoresis during feeding"}, {"id": "c", "text": "Polycythemia on the blood count"}, {"id": "d", "text": "Hepatomegaly"}, {"id": "e", "text": "Periorbital edema"}]'::jsonb, '["a", "b", "d", "e"]', 'Heart failure in infants presents with compensatory tachycardia (a), diaphoresis especially during feeding (b), hepatomegaly (d), and periorbital or peripheral edema (e). Polycythemia (c) is a sign of tetralogy of Fallot from chronic hypoxia, not heart failure.', true),
  ('cardio', 10, 'The parents of a 2-month-old with a newly found small VSD ask whether their infant will need heart surgery right away. The infant is pink and feeding well. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"All VSDs need surgery before the infant reaches 6 months old.\""}, {"id": "b", "text": "\"Small VSDs may close spontaneously; large ones need surgery.\""}, {"id": "c", "text": "\"A VSD is usually closed with indomethacin instead of surgery.\""}, {"id": "d", "text": "\"A VSD is a cyanotic defect, so repair is urgent.\""}]'::jsonb, '["b"]', 'Small VSDs may close spontaneously, while large VSDs require surgery. Indomethacin is used to close a PDA, and VSD is an acyanotic defect with a left-to-right shunt.', false),
  ('cardio', 11, 'A 7-year-old is seen for a sports physical. The child is pink, active, and growing normally, but a murmur is heard, and testing shows a hole between the atria. The parent asks how this could have been missed for years. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"This defect always causes cyanosis, so it was likely recent.\""}, {"id": "b", "text": "\"This defect causes a continuous machine-like murmur at birth.\""}, {"id": "c", "text": "\"This defect closes with indomethacin, so it went unnoticed.\""}, {"id": "d", "text": "\"This defect is often asymptomatic in childhood.\""}]'::jsonb, '["d"]', 'An ASD (hole between atria) is often asymptomatic in childhood and may be found only when a murmur is heard; it is repaired if large. ASD is acyanotic, and the continuous machine-like murmur and indomethacin treatment describe a PDA.', false),
  ('cardio', 12, 'A 3-year-old with unrepaired tetralogy of Fallot is admitted for surgical repair. Which assessment findings would the nurse expect in this child? Select all that apply.', '[{"id": "a", "text": "Continuous \"machine-like\" murmur"}, {"id": "b", "text": "Cyanosis that worsens with crying"}, {"id": "c", "text": "Clubbing of fingers/toes"}, {"id": "d", "text": "Pink color with normal O₂ saturation"}, {"id": "e", "text": "Polycythemia (high RBC)"}]'::jsonb, '["b", "c", "e"]', 'TOF is a cyanotic defect, so the child is blue, especially when crying (b), and has clubbing (c) and polycythemia from chronic hypoxia (e). A continuous machine-like murmur (a) describes a PDA, and pink color with normal O₂ saturation (d) describes acyanotic defects.', true),
  ('cardio', 13, 'A 2-year-old with heart failure has been receiving furosemide (Lasix) for 3 days. The child is now weak and less active, and the morning electrolyte panel was drawn. Which lab finding should the nurse report to the health care provider as MOST likely related to this drug?', '[{"id": "a", "text": "Elevated potassium (hyperkalemia)"}, {"id": "b", "text": "Elevated RBC count (polycythemia)"}, {"id": "c", "text": "Low potassium (hypokalemia)"}, {"id": "d", "text": "Elevated platelet count"}]'::jsonb, '["c"]', 'Furosemide is a loop diuretic with a hypokalemia risk, so K⁺ and electrolytes are monitored. Hyperkalemia is a caution with captopril, and polycythemia is a sign of tetralogy of Fallot.', false),
  ('cardio', 14, 'A 4-year-old with heart failure takes captopril and digoxin. The child is not taking furosemide. Today''s labs show a serum potassium above the normal range. Which medication should the nurse MOST suspect as contributing to this finding?', '[{"id": "a", "text": "Captopril"}, {"id": "b", "text": "Digoxin"}, {"id": "c", "text": "Indomethacin"}, {"id": "d", "text": "Morphine"}]'::jsonb, '["a"]', 'Captopril, an ACE inhibitor, carries cautions of hypotension, persistent dry cough, and hyperkalemia. Furosemide causes hypokalemia rather than high potassium, and digoxin''s cautions center on heart rate and toxicity.', false),
  ('cardio', 15, 'A 4-year-old returned from surgical repair of tetralogy of Fallot 6 hours ago. The child is crying and agitated, and the incision is dry. Which interventions should the nurse include in the post-operative plan? Select all that apply.', '[{"id": "a", "text": "Continuous cardiac monitoring and SpO₂"}, {"id": "b", "text": "Let the child cry to expand the lungs"}, {"id": "c", "text": "Pain management to reduce agitation"}, {"id": "d", "text": "Limit deep breathing to protect the incision"}, {"id": "e", "text": "Assess for arrhythmias"}]'::jsonb, '["a", "c", "e"]', 'Post-operative care includes continuous cardiac monitoring with vitals and SpO₂ (a), pain management to reduce agitation, which increases O₂ demand (c), and assessing for arrhythmias (e). Crying (b) adds agitation and O₂ demand, and deep breathing with incentive spirometry is encouraged, not limited (d).', true),
  ('cardio', 16, 'A 4-month-old with a congenital heart defect is pink with an SpO₂ of 97%. The infant breathes fast, has retractions with feeding, and has gained little weight since birth. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Right-to-left shunt sending unoxygenated blood to the systemic circulation"}, {"id": "b", "text": "Left-to-right shunt recirculating oxygenated blood through the lungs"}, {"id": "c", "text": "Tet spell triggered by the crying, feeding, or defecation"}, {"id": "d", "text": "Right-to-left shunt caused by the overriding aorta straddling the VSD"}]'::jsonb, '["b"]', 'Acyanotic defects shunt blood left to right so oxygenated blood recirculates through the lungs; the child is pink but may have increased respiratory effort and poor growth. A right-to-left shunt causes cyanosis and low O₂ saturation.', false),
  ('cardio', 17, 'The parent of a 9-month-old with a congenital heart defect reports that the infant''s lips and nail beds turn blue whenever the infant cries hard or crawls for a long time. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "Oxygenated blood is recirculating through the lungs"}, {"id": "b", "text": "The ductus arteriosus is closing after birth"}, {"id": "c", "text": "The heart rate is too slow from digoxin"}, {"id": "d", "text": "Unoxygenated blood enters the systemic circulation"}]'::jsonb, '["d"]', 'In cyanotic defects, blood shunts right to left so unoxygenated blood enters the systemic circulation, and the child is blue especially when crying or during activity. Recirculation of oxygenated blood through the lungs describes a left-to-right acyanotic defect, in which the child is pink.', false),
  ('cardio', 18, 'The nurse is preparing home-care teaching for the parents of a 6-month-old with heart failure who will be discharged on furosemide and digoxin. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Weigh the infant once a week on any scale"}, {"id": "b", "text": "Weigh daily at the same time on the same scale"}, {"id": "c", "text": "Skip a dose when the infant seems well"}, {"id": "d", "text": "SBE prophylaxis before dental procedures if applicable"}, {"id": "e", "text": "Encourage strenuous play to build endurance"}]'::jsonb, '["b", "d"]', 'Families weigh the child daily at the same time on the same scale (b) and use SBE prophylaxis, antibiotics before dental or invasive procedures, if applicable (d). Weekly weights on any scale (a) miss fluid changes, medications are given on schedule and never skipped (c), and strenuous play is avoided until cleared (e).', true),
  ('cardio', 19, 'The nurse on a pediatric cardiac unit receives morning report on four infants. Which infant should the nurse assess FIRST?', '[{"id": "a", "text": "A 2-month-old with a small VSD and a loud harsh murmur"}, {"id": "b", "text": "A 4-month-old with a PDA and a continuous machine-like murmur"}, {"id": "c", "text": "A 3-month-old who sweats and stops often during feedings"}, {"id": "d", "text": "A 5-month-old with an ASD who is pink and feeding well"}]'::jsonb, '["c"]', 'Diaphoresis and tiring during feeding with frequent stops are signs of heart failure in infants and need assessment first. A loud harsh murmur with VSD, a continuous machine-like murmur with PDA, and a pink, feeding ASD infant are expected findings for those defects.', false),
  ('cardio', 20, 'A 6-year-old with a congenital heart defect is resting quietly in bed. Vital signs: HR 130 bpm, RR 24/min, BP 100/64 mmHg, SpO₂ 97%. Which finding should the nurse report to the health care provider?', '[{"id": "a", "text": "HR 130 bpm"}, {"id": "b", "text": "RR 24/min"}, {"id": "c", "text": "BP 100/64 mmHg"}, {"id": "d", "text": "SpO₂ 97%"}]'::jsonb, '["a"]', 'The normal heart rate for a child aged 1–8 years is 70–120 bpm, so 130 bpm at rest is tachycardia, a compensatory sign of heart failure. RR 20–30/min, BP ~90–110/55–75 mmHg, and SpO₂ ≥95% are normal for this age.', false),
  ('cardio', 21, 'The nurse is preparing to give digoxin to a 6-month-old with heart failure. Which actions are appropriate before giving the dose? Select all that apply.', '[{"id": "a", "text": "Check the apical pulse for 1 full minute"}, {"id": "b", "text": "Hold the dose if the HR is <90 bpm"}, {"id": "c", "text": "Hold the dose only if the HR is <70 bpm"}, {"id": "d", "text": "Double-check the dose; narrow therapeutic range"}, {"id": "e", "text": "Give it on an empty stomach, as with captopril"}]'::jsonb, '["a", "b", "d"]', 'The nurse checks the apical pulse for 1 full minute (a), holds digoxin if the HR is <90 bpm in an infant (b), and is careful with dosing because digoxin has a narrow therapeutic range (d). The <70 bpm cut-off (c) applies to children, and giving on an empty stomach (e) is a caution for captopril in infants, not digoxin.', true),
  ('cardio', 22, 'A 3-month-old with a large VSD is awaiting surgery. The infant tires during feedings and has gained little weight over the past 2 weeks. Which pre-operative intervention should the nurse anticipate as the PRIORITY for this infant''s nutrition?', '[{"id": "a", "text": "Limiting feedings to reduce the heart''s workload"}, {"id": "b", "text": "Supporting feeding with high-calorie formula"}, {"id": "c", "text": "Restricting fluid intake to prevent fluid overload"}, {"id": "d", "text": "Holding feedings until the infant stops sweating"}]'::jsonb, '["b"]', 'Pre-operative care includes supporting feeding with high-calorie formula, along with daily weights and intake/output. Limiting, restricting, or holding feedings would worsen the poor growth that is common with acyanotic defects and heart failure.', false),
  ('cardio', 23, 'A 2-year-old is 1 day post-op after cardiac surgery. The child is thrashing, crying, and pulling at the dressing; the incision is intact, and the SpO₂ is drifting down. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Remove the dressing to inspect for dehiscence"}, {"id": "b", "text": "Have the child blow into the incentive spirometer now"}, {"id": "c", "text": "Delay comfort measures until vital signs settle"}, {"id": "d", "text": "Give prescribed pain medication to reduce agitation"}]'::jsonb, '["d"]', 'Post-operative care includes pain management and reducing agitation, because agitation increases O₂ demand. The incision is intact, and incentive spirometry is not realistic until the child is calmer.', false),
  ('cardio', 24, 'The nurse reviews the records of five children with congenital heart defects. Which children have a defect in which blood shunts left to right (an acyanotic defect)? Select all that apply.', '[{"id": "a", "text": "A 2-month-old with a ventricular septal defect"}, {"id": "b", "text": "A 3-year-old with tetralogy of Fallot"}, {"id": "c", "text": "A premature infant with a PDA"}, {"id": "d", "text": "An infant with pulmonary stenosis, VSD, overriding aorta"}, {"id": "e", "text": "A 6-year-old with an atrial septal defect"}]'::jsonb, '["a", "c", "e"]', 'VSD (a), PDA (c), and ASD (e) are acyanotic defects with a left-to-right shunt. Tetralogy of Fallot (b) is cyanotic with a right-to-left shunt, and pulmonary stenosis with VSD and an overriding aorta (d) are components of TOF.', true),
  ('cardio', 25, 'The parent of a 5-year-old with a repaired congenital heart defect calls the clinic because the child has a dental cleaning and tooth extraction scheduled next week. Which instruction by the nurse is MOST appropriate?', '[{"id": "a", "text": "\"Hold the heart medications on the day of the dental visit.\""}, {"id": "b", "text": "\"Dental care should wait until all activity limits are lifted.\""}, {"id": "c", "text": "\"SBE prophylaxis with antibiotics may be needed.\""}, {"id": "d", "text": "\"No special steps are needed once the heart has been repaired.\""}]'::jsonb, '["c"]', 'Family teaching includes SBE prophylaxis, which is antibiotics before dental or invasive procedures if applicable. Medications are given on schedule and never skipped.', false),
  ('cardio', 26, 'At a follow-up visit, the parent of a 2-year-old with heart failure says, "She seemed so well this week that I gave her digoxin only every other day." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Give medications on schedule; never skip doses, even if well.\""}, {"id": "b", "text": "\"Every-other-day dosing is fine while she is eating well.\""}, {"id": "c", "text": "\"Give a double dose tomorrow to make up for missed doses.\""}, {"id": "d", "text": "\"Give it each day only when her apical pulse is above 90 bpm.\""}]'::jsonb, '["a"]', 'Family teaching for heart conditions is to give medications on schedule and never skip doses. Doubling doses is unsafe because digoxin has a narrow therapeutic range, and for a child the hold cut-off is <70 bpm, not 90 bpm.', false),
  ('cardio', 27, 'The nurse is teaching the parents of a 2-month-old with an unrepaired VSD which changes at home are signs of distress that should be reported. Which signs should the nurse include? Select all that apply.', '[{"id": "a", "text": "Poor feeding"}, {"id": "b", "text": "Fast breathing"}, {"id": "c", "text": "More wet diapers than usual"}, {"id": "d", "text": "Color changes"}, {"id": "e", "text": "Fewer wet diapers"}]'::jsonb, '["a", "b", "d", "e"]', 'Signs of distress to teach families are poor feeding (a), fast breathing (b), color changes (d), and fewer wet diapers (e). More wet diapers than usual (c) is not a sign of distress listed for families.', true),
  ('cardio', 28, 'A 3-year-old with unrepaired tetralogy of Fallot is playing quietly with blocks. The child''s lips are slightly blue, and the SpO₂ is below 95%, unchanged from the child''s documented baseline. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The child is having a tet spell and needs knee-to-chest position"}, {"id": "b", "text": "A lower SpO₂ can be expected with this cyanotic defect"}, {"id": "c", "text": "The SpO₂ shows the shunt has changed to left to right"}, {"id": "d", "text": "The SpO₂ must be ≥95%, so oxygen is needed right away"}]'::jsonb, '["b"]', 'The normal SpO₂ is ≥95%, but a lower value may be expected with a cyanotic defect such as TOF, and this value is at the child''s baseline. A tet spell is a sudden blue, hypoxic episode, which this calm child is not having.', false),
  ('cardio', 29, 'The parents of a 1-week-old premature infant are told the infant has a PDA. They ask the nurse what that means. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "\"There is a hole between the two upper chambers of your baby''s heart.\""}, {"id": "b", "text": "\"There is a hole between the two lower chambers of your baby''s heart.\""}, {"id": "c", "text": "\"The valve to the lungs is narrowed and the aorta is shifted over.\""}, {"id": "d", "text": "\"A fetal vessel linking aorta and pulmonary artery stayed open.\""}]'::jsonb, '["d"]', 'PDA is a fetal vessel connecting the aorta to the pulmonary artery that fails to close after birth. A hole between the atria is an ASD, a hole between the ventricles is a VSD, and pulmonary stenosis with an overriding aorta are parts of TOF.', false),
  ('cardio', 30, 'A 6-month-old with heart failure takes captopril. The nurse reviews new findings with the parent. Which findings should the nurse recognize as cautions associated with this medication? Select all that apply.', '[{"id": "a", "text": "Hypotension"}, {"id": "b", "text": "Hypokalemia"}, {"id": "c", "text": "Persistent dry cough"}, {"id": "d", "text": "Hyperkalemia"}, {"id": "e", "text": "Yellow/green vision"}]'::jsonb, '["a", "c", "d"]', 'Captopril cautions are hypotension (a), persistent dry cough (c), and hyperkalemia (d). Hypokalemia (b) is a risk of furosemide, and yellow/green vision (e) is a sign of digoxin toxicity.', true),
  ('cardio', 31, 'A 7-month-old with heart failure started furosemide (Lasix) 2 days ago for fluid overload. Which finding BEST indicates that the medication is having the desired effect?', '[{"id": "a", "text": "Serum potassium is lower than it was on admission"}, {"id": "b", "text": "Heart rate has slowed to 88 bpm since yesterday"}, {"id": "c", "text": "Daily weight is falling; output exceeds intake"}, {"id": "d", "text": "A persistent dry cough has developed overnight"}]'::jsonb, '["c"]', 'Furosemide is a loop diuretic that reduces fluid overload, and its effect is monitored with I&Os and daily weight. A falling potassium is the hypokalemia risk to monitor, not a sign of benefit, and a dry cough is a captopril caution.', false),
  ('cardio', 32, 'A 4-month-old with a large VSD has periorbital edema, tachypnea with retractions, and an enlarged liver on palpation. Which medication should the nurse anticipate FIRST to reduce this infant''s fluid overload?', '[{"id": "a", "text": "Furosemide (Lasix)"}, {"id": "b", "text": "Indomethacin"}, {"id": "c", "text": "IV propranolol and O₂"}, {"id": "d", "text": "Morphine and O₂"}]'::jsonb, '["a"]', 'Periorbital edema, tachypnea with retractions, and hepatomegaly are heart failure signs, and furosemide is the loop diuretic that reduces fluid overload. Indomethacin closes a PDA, and morphine and IV propranolol are used for tet spells.', false),
  ('cardio', 33, 'A 9-month-old with tetralogy of Fallot becomes suddenly blue and hypoxic while feeding. The nurse calls for help. Which interventions are appropriate for this episode? Select all that apply.', '[{"id": "a", "text": "Encourage vigorous crying to deepen breaths"}, {"id": "b", "text": "Place the infant in knee-to-chest position"}, {"id": "c", "text": "Give O₂"}, {"id": "d", "text": "Give morphine as prescribed"}, {"id": "e", "text": "Calm the child"}]'::jsonb, '["b", "c", "d", "e"]', 'For a tet spell, the nurse places the child in knee-to-chest position (b), gives O₂ (c), gives morphine and IV propranolol as prescribed (d), and calms the child (e). Crying (a) is a trigger of tet spells and worsens the episode.', true),
  ('cardio', 34, 'The parent of a 1-year-old with heart failure asks why digoxin is needed when the child''s heart is already beating fast. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"It removes extra fluid so the liver can shrink.\""}, {"id": "b", "text": "\"It slows and strengthens the heartbeat.\""}, {"id": "c", "text": "\"It lowers afterload to reduce heart workload.\""}, {"id": "d", "text": "\"It closes the fetal vessel near the heart.\""}]'::jsonb, '["b"]', 'Digoxin slows and strengthens the heartbeat (positive inotropic, negative chronotropic). Lowering afterload describes captopril, removing fluid describes furosemide, and closing the fetal vessel describes indomethacin for PDA.', false),
  ('cardio', 35, 'A 6-week-old term infant has a loud harsh murmur at a well visit. The infant is pink with an SpO₂ of 98% but breathes fast during feeds. Which defect is the nurse MOST likely to see confirmed?', '[{"id": "a", "text": "Tetralogy of Fallot"}, {"id": "b", "text": "Patent ductus arteriosus"}, {"id": "c", "text": "Atrial septal defect"}, {"id": "d", "text": "Ventricular septal defect"}]'::jsonb, '["d"]', 'VSD, the most common congenital heart defect, causes a loud harsh murmur and is acyanotic, so the infant is pink but may breathe fast. PDA causes a continuous machine-like murmur and is common in premature infants, ASD is often asymptomatic, and TOF is cyanotic.', false),
  ('cardio', 36, 'A 4-month-old with a VSD is resting quietly. Vital signs: HR 172 bpm, RR 44/min, BP 86/58 mmHg, and SpO₂ 93%; at the next check the RR is 68/min. Which findings require follow-up? Select all that apply.', '[{"id": "a", "text": "HR 172 bpm"}, {"id": "b", "text": "RR 44/min"}, {"id": "c", "text": "RR 68/min"}, {"id": "d", "text": "SpO₂ 93%"}, {"id": "e", "text": "BP 86/58 mmHg"}]'::jsonb, '["a", "c", "d"]', 'Normal infant values are HR 100–160 bpm, RR 30–60/min, BP ~70–100/50–65 mmHg, and SpO₂ ≥95%. HR 172 (a), RR 68 (c), and SpO₂ 93% (d) are outside these ranges; a VSD is acyanotic, so a lower SpO₂ is not expected. RR 44 (b) and BP 86/58 (e) are normal.', true),
  ('cardio', 37, 'A 5-month-old receiving digoxin for heart failure has vomited after the last two feedings and is refusing the bottle. The apical pulse is 104 bpm. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Give the dose because the apical pulse is above 90 bpm"}, {"id": "b", "text": "Give the dose with formula to settle the stomach"}, {"id": "c", "text": "Hold the dose and report possible digoxin toxicity"}, {"id": "d", "text": "Give a smaller dose until the vomiting resolves"}]'::jsonb, '["c"]', 'Vomiting and loss of appetite are signs of digoxin toxicity, and digoxin has a narrow therapeutic range, so the nurse withholds and reports. A heart rate above 90 bpm does not rule out toxicity.', false),
  ('cardio', 38, 'The nurse is reviewing the medication schedule for a 4-month-old with heart failure who takes captopril. The infant feeds every 3 hours. Which plan for giving captopril is BEST?', '[{"id": "a", "text": "Give on an empty stomach, between feedings"}, {"id": "b", "text": "Mix it into the bottle during a full feeding"}, {"id": "c", "text": "Give it right after a full feeding"}, {"id": "d", "text": "Give it with high-calorie formula"}]'::jsonb, '["a"]', 'Captopril should be given on an empty stomach in infants, so it is timed between feedings. Mixing it into or giving it with formula would not meet this caution.', false),
  ('cardio', 39, 'An 8-month-old with tetralogy of Fallot is scheduled for surgical repair next week. Which actions should the nurse include in the pre-operative plan of care? Select all that apply.', '[{"id": "a", "text": "Monitor SpO₂ and cyanosis"}, {"id": "b", "text": "Daily weight; intake/output"}, {"id": "c", "text": "High-calorie formula feeds"}, {"id": "d", "text": "Restrict calories to lower workload"}, {"id": "e", "text": "Up-to-date vaccines; prevent infection"}]'::jsonb, '["a", "b", "c", "e"]', 'Pre-operative care includes monitoring SpO₂ and cyanosis (a), daily weight with intake/output (b), supporting feeding with high-calorie formula (c), and preventing infection with up-to-date vaccines (e). Restricting calories (d) contradicts high-calorie feeding support.', true),
  ('cardio', 40, 'A 5-year-old is 3 days post-op after cardiac surgery. The nurse notes that the edges of the chest incision have separated, with redness and drainage. The child is afebrile and calm. Which action is the PRIORITY?', '[{"id": "a", "text": "Document the finding and recheck at the next shift"}, {"id": "b", "text": "Report infection/dehiscence to the provider"}, {"id": "c", "text": "Have the child use the incentive spirometer more"}, {"id": "d", "text": "Apply a new dressing and reassess the next day"}]'::jsonb, '["b"]', 'Post-operative incision care includes watching for infection and dehiscence, so a separated, red, draining incision must be reported. Incentive spirometry is part of routine care, and waiting until the next shift or day delays treatment.', false),
  ('cardio', 41, 'A 9-year-old is 1 day post-op after repair of an ASD. The child is splinting the chest with shallow breaths and says it hurts to breathe deeply. Pain medication was given 30 minutes ago with relief. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Allow shallow breathing until the incision has healed"}, {"id": "b", "text": "Keep the child flat in bed and limit all movement"}, {"id": "c", "text": "Hold further pain medication to avoid drowsiness"}, {"id": "d", "text": "Encourage deep breathing with incentive spirometry"}]'::jsonb, '["d"]', 'With pain now relieved, the nurse encourages deep breathing and incentive spirometry, which is part of post-operative care. Shallow breathing should not be allowed to continue, and pain management is continued because agitation increases O₂ demand.', false),
  ('cardio', 42, 'The nurse evaluates home-care teaching with the parent of a 7-month-old with heart failure. Which statements by the parent indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "\"I''ll weigh her daily, on a different scale each time.\""}, {"id": "b", "text": "\"I''ll give her medicines on schedule every day.\""}, {"id": "c", "text": "\"I''ll call if she has fewer wet diapers than usual.\""}, {"id": "d", "text": "\"She can do strenuous play before being cleared.\""}, {"id": "e", "text": "\"I''ll supplement breastmilk to give her extra calories.\""}]'::jsonb, '["a", "d"]', 'The infant should be weighed daily at the same time on the same scale, so using any scale (a) needs correction, and activity restrictions apply with strenuous play avoided until cleared (d). Giving medications on schedule (b), reporting fewer wet diapers (c), and supplementing breastmilk for high-calorie feedings (e) are correct.', true),
  ('cardio', 43, 'A 3-year-old has had a high fever for 6 days and now shows 4 of the 5 diagnostic criteria for Kawasaki disease. The parent is anxious about the child''s heart. Which treatment plan should the nurse anticipate as MOST appropriate?', '[{"id": "a", "text": "Furosemide and captopril to reduce heart workload"}, {"id": "b", "text": "Knee-to-chest position, O₂, and morphine"}, {"id": "c", "text": "IVIG within 10 days plus high-dose aspirin"}, {"id": "d", "text": "Indomethacin, then surgical ligation if needed"}]'::jsonb, '["c"]', 'Kawasaki disease (fever ≥5 days plus 4 of 5 criteria) is treated with IVIG within 10 days plus high-dose aspirin to prevent coronary artery aneurysms. Knee-to-chest, O₂, and morphine treat tet spells, and indomethacin treats PDA.', false),
  ('cardio', 44, 'A nursing student caring for a 1-year-old with tetralogy of Fallot asks why the knee-to-chest position helps during a tet spell. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "\"It increases SVR, forcing blood through the pulmonary circulation.\""}, {"id": "b", "text": "\"It decreases SVR so more blood flows out through the aorta.\""}, {"id": "c", "text": "\"It closes the VSD so blood can no longer shunt between the ventricles.\""}, {"id": "d", "text": "\"It slows the heart rate in the same way that digoxin does.\""}]'::jsonb, '["a"]', 'Knee-to-chest position increases SVR, which forces blood through the pulmonary circulation during a tet spell. It does not close the VSD or act like digoxin, which slows and strengthens the heartbeat.', false),
  ('cardio', 45, 'A 2-year-old with heart failure has started furosemide (Lasix). The nurse is planning care for this medication. Which nursing actions are specific to furosemide therapy? Select all that apply.', '[{"id": "a", "text": "Hold the dose if HR is <90 bpm"}, {"id": "b", "text": "Watch for hyperkalemia"}, {"id": "c", "text": "Monitor K⁺ for hypokalemia"}, {"id": "d", "text": "Daily weight and I&Os"}, {"id": "e", "text": "Give on an empty stomach"}]'::jsonb, '["c", "d"]', 'Furosemide requires monitoring K⁺ for hypokalemia risk (c) and daily weight with I&Os (d), along with electrolytes. Holding for a low heart rate (a) applies to digoxin, and hyperkalemia (b) and giving on an empty stomach (e) are captopril cautions.', true),
  ('cardio', 46, 'A 6-year-old who had a VSD repaired 2 weeks ago wants to join a soccer game at recess. The surgeon has not yet cleared the child for full activity. Which response by the nurse to the parent is BEST?', '[{"id": "a", "text": "\"Soccer is fine if the child rests whenever tired.\""}, {"id": "b", "text": "\"Avoid strenuous play until the child is cleared.\""}, {"id": "c", "text": "\"Soccer is fine since the defect is now repaired.\""}, {"id": "d", "text": "\"Light running is fine if the incision looks healed.\""}]'::jsonb, '["b"]', 'Family teaching includes activity restrictions as ordered and avoiding strenuous play until cleared. A repaired defect, resting when tired, or a healed-looking incision does not mean the child has been cleared.', false),
  ('cardio', 47, 'The nurse is caring for four children with tetralogy of Fallot. Which child should the nurse see FIRST?', '[{"id": "a", "text": "A 3-year-old with clubbing of the fingers and toes"}, {"id": "b", "text": "A 4-year-old whose RBC count is above normal"}, {"id": "c", "text": "A 2-year-old with blue lips at a stable, baseline SpO₂ level"}, {"id": "d", "text": "A 7-month-old, suddenly blue and hypoxic while feeding"}]'::jsonb, '["d"]', 'A sudden blue, hypoxic episode triggered by feeding is a tet spell, which needs immediate knee-to-chest positioning. Clubbing, polycythemia, and baseline cyanosis are expected chronic findings of TOF.', false),
  ('cardio', 48, 'A nurse is preparing a dose of digoxin oral solution for a 10-month-old. A second nurse offers to skip the independent double-check because the unit is busy. Which response by the first nurse is MOST appropriate?', '[{"id": "a", "text": "\"A double-check is needed only for IV drugs, so this is fine.\""}, {"id": "b", "text": "\"A double-check is needed only if the pulse is below 90 bpm.\""}, {"id": "c", "text": "\"Digoxin has a narrow therapeutic range; let''s verify it.\""}, {"id": "d", "text": "\"The pulse check alone will show whether the dose is correct.\""}]'::jsonb, '["c"]', 'Digoxin has a narrow therapeutic range, so small dosing errors can cause toxicity, and careful verification is appropriate. The apical pulse check decides whether to give the dose; it does not verify the dose amount.', false),
  ('cardio', 49, 'The parents of a 2-week-old premature infant with a PDA are told that the first medication did not close the vessel. They ask what other options exist. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Surgical ligation is the other treatment option.\""}, {"id": "b", "text": "\"Knee-to-chest positioning will close the vessel.\""}, {"id": "c", "text": "\"Morphine and IV propranolol will close the vessel.\""}, {"id": "d", "text": "\"Captopril will close the vessel within a few days.\""}]'::jsonb, '["a"]', 'PDA is treated with indomethacin, which closes the PDA, or with surgical ligation. Knee-to-chest positioning, morphine, and IV propranolol are tet spell treatments, and captopril lowers afterload.', false),
  ('cardio', 50, 'An 11-month-old with tetralogy of Fallot has a hypercyanotic spell. The nurse has placed the infant in knee-to-chest position and started O₂, but the infant remains deeply cyanotic. Which prescribed medications should the nurse prepare NEXT?', '[{"id": "a", "text": "Digoxin and furosemide (Lasix)"}, {"id": "b", "text": "Morphine and IV propranolol"}, {"id": "c", "text": "Indomethacin and captopril"}, {"id": "d", "text": "Captopril and furosemide"}]'::jsonb, '["b"]', 'Tet spell management includes knee-to-chest position, O₂, morphine, and IV propranolol, along with calming the child. Digoxin, furosemide, and captopril treat heart failure, and indomethacin closes a PDA.', false),
  ('neuro_disorders', 1, 'A 4-year-old sitting on the floor of the playroom suddenly stiffens and then begins rhythmic jerking of all four extremities. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Hold the child''s arms and legs to stop the jerking"}, {"id": "b", "text": "Place a padded tongue blade between the child''s teeth"}, {"id": "c", "text": "Position the child side-lying to prevent aspiration"}, {"id": "d", "text": "Leave the child to bring the emergency medication cart"}]'::jsonb, '["c"]', 'During a tonic-clonic seizure the child is placed side-lying to prevent aspiration while the nurse stays with the child and calls for help. The child is NOT restrained and nothing is put in the mouth, and the nurse does not leave the child.', false),
  ('neuro_disorders', 2, 'A 7-year-old seated beside a metal IV pole stiffens and then begins rhythmic jerking. The nurse has called for help and stays with the child. Which actions should the nurse take while the seizure continues? Select all that apply.', '[{"id": "a", "text": "Time the seizure and note the movements"}, {"id": "b", "text": "Loosen clothing around the child''s neck"}, {"id": "c", "text": "Clear the area of hazards such as the IV pole"}, {"id": "d", "text": "Restrain the arms to protect from injury"}, {"id": "e", "text": "Turn the child into a side-lying position"}]'::jsonb, '["a", "b", "c", "e"]', 'Timing the seizure and documenting length and movements (a), loosening clothing (b), clearing the area of hazards (c), and side-lying positioning to prevent aspiration (e) are all correct seizure care. Restraining the child (d) is wrong because the child must NOT be restrained.', true),
  ('neuro_disorders', 3, 'A teacher reports that an 8-year-old seems to daydream many times a day: the child stares blankly for a few seconds, pauses in mid-sentence, and then resumes the activity. Which condition is the nurse MOST likely to suspect?', '[{"id": "a", "text": "Absence seizures, common in school-age children"}, {"id": "b", "text": "ADHD, inattentive type, treated with stimulants"}, {"id": "c", "text": "Febrile seizures, triggered by a rapid fever rise"}, {"id": "d", "text": "Tonic-clonic seizures, the most recognizable type"}]'::jsonb, '["a"]', 'A brief blank stare in which the child pauses and resumes activity is an absence seizure, which is common in school-age children and may be misunderstood as daydreaming. ADHD inattentive type does not cause brief blank staring spells with pausing and resuming of activity.', false),
  ('neuro_disorders', 4, 'Four children are brought to the emergency department after a brief generalized seizure that began as their temperature rose rapidly. Which child''s age is MOST consistent with a febrile seizure?', '[{"id": "a", "text": "4 months of age"}, {"id": "b", "text": "6 years of age"}, {"id": "c", "text": "9 years of age"}, {"id": "d", "text": "2 years of age"}]'::jsonb, '["d"]', 'Febrile seizures are triggered by a rapid fever rise in children ages 6 months to 5 years, so only the 2-year-old fits. The 4-month-old is younger than 6 months and the 6-year-old is older than 5 years.', false),
  ('neuro_disorders', 5, 'The parent of a 2-year-old who had a brief seizure after a rapid fever rise is receiving teaching from the nurse. Which statements by the parent indicate understanding? Select all that apply.', '[{"id": "a", "text": "''This type of seizure is usually harmless and brief.''"}, {"id": "b", "text": "''He will need daily valproic acid from now on.''"}, {"id": "c", "text": "''We still need to evaluate the fever source.''"}, {"id": "d", "text": "''This type of seizure usually causes brain damage.''"}, {"id": "e", "text": "''He is at risk for these until he is about 10 years old.''"}]'::jsonb, '["a", "c"]', 'Febrile seizures are usually harmless and brief (a), and the fever source must be evaluated (c). Valproic acid is a maintenance seizure medication, not routine after a febrile seizure (b); febrile seizures rarely cause brain damage (d); and they occur from 6 months to 5 years, not to age 10 (e).', true),
  ('neuro_disorders', 6, 'A 6-year-old''s 2-minute tonic-clonic seizure has just ended. The child is drowsy, difficult to arouse, and breathing noisily. Which action is the nurse''s PRIORITY?', '[{"id": "a", "text": "Document the length and movements of the seizure"}, {"id": "b", "text": "Notify the parents that the seizure has stopped"}, {"id": "c", "text": "Check airway, breathing, and LOC"}, {"id": "d", "text": "Give the scheduled dose of levetiracetam (Keppra)"}]'::jsonb, '["c"]', 'After a seizure the nurse checks airway, breathing, and LOC; noisy breathing in a drowsy child makes the airway the priority. Documentation of length, movements, and post-ictal state is required but comes after airway and breathing are secured.', false),
  ('neuro_disorders', 7, 'A 5-year-old has been having a generalized seizure for several minutes in the emergency department, and two attempts to start an IV have failed. Which prescription does the nurse MOST likely anticipate?', '[{"id": "a", "text": "Diazepam (Valium) rectally"}, {"id": "b", "text": "Phenytoin (Dilantin) by mouth"}, {"id": "c", "text": "Valproic acid by mouth"}, {"id": "d", "text": "Levetiracetam (Keppra) by mouth"}]'::jsonb, '["a"]', 'Emergency seizure medication is lorazepam or diazepam given IV or rectally; with no IV access, rectal diazepam is the option. Phenytoin, levetiracetam, and valproic acid are maintenance medications and are not given by mouth to a child who is actively seizing.', false),
  ('neuro_disorders', 8, 'The parent of a 9-year-old newly diagnosed with a seizure disorder asks the nurse which of the child''s medications are taken every day as maintenance therapy and which are kept for emergencies. Which medications should the nurse identify as maintenance medications? Select all that apply.', '[{"id": "a", "text": "Lorazepam (Ativan)"}, {"id": "b", "text": "Phenytoin (Dilantin)"}, {"id": "c", "text": "Levetiracetam (Keppra)"}, {"id": "d", "text": "Diazepam (Valium)"}, {"id": "e", "text": "Valproic acid"}]'::jsonb, '["b", "c", "e"]', 'Phenytoin (b), levetiracetam (c), and valproic acid (e) are maintenance medications. Lorazepam (a) and diazepam (d) are emergency medications given IV or rectally to stop an active seizure.', true),
  ('neuro_disorders', 9, 'A nurse on a pediatric unit receives report on four infants. Which infant should the nurse see FIRST?', '[{"id": "a", "text": "A newborn with Down syndrome who has a single palmar crease and low muscle tone"}, {"id": "b", "text": "A 10-month-old with spastic cerebral palsy who has stiff movements of the legs"}, {"id": "c", "text": "A 7-month-old who had a febrile seizure yesterday and is playing calmly"}, {"id": "d", "text": "A 4-month-old with a VP shunt who is vomiting and has a high-pitched, shrill cry"}]'::jsonb, '["d"]', 'Vomiting and a high-pitched, shrill cry in an infant with a VP shunt are signs of increased ICP and possible shunt blockage. A single palmar crease with low muscle tone in Down syndrome and stiff movements in spastic CP are expected findings of those conditions.', false),
  ('neuro_disorders', 10, 'A 3-month-old with a VP shunt is brought to the clinic because the parent says the infant ''has not been himself.'' Which assessment findings indicate increased ICP and require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Bulging, tense fontanel"}, {"id": "b", "text": "Eyes deviated downward (sunset sign)"}, {"id": "c", "text": "Eyes deviated upward with a blank stare"}, {"id": "d", "text": "Rapidly increasing head circumference"}, {"id": "e", "text": "Low muscle tone and a single palmar crease"}]'::jsonb, '["a", "b", "d"]', 'A bulging/tense fontanel (a), the sunset sign with eyes deviated downward (b), and rapidly increasing head circumference (d) are infant signs of increased ICP. In the sunset sign the eyes deviate downward, not upward (c), and low muscle tone with a single palmar crease (e) are features of Down syndrome.', true),
  ('neuro_disorders', 11, 'The nurse is teaching the parent of a 2-month-old who just had a VP shunt placed for hydrocephalus. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "''The shunt drains the extra CSF from a ventricle in his brain.''"}, {"id": "b", "text": "''The shunt carries the extra fluid from his brain into his heart.''"}, {"id": "c", "text": "''I should call if he has a fever, vomiting, or seems less alert.''"}, {"id": "d", "text": "''Fluid built up in his brain ventricles and raised the pressure.''"}]'::jsonb, '["b"]', 'A ventriculoperitoneal shunt drains CSF from a brain ventricle to the peritoneal cavity (abdomen), not to the heart. Fever, vomiting, and decreased LOC are correctly identified as shunt complications to report.', false),
  ('neuro_disorders', 12, 'A 7-year-old who had a VP shunt placed in infancy reports a headache since this morning, is febrile and flushed, has vomited twice, and is difficult to arouse. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Suspect viral meningitis, which is usually self-limiting, and observe"}, {"id": "b", "text": "Suspect a stomach virus and encourage small sips of clear fluid"}, {"id": "c", "text": "Suspect shunt infection or blockage and notify the provider"}, {"id": "d", "text": "Suspect an absence seizure and time each episode of staring"}]'::jsonb, '["c"]', 'Fever, vomiting, headache, and decreased LOC in a child with a VP shunt point to shunt infection or blockage and must be reported. Treating the findings as a self-limiting viral illness delays care for a shunt complication.', false),
  ('neuro_disorders', 13, 'A 9-year-old is admitted with fever, a severe headache, a stiff neck, photophobia, and vomiting. Bacterial meningitis is suspected. Which type of isolation should the nurse initiate IMMEDIATELY?', '[{"id": "a", "text": "Droplet precautions"}, {"id": "b", "text": "Airborne precautions"}, {"id": "c", "text": "Contact precautions"}, {"id": "d", "text": "Standard precautions only"}]'::jsonb, '["a"]', 'Fever, severe headache, nuchal rigidity, and photophobia indicate meningitis, and nursing care includes droplet precautions. Standard precautions alone would not meet the isolation required for meningitis.', false),
  ('neuro_disorders', 14, 'A 6-year-old with suspected meningitis has a fever, headache, and nuchal rigidity. On reassessment, which new finding requires IMMEDIATE notification of the health care provider?', '[{"id": "a", "text": "Temperature that remains elevated"}, {"id": "b", "text": "Petechiae and purpura on the trunk"}, {"id": "c", "text": "Discomfort when the room lights are on"}, {"id": "d", "text": "One episode of vomiting after lunch"}]'::jsonb, '["b"]', 'Petechiae/purpura suggest bacterial meningococcal meningitis, which is an emergency. Fever, photophobia, and vomiting are expected signs of meningitis already being managed.', false),
  ('neuro_disorders', 15, 'While assessing a febrile 8-year-old, the nurse flexes the child''s hip and then attempts to extend the knee. The child cries out in pain and resists the movement. Which documentation by the nurse is BEST?', '[{"id": "a", "text": "Positive Brudzinski sign; meningeal irritation"}, {"id": "b", "text": "Negative Kernig sign; no meningeal irritation"}, {"id": "c", "text": "Nuchal rigidity; a seizure is about to occur"}, {"id": "d", "text": "Positive Kernig sign; meningeal irritation"}]'::jsonb, '["d"]', 'Pain or resistance when extending the knee while the hip is flexed is a positive Kernig sign, indicating meningeal irritation. Brudzinski sign is tested by flexing the neck and watching for involuntary knee flexion.', false),
  ('neuro_disorders', 16, 'A 6-year-old is admitted with fever, vomiting, and irritability. Which assessment findings should the nurse interpret as signs of meningeal irritation? Select all that apply.', '[{"id": "a", "text": "Flexing the neck causes involuntary knee flexion"}, {"id": "b", "text": "Pain and resistance when the knee is extended with the hip flexed"}, {"id": "c", "text": "A brief blank stare after which activity resumes"}, {"id": "d", "text": "Increased muscle tone with stiff movements"}, {"id": "e", "text": "Poor balance and coordination when walking"}]'::jsonb, '["a", "b"]', 'Involuntary knee flexion when the neck is flexed is a positive Brudzinski sign (a), and pain/resistance on knee extension with the hip flexed is a positive Kernig sign (b); both mean meningeal irritation. A brief blank stare is an absence seizure (c), increased tone with stiff movements is spastic CP (d), and poor balance and coordination is ataxic CP (e).', true),
  ('neuro_disorders', 17, 'The nurse observes an unlicensed assistive personnel (UAP) caring for a 5-year-old with bacterial meningitis. Which action by the UAP requires IMMEDIATE intervention by the nurse?', '[{"id": "a", "text": "Speaking softly and keeping the room dim"}, {"id": "b", "text": "Following droplet precautions at the bedside"}, {"id": "c", "text": "Lowering the head of the bed flat for comfort"}, {"id": "d", "text": "Reporting that the child is harder to wake than an hour ago"}]'::jsonb, '["c"]', 'Meningitis care includes maintaining the head of bed slightly elevated, so lowering it flat must be corrected. A quiet/dim room, droplet precautions, and reporting a change in neuro status are appropriate.', false),
  ('neuro_disorders', 18, 'A 4-year-old is admitted with bacterial meningitis. The nurse is writing the plan of care for the first 24 hours. Which interventions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Place the child in a quiet, dim room"}, {"id": "b", "text": "Keep the head of bed slightly elevated"}, {"id": "c", "text": "Give IV antibiotics as prescribed"}, {"id": "d", "text": "Monitor neuro status and ICP signs"}, {"id": "e", "text": "Keep the room brightly lit for observation"}]'::jsonb, '["a", "b", "c", "d"]', 'Meningitis nursing care includes a quiet/dim room (a), head of bed slightly elevated (b), IV antibiotics (c), and monitoring neuro status and ICP signs (d). A brightly lit room (e) contradicts the quiet/dim room and worsens photophobia.', true),
  ('neuro_disorders', 19, 'The charge nurse is reviewing four pediatric clients at the start of the shift. Which child should the nurse assess FIRST?', '[{"id": "a", "text": "A 5-year-old with suspected bacterial meningitis who has new purpura on the legs"}, {"id": "b", "text": "A 7-year-old with viral meningitis who reports a headache that is slowly improving"}, {"id": "c", "text": "A 4-year-old with spastic CP who is due for a dose of baclofen"}, {"id": "d", "text": "A 12-year-old with ADHD asking for a morning dose of methylphenidate (Ritalin)"}]'::jsonb, '["a"]', 'Petechiae/purpura with suspected bacterial meningococcal meningitis is an emergency. Viral meningitis is usually self-limiting, and the scheduled baclofen and morning stimulant doses are routine.', false),
  ('neuro_disorders', 20, 'A 3-year-old with cerebral palsy has slow, involuntary, uncontrolled movements of the arms and face while remaining awake, alert, and able to respond to the parent. The movements are not rhythmic. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Tonic-clonic seizure activity"}, {"id": "b", "text": "Dyskinetic cerebral palsy"}, {"id": "c", "text": "Spastic cerebral palsy"}, {"id": "d", "text": "Ataxic cerebral palsy"}]'::jsonb, '["b"]', 'Involuntary, uncontrolled movements describe dyskinetic CP. A tonic-clonic seizure involves stiffening followed by rhythmic jerking, spastic CP causes increased muscle tone and stiff movements, and ataxic CP causes poor balance and coordination.', false),
  ('neuro_disorders', 21, 'The parent of a 4-year-old with cerebral palsy is discussing the child''s long-term care with the nurse. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "''Speech therapy can help with his communication and swallowing.''"}, {"id": "b", "text": "''Baclofen is a muscle relaxant to help with his stiff muscles.''"}, {"id": "c", "text": "''His brain damage will keep getting worse as he gets older.''"}, {"id": "d", "text": "''Safe positioning during feeding helps lower his aspiration risk.''"}]'::jsonb, '["c"]', 'Cerebral palsy is a group of non-progressive motor disorders, so the brain damage does not keep getting worse. Speech therapy, baclofen as a muscle relaxant, and safe positioning and feeding techniques are all part of CP care.', false),
  ('neuro_disorders', 22, 'A 5-year-old with spastic cerebral palsy coughs and gags repeatedly while being fed lunch by a new staff member who is seated above the child. Which nursing concern is the PRIORITY?', '[{"id": "a", "text": "Need for assistive devices for communication"}, {"id": "b", "text": "Need for a physical therapy referral for mobility"}, {"id": "c", "text": "Need for a baclofen dose to relax stiff muscles"}, {"id": "d", "text": "Risk for aspiration during feeding"}]'::jsonb, '["d"]', 'Children with CP have an aspiration risk, so coughing and gagging during feeding make safe positioning and feeding techniques the priority. Assistive devices, therapy referrals, and baclofen are part of CP care but do not address the immediate airway risk.', false),
  ('neuro_disorders', 23, 'The nurse is helping plan interdisciplinary care for a 3-year-old with spastic cerebral palsy who has increased muscle tone and stiff movements. Which interventions should the nurse expect to include? Select all that apply.', '[{"id": "a", "text": "PT/OT/speech therapy referrals"}, {"id": "b", "text": "Methylphenidate (Ritalin) for focus"}, {"id": "c", "text": "Baclofen as a muscle relaxant"}, {"id": "d", "text": "Assistive devices for mobility"}, {"id": "e", "text": "Preparing for progressive motor loss"}]'::jsonb, '["a", "c", "d"]', 'CP care includes PT/OT/speech therapy referrals (a), baclofen as a muscle relaxant (c), and assistive devices for mobility and communication (d). Methylphenidate (b) is an ADHD stimulant, and CP is non-progressive, so progressive motor loss (e) is not expected.', true),
  ('neuro_disorders', 24, 'A newborn has low muscle tone, a flat facial profile, upward slanting eyes, and a single palmar crease. Which screening should the nurse anticipate as the PRIORITY for this newborn?', '[{"id": "a", "text": "Screening for congenital heart defects such as AV canal"}, {"id": "b", "text": "Screening for atlantoaxial instability before neck activity"}, {"id": "c", "text": "Referral for speech/behavioral therapy (ABA)"}, {"id": "d", "text": "Screening for leukemia with a blood count"}]'::jsonb, '["a"]', 'These features indicate Down syndrome (trisomy 21), and screening for congenital heart defects, with AV canal the most common, is a key focus. Atlantoaxial instability matters for neck activities later in childhood, and ABA therapy is a referral for autism spectrum disorder.', false),
  ('neuro_disorders', 25, 'The nurse is reviewing activity plans with the parent of an 8-year-old with Down syndrome (trisomy 21). Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "''We will keep up with his hearing and vision checks.''"}, {"id": "b", "text": "''He signed up for a tumbling class with headstands.''"}, {"id": "c", "text": "''His thyroid will be checked for hypothyroidism.''"}, {"id": "d", "text": "''Early intervention therapies help his development.''"}]'::jsonb, '["b"]', 'Children with Down syndrome are at risk for atlantoaxial instability, so caution is needed with neck activities such as headstands. Hearing/vision checks, thyroid screening, and early intervention therapies are appropriate.', false),
  ('neuro_disorders', 26, 'A school-age child with trisomy 21 is seen for a routine well visit. The child has mild intellectual disability and short stature. For which complications should the nurse plan screening? Select all that apply.', '[{"id": "a", "text": "Hearing and vision problems"}, {"id": "b", "text": "Increased muscle tone with stiffness"}, {"id": "c", "text": "Hypothyroidism"}, {"id": "d", "text": "Leukemia"}, {"id": "e", "text": "Atlantoaxial instability"}]'::jsonb, '["a", "c", "d", "e"]', 'Down syndrome requires watching for hearing and vision problems (a), hypothyroidism (c), leukemia risk (d), and atlantoaxial instability (e). Down syndrome causes low muscle tone (hypotonia), so increased tone with stiffness (b) is not expected; that describes spastic CP.', true),
  ('neuro_disorders', 27, 'The parent of a 2-year-old reports the child does not make eye contact, has no words, rocks and flaps the hands, and has a tantrum whenever the bedtime routine changes. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Reassure that speech delays usually resolve after age 3"}, {"id": "b", "text": "Refer the child for a stimulant medication evaluation"}, {"id": "c", "text": "Arrange early referral to speech/behavioral therapy (ABA)"}, {"id": "d", "text": "Plan screening for atlantoaxial instability"}]'::jsonb, '["c"]', 'No eye contact, absent speech, repetitive behaviors, and rigid routines suggest autism spectrum disorder, which calls for early referral to speech/behavioral therapy (ABA). ASD signs typically appear before age 3, so waiting for the child to outgrow them is inappropriate.', false),
  ('neuro_disorders', 28, 'A 6-year-old with autism spectrum disorder is admitted for IV antibiotics and becomes very distressed at the change in surroundings. Which nursing action is BEST?', '[{"id": "a", "text": "Rotate nurses each shift to build social skills"}, {"id": "b", "text": "Give long verbal explanations just before procedures"}, {"id": "c", "text": "Room the child beside the busy playroom"}, {"id": "d", "text": "Use a visual schedule with simple language"}]'::jsonb, '["d"]', 'Visual schedules and simple language, along with consistent routines and reduced sensory stimulation, support the child with ASD. Changing caregivers, long explanations given at the last moment, and a busy, stimulating room increase distress.', false),
  ('neuro_disorders', 29, 'A 4-year-old with autism spectrum disorder who is over-reactive to noise and light is being admitted for surgery tomorrow. Which actions should the nurse include in the plan of care? Select all that apply.', '[{"id": "a", "text": "Change caregivers often to reduce dependence"}, {"id": "b", "text": "Reduce sensory stimulation in the room"}, {"id": "c", "text": "Use long, detailed talks for each procedure"}, {"id": "d", "text": "Prepare the child in advance for the move to surgery"}, {"id": "e", "text": "Place the child in a shared room to encourage eye contact"}]'::jsonb, '["b", "d"]', 'Reducing sensory stimulation (b) and preparing the child in advance for changes (d) are ASD nursing care. Frequent caregiver changes (a) disrupt consistent routines, long detailed talks (c) contradict simple language, and a shared busy room (e) increases sensory stimulation.', true),
  ('neuro_disorders', 30, 'The parent of a 9-year-old taking methylphenidate (Ritalin) for ADHD gives the dose after school at about 4 PM and reports the child now has trouble falling asleep. Which response by the nurse is BEST?', '[{"id": "a", "text": "''Give the medication early in the day to avoid insomnia.''"}, {"id": "b", "text": "''Hold the medication for a few days until sleep improves.''"}, {"id": "c", "text": "''Give the dose at bedtime so it lasts through the night.''"}, {"id": "d", "text": "''Give the dose with dinner to protect his appetite.''"}]'::jsonb, '["a"]', 'ADHD stimulant medications are given early in the day to avoid insomnia. Holding the medication means stopping it abruptly, which should not be done, and a bedtime dose would worsen the insomnia.', false),
  ('neuro_disorders', 31, 'A 10-year-old has taken amphetamine (Adderall) for 6 months. At today''s visit the child''s weight is 29 kg, down from 32 kg at the start of therapy, and the parent says the child often skips lunch. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Teach the parent to give the dose at bedtime"}, {"id": "b", "text": "Report the weight loss and poor appetite"}, {"id": "c", "text": "Advise the parent to stop the medication now"}, {"id": "d", "text": "Reassure that weight loss means the drug works"}]'::jsonb, '["b"]', 'Stimulants require monitoring of appetite, weight, and growth, so a 3-kg weight loss with skipped meals should be reported. The medication should not be stopped abruptly, and bedtime dosing causes insomnia.', false),
  ('neuro_disorders', 32, 'The nurse is teaching the parent of a 7-year-old who is starting amphetamine (Adderall) for combined-type ADHD. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "''I will give his dose before school in the morning.''"}, {"id": "b", "text": "''We will track his weight and growth at each visit.''"}, {"id": "c", "text": "''Stopping his medications abruptly over summer is fine.''"}, {"id": "d", "text": "''He will have behavioral therapy along with the pills.''"}]'::jsonb, '["c"]', 'ADHD medications should not be stopped abruptly. Morning dosing, monitoring weight and growth, and combining behavioral therapy with stimulant medication are correct.', false),
  ('neuro_disorders', 33, 'An 11-year-old is starting methylphenidate (Ritalin) for inattentive-type ADHD. Which instructions should the nurse include in the teaching plan for the family? Select all that apply.', '[{"id": "a", "text": "Monitor appetite, weight, and growth"}, {"id": "b", "text": "Watch for cardiovascular effects"}, {"id": "c", "text": "Give the medication early in the day"}, {"id": "d", "text": "Give the dose at bedtime to aid sleep"}, {"id": "e", "text": "Stop the drug abruptly if appetite drops"}]'::jsonb, '["a", "b", "c"]', 'Teaching includes monitoring appetite, weight, and growth (a), watching for cardiovascular effects (b), and giving the medication early in the day (c). Bedtime dosing (d) causes insomnia, and the drug should not be stopped abruptly (e).', true),
  ('neuro_disorders', 34, 'An 8-year-old has stomach aches and headaches on school mornings, clings to the parent at drop-off, refuses to go to school, and worries excessively. The physical examination is normal. Which treatment plan does the nurse MOST likely anticipate?', '[{"id": "a", "text": "Stimulant medication such as methylphenidate"}, {"id": "b", "text": "Baclofen with physical and occupational therapy"}, {"id": "c", "text": "Nutritional rehabilitation with family therapy"}, {"id": "d", "text": "CBT with an SSRI such as fluoxetine"}]'::jsonb, '["d"]', 'Stomach aches, headaches, clinginess, school refusal, and excessive worry suggest anxiety, which is treated with CBT plus SSRIs (fluoxetine). Stimulants treat ADHD and baclofen treats spasticity in CP.', false),
  ('neuro_disorders', 35, 'A 15-year-old has become irritable and withdrawn, grades have dropped, and the teen is sleeping more and eating less. The parent mentions the teen recently gave away a favorite gaming console. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Ask the teen directly about suicidal thoughts"}, {"id": "b", "text": "Avoid the topic of suicide so it is not suggested"}, {"id": "c", "text": "Suggest a school club to reduce the withdrawal"}, {"id": "d", "text": "Request a referral for behavioral therapy (ABA)"}]'::jsonb, '["a"]', 'Irritability, withdrawal, poor school performance, and sleep and appetite changes suggest depression, and giving away belongings is a red flag, so the nurse must always ask directly about suicidal thoughts. Avoiding the topic leaves the risk unassessed; ABA is a therapy for autism spectrum disorder.', false),
  ('neuro_disorders', 36, 'A 16-year-old is being treated for depression. The nurse reviews the teen''s recent behaviors reported by the family. Which behaviors are red flags for suicide that require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Giving away belongings"}, {"id": "b", "text": "Stomach aches before school"}, {"id": "c", "text": "Talking about death"}, {"id": "d", "text": "Clinginess with a parent"}, {"id": "e", "text": "Saying goodbye to friends"}]'::jsonb, '["a", "c", "e"]', 'Giving away belongings (a), talking about death (c), and saying goodbye (e) are suicide red flags. Stomach aches (b) and clinginess (d) are signs of childhood anxiety, not listed suicide red flags.', true),
  ('neuro_disorders', 37, 'A 14-year-old with depression started fluoxetine 1 week ago. During a follow-up phone call, the parent reports several changes. Which finding requires IMMEDIATE follow-up by the nurse?', '[{"id": "a", "text": "The teen still has irregular sleep patterns"}, {"id": "b", "text": "The teen reports new thoughts of suicide"}, {"id": "c", "text": "The teen''s grades have not improved yet"}, {"id": "d", "text": "The teen remains more irritable than usual"}]'::jsonb, '["b"]', 'When starting an SSRI, adolescents must be monitored closely for increased suicidal ideation (black box warning), so new thoughts of suicide require immediate follow-up. Sleep changes, poor school performance, and irritability are depression signs but not immediate safety threats.', false),
  ('neuro_disorders', 38, 'A charge nurse overhears a new nurse discussing care of a 15-year-old admitted for depression who began an SSRI yesterday. Which statement by the new nurse requires follow-up by the charge nurse?', '[{"id": "a", "text": "''I will ask him directly about suicidal thoughts.''"}, {"id": "b", "text": "''I will make sure his environment is kept safe.''"}, {"id": "c", "text": "''Once SSRIs are started, suicidal ideation is less of a risk.''"}, {"id": "d", "text": "''I will report any talk about death or goodbyes.''"}]'::jsonb, '["c"]', 'Starting an SSRI requires close monitoring for increased suicidal ideation in adolescents, so the risk is not lower at this point. Asking directly, ensuring a safe environment, and reporting talk of death or goodbyes are correct.', false),
  ('neuro_disorders', 39, 'A 15-year-old with a BMI significantly below normal is admitted with bradycardia, hypotension, lanugo, and amenorrhea, and says she still sees herself as fat. Which treatment goal should the nurse expect to address FIRST?', '[{"id": "a", "text": "Begin CBT for the distorted body image"}, {"id": "b", "text": "Start family therapy to improve home meals"}, {"id": "c", "text": "Begin an SSRI to reduce her fear of weight gain"}, {"id": "d", "text": "Medical stabilization"}]'::jsonb, '["d"]', 'These findings indicate anorexia nervosa with medical instability, and treatment begins with medical stabilization first. CBT, family therapy, and SSRIs (which have limited efficacy) follow stabilization.', false),
  ('neuro_disorders', 40, 'Nutrition was restarted 2 days ago for a 16-year-old hospitalized with anorexia nervosa. The nurse is monitoring for refeeding syndrome. Which finding should the nurse report IMMEDIATELY?', '[{"id": "a", "text": "Dangerous decrease in phosphate"}, {"id": "b", "text": "Persistent lanugo on the back and arms"}, {"id": "c", "text": "Continued amenorrhea since admission"}, {"id": "d", "text": "Ongoing cold intolerance and dry skin"}]'::jsonb, '["a"]', 'Refeeding syndrome is a dangerous drop in phosphate when nutrition is restarted too quickly, so a decreasing phosphate level requires immediate reporting. Lanugo, amenorrhea, cold intolerance, and dry skin are existing signs of anorexia that resolve slowly.', false),
  ('neuro_disorders', 41, 'A 14-year-old who severely restricts food intake and has an intense fear of weight gain has a BMI significantly below normal. Which findings should the nurse expect on assessment? Select all that apply.', '[{"id": "a", "text": "Lanugo (fine downy hair)"}, {"id": "b", "text": "Amenorrhea"}, {"id": "c", "text": "Calluses on knuckles (Russell''s sign)"}, {"id": "d", "text": "Bradycardia and hypotension"}, {"id": "e", "text": "Cold intolerance and dry skin"}]'::jsonb, '["a", "b", "d", "e"]', 'Anorexia nervosa causes lanugo (a), amenorrhea (b), bradycardia and hypotension (d), and cold intolerance with dry skin (e). Russell''s sign (c), calluses on the knuckles from self-induced vomiting, is a sign of bulimia nervosa.', true),
  ('neuro_disorders', 42, 'A 16-year-old of normal weight has calluses on the knuckles, dental erosion, parotid gland enlargement, and a hoarse voice. Which laboratory value is the PRIORITY for the nurse to monitor?', '[{"id": "a", "text": "Phosphate, for refeeding syndrome"}, {"id": "b", "text": "Sodium, for hyponatremia"}, {"id": "c", "text": "Potassium, for hypokalemia"}, {"id": "d", "text": "Thyroid level, for hypothyroidism"}]'::jsonb, '["c"]', 'These findings indicate bulimia nervosa, in which hypokalemia is the most dangerous imbalance because it causes arrhythmias. Phosphate monitoring is the focus of refeeding syndrome when nutrition is restarted in anorexia.', false),
  ('neuro_disorders', 43, 'A 17-year-old of normal weight reports eating large amounts of food in a short time while feeling out of control, followed by self-induced vomiting and laxative use. Which treatment plan does the nurse anticipate as MOST effective?', '[{"id": "a", "text": "Methylphenidate with behavioral therapy"}, {"id": "b", "text": "Fluoxetine with CBT and nutritional counseling"}, {"id": "c", "text": "Baclofen with physical therapy"}, {"id": "d", "text": "Valproic acid with nutritional counseling"}]'::jsonb, '["b"]', 'Binge eating with compensatory purging indicates bulimia nervosa, treated with CBT (most effective), fluoxetine, and nutritional counseling. Methylphenidate treats ADHD and valproic acid is a seizure maintenance medication.', false),
  ('neuro_disorders', 44, 'A 15-year-old hospitalized for anorexia nervosa pushes away her dinner tray and says she is not hungry. Which approach by the nurse is BEST?', '[{"id": "a", "text": "Insist she stay at the table until every bite is eaten"}, {"id": "b", "text": "Remove a privilege each time she refuses part of a meal"}, {"id": "c", "text": "Point out in a mirror how underweight her body looks"}, {"id": "d", "text": "Avoid power struggles around food"}]'::jsonb, '["d"]', 'Building a therapeutic relationship and avoiding power struggles around food is the key nursing approach. Insisting, punishing, and confronting her body image all create power struggles.', false),
  ('neuro_disorders', 45, 'A 17-year-old has a normal body weight but admits to episodes of eating large amounts quickly while feeling out of control. Which additional findings support bulimia nervosa rather than anorexia nervosa? Select all that apply.', '[{"id": "a", "text": "Calluses on knuckles (Russell''s sign)"}, {"id": "b", "text": "Lanugo on the arms and back"}, {"id": "c", "text": "Amenorrhea with bradycardia"}, {"id": "d", "text": "Parotid gland enlargement"}, {"id": "e", "text": "Distorted body image while severely underweight"}]'::jsonb, '["a", "d"]', 'Russell''s sign (a) and parotid gland enlargement (d) are signs of bulimia. Lanugo (b), amenorrhea with bradycardia (c), and a distorted body image while severely underweight (e) point to anorexia nervosa.', true),
  ('neuro_disorders', 46, 'During a 6-year-old''s tonic-clonic seizure, the nurse observes the actions of an unlicensed assistive personnel (UAP). Which actions by the UAP require IMMEDIATE intervention? Select all that apply.', '[{"id": "a", "text": "Turns the child onto the side"}, {"id": "b", "text": "Tries to restrain the child during the jerking"}, {"id": "c", "text": "Moves the bedside table away from the child"}, {"id": "d", "text": "Places a washcloth in the mouth of the child"}, {"id": "e", "text": "Stays with the child and calls for help"}]'::jsonb, '["b", "d"]', 'The child must NOT be restrained (b) and nothing is put in the mouth (d), so both require intervention. Side-lying positioning (a), clearing hazards (c), and staying with the child while calling for help (e) are correct.', true),
  ('neuro_disorders', 47, 'The parent of a 2-month-old whose head circumference has increased rapidly over 3 weeks and whose fontanel is bulging asks why the baby''s head is growing so fast. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "''Inflammation of the meninges is making his brain swell.''"}, {"id": "b", "text": "''Excess CSF is building up in the ventricles of his brain.''"}, {"id": "c", "text": "''An extra chromosome 21 is changing how his skull grows.''"}, {"id": "d", "text": "''Brain damage around birth is causing his skull to enlarge.''"}]'::jsonb, '["b"]', 'A rapidly increasing head circumference with a bulging fontanel indicates hydrocephalus, in which excess CSF accumulates in the brain ventricles and increases ICP. Inflammation of the meninges is meningitis, and brain damage around birth describes cerebral palsy.', false),
  ('neuro_disorders', 48, 'The parent of a 6-year-old with viral meningitis is frightened after hearing that a child on the unit with bacterial meningitis was moved to intensive care. Which response by the nurse is BEST?', '[{"id": "a", "text": "''Viral meningitis is usually self-limiting; bacterial is more serious.''"}, {"id": "b", "text": "''Viral and bacterial meningitis are equally serious emergencies.''"}, {"id": "c", "text": "''Viral meningitis means no isolation or neuro checks are needed.''"}, {"id": "d", "text": "''Meningitis only becomes serious once a stiff neck develops.''"}]'::jsonb, '["a"]', 'Bacterial meningitis is serious while viral meningitis is usually self-limiting. Meningitis care still includes droplet precautions and neuro monitoring, and a stiff neck is a common sign rather than a marker of severity.', false),
  ('neuro_disorders', 49, 'The nurse is preparing discharge teaching for the parent of a 5-year-old who had a VP shunt revised. Which findings should the parent be taught to report as possible shunt infection or blockage? Select all that apply.', '[{"id": "a", "text": "New fever"}, {"id": "b", "text": "Repeated vomiting"}, {"id": "c", "text": "Stomach aches on school mornings"}, {"id": "d", "text": "Headache"}, {"id": "e", "text": "Decreased LOC"}]'::jsonb, '["a", "b", "d", "e"]', 'Fever (a), vomiting (b), headache (d), and decreased LOC (e) are signs of shunt infection or blockage. Stomach aches on school mornings (c) suggest anxiety with school refusal, not a shunt complication.', true),
  ('neuro_disorders', 50, 'A 4-year-old with cerebral palsy walks with an unsteady gait, has poor balance and coordination, and falls often. Which type of cerebral palsy is the nurse MOST likely to document?', '[{"id": "a", "text": "Spastic"}, {"id": "b", "text": "Dyskinetic"}, {"id": "c", "text": "Absence"}, {"id": "d", "text": "Ataxic"}]'::jsonb, '["d"]', 'Poor balance and coordination describe ataxic CP. Spastic CP causes increased muscle tone and stiff movements, dyskinetic CP causes involuntary movements, and absence is a seizure type, not a CP type.', false),
  ('diabetes', 1, 'A 9-year-old with type 1 diabetes comes off the soccer field shaky, sweaty, pale, and irritable. The fingerstick glucose is 62 mg/dL, and the child is alert and able to swallow. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Give 15 g of fast-acting carbohydrates"}, {"id": "b", "text": "Give glucagon injection IM or IN"}, {"id": "c", "text": "Check urine/blood ketones"}, {"id": "d", "text": "Give a dose of her rapid-acting insulin now"}]'::jsonb, '["a"]', 'A glucose below 70 mg/dL with shakiness, diaphoresis, pallor, and irritability is hypoglycemia, so a child who can swallow gets 15 g of fast-acting carbohydrates. Glucagon is for a child who is unconscious or cannot swallow; ketones are checked for BG above 240.', false),
  ('diabetes', 2, 'A school nurse is called to see a 10-year-old with type 1 diabetes whose glucose is 55 mg/dL. Which findings should the nurse expect? Select all that apply.', '[{"id": "a", "text": "Kussmaul respirations"}, {"id": "b", "text": "Shakiness and diaphoresis"}, {"id": "c", "text": "Pallor"}, {"id": "d", "text": "Fruity/acetone breath"}, {"id": "e", "text": "Irritability and difficulty concentrating"}]'::jsonb, '["b", "c", "e"]', 'Correct: (b) shakiness and diaphoresis, (c) pallor, and (e) irritability and difficulty concentrating are signs of hypoglycemia (<70 mg/dL). Wrong: (a) Kussmaul respirations and (d) fruity/acetone breath are signs of DKA from ketones.', true),
  ('diabetes', 3, 'Fifteen minutes after drinking 4 oz of juice for a glucose of 58 mg/dL, an 11-year-old''s recheck is 64 mg/dL. The child is alert and swallowing. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Give glucagon injection IM or IN"}, {"id": "b", "text": "Repeat 15 g of fast-acting carbohydrates"}, {"id": "c", "text": "Wait 15 more minutes, then recheck"}, {"id": "d", "text": "Give a protein snack and recheck at dinner"}]'::jsonb, '["b"]', 'In the 15–15 rule, if the recheck is still below 70 mg/dL, the 15 g of fast-acting carbohydrate is repeated. Waiting again without treating delays correction, and glucagon is for a child who is unconscious or cannot swallow.', false),
  ('diabetes', 4, 'A 12-year-old with type 1 diabetes is found unresponsive in the school bathroom; a glucose meter reads 38 mg/dL. Which action should the school nurse take FIRST?', '[{"id": "a", "text": "Place glucose tablets in the cheek"}, {"id": "b", "text": "Pour 4 oz of juice into the mouth"}, {"id": "c", "text": "Give glucagon injection IM or IN"}, {"id": "d", "text": "Give the child''s rapid-acting insulin"}]'::jsonb, '["c"]', 'A child who is unconscious or cannot swallow receives glucagon IM or IN (nasal), and 911 is called if unresponsive. Oral juice or tablets require the child to swallow, and insulin would lower the glucose further.', false),
  ('diabetes', 5, 'A 10-year-old arrives in the emergency department with vomiting, abdominal pain, deep and rapid labored breathing, and fruity breath. Glucose is 480 mg/dL with ketones in the urine. Which order should the nurse implement FIRST?', '[{"id": "a", "text": "Subcutaneous regular insulin"}, {"id": "b", "text": "IV regular insulin drip"}, {"id": "c", "text": "IV potassium replacement"}, {"id": "d", "text": "IV normal saline bolus"}]'::jsonb, '["d"]', 'These findings indicate DKA. Treatment begins with an IV normal saline bolus for fluid resuscitation, then an IV regular insulin drip, then potassium replacement. Insulin is NOT given subcut first.', false),
  ('diabetes', 6, 'A nurse is reviewing the admission orders for a 9-year-old in DKA. Which orders should the nurse expect as part of the treatment plan? Select all that apply.', '[{"id": "a", "text": "IV normal saline for fluid resuscitation"}, {"id": "b", "text": "IV regular insulin drip"}, {"id": "c", "text": "Subcutaneous insulin glargine as the first step"}, {"id": "d", "text": "Potassium replacement"}, {"id": "e", "text": "Oral juice every 15 minutes"}]'::jsonb, '["a", "b", "d"]', 'Correct: (a) IV normal saline (fluid resuscitation), (b) an IV regular insulin drip, and (d) potassium replacement because K⁺ drops when insulin is given. Wrong: (c) insulin is NOT given subcut first; (e) fast-acting carbohydrates treat hypoglycemia, not DKA.', true),
  ('diabetes', 7, 'Two hours after an IV regular insulin drip is started for a 13-year-old in DKA, the glucose is falling as expected. Which laboratory value should the nurse monitor MOST closely now?', '[{"id": "a", "text": "Serum potassium"}, {"id": "b", "text": "HbA1c"}, {"id": "c", "text": "Urine ketones only"}, {"id": "d", "text": "Fasting glucose"}]'::jsonb, '["a"]', 'Potassium is monitored closely because K⁺ drops when insulin is given; hypokalemia is a DKA treatment complication. HbA1c and fasting glucose are diagnostic criteria, not treatment monitoring.', false),
  ('diabetes', 8, 'A 14-year-old with glucose of 520 mg/dL has deep, rapid, labored breathing. The parent asks why the teen is breathing that way. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "The low glucose is causing the panting"}, {"id": "b", "text": "The body is compensating for acidosis"}, {"id": "c", "text": "The lungs are reacting to dehydration"}, {"id": "d", "text": "Anxiety about being admitted is the cause"}]'::jsonb, '["b"]', 'Kussmaul respirations are deep, rapid, labored breathing that compensates for acidosis from ketones in DKA. The glucose is high, not low.', false),
  ('diabetes', 9, 'An 11-year-old is brought to the clinic with 3 days of vomiting. Which findings support DKA and require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Pallor and diaphoresis"}, {"id": "b", "text": "Kussmaul respirations"}, {"id": "c", "text": "Fruity/acetone breath"}, {"id": "d", "text": "Glucose of 62 mg/dL"}, {"id": "e", "text": "Confusion and lethargy"}]'::jsonb, '["b", "c", "e"]', 'Correct: (b) Kussmaul respirations, (c) fruity/acetone breath from ketones, and (e) confusion and lethargy, which can progress to coma, are DKA signs. Wrong: (a) pallor and diaphoresis and (d) a glucose below 70 mg/dL indicate hypoglycemia.', true),
  ('diabetes', 10, 'The parent of a 7-year-old prepares to draw up the bedtime glargine and the dinner lispro in the same syringe "to save a shot." Which response by the nurse is BEST?', '[{"id": "a", "text": "Draw up the glargine first, then the lispro"}, {"id": "b", "text": "Draw up the lispro first, then the glargine"}, {"id": "c", "text": "Do NOT mix glargine with other insulins"}, {"id": "d", "text": "Mixing is fine if given at the same time daily"}]'::jsonb, '["c"]', 'Glargine (Lantus) is NOT mixed with other insulins, so neither drawing order is acceptable. Giving it at the same time daily is correct, but it does not make mixing safe.', false),
  ('diabetes', 11, 'The parent of a 12-year-old who takes insulin glargine at bedtime asks when the low blood glucose peak from this insulin will occur. Which response by the nurse is BEST?', '[{"id": "a", "text": "Its peak is 30–90 minutes after the bedtime injection"}, {"id": "b", "text": "Its peak is 2–4 hours after the injection"}, {"id": "c", "text": "Its peak is 4–12 hours after the injection"}, {"id": "d", "text": "Glargine has no peak, so it has no hypoglycemic spike"}]'::jsonb, '["d"]', 'Glargine (Lantus) is long-acting with no peak, so it produces no hypoglycemic spike. A 30–90-minute peak is rapid-acting, 2–4 hours is regular, and 4–12 hours is NPH.', false),
  ('diabetes', 12, 'A 10-year-old receives insulin lispro at 1200 with lunch. During which time frame should the nurse watch MOST closely for hypoglycemia from this dose?', '[{"id": "a", "text": "1230 to 1330"}, {"id": "b", "text": "1400 to 1600"}, {"id": "c", "text": "1600 until midnight"}, {"id": "d", "text": "1300 to 1400"}]'::jsonb, '["a"]', 'Rapid-acting lispro (Humalog) has an onset under 15 minutes and peaks at 30–90 minutes, so the peak is 1230–1330. 1400–1600 matches the 2–4-hour peak of regular insulin, and 1600–2400 matches NPH''s 4–12-hour peak.', false),
  ('diabetes', 13, 'A 13-year-old receives regular insulin (Humulin R) at 0700. At which time is the teen''s hypoglycemia risk from this dose HIGHEST?', '[{"id": "a", "text": "0730"}, {"id": "b", "text": "1000"}, {"id": "c", "text": "0800"}, {"id": "d", "text": "1600"}]'::jsonb, '["b"]', 'Regular insulin peaks 2–4 hours after injection, so 0900–1100 is the peak window and 1000 falls within it. 0730 and 0800 are within onset (30–60 min), and 1600 is past the 5–8-hour duration.', false),
  ('diabetes', 14, 'A nurse is reviewing an insulin action chart with the parents of a child newly diagnosed with type 1 diabetes. Which statements by the parents are correct? Select all that apply.', '[{"id": "a", "text": "Lispro onset is <15 min"}, {"id": "b", "text": "Glargine has a peak at 4–12 hours"}, {"id": "c", "text": "Lispro lasts 20–24 hours"}, {"id": "d", "text": "Glargine has no peak"}, {"id": "e", "text": "Regular insulin peaks at 2–4 hours"}]'::jsonb, '["a", "d", "e"]', 'Correct: (a) rapid-acting lispro has an onset under 15 minutes; (e) regular insulin peaks at 2–4 hours; (d) glargine has no peak. Wrong: (b) a 4–12-hour peak belongs to NPH; (c) lispro lasts 3–5 hours, while 20–24+ hours is long-acting glargine.', true),
  ('diabetes', 15, 'A 15-year-old taking insulin lispro with meals tells the nurse about a usual routine. Which statement by the teen indicates a need for further teaching?', '[{"id": "a", "text": "I take my lispro right when my meal is ready"}, {"id": "b", "text": "I take my lispro, then eat about an hour later"}, {"id": "c", "text": "I watch for lows 30–90 minutes after lispro"}, {"id": "d", "text": "I expect my lispro to wear off in about 3–5 hours"}]'::jsonb, '["b"]', 'Lispro has an onset under 15 minutes and peaks at 30–90 minutes, so eating an hour later risks hypoglycemia. Giving it with the meal, watching for lows in the 30–90-minute peak, and expecting a 3–5-hour duration are correct.', false),
  ('diabetes', 16, 'The parent of a 6-year-old with type 1 diabetes calls: the child has a stomach virus, is eating very little, and is keeping fluids down. The parent says, "I''ll skip his insulin today since he''s barely eating." Which response is BEST?', '[{"id": "a", "text": "Skip it and give insulin once he eats again"}, {"id": "b", "text": "Give half the insulin and skip the bedtime dose"}, {"id": "c", "text": "Never skip insulin; illness increases BG"}, {"id": "d", "text": "Skip it and check his glucose once at bedtime"}]'::jsonb, '["c"]', 'Insulin is never skipped even when the child is not eating, because illness increases BG. Blood glucose is checked every 3–4 hours, not once a day.', false),
  ('diabetes', 17, 'The parent of a 9-year-old with type 1 diabetes reviews sick day rules before flu season. Which statements by the parent indicate understanding? Select all that apply.', '[{"id": "a", "text": "I''ll check her blood glucose every 3–4 hours"}, {"id": "b", "text": "I''ll hold her insulin if she is not eating"}, {"id": "c", "text": "I''ll check ketones if her BG is over 240"}, {"id": "d", "text": "I''ll keep her hydrated with fluids"}, {"id": "e", "text": "I''ll give her insulin even if she is not eating"}]'::jsonb, '["a", "c", "d", "e"]', 'Correct: (a) blood glucose every 3–4 hours, (c) ketones if BG is above 240 mg/dL, (d) stay hydrated with fluids, and (e) never skip insulin even if not eating. Wrong: (b) holding insulin contradicts the rule because illness increases BG.', true),
  ('diabetes', 18, 'A 12-year-old with type 1 diabetes has a fever and cold. The parent reports a blood glucose of 262 mg/dL; the child is drinking well and not vomiting. Which action should the nurse instruct the parent to take NEXT?', '[{"id": "a", "text": "Give glucagon IM or IN"}, {"id": "b", "text": "Hold the next insulin dose"}, {"id": "c", "text": "Give 15 g of carbohydrates"}, {"id": "d", "text": "Check urine/blood ketones"}]'::jsonb, '["d"]', 'On sick days, ketones are checked if BG is above 240 mg/dL. Insulin is never skipped, and glucagon and 15 g of carbohydrates treat hypoglycemia, not a high BG.', false),
  ('diabetes', 19, 'A 10-year-old with type 1 diabetes and gastroenteritis has vomited four times in 3 hours and cannot keep sips of fluid down. The glucose is 230 mg/dL. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "Call the provider or go to the ER now"}, {"id": "b", "text": "Skip insulin until vomiting stops"}, {"id": "c", "text": "Recheck the glucose in 3–4 hours"}, {"id": "d", "text": "Give 4 oz of juice every 15 minutes at home"}]'::jsonb, '["a"]', 'If the child is vomiting and cannot keep fluids down, the parent calls the provider or goes to the ER. Insulin is never skipped, and simply rechecking in 3–4 hours delays care.', false),
  ('diabetes', 20, 'The parent of an 8-year-old with type 1 diabetes asks which situations need urgent outside help rather than home care. Which situations should the nurse identify? Select all that apply.', '[{"id": "a", "text": "Vomiting and cannot keep fluids down"}, {"id": "b", "text": "Glucose 250 mg/dL, drinking well, ketones being checked"}, {"id": "c", "text": "Unresponsive with a glucose of 40 mg/dL"}, {"id": "d", "text": "Glucose 65 mg/dL, alert and able to drink juice"}, {"id": "e", "text": "Mild cold with glucose 180 mg/dL, eating well"}]'::jsonb, '["a", "c"]', 'Correct: (a) vomiting with inability to keep fluids down requires calling the provider or going to the ER; (c) an unresponsive child receives glucagon and 911 is called. Wrong: (b) a BG above 240 in a child drinking well is managed with ketone checks; (d) an alert child with a low glucose is treated with 15 g of carbohydrates; (e) a mild illness while eating is managed with sick day rules.', true),
  ('diabetes', 21, 'A provider is evaluating a 9-year-old for diabetes. Which single test result meets a diagnostic criterion for diabetes?', '[{"id": "a", "text": "Fasting glucose of 118 mg/dL"}, {"id": "b", "text": "HbA1c of 6.5%"}, {"id": "c", "text": "Random glucose of 190 mg/dL with polyuria"}, {"id": "d", "text": "2-hour OGTT of 180 mg/dL"}]'::jsonb, '["b"]', 'An HbA1c ≥ 6.5% meets a criterion. Fasting glucose must be ≥ 126 mg/dL, random glucose ≥ 200 mg/dL with symptoms, and 2-hour OGTT ≥ 200 mg/dL, so the other values fall just short.', false),
  ('diabetes', 22, 'A nurse reviews test results for several children being evaluated for diabetes. Which results meet a diagnostic criterion? Select all that apply.', '[{"id": "a", "text": "Fasting glucose 126 mg/dL"}, {"id": "b", "text": "Fasting glucose 130 mg/dL"}, {"id": "c", "text": "Random glucose 210 mg/dL with polydipsia"}, {"id": "d", "text": "HbA1c 6.2%"}, {"id": "e", "text": "2-hour OGTT 205 mg/dL"}]'::jsonb, '["a", "b", "c", "e"]', 'Correct: (a) and (b) fasting glucose ≥ 126 mg/dL (126 meets the cutoff); (c) random glucose ≥ 200 mg/dL with symptoms; (e) 2-hour OGTT ≥ 200 mg/dL. Wrong: (d) 6.2% is below the HbA1c cutoff of ≥ 6.5%.', true),
  ('diabetes', 23, 'A previously toilet-trained 7-year-old has started wetting the bed, is always asking for drinks, eats more than usual, and has lost 4 lb in a month. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Reassure that bedwetting is common"}, {"id": "b", "text": "Limit fluids after dinner"}, {"id": "c", "text": "Check the child''s blood glucose"}, {"id": "d", "text": "Increase calories for weight loss"}]'::jsonb, '["c"]', 'Polyuria (frequent urination), polydipsia (excessive thirst), and polyphagia (increased hunger) with weight loss are the 3 Ps of hyperglycemia, so blood glucose is checked. Limiting fluids or adding calories misses the cause.', false),
  ('diabetes', 24, 'The parent of a 10-year-old describes changes over the past month. Which findings suggest hyperglycemia and should be reported to the provider? Select all that apply.', '[{"id": "a", "text": "Frequent urination, including at night"}, {"id": "b", "text": "Excessive thirst"}, {"id": "c", "text": "Shakiness and sweating before lunch"}, {"id": "d", "text": "Increased hunger with weight loss"}, {"id": "e", "text": "Fatigue and blurry vision"}]'::jsonb, '["a", "b", "d", "e"]', 'Correct: (a) polyuria, (b) polydipsia, (d) polyphagia with weight loss, and (e) fatigue and blurry vision are hyperglycemia findings. Wrong: (c) shakiness and sweating (diaphoresis) are hypoglycemia signs.', true),
  ('diabetes', 25, 'The parent of a 9-year-old newly diagnosed with type 1 diabetes asks, "Can she take metformin pills like her uncle instead of shots?" Which response by the nurse is BEST?', '[{"id": "a", "text": "Metformin works once her diet is well controlled"}, {"id": "b", "text": "Metformin can replace shots after 1 year"}, {"id": "c", "text": "Pills work if she exercises every day"}, {"id": "d", "text": "Type 1 requires insulin; no oral meds alone"}]'::jsonb, '["d"]', 'Type 1 is autoimmune destruction of beta cells with absolute insulin deficiency, so insulin is required and oral meds alone are not used. Metformin with diet/exercise is a type 2 treatment.', false),
  ('diabetes', 26, 'A nurse is comparing type 1 and type 2 diabetes for the parents in a pediatric diabetes class. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "Type 1 involves autoimmune destruction of beta cells"}, {"id": "b", "text": "Type 2 involves insulin resistance"}, {"id": "c", "text": "Type 1 can be managed with oral meds alone"}, {"id": "d", "text": "Type 2 is associated with obesity and a sedentary lifestyle"}, {"id": "e", "text": "Type 2 always involves absolute insulin deficiency"}]'::jsonb, '["a", "b", "d"]', 'Correct: (a) type 1 is autoimmune destruction of pancreatic beta cells; (b) type 2 involves insulin resistance with relative insulin deficiency; (d) type 2 is associated with obesity and a sedentary lifestyle. Wrong: (c) type 1 requires insulin, with no oral meds alone; (e) absolute insulin deficiency describes type 1.', true),
  ('diabetes', 27, 'A 15-year-old with type 2 diabetes reviews the treatment plan with the nurse. Which statement by the teen indicates understanding?', '[{"id": "a", "text": "I have absolute insulin deficiency like type 1"}, {"id": "b", "text": "Diet, exercise, and metformin are my main treatment"}, {"id": "c", "text": "Insulin is never part of type 2 treatment"}, {"id": "d", "text": "My pancreatic beta cells were destroyed by autoimmunity"}]'::jsonb, '["b"]', 'Type 2 treatment is diet/exercise and metformin, with insulin added as needed (±). Absolute insulin deficiency and autoimmune beta-cell destruction describe type 1.', false),
  ('diabetes', 28, 'A school nurse is reviewing the health records of four students. Which student has the MOST risk factors for type 2 diabetes?', '[{"id": "a", "text": "A 12-year-old with a recent viral cold and a high fever"}, {"id": "b", "text": "A 13-year-old runner with a normal weight"}, {"id": "c", "text": "A 14-year-old with obesity and a sedentary lifestyle"}, {"id": "d", "text": "A 15-year-old with seasonal allergies"}]'::jsonb, '["c"]', 'Type 2 diabetes in children is associated with obesity and a sedentary lifestyle; the other students have neither risk factor.', false),
  ('diabetes', 29, 'A 12-year-old with type 1 diabetes is going to a 2-hour basketball practice. Which statement by the child indicates understanding?', '[{"id": "a", "text": "Exercise raises my BG, so I take extra insulin first"}, {"id": "b", "text": "Exercise has no effect on BG with glargine"}, {"id": "c", "text": "I skip my snack so my BG stays lower"}, {"id": "d", "text": "Exercise lowers my BG, so I watch for hypoglycemia"}]'::jsonb, '["d"]', 'Exercise lowers BG, so the child watches for hypoglycemia. Taking extra insulin or skipping a snack increases the risk of a low, and glargine does not prevent exercise from lowering BG.', false),
  ('diabetes', 30, 'A nurse is teaching a 13-year-old with type 1 diabetes about safety during sports. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Take an extra insulin dose before practice"}, {"id": "b", "text": "Watch for hypoglycemia during and after exercise"}, {"id": "c", "text": "Skip the pre-practice snack to stay light"}, {"id": "d", "text": "Keep glucose tablets in your sports bag"}, {"id": "e", "text": "Treat a low with diet soda for no calories"}]'::jsonb, '["b", "d"]', 'Correct: (b) exercise lowers BG, so the teen watches for hypoglycemia; (d) glucose tablets are a fast-acting carbohydrate for treating a low. Wrong: (a) extra insulin and (c) skipping a snack further lower BG; (e) regular soda, not diet soda, is the fast-acting carbohydrate.', true),
  ('diabetes', 31, 'While giving an injection, a nurse notes a lumpy, hard area of skin at the abdominal site a 10-year-old''s parent uses for every glargine dose. Which action is BEST?', '[{"id": "a", "text": "Teach the parent to rotate injection sites"}, {"id": "b", "text": "Massage the lumpy area well before each injection"}, {"id": "c", "text": "Switch to mixing glargine with lispro"}, {"id": "d", "text": "Give the glargine only at bedtime"}]'::jsonb, '["a"]', 'Lumpy/hard skin is lipodystrophy, which is prevented by rotating injection sites. Glargine is never mixed with other insulins, and timing does not affect site damage.', false),
  ('diabetes', 32, 'The parent of a 9-year-old starting insulin glargine is taught about this insulin. Which statements by the parent indicate understanding? Select all that apply.', '[{"id": "a", "text": "I''ll give it at the same time every day"}, {"id": "b", "text": "It has a peak at 30–90 minutes"}, {"id": "c", "text": "I won''t mix it with her other insulin"}, {"id": "d", "text": "I''ll rotate where I give the injection"}, {"id": "e", "text": "I''ll give it in one spot to avoid bruises"}]'::jsonb, '["a", "c", "d"]', 'Correct: (a) glargine is given at bedtime or the same time daily; (c) it is not mixed with other insulins; (d) sites are rotated to prevent lipodystrophy. Wrong: (b) glargine has no peak (30–90 minutes is rapid-acting); (e) using one spot causes lipodystrophy.', true),
  ('diabetes', 33, 'A nurse receives reports on four children with type 1 diabetes. Which child should the nurse see FIRST?', '[{"id": "a", "text": "A 12-year-old with a glucose of 190 mg/dL just after lunch"}, {"id": "b", "text": "A 10-year-old with Kussmaul respirations who is lethargic"}, {"id": "c", "text": "A 13-year-old needing glargine teaching before discharge"}, {"id": "d", "text": "A 9-year-old asking about basketball and hypoglycemia"}]'::jsonb, '["b"]', 'Kussmaul respirations with lethargy indicate DKA, a life-threatening complication that can progress to coma. The others are stable teaching or monitoring needs.', false),
  ('diabetes', 34, 'In the emergency department, a nurse prepares to give subcutaneous regular insulin to a dehydrated 11-year-old in DKA before the IV line is placed. Which response by the charge nurse is BEST?', '[{"id": "a", "text": "Give it now, then start the IV fluids"}, {"id": "b", "text": "Give glargine instead of regular insulin"}, {"id": "c", "text": "Start the IV fluid bolus before any insulin"}, {"id": "d", "text": "Give it in the thigh to speed up the absorption"}]'::jsonb, '["c"]', 'In DKA, insulin is NOT given subcut first; an IV fluid bolus treats hypovolemia first, followed by an IV insulin drip. Changing the insulin type or site does not correct the error.', false),
  ('diabetes', 35, 'An IV regular insulin drip has been running for a 12-year-old in DKA. Which assessments are MOST important for the nurse to monitor? Select all that apply.', '[{"id": "a", "text": "2-hour OGTT result"}, {"id": "b", "text": "Fasting glucose criterion"}, {"id": "c", "text": "Confusion or lethargy"}, {"id": "d", "text": "HbA1c"}, {"id": "e", "text": "Serum potassium"}]'::jsonb, '["c", "e"]', 'Correct: (e) potassium is monitored closely because K⁺ drops when insulin is given (hypokalemia); (c) confusion and lethargy can progress to coma, so close monitoring includes mental status. Wrong: (d), (b), and (a) are diagnostic criteria, not DKA treatment monitoring.', true),
  ('diabetes', 36, 'A nurse is preparing the insulin infusion ordered for a 10-year-old in DKA after the normal saline bolus. Which insulin should the nurse expect to be used for the infusion?', '[{"id": "a", "text": "Insulin glargine"}, {"id": "b", "text": "NPH insulin"}, {"id": "c", "text": "Insulin lispro"}, {"id": "d", "text": "Regular insulin"}]'::jsonb, '["d"]', 'DKA treatment uses an IV regular insulin drip after fluid resuscitation. Glargine, NPH, and lispro are long-, intermediate-, and rapid-acting insulins, not the IV regular insulin drip.', false),
  ('diabetes', 37, 'A school nurse is teaching staff about a 7-year-old with type 1 diabetes. Which items provide 15 g of fast-acting carbohydrate for a low glucose? Select all that apply.', '[{"id": "a", "text": "4 oz of juice"}, {"id": "b", "text": "4 oz of diet soda"}, {"id": "c", "text": "An insulin pen"}, {"id": "d", "text": "Regular soda"}, {"id": "e", "text": "Glucose tablets"}]'::jsonb, '["a", "d", "e"]', 'Correct: (a) 4 oz juice, (e) glucose tablets, and (d) regular soda are the fast-acting carbohydrates for the 15–15 rule. Wrong: (b) diet soda is not regular soda; (c) insulin lowers glucose further.', true),
  ('diabetes', 38, 'The parent of a 10-year-old is learning the 15–15 rule. Which statements by the parent indicate understanding? Select all that apply.', '[{"id": "a", "text": "I''ll recheck her blood glucose after 1 hour"}, {"id": "b", "text": "I''ll wait 15 minutes after treating"}, {"id": "c", "text": "I''ll recheck her blood glucose"}, {"id": "d", "text": "I''ll repeat the carbs if she is still under 70"}, {"id": "e", "text": "I''ll give 30 g of carbs to be safe"}]'::jsonb, '["b", "c", "d"]', 'Correct: (b) wait 15 minutes, (c) recheck blood glucose, and (d) repeat if still <70. Wrong: (a) the recheck is at 15 minutes, not 1 hour; (e) the rule uses 15 g, not 30 g.', true),
  ('diabetes', 39, 'A teacher reports that an 8-year-old with type 1 diabetes became confused, sweaty, and unable to concentrate before lunch. The child is awake and can swallow. Which finding should the nurse expect when checking glucose?', '[{"id": "a", "text": "Glucose below 70 mg/dL"}, {"id": "b", "text": "Glucose above 240 mg/dL"}, {"id": "c", "text": "Glucose above 250 mg/dL with ketones"}, {"id": "d", "text": "Glucose of 126 mg/dL fasting"}]'::jsonb, '["a"]', 'Confusion, diaphoresis, and difficulty concentrating are hypoglycemia signs (<70 mg/dL). BG above 240–250 with ketones reflects hyperglycemia and DKA.', false),
  ('diabetes', 40, 'A 6-year-old with type 1 diabetes has shakiness and irritability with a glucose of 50 mg/dL, but refuses juice. Which action is MOST important to prevent a complication?', '[{"id": "a", "text": "Wait until lunch, when he will eat"}, {"id": "b", "text": "Treat now; untreated lows lead to seizures"}, {"id": "c", "text": "Recheck the glucose in 1 hour"}, {"id": "d", "text": "Give a dose of regular insulin"}]'::jsonb, '["b"]', 'Untreated hypoglycemia progresses to seizures, so the low is treated promptly with fast-acting carbohydrates such as glucose tablets or regular soda. Waiting or giving insulin worsens the low.', false),
  ('diabetes', 41, 'The parent of a 5-year-old asks when the prescribed nasal glucagon should be used. Which response by the nurse is BEST?', '[{"id": "a", "text": "When her glucose is above 240 mg/dL"}, {"id": "b", "text": "Before every soccer practice or game she plays"}, {"id": "c", "text": "When she is unconscious or cannot swallow"}, {"id": "d", "text": "When she is shaky but able to drink"}]'::jsonb, '["c"]', 'Glucagon IM or IN (nasal) is for a child who is unconscious or cannot swallow; an alert child who can drink receives 15 g of fast-acting carbohydrates. BG above 240 calls for ketone checks.', false),
  ('diabetes', 42, 'During sick day phone triage, the parent of a 9-year-old with type 1 diabetes says the child is drinking well and has a glucose of 220 mg/dL. The parent plans to check glucose only at breakfast and bedtime. Which instruction is BEST?', '[{"id": "a", "text": "Check ketones every hour around the clock"}, {"id": "b", "text": "Go to the ER right away"}, {"id": "c", "text": "Skip insulin until BG drops"}, {"id": "d", "text": "Check blood glucose every 3–4 hours"}]'::jsonb, '["d"]', 'Sick day rules call for checking blood glucose every 3–4 hours. Ketones are checked when BG is above 240, the ER is for vomiting with inability to keep fluids down, and insulin is never skipped.', false),
  ('diabetes', 43, 'An 11-year-old with a glucose of 410 mg/dL is vomiting, has sunken eyes and dry mucous membranes, and urine ketones are large. Which complication should the nurse suspect?', '[{"id": "a", "text": "Diabetic ketoacidosis"}, {"id": "b", "text": "Hypoglycemia from excess insulin"}, {"id": "c", "text": "Lipodystrophy from one site"}, {"id": "d", "text": "New onset of type 2"}]'::jsonb, '["a"]', 'BG often above 250 mg/dL with ketones in urine/blood, vomiting, and dehydration with sunken eyes indicate DKA. Hypoglycemia is below 70 mg/dL, and lipodystrophy is lumpy skin from unrotated sites.', false),
  ('diabetes', 44, 'A nurse is caring for an 11-year-old admitted in DKA. Which findings should the nurse expect? Select all that apply.', '[{"id": "a", "text": "Glucose of 65 mg/dL"}, {"id": "b", "text": "Ketones in urine"}, {"id": "c", "text": "Sunken eyes and dehydration"}, {"id": "d", "text": "Shakiness and pallor"}, {"id": "e", "text": "Nausea, vomiting, and abdominal pain"}]'::jsonb, '["b", "c", "e"]', 'Correct: (e) nausea, vomiting, and abdominal pain, (c) dehydration with sunken eyes, and (b) ketones in urine/blood are DKA findings. Wrong: (d) shakiness and pallor and (a) a glucose below 70 mg/dL are hypoglycemia.', true),
  ('diabetes', 45, 'A 13-year-old received regular insulin at 0700. By which time should the nurse expect the effect of this dose to have ended?', '[{"id": "a", "text": "0900"}, {"id": "b", "text": "1500"}, {"id": "c", "text": "1000"}, {"id": "d", "text": "1100"}]'::jsonb, '["b"]', 'Regular insulin lasts 5–8 hours, so a dose at 0700 ends by 1200–1500; by 1500 (8 hours) the effect has ended. 0900–1100 is the 2–4-hour peak, when the effect is greatest.', false),
  ('diabetes', 46, 'A nurse is caring for a 12-year-old found unresponsive at home with a glucose meter reading of 35 mg/dL. Which actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Give glucagon IM"}, {"id": "b", "text": "Call 911"}, {"id": "c", "text": "Give 4 oz of juice by mouth"}, {"id": "d", "text": "Give rapid-acting insulin"}, {"id": "e", "text": "Wait 15 minutes and recheck first"}]'::jsonb, '["a", "b"]', 'Correct: (a) a child who is unconscious or cannot swallow receives glucagon IM or IN; (b) 911 is called if unresponsive. Wrong: (c) oral juice requires the child to swallow; (d) insulin lowers glucose further; (e) waiting delays treatment of an unresponsive child.', true),
  ('diabetes', 47, 'A 14-year-old in DKA has received an IV fluid bolus and an IV regular insulin drip. The nurse notes the serum potassium is dropping. Which order should the nurse anticipate NEXT?', '[{"id": "a", "text": "A second IV insulin drip"}, {"id": "b", "text": "Subcutaneous glargine"}, {"id": "c", "text": "Potassium replacement"}, {"id": "d", "text": "Glucagon injection"}]'::jsonb, '["c"]', 'K⁺ drops when insulin is given, so potassium replacement follows the IV insulin drip; hypokalemia is a DKA treatment complication. Glucagon treats hypoglycemia, not low potassium.', false),
  ('diabetes', 48, 'A 10-year-old with type 1 diabetes has a fever and a cold, is drinking well, and has a blood glucose of 210 mg/dL. The parent asks what to do today. Which plan by the nurse is BEST?', '[{"id": "a", "text": "Hold insulin, check BG every 3–4 hours, stay hydrated"}, {"id": "b", "text": "Give insulin and check ketones now, since BG is over 200"}, {"id": "c", "text": "Give insulin and go to the ER because of the fever"}, {"id": "d", "text": "Give insulin, check BG every 3–4 hours, stay hydrated"}]'::jsonb, '["d"]', 'Sick day rules: never skip insulin (illness increases BG), check blood glucose every 3–4 hours, and stay hydrated with fluids. Ketones are checked when BG is above 240 mg/dL, and the ER is for vomiting with inability to keep fluids down.', false),
  ('diabetes', 49, 'An 8-year-old is brought in after weeks of thirst and frequent urination. The child now has deep, labored breathing, fruity breath, and is hard to arouse. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Prepare for an IV normal saline bolus"}, {"id": "b", "text": "Give 15 g of fast-acting carbohydrates"}, {"id": "c", "text": "Give subcutaneous regular insulin first"}, {"id": "d", "text": "Teach the 3 Ps of hyperglycemia now"}]'::jsonb, '["a"]', 'Kussmaul respirations, fruity breath, and decreasing consciousness after polydipsia and polyuria indicate DKA, a life-threatening emergency; the first step is an IV normal saline bolus. Subcut insulin is not given first, and carbohydrates treat hypoglycemia.', false),
  ('diabetes', 50, 'A 9-year-old with type 1 diabetes has a headache, is hungry, and is irritable before dinner. A glucose check is 68 mg/dL, and the child can swallow. Which action is the PRIORITY?', '[{"id": "a", "text": "Give the dinner dose of lispro now so she can eat"}, {"id": "b", "text": "Give 4 oz of juice and recheck in 15 minutes"}, {"id": "c", "text": "Check urine ketones before dinner"}, {"id": "d", "text": "Give glucagon IN and call 911"}]'::jsonb, '["b"]', 'A glucose of 68 mg/dL (<70) with headache, hunger, and irritability is hypoglycemia; the 15–15 rule gives 15 g of fast-acting carbohydrates (4 oz juice), waits 15 minutes, and rechecks. Glucagon is for a child who is unconscious or cannot swallow.', false),
  ('fever_pku', 1, 'A 7-week-old is brought to the clinic with a rectal temperature of 100.6°F. The infant is alert, feeding well, and has a normal cry. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Report the fever to the provider immediately"}, {"id": "b", "text": "Give acetaminophen and recheck in 1 hour"}, {"id": "c", "text": "Encourage fluids and dress in light clothing"}, {"id": "d", "text": "Reassure the parent that fever is a normal response"}]'::jsonb, '["a"]', 'Any fever (≥100.4°F) in an infant under 3 months is reported immediately because of possible serious bacterial infection, even when the infant looks well. Fluids, light clothing, and reassurance are home measures for older children.', false),
  ('fever_pku', 2, 'A nurse is reviewing home fever care with the parent of a 4-year-old who weighs 16 kg and has a temperature of 101.8°F. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Give acetaminophen 160–240 mg every 4–6 hours"}, {"id": "b", "text": "Give a children''s aspirin product for comfort"}, {"id": "c", "text": "Encourage fluids throughout the day"}, {"id": "d", "text": "Sponge with rubbing alcohol to cool the skin"}, {"id": "e", "text": "Dress the child in light clothing"}]'::jsonb, '["a", "c", "e"]', 'Correct: (a) acetaminophen 10–15 mg/kg × 16 kg = 160–240 mg every 4–6 hours; (c) encourage fluids; (e) light clothing. Wrong: (b) aspirin is never given to children because of Reye''s syndrome risk; (d) cold or alcohol sponge baths are not used.', true),
  ('fever_pku', 3, 'The parent of a 6-week-old asks which method to use at home to check the infant''s temperature, because the infant fusses during rectal checks. Which method should the nurse recommend as BEST?', '[{"id": "a", "text": "Axillary, because it is less upsetting for her"}, {"id": "b", "text": "Rectal, because it is the most accurate"}, {"id": "c", "text": "Temporal, because it is quick and easy"}, {"id": "d", "text": "Oral, because the infant can suck on it"}]'::jsonb, '["b"]', 'Under 3 months, the rectal route is used because it is the most accurate. Axillary and temporal are options only from 3 months to 3 years, and oral is for children older than 3 years.', false),
  ('fever_pku', 4, 'A 12-kg toddler has a fever of 102°F. The nurse reviews four acetaminophen orders. Which order is within the safe dose range?', '[{"id": "a", "text": "100 mg q4–6h as needed"}, {"id": "b", "text": "200 mg q4–6h"}, {"id": "c", "text": "150 mg q4–6h"}, {"id": "d", "text": "150 mg q2h"}]'::jsonb, '["c"]', 'Acetaminophen 10–15 mg/kg × 12 kg = 120–180 mg every 4–6 hours, so 150 mg q4–6h is safe. 100 mg is below range, 200 mg is above range, and every 2 hours is too frequent.', false),
  ('fever_pku', 5, 'A nurse is reviewing the record of an 8-kg, 9-month-old with a fever. Which medication orders are within the safe range for this infant? Select all that apply.', '[{"id": "a", "text": "Ibuprofen 100 mg every 6 hours"}, {"id": "b", "text": "Acetaminophen 100 mg every 4–6 hours"}, {"id": "c", "text": "Ibuprofen 80 mg every 8 hours"}, {"id": "d", "text": "Aspirin 80 mg every 6 hours"}, {"id": "e", "text": "Ibuprofen 60 mg every 6–8 hours"}]'::jsonb, '["b", "c", "e"]', 'Correct: (e) and (c) ibuprofen 5–10 mg/kg × 8 kg = 40–80 mg every 6–8 hours, so 60 mg and 80 mg are safe; (b) acetaminophen 10–15 mg/kg × 8 kg = 80–120 mg every 4–6 hours, so 100 mg is safe. Wrong: (a) 100 mg of ibuprofen exceeds 80 mg; (d) aspirin is never given to children (Reye''s syndrome risk).', true),
  ('fever_pku', 6, 'A parent of a 5-month-old with a temperature of 101°F says, "I have children''s ibuprofen at home, so I''ll use that." Which response by the nurse is BEST?', '[{"id": "a", "text": "Ibuprofen is fine at 5–10 mg/kg every 6–8 hours for her"}, {"id": "b", "text": "Alternate ibuprofen with a cool alcohol sponge bath"}, {"id": "c", "text": "Use a baby aspirin product until 6 months of age"}, {"id": "d", "text": "Use acetaminophen; ibuprofen is for 6 months and older"}]'::jsonb, '["d"]', 'Ibuprofen is given only to children 6 months or older, so a 5-month-old receives acetaminophen (10–15 mg/kg q4–6h). Aspirin is never used in children, and alcohol sponge baths are not used.', false),
  ('fever_pku', 7, 'The parent of a 7-year-old with fever and body aches says, "I gave him one of my aspirin tablets last night and it helped." Which response by the nurse is MOST important?', '[{"id": "a", "text": "Aspirin is never given to children (Reye''s syndrome)"}, {"id": "b", "text": "Aspirin is fine if you give it with plenty of food and fluids"}, {"id": "c", "text": "Use aspirin only if the fever lasts more than 3 days"}, {"id": "d", "text": "Switch to aspirin sponge baths to lower the fever"}]'::jsonb, '["a"]', 'Aspirin is NEVER given to children because of Reye''s syndrome risk; it is not made safe by food or by waiting 3 days. A fever lasting more than 3 days is a reason to report, not a reason to use aspirin.', false),
  ('fever_pku', 8, 'A grandparent caring for a febrile 3-year-old plans to "wipe him down with rubbing alcohol and ice water" to bring the temperature down. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "Use alcohol only, because ice water can cause shivering"}, {"id": "b", "text": "Use light clothing and fluids, not cold or alcohol baths"}, {"id": "c", "text": "Use ice water only, because alcohol irritates the skin"}, {"id": "d", "text": "Bundle him in blankets to sweat out the fever"}]'::jsonb, '["b"]', 'Fever care is encouraging fluids and light clothing; cold and alcohol sponge baths are not used, so neither substitute is acceptable. Bundling in blankets contradicts light clothing.', false),
  ('fever_pku', 9, 'A nurse is assessing several febrile children in an urgent care clinic. Which findings should the nurse report to the provider IMMEDIATELY? Select all that apply.', '[{"id": "a", "text": "A 2-year-old with fever who is lethargic and not drinking"}, {"id": "b", "text": "A 4-year-old with fever, stiff neck, and petechiae"}, {"id": "c", "text": "A 3-year-old with fever on day 1 who is playful and drinking"}, {"id": "d", "text": "A 6-year-old with a fever that has lasted 4 days"}, {"id": "e", "text": "A 5-year-old with fever and difficulty breathing"}]'::jsonb, '["a", "b", "d", "e"]', 'Correct: (a) lethargy and not drinking, (b) stiff neck and petechiae, (d) fever lasting more than 3 days, and (e) difficulty breathing are all reported immediately. Wrong: (c) a 3-year-old on day 1 of fever who is playful and drinking has no red flag; fever is usually a normal immune response.', true),
  ('fever_pku', 10, 'An 18-month-old with a temperature of 103°F begins having a generalized seizure in the clinic waiting room. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Hold the arms and legs firmly to stop the jerking"}, {"id": "b", "text": "Place the child in a cool bath to lower the fever"}, {"id": "c", "text": "Place the child side-lying and time the seizure"}, {"id": "d", "text": "Give oral ibuprofen as soon as possible"}]'::jsonb, '["c"]', 'During a febrile seizure the child is placed side-lying, is not restrained, and the seizure is timed. Holding the limbs is restraint, cold baths are not used, and nothing is given orally during the seizure.', false),
  ('fever_pku', 11, 'A 9-month-old has had diarrhea for 2 days. Findings: sunken anterior fontanel, no tears when crying, no wet diaper in 8 hours, and tented skin. Which classification does the nurse expect?', '[{"id": "a", "text": "Mild dehydration"}, {"id": "b", "text": "Hypotonic dehydration"}, {"id": "c", "text": "Normal hydration with a fever"}, {"id": "d", "text": "Moderate–severe dehydration"}]'::jsonb, '["d"]', 'A sunken fontanel, no tears when crying, greatly decreased or absent wet diapers, and tented (poor turgor) skin match moderate–severe dehydration. Mild dehydration has normal skin turgor and only decreased tears. Hypotonic describes a sodium value, which is not given.', false),
  ('fever_pku', 12, 'A 2-year-old with diarrhea since yesterday has dry mucous membranes and fewer wet diapers than normal. The child is alert, slightly thirsty, and has normal skin turgor and vital signs. Which intervention is BEST?', '[{"id": "a", "text": "Small frequent amounts of an oral rehydration solution"}, {"id": "b", "text": "A normal saline bolus followed by IV maintenance"}, {"id": "c", "text": "Diluted apple juice offered as often as desired"}, {"id": "d", "text": "A sports drink to replace the electrolytes lost in the stool"}]'::jsonb, '["a"]', 'These findings are mild dehydration, which is treated with ORS (Pedialyte, Enfalyte) in small frequent amounts. IV fluids are for moderate–severe dehydration, and juice and sports drinks are avoided because high sugar worsens diarrhea.', false),
  ('fever_pku', 13, 'A nurse is assessing a 10-month-old admitted with vomiting and diarrhea. Which findings indicate moderate–severe dehydration? Select all that apply.', '[{"id": "a", "text": "No tears when crying"}, {"id": "b", "text": "Sunken eyes and sunken fontanel"}, {"id": "c", "text": "Alert and slightly thirsty"}, {"id": "d", "text": "Tented skin that stays up when pinched"}, {"id": "e", "text": "Delayed capillary refill"}]'::jsonb, '["a", "b", "d", "e"]', 'Correct: (b) sunken eyes and fontanel, (a) no tears when crying, (d) tented skin (pinched skin stays up), and (e) delayed cap refill are moderate–severe findings. Wrong: (c) alert and slightly thirsty is the mental status of mild dehydration.', true),
  ('fever_pku', 14, 'A 14-month-old with 3 days of diarrhea is lethargic, has a heart rate well above baseline, low blood pressure, and delayed capillary refill. Which order should the nurse anticipate FIRST?', '[{"id": "a", "text": "Oral rehydration in small amounts"}, {"id": "b", "text": "A normal saline bolus"}, {"id": "c", "text": "Diluted juice by oral syringe"}, {"id": "d", "text": "A sports drink as tolerated"}]'::jsonb, '["b"]', 'Tachycardia, low BP, delayed cap refill, and lethargy indicate moderate–severe dehydration with shock, which is treated with IV fluid replacement and a normal saline bolus. ORS is for mild dehydration, and juice or sports drinks are avoided.', false),
  ('fever_pku', 15, 'The parent of a 3-year-old with mild dehydration from diarrhea is taught about oral rehydration. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "I''ll give small amounts of Pedialyte often"}, {"id": "b", "text": "I''ll avoid giving him soda or juice for now"}, {"id": "c", "text": "I''ll give sports drinks since he likes them"}, {"id": "d", "text": "I''ll keep track of his wet diapers and intake"}]'::jsonb, '["c"]', 'Sports drinks, soda, sugary drinks, and juice are avoided because the high sugar worsens diarrhea. Small frequent amounts of ORS such as Pedialyte, avoiding soda and juice, and tracking I&Os are correct.', false),
  ('fever_pku', 16, 'The parent of an 11-month-old with mild dehydration is going home with oral rehydration instructions. Which statements by the parent indicate understanding? Select all that apply.', '[{"id": "a", "text": "I''ll give a full bottle of juice when he is thirsty"}, {"id": "b", "text": "I''ll give Pedialyte in small frequent amounts"}, {"id": "c", "text": "I''ll avoid soda and sports drinks while he has diarrhea"}, {"id": "d", "text": "I''ll switch to soda if he refuses the Pedialyte"}, {"id": "e", "text": "I''ll give a full 8 ounces of solution all at once"}]'::jsonb, '["b", "c"]', 'Correct: (b) ORS such as Pedialyte is given in small frequent amounts; (c) soda and sports drinks are avoided because high sugar worsens diarrhea. Wrong: (a) and (d) juice and soda are high-sugar drinks to avoid; (e) large amounts at once contradict small frequent amounts.', true),
  ('fever_pku', 17, 'An infant with several days of diarrhea has a serum sodium of 151 mEq/L. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Hypotonic dehydration; cells swell"}, {"id": "b", "text": "Isotonic dehydration; cells are unchanged"}, {"id": "c", "text": "Hypertonic dehydration; cells swell"}, {"id": "d", "text": "Hypertonic dehydration; cells shrink"}]'::jsonb, '["d"]', 'A serum Na⁺ above 145 mEq/L means more water was lost than sodium (hypertonic), and the cells shrink. Hypotonic (Na⁺ <135) is the type in which cells swell.', false),
  ('fever_pku', 18, 'A toddler admitted with vomiting has a serum sodium of 131 mEq/L. Which statement BEST explains this finding?', '[{"id": "a", "text": "More sodium was lost than water, and cells swell"}, {"id": "b", "text": "More water was lost than sodium, and cells shrink"}, {"id": "c", "text": "Water and sodium were lost equally, the usual type"}, {"id": "d", "text": "More water was lost than sodium, and cells swell"}]'::jsonb, '["a"]', 'A serum Na⁺ below 135 mEq/L is hypotonic dehydration: more sodium lost than water, and cells swell. Equal loss is isotonic (135–145), and more water lost with cell shrinking is hypertonic (>145).', false),
  ('fever_pku', 19, 'A nurse reviews the serum sodium results of three dehydrated children. Which interpretations are correct? Select all that apply.', '[{"id": "a", "text": "Na⁺ 132 mEq/L: hypertonic, cells shrink"}, {"id": "b", "text": "Na⁺ 140 mEq/L: isotonic, the most common type"}, {"id": "c", "text": "Na⁺ 132 mEq/L: hypotonic, cells swell"}, {"id": "d", "text": "Na⁺ 148 mEq/L: hypertonic, cells shrink"}, {"id": "e", "text": "Na⁺ 148 mEq/L: isotonic, cells unchanged"}]'::jsonb, '["b", "c", "d"]', 'Correct: (b) 135–145 mEq/L is isotonic, the most common type; (c) below 135 is hypotonic and cells swell; (d) above 145 is hypertonic and cells shrink. Wrong: (a) 132 is hypotonic, not hypertonic; (e) 148 is above the isotonic range.', true),
  ('fever_pku', 20, 'The parent of a 2-year-old who weighs 12 kg reports giving ibuprofen 100 mg every 4 hours for a fever since yesterday. Which response by the nurse is BEST?', '[{"id": "a", "text": "The dose is too high; give 50 mg every 4 hours"}, {"id": "b", "text": "Ibuprofen is not safe until 3 years of age"}, {"id": "c", "text": "The dose is safe, but give it every 6–8 hours"}, {"id": "d", "text": "Switch to aspirin every 4 hours for this fever"}]'::jsonb, '["c"]', 'Ibuprofen for children 6 months and older is 5–10 mg/kg every 6–8 hours: 5–10 mg/kg × 12 kg = 60–120 mg, so 100 mg is safe but every 4 hours is too frequent. 50 mg is below range, and aspirin is never given to children.', false),
  ('fever_pku', 21, 'A nurse is caring for a 7-month-old receiving IV fluid replacement for moderate–severe dehydration caused by diarrhea. Which assessments should the nurse include in the plan of care? Select all that apply.', '[{"id": "a", "text": "Intake and output"}, {"id": "b", "text": "Daily weight"}, {"id": "c", "text": "Blood phenylalanine level"}, {"id": "d", "text": "Serum K⁺"}, {"id": "e", "text": "Urine output"}]'::jsonb, '["a", "b", "d", "e"]', 'Correct: (a) I&Os, (b) weight, (d) electrolytes including K⁺ (monitored with diarrhea), and (e) urine output are monitored during rehydration. Wrong: (c) blood Phe monitoring is part of PKU treatment, not dehydration care.', true),
  ('fever_pku', 22, 'A newborn is discharged at 20 hours of age after breastfeeding poorly; the PKU heel stick was drawn at 6 hours, before the first feeding. The result is normal. Which action is BEST?', '[{"id": "a", "text": "Reassure the parents that PKU has been ruled out"}, {"id": "b", "text": "Repeat the heel stick; done too early it may be false negative"}, {"id": "c", "text": "Start a Phe-free formula until a repeat result is confirmed"}, {"id": "d", "text": "Repeat the screen only if a musty/mousy body odor develops later"}]'::jsonb, '["b"]', 'The heel stick must be done after 24–48 hours of feeding because protein must be ingested to detect elevated Phe; a sample drawn too early can be a false negative and must be repeated. Waiting for a musty odor would allow brain damage.', false),
  ('fever_pku', 23, 'A nurse reviews the PKU newborn screening data for several infants. Which infants need a repeat heel stick? Select all that apply.', '[{"id": "a", "text": "Drawn after 48 hours of feeding"}, {"id": "b", "text": "Drawn after 30 hours of breastfeeding"}, {"id": "c", "text": "Drawn at 12 hours, after one small feeding"}, {"id": "d", "text": "Drawn after 36 hours of formula feeding"}, {"id": "e", "text": "Drawn at 8 hours of age, before any feeding"}]'::jsonb, '["c", "e"]', 'Correct: (e) and (c) were drawn too early, before 24–48 hours of feeding, so protein may not have been ingested and the result may be a false negative. Wrong: (d), (b), and (a) were drawn after 24–48 hours of feeding, so elevated Phe can be detected.', true),
  ('fever_pku', 24, 'An 8-month-old adopted from a region without newborn screening has seizures, developmental delay, a musty body odor, and lighter hair than the birth family. Which explanation is MOST likely?', '[{"id": "a", "text": "Ketones accumulate from hypertonic dehydration"}, {"id": "b", "text": "Sodium accumulates from more water lost than sodium"}, {"id": "c", "text": "Phenylalanine accumulates from a deficient enzyme"}, {"id": "d", "text": "Febrile seizures from a rapid temperature rise"}]'::jsonb, '["c"]', 'A missing or deficient phenylalanine hydroxylase enzyme lets phenylalanine (Phe) accumulate, causing seizures, intellectual disability, a distinctive musty/mousy odor, and lighter skin and hair when untreated. Febrile seizures occur with fever and do not explain the odor or hair.', false),
  ('fever_pku', 25, 'A 10-month-old with untreated PKU is admitted after a newborn screen was missed. Which findings should the nurse expect? Select all that apply.', '[{"id": "a", "text": "Lighter skin and hair than family members"}, {"id": "b", "text": "Musty/mousy body odor"}, {"id": "c", "text": "Fruity, acetone-smelling breath"}, {"id": "d", "text": "Darker skin and hair than family members"}, {"id": "e", "text": "Intellectual disability"}]'::jsonb, '["a", "b", "e"]', 'Correct: (b) a distinctive musty/mousy body odor, (a) lighter skin and hair than family members, and (e) severe intellectual disability are signs of untreated PKU. Wrong: (c) the distinctive odor is musty/mousy, not fruity; (d) skin and hair are lighter, not darker.', true),
  ('fever_pku', 26, 'The parent of a 6-year-old with PKU makes several statements during a clinic visit. Which statement indicates a need for further teaching?', '[{"id": "a", "text": "She can have most fruits and vegetables"}, {"id": "b", "text": "Her special formula gives her the protein she needs"}, {"id": "c", "text": "She will have regular blood Phe checks"}, {"id": "d", "text": "Diet soda is fine for her because it has no sugar"}]'::jsonb, '["d"]', 'Diet sodas contain aspartame, an artificial sweetener that contains phenylalanine, so they must be avoided. Most fruits and vegetables are allowed, the PKU formula provides protein without Phe, and blood Phe is monitored regularly.', false),
  ('fever_pku', 27, 'A school-age child with PKU is choosing an after-school snack. Which choice should the nurse support as BEST for this child?', '[{"id": "a", "text": "Apple slices and carrot sticks"}, {"id": "b", "text": "A cheese stick with low-protein crackers"}, {"id": "c", "text": "Peanut butter on celery"}, {"id": "d", "text": "A boiled egg and milk"}]'::jsonb, '["a"]', 'Most fruits and vegetables are allowed on a low-phenylalanine diet. Cheese, milk, and eggs (dairy products), and nuts such as peanut butter are high-phenylalanine foods to avoid.', false),
  ('fever_pku', 28, 'A nurse is teaching the parents of an infant newly diagnosed with PKU about foods to avoid as the child grows. Which foods should the nurse include? Select all that apply.', '[{"id": "a", "text": "Chicken and fish"}, {"id": "b", "text": "Green beans"}, {"id": "c", "text": "Cheese and milk"}, {"id": "d", "text": "Diet soda with aspartame"}, {"id": "e", "text": "Applesauce"}]'::jsonb, '["a", "c", "d"]', 'Correct: (a) meat, poultry, and fish, (c) dairy products such as cheese and milk, and (d) aspartame, which contains phenylalanine, are high-phenylalanine items to avoid. Wrong: (b) and (e) most fruits and vegetables are allowed.', true),
  ('fever_pku', 29, 'The parent of a 2-month-old with PKU asks, "If she can''t eat high-protein foods, how will she get the protein she needs to grow?" Which response by the nurse is BEST?', '[{"id": "a", "text": "Small servings of meat and milk will meet her needs"}, {"id": "b", "text": "The special PKU formula provides protein without Phe"}, {"id": "c", "text": "Sapropterin (Kuvan) replaces the protein she cannot eat"}, {"id": "d", "text": "She will not need protein until she is a toddler"}]'::jsonb, '["b"]', 'The special PKU formula (a Phe-free amino acid formula) provides protein without Phe. Meat and milk are high-phenylalanine foods, and sapropterin (Kuvan) increases enzyme activity rather than supplying protein.', false),
  ('fever_pku', 30, 'A 14-year-old with PKU tells the nurse, "I feel fine now, so I''m going to stop my special diet and eat what my friends eat." Which response by the nurse is BEST?', '[{"id": "a", "text": "The diet can stop once growth is complete"}, {"id": "b", "text": "The diet can stop if you take sapropterin"}, {"id": "c", "text": "The low-phenylalanine diet is lifelong"}, {"id": "d", "text": "The diet is needed only during infancy"}]'::jsonb, '["c"]', 'PKU treatment is a lifelong low-phenylalanine diet with regular blood Phe monitoring. Sapropterin (Kuvan) may benefit some patients by increasing enzyme activity but does not replace the diet.', false),
  ('fever_pku', 31, 'The parents of a toddler with PKU are reviewing the treatment plan. Which statements by the parents indicate understanding? Select all that apply.', '[{"id": "a", "text": "His formula gives protein without Phe"}, {"id": "b", "text": "He will need regular blood Phe monitoring"}, {"id": "c", "text": "The diet can stop when he starts school"}, {"id": "d", "text": "He can have meat if he takes his formula"}, {"id": "e", "text": "His low-phenylalanine diet is lifelong"}]'::jsonb, '["a", "b", "e"]', 'Correct: (b) regular blood Phe monitoring, (a) the Phe-free PKU formula provides protein without Phe, and (e) the low-phenylalanine diet is lifelong. Wrong: (c) the diet does not stop at school age; (d) meat is a high-phenylalanine food to avoid regardless of formula.', true),
  ('fever_pku', 32, 'The parents of a child with PKU ask about sapropterin (Kuvan), which the provider is considering. Which statement by the parents indicates understanding?', '[{"id": "a", "text": "It replaces the need for the PKU formula"}, {"id": "b", "text": "It removes the Phe from the foods that she eats each day"}, {"id": "c", "text": "It allows her to drink diet soda safely"}, {"id": "d", "text": "It may increase enzyme activity in some patients"}]'::jsonb, '["d"]', 'Sapropterin (Kuvan) increases enzyme activity and only some patients benefit; the lifelong low-phenylalanine diet and PKU formula continue, and aspartame in diet soda is still avoided.', false),
  ('fever_pku', 33, 'A nurse in a pediatric urgent care clinic receives four triage reports. Which child should the nurse see FIRST?', '[{"id": "a", "text": "A 2-month-old with a temperature of 100.8°F"}, {"id": "b", "text": "A 4-year-old with fever for 2 days who is playful"}, {"id": "c", "text": "A 3-year-old with mild dehydration drinking ORS"}, {"id": "d", "text": "A 6-year-old with PKU asking about snacks"}]'::jsonb, '["a"]', 'Any fever in an infant under 3 months is an emergency because of possible serious bacterial infection. A playful 4-year-old on day 2, a mildly dehydrated child taking ORS, and a diet question can wait.', false),
  ('fever_pku', 34, 'A nurse is assessing a 2-year-old with gastroenteritis whose parent reports diarrhea since yesterday. Which findings are consistent with mild dehydration? Select all that apply.', '[{"id": "a", "text": "Tented skin turgor"}, {"id": "b", "text": "Sunken eyes and fontanel"}, {"id": "c", "text": "Alert and slightly thirsty"}, {"id": "d", "text": "Dry mucous membranes"}, {"id": "e", "text": "Fewer wet diapers than normal"}]'::jsonb, '["c", "d", "e"]', 'Correct: (d) dry mucous membranes, (e) fewer wet diapers than normal, and (c) alert, slightly thirsty are mild findings. Wrong: (b) sunken eyes and fontanel and (a) tented skin are moderate–severe findings.', true),
  ('fever_pku', 35, 'A 2-month-old brought for a well visit has a rectal temperature of 37.9°C, is feeding well, and is alert and active. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Report a fever in an infant under 3 months to the provider immediately"}, {"id": "b", "text": "Continue care; fever is a temperature of 38°C or higher"}, {"id": "c", "text": "Give acetaminophen and recheck in 1 hour"}, {"id": "d", "text": "Encourage fluids and light clothing for fever"}]'::jsonb, '["b"]', 'Fever is a temperature of 38°C (100.4°F) or higher, so 37.9°C is not a fever, and the under-3-month emergency rule does not apply. Acetaminophen and fever measures are not needed without a fever.', false),
  ('fever_pku', 36, 'The parent of a 4-year-old calls because the child has a temperature of 100.2°F, is playing, and is drinking well. Which response by the nurse is BEST?', '[{"id": "a", "text": "Bring the child in to be seen immediately"}, {"id": "b", "text": "Give ibuprofen now and repeat the dose every 4 hours today"}, {"id": "c", "text": "Fever is 100.4°F or higher, so this is not a fever"}, {"id": "d", "text": "Start a cool sponge bath to prevent seizures"}]'::jsonb, '["c"]', 'Fever is ≥100.4°F (38°C), so 100.2°F does not meet the threshold, and the child has no red flags. Ibuprofen is given every 6–8 hours, not every 4, and cold sponge baths are not used.', false),
  ('fever_pku', 37, 'For which children is a rectal temperature an appropriate measurement route? Select all that apply.', '[{"id": "a", "text": "A 6-week-old infant"}, {"id": "b", "text": "A 2-year-old child"}, {"id": "c", "text": "A 5-year-old child"}, {"id": "d", "text": "An 8-month-old infant"}, {"id": "e", "text": "A 10-year-old child"}]'::jsonb, '["a", "b", "d"]', 'Correct: (a) under 3 months, rectal is the most accurate route; (b) and (d) from 3 months to 3 years, rectal, axillary, or temporal may be used. Wrong: (c) and (e) children older than 3 years use oral or axillary.', true),
  ('fever_pku', 38, 'A nurse is measuring the temperature of a cooperative 6-year-old admitted with a respiratory infection. Which routes should the nurse consider BEST for this child?', '[{"id": "a", "text": "Rectal only"}, {"id": "b", "text": "Temporal or rectal"}, {"id": "c", "text": "Rectal or axillary"}, {"id": "d", "text": "Oral or axillary"}]'::jsonb, '["d"]', 'For children older than 3 years, oral or axillary routes are used. Rectal is the most accurate route under 3 months, and temporal is listed for 3 months to 3 years.', false),
  ('fever_pku', 39, 'A parent of a 20-month-old calls: the child has had a fever since this morning, is now inconsolable, and has refused all fluids for 6 hours. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "The child needs to be seen immediately"}, {"id": "b", "text": "Give acetaminophen and call back in 3 days"}, {"id": "c", "text": "Use a cool sponge bath to calm the child"}, {"id": "d", "text": "Offer juice instead of water to tempt the child"}]'::jsonb, '["a"]', 'A febrile child who is inconsolable or not drinking is reported immediately. Waiting 3 days applies to otherwise well children, cold sponge baths are not used, and juice is a sugary drink to avoid.', false),
  ('fever_pku', 40, 'The parent of a 2-year-old who had a brief febrile seizure is receiving discharge teaching. Which statements by the parent indicate understanding? Select all that apply.', '[{"id": "a", "text": "These seizures happen from a rapid rise in temperature"}, {"id": "b", "text": "I should hold his arms down so he does not get hurt"}, {"id": "c", "text": "These seizures are usually brief and harmless"}, {"id": "d", "text": "I''ll put him in a cold bath if he has another one"}, {"id": "e", "text": "These seizures can occur at any age up to 12 years"}]'::jsonb, '["a", "c"]', 'Correct: (a) febrile seizures occur due to a rapid temperature rise; (c) they are usually brief and harmless. Wrong: (b) the child is not restrained; (d) cold sponge baths are not used; (e) febrile seizures occur from 6 months to 5 years.', true),
  ('fever_pku', 41, 'A parent reports that a 3-year-old''s fever was 101.6°F at 1300 after a dose of acetaminophen at 1200, and is still 101.6°F at 1430. The parent plans to give another dose now. Which response by the nurse is BEST?', '[{"id": "a", "text": "Give another dose now since the fever persists"}, {"id": "b", "text": "Acetaminophen is given q4–6h, so not before 1600"}, {"id": "c", "text": "Give an aspirin dose now to bridge until 1600"}, {"id": "d", "text": "Give a double dose next time for a stronger effect"}]'::jsonb, '["b"]', 'Acetaminophen is given 10–15 mg/kg every 4–6 hours, so the next dose is due no earlier than 1600. Aspirin is never given to children, and doubling a dose exceeds the weight-based range.', false),
  ('fever_pku', 42, 'During rounds, a nurse finds a febrile 2-year-old wrapped in two blankets and a fleece sleeper because the parent wants to "sweat out the fever." Which action by the nurse is BEST?', '[{"id": "a", "text": "Add a hat to prevent heat loss from the head"}, {"id": "b", "text": "Leave the blankets but give an alcohol sponge bath"}, {"id": "c", "text": "Change to light clothing and encourage fluids"}, {"id": "d", "text": "Leave the blankets and offer a sports drink"}]'::jsonb, '["c"]', 'Fever management includes encouraging fluids and light clothing; alcohol sponge baths are not used, and sports drinks are avoided because of high sugar.', false),
  ('fever_pku', 43, 'A nurse explains to a parent why an 18-month-old with diarrhea is at higher risk of dehydration than the parent. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "Children have a lower body water percentage"}, {"id": "b", "text": "Children have a slower metabolic rate"}, {"id": "c", "text": "Children have a higher body water percentage"}, {"id": "d", "text": "Children have a faster metabolic rate"}, {"id": "e", "text": "Children lose sodium only, not water"}]'::jsonb, '["c", "d"]', 'Correct: (c) a higher body water percentage and (d) a faster metabolic rate place children at higher risk. Wrong: (a) and (b) reverse these facts; (e) dehydration involves loss of water and sodium in varying proportions.', true),
  ('fever_pku', 44, 'A 15-month-old with diarrhea had dry mucous membranes on admission. Four hours later, the nurse notes the toddler is irritable and the skin stays up when pinched. Which interpretation is MOST accurate?', '[{"id": "a", "text": "Expected findings of mild dehydration at this stage"}, {"id": "b", "text": "Improvement with oral rehydration"}, {"id": "c", "text": "Signs of a febrile seizure starting"}, {"id": "d", "text": "Progression to moderate–severe dehydration"}]'::jsonb, '["d"]', 'Irritability and tented skin (pinched skin stays up) are moderate–severe findings; mild dehydration has normal turgor and an alert, slightly thirsty child.', false),
  ('fever_pku', 45, 'A 13-month-old is receiving ORS for mild dehydration from diarrhea. Which finding BEST indicates that rehydration is effective?', '[{"id": "a", "text": "Tears when crying and more frequent wet diapers"}, {"id": "b", "text": "Sunken fontanel and fewer wet diapers"}, {"id": "c", "text": "Increased thirst with persistently dry mucous membranes"}, {"id": "d", "text": "Tented skin that slowly returns to place"}]'::jsonb, '["a"]', 'Decreased tears and fewer wet diapers are dehydration signs, so tears returning and more wet diapers show improvement. A sunken fontanel and tented skin are moderate–severe signs, and dry membranes with thirst are mild signs.', false),
  ('fever_pku', 46, 'A 4-year-old with fever, vomiting, and a new rash of petechiae on the legs is holding the neck stiffly. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Give ibuprofen and recheck the temperature in 1 hour"}, {"id": "b", "text": "Report the findings to the provider immediately"}, {"id": "c", "text": "Offer small frequent amounts of oral rehydration"}, {"id": "d", "text": "Measure an oral temperature to confirm the fever"}]'::jsonb, '["b"]', 'Stiff neck and petechiae with fever are reported immediately; giving antipyretics, starting ORS, or rechecking the temperature delays reporting.', false),
  ('fever_pku', 47, 'A nurse is coaching a parent by phone whose 2-year-old with a fever of 103°F has just started a generalized seizure. Which instructions should the nurse give? Select all that apply.', '[{"id": "a", "text": "Hold his arms and legs still"}, {"id": "b", "text": "Put him in a cold bath now"}, {"id": "c", "text": "Use a side-lying position"}, {"id": "d", "text": "Time the seizure"}, {"id": "e", "text": "Do not restrain him"}]'::jsonb, '["c", "d", "e"]', 'Correct: (c) side-lying position, (d) time the seizure, and (e) do not restrain. Wrong: (a) holding the limbs is restraint; (b) cold baths are not used.', true),
  ('fever_pku', 48, 'A child with PKU has phenylalanine levels that keep rising despite reported diet adherence. Which item in the child''s diet should the nurse identify as the MOST likely cause?', '[{"id": "a", "text": "Low-protein bread and pasta at dinner each night"}, {"id": "b", "text": "Fresh fruit with each meal"}, {"id": "c", "text": "Gum with aspartame, an artificial sweetener"}, {"id": "d", "text": "Phe-free amino acid formula"}]'::jsonb, '["c"]', 'Aspartame contains phenylalanine and must be avoided. Low-protein grains and most fruits are allowed, and the Phe-free amino acid formula provides protein without Phe.', false),
  ('fever_pku', 49, 'A nurse is explaining PKU newborn screening to the parents of a healthy formula-fed newborn. Which timing for the heel stick BEST ensures an accurate result?', '[{"id": "a", "text": "Within 6 hours of birth"}, {"id": "b", "text": "Before the first feeding"}, {"id": "c", "text": "After the first 2 hours of feeding"}, {"id": "d", "text": "After 24–48 hours of feeding"}]'::jsonb, '["d"]', 'The heel stick is done after 24–48 hours of feeding because the infant must have ingested protein for elevated Phe to be detected; testing too early can give a false negative.', false),
  ('fever_pku', 50, 'A 9-month-old with 2 days of vomiting is irritable, has extremely dry, cracked lips, and has had only one wet diaper in 12 hours. Which plan should the nurse anticipate as BEST?', '[{"id": "a", "text": "IV fluid replacement"}, {"id": "b", "text": "Diluted juice in small sips"}, {"id": "c", "text": "ORS only, with no monitoring"}, {"id": "d", "text": "A sports drink every hour"}]'::jsonb, '["a"]', 'Irritability, extremely dry cracked lips, and greatly decreased wet diapers indicate moderate–severe dehydration, which is treated with IV fluid replacement and monitoring of I&Os, weight, urine output, and electrolytes. Juice and sports drinks are avoided.', false),
  ('gi', 1, 'A 4-week-old first-born male has had forceful, non-green vomiting after every feeding for 5 days and roots eagerly for the bottle right after vomiting. His mucous membranes are dry, and he now weighs less than at birth. An ultrasound confirms the suspected diagnosis. Which action should the nurse anticipate FIRST?', '[{"id": "a", "text": "Prepare the infant for an air enema to relieve the obstruction"}, {"id": "b", "text": "Stabilize fluids and electrolytes before the pyloromyotomy"}, {"id": "c", "text": "Give small, frequent feedings and keep the infant upright"}, {"id": "d", "text": "Transport the infant to the operating room for a pyloromyotomy"}]'::jsonb, '["b"]', 'Projectile non-bilious vomiting with constant hunger in a first-born male at 2–8 weeks indicates pyloric stenosis, and treatment is to stabilize fluids and electrolytes first, then perform the pyloromyotomy. Going straight to surgery skips correcting the dehydration; an air enema treats intussusception.', false),
  ('gi', 2, 'A 5-week-old first-born male has had projectile vomiting after feedings for 3 days and has lost weight. Which additional findings would support the nurse''s suspicion of an obstruction at the outlet of the stomach? Select all that apply.', '[{"id": "a", "text": "Vomiting that is non-bilious (not green)"}, {"id": "b", "text": "Olive-shaped mass in the right upper abdomen"}, {"id": "c", "text": "Red, jelly-like stools with blood and mucus"}, {"id": "d", "text": "Constant hunger, even right after vomiting"}, {"id": "e", "text": "No meconium passed within 24 hours of birth"}]'::jsonb, '["a", "b", "d"]', 'Pyloric stenosis causes projectile vomiting that is non-bilious (NOT green), an olive-shaped mass palpable in the right upper abdomen, and constant hunger right after vomiting, so those three findings fit. Red, jelly-like (currant jelly) stools belong to the intussusception triad, and no meconium within 24 hours is the hallmark of Hirschsprung disease, so those two do not fit.', true),
  ('gi', 3, 'A 3-week-old has vomited forcefully after nearly every feeding for 6 days and has a palpable olive-shaped mass in the right upper abdomen. The infant has dry mucous membranes and has lost weight. Which acid-base imbalance is the nurse MOST likely to find on the laboratory results?', '[{"id": "a", "text": "Metabolic acidosis"}, {"id": "b", "text": "Respiratory alkalosis"}, {"id": "c", "text": "Metabolic alkalosis"}, {"id": "d", "text": "Respiratory acidosis"}]'::jsonb, '["c"]', 'Projectile vomiting with an olive-shaped mass indicates pyloric stenosis, whose classic signs include weight loss, dehydration, and metabolic alkalosis. An acidosis or a respiratory imbalance is not the expected finding for this condition.', false),
  ('gi', 4, 'Shortly after birth, a newborn has frothy saliva and bubbles at the mouth. When a bottle is offered, the newborn coughs, chokes, and becomes cyanotic and does not seem able to swallow. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Burp the newborn and resume the feeding more slowly"}, {"id": "b", "text": "Switch to a Haberman feeder in a semi-upright position"}, {"id": "c", "text": "Stop the feeding and keep the newborn NPO"}, {"id": "d", "text": "Offer smaller volumes of formula more often"}]'::jsonb, '["c"]', 'Frothy saliva and bubbles with choking, coughing, cyanosis and inability to swallow are the signs at birth of EA/TEF, so the newborn is made NPO immediately to prevent aspiration. Resuming oral feeding, even slowly or with a cleft feeder, continues the aspiration risk.', false),
  ('gi', 5, 'A newborn has frothy saliva, cannot swallow, and choked and turned cyanotic during a feeding attempt. The provider suspects the esophagus ends in a blind pouch with an abnormal connection to the trachea. Which orders should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "NG tube to low suction"}, {"id": "b", "text": "Small, frequent oral feedings"}, {"id": "c", "text": "Position upright"}, {"id": "d", "text": "IV fluids"}, {"id": "e", "text": "Surgical repair of the defect"}]'::jsonb, '["a", "c", "d", "e"]', 'For EA/TEF the actions are NPO immediately, an NG tube to low suction to prevent aspiration, upright positioning, IV fluids, and surgical repair, which is required — so the NG tube, upright position, IV fluids and surgical repair are all correct. Small, frequent thickened feedings are wrong because any oral feeding is unsafe; the newborn must be NPO.', true),
  ('gi', 6, 'A newborn awaiting surgical repair of esophageal atresia with tracheoesophageal fistula is NPO with an NG tube ordered to low suction. On rounds, the nurse finds the suction turned off and frothy saliva pooling in the newborn''s mouth. Restoring the suction is the PRIORITY because it prevents which complication?', '[{"id": "a", "text": "Aspiration"}, {"id": "b", "text": "Metabolic alkalosis"}, {"id": "c", "text": "Peritonitis"}, {"id": "d", "text": "Dehydration"}]'::jsonb, '["a"]', 'The NG tube is placed to low suction to prevent aspiration of the frothy secretions the newborn cannot swallow. Metabolic alkalosis is a finding of pyloric stenosis, and hydration is maintained with IV fluids, not suction.', false),
  ('gi', 7, 'A 2-day-old with an unrepaired cleft lip and palate is feeding with a specialized cleft bottle. Midway through each feeding, the infant becomes fussy and the abdomen looks distended, then the infant settles once the feeding stops. Which instruction is BEST for the nurse to give the parent?', '[{"id": "a", "text": "Lay the infant flat so sucking takes less effort"}, {"id": "b", "text": "Burp the infant frequently during the feeding"}, {"id": "c", "text": "Offer a pacifier between feedings to strengthen sucking"}, {"id": "d", "text": "Switch to a regular nipple so the feeding ends sooner"}]'::jsonb, '["b"]', 'An infant with a cleft swallows more air, so the parent should burp frequently; the mid-feed fussing and distension reflect swallowed air. Feeding flat is wrong because the infant should be upright or semi-upright during feeding.', false),
  ('gi', 8, 'The nurse is teaching the parent of a 1-week-old with an unrepaired cleft palate how to feed the infant at home until surgery. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Apply elbow restraints for every feeding at home"}, {"id": "b", "text": "Use a specialized cleft bottle such as a Haberman feeder"}, {"id": "c", "text": "Place the infant supine and flat during the feeding"}, {"id": "d", "text": "Hold the infant upright or semi-upright during feeding"}, {"id": "e", "text": "Wait to burp the infant until the feeding is finished"}]'::jsonb, '["b", "d"]', 'Before surgery, a cleft infant is fed with specialized cleft bottles/nipples such as the Haberman feeder, in an upright or semi-upright position, so those two are correct. Feeding supine and flat contradicts upright positioning; waiting to burp is wrong because the infant needs to burp frequently; elbow restraints are a post-op measure to keep hands off the repair, not a feeding technique.', true),
  ('gi', 9, 'A 12-month-old is recovering on the pediatric unit after cleft palate repair. The nurse observes the unlicensed assistive personnel (UAP) providing care. Which action by the UAP requires the nurse to intervene IMMEDIATELY?', '[{"id": "a", "text": "Reapplying the elbow restraints after a skin check"}, {"id": "b", "text": "Gently cleaning the suture site after the feeding"}, {"id": "c", "text": "Offering pacifiers to the child after feedings"}, {"id": "d", "text": "Offering the soft diet that was ordered after surgery"}]'::jsonb, '["c"]', 'After cleft repair, no pacifiers, straws, or fingers are allowed near the repair, so giving a pacifier must be stopped. Elbow restraints, gentle cleaning of the suture site after feedings, and a soft diet are all correct post-op care.', false),
  ('gi', 10, 'The nurse provides discharge teaching to the parent of a 10-month-old after cleft palate repair. Which statements by the parent indicate understanding of the teaching? Select all that apply.', '[{"id": "a", "text": "\"I''ll keep the elbow restraints on so his hands can''t touch the repair.\""}, {"id": "b", "text": "\"I''ll gently clean the suture site after each of his feedings.\""}, {"id": "c", "text": "\"He can sip his juice through a straw so he won''t need a bottle.\""}, {"id": "d", "text": "\"He can go back to his usual diet as soon as we get home.\""}, {"id": "e", "text": "\"I''ll let him suck on his fingers to comfort himself at night.\""}]'::jsonb, '["a", "b"]', 'Post-op cleft care includes elbow restraints to prevent hands touching the repair site and gently cleaning the suture site after feedings, so those two statements are correct. The child needs a soft diet for a specified period, not the usual diet right away, and straws and fingers are not allowed near the repair.', true),
  ('gi', 11, 'A 10-month-old has sudden episodes of screaming while drawing the knees to the chest, then rests quietly between episodes. The infant has vomited twice, and the latest diaper contains red, jelly-like stool. Which intervention should the nurse prepare the infant for INITIALLY?', '[{"id": "a", "text": "Pyloromyotomy after fluids and electrolytes are stabilized"}, {"id": "b", "text": "Appendectomy before the inflamed area can rupture"}, {"id": "c", "text": "Pull-through procedure with a temporary colostomy"}, {"id": "d", "text": "Air enema, which is first-line and often curative"}]'::jsonb, '["d"]', 'Paroxysmal pain with knees drawn to the chest, currant jelly stool and vomiting is the intussusception triad, and an air enema is the first-line treatment that is often curative. Pyloromyotomy treats pyloric stenosis and a pull-through procedure treats Hirschsprung disease.', false),
  ('gi', 12, 'An 18-month-old''s abdominal ultrasound shows a "target sign." Which findings reported by the parent are consistent with this result? Select all that apply.', '[{"id": "a", "text": "Sudden bouts of pain with knees drawn to the chest that then resolve"}, {"id": "b", "text": "Red, jelly-like stools that contain blood and mucus"}, {"id": "c", "text": "Vomiting with the pain episodes"}, {"id": "d", "text": "Narrow, ribbon-like stools since early infancy"}, {"id": "e", "text": "Greasy, fatty stools with a bloated abdomen"}]'::jsonb, '["a", "b", "c"]', 'A target sign on ultrasound indicates intussusception, whose triad is sudden paroxysmal pain (knees drawn to chest, then resolves), red jelly-like "currant jelly" stool of blood and mucus, and vomiting — so those three fit. Ribbon-like stools point to Hirschsprung disease and greasy, fatty stools (steatorrhea) with bloating point to celiac disease.', true),
  ('gi', 13, 'A 2-year-old with a target sign on ultrasound has just had an air enema. One hour later, the child again draws the knees to the chest with paroxysmal pain and passes another currant jelly stool. Which action should the nurse anticipate NEXT?', '[{"id": "a", "text": "Prepare the child for surgery because the enema did not work"}, {"id": "b", "text": "Offer clear liquids because the enema is usually curative"}, {"id": "c", "text": "Apply a warm pack to the abdomen to ease the cramping"}, {"id": "d", "text": "Begin a strict gluten-free diet to let the bowel heal"}]'::jsonb, '["a"]', 'Ongoing paroxysmal pain and currant jelly stool after the air enema mean the intussusception was not reduced, and surgery is done if the enema fails or the bowel is compromised. Although the air enema is often curative, assuming success and offering liquids ignores the returning signs.', false),
  ('gi', 14, 'The nurse receives report on four children on a pediatric surgical unit. Which child should the nurse assess FIRST?', '[{"id": "a", "text": "A 9-year-old with appendicitis whose pain stopped suddenly"}, {"id": "b", "text": "A 4-week-old with pyloric stenosis who is hungry right after vomiting"}, {"id": "c", "text": "A 2-month-old with GERD who arches the back and is irritable after feeds"}, {"id": "d", "text": "A 6-year-old with celiac disease who has bloating and greasy stools"}]'::jsonb, '["a"]', 'When appendicitis pain suddenly stops, perforation is suspected and must be reported immediately, so this child is seen first. Hunger after vomiting, back arching with irritability, and bloating with steatorrhea are expected findings of pyloric stenosis, GERD, and celiac disease.', false),
  ('gi', 15, 'A 12-year-old has fever, nausea, anorexia, and guarding of the abdomen. The nurse suspects inflammation of the appendix. Which pain history obtained from the child is MOST consistent with this suspicion?', '[{"id": "a", "text": "Cramping that comes in waves with the knees drawn to the chest"}, {"id": "b", "text": "Pain over a palpable olive-shaped mass in the right upper abdomen"}, {"id": "c", "text": "Pain around the navel that migrated to McBurney''s point"}, {"id": "d", "text": "Bloating and pain that worsen after eating bread or pasta"}]'::jsonb, '["c"]', 'Appendicitis pain begins around the navel and migrates to the right lower quadrant (McBurney''s point). Paroxysmal pain with knees drawn to the chest describes intussusception, and an olive-shaped mass describes pyloric stenosis.', false),
  ('gi', 16, 'A 10-year-old is admitted with right lower quadrant pain, fever, rebound tenderness, and guarding and is awaiting an appendectomy. Which nursing actions are appropriate while the child waits for surgery? Select all that apply.', '[{"id": "a", "text": "Keep the child NPO"}, {"id": "b", "text": "Apply a heating pad to the abdomen for comfort"}, {"id": "c", "text": "Give an enema to relieve abdominal pressure"}, {"id": "d", "text": "Report sudden pain relief immediately"}, {"id": "e", "text": "Offer clear liquids to prevent dehydration"}]'::jsonb, '["a", "d"]', 'With appendicitis the child is kept NPO, and sudden pain relief signals possible perforation that must be reported immediately, so those two actions are correct. Heat must NOT be applied to the abdomen and enemas must NOT be given, and offering clear liquids violates NPO status.', true),
  ('gi', 17, 'A 14-year-old with fever, anorexia, rebound tenderness, and pain at McBurney''s point is waiting for the operating room to become available. Which complication is the nurse MOST concerned about if surgery is delayed?', '[{"id": "a", "text": "Metabolic alkalosis"}, {"id": "b", "text": "Peritonitis from rupture"}, {"id": "c", "text": "Aspiration of secretions"}, {"id": "d", "text": "Iron-deficiency anemia"}]'::jsonb, '["b"]', 'An inflamed appendix can rupture and cause peritonitis, which is why an appendectomy is needed. Metabolic alkalosis is linked to pyloric stenosis and iron-deficiency anemia to celiac disease.', false),
  ('gi', 18, 'A full-term newborn is 30 hours old and has not passed meconium. The abdomen is distended, and the newborn vomited after the last feeding. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Document it as expected and recheck the diaper at 48 hours"}, {"id": "b", "text": "Give small feedings and keep the newborn upright"}, {"id": "c", "text": "Offer larger feedings to stimulate peristalsis"}, {"id": "d", "text": "Report the absence of meconium to the provider"}]'::jsonb, '["d"]', 'No meconium within 24 hours of birth is the hallmark sign of Hirschsprung disease, and with distension and vomiting it must be reported. Waiting until 48 hours treats a hallmark sign of functional obstruction as normal.', false),
  ('gi', 19, 'A 3-month-old with feeding intolerance has a rectal biopsy showing absence of ganglion (nerve) cells in a segment of the colon. Which findings in the infant''s history are consistent with this result? Select all that apply.', '[{"id": "a", "text": "No meconium within 24 hours of birth"}, {"id": "b", "text": "Abdominal distension"}, {"id": "c", "text": "Narrow, ribbon-like stools"}, {"id": "d", "text": "Vomiting with feedings"}, {"id": "e", "text": "Red, currant jelly stools"}]'::jsonb, '["a", "b", "c", "d"]', 'Absent ganglion cells mean Hirschsprung disease, which presents with no meconium within 24 hours of birth, abdominal distension, ribbon-like (narrow) stools, and vomiting with feeding intolerance — so those four fit. Red currant jelly stools are a sign of intussusception.', true),
  ('gi', 20, 'The parents of a 2-month-old with an aganglionic segment of colon are preparing for surgery. Which statement by a parent indicates understanding of the planned procedure?', '[{"id": "a", "text": "\"The surgery removes the part of the colon without nerve cells.\""}, {"id": "b", "text": "\"A strict gluten-free diet will let us avoid surgery entirely.\""}, {"id": "c", "text": "\"An air enema should open the bowel, so surgery isn''t needed.\""}, {"id": "d", "text": "\"The surgery cuts the thickened muscle at the stomach outlet.\""}]'::jsonb, '["a"]', 'Hirschsprung disease is treated with a pull-through procedure that removes the aganglionic segment, the part of the colon lacking ganglion (nerve) cells. Cutting the pyloric muscle is a pyloromyotomy for pyloric stenosis, and an air enema treats intussusception.', false),
  ('gi', 21, 'The nurse reviews the records of four 3-month-old infants whose parents report spitting up after feedings. Which infant''s findings MOST strongly suggest GERD rather than normal spitting up?', '[{"id": "a", "text": "Spits up after some feedings and is gaining weight well"}, {"id": "b", "text": "Spits up when burped and is content between feedings"}, {"id": "c", "text": "Spits up small amounts and has normal wet diapers"}, {"id": "d", "text": "Spits up after most feedings and has poor weight gain"}]'::jsonb, '["d"]', 'Normal spitting up and GERD are distinguished by frequency and complications; frequent spitting up with poor weight gain is GERD. The other infants spit up without a complication such as poor weight gain.', false),
  ('gi', 22, 'The nurse is teaching the parent of a 2-month-old who has frequent spitting up, irritability, and poor weight gain related to a weak lower esophageal sphincter. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Give small, frequent feedings"}, {"id": "b", "text": "Keep the infant upright 30 minutes after feeding"}, {"id": "c", "text": "Avoid overfeeding"}, {"id": "d", "text": "Give a PPI if the reflux becomes severe"}, {"id": "e", "text": "Give larger feedings less often to limit spit-up"}]'::jsonb, '["a", "b", "c", "d"]', 'GERD treatment includes small frequent feedings, keeping the infant upright 30 min after feeding, avoiding overfeeding, and PPIs if severe, so those four are correct. Larger, less frequent feedings contradict small frequent feedings and invite overfeeding.', true),
  ('gi', 23, 'The nurse reviews home care with the parent of a 6-week-old with GERD. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll keep her upright for 30 minutes after each feeding.\""}, {"id": "b", "text": "\"I''ll offer smaller amounts more often instead of big bottles.\""}, {"id": "c", "text": "\"Overfeeding is fine if it helps her weight gain.\""}, {"id": "d", "text": "\"Her arching and fussiness can be part of her reflux.\""}]'::jsonb, '["c"]', 'Overfeeding should be avoided in GERD, so letting the infant take as much as she wants needs correction. Upright positioning for 30 minutes, small frequent feedings, and recognizing arching and irritability as GERD signs are all correct.', false),
  ('gi', 24, 'A 4-month-old''s parent reports that the infant spits up after nearly every feeding. Which additional findings would the nurse recognize as consistent with gastroesophageal reflux disease? Select all that apply.', '[{"id": "a", "text": "Red, jelly-like stools"}, {"id": "b", "text": "Arching of the back (Sandifer posture)"}, {"id": "c", "text": "Hoarse voice"}, {"id": "d", "text": "Irritability"}, {"id": "e", "text": "Poor weight gain"}]'::jsonb, '["b", "c", "d", "e"]', 'Signs of GERD include frequent spitting up, arching back (Sandifer posture), poor weight gain, irritability, and hoarse voice, so arching, hoarse voice, irritability and poor weight gain all fit. Red, jelly-like stools are part of the intussusception triad, not GERD.', true),
  ('gi', 25, 'A 5-month-old with GERD still spits up frequently and has poor weight gain despite small frequent feedings, upright positioning after feeds, and avoiding overfeeding. Which addition to the plan of care should the nurse anticipate NEXT?', '[{"id": "a", "text": "A PPI, because the GERD is severe"}, {"id": "b", "text": "A pyloromyotomy after fluids are stabilized"}, {"id": "c", "text": "An air enema to reduce the bowel"}, {"id": "d", "text": "A lifelong strict gluten-free diet"}]'::jsonb, '["a"]', 'PPIs are added when GERD is severe, as with persistent spitting up and poor weight gain despite feeding and positioning measures. A pyloromyotomy treats pyloric stenosis and a gluten-free diet treats celiac disease.', false),
  ('gi', 26, 'A 2-year-old has had chronic diarrhea with greasy stools, a bloated abdomen, weight loss, and fatigue since starting bread and cereal. Testing confirms the suspected autoimmune disorder. Which dietary instruction is the nurse MOST likely to reinforce with the parent?', '[{"id": "a", "text": "Avoid gluten until the diarrhea resolves"}, {"id": "b", "text": "Avoid wheat, barley, and rye for life"}, {"id": "c", "text": "Avoid rice, corn, and potatoes"}, {"id": "d", "text": "Give small, frequent feedings"}]'::jsonb, '["b"]', 'Chronic diarrhea, steatorrhea, bloating and weight loss after starting gluten foods indicate celiac disease, treated with a lifelong strict gluten-free diet — no wheat, barley, or rye. Avoiding gluten only until symptoms resolve is wrong because the diet is lifelong; rice, corn and potatoes are safe.', false),
  ('gi', 27, 'A 7-year-old recently diagnosed with an autoimmune reaction to gluten is choosing foods from the school lunch line. Which choices are safe for this child? Select all that apply.', '[{"id": "a", "text": "Pasta"}, {"id": "b", "text": "Corn"}, {"id": "c", "text": "Potatoes"}, {"id": "d", "text": "Barley"}, {"id": "e", "text": "Rice"}]'::jsonb, '["b", "c", "e"]', 'In celiac disease, rice, corn, and potatoes are safe, so those three are correct. Pasta is made from wheat and barley contains gluten, so both must be avoided on the lifelong gluten-free diet.', true),
  ('gi', 28, 'The parent of a 4-year-old with celiac disease reviews the home diet plan with the nurse. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"Once his diarrhea stops, he can have regular bread again.\""}, {"id": "b", "text": "\"Oats are sometimes contaminated, so I''ll check them first.\""}, {"id": "c", "text": "\"Rice, corn, and potatoes are safe foods for him to eat.\""}, {"id": "d", "text": "\"I''ll read labels for wheat, barley, and rye at the store.\""}]'::jsonb, '["a"]', 'Celiac disease requires a lifelong strict gluten-free diet, so returning to wheat bread when diarrhea stops is incorrect. Checking oats because they are sometimes contaminated and choosing rice, corn and potatoes are correct.', false),
  ('gi', 29, 'A 9-year-old with untreated celiac disease has fatigue, pallor, and laboratory results showing iron-deficiency anemia. The parent asks why the child is anemic. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"Blood is lost in jelly-like stools when the bowel telescopes.\""}, {"id": "b", "text": "\"Gluten damages the villi, causing malabsorption of iron.\""}, {"id": "c", "text": "\"Repeated forceful vomiting causes iron to be lost.\""}, {"id": "d", "text": "\"The colon lacks nerve cells, so iron is not absorbed.\""}]'::jsonb, '["b"]', 'In celiac disease the reaction to gluten damages the small intestine villi, causing malabsorption that leads to iron-deficiency anemia. Blood loss in currant jelly stool describes intussusception, not celiac disease.', false),
  ('gi', 30, 'An 18-month-old began eating bread and cereal at 9 months of age and now has a growth chart showing failure to thrive. The nurse suspects celiac disease. Which additional findings support this suspicion? Select all that apply.', '[{"id": "a", "text": "Currant jelly stools"}, {"id": "b", "text": "Steatorrhea (fatty, greasy stools)"}, {"id": "c", "text": "Ribbon-like stools"}, {"id": "d", "text": "Projectile, non-green vomiting"}, {"id": "e", "text": "Abdominal bloating and pain"}]'::jsonb, '["b", "e"]', 'Celiac disease causes chronic diarrhea, steatorrhea (fatty/greasy stools), abdominal bloating and pain, failure to thrive, weight loss and iron-deficiency anemia, so steatorrhea and bloating fit. Currant jelly stools indicate intussusception, ribbon-like stools indicate Hirschsprung disease, and projectile non-green vomiting indicates pyloric stenosis.', true),
  ('gi', 31, 'A nurse in a pediatric clinic is triaging telephone calls about vomiting infants. Which infant''s presentation is MOST consistent with hypertrophy of the pyloric muscle?', '[{"id": "a", "text": "A 9-month-old girl with vomiting and stools of blood and mucus"}, {"id": "b", "text": "A 2-day-old who has not passed meconium and has a distended abdomen"}, {"id": "c", "text": "A 4-month-old who spits up often and arches the back after feeds"}, {"id": "d", "text": "A 3-week-old first-born boy with projectile, non-green vomiting"}]'::jsonb, '["d"]', 'Pyloric stenosis is most common at 2–8 weeks of age and in first-born males, with projectile non-bilious vomiting. Blood and mucus stools fit intussusception, no meconium fits Hirschsprung disease, and arching with spitting up fits GERD.', false),
  ('gi', 32, 'The nurse is caring for four newborns in the nursery. Which newborn should the nurse assess FIRST?', '[{"id": "a", "text": "A newborn with cleft lip and palate who needs frequent burping during feeds"}, {"id": "b", "text": "A 10-hour-old newborn who has not yet passed meconium"}, {"id": "c", "text": "A newborn with frothy saliva, choking, and cyanosis with feeding"}, {"id": "d", "text": "A newborn with cleft lip who is feeding upright with a Haberman feeder"}]'::jsonb, '["c"]', 'Frothy saliva with coughing, choking and cyanosis at feeding signals EA/TEF with aspiration risk and needs immediate action (NPO, NG to low suction). No meconium is concerning only when absent beyond 24 hours, and frequent burping and upright Haberman feeding are expected cleft care.', false),
  ('gi', 33, 'The nurse is caring for a 14-month-old with intussusception and a 10-year-old with appendicitis. Which finding requires IMMEDIATE follow-up by the nurse?', '[{"id": "a", "text": "The toddler is calm and playing between bouts of knees-to-chest pain"}, {"id": "b", "text": "The 10-year-old reports that the abdominal pain suddenly stopped"}, {"id": "c", "text": "The toddler vomited once while waiting for the air enema"}, {"id": "d", "text": "The 10-year-old has guarding and rebound tenderness on exam"}]'::jsonb, '["b"]', 'In appendicitis, sudden pain relief means perforation is suspected and must be reported immediately. In intussusception, paroxysmal pain that resolves between episodes is part of the classic triad, so a calm toddler between bouts is expected.', false),
  ('gi', 34, 'A 4-year-old has had chronic constipation since infancy, a distended abdomen, and narrow, ribbon-like stools. The parent recalls the child did not pass meconium until 2 days after birth. Which treatment should the nurse anticipate for this child?', '[{"id": "a", "text": "Surgery to remove the aganglionic segment"}, {"id": "b", "text": "Air enema to reduce the telescoped bowel"}, {"id": "c", "text": "Pyloromyotomy after fluid stabilization"}, {"id": "d", "text": "Lifelong strict gluten-free diet"}]'::jsonb, '["a"]', 'Delayed meconium, distension and ribbon-like stools indicate Hirschsprung disease, treated with surgery (pull-through procedure) to remove the aganglionic segment. A gluten-free diet treats celiac disease, which causes greasy stools rather than ribbon-like stools.', false),
  ('gi', 35, 'A 20-month-old has had paroxysmal abdominal pain with the knees drawn to the chest, vomiting, and one currant jelly stool. Which finding on the diagnostic ultrasound would the nurse expect to see documented?', '[{"id": "a", "text": "Olive-shaped pyloric mass"}, {"id": "b", "text": "Target sign"}, {"id": "c", "text": "Blind esophageal pouch"}, {"id": "d", "text": "Inflamed appendix at McBurney''s point"}]'::jsonb, '["b"]', 'This child has the intussusception triad, which is diagnosed by ultrasound showing a "target sign." An olive-shaped mass is the finding in pyloric stenosis, which is also diagnosed by ultrasound.', false),
  ('gi', 36, 'A newborn with suspected tracheoesophageal fistula has an NG tube to low suction while awaiting surgery. The nurse finds the parent holding the newborn and offering a bottle of colostrum. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Allow small sips to support the parent-infant bond"}, {"id": "b", "text": "Have the parent burp the newborn after every half ounce"}, {"id": "c", "text": "Increase the suction so the colostrum is removed quickly"}, {"id": "d", "text": "Keep NPO and stop the feeding immediately"}]'::jsonb, '["d"]', 'A newborn with EA/TEF must be NPO immediately because oral feeding leads to aspiration; the NG tube to low suction is for secretions, not to clear feedings. Allowing even small sips risks aspiration.', false),
  ('gi', 37, 'A nurse on a pediatric unit reviews the status of several clients with abdominal problems. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "4-week-old with projectile vomiting, dry mucous membranes, and weight loss"}, {"id": "b", "text": "Infant with GERD who spits up after feeds but is gaining weight"}, {"id": "c", "text": "Child with appendicitis and a heating pad on the abdomen"}, {"id": "d", "text": "Infant with an unrepaired cleft palate who swallows air during feeds"}, {"id": "e", "text": "Newborn with frothy saliva and bubbles who is unable to swallow"}]'::jsonb, '["a", "c", "e"]', 'The dehydrated infant with pyloric stenosis needs fluids and electrolytes stabilized, heat must NOT be applied to the abdomen in appendicitis, and frothy saliva with inability to swallow signals EA/TEF needing NPO and NG suction — all need immediate follow-up. Spitting up without poor weight gain lacks a complication, and a cleft infant swallowing air is expected (burp frequently).', true),
  ('gi', 38, 'The parent of a 3-week-old first-born boy with projectile vomiting and an olive-shaped mass asks about the plan of care. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"His vomiting will be green from the obstruction.\""}, {"id": "b", "text": "\"The surgery cuts the pyloric muscle so his stomach can empty.\""}, {"id": "c", "text": "\"His fluids and electrolytes need to be corrected before surgery.\""}, {"id": "d", "text": "\"An ultrasound is the test used to confirm what is going on.\""}]'::jsonb, '["a"]', 'Vomiting in pyloric stenosis is non-bilious — NOT green — so this statement is incorrect. A pyloromyotomy cuts the pyloric muscle, fluids and electrolytes are stabilized first, and ultrasound confirms the diagnosis.', false),
  ('gi', 39, 'The nurse teaches the parents of a 2-year-old who had a target sign on ultrasound and episodes of currant jelly stool. Which statements by the parents indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"He will need a lifelong gluten-free diet.\""}, {"id": "b", "text": "\"An air enema is the first treatment and often fixes it.\""}, {"id": "c", "text": "\"He will need surgery if the air enema fails.\""}, {"id": "d", "text": "\"He needs a pyloromyotomy to cut the thick muscle.\""}, {"id": "e", "text": "\"Surgery is needed if part of the bowel is compromised.\""}]'::jsonb, '["b", "c", "e"]', 'Intussusception is treated with an air enema, which is first-line and often curative; surgery is needed if the enema fails or the bowel is compromised — so those three statements are correct. A gluten-free diet treats celiac disease and a pyloromyotomy treats pyloric stenosis.', true),
  ('gi', 40, 'A 7-year-old with celiac disease has followed a strict gluten-free diet for 3 months. Which finding BEST indicates that the treatment is effective?', '[{"id": "a", "text": "Hoarse voice and back arching have resolved"}, {"id": "b", "text": "Stools are no longer narrow and ribbon-like"}, {"id": "c", "text": "Steatorrhea has decreased and weight is increasing"}, {"id": "d", "text": "Vomiting is no longer projectile after meals"}]'::jsonb, '["c"]', 'Celiac disease causes steatorrhea, weight loss and failure to thrive from malabsorption, so less steatorrhea and weight gain show the gluten-free diet is working. Hoarse voice and arching are GERD signs, and ribbon-like stools are Hirschsprung signs.', false),
  ('gi', 41, 'A newborn has a functional obstruction because a segment of colon has no peristalsis. The parents ask what to expect after the surgical repair. Which statement by a parent indicates understanding?', '[{"id": "a", "text": "\"After the pyloromyotomy, she can feed normally again.\""}, {"id": "b", "text": "\"She may need a temporary colostomy after the pull-through.\""}, {"id": "c", "text": "\"An air enema will be tried first to avoid any surgery.\""}, {"id": "d", "text": "\"She will need elbow restraints so she can''t touch the repair.\""}]'::jsonb, '["b"]', 'Hirschsprung disease is treated with a pull-through procedure to remove the aganglionic segment, and the child may need a temporary colostomy. A pyloromyotomy is for pyloric stenosis and elbow restraints are for cleft repair.', false),
  ('gi', 42, 'The parent of a 3-month-old with GERD asks why the infant keeps spitting up and seems uncomfortable after feeds. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"A thickened muscle keeps the stomach from emptying into the bowel.\""}, {"id": "b", "text": "\"A segment of the colon lacks nerve cells and cannot move stool.\""}, {"id": "c", "text": "\"A weak LES lets stomach contents reflux back into the esophagus.\""}, {"id": "d", "text": "\"One section of bowel slides into another and blocks it.\""}]'::jsonb, '["c"]', 'In GERD, stomach contents reflux back into the esophagus because of a weak or incompetent LES. A thickened pyloric muscle describes pyloric stenosis, and absent nerve cells describe Hirschsprung disease.', false),
  ('gi', 43, 'A 4-month-old is irritable after feeds, spits up frequently, and repeatedly arches the back during and after feedings. The infant''s weight gain has slowed. Which interpretation of these findings is MOST accurate?', '[{"id": "a", "text": "Normal spitting up that needs no change in care"}, {"id": "b", "text": "Projectile vomiting from a narrowed pyloric channel"}, {"id": "c", "text": "Paroxysmal pain from one bowel segment telescoping"}, {"id": "d", "text": "GERD with Sandifer posture and poor weight gain"}]'::jsonb, '["d"]', 'Frequent spitting up, arching back (Sandifer posture), irritability and poor weight gain are signs of GERD; the complication of poor weight gain separates it from normal spitting up. Narrowed pyloric channel causes projectile, not frequent small, vomiting.', false),
  ('gi', 44, 'Four children are brought to the emergency department with abdominal complaints. Which child''s presentation is MOST consistent with telescoping of one bowel segment into another?', '[{"id": "a", "text": "A 10-year-old whose pain began at the navel and moved to the right lower quadrant"}, {"id": "b", "text": "A 3-week-old first-born boy who vomits forcefully after every feeding"}, {"id": "c", "text": "A 16-month-old with sudden pain, knees drawn to chest, then normal play"}, {"id": "d", "text": "A newborn who has not passed meconium within 24 hours of birth"}]'::jsonb, '["c"]', 'Sudden paroxysmal pain with the knees drawn to the chest that then resolves, in a child within the most common age of 6 months – 3 years, indicates intussusception. Pain migrating from the navel to the right lower quadrant fits appendicitis, forceful vomiting at 3 weeks fits pyloric stenosis, and no meconium fits Hirschsprung disease.', false),
  ('gi', 45, 'A 4-month-old had cleft lip repair yesterday and has just finished a feeding of formula. The elbow restraints are in place. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Remove the elbow restraints so the infant can rest"}, {"id": "b", "text": "Clean the suture site gently"}, {"id": "c", "text": "Offer a pacifier to soothe the infant"}, {"id": "d", "text": "Lay the infant flat with a bottle"}]'::jsonb, '["b"]', 'After cleft repair, the suture site is cleaned gently after feedings. Elbow restraints stay on to prevent the hands touching the repair site, and pacifiers are not allowed near the repair.', false),
  ('gi', 46, 'A 3-year-old with suspected celiac disease is admitted with weight loss, chronic diarrhea, and fatigue. The nurse reviews meal orders entered for the child. Which meal should the nurse question FIRST?', '[{"id": "a", "text": "Baked potato with grilled chicken"}, {"id": "b", "text": "Rice with steamed vegetables"}, {"id": "c", "text": "Corn tortillas with beans"}, {"id": "d", "text": "Wheat pasta with meat sauce"}]'::jsonb, '["d"]', 'Pasta is made from wheat, which contains gluten and is excluded in celiac disease. Potatoes, rice, and corn are safe.', false),
  ('gi', 47, 'An 11-year-old with suspected appendicitis reports pain that began around the umbilicus and is now in the right lower quadrant. Which additional assessment findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "Olive-shaped mass"}, {"id": "b", "text": "Currant jelly stool"}, {"id": "c", "text": "Rebound tenderness"}, {"id": "d", "text": "Ribbon-like stools"}, {"id": "e", "text": "Fever"}]'::jsonb, '["c", "e"]', 'Appendicitis causes fever, nausea, anorexia, rebound tenderness, and guarding, so rebound tenderness and fever are expected. An olive-shaped mass indicates pyloric stenosis, currant jelly stool indicates intussusception, and ribbon-like stools indicate Hirschsprung disease.', true),
  ('gi', 48, 'A 1-day-old newborn''s esophagus is found to end in a blind pouch. Which findings would the nurse expect when assessing this newborn? Select all that apply.', '[{"id": "a", "text": "Frothy saliva and bubbles"}, {"id": "b", "text": "Projectile, non-green vomiting"}, {"id": "c", "text": "Choking and coughing with feeding"}, {"id": "d", "text": "Cyanosis"}, {"id": "e", "text": "Inability to swallow"}]'::jsonb, '["a", "c", "d", "e"]', 'EA/TEF presents at birth with frothy saliva and bubbles, choking/coughing with the first feeding, cyanosis, and inability to swallow, so those four are expected. Projectile, non-bilious vomiting is the sign of pyloric stenosis at 2–8 weeks.', true),
  ('gi', 49, 'The parent of a 4-week-old with projectile vomiting and a palpable olive-shaped mass says, "He throws up and then right away he''s screaming for more. I think I''m not giving him enough formula." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Being hungry right after vomiting is a classic sign of his condition.\""}, {"id": "b", "text": "\"Increase each bottle by an ounce so he stays full longer.\""}, {"id": "c", "text": "\"His hunger shows the blockage is starting to resolve.\""}, {"id": "d", "text": "\"Switch to a cleft bottle so he swallows less air.\""}]'::jsonb, '["a"]', 'Constant hunger, being hungry right after vomiting, is a classic sign of pyloric stenosis, not a sign of underfeeding. Larger bottles will not pass the narrowed pyloric channel, and the hunger does not mean the obstruction is resolving.', false),
  ('gi', 50, 'The parent of a 5-year-old newly diagnosed with celiac disease asks, "Can he still have the oatmeal he eats every morning?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Yes, oats are a safe grain just like rice and corn.\""}, {"id": "b", "text": "\"No, oats contain the same protein as wheat and can never be eaten.\""}, {"id": "c", "text": "\"Yes, once his diarrhea and bloating have gone away.\""}, {"id": "d", "text": "\"Oats are sometimes contaminated, so check before using them.\""}]'::jsonb, '["d"]', 'Gluten is the protein in wheat, barley, and rye, and oats are sometimes contaminated with it, so oats must be checked before use. Rice, corn, and potatoes are the safe foods, and the gluten-free diet is lifelong, not only until symptoms resolve.', false),
  ('heme_onc', 1, 'An 8-year-old with sickle cell disease is admitted in vaso-occlusive crisis with leg pain rated 8/10, dry mucous membranes, and an SpO₂ of 96% on room air. Which nursing action is the PRIORITY to prevent further sickling?', '[{"id": "a", "text": "Apply O₂ by nasal cannula to raise the saturation"}, {"id": "b", "text": "Apply cold packs to the painful legs to ease the pain"}, {"id": "c", "text": "Give IV fluids and encourage oral fluids"}, {"id": "d", "text": "Encourage walking in the hall to improve circulation"}]'::jsonb, '["c"]', 'Hydration with IV fluids plus oral fluids prevents sickling, and dry mucous membranes show dehydration, a crisis trigger. O₂ is indicated only if SpO₂ is <95%, so a reading of 96% does not call for it; cold is avoided.', false),
  ('heme_onc', 2, 'A 12-year-old with sickle cell disease is receiving IV fluids and an opioid for a pain crisis. During the 0400 assessment, which finding requires IMMEDIATE follow-up?', '[{"id": "a", "text": "Yellow sclerae that were also noted on admission"}, {"id": "b", "text": "New chest pain with signs of respiratory distress"}, {"id": "c", "text": "Bone pain in both thighs rated 6/10 after the opioid"}, {"id": "d", "text": "Hemoglobin below normal, consistent with prior labs"}]'::jsonb, '["b"]', 'Chest pain plus respiratory distress signals acute chest syndrome, an emergency in sickle cell disease. Jaundice (RBC breakdown) and chronic anemia are expected signs of the disease, and bone pain is the crisis being treated.', false),
  ('heme_onc', 3, 'A 9-year-old with sickle cell disease is admitted in vaso-occlusive crisis with severe abdominal and leg pain and dry mucous membranes. Which interventions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Give opioids or NSAIDs as prescribed for pain"}, {"id": "b", "text": "Apply cold packs to the painful joints"}, {"id": "c", "text": "Apply a heating pad to painful areas"}, {"id": "d", "text": "Encourage frequent walking to improve blood flow"}, {"id": "e", "text": "Encourage oral fluids in addition to IV fluids"}]'::jsonb, '["a", "c", "e"]', 'Correct: pain management uses opioids and NSAIDs (a); a heating pad is used for comfort because cold is avoided (c); hydration with IV fluids plus oral fluids prevents sickling (e). Wrong: cold packs are contraindicated (NO cold) (b); rest, not activity, is needed to decrease O₂ demand (d).', true),
  ('heme_onc', 4, 'A 6-year-old in sickle cell pain crisis has IV fluids infusing and a heating pad on the painful knee. The child is resting quietly, but the pulse oximeter now reads 94% on room air. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Recheck the saturation at the next scheduled vital signs"}, {"id": "b", "text": "Replace the heating pad with an ice pack on the knee"}, {"id": "c", "text": "Have the child walk in the hall to expand the lungs"}, {"id": "d", "text": "Give O₂ as prescribed because SpO₂ is below 95%"}]'::jsonb, '["d"]', 'In a vaso-occlusive crisis, O₂ is given when SpO₂ is <95%; 94% meets that threshold, so waiting is unsafe. Cold must not be used, and rest (not walking) decreases O₂ demand.', false),
  ('heme_onc', 5, 'The parent of a 9-month-old with sickle cell disease brings the infant to the clinic because the infant has been fussy and cries whenever the hands or feet are touched. Which assessment finding would the nurse MOST likely expect?', '[{"id": "a", "text": "Dactylitis with swollen hands and feet"}, {"id": "b", "text": "Hemarthrosis with a warm, swollen knee"}, {"id": "c", "text": "Spoon-shaped nails with a craving for dirt"}, {"id": "d", "text": "Periorbital ecchymosis with an abdominal mass"}]'::jsonb, '["a"]', 'Dactylitis (swollen hands/feet in infants) is a sign of sickle cell disease. Hemarthrosis is a hemophilia finding, spoon-shaped nails and pica point to iron deficiency, and periorbital ecchymosis suggests neuroblastoma.', false),
  ('heme_onc', 6, 'A 10-year-old with sickle cell disease is admitted with a pain crisis in both elbows. The parent says, ''At home we put bags of frozen peas on his joints to numb the pain.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Cold packs are helpful because they reduce swelling in the joints."}, {"id": "b", "text": "We use a heating pad, because cold temperatures can trigger sickling."}, {"id": "c", "text": "Ice is used for these joints, just as it is for a hemophilia joint bleed."}, {"id": "d", "text": "Alternating ice and heat every hour will balance the blood flow."}]'::jsonb, '["b"]', 'Sickle cell pain management uses a heating pad with NO cold, because cold temperatures are a crisis trigger. Ice belongs to RICE for hemophilia joint bleeds, not sickle cell pain.', false),
  ('heme_onc', 7, 'The nurse on a pediatric hematology-oncology unit receives report on four children with the following conditions. Which child should the nurse assess FIRST?', '[{"id": "a", "text": "Hodgkin lymphoma, reporting night sweats last night"}, {"id": "b", "text": "Sickle cell disease, with slightly yellow sclerae"}, {"id": "c", "text": "ALL on chemotherapy, with a new fever of 38.6°C"}, {"id": "d", "text": "Iron-deficiency anemia on ferrous sulfate, with dark stools"}]'::jsonb, '["c"]', 'A child with ALL is at infection risk from neutropenia, so a new fever must be addressed first. Night sweats are an expected B symptom of Hodgkin lymphoma, jaundice reflects RBC breakdown in sickle cell disease, and dark stool is expected with ferrous sulfate.', false),
  ('heme_onc', 8, 'The nurse is taking a history from the parent of a 4-year-old admitted in sickle cell pain crisis after 2 days of vomiting, sledding in the snow, and a cough with fever. Which factors in the history MOST likely contributed to the crisis? Select all that apply.', '[{"id": "a", "text": "Dehydration from low oral intake"}, {"id": "b", "text": "Cold temperatures during play in the snow"}, {"id": "c", "text": "Eating fortified cereals each morning"}, {"id": "d", "text": "A recent infection with fever"}, {"id": "e", "text": "Daily prophylactic penicillin"}]'::jsonb, '["a", "b", "d"]', 'Correct: dehydration (a), cold temperatures (b), and infection (d) — all listed sickle cell triggers. Wrong: fortified cereal is an iron-rich food and not a trigger (c); prophylactic penicillin until age 5 prevents infection rather than causing a crisis (e).', true),
  ('heme_onc', 9, 'An 18-month-old is pale and irritable and has a heart rate above the normal range for age. The parent reports the toddler drinks about 6 bottles of cow''s milk a day and eats very little solid food. Which intervention BEST addresses the cause of these findings?', '[{"id": "a", "text": "Mix the prescribed iron into the toddler''s milk bottles"}, {"id": "b", "text": "Add a daily antacid to protect the stomach from iron"}, {"id": "c", "text": "Limit cow''s milk and offer iron-rich foods instead"}, {"id": "d", "text": "Increase milk intake to boost calories and protein"}]'::jsonb, '["c"]', 'Too much cow''s milk in toddlers replaces iron-rich food and is a cause of iron-deficiency anemia, whose signs include pallor, irritability, and tachycardia. Giving iron with milk or antacids reduces absorption.', false),
  ('heme_onc', 10, 'A 4-year-old with iron-deficiency anemia is prescribed ferrous sulfate. The family eats breakfast at 0700 and lunch at 1200, and the child drinks milk with every meal. Which administration plan is BEST?', '[{"id": "a", "text": "Give it at breakfast with a cup of milk"}, {"id": "b", "text": "Give it at lunch with an antacid for comfort"}, {"id": "c", "text": "Give it at bedtime with a cup of warm milk"}, {"id": "d", "text": "Give it between meals with orange juice"}]'::jsonb, '["d"]', 'Ferrous sulfate is given between meals with vitamin C (orange juice) to enhance absorption. Milk and antacids reduce absorption, so giving it at mealtimes when milk is served lowers its effect.', false),
  ('heme_onc', 11, 'A 2-year-old who was born prematurely and drinks large amounts of cow''s milk has a low hemoglobin due to insufficient iron. Which findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "Pallor"}, {"id": "b", "text": "Tachycardia"}, {"id": "c", "text": "Jaundice of the sclerae"}, {"id": "d", "text": "Irritability"}, {"id": "e", "text": "Pica (craving non-food items)"}]'::jsonb, '["a", "b", "d", "e"]', 'Correct: pallor (a), tachycardia (b), irritability (d), and pica — craving non-food items (e) are signs of iron-deficiency anemia. Wrong: jaundice reflects RBC breakdown in sickle cell disease, not low iron (c).', true),
  ('heme_onc', 12, 'The parent of a 3-year-old who started ferrous sulfate 5 days ago calls the clinic: ''His stools have turned dark. He is playing and eating normally.'' Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "Dark stool is expected with the iron; keep giving it as prescribed."}, {"id": "b", "text": "Stop the iron now and bring him to the emergency department."}, {"id": "c", "text": "Give the iron with milk from now on to lighten the stool color."}, {"id": "d", "text": "Hold the iron until his stools return to their usual color."}]'::jsonb, '["a"]', 'Stool turning dark with ferrous sulfate is expected, and the nurse should reassure the family. Giving iron with milk reduces absorption, and stopping or holding the iron is not indicated for this expected effect.', false),
  ('heme_onc', 13, 'A 4-year-old boy with hemophilia A falls at preschool. An hour later his right knee is swollen, warm, and painful, and he refuses to walk. Factor concentrate has been prescribed and is on its way from the pharmacy. Which nursing action is MOST appropriate while waiting?', '[{"id": "a", "text": "Give ibuprofen as needed for pain and swelling"}, {"id": "b", "text": "Rest, Ice, Compression, and Elevation of the knee"}, {"id": "c", "text": "Apply a heating pad to the knee to ease the pain"}, {"id": "d", "text": "Encourage gentle walking to keep the joint from stiffening"}]'::jsonb, '["b"]', 'A joint bleed (hemarthrosis) is managed with RICE — Rest, Ice, Compression, Elevation — along with clotting factor. NSAIDs increase bleeding risk, and a heating pad is the sickle cell comfort measure, not care for a bleeding joint.', false),
  ('heme_onc', 14, 'The nurse reviews home care with the parents of a 7-year-old with hemophilia. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "We are learning how to give his factor at home."}, {"id": "b", "text": "He will wear his medical alert bracelet at school."}, {"id": "c", "text": "We will give him aspirin for pain in his elbows."}, {"id": "d", "text": "We bought him a soft toothbrush for his teeth."}]'::jsonb, '["c"]', 'Aspirin and NSAIDs increase bleeding risk and must be avoided in hemophilia. Home factor administration, a medical alert bracelet, and a soft toothbrush are all correct parts of hemophilia care.', false),
  ('heme_onc', 15, 'The nurse is preparing discharge teaching for the parents of a 5-year-old boy newly diagnosed with hemophilia A after a knee bleed. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Give aspirin for joint pain"}, {"id": "b", "text": "Use a soft toothbrush"}, {"id": "c", "text": "Avoid contact sports"}, {"id": "d", "text": "Apply heat to a bleeding joint"}, {"id": "e", "text": "Wear a medical alert bracelet"}]'::jsonb, '["b", "c", "e"]', 'Correct: a soft toothbrush (b), avoiding contact sports (c), and a medical alert bracelet (e) are hemophilia nursing care. Wrong: aspirin increases bleeding risk and must be avoided (a); a bleeding joint is treated with RICE, which uses ice, not heat (d).', true),
  ('heme_onc', 16, 'A 10-month-old boy who just started crawling has large bruises on both knees and bled for a long time after a minor cut. His maternal uncle has a bleeding disorder. The nurse anticipates that testing will MOST likely show a deficiency of which substance?', '[{"id": "a", "text": "Clotting factor IX"}, {"id": "b", "text": "Clotting factor VIII"}, {"id": "c", "text": "Platelets crowded out by blasts"}, {"id": "d", "text": "Iron from excess cow''s milk"}]'::jsonb, '["b"]', 'Easy bruising and prolonged bleeding in a male with an affected maternal relative fit X-linked hemophilia; factor VIII deficiency (Hemophilia A) is the most common type. Factor IX deficiency (Hemophilia B) is possible but less common.', false),
  ('heme_onc', 17, 'A 4-year-old has had low-grade fevers and fatigue for 3 weeks. The nurse notes pallor, petechiae on the legs, lymphadenopathy, and splenomegaly, and the child cries when the legs are moved because of bone pain. Which condition does the nurse MOST likely suspect?', '[{"id": "a", "text": "Hodgkin lymphoma"}, {"id": "b", "text": "Iron-deficiency anemia"}, {"id": "c", "text": "Neuroblastoma"}, {"id": "d", "text": "Acute lymphoblastic leukemia"}]'::jsonb, '["d"]', 'Fever, fatigue/pallor, petechiae, bone/joint pain, lymphadenopathy, and splenomegaly are the signs of ALL, caused by blasts crowding out normal marrow cells. Neuroblastoma causes bone pain but with an abdominal mass and raccoon eyes, not petechiae and splenomegaly.', false),
  ('heme_onc', 18, 'A 4-year-old is being evaluated for acute lymphoblastic leukemia. Which findings would the nurse expect as a result of immature WBCs crowding out normal marrow cells? Select all that apply.', '[{"id": "a", "text": "Hypertension and hematuria"}, {"id": "b", "text": "Petechiae and bruising"}, {"id": "c", "text": "Fatigue and pallor"}, {"id": "d", "text": "Periorbital ecchymosis"}, {"id": "e", "text": "Fever"}]'::jsonb, '["b", "c", "e"]', 'Correct: blasts crowd out platelets (petechiae/bruising, b), RBCs (fatigue/pallor, c), and normal WBCs, so fever is a presenting sign (e). Wrong: hypertension and hematuria are Wilms tumor signs (a); periorbital ecchymosis (raccoon eyes) is a neuroblastoma sign (d).', true),
  ('heme_onc', 19, 'A 6-year-old with ALL has petechiae on the trunk and oozing from the gums. Which action by the unlicensed assistive personnel (UAP) requires IMMEDIATE intervention by the nurse?', '[{"id": "a", "text": "Obtaining rectal temps for vital signs"}, {"id": "b", "text": "Giving a soft toothbrush for mouth care"}, {"id": "c", "text": "Telling the nurse about new petechiae"}, {"id": "d", "text": "Doing hand hygiene before entering"}]'::jsonb, '["a"]', 'Petechiae and gum bleeding indicate thrombocytopenia, so bleeding precautions include no rectal temps. A soft toothbrush, reporting petechiae, and hand hygiene are all correct care for a child with leukemia.', false),
  ('heme_onc', 20, 'A 7-year-old with ALL is neutropenic and has a central venous line for chemotherapy. The nurse observes a new graduate nurse preparing to change the central line dressing. Which action requires IMMEDIATE intervention?', '[{"id": "a", "text": "Performing hand hygiene before gathering supplies"}, {"id": "b", "text": "Explaining each step to the child before starting"}, {"id": "c", "text": "Using clean instead of sterile technique for line care"}, {"id": "d", "text": "Looking at the site before removing the old dressing"}]'::jsonb, '["c"]', 'Central line care for a child with leukemia requires sterile technique; clean gloves break that standard in a child already at infection risk. Hand hygiene, explaining the procedure, and inspecting the site are appropriate.', false),
  ('heme_onc', 21, 'A 6-year-old with ALL is neutropenic after chemotherapy and has a central venous line. Which actions by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Use clean technique when accessing the central line"}, {"id": "b", "text": "Perform hand hygiene before every contact"}, {"id": "c", "text": "Give the live vaccine scheduled for this week"}, {"id": "d", "text": "Monitor the child for fever"}, {"id": "e", "text": "Take rectal temperatures every 4 hours"}]'::jsonb, '["b", "d"]', 'Correct: hand hygiene (b) and monitoring for fever (d) are neutropenia precautions. Wrong: central line care requires sterile, not clean, technique (a); live vaccines are avoided (c); rectal temps are avoided because of bleeding risk from thrombocytopenia (e).', true),
  ('heme_onc', 22, 'A 9-year-old receiving chemotherapy for ALL has painful mouth sores and has eaten very little for 2 days. Which nursing intervention is MOST appropriate?', '[{"id": "a", "text": "Offer the crunchy snacks the child usually enjoys"}, {"id": "b", "text": "Provide oral hygiene and offer soft foods"}, {"id": "c", "text": "Hold all mouth care until the sores have healed"}, {"id": "d", "text": "Use a firm toothbrush to clear debris from the sores"}]'::jsonb, '["b"]', 'Mouth sores during chemotherapy are mucositis, managed with oral hygiene and soft foods. Holding mouth care removes needed oral hygiene, and crunchy foods or a firm brush injure the mucosa (a soft toothbrush is used for bleeding risk).', false),
  ('heme_onc', 23, 'A 5-year-old with ALL is pale, becomes tired after walking a few steps, and has a hemoglobin lower than yesterday''s value. A transfusion has been ordered. Which nursing action is the PRIORITY while the blood is being prepared?', '[{"id": "a", "text": "Encourage walking in the hall to build up endurance"}, {"id": "b", "text": "Move the child to a shared room for social contact"}, {"id": "c", "text": "Provide rest and monitor Hgb as ordered"}, {"id": "d", "text": "Offer crunchy, iron-rich snacks between the meals"}]'::jsonb, '["c"]', 'Anemia in leukemia is managed with rest, monitoring Hgb, and transfusion as ordered, so clustering care to allow rest is the priority. A shared room conflicts with reverse isolation for neutropenia, and walking increases fatigue.', false),
  ('heme_onc', 24, 'An 8-year-old with ALL is receiving chemotherapy through a central line, has painful mouth sores, and has a falling hemoglobin. Which interventions are appropriate? Select all that apply.', '[{"id": "a", "text": "Provide oral hygiene"}, {"id": "b", "text": "Offer soft foods"}, {"id": "c", "text": "Offer crunchy snacks to stimulate appetite"}, {"id": "d", "text": "Use sterile technique for central line care"}, {"id": "e", "text": "Monitor Hgb and transfuse as ordered"}]'::jsonb, '["a", "b", "d", "e"]', 'Correct: mucositis is managed with oral hygiene (a) and soft foods (b); central line care requires sterile technique (d); anemia is managed by monitoring Hgb and transfusing as ordered (e). Wrong: crunchy snacks injure the sore mucosa — soft foods are indicated (c).', true),
  ('heme_onc', 25, 'A 3-year-old is admitted after the parent noticed a firm mass on one side of the abdomen during bathing. The child''s blood pressure is elevated, and the urine is pink-tinged. Which nursing action is the PRIORITY?', '[{"id": "a", "text": "Place a sign on the bed: DO NOT PALPATE the abdomen"}, {"id": "b", "text": "Palpate the mass to estimate its size and location"}, {"id": "c", "text": "Apply a heating pad to the abdomen for comfort"}, {"id": "d", "text": "Check the mass for tenderness at each assessment"}]'::jsonb, '["a"]', 'A painless abdominal mass found during bathing with hypertension and hematuria suggests Wilms tumor; palpation can rupture the tumor and spread cancer cells, so palpation must be prevented. Checking the mass at each assessment repeats that danger.', false),
  ('heme_onc', 26, 'A 10-month-old has a firm abdominal mass, recent weight loss, and bruising around both eyes. The parent says the infant cries when the legs are handled. Which condition does the nurse MOST likely suspect?', '[{"id": "a", "text": "Wilms tumor"}, {"id": "b", "text": "Hemophilia A"}, {"id": "c", "text": "Neuroblastoma"}, {"id": "d", "text": "Hodgkin lymphoma"}]'::jsonb, '["c"]', 'An abdominal mass with weight loss, bone pain, and periorbital ecchymosis (raccoon eyes) in an infant fits neuroblastoma, the most common solid tumor in infants. Wilms tumor presents with a painless mass, hypertension, and hematuria rather than raccoon eyes.', false),
  ('heme_onc', 27, 'A 3-year-old is admitted for evaluation of a possible Wilms tumor. Which findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "Hypertension"}, {"id": "b", "text": "Periorbital ecchymosis"}, {"id": "c", "text": "Hematuria"}, {"id": "d", "text": "A mass that is painless"}, {"id": "e", "text": "A mass the parent noticed during bathing"}]'::jsonb, '["a", "c", "d", "e"]', 'Correct: Wilms tumor signs are an abdominal mass noticed by a parent during bathing (e) that is painless (d), hypertension (a), and hematuria (c). Wrong: periorbital ecchymosis (raccoon eyes) is a sign of neuroblastoma (b).', true),
  ('heme_onc', 28, 'The parent of a 14-month-old newly diagnosed with neuroblastoma of the adrenal gland cries, ''How did we not notice a tumor this big?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "This tumor grows only inside the kidney, where it can''t be felt."}, {"id": "b", "text": "Most of these tumors are found early at routine checkups."}, {"id": "c", "text": "You may have felt it during bathing if you had looked closely."}, {"id": "d", "text": "This tumor is often silent until it is large, so it''s found late."}]'::jsonb, '["d"]', 'Neuroblastoma is frequently diagnosed late because it is silent until large, which answers the parent without blame. It arises from the adrenal medulla or sympathetic nerve tissue, not the kidney (Wilms tumor).', false),
  ('heme_onc', 29, 'A 16-year-old has a painless, rubbery swelling in the neck, night sweats, and weight loss over 2 months. The adolescent asks how the diagnosis will be confirmed. Which response by the nurse is BEST?', '[{"id": "a", "text": "A biopsy of the node will look for Reed-Sternberg cells."}, {"id": "b", "text": "A blood test will measure your clotting factor levels."}, {"id": "c", "text": "The provider will palpate deeply to measure the node."}, {"id": "d", "text": "A blood test will check your red cells for HbS."}]'::jsonb, '["a"]', 'Painless, rubbery cervical node swelling with B symptoms suggests Hodgkin lymphoma, diagnosed by biopsy showing Reed-Sternberg cells. Clotting factor levels relate to hemophilia and HbS to sickle cell disease.', false),
  ('heme_onc', 30, 'A 17-year-old reports a painless, rubbery lump in the neck that has been growing for a month. Which additional findings should the nurse recognize as consistent with this presentation''s B symptoms? Select all that apply.', '[{"id": "a", "text": "Night sweats"}, {"id": "b", "text": "A tender, red lymph node"}, {"id": "c", "text": "Hematuria"}, {"id": "d", "text": "Weight loss"}, {"id": "e", "text": "Spoon-shaped nails"}]'::jsonb, '["a", "d"]', 'Correct: night sweats (a) and weight loss (d) are B symptoms of Hodgkin lymphoma, along with fever. Wrong: the node in Hodgkin lymphoma is painless, not tender (b); hematuria is a Wilms tumor sign (c); spoon-shaped nails are seen in severe iron-deficiency anemia (e).', true),
  ('heme_onc', 31, 'The nurse reviews crisis prevention with the parents of a 6-year-old with sickle cell disease. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "We''ll send a full water bottle to school every day."}, {"id": "b", "text": "Our family vacation will be at a high altitude."}, {"id": "c", "text": "He will wear a warm coat and hat in cold weather."}, {"id": "d", "text": "We''ll call the clinic if he gets a fever or cough."}]'::jsonb, '["b"]', 'High altitude is a sickle cell trigger, along with dehydration, cold, stress, infection, and low O₂, so a high-mountain trip needs more teaching. Fluids, warm clothing, and reporting signs of infection all reduce crisis risk.', false),
  ('heme_onc', 32, 'The parent of a 5-year-old with sickle cell disease asks why the child''s eyes often look yellow even on days the child feels well. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "Yellow eyes mean the liver is failing and needs urgent testing."}, {"id": "b", "text": "The yellow color comes from too much iron in the diet."}, {"id": "c", "text": "It is jaundice caused by the breakdown of red blood cells."}, {"id": "d", "text": "Yellow eyes are an early sign of acute chest syndrome."}]'::jsonb, '["c"]', 'Jaundice in sickle cell disease reflects RBC breakdown and is a listed sign of the disease. Acute chest syndrome presents as chest pain plus respiratory distress, not yellow eyes.', false),
  ('heme_onc', 33, 'The nurse receives report on four children. Which child should the nurse see FIRST?', '[{"id": "a", "text": "A 9-year-old with sickle cell disease who now has chest pain and respiratory distress"}, {"id": "b", "text": "A 4-year-old with Wilms tumor whose blood pressure remains elevated since admission"}, {"id": "c", "text": "A 15-year-old with Hodgkin lymphoma who had night sweats and a low-grade fever overnight"}, {"id": "d", "text": "A 3-year-old on ferrous sulfate whose parent reports the child''s stools are now dark"}]'::jsonb, '["a"]', 'Chest pain plus respiratory distress in sickle cell disease is acute chest syndrome, an emergency. Hypertension is an expected Wilms tumor sign, night sweats and fever are expected B symptoms, and dark stool is expected with iron.', false),
  ('heme_onc', 34, 'A 10-year-old with sickle cell disease is being treated for a pain crisis. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Yellow sclerae, unchanged since admission"}, {"id": "b", "text": "SpO₂ of 91% while at rest"}, {"id": "c", "text": "Hemoglobin low, matching the child''s baseline"}, {"id": "d", "text": "New chest pain with respiratory distress"}, {"id": "e", "text": "Bone pain that improved after the opioid"}]'::jsonb, '["b", "d"]', 'Correct: an SpO₂ of 91% is below 95% and requires O₂ (b); chest pain with respiratory distress is acute chest syndrome, an emergency (d). Wrong: jaundice from RBC breakdown (a) and chronic anemia (c) are expected signs of sickle cell disease; pain that improves after an opioid shows effective pain management (e).', true),
  ('heme_onc', 35, 'A 4-year-old receiving chemotherapy for ALL is seen in the clinic, and the immunization record shows a live vaccine is due today. Which action by the nurse is BEST?', '[{"id": "a", "text": "Give the live vaccine today to prevent infection"}, {"id": "b", "text": "Avoid live vaccines and notify the provider"}, {"id": "c", "text": "Give the vaccine, then begin reverse isolation"}, {"id": "d", "text": "Give half the dose to lower the reaction risk"}]'::jsonb, '["b"]', 'Live vaccines are avoided in a child with leukemia because of neutropenic infection risk, so the vaccine is held and the provider notified. Reverse isolation does not make a live vaccine safe.', false),
  ('heme_onc', 36, 'A 6-year-old with ALL is admitted with neutropenia after the latest chemotherapy cycle. Which room assignment is MOST appropriate?', '[{"id": "a", "text": "A room shared with a child who has pneumonia"}, {"id": "b", "text": "A room shared with a febrile child in sickle crisis"}, {"id": "c", "text": "A room by the playroom for group play activities"}, {"id": "d", "text": "A room with reverse isolation and hand hygiene"}]'::jsonb, '["d"]', 'Neutropenia creates infection risk, which is managed with reverse isolation and hand hygiene. Rooming with a child who has an infection or fever, or joining group play, increases exposure.', false),
  ('heme_onc', 37, 'The clinic nurse reviews the records of four infants at their 9-month visit. Based on the following histories, which infant is at HIGHEST risk for iron-deficiency anemia?', '[{"id": "a", "text": "Term birth; eats fortified cereals and red meat daily"}, {"id": "b", "text": "Term birth; eats legumes and leafy greens most days"}, {"id": "c", "text": "Premature birth; now drinks too much cow''s milk"}, {"id": "d", "text": "Term birth; has orange juice with iron-rich foods"}]'::jsonb, '["c"]', 'Premature birth (depleted iron stores) and too much cow''s milk replacing iron-rich food are both causes of iron-deficiency anemia. Fortified cereals, red meat, legumes, and leafy greens are iron-rich foods, and vitamin C enhances absorption.', false),
  ('heme_onc', 38, 'The parent of a 15-month-old with iron-deficiency anemia asks which foods to offer more often. Which foods should the nurse recommend? Select all that apply.', '[{"id": "a", "text": "Red meat"}, {"id": "b", "text": "Legumes"}, {"id": "c", "text": "Extra cow''s milk with meals"}, {"id": "d", "text": "Fortified cereals"}, {"id": "e", "text": "Leafy greens"}]'::jsonb, '["a", "b", "d", "e"]', 'Correct: red meat (a), legumes (b), fortified cereals (d), and leafy greens (e) are iron-rich foods to increase. Wrong: too much cow''s milk replaces iron-rich food and milk reduces iron absorption (c).', true),
  ('heme_onc', 39, 'The parents of a 4-year-old with Wilms tumor review the treatment plan with the nurse. Which statement by a parent indicates understanding?', '[{"id": "a", "text": "She will need a nephrectomy plus chemotherapy."}, {"id": "b", "text": "The tumor is checked by pressing on her belly every day."}, {"id": "c", "text": "She will take penicillin until age 5 to shrink the tumor."}, {"id": "d", "text": "She''ll need a biopsy for Reed-Sternberg cells first."}]'::jsonb, '["a"]', 'Wilms tumor is treated with post-op nephrectomy plus chemotherapy, with or without radiation. Pressing on the abdomen is prohibited because palpation can rupture the tumor; Reed-Sternberg cells relate to Hodgkin lymphoma.', false),
  ('heme_onc', 40, 'The nurse teaches the family of a 4-year-old with a suspected Wilms tumor. Which statements by family members indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "I''ll palpate his abdomen each night to check the tumor."}, {"id": "b", "text": "We''ll be gentle at bath time and not press on his belly."}, {"id": "c", "text": "Family members can palpate the mass to understand it."}, {"id": "d", "text": "Pressing on the tumor could make it rupture and spread."}, {"id": "e", "text": "We''ll avoid pressing on his belly when we pick him up."}]'::jsonb, '["a", "c"]', 'Correct (need teaching): palpating the abdomen nightly (a) and letting family members palpate the mass (c), which can rupture the tumor and spread cancer cells. Wrong (correct understanding): avoiding pressure at bath time (b) and knowing pressure can cause rupture and spread (d) are accurate; avoiding pressure when lifting him (e) is also correct.', true),
  ('heme_onc', 41, 'A mother whose son has hemophilia A asks the nurse about her two other children, a 3-year-old daughter and an infant son. Which statement by the mother indicates understanding?', '[{"id": "a", "text": "My daughter is the one more likely to have bleeding problems."}, {"id": "b", "text": "Hemophilia will affect my son and daughter in the same way."}, {"id": "c", "text": "Since my older son has it, my younger son cannot have it."}, {"id": "d", "text": "My infant son could be affected; my daughter could carry it."}]'::jsonb, '["d"]', 'Hemophilia is X-linked recessive: males are affected and females carry. The daughter is a possible carrier rather than the child more likely to bleed.', false),
  ('heme_onc', 42, 'A 7-year-old in sickle cell pain crisis is receiving IV fluids, an opioid, and O₂ for an SpO₂ of 93%. The child asks to walk laps around the unit to ''stay strong.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Walking will help the sickled cells move through your vessels."}, {"id": "b", "text": "You can walk laps as long as the oxygen tubing stays on."}, {"id": "c", "text": "Rest is needed now to decrease O₂ demand during a crisis."}, {"id": "d", "text": "Exercise will help your pain medicine work more quickly."}]'::jsonb, '["c"]', 'Rest decreases O₂ demand and is a vaso-occlusive crisis priority, together with hydration, pain management, and O₂. Activity raises O₂ demand even while O₂ is applied.', false),
  ('heme_onc', 43, 'A 6-year-old with hemophilia B is brought in with a deep muscle hematoma in the thigh after a fall. Which prescription should the nurse anticipate administering FIRST?', '[{"id": "a", "text": "Factor IX clotting factor concentrate"}, {"id": "b", "text": "Factor VIII clotting factor concentrate"}, {"id": "c", "text": "IV fluids to prevent sickling"}, {"id": "d", "text": "Ferrous sulfate given with orange juice"}]'::jsonb, '["a"]', 'Hemophilia B is a deficiency of factor IX, so a factor IX concentrate is given as prescribed for the bleed. Factor VIII is deficient in Hemophilia A, and IV fluids to prevent sickling are sickle cell crisis care.', false),
  ('heme_onc', 44, 'A 5-year-old with ALL has a low platelet count and bruises easily. Which instructions should the nurse give the parents? Select all that apply.', '[{"id": "a", "text": "Check temperatures rectally for accuracy"}, {"id": "b", "text": "Use a soft toothbrush for mouth care"}, {"id": "c", "text": "Brush with a firm toothbrush to prevent mouth sores"}, {"id": "d", "text": "Report new petechiae"}, {"id": "e", "text": "Expect new petechiae; they need no follow-up"}]'::jsonb, '["b", "d"]', 'Correct: bleeding precautions for thrombocytopenia include a soft toothbrush (b) and reporting petechiae (d). Wrong: rectal temps are avoided (a); a firm toothbrush increases bleeding (c); petechiae signal low platelets and must be reported, not ignored (e).', true),
  ('heme_onc', 45, 'The parent of a 3-year-old with sickle cell disease asks why the child takes penicillin every day even when not sick. Which response by the nurse is BEST?', '[{"id": "a", "text": "It treats the pain of a crisis so opioids are not needed."}, {"id": "b", "text": "It keeps the red cells hydrated so they do not sickle."}, {"id": "c", "text": "It is taken for life to keep the eyes from turning yellow."}, {"id": "d", "text": "It helps prevent infection and is given until age 5."}]'::jsonb, '["d"]', 'Prophylactic penicillin until age 5, along with vaccines, prevents infection — a sickle cell crisis trigger. Hydration, not penicillin, prevents sickling, and jaundice results from RBC breakdown.', false),
  ('heme_onc', 46, 'The nurse is reviewing ferrous sulfate teaching with the parent of a 2-year-old with iron-deficiency anemia. Which statements by the parent indicate understanding? Select all that apply.', '[{"id": "a", "text": "I''ll give it with a glass of orange juice."}, {"id": "b", "text": "I''ll mix it into his milk so it goes down easily."}, {"id": "c", "text": "His stool may turn dark, and that is expected."}, {"id": "d", "text": "I''ll give it at the same time as his antacid."}, {"id": "e", "text": "I''ll give it to him between meals."}]'::jsonb, '["a", "c", "e"]', 'Correct: vitamin C (orange juice) enhances absorption (a); dark stool is expected (c); ferrous sulfate is given between meals (e). Wrong: milk (b) and antacids (d) reduce absorption.', true),
  ('heme_onc', 47, 'A 7-year-old''s teacher reports poor concentration in class. The nurse notes pallor and spoon-shaped nails, and the parent says the child has been eating paper and dirt. Which condition does the nurse MOST likely suspect?', '[{"id": "a", "text": "Sickle cell disease"}, {"id": "b", "text": "Acute lymphoblastic leukemia"}, {"id": "c", "text": "Hodgkin lymphoma"}, {"id": "d", "text": "Iron-deficiency anemia"}]'::jsonb, '["d"]', 'Poor concentration, pallor, spoon-shaped nails (koilonychia), and pica are signs of iron-deficiency anemia. Leukemia also causes pallor but with fever, petechiae, and bone pain rather than koilonychia and pica.', false),
  ('heme_onc', 48, 'A 17-year-old newly diagnosed with Hodgkin lymphoma after a biopsy showed Reed-Sternberg cells asks, ''Do people actually survive this?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Chemotherapy, sometimes with radiation, has a high cure rate."}, {"id": "b", "text": "Surgery to remove the kidney is the treatment that cures it."}, {"id": "c", "text": "This cancer is usually found too late to be cured, sadly."}, {"id": "d", "text": "Daily penicillin keeps this cancer from ever coming back."}]'::jsonb, '["a"]', 'Hodgkin lymphoma is treated with chemotherapy with or without radiation and has a high cure rate. Nephrectomy is Wilms tumor treatment, and late diagnosis describes neuroblastoma.', false),
  ('heme_onc', 49, 'A 14-year-old boy with hemophilia A is learning to manage his own care before starting high school. Which statements by the adolescent indicate understanding? Select all that apply.', '[{"id": "a", "text": "I''ll keep wearing my medical alert bracelet."}, {"id": "b", "text": "I''ll join the wrestling team since I''m older now."}, {"id": "c", "text": "I can learn to give my own factor at home."}, {"id": "d", "text": "A hard toothbrush will keep my gums healthy."}, {"id": "e", "text": "My sister can''t carry it, since only boys get it."}]'::jsonb, '["a", "c"]', 'Correct: a medical alert bracelet (a) and administering factor at home (c) are hemophilia care. Wrong: wrestling is a contact sport, which is avoided (b); a soft toothbrush is used (d); hemophilia is X-linked recessive — males are affected, but females carry it (e).', true),
  ('heme_onc', 50, 'An 11-month-old is being evaluated for a tumor arising from the adrenal medulla. Which findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "Abdominal mass"}, {"id": "b", "text": "Weight loss"}, {"id": "c", "text": "Hematuria"}, {"id": "d", "text": "Bone pain"}, {"id": "e", "text": "Periorbital ecchymosis"}]'::jsonb, '["a", "b", "d", "e"]', 'Correct: neuroblastoma, often found in the abdomen (adrenal glands), presents with an abdominal mass (a), weight loss (b), bone pain (d), and periorbital ecchymosis or raccoon eyes (e). Wrong: hematuria is a sign of Wilms tumor (c).', true),
  ('infectious', 1, 'An unvaccinated 3-year-old has had a high fever, cough, runny nose, and red, watery eyes for 3 days. No rash is present, but the nurse notes tiny white dots on the inside of the cheeks. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Place the child in a private room and wear a surgical mask"}, {"id": "b", "text": "Place the child in a negative pressure private room with N95 use"}, {"id": "c", "text": "Place the child in contact precautions with a gown and gloves on"}, {"id": "d", "text": "Wait for the rash to appear before starting any isolation"}]'::jsonb, '["b"]', 'High fever, cough, coryza, conjunctivitis, and Koplik spots (an early diagnostic sign) indicate measles, which requires airborne precautions: N95 respirator and a negative pressure private room. A surgical mask is droplet PPE, and measles is contagious before the rash, so isolation should not wait.', false),
  ('infectious', 2, 'A 5-year-old has had chickenpox for 5 days. Most lesions are crusted, but two new vesicles appeared on the trunk this morning, and the child has been fever-free for 2 days. The parent asks when the child may return to kindergarten. Which response by the nurse is BEST?', '[{"id": "a", "text": "Your child may return now because most lesions have crusted."}, {"id": "b", "text": "Your child may return once all the lesions are crusted."}, {"id": "c", "text": "Your child may return 24 hours after the fever is gone."}, {"id": "d", "text": "Your child may return 5 days after the rash first appeared."}]'::jsonb, '["b"]', 'Varicella is contagious from 1–2 days before the rash until all lesions are crusted; new vesicles mean the child is still contagious. Being fever-free or a set number of days after the rash does not end the contagious period.', false),
  ('infectious', 3, 'The parent of a 4-year-old with an itchy vesicular rash appearing in crops calls and says, ''Her temperature was 101°F, so I gave her one of my aspirin tablets.'' Which response by the nurse is MOST important?', '[{"id": "a", "text": "Alternate the aspirin with diphenhydramine every 4 hours."}, {"id": "b", "text": "Continue the aspirin and add calamine lotion for her itching."}, {"id": "c", "text": "Do not give aspirin; use acetaminophen for her fever instead."}, {"id": "d", "text": "Aspirin is safe to give once the lesions have crusted over."}]'::jsonb, '["c"]', 'This child has varicella; aspirin must NEVER be given because of the risk of Reye''s syndrome, and acetaminophen is used for fever. Diphenhydramine and calamine lotion are appropriate for itch but do not make aspirin safe.', false),
  ('infectious', 4, 'The nurse reviews four children with newly diagnosed chickenpox, each with a low fever and itchy vesicular lesions in crops. For which child is the nurse MOST likely to anticipate a prescription for acyclovir?', '[{"id": "a", "text": "A healthy 4-year-old with many itchy lesions"}, {"id": "b", "text": "A 2-year-old with a low fever and new crops"}, {"id": "c", "text": "A 6-year-old who is immunocompromised"}, {"id": "d", "text": "An 8-year-old whose lesions are almost all crusted"}]'::jsonb, '["c"]', 'Immunocompromised children with varicella are high-risk and receive the antiviral acyclovir. Healthy children are managed with comfort care such as calamine lotion, cool baths, and acetaminophen for fever.', false),
  ('infectious', 5, 'A 6-year-old with chickenpox whose lesions are not yet crusted is admitted to a negative pressure private room. Which action by the unlicensed assistive personnel (UAP) requires IMMEDIATE intervention by the nurse?', '[{"id": "a", "text": "Applying calamine lotion to the itchy lesions"}, {"id": "b", "text": "Giving the child a cool bath for comfort"}, {"id": "c", "text": "Putting mittens on the child''s hands at night"}, {"id": "d", "text": "Entering the room wearing a surgical mask"}]'::jsonb, '["d"]', 'Varicella requires airborne precautions with an N95 respirator; a surgical mask is droplet PPE and does not protect the UAP. Calamine lotion, cool baths, and mittens to prevent scratching are appropriate varicella care.', false),
  ('infectious', 6, 'A 7-year-old developed painful swelling of both parotid glands on Wednesday morning. The child attended school on Monday and Tuesday with only a fever and earache. The parent says, ''He couldn''t have spread it at school because his face wasn''t swollen yet.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "You''re right; mumps is spread only after the parotid swelling begins."}, {"id": "b", "text": "Mumps is contagious 2 days before the swelling starts, so classmates were exposed."}, {"id": "c", "text": "You''re right; mumps is spread only through contact with skin lesions."}, {"id": "d", "text": "Mumps is contagious only after a rash appears, so no one at school was exposed."}]'::jsonb, '["b"]', 'Mumps is contagious from 2 days before to 5 days after the onset of parotid swelling, so classmates on Monday and Tuesday were exposed. Mumps is spread by droplets and has no rash.', false),
  ('infectious', 7, 'A 14-year-old boy with swollen, painful parotid glands that began 5 days ago now reports pain and swelling in the testes. Which complication is the nurse MOST likely to suspect?', '[{"id": "a", "text": "Oophoritis"}, {"id": "b", "text": "Myocarditis"}, {"id": "c", "text": "Reye''s syndrome"}, {"id": "d", "text": "Orchitis"}]'::jsonb, '["d"]', 'Mumps (swollen/painful parotid glands) can be complicated by orchitis in males. Oophoritis is the ovarian complication in females, and myocarditis is a toxin-mediated complication of diphtheria.', false),
  ('infectious', 8, 'A 4-year-old with a mild pink maculopapular rash, low fever, and swollen posterior cervical lymph nodes is diagnosed with rubella. The child''s mother is 10 weeks pregnant and unsure of her immunity. Which statement by the nurse is the PRIORITY?', '[{"id": "a", "text": "Get the MMR vaccine today so your baby will be protected."}, {"id": "b", "text": "Rubella is mild in pregnancy, so no follow-up is necessary."}, {"id": "c", "text": "Rubella is serious in pregnancy; contact your prenatal provider now."}, {"id": "d", "text": "Take acyclovir now to keep the virus from reaching your baby."}]'::jsonb, '["c"]', 'Rubella is serious in pregnancy because of congenital rubella syndrome (deafness, cataracts, heart defects, intellectual disability), so the mother needs prompt follow-up. MMR is a live vaccine contraindicated in pregnancy.', false),
  ('infectious', 9, 'An unvaccinated 5-year-old has a low fever, swollen posterior cervical lymph nodes, and a mild pink maculopapular rash that spread from the face to the feet over 3 days. Which isolation precaution should the nurse implement FIRST?', '[{"id": "a", "text": "Droplet precautions with a surgical mask"}, {"id": "b", "text": "Airborne precautions with an N95 respirator"}, {"id": "c", "text": "Contact precautions with a gown and gloves"}, {"id": "d", "text": "No isolation because the rash has already spread"}]'::jsonb, '["a"]', 'These findings indicate rubella, which requires droplet precautions with a surgical mask, and the child is isolated for 7 days after the rash appears. Airborne precautions are for measles and varicella, and contact precautions are for HFMD, impetigo, and RSV.', false),
  ('infectious', 10, 'A 6-week-old is brought to the emergency department after repeated coughing spells. The mother says the baby turns red, coughs many times in a row, and then ''stops breathing for a few seconds,'' but never makes a whooping sound. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The absence of a whoop rules out pertussis in this infant."}, {"id": "b", "text": "Infants with pertussis may have apnea instead of a whoop."}, {"id": "c", "text": "Apnea after coughing is an expected sign of fifth disease."}, {"id": "d", "text": "Pertussis causes apnea only after the vomiting phase ends."}]'::jsonb, '["b"]', 'Pertussis causes paroxysmal coughing spells followed by a whoop, but infants may have apnea instead of a whoop. A missing whoop therefore does not rule out pertussis in an infant.', false),
  ('infectious', 11, 'A 7-year-old hospitalized with pertussis started azithromycin 3 days ago, and the coughing spells are less frequent. The parent asks whether the mask and isolation sign can be removed today. Which response by the nurse is BEST?', '[{"id": "a", "text": "Isolation can stop now because the cough is improving."}, {"id": "b", "text": "Isolation continues until 24 hours after antibiotics started."}, {"id": "c", "text": "Isolation continues until 5 days after antibiotics started."}, {"id": "d", "text": "Isolation continues until all of the coughing has stopped."}]'::jsonb, '["c"]', 'A child with pertussis is isolated until 5 days after antibiotics are started; only 3 days have passed. The 24-hours-after-antibiotics rule applies to scarlet fever school exclusion, not pertussis.', false),
  ('infectious', 12, 'A woman who is 28 weeks pregnant with her second child says, ''I got the Tdap shot during my first pregnancy 2 years ago, so I don''t need it again.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "That''s right; the dose from your last pregnancy still protects this baby."}, {"id": "b", "text": "That''s right; Tdap is a live vaccine and is avoided during pregnancy."}, {"id": "c", "text": "Tdap is given only if the newborn will attend daycare in the first year."}, {"id": "d", "text": "Tdap is recommended in every pregnancy to help protect your newborn."}]'::jsonb, '["d"]', 'Tdap is given in every pregnancy to protect the newborn from pertussis. The live vaccines that are avoided in pregnancy are MMR and varicella, not Tdap.', false),
  ('infectious', 13, 'A 7-year-old has a bright red "slapped cheek" rash on the face and a lacy rash on the arms and trunk. The nurse reviews the household members who were with the child during the week before the rash appeared. Which household members require follow-up? Select all that apply.', '[{"id": "a", "text": "Healthy 10-year-old brother"}, {"id": "b", "text": "Aunt who is 20 weeks pregnant"}, {"id": "c", "text": "Healthy 35-year-old father"}, {"id": "d", "text": "Sister with hemolytic anemia"}, {"id": "e", "text": "Grandparent who is immunocompromised"}]'::jsonb, '["b", "d", "e"]', 'Fifth disease (parvovirus B19) is contagious before the rash and is dangerous in pregnancy (hydrops fetalis) (b), hemolytic anemia (aplastic crisis) (d), and immunocompromised people (e). Healthy children and adults (a, c) have a viral, self-limiting illness managed with supportive care only.', true),
  ('infectious', 14, 'A school nurse assesses a 6-year-old with a bright red "slapped cheek" rash and a lacy rash on the arms. The teacher wants the child kept home until the rash fades. Which response by the school nurse is BEST?', '[{"id": "a", "text": "Once this rash appears, the child is no longer contagious."}, {"id": "b", "text": "The child should stay home until the rash fades completely."}, {"id": "c", "text": "The child may return 24 hours after starting antibiotics."}, {"id": "d", "text": "The child should stay home until all lesions are crusted."}]'::jsonb, '["a"]', 'In fifth disease the child is contagious before the rash appears; once the rash appears, the child is no longer contagious. It is viral and self-limiting, so antibiotics are not used, and crusting of lesions applies to varicella.', false),
  ('infectious', 15, 'A 2-year-old has a fever, painful mouth sores, and a vesicular rash on the palms and soles and is refusing solid food. The nurse reviews home care with the parent. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "I''ll offer popsicles and other cool liquids during the day."}, {"id": "b", "text": "I''ll give acidic drinks like orange juice for the mouth sores."}, {"id": "c", "text": "I''ll give soft foods until the sores in the mouth feel better."}, {"id": "d", "text": "I''ll give acetaminophen or ibuprofen for the pain and fever."}]'::jsonb, '["b"]', 'This is hand-foot-and-mouth disease; acidic drinks such as orange juice should be avoided because of the painful mouth sores. Cool liquids, popsicles, soft foods, and acetaminophen or ibuprofen are all recommended.', false),
  ('infectious', 16, 'An unvaccinated 6-year-old has had a fever for 2 days and now has swelling in front of both ears. Which additional findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "Difficulty chewing"}, {"id": "b", "text": "Koplik spots inside the cheeks"}, {"id": "c", "text": "Earache"}, {"id": "d", "text": "Painful parotid glands"}, {"id": "e", "text": "Fever"}]'::jsonb, '["a", "c", "d", "e"]', 'Mumps causes swollen/painful parotid glands (d), fever (e), earache (c), and difficulty chewing (a). Koplik spots (b) are the early diagnostic sign of measles.', true),
  ('infectious', 17, 'A 3-year-old is admitted with fever, painful mouth sores, and a vesicular rash on the palms and soles. The child wears diapers. Which precautions should the nurse implement FIRST?', '[{"id": "a", "text": "Airborne precautions in a negative pressure room"}, {"id": "b", "text": "Droplet precautions with a surgical mask on entry"}, {"id": "c", "text": "Contact precautions, with care during diaper changes"}, {"id": "d", "text": "No isolation, because the rash is only on the extremities"}]'::jsonb, '["c"]', 'Hand-foot-and-mouth disease (coxsackievirus) requires contact precautions with a gown and gloves and spreads by contact and fecal-oral transmission, so diaper changes need care. Airborne precautions are for measles and varicella.', false),
  ('infectious', 18, 'A 4-year-old is recovering from hand-foot-and-mouth disease. The parent calls to ask whether the child can return to preschool tomorrow. Which finding indicates the child MOST likely meets the criteria to return?', '[{"id": "a", "text": "Fever gone for 1 day, blisters still oozing, drinking only fluids"}, {"id": "b", "text": "No fever, blisters healing, and eating normally"}, {"id": "c", "text": "Fever gone, completing 24 hours of antibiotic therapy"}, {"id": "d", "text": "Low fever, blisters crusted, and eating soft foods"}]'::jsonb, '["b"]', 'Children with HFMD are excluded from school until there is no fever, the blisters are healing, and the child is eating normally. Oozing blisters, drinking only fluids, or a persistent low fever do not meet the criteria; antibiotics are not used for this viral illness.', false),
  ('infectious', 19, 'A 5-year-old with a gray/white pseudomembrane over the tonsils and "bull neck" swelling has started diphtheria antitoxin. Which complications should the nurse monitor for? Select all that apply.', '[{"id": "a", "text": "Rheumatic fever"}, {"id": "b", "text": "Hydrops fetalis"}, {"id": "c", "text": "Myocarditis"}, {"id": "d", "text": "Airway obstruction"}, {"id": "e", "text": "Neuropathy"}]'::jsonb, '["c", "d", "e"]', 'Diphtheria complications are airway obstruction (d), myocarditis (c), and neuropathy (e), which are toxin-mediated. Rheumatic fever (a) is prevented by treating scarlet fever, and hydrops fetalis (b) is a risk of fifth disease in pregnancy.', true),
  ('infectious', 20, 'A nurse observes a student nurse caring for a 7-year-old who has a sore throat, low fever, malaise, and a gray/white membrane over the tonsils and pharynx. Which action by the student nurse requires IMMEDIATE intervention?', '[{"id": "a", "text": "Wearing a surgical mask when entering the room"}, {"id": "b", "text": "Assessing the neck for \"bull neck\" swelling"}, {"id": "c", "text": "Attempting to remove the pseudomembrane with gauze"}, {"id": "d", "text": "Monitoring the child''s breathing for obstruction"}]'::jsonb, '["c"]', 'This is diphtheria; the pseudomembrane bleeds when removed, so the nurse must NOT attempt to remove it. Droplet precautions with a surgical mask, assessing for bull neck, and monitoring for airway obstruction are appropriate.', false),
  ('infectious', 21, 'An unvaccinated 6-year-old has a sore throat, low fever, malaise, a gray/white pseudomembrane over the tonsils, and marked cervical lymph node swelling. Which prescription should the nurse anticipate as the PRIORITY?', '[{"id": "a", "text": "Penicillin alone for 10 days to prevent rheumatic fever"}, {"id": "b", "text": "Acyclovir because the infection is caused by a virus"}, {"id": "c", "text": "Diphtheria antitoxin plus erythromycin or penicillin"}, {"id": "d", "text": "Supportive care only, because the illness is self-limiting"}]'::jsonb, '["c"]', 'Diphtheria is treated with diphtheria antitoxin, which neutralizes the toxin, plus antibiotics (erythromycin or penicillin). Penicillin alone for 10 days is the scarlet fever regimen and does not neutralize the toxin.', false),
  ('infectious', 22, 'A 6-year-old has a sore throat and fever for 2 days. The provider suspects Group A Streptococcus with an erythrogenic toxin. Which findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "Red streaks in skin folds of the axillae and groin"}, {"id": "b", "text": "Pale area around the mouth"}, {"id": "c", "text": "Rough, red rash that feels like coarse sandpaper"}, {"id": "d", "text": "Tiny white dots inside the cheeks"}, {"id": "e", "text": "Bright red bumpy tongue after a white coating"}]'::jsonb, '["a", "b", "c", "e"]', 'Scarlet fever causes Pastia''s lines in skin folds (a), circumoral pallor (b), a sandpaper rash (c), and a strawberry tongue with a white coating on days 1–2 then a bright red bumpy tongue (e). Tiny white dots inside the cheeks (d) are Koplik spots of measles.', true),
  ('infectious', 23, 'A 7-year-old with a sandpaper rash, strawberry tongue, and fever started penicillin 3 days ago and now feels well. The parent asks, ''Why does he have to finish all 10 days?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "The full course prevents rheumatic fever, which can damage the heart."}, {"id": "b", "text": "The full course prevents Reye''s syndrome from developing later on."}, {"id": "c", "text": "The full course keeps the rash from turning into vesicles in crops."}, {"id": "d", "text": "The full course prevents orchitis, a common complication in boys."}]'::jsonb, '["a"]', 'Scarlet fever is treated with penicillin for 10 days to prevent rheumatic fever (cardiac damage). Reye''s syndrome is linked to aspirin use in varicella, and orchitis is a mumps complication.', false),
  ('infectious', 24, 'A 6-year-old with scarlet fever started amoxicillin yesterday morning and has had no fever since last night. The parent asks when the child may return to school. Which criterion is MOST appropriate for the nurse to use in answering?', '[{"id": "a", "text": "After all 10 days of the antibiotic course are completed"}, {"id": "b", "text": "After 24 hours of antibiotics and once the child is fever-free"}, {"id": "c", "text": "When the sandpaper rash and the strawberry tongue fade"}, {"id": "d", "text": "After 5 days of antibiotics, as with other droplet infections"}]'::jsonb, '["b"]', 'Children with scarlet fever are excluded from school until 24 hours after antibiotics are started and they are fever-free. Five days after antibiotics is the pertussis isolation rule, and the full 10-day course is for preventing rheumatic fever, not for school return.', false),
  ('infectious', 25, 'On day 1 of a sandpaper rash, a 5-year-old had a white coating on the tongue. On day 4 the parent calls, worried because the tongue is now bright red and bumpy. Which statement by the nurse reflects an expected finding?', '[{"id": "a", "text": "This change means the infection has spread to the mouth."}, {"id": "b", "text": "This change means the antibiotic is causing a reaction."}, {"id": "c", "text": "This change is the expected strawberry tongue pattern."}, {"id": "d", "text": "This change means the child now has mouth sores (stomatitis)."}]'::jsonb, '["c"]', 'In scarlet fever the strawberry tongue has a white coating on days 1–2 and then becomes a bright red bumpy tongue. Painful mouth sores (stomatitis) are a finding of hand-foot-and-mouth disease.', false),
  ('infectious', 26, 'A 10-month-old had a fever of 104°F for 4 days but stayed playful and fed well. This morning the fever dropped suddenly and a rose-colored rash appeared on the trunk. The parent fears the child is getting worse. Which response by the nurse is BEST?', '[{"id": "a", "text": "The rash means your child must now be kept in airborne isolation."}, {"id": "b", "text": "The rash means your child needs penicillin for 10 full days."}, {"id": "c", "text": "The rash means your child is now at the most contagious stage."}, {"id": "d", "text": "The rash means the illness is ending, not getting worse."}]'::jsonb, '["d"]', 'High fever for 3–5 days in a well-appearing infant, then a rose-colored rash on the trunk after the fever breaks, is roseola; caregivers are reassured that the rash means the illness is ending, not worsening. The child is contagious during the fever phase, not once the rash appears.', false),
  ('infectious', 27, 'A 10-year-old had an expanding circular rash with central clearing after a summer camping trip but was never treated. Months later the child is evaluated. Which findings would the nurse recognize as late disease? Select all that apply.', '[{"id": "a", "text": "Strawberry tongue"}, {"id": "b", "text": "Bell''s palsy (facial nerve)"}, {"id": "c", "text": "Migratory joint pain"}, {"id": "d", "text": "Carditis (AV block)"}, {"id": "e", "text": "Neurological symptoms"}]'::jsonb, '["b", "c", "d", "e"]', 'Untreated Lyme disease can progress to late disease with Bell''s palsy (b), migratory joint pain (c), carditis with AV block (d), and neurological symptoms (e). Strawberry tongue (a) is a scarlet fever finding.', true),
  ('infectious', 28, 'Ten days after a camping trip in a wooded area, a 9-year-old has fever, headache, fatigue, and joint aches and an expanding circular rash with central clearing on the thigh. Which finding is the nurse MOST likely documenting?', '[{"id": "a", "text": "Pastia''s lines from scarlet fever"}, {"id": "b", "text": "Lacy rash on the trunk from fifth disease"}, {"id": "c", "text": "Vesicles in crops from varicella"}, {"id": "d", "text": "Erythema migrans from Lyme disease"}]'::jsonb, '["d"]', 'A bull''s-eye rash (erythema migrans) with central clearing at a tick bite site appearing 3–30 days after the bite, plus flu-like symptoms, indicates Lyme disease. Pastia''s lines are red streaks in skin folds in scarlet fever, and fifth disease causes a lacy rash after slapped cheeks.', false),
  ('infectious', 29, 'The nurse teaches the parents of a 7-year-old who often plays in wooded areas about preventing Lyme disease. Which statement by the parents indicates a need for further teaching?', '[{"id": "a", "text": "We''ll check her for ticks after outdoor activities."}, {"id": "b", "text": "We''ll dress her in long clothing and use DEET."}, {"id": "c", "text": "If I find a tick, I''ll remove it promptly using fine tweezers."}, {"id": "d", "text": "If I find a tick, I''ll leave it until it falls off by itself."}]'::jsonb, '["d"]', 'Ticks should be removed promptly with tweezers, not left to fall off. Tick checks after outdoor activities, long clothing, and DEET are all correct Lyme disease prevention measures.', false),
  ('infectious', 30, 'A healthy 5-year-old is seen for kindergarten entry. The record shows DTaP at 2, 4, 6, and 15 months and at 4 years; Hib at 2, 4, 6, and 12 months; and MMR and varicella at 12 months. Which vaccines should the nurse anticipate giving today? Select all that apply.', '[{"id": "a", "text": "DTaP"}, {"id": "b", "text": "MMR"}, {"id": "c", "text": "Hib"}, {"id": "d", "text": "Varicella"}, {"id": "e", "text": "HPV"}]'::jsonb, '["b", "d"]', 'MMR (b) and varicella (d) are given at 12–15 months and 4–6 years, so this child needs the second dose of each. DTaP (a) is complete with the 4–6-year dose already given, Hib (c) ends at 12–15 months, and HPV (e) starts at 11–12 years (can start at 9).', true),
  ('infectious', 31, 'During flu season, the nurse prepares to give influenza vaccine to four children at a clinic. For which child is a 2-dose schedule this season MOST appropriate?', '[{"id": "a", "text": "7-year-old receiving influenza vaccine for the first time"}, {"id": "b", "text": "10-year-old receiving influenza vaccine for the first time"}, {"id": "c", "text": "8-year-old who received influenza vaccine last year"}, {"id": "d", "text": "12-year-old who received influenza vaccine last year"}]'::jsonb, '["a"]', 'Influenza vaccine is given annually from 6 months, with 2 doses for first-time recipients younger than 9 years. The 10-year-old is a first-time recipient but is 9 or older, and the other children have received the vaccine before.', false),
  ('infectious', 32, 'A 16-year-old girl receives her first HPV vaccine dose today. The parent asks how many doses she will need in total. Which response by the nurse is BEST?', '[{"id": "a", "text": "2 doses, because the series is usually started at 11–12 years"}, {"id": "b", "text": "1 dose, because she is already in her teens"}, {"id": "c", "text": "2 doses, because she is younger than 18 years"}, {"id": "d", "text": "3 doses, because she is starting at 15 years or older"}]'::jsonb, '["d"]', 'HPV vaccine requires 2 doses if started before 15 years and 3 doses if started at 15 years or older; she is starting at 16. The 11–12-year age is the routine start, not the basis for her dose count.', false),
  ('infectious', 33, 'A 15-month-old who is immunocompromised from chemotherapy is seen for routine immunizations. Which vaccines should the nurse question before giving them? Select all that apply.', '[{"id": "a", "text": "MMR"}, {"id": "b", "text": "DTaP"}, {"id": "c", "text": "Varicella"}, {"id": "d", "text": "Hib"}, {"id": "e", "text": "Inactivated influenza injection"}]'::jsonb, '["a", "c"]', 'MMR (a) and varicella (c) are live vaccines that are avoided in immunocompromised children. DTaP (b), Hib (d), and an inactivated influenza injection (e) are not listed among the live vaccines with these restrictions.', true),
  ('infectious', 34, 'A healthy 15-month-old''s record shows DTaP at 2, 4, and 6 months; Hib at 2, 4, 6, and 12 months; and MMR and varicella at 12 months. Which vaccine is the nurse MOST likely to give at this visit?', '[{"id": "a", "text": "Fourth dose of DTaP"}, {"id": "b", "text": "Second dose of MMR"}, {"id": "c", "text": "Fifth dose of Hib"}, {"id": "d", "text": "Second dose of varicella"}]'::jsonb, '["a"]', 'DTaP is given at 2, 4, 6 months, 15–18 months, and 4–6 years, so the fourth dose is due now. The second MMR and varicella doses are due at 4–6 years, and the Hib series ends at 12–15 months.', false),
  ('infectious', 35, 'A 4-year-old with a low fever and itchy vesicular lesions in crops, some not yet crusted, is admitted for poor oral intake. Which precautions should the nurse implement? Select all that apply.', '[{"id": "a", "text": "N95 respirator for staff entering the room"}, {"id": "b", "text": "Negative pressure private room"}, {"id": "c", "text": "Gown and gloves"}, {"id": "d", "text": "Surgical mask instead of a respirator"}, {"id": "e", "text": "Cohort with a child who has mumps"}]'::jsonb, '["a", "b", "c"]', 'Varicella requires airborne precautions: an N95 respirator (a), a negative pressure private room (b), and gown and gloves (c). A surgical mask (d) is droplet PPE, and cohorting with a child who has mumps (e), a droplet infection, is not appropriate for a child needing a private airborne room.', true),
  ('infectious', 36, 'Only one negative pressure private room is available on the pediatric unit, and four children are waiting for admission. Which child is it MOST appropriate for the nurse to assign to this room?', '[{"id": "a", "text": "Child with swollen, painful parotid glands and earache"}, {"id": "b", "text": "Child with paroxysmal coughing spells and an inspiratory whoop"}, {"id": "c", "text": "Child with an itchy vesicular rash in crops and a low fever"}, {"id": "d", "text": "Child with a sandpaper rash and a strawberry tongue"}]'::jsonb, '["c"]', 'An itchy vesicular rash in crops with low fever is varicella, which requires airborne precautions in a negative pressure private room. Mumps, pertussis, and scarlet fever are droplet infections that do not need a negative pressure room.', false),
  ('infectious', 37, 'An unvaccinated 2-year-old has had a high fever for 3 days, and the provider suspects rubeola. Which findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "Slapped cheek rash on the face"}, {"id": "b", "text": "Vesicles on the palms and soles"}, {"id": "c", "text": "Coryza (runny nose)"}, {"id": "d", "text": "Koplik spots inside the cheeks"}, {"id": "e", "text": "Conjunctivitis"}]'::jsonb, '["c", "d", "e"]', 'Measles (rubeola) causes high fever, cough, coryza (c), conjunctivitis (e), and Koplik spots (d), followed by a maculopapular rash. A slapped cheek rash (a) is fifth disease, and vesicles on the palms and soles (b) are hand-foot-and-mouth disease.', true),
  ('infectious', 38, 'A 3-year-old with measles has had a high fever, cough, coryza, and conjunctivitis, and Koplik spots were seen yesterday. Which rash pattern should the nurse expect NEXT?', '[{"id": "a", "text": "Rose-colored rash on the trunk after the fever breaks"}, {"id": "b", "text": "Vesicular rash appearing in crops on the trunk"}, {"id": "c", "text": "Bright red slapped cheeks, then a lacy rash"}, {"id": "d", "text": "Maculopapular rash spreading head-to-toe"}]'::jsonb, '["d"]', 'In measles, Koplik spots are followed by a maculopapular rash spreading head-to-toe. A rose-colored rash after the fever breaks is roseola, and vesicles in crops are varicella.', false),
  ('infectious', 39, 'The nurse teaches the parent of a 3-year-old with chickenpox who keeps scratching the lesions and has a low fever. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Apply calamine lotion to itchy areas"}, {"id": "b", "text": "Give cool baths"}, {"id": "c", "text": "Trim nails or use mittens"}, {"id": "d", "text": "Give aspirin for the fever"}, {"id": "e", "text": "Give diphenhydramine for itch"}]'::jsonb, '["a", "b", "c", "e"]', 'Varicella care includes calamine lotion (a), cool baths (b), trimming nails or using mittens (c), and diphenhydramine for itch (e), with acetaminophen for fever. Aspirin (d) is NEVER given because of Reye''s syndrome.', true),
  ('infectious', 40, 'A 9-month-old has had an abrupt fever of 104°F for 2 days but is playful and feeding well, and the provider suspects roseola (HHV-6). Which complication is MOST important for the nurse to teach the parent to watch for during the fever phase?', '[{"id": "a", "text": "Febrile seizures"}, {"id": "b", "text": "Rheumatic fever (cardiac)"}, {"id": "c", "text": "Aplastic crisis"}, {"id": "d", "text": "Bell''s palsy"}]'::jsonb, '["a"]', 'Roseola can cause febrile seizures due to the rapid fever spike. Rheumatic fever follows untreated scarlet fever, aplastic crisis is a fifth disease risk in hemolytic anemia, and Bell''s palsy is a late Lyme disease finding.', false),
  ('infectious', 41, 'A 9-year-old has had 2 weeks of paroxysmal coughing spells, each followed by a high-pitched inspiratory whoop and vomiting after coughing. Which medication should the nurse anticipate as MOST appropriate?', '[{"id": "a", "text": "Acyclovir"}, {"id": "b", "text": "Azithromycin"}, {"id": "c", "text": "Diphtheria antitoxin"}, {"id": "d", "text": "Penicillin for 10 days"}]'::jsonb, '["b"]', 'Paroxysmal coughing, an inspiratory whoop, and post-cough vomiting indicate pertussis (Bordetella pertussis), treated with azithromycin. Penicillin for 10 days treats scarlet fever, and antitoxin is for diphtheria.', false),
  ('infectious', 42, 'The charge nurse is assigning rooms for five children admitted overnight. Which children should be placed on contact precautions? Select all that apply.', '[{"id": "a", "text": "Child with impetigo"}, {"id": "b", "text": "Child with paroxysmal cough and a whoop"}, {"id": "c", "text": "Child with RSV"}, {"id": "d", "text": "Child with painful mouth sores and vesicular rash on palms and soles"}, {"id": "e", "text": "Child with swollen, painful parotid glands"}]'::jsonb, '["a", "c", "d"]', 'Contact precautions are used for RSV (c), impetigo (a), and hand-foot-and-mouth disease (d). Pertussis (b) and mumps (e) require droplet precautions.', true),
  ('infectious', 43, 'A 5-year-old''s rubella rash appeared on Monday. On Thursday the rash has faded, and the parent asks to take the child to a family gathering where a pregnant relative will be present. Which response by the nurse is BEST?', '[{"id": "a", "text": "Keep your child isolated until 7 days after the rash appeared."}, {"id": "b", "text": "Your child is no longer contagious because the rash has faded."}, {"id": "c", "text": "Your child can go once fever-free for at least 24 hours."}, {"id": "d", "text": "Your child can go after 5 days of antibiotic treatment."}]'::jsonb, '["a"]', 'A person with rubella is isolated for 7 days after the rash appears (contagious 5–7 days after the rash), and rubella is serious in pregnancy. Only 3 days have passed, and a faded rash does not end the contagious period.', false),
  ('infectious', 44, 'During her first trimester, a newborn''s mother had a mild pink rash, low fever, and swollen posterior cervical lymph nodes. Which findings should the nurse assess for in the newborn? Select all that apply.', '[{"id": "a", "text": "Hydrops fetalis"}, {"id": "b", "text": "Apnea instead of a whoop"}, {"id": "c", "text": "Heart defects"}, {"id": "d", "text": "Cataracts"}, {"id": "e", "text": "Bull neck swelling"}]'::jsonb, '["c", "d"]', 'Rubella in pregnancy causes congenital rubella syndrome, including cataracts (d) and heart defects (c), as well as deafness and intellectual disability. Hydrops fetalis (a) is the pregnancy risk of fifth disease, apnea instead of a whoop (b) is infant pertussis, and bull neck (e) is diphtheria.', true),
  ('infectious', 45, 'A 14-month-old in daycare had 4 days of high fever while acting well; yesterday the fever broke and a rose-colored rash appeared on the trunk. The daycare director asks when the child could have spread the illness. Which response by the nurse is BEST?', '[{"id": "a", "text": "The child was contagious during the fever phase, before the rash."}, {"id": "b", "text": "The child is contagious only now that the rash has appeared."}, {"id": "c", "text": "The child will be contagious until the rash has crusted over."}, {"id": "d", "text": "The child was never contagious, since this rash is from a tick."}]'::jsonb, '["a"]', 'In roseola (HHV-6), the child is contagious during the fever phase; the rash appears after the fever drops and fades within 1–3 days. Crusting applies to varicella lesions, and tick-borne rash describes Lyme disease.', false),
  ('infectious', 46, 'An 8-year-old who never received the DTaP series has had a cough for 10 days. Which findings would support the suspected bacterial infection with Bordetella pertussis? Select all that apply.', '[{"id": "a", "text": "Paroxysmal coughing spells"}, {"id": "b", "text": "High-pitched inspiratory whoop"}, {"id": "c", "text": "Gray/white pseudomembrane over the tonsils"}, {"id": "d", "text": "Vomiting after coughing"}, {"id": "e", "text": "Koplik spots inside the cheeks"}]'::jsonb, '["a", "b", "d"]', 'Pertussis causes paroxysmal coughing spells (a), then a high-pitched inspiratory whoop (b), then vomiting after coughing (d). A gray/white pseudomembrane (c) is diphtheria, and Koplik spots (e) are measles.', true),
  ('infectious', 47, 'The parent of a healthy 5-year-old with a bright red slapped cheek rash and a lacy rash on the trunk asks the nurse for antibiotics. Which response by the nurse is BEST?', '[{"id": "a", "text": "Antibiotics for 10 days are needed to prevent rheumatic fever."}, {"id": "b", "text": "It is viral and self-limiting; supportive care only is needed."}, {"id": "c", "text": "An antiviral such as acyclovir is needed to shorten the illness."}, {"id": "d", "text": "Antibiotics are needed for 5 days before your child returns."}]'::jsonb, '["b"]', 'Fifth disease (parvovirus B19) is viral and self-limiting, so only supportive care is needed in a healthy child. Ten days of antibiotics to prevent rheumatic fever applies to scarlet fever, and acyclovir is for high-risk varicella.', false),
  ('infectious', 48, 'The nurse is preparing isolation signs for five newly admitted children. Which children require droplet precautions with a surgical mask? Select all that apply.', '[{"id": "a", "text": "Child with swollen, painful parotid glands"}, {"id": "b", "text": "Child with paroxysmal cough and inspiratory whoop"}, {"id": "c", "text": "Child with Koplik spots and a high fever"}, {"id": "d", "text": "Child with a gray/white pseudomembrane"}, {"id": "e", "text": "Child with mild pink rash and posterior node swelling"}]'::jsonb, '["a", "b", "d", "e"]', 'Droplet precautions (surgical mask) are used for mumps (a), pertussis (b), diphtheria (d), and rubella (e). Koplik spots with high fever (c) indicate measles, which requires airborne precautions with an N95 respirator.', true),
  ('infectious', 49, 'A 6-year-old with a sore throat, low fever, and malaise has a gray/white pseudomembrane over the tonsils and pharynx with a "bull neck" appearance. Which isolation sign is MOST appropriate for the nurse to post on the door?', '[{"id": "a", "text": "Droplet precautions"}, {"id": "b", "text": "Airborne precautions"}, {"id": "c", "text": "Contact precautions"}, {"id": "d", "text": "Standard precautions only"}]'::jsonb, '["a"]', 'These findings indicate diphtheria, which is managed with droplet precautions along with antitoxin and antibiotics. Airborne precautions are for measles and varicella, and contact precautions are for HFMD, impetigo, and RSV.', false),
  ('infectious', 50, 'A 12-month-old is evaluated for a suspected human herpesvirus-6 (HHV-6) infection. Which findings are consistent with this diagnosis? Select all that apply.', '[{"id": "a", "text": "Abrupt high fever lasting 3–5 days"}, {"id": "b", "text": "Child appears surprisingly well despite fever"}, {"id": "c", "text": "Itchy vesicular rash appearing in crops"}, {"id": "d", "text": "Rose-colored rash after the fever drops"}, {"id": "e", "text": "Rash that begins on the face and spreads down"}]'::jsonb, '["a", "b", "d"]', 'Roseola causes an abrupt high fever lasting 3–5 days (a) in a child who appears surprisingly well (b), followed by a rose-colored rash when the fever drops (d). The roseola rash is non-itchy, unlike the itchy vesicles in crops of varicella (c), and it starts on the trunk first rather than the face (e).', true),
  ('renal', 1, 'A 5-month-old is brought to the clinic with a fever that has no obvious source. The parent reports irritability, poor feeding, and diapers that smell foul. The provider orders a urinalysis and urine culture. Which collection method is BEST for the nurse to use?', '[{"id": "a", "text": "Apply a urine bag to the perineum and wait for a void"}, {"id": "b", "text": "Collect urine by catheter for an accurate culture"}, {"id": "c", "text": "Wait until the infant can give a clean-catch sample"}, {"id": "d", "text": "Squeeze urine from a wet diaper into a sterile cup"}]'::jsonb, '["b"]', 'Fever without a source in an infant suggests a UTI, and urine is collected by catheter or suprapubic aspiration, not a bag specimen, for an accurate culture in infants. A bag specimen is the tempting choice but does not give an accurate culture.', false),
  ('renal', 2, 'An 8-month-old girl has a urinalysis and urine culture that confirm E. coli in the urine. Which findings would the nurse expect in this infant? Select all that apply.', '[{"id": "a", "text": "Fever without an obvious source"}, {"id": "b", "text": "Poor feeding"}, {"id": "c", "text": "Periorbital edema on waking"}, {"id": "d", "text": "Vomiting"}, {"id": "e", "text": "Foul-smelling urine"}]'::jsonb, '["a", "b", "d", "e"]', 'Infants and young children with a UTI may not show classic urinary symptoms; infant signs are fever without an obvious source, irritability, poor feeding, vomiting, and foul-smelling urine — so fever, poor feeding, vomiting and foul-smelling urine are expected. Periorbital edema on waking is a sign of acute glomerulonephritis, not UTI.', true),
  ('renal', 3, 'A 7-year-old was treated for strep throat 2 weeks ago and now has cola-colored urine, periorbital edema on waking, and decreased urine output. Which nursing assessment is the PRIORITY?', '[{"id": "a", "text": "Testing the urine for massive proteinuria"}, {"id": "b", "text": "Assessing for scrotal edema and ascites"}, {"id": "c", "text": "Monitoring the blood pressure"}, {"id": "d", "text": "Checking the skin for impetigo lesions"}]'::jsonb, '["c"]', 'Cola-colored urine, periorbital edema and oliguria after strep throat indicate acute glomerulonephritis, which causes hypertension, so monitoring BP is the priority. Massive proteinuria and scrotal edema/ascites belong to nephrotic syndrome; AGN has only mild proteinuria.', false),
  ('renal', 4, 'A 3-year-old has developed generalized edema over the past week, including scrotal swelling and ascites. The urine is frothy, the blood pressure is normal, and laboratory results show hypoalbuminemia and hyperlipidemia. Which medication is the nurse MOST likely to administer?', '[{"id": "a", "text": "Prednisone"}, {"id": "b", "text": "An antihypertensive"}, {"id": "c", "text": "An oral antibiotic"}, {"id": "d", "text": "Desmopressin (DDAVP)"}]'::jsonb, '["a"]', 'Massive proteinuria (frothy urine), severe edema, hypoalbuminemia, hyperlipidemia and normal BP indicate nephrotic syndrome, which is treated with corticosteroids (prednisone); minimal change disease responds well to steroids. Antihypertensives are used in AGN, where BP is high.', false),
  ('renal', 5, 'A 9-year-old is admitted 2 weeks after an episode of impetigo with puffy eyes on waking. The nurse suspects post-streptococcal kidney inflammation. Which additional findings support this suspicion? Select all that apply.', '[{"id": "a", "text": "Tea-colored urine"}, {"id": "b", "text": "Normal to low blood pressure"}, {"id": "c", "text": "Hypertension"}, {"id": "d", "text": "Massive proteinuria with frothy urine"}, {"id": "e", "text": "Decreased urine output"}]'::jsonb, '["a", "c", "e"]', 'AGN follows strep throat or impetigo and causes hematuria (tea-, cola- or rust-colored urine), periorbital edema on waking, hypertension, decreased urine output (oliguria), and only mild proteinuria — so tea-colored urine, hypertension and decreased output fit. Normal to low BP and massive proteinuria with frothy urine are nephrotic syndrome findings.', true),
  ('renal', 6, 'The parent of a 4-year-old with severe generalized edema, frothy urine, and hypoalbuminemia asks, "Why is his whole body so swollen?" Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"Strep antibodies are inflaming his kidneys and raising his blood pressure.\""}, {"id": "b", "text": "\"His kidneys are holding on to salt because his blood pressure is high.\""}, {"id": "c", "text": "\"A tumor in his kidney is pressing on the vessels and blocking flow.\""}, {"id": "d", "text": "\"Protein lost in his urine lowers oncotic pressure, so fluid leaks out.\""}]'::jsonb, '["d"]', 'In nephrotic syndrome, massive protein loss causes hypoalbuminemia; low protein means low oncotic pressure, so fluid leaks and causes edema. Strep-related inflammation with high BP describes AGN, in which edema is milder.', false),
  ('renal', 7, 'The nurse reviews prevention teaching with the parent of a 5-year-old girl who has had two urinary tract infections this year. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"She can have bubble baths as long as she rinses off well.\""}, {"id": "b", "text": "\"I''ll teach her to wipe front to back after using the toilet.\""}, {"id": "c", "text": "\"I''ll buy cotton underwear and remind her to empty her bladder.\""}, {"id": "d", "text": "\"We''ll set regular toilet times and make sure she drinks enough.\""}]'::jsonb, '["a"]', 'UTI prevention includes avoiding bubble baths, so this statement needs correction. Wiping front to back, cotton underwear, complete voiding, regular toilet schedules and adequate fluid intake are all correct prevention measures.', false),
  ('renal', 8, 'At birth, a newborn boy is found to have the urethral opening on the underside of the penis. Which information should the nurse include when teaching the parents? Select all that apply.', '[{"id": "a", "text": "The opening on the top of the penis is hypospadias"}, {"id": "b", "text": "Do not circumcise the baby before the repair"}, {"id": "c", "text": "The foreskin may be needed for the reconstruction"}, {"id": "d", "text": "Circumcision now will make the later repair easier"}, {"id": "e", "text": "Surgical repair is usually done at 6–12 months"}]'::jsonb, '["b", "c", "e"]', 'An opening on the underside (ventral surface) is hypospadias, treated with surgery at 6–12 months; parents are taught at birth not to circumcise because the foreskin may be needed for the reconstructive surgery — so those three are correct. An opening on the top (dorsal surface) is epispadias, and circumcision would eliminate tissue needed for repair rather than make it easier.', true),
  ('renal', 9, 'While bathing her 3-year-old, a parent felt a smooth, firm mass on one side of the child''s abdomen. The child otherwise appears well. When the child is admitted for evaluation, which action should the nurse take FIRST?', '[{"id": "a", "text": "Palpate the mass gently to estimate its size and borders"}, {"id": "b", "text": "Do not palpate, and educate all caregivers and staff"}, {"id": "c", "text": "Obtain a urine specimen by catheter for a culture"}, {"id": "d", "text": "Begin a fluid restriction and a low sodium diet"}]'::jsonb, '["b"]', 'An asymptomatic, smooth, firm, unilateral mass found while bathing a 3-year-old suggests Wilms tumor, so the abdomen must never be palpated; manipulation can cause tumor rupture and seed cancer cells, and all caregivers and staff are educated. Gently palpating to measure the mass is exactly what must be avoided.', false),
  ('renal', 10, 'A 2-month-old born at 32 weeks'' gestation has an empty left scrotal sac, and the testis cannot be felt in the scrotum. The parent asks whether surgery is needed right away. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Surgery is needed right now to prevent infertility and testicular cancer.\""}, {"id": "b", "text": "\"Surgery will be done at 6–12 months, the same as for hypospadias.\""}, {"id": "c", "text": "\"It''s common in premature infants and may self-correct by 6 months.\""}, {"id": "d", "text": "\"If it still hasn''t come down by school age, surgery will be planned.\""}]'::jsonb, '["c"]', 'Cryptorchidism is common in premature infants and may self-correct by 6 months, so immediate surgery is not needed. Waiting until school age is wrong because orchiopexy is recommended by age 1 year.', false),
  ('renal', 11, 'A 5-year-old with nephrotic syndrome is receiving prednisone and has severe generalized edema. The charge nurse is assigning rooms. Which roommate is MOST appropriate for this child?', '[{"id": "a", "text": "A 6-year-old recovering from a nephrectomy"}, {"id": "b", "text": "A 4-year-old admitted with fever and a cough"}, {"id": "c", "text": "A 7-year-old with impetigo on both legs"}, {"id": "d", "text": "A 5-year-old with a draining wound infection"}]'::jsonb, '["a"]', 'A child with nephrotic syndrome on prednisone is immunosuppressed, so care includes preventing infection; a post-nephrectomy child has no infection. The children with a fever and cough, impetigo, or a wound infection pose an infection risk.', false),
  ('renal', 12, 'A 6-year-old with acute glomerulonephritis has periorbital edema, oliguria, and an elevated blood pressure. Which prescription requires follow-up with the health care provider?', '[{"id": "a", "text": "Daily weight and I&Os"}, {"id": "b", "text": "Low sodium diet"}, {"id": "c", "text": "Bedrest during the acute phase"}, {"id": "d", "text": "Encourage fluids liberally"}]'::jsonb, '["d"]', 'AGN treatment includes fluid restriction, so an order to encourage fluids in a child with oliguria, edema and hypertension should be questioned. Daily weight, I&Os, a low sodium diet and bedrest during the acute phase are all expected AGN orders.', false),
  ('renal', 13, 'A 4-year-old with minimal change disease has anasarca and is receiving prednisone and a diuretic. Which interventions should the nurse include in the plan of care? Select all that apply.', '[{"id": "a", "text": "Liberal fluid intake to flush the kidneys"}, {"id": "b", "text": "Daily weight"}, {"id": "c", "text": "Skin care for edematous areas"}, {"id": "d", "text": "Accurate I&Os"}, {"id": "e", "text": "Measures to prevent infection"}]'::jsonb, '["b", "c", "d", "e"]', 'Nephrotic syndrome care includes daily weight, I&Os, skin care for edematous areas, and preventing infection because the child is immunosuppressed — so those four are correct. Liberal fluids are wrong because severe cases call for albumin IV with fluid restriction.', true),
  ('renal', 14, 'Two children are admitted with periorbital edema. One had strep throat 2 weeks ago; the other has minimal change disease. Which finding is the nurse MOST likely to see in the child with minimal change disease but not in the other child?', '[{"id": "a", "text": "Cola-colored urine with hematuria"}, {"id": "b", "text": "Elevated blood pressure"}, {"id": "c", "text": "Mild proteinuria"}, {"id": "d", "text": "Frothy urine and anasarca"}]'::jsonb, '["d"]', 'Minimal change disease causes nephrotic syndrome, with massive proteinuria (frothy urine) and severe edema (anasarca). Cola-colored hematuria, high BP and mild proteinuria are features of post-strep AGN.', false),
  ('renal', 15, 'A 7-year-old boy has never been consistently dry at night, and his urinalysis is normal. Which measures should the nurse teach the family as the INITIAL approach? Select all that apply.', '[{"id": "a", "text": "Limit fluids 2 hours before bedtime"}, {"id": "b", "text": "Void before sleep"}, {"id": "c", "text": "Motivational charts for dry nights"}, {"id": "d", "text": "Desmopressin (DDAVP) every night"}, {"id": "e", "text": "Bedwetting alarm"}]'::jsonb, '["a", "b", "c", "e"]', 'This is primary enuresis; first-line treatment is limiting fluids 2 hours before bedtime, voiding before sleep, positive reinforcement with motivational charts, and bedwetting alarms — so those four are correct. Desmopressin (DDAVP) is pharmacological treatment used only if needed, not the initial approach.', true),
  ('renal', 16, 'An 8-year-old girl who had been dry at night for over a year has started wetting the bed again during the past month. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Teach the parents to limit fluids 2 hours before bed"}, {"id": "b", "text": "Evaluate for stress, a UTI, and diabetes mellitus"}, {"id": "c", "text": "Reassure the parents this is normal until age 5"}, {"id": "d", "text": "Ask the provider about starting imipramine"}]'::jsonb, '["b"]', 'A child dry for more than 6 months who starts wetting again has secondary enuresis, which is evaluated for stress, UTI, and DM before treatment. Limiting fluids is a first-line measure but does not address a possible underlying cause.', false),
  ('renal', 17, 'A 4-year-old with a suspected Wilms tumor is admitted for an abdominal ultrasound. Which action by a nursing student requires the nurse to intervene IMMEDIATELY?', '[{"id": "a", "text": "Checking the child''s blood pressure"}, {"id": "b", "text": "Asking the parent whether the urine has looked bloody"}, {"id": "c", "text": "Weighing the child before the ultrasound"}, {"id": "d", "text": "Trying to palpate the abdomen to check the mass"}]'::jsonb, '["d"]', 'The abdomen must never be palpated or compressed when Wilms tumor is suspected because manipulation can cause tumor rupture and seed cancer cells. Checking BP and asking about hematuria are appropriate because hypertension and hematuria are signs of Wilms tumor.', false),
  ('renal', 18, 'The parents of a 1-day-old boy with hypospadias ask to have him circumcised before discharge, as they had planned. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Circumcision is delayed because the foreskin may be needed for the repair.\""}, {"id": "b", "text": "\"Circumcision now will help the opening on the underside of the penis heal.\""}, {"id": "c", "text": "\"Circumcision can be done now, since the repair happens at 6–12 months.\""}, {"id": "d", "text": "\"Circumcision is fine because the repair uses tissue from the scrotum.\""}]'::jsonb, '["a"]', 'A child with hypospadias must not be circumcised before surgical repair because the foreskin may be needed for the reconstructive surgery. Although the repair is done at 6–12 months, circumcising now would eliminate that tissue.', false),
  ('renal', 19, 'A 3-year-old is brought in after a parent noticed a mass in the child''s abdomen during a bath. The nurse suspects a tumor that originates from embryonic kidney cells. Which additional findings are consistent with this suspicion? Select all that apply.', '[{"id": "a", "text": "Hematuria"}, {"id": "b", "text": "Frothy urine with anasarca"}, {"id": "c", "text": "Massive proteinuria"}, {"id": "d", "text": "Periorbital edema on waking"}, {"id": "e", "text": "Smooth, firm mass on one side"}]'::jsonb, '["a", "e"]', 'Wilms tumor presents as a smooth, firm mass confined to one side, and other signs include hematuria, hypertension, abdominal pain, fever, and anorexia — so hematuria and the smooth, firm unilateral mass fit. Frothy urine with anasarca and massive proteinuria are nephrotic syndrome findings, and periorbital edema on waking points to AGN.', true),
  ('renal', 20, 'A 4-year-old with nephrotic syndrome has been receiving prednisone and a diuretic for 10 days. Which findings indicate that the treatment is effective? Select all that apply.', '[{"id": "a", "text": "Daily weight is decreasing"}, {"id": "b", "text": "Urine is less frothy"}, {"id": "c", "text": "Blood pressure has risen above baseline"}, {"id": "d", "text": "Periorbital and scrotal edema are decreasing"}, {"id": "e", "text": "Urine has become cola-colored"}]'::jsonb, '["a", "b", "d"]', 'Nephrotic syndrome causes massive proteinuria (frothy urine) and severe edema (periorbital, scrotal), which are tracked with daily weight, so less frothy urine, less edema and a falling daily weight show improvement. A rising BP is a feature of AGN, not an improvement, and cola-colored urine is the hematuria of AGN.', true),
  ('renal', 21, 'A 6-year-old with acute glomerulonephritis had an intake of 1,100 mL and an output of 240 mL over the past 24 hours. Today''s weight is 0.6 kg more than yesterday''s, and the periorbital edema is worse. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Check the blood pressure and report the fluid retention"}, {"id": "b", "text": "Encourage fluids to help increase the urine output"}, {"id": "c", "text": "Document the findings as expected for the condition"}, {"id": "d", "text": "Hold the daily weight until the edema has decreased"}]'::jsonb, '["a"]', 'Output far below intake (oliguria), a rising daily weight, and worsening edema show fluid retention in AGN, which raises the blood pressure; the nurse monitors BP and reports. Encouraging fluids is wrong because AGN treatment includes fluid restriction.', false),
  ('renal', 22, 'A 7-year-old with post-streptococcal glomerulonephritis has cola-colored urine, periorbital edema, and hypertension. Which interventions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Monitor the BP"}, {"id": "b", "text": "Fluid restriction"}, {"id": "c", "text": "Low sodium diet"}, {"id": "d", "text": "Encourage fluids"}, {"id": "e", "text": "Bedrest during the acute phase"}]'::jsonb, '["a", "b", "c", "e"]', 'AGN is usually self-resolving and is managed by monitoring BP, fluid restriction, a low sodium diet, daily weight, I&Os, and bedrest during the acute phase — so those four are correct. Encouraging fluids is wrong for AGN; it is a UTI measure.', true),
  ('renal', 23, 'A 10-year-old is seen for puffy eyes on waking and urine the color of tea. The blood pressure is elevated. Which question by the nurse is MOST important when taking the history?', '[{"id": "a", "text": "\"Has he been wetting the bed again at night?\""}, {"id": "b", "text": "\"Has he had strep throat or impetigo recently?\""}, {"id": "c", "text": "\"Has anyone felt a firm lump on one side of his abdomen?\""}, {"id": "d", "text": "\"Does he wipe front to back after using the toilet?\""}]'::jsonb, '["b"]', 'Tea-colored urine, periorbital edema on waking and hypertension suggest AGN, which follows strep throat or impetigo by 1–3 weeks. A firm one-sided abdominal lump relates to Wilms tumor, which can cause hematuria but not periorbital edema on waking.', false),
  ('renal', 24, 'A 9-year-old in the acute phase of post-strep glomerulonephritis has hypertension and hematuria. The child asks to go to the playroom to play basketball. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Yes, activity helps your kidneys get rid of the extra fluid.\""}, {"id": "b", "text": "\"You can play once your urine is no longer frothy.\""}, {"id": "c", "text": "\"Bedrest is needed during the acute phase; we''ll bring games.\""}, {"id": "d", "text": "\"You can play if you drink extra fluids to stay hydrated.\""}]'::jsonb, '["c"]', 'AGN treatment includes bedrest during the acute phase. Frothy urine is a nephrotic syndrome sign, and extra fluids contradict the fluid restriction used in AGN.', false),
  ('renal', 25, 'A 9-year-old girl tells the school nurse that it burns when she urinates. Which additional findings would support a urinary tract infection? Select all that apply.', '[{"id": "a", "text": "Urinary frequency and urgency"}, {"id": "b", "text": "Cola-colored or rusty urine"}, {"id": "c", "text": "Cloudy or foul-smelling urine"}, {"id": "d", "text": "Elevated blood pressure"}, {"id": "e", "text": "Periorbital edema on waking"}]'::jsonb, '["a", "c"]', 'Older children with a UTI have dysuria, urinary frequency/urgency, foul-smelling or cloudy urine, and suprapubic or flank pain — so frequency/urgency and cloudy or foul urine fit. Cola-colored urine, hypertension, and periorbital edema are the classic nephritic signs of AGN.', true),
  ('renal', 26, 'The parent of 4-year-old twins, a boy and a girl, asks why the daughter has had three urinary tract infections while the son has had none. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "\"Girls tend to empty the bladder less completely than boys.\""}, {"id": "b", "text": "\"Girls are more likely to have kidney inflammation after strep.\""}, {"id": "c", "text": "\"Girls carry more E. coli in the bladder as they grow older.\""}, {"id": "d", "text": "\"Girls have a shorter urethra, so UTIs are more common.\""}]'::jsonb, '["d"]', 'UTIs are more common in girls because of their shorter urethra. E. coli is the most common cause of UTI, but it is not explained as being carried in girls'' bladders.', false),
  ('renal', 27, 'During a well-child visit, the nurse notes that a 14-month-old''s right testis has never descended into the scrotum. The parents would like to keep waiting. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Orchiopexy is recommended by age 1 year, so surgery should be discussed.\""}, {"id": "b", "text": "\"Most testes come down on their own by school age, so waiting is safe.\""}, {"id": "c", "text": "\"Surgery is avoided because the operation itself can cause infertility.\""}, {"id": "d", "text": "\"Waiting is fine because an undescended testis carries no long-term risks.\""}]'::jsonb, '["a"]', 'Cryptorchidism is treated with orchiopexy, recommended by age 1 year, and this child is already 14 months old. Untreated cryptorchidism carries risks of infertility, testicular cancer, and psychological concerns, so it is not risk-free.', false),
  ('renal', 28, 'The parents of an 18-month-old with an untreated undescended testicle ask why surgery matters. Which risks of leaving it untreated should the nurse explain? Select all that apply.', '[{"id": "a", "text": "Infertility"}, {"id": "b", "text": "Hypospadias"}, {"id": "c", "text": "Testicular cancer"}, {"id": "d", "text": "Low blood pressure"}, {"id": "e", "text": "Urinary tract infection"}]'::jsonb, '["a", "c"]', 'Risks of untreated cryptorchidism are infertility, testicular cancer, and psychological concerns, so infertility and testicular cancer are correct. Hypospadias is a separate urethral defect, and low blood pressure and urinary tract infection are not listed risks of an undescended testis.', true),
  ('renal', 29, 'The parent of a 4-year-old reports that the child wets the bed 3 or 4 nights a week but stays dry during the day. The parent asks whether medication is needed. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Desmopressin (DDAVP) is the usual choice for children this age.\""}, {"id": "b", "text": "\"This is secondary enuresis and needs a workup for diabetes.\""}, {"id": "c", "text": "\"Nighttime control isn''t expected until age 5; this is very common.\""}, {"id": "d", "text": "\"Firm consequences for wet nights will help him stay dry sooner.\""}]'::jsonb, '["c"]', 'Enuresis is involuntary urination after the age of expected bladder control, which is age 5 for nighttime, and the family should be reassured it is very common. Secondary enuresis means wetting after being dry more than 6 months, which this child has not been, and punishment is avoided.', false),
  ('renal', 30, 'The nurse teaches the parents of a 7-year-old with primary nocturnal enuresis. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "\"We''ll have him void right before he goes to sleep.\""}, {"id": "b", "text": "\"We''ll stop drinks 2 hours before bedtime.\""}, {"id": "c", "text": "\"We''ll put a sticker on his chart for every dry night.\""}, {"id": "d", "text": "\"He''ll lose his tablet time each morning he wakes up wet.\""}]'::jsonb, '["d"]', 'Punishment is avoided in enuresis, so taking away tablet time for wet nights needs correction. Voiding before sleep, limiting fluids 2 hours before bedtime, and motivational charts are first-line measures.', false),
  ('renal', 31, 'A 9-year-old with primary enuresis still wets the bed nearly every night after 6 months of fluid limits before bed, voiding before sleep, a motivational chart, and a bedwetting alarm. Which treatment should the nurse anticipate NEXT?', '[{"id": "a", "text": "Oral antibiotics for a presumed UTI"}, {"id": "b", "text": "Desmopressin (DDAVP)"}, {"id": "c", "text": "Prednisone"}, {"id": "d", "text": "An antihypertensive medication"}]'::jsonb, '["b"]', 'When first-line measures fail, pharmacological treatment with desmopressin (DDAVP) or imipramine is used if needed. Prednisone treats nephrotic syndrome, and antibiotics treat a UTI, which has not been identified here.', false),
  ('renal', 32, 'A 3-year-old''s abdominal ultrasound confirms a kidney mass, and a CT scan is scheduled for staging. The parent asks why a chest CT has also been ordered. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"It checks the heart for strain from his high blood pressure.\""}, {"id": "b", "text": "\"It looks for fluid in the lungs from the kidney not working.\""}, {"id": "c", "text": "\"It checks for lung metastases from the kidney cancer.\""}, {"id": "d", "text": "\"It is the first-line test that confirms the kidney tumor.\""}]'::jsonb, '["c"]', 'In Wilms tumor, a chest CT checks for lung metastases; the lung is the most common site of distant spread. Abdominal ultrasound, not chest CT, is the first-line diagnostic test.', false),
  ('renal', 33, 'A 2-year-old has aniridia, a genitourinary anomaly, and intellectual disability. Which condition should the nurse MOST closely monitor this child for at well-child visits?', '[{"id": "a", "text": "Wilms tumor"}, {"id": "b", "text": "Nephrotic syndrome"}, {"id": "c", "text": "Acute glomerulonephritis"}, {"id": "d", "text": "Enuresis"}]'::jsonb, '["a"]', 'Aniridia, GU anomalies, and intellectual disability are parts of WAGR syndrome (Wilms + Aniridia + GU anomalies + intellectual disability), which is associated with Wilms tumor. Nephrotic syndrome and AGN are not associated with these findings.', false),
  ('renal', 34, 'A float nurse is assigned to a 4-year-old who returned from a nephrectomy for Wilms tumor this morning. Which instruction from the charge nurse is MOST important?', '[{"id": "a", "text": "\"Encourage fluids to flush the remaining kidney.\""}, {"id": "b", "text": "\"Palpate the abdomen each shift for new masses.\""}, {"id": "c", "text": "\"Restrict sodium because his BP will be low.\""}, {"id": "d", "text": "\"Do not palpate the abdomen; the sign is on the bed.\""}]'::jsonb, '["d"]', 'After surgery for Wilms tumor, the bed carries a "DO NOT PALPATE ABDOMEN" sign, and all caregivers and staff are educated. Palpating each shift for masses is the unsafe action this rule prevents.', false),
  ('renal', 35, 'Imaging shows that a 3-year-old''s Wilms tumor is confined to the kidney with no spread. The parent asks what treatment to expect. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Steroids and diuretics, since the tumor often responds to them.\""}, {"id": "b", "text": "\"Nephrectomy, followed by chemotherapy with vincristine and dactinomycin.\""}, {"id": "c", "text": "\"Nephrectomy plus whole-lung radiation to prevent spread to the lungs.\""}, {"id": "d", "text": "\"Watchful waiting, because these tumors are usually self-resolving.\""}]'::jsonb, '["b"]', 'A Wilms tumor confined to the kidney (stage I) is treated with nephrectomy plus chemotherapy (vincristine + dactinomycin). Whole-lung radiation is added only for stage IV disease with distant metastases.', false),
  ('renal', 36, 'The parent of a 4-year-old whose Wilms tumor is localized to one kidney asks, "Is my child going to survive this?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Survival depends mainly on how quickly the mass is felt at each visit.\""}, {"id": "b", "text": "\"Most children need lifelong dialysis, but survival is still possible.\""}, {"id": "c", "text": "\"The outlook is excellent; survival is over 90% for localized disease.\""}, {"id": "d", "text": "\"The outlook is poor because these tumors spread to the lungs early.\""}]'::jsonb, '["c"]', 'The prognosis for Wilms tumor is excellent, with overall 5-year survival above 90% for localized disease. Feeling the mass at each visit is unsafe because the abdomen must not be palpated.', false),
  ('renal', 37, 'The nurse reviews findings for several children on the pediatric renal unit. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Child on prednisone (immunosuppressed) whose roommate has a fever"}, {"id": "b", "text": "Child with nephrotic syndrome whose blood pressure is in the normal range"}, {"id": "c", "text": "Infant with hypospadias who is to be circumcised today"}, {"id": "d", "text": "Child with nephrotic syndrome whose urine still looks frothy"}, {"id": "e", "text": "4-year-old who wets the bed at night but is dry during the day"}]'::jsonb, '["a", "c"]', 'A child with nephrotic syndrome on prednisone is immunosuppressed and must be protected from infection, and a child with hypospadias must NOT be circumcised before repair because the foreskin may be needed — both need immediate follow-up. Normal BP and frothy urine are expected in nephrotic syndrome, and nighttime wetting is expected until age 5.', true),
  ('renal', 38, 'On a newborn assessment, the nurse notes that the urethral opening is on the dorsal (top) surface of the penis. The parents ask whether this is the common type of defect. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"This is hypospadias, the most common type; it''s repaired at 6–12 months.\""}, {"id": "b", "text": "\"This is epispadias, which is less common and requires surgical repair.\""}, {"id": "c", "text": "\"This is an undescended testis, which may self-correct by 6 months.\""}, {"id": "d", "text": "\"This is hypospadias, so circumcision can be done before the repair.\""}]'::jsonb, '["b"]', 'A urethral opening on the top (dorsal surface) of the penis is epispadias, which is less common and requires surgical repair. Hypospadias is the more common defect, with the opening on the underside (ventral surface).', false),
  ('renal', 39, 'A 3-month-old is brought to the emergency department with a fever that has no obvious source. The infant is irritable and feeding poorly. Which diagnostic tests should the nurse anticipate as MOST important?', '[{"id": "a", "text": "Urinalysis and urine culture"}, {"id": "b", "text": "Abdominal ultrasound for a mass"}, {"id": "c", "text": "Throat culture for strep"}, {"id": "d", "text": "Serum albumin and lipid levels"}]'::jsonb, '["a"]', 'Fever without a source in an infant suggests a UTI, which is diagnosed by urinalysis plus urine culture. A throat culture relates to the strep infection that precedes AGN, which presents with hematuria and edema rather than fever without a source.', false),
  ('renal', 40, 'A 3-year-old with nephrotic syndrome has worsening anasarca with ascites and scrotal edema despite oral prednisone. Which combination of orders should the nurse anticipate for this severe case?', '[{"id": "a", "text": "Antihypertensives and bedrest"}, {"id": "b", "text": "Encourage fluids and a regular diet"}, {"id": "c", "text": "Antibiotics and increased fluids"}, {"id": "d", "text": "Albumin IV with fluid restriction"}]'::jsonb, '["d"]', 'Severe nephrotic syndrome is treated with albumin IV plus fluid restriction, along with steroids and diuretics. Antihypertensives and bedrest are AGN measures, where BP is high.', false),
  ('renal', 41, 'A 2-year-old has frothy urine and swelling around the eyes, abdomen, and scrotum. Laboratory results show massive proteinuria. Which additional findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "Cola-colored urine"}, {"id": "b", "text": "Hypoalbuminemia"}, {"id": "c", "text": "Hyperlipidemia"}, {"id": "d", "text": "Normal to low blood pressure"}, {"id": "e", "text": "Severe generalized edema"}]'::jsonb, '["b", "c", "d", "e"]', 'Nephrotic syndrome causes massive proteinuria, severe generalized edema (anasarca), hypoalbuminemia, normal to low BP, and hyperlipidemia as the liver makes more lipoproteins — so those four are expected. Cola-colored urine is the hematuria of AGN; hematuria is minimal or absent in nephrotic syndrome.', true),
  ('renal', 42, 'A 6-year-old with a urinary tract infection is being discharged on an oral antibiotic. Which instruction is MOST important for the nurse to reinforce with the parent?', '[{"id": "a", "text": "\"Limit fluids so that voiding is less painful.\""}, {"id": "b", "text": "\"Follow a low sodium diet until the urine clears.\""}, {"id": "c", "text": "\"Encourage fluids while she takes the antibiotic.\""}, {"id": "d", "text": "\"Keep her on bedrest until the fever is gone.\""}]'::jsonb, '["c"]', 'UTI treatment is antibiotics with encouraged fluids, and adequate fluid intake is also part of prevention. A low sodium diet and bedrest are AGN measures, and limiting fluids contradicts the plan.', false),
  ('renal', 43, 'A 5-year-old boy with nephrotic syndrome has marked scrotal edema and anasarca. During morning care, which action by the nurse is MOST important?', '[{"id": "a", "text": "Encourage fluids to replace protein lost in the urine"}, {"id": "b", "text": "Provide skin care to the edematous scrotal area"}, {"id": "c", "text": "Check the blood pressure hourly for hypertension"}, {"id": "d", "text": "Collect a bag urine specimen for a culture"}]'::jsonb, '["b"]', 'Nephrotic syndrome care includes skin care for edematous areas such as the scrotum. Hourly checks for hypertension fit AGN, since BP in nephrotic syndrome is normal or low.', false),
  ('renal', 44, 'The nurse in a pediatric clinic receives four telephone messages. Which child should the nurse arrange to be seen FIRST?', '[{"id": "a", "text": "A 3-year-old whose parent felt a smooth abdominal mass while bathing"}, {"id": "b", "text": "A 4-year-old with nephrotic syndrome whose urine is still frothy"}, {"id": "c", "text": "A 4-year-old who wets the bed at night but is dry during the day"}, {"id": "d", "text": "A 2-month-old born early who has an undescended testis"}]'::jsonb, '["a"]', 'A smooth, firm abdominal mass found by a parent while bathing a toddler is the classic presentation of Wilms tumor and needs prompt evaluation. Frothy urine is expected in nephrotic syndrome, nighttime wetting is normal until age 5, and an undescended testis in a premature infant may self-correct by 6 months.', false),
  ('renal', 45, 'A 9-year-old who had been dry at night for 2 years is now wetting the bed several nights a week. Which assessments should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Deep palpation of the abdomen for a mass"}, {"id": "b", "text": "Evaluate for stress at home"}, {"id": "c", "text": "Urinalysis to check for a UTI"}, {"id": "d", "text": "Starting a bedwetting alarm before any testing"}, {"id": "e", "text": "Evaluate for DM"}]'::jsonb, '["b", "c", "e"]', 'Wetting after being dry for more than 6 months is secondary enuresis, which is evaluated for stress, UTI, and DM — so asking about stress, urinalysis and DM screening are correct. Deep palpation for a mass is not part of the enuresis workup, and starting an alarm before evaluating skips the required evaluation.', true),
  ('renal', 46, 'The parent of a 6-year-old recovering from acute glomerulonephritis that followed strep throat asks about the long-term outlook. Which statement by the parent indicates understanding?', '[{"id": "a", "text": "\"He''ll need prednisone for months to control the protein loss.\""}, {"id": "b", "text": "\"His kidney will need to be removed once the swelling goes down.\""}, {"id": "c", "text": "\"It is usually self-resolving after the strep infection.\""}, {"id": "d", "text": "\"He''ll have frothy urine and low blood pressure as he grows.\""}]'::jsonb, '["c"]', 'AGN is usually self-resolving, with BP monitoring and supportive care. Prednisone for protein loss is the treatment for nephrotic syndrome, which also causes frothy urine and normal to low BP.', false),
  ('renal', 47, 'A 6-year-old girl is being treated for her second urinary tract infection this year. Which instructions should the nurse include in prevention teaching? Select all that apply.', '[{"id": "a", "text": "Wipe front to back"}, {"id": "b", "text": "Take bubble baths to keep the area clean"}, {"id": "c", "text": "Wear cotton underwear"}, {"id": "d", "text": "Keep regular toilet schedules"}, {"id": "e", "text": "Limit fluids to reduce the number of voids"}]'::jsonb, '["a", "c", "d"]', 'UTI prevention includes wiping front to back, cotton underwear, regular toilet schedules, complete voiding, and adequate fluid intake — so those three are correct. Bubble baths should be avoided, and limiting fluids contradicts adequate fluid intake.', true),
  ('renal', 48, 'The nurse is reviewing the histories of four children who had strep throat. Which child is MOST likely to be developing acute glomerulonephritis?', '[{"id": "a", "text": "A 7-year-old with burning on urination 2 days after strep throat"}, {"id": "b", "text": "An 8-year-old with rusty urine 2 weeks after strep throat"}, {"id": "c", "text": "A 6-year-old with bedwetting 6 months after strep throat"}, {"id": "d", "text": "A 9-year-old with frothy urine and normal BP 3 days after strep"}]'::jsonb, '["b"]', 'AGN follows strep throat or impetigo by 1–3 weeks and causes hematuria (tea-colored, cola-colored, or rusty urine). Burning on urination suggests a UTI, and frothy urine with normal BP suggests nephrotic syndrome.', false),
  ('renal', 49, 'A 3-year-old is diagnosed with minimal change disease after developing anasarca and frothy urine. Which treatments should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Antihypertensives for high blood pressure"}, {"id": "b", "text": "Corticosteroids (prednisone)"}, {"id": "c", "text": "Diuretics"}, {"id": "d", "text": "No medications, since it is self-resolving"}, {"id": "e", "text": "Encouraging extra oral fluids"}]'::jsonb, '["b", "c"]', 'Minimal change disease, the most common cause of nephrotic syndrome in children, is treated with corticosteroids (prednisone) and diuretics, so those two are correct. High BP needing antihypertensives and a self-resolving course describe AGN, and severe cases need fluid restriction, not extra fluids.', true),
  ('renal', 50, 'The school nurse is asked about four children who wet the bed. Which child''s pattern is MOST consistent with primary enuresis?', '[{"id": "a", "text": "A 4-year-old who has wet the bed most nights since birth"}, {"id": "b", "text": "A 7-year-old who was dry for a year and now wets nightly"}, {"id": "c", "text": "A 6-year-old who has never been consistently dry at night"}, {"id": "d", "text": "A 3-year-old who has accidents at naptime and at night"}]'::jsonb, '["c"]', 'Enuresis is involuntary urination after the age of expected bladder control (age 5 for nighttime), and primary enuresis means the child has never been consistently dry. The 7-year-old who was dry for a year has secondary enuresis, and children under 5 do not meet the definition.', false),
  ('msk', 1, 'The parent of a 4-month-old in a Pavlik harness for developmental dysplasia of the hip says the diapers keep leaking. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "We keep the harness on 24/7, even during the night."}, {"id": "b", "text": "We will keep every follow-up visit with the provider."}, {"id": "c", "text": "We will double-diaper her to stop the leaks."}, {"id": "d", "text": "We know she will wear it full-time for her hips."}]'::jsonb, '["c"]', 'Do NOT double-diaper an infant being treated for DDH. The Pavlik harness is worn 24/7 (full-time) for infants younger than 6 months.', false),
  ('msk', 2, 'An 8-month-old is newly diagnosed with developmental dysplasia of the hip after the parent noticed asymmetrical gluteal folds. Which treatment should the nurse anticipate MOST likely being prescribed?', '[{"id": "a", "text": "A Pavlik harness worn 24/7"}, {"id": "b", "text": "A Denis Browne bar for 23 hrs/day"}, {"id": "c", "text": "A Boston brace or TLSO"}, {"id": "d", "text": "Bryant traction or a spica cast"}]'::jsonb, '["d"]', 'The Pavlik harness is used for infants younger than 6 months; an older infant is treated with Bryant traction or a spica cast. The Denis Browne bar follows clubfoot casting, and the Boston brace/TLSO is for scoliosis.', false),
  ('msk', 3, 'The nurse reviews the history of a newborn being evaluated for developmental dysplasia of the hip. Which factors increase this newborn''s risk? Select all that apply.', '[{"id": "a", "text": "Firstborn"}, {"id": "b", "text": "Dark skin"}, {"id": "c", "text": "Girls"}, {"id": "d", "text": "Breech"}, {"id": "e", "text": "Exclusively breastfed"}]'::jsonb, '["a", "c", "d"]', 'Correct: girls (c), breech (d), and firstborn (a) infants are at risk for DDH, along with family history and tight swaddling. Wrong: exclusive breastfeeding (e) and dark skin (b) are risk factors for rickets, not DDH.', true),
  ('msk', 4, 'A newborn with talipes equinovarus is discharged on day 2. The parent says, ''We''d like to wait until she is 3 months old to start casting so she can settle in at home.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Waiting is fine; the foot corrects best once she is bigger."}, {"id": "b", "text": "Start within 1–2 weeks, when bones are most flexible."}, {"id": "c", "text": "Casting can wait until she is old enough for a Denis Browne bar."}, {"id": "d", "text": "Treatment begins with an Achilles tenotomy at about 3 months."}]'::jsonb, '["b"]', 'Clubfoot treatment starts within the first 1–2 weeks because bones are most flexible and responsive to correction in the early weeks; treatment should not be delayed. The Denis Browne bar and possible tenotomy come after serial casting.', false),
  ('msk', 5, 'The parent of a 3-month-old who just finished Ponseti casting for clubfoot is learning about the Denis Browne bar. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "She will wear the bar 23 hours a day for months."}, {"id": "b", "text": "The bar helps keep the correction from the casts."}, {"id": "c", "text": "She''ll wear the bar only while she sleeps."}, {"id": "d", "text": "We will take it off for about an hour each day."}]'::jsonb, '["c"]', 'Denis Browne bar bracing is worn 23 hrs/day for months after serial casting, so wearing it only during sleep is not enough. Removing it for about an hour a day fits the 23-hour schedule.', false),
  ('msk', 6, 'The nurse observes the parent of a 3-week-old in a long-leg cast for clubfoot. Which action by the parent requires IMMEDIATE intervention?', '[{"id": "a", "text": "Checking the toes for color and warmth"}, {"id": "b", "text": "Putting a cotton swab inside the cast"}, {"id": "c", "text": "Pressing a toenail to check cap refill"}, {"id": "d", "text": "Bringing the infant back weekly for cast changes"}]'::jsonb, '["b"]', 'Never put anything inside the cast. Checking toe color, warmth, and cap refill and returning weekly for cast changes are correct parts of Ponseti care.', false),
  ('msk', 7, 'The parent of a 1-week-old beginning Ponseti treatment for clubfoot asks how often the infant will need to come back to the clinic. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Casts are changed monthly for about 6 months."}, {"id": "b", "text": "Casts are changed weekly for about 6 weeks."}, {"id": "c", "text": "One cast is worn for 6 weeks without changes."}, {"id": "d", "text": "Casts are changed every 4–6 months for a year."}]'::jsonb, '["b"]', 'The Ponseti method is serial casting changed weekly for about 6 weeks. Follow-up every 4–6 months describes observation of a scoliosis curve under 20°.', false),
  ('msk', 8, 'The nurse is teaching the parents of a 2-week-old with bilateral clubfoot who has just had the first Ponseti cast applied. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Remove the cast at home if the toes swell"}, {"id": "b", "text": "Check toes for color, warmth, and cap refill"}, {"id": "c", "text": "Delay the next cast if the infant is fussy"}, {"id": "d", "text": "Never put anything inside the cast"}, {"id": "e", "text": "Return each week for a cast change"}]'::jsonb, '["b", "d", "e"]', 'Correct: check toes for color, warmth, and cap refill after each cast change (b); never put anything inside the cast (d); Ponseti casts are changed weekly (e). Wrong: treatment must not be delayed, because bones are most flexible and responsive to correction in the early weeks (c); parents do not remove casts — changes are part of serial casting (a).', true),
  ('msk', 9, 'A 7-month-old is brought to the emergency department with a new femur fracture after the parent says the infant ''just rolled over.'' X-rays show several other fractures at different healing stages, and the nurse notes blue sclerae. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Report the parents for abuse and restrict their visits"}, {"id": "b", "text": "Obtain a full social and medical history and alert the team"}, {"id": "c", "text": "Tell the parents that the fractures are clearly from abuse"}, {"id": "d", "text": "Splint the femur and discharge the infant home with the parents"}]'::jsonb, '["b"]', 'Multiple fractures at different healing stages can mimic abuse in osteogenesis imperfecta, especially with blue sclerae, so a full social and medical history is essential and the interdisciplinary team is alerted. Concluding abuse without that history is premature.', false),
  ('msk', 10, 'A 2-year-old with osteogenesis imperfecta is admitted for a fractured arm. Which action by the unlicensed assistive personnel (UAP) requires IMMEDIATE intervention by the nurse?', '[{"id": "a", "text": "Lifting the child by the arms to move up in bed"}, {"id": "b", "text": "Supporting the trunk and head when repositioning"}, {"id": "c", "text": "Adding padding to the side rails of the crib"}, {"id": "d", "text": "Moving the child slowly and gently during care"}]'::jsonb, '["a"]', 'Children with OI need extremely gentle handling — support the trunk and head and do not lift by arms or pull limbs. Padding the crib and moving slowly are correct care.', false),
  ('msk', 11, 'A 3-year-old is admitted with a fracture after a minor fall, the third fracture this year. The nurse suspects osteogenesis imperfecta. Which findings would support this suspicion? Select all that apply.', '[{"id": "a", "text": "Dental abnormalities"}, {"id": "b", "text": "Multiple fractures with minimal trauma"}, {"id": "c", "text": "Blue/grey sclerae"}, {"id": "d", "text": "Rachitic rosary"}, {"id": "e", "text": "Short stature"}]'::jsonb, '["a", "b", "c", "e"]', 'Correct: blue/grey sclerae (c, the classic finding), short stature (e), dental abnormalities (a), and multiple fractures with minimal or no trauma (b) are signs of OI. Wrong: rachitic rosary is a rickets finding caused by vitamin D deficiency (d).', true),
  ('msk', 12, 'The parents of a 4-year-old with osteogenesis imperfecta ask why their child receives pamidronate infusions. Which statement by a parent indicates understanding of the teaching?', '[{"id": "a", "text": "It replaces the vitamin D that his diet is missing."}, {"id": "b", "text": "It is a bisphosphonate given to strengthen his bones."}, {"id": "c", "text": "It turns his blue sclerae back to a normal white color."}, {"id": "d", "text": "It corrects the collagen gene so fractures stop."}]'::jsonb, '["b"]', 'Bisphosphonates (pamidronate) are given to strengthen bones in OI. Vitamin D replacement is rickets treatment, and OI is a genetic collagen disorder that the drug does not correct.', false),
  ('msk', 13, 'A 9-month-old is seen for a fracture after minimal trauma. Rickets and osteogenesis imperfecta are both being considered. Which assessment finding MOST supports osteogenesis imperfecta?', '[{"id": "a", "text": "Bowing of the legs"}, {"id": "b", "text": "Rachitic rosary"}, {"id": "c", "text": "Blue sclerae"}, {"id": "d", "text": "Craniotabes"}]'::jsonb, '["c"]', 'Both rickets and OI cause fractures; OI is genetic and causes blue sclerae and brittle bones, while rickets causes bowing deformities, rachitic rosary, and soft skull bones (craniotabes).', false),
  ('msk', 14, 'The nurse is planning care for a 2-year-old with osteogenesis imperfecta. Which actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Support the trunk and head when moving"}, {"id": "b", "text": "Restrict all movement and therapy"}, {"id": "c", "text": "Lift by the arms to avoid pressure on the ribs"}, {"id": "d", "text": "Provide a padded bed/crib environment"}, {"id": "e", "text": "Pull gently on the legs to straighten them"}]'::jsonb, '["a", "d"]', 'Correct: a padded bed/crib environment (d) and supporting the trunk and head (a) are OI nursing care. Wrong: do not lift by the arms (c) or pull limbs (e); PT/OT with lightweight splints/braces is part of care, so all movement and therapy are not restricted (b).', true),
  ('msk', 15, 'A nurse is documenting the assessment of an infant with several fractures at different healing stages whose parents report no injury. Which documentation entry is MOST appropriate?', '[{"id": "a", "text": "Parents seem guilty and are likely hiding abuse."}, {"id": "b", "text": "Sclerae blue/grey; parents report no known trauma."}, {"id": "c", "text": "Fractures are clearly caused by rough handling."}, {"id": "d", "text": "Infant has brittle bones, so abuse has been ruled out."}]'::jsonb, '["b"]', 'With fractures that can mimic abuse, the nurse documents objectively — observed findings and reported history — and does not draw conclusions either way. Ruling abuse in or out is not done by the nurse''s documentation.', false),
  ('msk', 16, 'A 6-year-old boy has had a limp for several weeks, and the parent says he complains of knee pain. The nurse finds hip stiffness, limited hip ROM, and a Trendelenburg gait. He is of average weight. Which condition does the nurse MOST likely suspect?', '[{"id": "a", "text": "Legg-Calvé-Perthes disease"}, {"id": "b", "text": "Slipped capital femoral epiphysis"}, {"id": "c", "text": "Developmental dysplasia of the hip"}, {"id": "d", "text": "Osteogenesis imperfecta"}]'::jsonb, '["a"]', 'A limp, hip or referred knee pain, stiffness, limited hip ROM, and Trendelenburg gait in a boy aged 4–8 years fit Legg-Calvé-Perthes disease. SCFE also causes referred knee pain but typically affects obese adolescent males.', false),
  ('msk', 17, 'The parent of a 7-year-old with Legg-Calvé-Perthes disease asks why the child has to use crutches when the hip ''doesn''t hurt much.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Crutches keep weight off the femoral head while it regrows."}, {"id": "b", "text": "Crutches are used until the growth plate is pinned in surgery."}, {"id": "c", "text": "Crutches let the hip slip back onto the femoral neck."}, {"id": "d", "text": "Crutches help the leg turn outward into a normal position."}]'::jsonb, '["a"]', 'In LCP, the blood supply to the femoral head is interrupted, the bone dies and regrows, so treatment protects the femoral head during regrowth with non-weight-bearing (crutches). Surgical pinning of a slipped epiphysis is SCFE treatment.', false),
  ('msk', 18, 'The parent of a 5-year-old boy newly diagnosed with Legg-Calvé-Perthes disease asks, ''How long will this last?'' Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "It usually heals in 6 weeks with casts changed weekly."}, {"id": "b", "text": "It lasts until surgery is done, then heals in days."}, {"id": "c", "text": "It is self-limited but takes about 2–4 years to heal."}, {"id": "d", "text": "It is lifelong because the bone cannot regrow at all."}]'::jsonb, '["c"]', 'LCP disease is self-limited but takes 2–4 years as the femoral head regrows and remodels. Weekly casts for about 6 weeks describe Ponseti treatment for clubfoot.', false),
  ('msk', 19, 'A 6-year-old boy is evaluated for a temporary interruption of blood supply to the femoral head. Which findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "Limited hip ROM"}, {"id": "b", "text": "Sudden severe pain, unable to bear weight"}, {"id": "c", "text": "Trendelenburg gait"}, {"id": "d", "text": "Referred knee pain"}, {"id": "e", "text": "Bowing of the legs"}]'::jsonb, '["a", "c", "d"]', 'Correct: Legg-Calvé-Perthes disease causes a Trendelenburg gait (c), hip or referred knee pain (d), and limited hip ROM (a). Wrong: bowing deformities are a rickets finding (e); sudden severe pain with inability to bear weight describes an acute SCFE slip (b).', true),
  ('msk', 20, 'A 13-year-old boy with obesity arrives at urgent care with sudden severe left hip pain after jumping from a step. He cannot bear weight, and his left leg is externally rotated. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Give pain medicine and send him home with crutches and rest"}, {"id": "b", "text": "Have him walk a few steps to assess his gait pattern"}, {"id": "c", "text": "Apply an abduction brace and schedule follow-up in a week"}, {"id": "d", "text": "Keep NPO and non-weight-bearing; urgent surgical consult"}]'::jsonb, '["d"]', 'An obese teenager with sudden hip pain and an externally rotated leg suggests an acute SCFE slip: keep NPO, no weight-bearing, and obtain an urgent surgical consult. Do not give pain meds and send home.', false),
  ('msk', 21, 'A 12-year-old boy with obesity has had a limp and knee pain for 3 weeks. His knee examination is normal, and his right foot turns outward when he lies supine. The nurse anticipates the provider will MOST likely evaluate which area NEXT?', '[{"id": "a", "text": "The right hip for a slipped epiphysis"}, {"id": "b", "text": "The right ankle for a sprain"}, {"id": "c", "text": "The spine for a lateral curvature with rotation"}, {"id": "d", "text": "The knee again with an X-ray"}]'::jsonb, '["a"]', 'SCFE causes hip or groin pain, referred knee pain, a limp, and an externally rotated leg in obese adolescent males, so the hip — not the knee — is the source. A normal knee exam with an outward-turned leg points to the hip.', false),
  ('msk', 22, 'The parents of a 14-year-old with slipped capital femoral epiphysis are reviewing the plan. Which statement by a parent indicates understanding?', '[{"id": "a", "text": "He will need surgical pinning (in-situ fixation)."}, {"id": "b", "text": "He can walk on it until the surgery is done."}, {"id": "c", "text": "He will wear a Pavlik harness for several weeks first."}, {"id": "d", "text": "Rest and pain pills at home will fix the slip."}]'::jsonb, '["a"]', 'SCFE is treated with surgical pinning (in-situ fixation), with no weight-bearing until surgery. Pain medicine at home without surgery is unsafe.', false),
  ('msk', 23, 'A 14-year-old boy with obesity is admitted with sudden severe hip pain and an externally rotated leg. Which nursing actions are appropriate before surgery? Select all that apply.', '[{"id": "a", "text": "Encourage walking to prevent stiffness"}, {"id": "b", "text": "Keep the adolescent NPO"}, {"id": "c", "text": "Maintain no weight-bearing"}, {"id": "d", "text": "Give pain meds and discharge home"}, {"id": "e", "text": "Arrange an urgent surgical consult"}]'::jsonb, '["b", "c", "e"]', 'Correct: for SCFE, keep NPO (b), maintain no weight-bearing until surgery (c), and arrange an urgent surgical consult (e). Wrong: do not give pain meds and send home (d); walking puts weight on the slipped epiphysis (a).', true),
  ('msk', 24, 'The parent of a 13-year-old admitted with an acute SCFE slip asks why the surgery cannot wait until next month. Which response by the nurse is BEST?', '[{"id": "a", "text": "The growth plate will close soon and correct the slip without surgery."}, {"id": "b", "text": "Waiting allows a cast to be placed and changed every week."}, {"id": "c", "text": "Surgery is urgent because the knee joint is the source of pain."}, {"id": "d", "text": "The slip can damage the blood supply and cause avascular necrosis."}]'::jsonb, '["d"]', 'SCFE carries a risk of avascular necrosis of the femoral head if blood supply is compromised, which is why it is treated as an emergency. The knee pain is referred; the problem is at the hip.', false),
  ('msk', 25, 'A 13-year-old girl has a 15° spinal curve with rotation on her first X-ray. Which plan does the nurse anticipate?', '[{"id": "a", "text": "Boston brace worn 23 hrs/day, off only to bathe"}, {"id": "b", "text": "Spinal fusion with instrumentation (rods/screws)"}, {"id": "c", "text": "TLSO worn only at night while sleeping"}, {"id": "d", "text": "Observation and follow-up every 4–6 months"}]'::jsonb, '["d"]', 'A curve of <20° is managed with observation, follow-up every 4–6 months, and exercises. Bracing is used for 20–40° and surgery for >40°.', false),
  ('msk', 26, 'A 14-year-old with idiopathic scoliosis and a 32° curve has just received a TLSO. Which statement by the adolescent indicates a need for further teaching?', '[{"id": "a", "text": "I''ll wear it to school but not at home."}, {"id": "b", "text": "I will take the brace off only to bathe."}, {"id": "c", "text": "I''ll wear the brace 23 hours every day."}, {"id": "d", "text": "I''ll check my skin under the brace daily."}]'::jsonb, '["a"]', 'For a 20–40° curve the brace (Boston brace or TLSO) is worn 23 hrs/day and removed only for bathing, with daily skin checks. Wearing it only at school falls far short of 23 hours.', false),
  ('msk', 27, 'A 15-year-old with idiopathic scoliosis has a curve that has progressed to 46° despite bracing. Which treatment should the nurse prepare the family for?', '[{"id": "a", "text": "A stiffer Boston brace 23 hrs/day"}, {"id": "b", "text": "Spinal fusion with rods/screws"}, {"id": "c", "text": "Observation and exercises only"}, {"id": "d", "text": "Bryant traction until the curve improves"}]'::jsonb, '["b"]', 'A curve >40° is treated with surgery — spinal fusion with instrumentation (rods/screws). Bracing is for curves of 20–40° and observation for <20°.', false),
  ('msk', 28, 'A 14-year-old is 12 hours post-op after spinal fusion for scoliosis. Which finding requires IMMEDIATE follow-up?', '[{"id": "a", "text": "Pain rated 4/10 after the scheduled analgesic"}, {"id": "b", "text": "Reluctance to take deep breaths because of pain"}, {"id": "c", "text": "New numbness and weakness in both legs"}, {"id": "d", "text": "Request for help to be log-rolled to the side"}]'::jsonb, '["c"]', 'New numbness and weakness in the legs suggests spinal cord compromise, which is monitored for after spinal fusion. Pain and reluctance to deep breathe need nursing care, and log-rolling is the correct repositioning method.', false),
  ('msk', 29, 'A 15-year-old returns to the unit after spinal fusion with rods for scoliosis. Which actions should the nurse include in the post-op plan? Select all that apply.', '[{"id": "a", "text": "Encourage deep breathing"}, {"id": "b", "text": "Plan early ambulation"}, {"id": "c", "text": "Use the log-roll technique to reposition"}, {"id": "d", "text": "Perform neurovascular monitoring"}, {"id": "e", "text": "Keep on strict bed rest for 1 week"}]'::jsonb, '["a", "b", "c", "d"]', 'Correct: post-op care after spinal fusion includes the log-roll technique (c), neurovascular monitoring (d), deep breathing (a), and early ambulation (b). Wrong: strict bed rest contradicts early ambulation (e).', true),
  ('msk', 30, 'A 13-year-old with a 28° curve tells the nurse, ''Everyone at school stares at my brace, so I just leave it in my locker.'' Which nursing action is the PRIORITY?', '[{"id": "a", "text": "Tell her the curve will need surgery if she refuses"}, {"id": "b", "text": "Ask the provider to change her to observation only"}, {"id": "c", "text": "Teach her to wear the brace only during sleep"}, {"id": "d", "text": "Explore her body image and peer concerns with her"}]'::jsonb, '["d"]', 'Body image and peer concerns are significant barriers to brace compliance, and psychosocial support is a nursing priority. Changing the plan or shortening wear time does not address the 23-hour requirement.', false),
  ('msk', 31, 'The nurse is teaching a 13-year-old with a 25° scoliosis curve who was just fitted with a Boston brace. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Check skin under the brace daily"}, {"id": "b", "text": "Remove the brace for school and sports"}, {"id": "c", "text": "The brace will correct the curve"}, {"id": "d", "text": "Remove the brace only for bathing"}, {"id": "e", "text": "Wear the brace 8 hours a day"}]'::jsonb, '["a", "d"]', 'Correct: check skin under the brace daily (a) and remove it only for bathing (d). Wrong: the brace is worn 23 hrs/day, not 8 (e), and not removed for school or sports (b); bracing stops progression but does NOT correct the curve (c).', true),
  ('msk', 32, 'A 14-year-old who started wearing a TLSO for a 30° curve asks, ''If I wear this every day, will my back be straight in a year?'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes, after a year the curve is usually fully corrected."}, {"id": "b", "text": "The brace stops progression; it does not correct the curve."}, {"id": "c", "text": "Only surgery can help, so the brace is just for comfort."}, {"id": "d", "text": "The brace works only if you wear it while you sleep."}]'::jsonb, '["b"]', 'Bracing for a 20–40° curve stops progression but does NOT correct it. It is worn 23 hrs/day, and surgery is reserved for curves >40°.', false),
  ('msk', 33, 'A 10-month-old who is exclusively breastfed and has dark skin lives in a northern city and has never received a vitamin D supplement. The infant has bowed legs and delayed teeth, and the X-ray shows cupped, frayed metaphyses. Which treatment should the nurse anticipate?', '[{"id": "a", "text": "Bisphosphonates (pamidronate) to strengthen bones"}, {"id": "b", "text": "Oral vitamin D supplementation plus adequate calcium"}, {"id": "c", "text": "Bryant traction followed by a spica cast for 6 weeks"}, {"id": "d", "text": "Serial casting changed weekly for ~6 weeks"}]'::jsonb, '["b"]', 'These findings point to rickets, treated with oral vitamin D supplementation plus adequate calcium intake and sunlight exposure. Pamidronate is used for osteogenesis imperfecta, a genetic collagen disorder.', false),
  ('msk', 34, 'A mother who is exclusively breastfeeding her 2-day-old asks about vitamin D. Which statement by the mother indicates a need for further teaching?', '[{"id": "a", "text": "He should get 400 IU of vitamin D every day."}, {"id": "b", "text": "Breast milk is low in vitamin D, so he needs the drops."}, {"id": "c", "text": "Vitamin D helps prevent soft bones and bowing."}, {"id": "d", "text": "I''ll wait to start vitamin D until he eats solids."}]'::jsonb, '["d"]', 'The AAP recommends 400 IU vitamin D daily for exclusively or partially breastfed infants beginning at birth, because breast milk is low in vitamin D. Waiting until solids delays prevention.', false),
  ('msk', 35, 'A 1-month-old receives breast milk during the day and formula at night. The parent says, ''Since he gets some formula, he doesn''t need the vitamin D drops.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Partially breastfed infants also need 400 IU daily."}, {"id": "b", "text": "Infants who get any formula do not need vitamin D drops."}, {"id": "c", "text": "Vitamin D drops are started once the fontanels close."}, {"id": "d", "text": "He needs drops only if he develops bowing of the legs."}]'::jsonb, '["a"]', 'The AAP recommends 400 IU of vitamin D daily for all exclusively or partially breastfed infants beginning at birth. Waiting for bowing deformities means treating rickets instead of preventing it.', false),
  ('msk', 36, 'A 14-month-old has bowed legs and is being evaluated for vitamin D deficiency. Which laboratory findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "↓ phosphate"}, {"id": "b", "text": "↑ alkaline phosphatase"}, {"id": "c", "text": "↓ alkaline phosphatase"}, {"id": "d", "text": "↓ serum 25-OH vitamin D"}, {"id": "e", "text": "↑ serum calcium"}]'::jsonb, '["a", "b", "d"]', 'Correct: rickets shows ↓ serum 25-OH vitamin D (d), ↓ phosphate (a), and ↑ alkaline phosphatase (b). Wrong: calcium is decreased, not increased (e); alkaline phosphatase is increased, not decreased (c).', true),
  ('msk', 37, 'An exclusively breastfed 11-month-old who never received vitamin D supplementation is being assessed for rickets. Which findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "Rachitic rosary"}, {"id": "b", "text": "Enlarged fontanels with frontal bossing"}, {"id": "c", "text": "Blue/grey sclerae"}, {"id": "d", "text": "Delayed dentition"}, {"id": "e", "text": "Craniotabes"}]'::jsonb, '["a", "b", "d", "e"]', 'Correct: rickets causes rachitic rosary (a), enlarged fontanels with delayed closure and frontal bossing (b), delayed dentition (d), and craniotabes — soft skull bones (e). Wrong: blue/grey sclerae are the classic finding of osteogenesis imperfecta (c).', true),
  ('msk', 38, 'While assessing a 5-month-old who is exclusively breastfed and lives in a northern latitude, the nurse presses on the skull and feels it give way like a ping-pong ball. Which additional finding would MOST support the suspected condition?', '[{"id": "a", "text": "Asymmetrical gluteal folds"}, {"id": "b", "text": "Blue/grey sclerae"}, {"id": "c", "text": "Externally rotated leg"}, {"id": "d", "text": "Beaded costochondral junctions"}]'::jsonb, '["d"]', 'A ping-pong ball feel of the skull is craniotabes, a rickets finding; rachitic rosary — beaded enlargement of costochondral junctions — also supports rickets. Blue/grey sclerae point to OI.', false),
  ('msk', 39, 'The clinic nurse reviews four infant histories. Which infant is at HIGHEST risk for rickets?', '[{"id": "a", "text": "Formula-fed infant living in a sunny southern city"}, {"id": "b", "text": "Breastfed infant receiving 400 IU of vitamin D daily since birth"}, {"id": "c", "text": "Dark-skinned, exclusively breastfed infant in a northern city"}, {"id": "d", "text": "Firstborn girl who was born in breech position"}]'::jsonb, '["c"]', 'Exclusively breastfed infants, dark-skinned children, and children in northern latitudes are at-risk groups for rickets. A breastfed infant receiving 400 IU daily is protected, and firstborn, breech girls are at risk for DDH.', false),
  ('msk', 40, 'A 3-year-old has bowing of the legs and is diagnosed with rickets. Which factors in the history could have caused it? Select all that apply.', '[{"id": "a", "text": "Firstborn and breech position"}, {"id": "b", "text": "Malabsorption from celiac disease"}, {"id": "c", "text": "Obesity in early adolescence"}, {"id": "d", "text": "Insufficient sunlight exposure"}, {"id": "e", "text": "Tight swaddling in infancy"}]'::jsonb, '["b", "d"]', 'Correct: malabsorption such as celiac disease (b) and insufficient sunlight exposure (d) are causes of rickets. Wrong: firstborn and breech position (a) and tight swaddling (e) are DDH risk factors; obesity in adolescence is a risk for SCFE (c).', true),
  ('msk', 41, 'A 2-year-old has bowed legs and a rachitic rosary. The parent, who read about ''brittle bone disease'' online, asks if the child has a genetic bone disorder. Which response by the nurse is BEST?', '[{"id": "a", "text": "These findings point to a genetic collagen mutation in the bones."}, {"id": "b", "text": "These findings mean fractures will happen spontaneously."}, {"id": "c", "text": "These findings fit a nutritional deficiency of vitamin D."}, {"id": "d", "text": "These findings mean the sclerae will turn blue later."}]'::jsonb, '["c"]', 'Rickets is a nutritional deficiency (vitamin D/Ca²⁺) that causes bowing deformities and rachitic rosary; OI is genetic (collagen mutation) with blue sclerae and multiple fractures.', false),
  ('msk', 42, 'The nurse on an orthopedic unit receives report on four children. Which child should the nurse see FIRST?', '[{"id": "a", "text": "Infant with pale, cool toes after a clubfoot cast change"}, {"id": "b", "text": "A 6-year-old with LCP disease who walks with a Trendelenburg gait"}, {"id": "c", "text": "A 3-year-old with OI who is waiting for a padded crib"}, {"id": "d", "text": "A 14-year-old with a TLSO who is upset about how it looks"}]'::jsonb, '["a"]', 'Toes must be checked for color, warmth, and cap refill after each cast change; pale, cool toes signal compromised circulation. A Trendelenburg gait in LCP is expected, a padded crib is routine OI care, and body image concerns need support but are not urgent.', false),
  ('msk', 43, 'The nurse is reviewing several clients on a pediatric orthopedic unit. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "6-year-old with LCP disease who has a Trendelenburg gait"}, {"id": "b", "text": "14-year-old with new leg numbness 1 day after spinal fusion"}, {"id": "c", "text": "Infant with OI who has blue/grey sclerae"}, {"id": "d", "text": "13-year-old with a 15° curve due for follow-up in 4 months"}, {"id": "e", "text": "Obese 13-year-old with sudden severe hip pain, unable to bear weight"}]'::jsonb, '["b", "e"]', 'Correct: sudden severe pain with inability to bear weight in an obese teen is an acute SCFE slip needing urgent surgical consult (e); new leg numbness after spinal fusion suggests spinal cord compromise (b). Wrong: Trendelenburg gait is an expected LCP sign (a); blue/grey sclerae are the classic OI finding (c); a curve <20° is followed every 4–6 months (d).', true),
  ('msk', 44, 'A 14-year-old boy with obesity has had a gradual onset of symptoms and is being evaluated for slipped capital femoral epiphysis. Which findings would the nurse expect? Select all that apply.', '[{"id": "a", "text": "A limp"}, {"id": "b", "text": "Affected leg externally rotated"}, {"id": "c", "text": "Hip or groin pain"}, {"id": "d", "text": "Referred knee pain"}, {"id": "e", "text": "Rib hump on forward bend"}]'::jsonb, '["a", "b", "c", "d"]', 'Correct: SCFE causes hip or groin pain (c), referred knee pain (d), a limp (a), and an externally rotated affected leg (b). Wrong: a rib hump on the Adam''s Forward Bend Test is a scoliosis screening finding (e).', true),
  ('msk', 45, 'A 3-month-old girl has just been fitted with a Pavlik harness for developmental dysplasia of the hip. The parent asks when the harness may come off. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "It can come off at night while she is sleeping."}, {"id": "b", "text": "It comes off for baths and feedings each day."}, {"id": "c", "text": "It is worn 24/7 during treatment."}, {"id": "d", "text": "It is worn 23 hours a day, like a scoliosis brace."}]'::jsonb, '["c"]', 'For infants younger than 6 months the Pavlik harness is worn 24/7. The 23-hour schedule applies to scoliosis bracing and the Denis Browne bar, not the Pavlik harness.', false),
  ('msk', 46, 'A 9-month-old with developmental dysplasia of the hip is in a spica cast after the harness failed. Which nursing action is the PRIORITY during each shift?', '[{"id": "a", "text": "Double-diapering to protect the cast from urine"}, {"id": "b", "text": "Removing the cast briefly to wash the skin"}, {"id": "c", "text": "Adding a heating pad over the cast for comfort"}, {"id": "d", "text": "Neurovascular checks of both lower extremities"}]'::jsonb, '["d"]', 'Neurovascular checks every shift are required for infants treated for DDH. Double-diapering is specifically avoided, and the cast is not removed by the nurse.', false),
  ('msk', 47, 'A 2-year-old with rickets from vitamin D deficiency is starting treatment. Which interventions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Adequate calcium intake"}, {"id": "b", "text": "Bisphosphonates (pamidronate)"}, {"id": "c", "text": "Sunlight exposure"}, {"id": "d", "text": "Address underlying cause"}, {"id": "e", "text": "Oral vitamin D supplementation"}]'::jsonb, '["a", "c", "d", "e"]', 'Correct: rickets is treated with oral vitamin D supplementation (e), adequate calcium intake (a), sunlight exposure (c), and addressing the underlying cause (d). Wrong: pamidronate (a bisphosphonate) is used to strengthen bones in osteogenesis imperfecta (b).', true),
  ('msk', 48, 'The nurse reviews a radiology report for a 15-month-old with bowed legs: ''Cupped, frayed metaphyses at the wrists and knees.'' The infant also has delayed teeth. Which condition does this finding MOST likely indicate?', '[{"id": "a", "text": "Rickets"}, {"id": "b", "text": "Osteogenesis imperfecta"}, {"id": "c", "text": "Legg-Calvé-Perthes disease"}, {"id": "d", "text": "Developmental dysplasia of the hip"}]'::jsonb, '["a"]', 'Cupped, frayed metaphyses on X-ray are the classic radiographic sign of rickets, along with bowing and delayed dentition. OI is distinguished by blue sclerae and multiple fractures.', false),
  ('msk', 49, 'A 5-year-old with osteogenesis imperfecta who uses lightweight braces will start kindergarten next month. Which nursing action is BEST to protect the child at school?', '[{"id": "a", "text": "Advise keeping the child home until fractures stop"}, {"id": "b", "text": "Ask teachers to lift the child by the arms in transfers"}, {"id": "c", "text": "Educate school personnel about gentle handling"}, {"id": "d", "text": "Request that the child skip PT/OT during the school year"}]'::jsonb, '["c"]', 'OI nursing care includes educating the family and school personnel, with extremely gentle handling and continued PT/OT. Lifting by the arms is unsafe.', false),
  ('msk', 50, 'A 6-year-old boy with Legg-Calvé-Perthes disease is fitted with a brace. Which description of the brace''s purpose by the parent indicates understanding?', '[{"id": "a", "text": "It holds the leg turned outward so the hip is protected."}, {"id": "b", "text": "It corrects a curve in his spine over the next 2–4 years."}, {"id": "c", "text": "It keeps the foot from twisting inward and downward again."}, {"id": "d", "text": "It is an abduction brace that protects the femoral head."}]'::jsonb, '["d"]', 'LCP treatment protects the femoral head during regrowth, and bracing uses an abduction brace. An outward-turned leg is a sign of SCFE, and a foot twisted inward and downward is clubfoot.', false),
  ('integumentary', 1, 'A 9-month-old has had a diaper rash for 4 days despite frequent diaper changes and zinc oxide. The nurse finds a bright red, beefy rash that involves the skin folds, with small red spots scattered outside the main rash area. Which treatment should the nurse anticipate as MOST appropriate?', '[{"id": "a", "text": "Topical antifungal (nystatin cream)"}, {"id": "b", "text": "A thicker layer of zinc oxide barrier cream"}, {"id": "c", "text": "Topical mupirocin (Bactroban)"}, {"id": "d", "text": "Topical corticosteroid for flares"}]'::jsonb, '["a"]', 'Satellite lesions outside the main rash and involvement of the skin folds indicate a candidal (yeast) rash, treated with nystatin cream. Adding more zinc oxide barrier cream treats an irritant rash, which spares the folds.', false),
  ('integumentary', 2, 'The nurse assesses a 6-month-old whose diaper area is red and inflamed but the skin folds are spared and there are no lesions outside the rash. Which statements by the parent indicate understanding of the teaching? Select all that apply.', '[{"id": "a", "text": "\"I will change the diapers more frequently.\""}, {"id": "b", "text": "\"I will clean the area with alcohol wipes.\""}, {"id": "c", "text": "\"I will apply nystatin cream to the red area.\""}, {"id": "d", "text": "\"I will put zinc oxide cream on at diaper changes.\""}, {"id": "e", "text": "\"I will pat the skin dry and not rub it.\""}]'::jsonb, '["a", "d", "e"]', 'A rash that spares the skin folds is irritant diaper dermatitis. Patting dry (not rubbing), zinc oxide barrier cream, and frequent diaper changes are all correct treatment. Alcohol wipes should be avoided. Nystatin cream is the antifungal for a candidal rash with satellite lesions that involves the folds, not for an irritant rash.', true),
  ('integumentary', 3, 'A 7-month-old is brought to the clinic for itchy, inflamed, dry patches that come and go. The father has asthma and allergic rhinitis. Which assessment finding is an expected finding in this infant?', '[{"id": "a", "text": "Lesions in the flexural creases inside the elbows and behind the knees"}, {"id": "b", "text": "Silvery-white plaques on a red base over the elbows and knees"}, {"id": "c", "text": "Honey-colored crusted lesions around the mouth and nose"}, {"id": "d", "text": "Lesions on the cheeks, scalp, and extensor surfaces of arms and legs"}]'::jsonb, '["d"]', 'Relapsing itchy inflammation with a family history of the atopic triad suggests eczema; in infants it is distributed on the cheeks, scalp, and extensor surfaces (reaching, crawling areas). Flexural creases are the older-child distribution.', false),
  ('integumentary', 4, 'A 6-year-old with atopic dermatitis has red, excoriated patches inside both elbows and behind the knees and wakes at night scratching. Which instructions should the nurse include when teaching the parent? Select all that apply.', '[{"id": "a", "text": "Use the highest-potency topical corticosteroid for every flare"}, {"id": "b", "text": "Keep the child''s nails short to minimize excoriation"}, {"id": "c", "text": "Moisturize generously after every bath with fragrance-free emollients"}, {"id": "d", "text": "Give diphenhydramine for itch, especially at night"}, {"id": "e", "text": "Avoid triggers such as wool, harsh soaps, and fragrances"}]'::jsonb, '["b", "c", "d", "e"]', 'Eczema care includes generous fragrance-free emollients after every bath, short nails to minimize excoriation, an antihistamine (diphenhydramine) for itch especially at night, and avoiding triggers such as wool, harsh soaps, and fragrances. Topical corticosteroids are used for flares at the lowest effective potency, not the highest.', true),
  ('integumentary', 5, 'The nurse reviews home care with the parent of a 4-year-old who has a flare of eczema with flexural lesions. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll keep him from getting overheated and sweaty while he plays outside.\""}, {"id": "b", "text": "\"I''ll switch to a mild soap and avoid perfumed lotions.\""}, {"id": "c", "text": "\"I''ll use topical corticosteroids at the highest potency for flares.\""}, {"id": "d", "text": "\"I''ll put a fragrance-free moisturizer on him after every bath.\""}]'::jsonb, '["c"]', 'Topical corticosteroids for eczema flares are used at the lowest effective potency, so choosing the highest potency needs correction. Avoiding heat, sweating, harsh soaps, and fragrances and moisturizing after every bath are correct.', false),
  ('integumentary', 6, 'A 3-year-old with severe atopic dermatitis continues to have widespread inflamed, weeping patches despite fragrance-free emollients after every bath and a topical corticosteroid. Which additional therapy should the nurse anticipate NEXT?', '[{"id": "a", "text": "Oral griseofulvin"}, {"id": "b", "text": "Wet wrap therapy"}, {"id": "c", "text": "Coal tar preparations"}, {"id": "d", "text": "Permethrin 5% cream"}]'::jsonb, '["b"]', 'Wet wrap therapy is listed for severe cases of eczema. Coal tar preparations are a psoriasis treatment, oral griseofulvin treats tinea capitis, and permethrin 5% treats scabies.', false),
  ('integumentary', 7, 'In August, a 5-year-old who attends daycare has two lesions near the nose that began as red sores, ruptured, and are now covered with honey-colored crusts. The rest of the skin is clear. Which treatment should the nurse anticipate as MOST appropriate?', '[{"id": "a", "text": "Oral antibiotics for 10 days"}, {"id": "b", "text": "Topical mupirocin (Bactroban)"}, {"id": "c", "text": "Topical antifungal (nystatin cream)"}, {"id": "d", "text": "Permethrin 5% cream applied to the face"}]'::jsonb, '["b"]', 'Honey-colored crusted lesions around the nose indicate impetigo; limited lesions are treated with topical mupirocin. Oral antibiotics are reserved for widespread impetigo.', false),
  ('integumentary', 8, 'A 6-year-old with widespread honey-colored crusted lesions on the face and hands received the first dose of an oral antibiotic at 9:00 a.m. on Monday. The parent asks when the child may return to school. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"She may return 24 hours after antibiotics started: Tuesday at 9:00 a.m.\""}, {"id": "b", "text": "\"She may return once the first antibiotic dose is taken: today.\""}, {"id": "c", "text": "\"She may return once every crust has completely healed and fallen off.\""}, {"id": "d", "text": "\"She may return 7 days after antibiotics started: next Monday.\""}]'::jsonb, '["a"]', 'A child with impetigo should stay home until 24 hours after antibiotics are started, which is Tuesday 9:00 a.m. Returning after the first dose is too early, and waiting until every crust heals is longer than required.', false),
  ('integumentary', 9, 'A 4-year-old has several golden crusted lesions around the mouth and on the hands, and two siblings live in the home. Which measures should the nurse teach the family to limit spread? Select all that apply.', '[{"id": "a", "text": "Apply zinc oxide barrier cream over the crusts"}, {"id": "b", "text": "Perform meticulous hand hygiene after touching the lesions"}, {"id": "c", "text": "Give the child separate towels and linens"}, {"id": "d", "text": "Treat every household member with permethrin 5%"}, {"id": "e", "text": "Keep the child home until all crusts have healed"}]'::jsonb, '["b", "c"]', 'Honey-colored (golden) crusted lesions indicate impetigo, a highly contagious bacterial infection; meticulous hand hygiene and separate towels/linens limit spread. Zinc oxide is a diaper-rash barrier, treating the whole household with permethrin 5% is scabies care, and the child only needs to stay home until 24 hours after antibiotics are started, not until all crusts heal.', true),
  ('integumentary', 10, 'A school nurse examines a 7-year-old sent from class for intense scalp itching. No live insects are seen on the top of the head. Where should the nurse look NEXT to MOST likely find nits?', '[{"id": "a", "text": "Along the part line at the crown of the head"}, {"id": "b", "text": "Between the fingers and on the wrists"}, {"id": "c", "text": "On the cheeks and extensor surfaces"}, {"id": "d", "text": "Behind the ears and at the nape of the neck"}]'::jsonb, '["d"]', 'Nits are eggs cemented to hair shafts, found especially behind the ears and at the nape of the neck. Between the fingers and wrists is where scabies burrows are found.', false),
  ('integumentary', 11, 'A 6-year-old has live lice and nits on the hair shafts, and the parent has just completed the first permethrin 1% (Nix) treatment. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Notify the school or daycare"}, {"id": "b", "text": "Use a fine-tooth nit comb to remove nits daily"}, {"id": "c", "text": "Vacuum the furniture and car seats"}, {"id": "d", "text": "Wash bedding and stuffed animals in hot water; dry on high heat"}, {"id": "e", "text": "Apply permethrin 5% cream from the neck to the toes"}]'::jsonb, '["a", "b", "c", "d"]', 'Head lice care includes daily nit combing, washing bedding, clothing, towels and stuffed animals in hot water and drying on high heat, vacuuming furniture and car seats, and notifying the school/daycare. Permethrin 5% cream applied from neck to toes is the scabies treatment.', true),
  ('integumentary', 12, 'The nurse teaches the parent of a 5-year-old with intense scalp itching and nits cemented to the hair shafts. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"She probably caught them from head-to-head contact with a friend.\""}, {"id": "b", "text": "\"I''ll let her daycare know so they can check the other children.\""}, {"id": "c", "text": "\"She got these because we don''t wash her hair often enough.\""}, {"id": "d", "text": "\"I''ll wash her stuffed animals in hot water and dry them on high heat.\""}]'::jsonb, '["c"]', 'Head lice are spread by direct head-to-head contact and are not a sign of poor hygiene, so blaming hair washing needs correction. Notifying daycare and hot-water washing with high-heat drying are correct.', false),
  ('integumentary', 13, 'A parent applied permethrin 1% (Nix) to a 7-year-old''s hair on Monday and has combed out nits daily. The parent asks whether anything else is needed. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Repeat the treatment tomorrow to kill any surviving eggs.\""}, {"id": "b", "text": "\"Repeat the treatment in 2 to 4 weeks if itching continues.\""}, {"id": "c", "text": "\"Repeat the treatment in 7 to 9 days to kill newly hatched lice.\""}, {"id": "d", "text": "\"No repeat treatment is needed as long as you comb out the nits daily.\""}]'::jsonb, '["c"]', 'Lice treatment is repeated in 7–9 days to kill newly hatched lice. The 2–4 week timeframe refers to itching that may persist after scabies treatment, not lice retreatment.', false),
  ('integumentary', 14, 'A 3-year-old pulled a cup of hot coffee onto herself. The forearm is blistered, moist, and red/pink, and she screams when it is touched. A patch on the chest is white, waxy, and dry, and she does not react when it is touched. The parent says, "At least the chest isn''t hurting her." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"The chest burn is superficial and should heal on its own in 3 to 5 days.\""}, {"id": "b", "text": "\"The chest burn is full-thickness; it is painless from nerve destruction.\""}, {"id": "c", "text": "\"The forearm burn is the most serious one because it is so very painful.\""}, {"id": "d", "text": "\"The chest burn should heal in 2 to 3 weeks without any grafting.\""}]'::jsonb, '["b"]', 'White, waxy, dry, painless skin indicates a full-thickness burn; it is painless because of nerve destruction, which is a red flag, and it requires grafting. The blistered, very painful forearm is partial-thickness.', false),
  ('integumentary', 15, 'An 8-year-old spent the afternoon outdoors and now has a burn on the shoulders that is red and dry with no blisters, and the child says it is painful. The parent asks how long it will take to heal. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"It should heal in about 3 to 5 days.\""}, {"id": "b", "text": "\"It should heal in about 2 to 3 weeks.\""}, {"id": "c", "text": "\"It will need skin grafting to heal.\""}, {"id": "d", "text": "\"It should heal in about 7 to 9 days.\""}]'::jsonb, '["a"]', 'Red, dry, painful skin without blisters (like sunburn) is a superficial (1st degree) burn, which heals in 3–5 days. Two to three weeks is the healing time for partial-thickness burns with blisters.', false),
  ('integumentary', 16, 'A 6-year-old is admitted after a house fire with burns of varying depth on the legs. Which assessment findings indicate that an area is a full-thickness burn? Select all that apply.', '[{"id": "a", "text": "The skin is red and dry and very painful"}, {"id": "b", "text": "The surface is moist and red/pink with blisters"}, {"id": "c", "text": "The surface is dry with no blisters"}, {"id": "d", "text": "The child does not report pain in the area"}, {"id": "e", "text": "The surface is white, waxy, or leathery"}]'::jsonb, '["c", "d", "e"]', 'Full-thickness burns are white, waxy, leathery, or charred; dry with no blisters; and painless because of nerve destruction. Moist red/pink skin with blisters is partial-thickness, and red, dry, painful skin is superficial.', true),
  ('integumentary', 17, 'A 5-year-old is carried from a house fire with burns to the face, chest, and both arms. The child is crying, and the provider has ordered IV access, pain medication, and silver sulfadiazine dressings. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Calculate IV fluid needs using the Parkland formula"}, {"id": "b", "text": "Administer the prescribed pain medication"}, {"id": "c", "text": "Apply silver sulfadiazine with sterile dressings"}, {"id": "d", "text": "Assess the airway for edema from the facial burns"}]'::jsonb, '["d"]', 'Facial/inhalation burns make the airway the top priority because edema can obstruct rapidly. Parkland fluids come next, followed by pain management and infection prevention.', false),
  ('integumentary', 18, 'A 20-kg child has partial- and full-thickness burns covering 30% TBSA. Using the Parkland formula, at what hourly rate should the nurse infuse IV fluids during the FIRST 8 hours after the burn?', '[{"id": "a", "text": "300 mL/hr"}, {"id": "b", "text": "100 mL/hr"}, {"id": "c", "text": "75 mL/hr"}, {"id": "d", "text": "150 mL/hr"}]'::jsonb, '["d"]', 'Parkland: 4 mL × 20 kg × 30% = 2,400 mL in 24 hours; half (1,200 mL) is given in the first 8 hours = 150 mL/hr. 300 mL/hr gives the full 24-hour volume in 8 hours, and 100 mL/hr spreads it evenly over 24 hours.', false),
  ('integumentary', 19, 'A 10-kg toddler has a scald burn covering the entire head and neck and one entire arm. Using the child adjustments to the Rule of Nines and the Parkland formula, how much IV fluid should the nurse expect to give in the FIRST 8 hours?', '[{"id": "a", "text": "360 mL"}, {"id": "b", "text": "1,080 mL"}, {"id": "c", "text": "540 mL"}, {"id": "d", "text": "270 mL"}]'::jsonb, '["c"]', 'In a child, head and neck = 18% and each arm = 9%, so TBSA = 27%. Parkland: 4 × 10 × 27 = 1,080 mL in 24 hours, half (540 mL) in the first 8 hours. 360 mL results from using the adult head value of 9%.', false),
  ('integumentary', 20, 'A 6-year-old has a circumferential full-thickness burn encircling the left lower leg. Which nursing assessment is MOST important to perform frequently on this extremity?', '[{"id": "a", "text": "Check pain at the burn to track depth"}, {"id": "b", "text": "Monitor for compartment syndrome"}, {"id": "c", "text": "Monitor for hyperthermia from the burn"}, {"id": "d", "text": "Check for new blisters to stage healing"}]'::jsonb, '["b"]', 'Circumferential burns can cause compartment syndrome that may require escharotomy. Pain cannot be used to track a full-thickness burn because it is painless, and the burned child is at risk for hypothermia, not hyperthermia.', false),
  ('integumentary', 21, 'A 2-year-old with burns over 40% TBSA is scheduled for a dressing change in the burn unit. Which nursing action is MOST important during the procedure?', '[{"id": "a", "text": "Keep the child warm to prevent hypothermia"}, {"id": "b", "text": "Use clean, nonsterile dressings to shorten the procedure"}, {"id": "c", "text": "Leave the burns uncovered to air dry"}, {"id": "d", "text": "Hold pain medication until it is done"}]'::jsonb, '["a"]', 'Burned children are at risk for hypothermia because of their large surface area and fluid loss, so warmth must be maintained. Dressings must be sterile, and pain management is a nursing priority, not something to hold.', false),
  ('integumentary', 22, 'A 7-year-old has partial- and full-thickness burns over 25% TBSA and has been receiving Parkland fluids for 4 hours. Which interventions belong in the plan of care? Select all that apply.', '[{"id": "a", "text": "Give the first half of the Parkland volume over 16 hours"}, {"id": "b", "text": "Apply topical silver sulfadiazine under sterile dressings"}, {"id": "c", "text": "Prevent hypothermia during dressing changes"}, {"id": "d", "text": "Provide pain management"}, {"id": "e", "text": "Omit pain assessment over the full-thickness areas"}]'::jsonb, '["b", "c", "d"]', 'Burn priorities include infection prevention with sterile dressings and topical silver sulfadiazine, pain management, and preventing hypothermia. The first half of the Parkland volume is given in the first 8 hours, not 16, and full-thickness areas are painless but the child must still be monitored and treated aggressively.', true),
  ('integumentary', 23, 'A 4-year-old has a scald burn covering the entire right leg and the front of the trunk only. Using the child adjustments to the Rule of Nines, which TBSA should the nurse document as MOST accurate?', '[{"id": "a", "text": "32%"}, {"id": "b", "text": "36%"}, {"id": "c", "text": "50%"}, {"id": "d", "text": "28%"}]'::jsonb, '["a"]', 'In a child, each leg = 14% and the anterior trunk = 18%, so 14% + 18% = 32%. 36% uses the adult leg value of 18%, and 50% adds the posterior trunk, which is not burned.', false),
  ('integumentary', 24, 'A new graduate nurse begins estimating the burn size of a 2-year-old using the adult Rule of Nines, assigning 9% to the head and 18% to each leg. Which action by the precepting nurse is BEST?', '[{"id": "a", "text": "Approve the adult values because the child is older than 1 year"}, {"id": "b", "text": "Advise counting the head as 9% and each leg as 14%"}, {"id": "c", "text": "Advise estimating TBSA after Parkland fluids start"}, {"id": "d", "text": "Advise using the Lund and Browder Chart for this child"}]'::jsonb, '["d"]', 'The Lund and Browder Chart is the most accurate method for pediatric burns because it accounts for age-based changes in head and leg size. Children''s head is 18% and each leg 14%, so adult values are inaccurate.', false),
  ('integumentary', 25, 'The emergency department nurse is triaging four children with burns. Which child should the nurse see FIRST because the presentation requires IMMEDIATE follow-up for possible abuse?', '[{"id": "a", "text": "A 3-year-old with irregular splash burns after pulling a pot"}, {"id": "b", "text": "A 4-year-old with a blister on one finger from a stove"}, {"id": "c", "text": "A 2-year-old with a uniform scald line around both feet"}, {"id": "d", "text": "A 9-year-old with red, dry, painful shoulders after a beach day"}]'::jsonb, '["c"]', 'A uniform stocking distribution and bilateral symmetric burns suggest the child was held in hot water; defensive splashing creates an irregular burn. Irregular splash burns from pulling a pot fit an accidental mechanism.', false),
  ('integumentary', 26, 'An 18-month-old is brought to the emergency department with scald burns. Which findings should the nurse recognize as indicators of non-accidental trauma that require follow-up? Select all that apply.', '[{"id": "a", "text": "An irregular splash pattern on one forearm"}, {"id": "b", "text": "Older burns at a different stage of healing"}, {"id": "c", "text": "Both hands are equally burned"}, {"id": "d", "text": "Burns on the buttocks and perineum"}, {"id": "e", "text": "The caregiver waited 2 days to seek care"}]'::jsonb, '["b", "c", "d", "e"]', 'Burns on the buttocks/perineum (dunking pattern), delay in seeking care, multiple burns at different stages of healing, and bilateral symmetric burns are abuse indicators. An irregular burn pattern fits defensive splashing, which occurs with accidental contact rather than being held in hot water.', true),
  ('integumentary', 27, 'A 2-year-old has a uniform scald line on both hands. The caregiver states the child "climbed into the sink and turned on the hot water." Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Wait for the provider to confirm abuse before reporting"}, {"id": "b", "text": "Report to CPS and notify the charge nurse/provider"}, {"id": "c", "text": "Ask the caregiver why the story keeps changing"}, {"id": "d", "text": "Document that the caregiver most likely caused the burn"}]'::jsonb, '["b"]', 'A stocking/glove pattern with a history that does not fit the pattern or child''s development is suspicious; nurses are mandatory reporters and must report suspected abuse to CPS and notify the charge nurse/provider immediately. Reporting does not wait for confirmation.', false),
  ('integumentary', 28, 'The nurse suspects non-accidental trauma in a 3-year-old with bilateral symmetric burns on both feet. Which documentation entry is MOST appropriate?', '[{"id": "a", "text": "\"Burn pattern is consistent with abuse by the child''s mother.\""}, {"id": "b", "text": "Exact location, shape, size, and the caregiver''s explanation"}, {"id": "c", "text": "\"Caregiver appears nervous and guilty when questioned.\""}, {"id": "d", "text": "\"Small foot burns; story seems suspicious to this nurse.\""}]'::jsonb, '["b"]', 'Documentation must be objective: exact burn location, shape, size, and the caregiver''s explanation. Conclusions about who caused the burn or judgments about the caregiver''s demeanor are not objective.', false),
  ('integumentary', 29, 'A 9-year-old has intense itching that is worse at night, small red bumps, and thin, thread-like lines under the skin between the fingers and at the wrists. A sibling has started itching too. Which treatment should the nurse anticipate?', '[{"id": "a", "text": "Permethrin 5% cream applied from neck to toes"}, {"id": "b", "text": "Permethrin 1% lotion applied to the hair"}, {"id": "c", "text": "Topical mupirocin applied to the lines"}, {"id": "d", "text": "Topical clotrimazole or miconazole for 2–4 weeks"}]'::jsonb, '["a"]', 'Itching worse at night with burrow tracks between the fingers and wrists indicates scabies, treated with permethrin 5% cream applied from neck to toes. Permethrin 1% (Nix) is the head lice treatment.', false),
  ('integumentary', 30, 'A 7-year-old has itching that is worse at night and burrow tracks along the waist and axillae. The parent is being taught about the prescribed permethrin 5% cream. Which statements by the parent indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"I''ll leave it on 8 to 14 hours, then wash it off.\""}, {"id": "b", "text": "\"I''ll apply it from her neck to her toes.\""}, {"id": "c", "text": "\"I''ll rinse it off after 10 minutes like the lice treatment.\""}, {"id": "d", "text": "\"All household members and close contacts will be treated together.\""}, {"id": "e", "text": "\"Only people with an itchy rash need to use the cream.\""}]'::jsonb, '["a", "b", "d"]', 'Permethrin 5% is applied from neck to toes, left on 8–14 hours, then washed off, and all household members and close contacts are treated simultaneously. Leaving on 10 minutes is the permethrin 1% lice regimen, and treating only symptomatic people misses contacts.', true),
  ('integumentary', 31, 'Two weeks after a correctly applied permethrin 5% treatment for scabies, a 10-year-old still reports itching, but no new burrow tracks are seen. The parent asks whether the treatment failed. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Persistent itching means the treatment failed, so reapply it tonight.\""}, {"id": "b", "text": "\"He is likely allergic to permethrin, so stop using the cream.\""}, {"id": "c", "text": "\"Itching should resolve within 24 hours; he needs an oral drug.\""}, {"id": "d", "text": "\"Itching may persist 2 to 4 weeks; it doesn''t mean treatment failed.\""}]'::jsonb, '["d"]', 'Itching may persist 2–4 weeks after successful scabies treatment because the inflammatory response continues; it does NOT mean treatment failed. Reapplying because of itching alone is not indicated.', false),
  ('integumentary', 32, 'A 4-month-old lives with an older sibling who was just diagnosed with scabies, and the infant has become fussy and irritable. Where should the nurse expect scabies lesions in this infant? Select all that apply.', '[{"id": "a", "text": "Behind the ears and nape of the neck"}, {"id": "b", "text": "Face and scalp"}, {"id": "c", "text": "Extensor surfaces of elbows and knees"}, {"id": "d", "text": "Palms and soles"}, {"id": "e", "text": "Groin with sparing of the scrotum"}]'::jsonb, '["b", "d"]', 'In infants, scabies is found on the palms, soles, face, and scalp. Behind the ears and nape of the neck is where lice nits are found, extensor surfaces of elbows and knees are typical for psoriasis plaques, and a groin rash sparing the scrotum is tinea cruris.', true),
  ('integumentary', 33, 'A 10-year-old started carbamazepine 2 weeks ago. After 2 days of high fever and malaise, the child now has a painful red/purple rash spreading rapidly, mouth ulcers, and eye inflammation. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Apply a topical corticosteroid to the rash"}, {"id": "b", "text": "Give diphenhydramine and recheck in 1 hour"}, {"id": "c", "text": "Hold the carbamazepine and notify the provider"}, {"id": "d", "text": "Request an ophthalmology consult for the eye inflammation"}]'::jsonb, '["c"]', 'Fever and malaise followed by a rapidly spreading painful rash with mucosal involvement after starting an anticonvulsant suggests SJS; the priority is to stop the offending drug immediately. An ophthalmology consult is needed if the eyes are involved, but it does not come before stopping the drug.', false),
  ('integumentary', 34, 'A 12-year-old taking TMP-SMX develops a painful rash after a febrile prodrome, and the skin is sloughing off in sheets over an estimated 35% of BSA. The nurse recognizes this presentation as which condition?', '[{"id": "a", "text": "Stevens-Johnson syndrome, because SJS affects over 30% of BSA"}, {"id": "b", "text": "A full-thickness burn that will require grafting"}, {"id": "c", "text": "Toxic Epidermal Necrolysis (TEN), the more severe form"}, {"id": "d", "text": "Bullous impetigo with fluid-filled staph blisters"}]'::jsonb, '["c"]', 'SJS affects less than 10% of BSA; involvement greater than 30% is Toxic Epidermal Necrolysis (TEN), which is more severe. Sloughing after a sulfa drug is a drug reaction, not a burn or bullous impetigo.', false),
  ('integumentary', 35, 'A 9-year-old with Stevens-Johnson syndrome after starting lamotrigine has skin sloughing in sheets, mouth ulcers, and eye inflammation and is admitted to the burn unit. The causative drug has been discontinued. Which interventions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Sterile wound care"}, {"id": "b", "text": "An ophthalmology consult"}, {"id": "c", "text": "Nutritional support"}, {"id": "d", "text": "Restart lamotrigine at a lower dose"}, {"id": "e", "text": "IV fluids as for a burn patient"}]'::jsonb, '["a", "b", "c", "e"]', 'SJS is treated like a burn: IV fluids, infection prevention, sterile wound care, pain control, and nutritional support, with an ophthalmology consult if the eyes are involved. The offending drug is discontinued, not restarted at a lower dose.', true),
  ('integumentary', 36, 'The nurse in a pediatric urgent care clinic is reviewing four children with eye complaints. Which child should the nurse see FIRST?', '[{"id": "a", "text": "A 4-year-old with eyelid swelling after an insect bite and normal vision"}, {"id": "b", "text": "A 6-year-old with a bulging eye and pain with eye movement"}, {"id": "c", "text": "A 7-year-old with a stye and a red eyelid but no pain with eye movement"}, {"id": "d", "text": "A 5-year-old with honey-colored crusts at the nostrils and upper lip"}]'::jsonb, '["b"]', 'Pain with eye movement plus proptosis indicates orbital cellulitis, an emergency with risk of vision loss and meningitis. Eyelid swelling without pain on eye movement or vision change is periorbital (preseptal) cellulitis, which is serious but manageable.', false),
  ('integumentary', 37, 'A 3-year-old with a red, swollen eyelid after an insect bite has no pain with eye movement, no vision changes, and no proptosis and is being discharged on oral amoxicillin-clavulanate. Which instruction is MOST important to give the caregiver?', '[{"id": "a", "text": "Return immediately if the eye bulges or eye movement becomes painful"}, {"id": "b", "text": "Expect mild pain with eye movement as the swelling resolves"}, {"id": "c", "text": "Return if the eyelid is still red after the antibiotic course is completed"}, {"id": "d", "text": "Apply topical mupirocin to the eyelid three times a day"}]'::jsonb, '["a"]', 'Caregivers must return immediately if the eye bulges, vision changes, or eye movement becomes painful, because these signal orbital cellulitis, an emergency. Pain with eye movement is absent in periorbital cellulitis.', false),
  ('integumentary', 38, 'A 9-month-old has a red, swollen eyelid after a scratch, with normal eye movement and no proptosis. Which treatment plan should the nurse anticipate as MOST appropriate?', '[{"id": "a", "text": "Oral amoxicillin-clavulanate with follow-up at home"}, {"id": "b", "text": "Surgical drainage with an ophthalmology consult"}, {"id": "c", "text": "Topical mupirocin applied to the eyelid scratch"}, {"id": "d", "text": "IV antibiotics because the infant is under 1 year"}]'::jsonb, '["d"]', 'Eyelid swelling without pain on eye movement or proptosis is periorbital (preseptal) cellulitis; mild cases receive oral amoxicillin-clavulanate, but IV antibiotics are used if the child is under 1 year. Surgical drainage is for orbital cellulitis.', false),
  ('integumentary', 39, 'An 8-year-old with ethmoid sinusitis now has a swollen, red eyelid. Which additional findings indicate orbital rather than periorbital cellulitis and require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Changes in vision"}, {"id": "b", "text": "Swelling limited to the eyelid"}, {"id": "c", "text": "Proptosis (bulging eye)"}, {"id": "d", "text": "A recent stye on the same eyelid"}, {"id": "e", "text": "Pain with eye movement"}]'::jsonb, '["a", "c", "e"]', 'Pain with eye movement (key sign), proptosis, and possible vision changes indicate orbital cellulitis, an emergency. Swelling limited to the eyelid (in front of the orbital septum) is periorbital cellulitis, and a stye is a common cause of periorbital cellulitis.', true),
  ('integumentary', 40, 'An 8-year-old has circular patches of hair loss with scaling and a boggy swelling on the scalp. Which prescription should the nurse anticipate as the MOST appropriate primary treatment?', '[{"id": "a", "text": "Topical clotrimazole"}, {"id": "b", "text": "Selenium sulfide shampoo"}, {"id": "c", "text": "Permethrin 1% (Nix)"}, {"id": "d", "text": "Oral griseofulvin"}]'::jsonb, '["d"]', 'Circular patches of hair loss with scaling and a kerion indicate tinea capitis, which requires oral griseofulvin because topical antifungals don''t penetrate hair follicles. Selenium sulfide shampoo is only an adjunct.', false),
  ('integumentary', 41, 'The nurse is teaching the parent of a 7-year-old who has scalp ringworm with circular patches of hair loss. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"She''ll take griseofulvin by mouth since creams can''t reach the follicles.\""}, {"id": "b", "text": "\"She can go back to school once her treatment has been started.\""}, {"id": "c", "text": "\"She can keep sharing combs, hats, and hair accessories with her sister.\""}, {"id": "d", "text": "\"I''ll use the selenium sulfide shampoo along with her medicine.\""}]'::jsonb, '["c"]', 'Children with tinea capitis must not share combs, hats, or hair accessories. Oral griseofulvin, adjunct selenium sulfide shampoo, and exclusion from school only until treatment is started are correct.', false),
  ('integumentary', 42, 'A 6-year-old has a ring-shaped, red, scaly plaque with central clearing and a raised border on the forearm. The parent asks, "Is it a worm?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"It''s a fungal infection that requires oral griseofulvin to clear it.\""}, {"id": "b", "text": "\"It''s a fungal infection; use topical clotrimazole for 2–4 weeks.\""}, {"id": "c", "text": "\"It''s a bacterial infection treated with topical mupirocin cream.\""}, {"id": "d", "text": "\"It''s a parasite, so the whole household needs permethrin 5%.\""}]'::jsonb, '["b"]', 'A ring-shaped scaly plaque with central clearing on the body is tinea corporis, a fungal infection (not a worm) treated with topical clotrimazole or miconazole for 2–4 weeks. Oral griseofulvin is required for tinea capitis on the scalp.', false),
  ('integumentary', 43, 'A 15-year-old on the swim team has scaling, cracking, and maceration between the toes with itching and burning. Which instructions should the nurse give? Select all that apply.', '[{"id": "a", "text": "Take oral griseofulvin since creams cannot reach the area"}, {"id": "b", "text": "Apply a topical antifungal such as clotrimazole or terbinafine"}, {"id": "c", "text": "Apply a topical corticosteroid as the main treatment"}, {"id": "d", "text": "Apply zinc oxide barrier cream between the toes"}, {"id": "e", "text": "Keep feet dry and wear moisture-wicking socks"}]'::jsonb, '["b", "e"]', 'Scaling, cracking, and maceration between the toes is tinea pedis, treated with a topical antifungal (clotrimazole/terbinafine), keeping feet dry, and moisture-wicking socks. Oral griseofulvin is for tinea capitis because topicals don''t penetrate hair follicles, corticosteroids are for eczema and psoriasis, and zinc oxide is an irritant diaper rash barrier.', true),
  ('integumentary', 44, 'A 10-year-old whose father has a chronic skin disease has well-defined silvery-white plaques on a red base over the elbows and knees; pinpoint bleeding occurs when a scale is removed. Which treatment should the nurse anticipate FIRST?', '[{"id": "a", "text": "Topical corticosteroids and topical calcipotriene"}, {"id": "b", "text": "Oral griseofulvin with a selenium sulfide shampoo"}, {"id": "c", "text": "Oral isotretinoin with monthly pregnancy tests"}, {"id": "d", "text": "Methotrexate with UVB phototherapy"}]'::jsonb, '["a"]', 'Silvery plaques on extensor surfaces with the Auspitz sign indicate psoriasis; first-line treatment is topical corticosteroids and topical calcipotriene. Phototherapy and methotrexate are reserved for severe cases.', false),
  ('integumentary', 45, 'Two weeks after a sore throat, a 7-year-old develops many small droplet-shaped, scaly lesions on the trunk. Which nursing action is MOST important?', '[{"id": "a", "text": "Treat the strep (streptococcal pharyngitis)"}, {"id": "b", "text": "Apply topical clotrimazole to each lesion for 2 to 4 weeks"}, {"id": "c", "text": "Begin wet wrap therapy and keep the nails short"}, {"id": "d", "text": "Keep the child home until 24 hours of antibiotics"}]'::jsonb, '["a"]', 'Droplet-shaped lesions after strep throat indicate guttate psoriasis, which is often triggered by streptococcal pharyngitis, so the strep must be treated. Staying home until 24 hours after antibiotics is the impetigo rule.', false),
  ('integumentary', 46, 'A 12-year-old with a family history of psoriasis is examined for scaly skin lesions. Which findings support this diagnosis? Select all that apply.', '[{"id": "a", "text": "Ring-shaped plaque with central clearing"}, {"id": "b", "text": "Silvery-white plaques on the elbows and knees"}, {"id": "c", "text": "New plaques forming at sites of skin trauma"}, {"id": "d", "text": "Thread-like burrow tracks between the fingers"}, {"id": "e", "text": "Pinpoint bleeding when a scale is removed"}]'::jsonb, '["b", "c", "e"]', 'Psoriasis findings include the Auspitz sign (pinpoint bleeding when scale is removed), the Koebner phenomenon (new plaques at sites of skin trauma), and silvery-white plaques on extensor surfaces. Burrow tracks indicate scabies, and a ring-shaped plaque with central clearing is tinea corporis.', true),
  ('integumentary', 47, 'A 14-year-old has many open and closed comedones on the forehead and nose, with no papules, pustules, or nodules. Which treatment plan should the nurse anticipate as BEST?', '[{"id": "a", "text": "Topical clindamycin plus oral doxycycline"}, {"id": "b", "text": "Oral isotretinoin with enrollment in the iPLEDGE program"}, {"id": "c", "text": "Oral doxycycline as a single therapy"}, {"id": "d", "text": "Topical tretinoin plus topical benzoyl peroxide"}]'::jsonb, '["d"]', 'Comedones only is mild acne, treated first-line with topical retinoids (tretinoin) plus topical benzoyl peroxide. Topical clindamycin ± oral doxycycline is added for moderate acne with papules/pustules, and isotretinoin is for severe nodular/cystic acne.', false),
  ('integumentary', 48, 'A 16-year-old female with nodular and cystic acne is starting oral isotretinoin (Accutane). Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Get extra sun exposure to dry the lesions"}, {"id": "b", "text": "Take a vitamin A supplement for the skin"}, {"id": "c", "text": "Have monthly negative pregnancy tests"}, {"id": "d", "text": "Do not donate blood during treatment"}, {"id": "e", "text": "Use two forms of contraception"}]'::jsonb, '["c", "d", "e"]', 'Isotretinoin is highly teratogenic, so females must use two forms of contraception and have monthly negative pregnancy tests, and they must not donate blood. Vitamin A supplements are not allowed, and sun exposure should be avoided.', true),
  ('integumentary', 49, 'The nurse is calling four adolescents who are taking oral isotretinoin. Which statement requires IMMEDIATE follow-up?', '[{"id": "a", "text": "\"I wear sunscreen and stay out of the sun when we go to the beach this summer.\""}, {"id": "b", "text": "\"I canceled my eyebrow waxing until treatment is done.\""}, {"id": "c", "text": "\"I''ve had no pregnancy tests lately, and we use one form of contraception.\""}, {"id": "d", "text": "\"I told the school blood drive that I can''t donate.\""}]'::jsonb, '["c"]', 'Isotretinoin is highly teratogenic (Category X); females need two forms of contraception and monthly negative pregnancy tests, so missed tests with one method require immediate follow-up. Avoiding sun, waxing, and blood donation are correct.', false),
  ('integumentary', 50, 'A 17-year-old with acne has mainly papules and pustules on the face and has used topical tretinoin and benzoyl peroxide for several months. Which addition to the plan should the nurse anticipate NEXT?', '[{"id": "a", "text": "Oral isotretinoin with iPLEDGE enrollment"}, {"id": "b", "text": "Topical clindamycin ± oral doxycycline"}, {"id": "c", "text": "Topical nystatin cream"}, {"id": "d", "text": "Selenium sulfide shampoo"}]'::jsonb, '["b"]', 'Papules and pustules are moderate acne, for which topical antibiotics (clindamycin) ± oral doxycycline are added. Oral isotretinoin is reserved for severe nodular/cystic acne.', false),
  ('eent', 1, 'Six hours after a tonsillectomy, a 6-year-old is resting quietly, but the nurse observes the child swallowing every few seconds while asleep. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Offer a cool popsicle to soothe the child''s sore throat."}, {"id": "b", "text": "Treat it as an emergency and report possible bleeding."}, {"id": "c", "text": "Apply the ice collar for comfort and reassess in 1 hour."}, {"id": "d", "text": "Encourage the child to cough and clear the throat now."}]'::jsonb, '["b"]', 'Frequent swallowing after tonsillectomy signals bleeding and is an emergency, so the provider is notified immediately. Popsicles and the ice collar are comfort measures that delay care, and coughing or clearing the throat can dislodge the clot.', false),
  ('eent', 2, 'The nurse on a pediatric unit receives report on four children. Which child should the nurse assess FIRST?', '[{"id": "a", "text": "A 2-year-old with a barking cough and low-grade fever on cool mist"}, {"id": "b", "text": "A 10-month-old with fever who is tugging at the right ear"}, {"id": "c", "text": "A 7-year-old who keeps clearing the throat after tonsillectomy"}, {"id": "d", "text": "A 5-year-old with watery eyes that began after a cold"}]'::jsonb, '["c"]', 'Clearing the throat after tonsillectomy is a sign of bleeding, which is an emergency. Croup with low-grade fever on cool mist, otitis media with ear tugging and fever, and viral conjunctivitis are not immediately life-threatening.', false),
  ('eent', 3, 'The nurse teaches the parent of a 5-year-old being discharged after tonsillectomy. Which signs should the parent be taught to treat as an emergency? Select all that apply.', '[{"id": "a", "text": "Throat pain that increases on day 6"}, {"id": "b", "text": "Frequent swallowing"}, {"id": "c", "text": "Frequent clearing of the throat"}, {"id": "d", "text": "Coughing blood"}, {"id": "e", "text": "Spitting of bright red blood"}]'::jsonb, '["b", "c", "d", "e"]', 'Frequent swallowing, clearing the throat, coughing blood, and spitting bright red blood indicate post-tonsillectomy hemorrhage, an emergency requiring an immediate return to the ER. Pain peaking on day 5–7 as the clot separates is expected, and the family is taught to anticipate it.', true),
  ('eent', 4, 'The nurse reviews discharge teaching with the parent of an 8-year-old after tonsillectomy. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll give him popsicles and cool water to drink.\""}, {"id": "b", "text": "\"He''ll avoid crunchy foods like chips for 2 weeks.\""}, {"id": "c", "text": "\"An ice collar can help keep him comfortable.\""}, {"id": "d", "text": "\"Cherry gelatin will be a good soft food for him.\""}]'::jsonb, '["d"]', 'Red or dark liquids are avoided because they look like blood if vomited, so cherry gelatin needs correction. Cool fluids, avoiding hard or crunchy foods for 2 weeks, and an ice collar are all correct.', false),
  ('eent', 5, 'On the evening after a 4-year-old''s tonsillectomy, the nurse observes the parent''s actions at the bedside. Which action by the parent requires IMMEDIATE intervention?', '[{"id": "a", "text": "Offering the child ice chips from a cup"}, {"id": "b", "text": "Placing an ice collar around the child''s neck"}, {"id": "c", "text": "Giving the child cool water through a straw"}, {"id": "d", "text": "Offering a cool, non-red popsicle"}]'::jsonb, '["c"]', 'Straws are avoided because suction can dislodge the clot and cause bleeding. Ice chips, an ice collar and cool non-red popsicles are recommended after tonsillectomy.', false),
  ('eent', 6, 'A parent calls on postoperative day 6 after a 7-year-old''s tonsillectomy. The child reports worse throat pain than yesterday but is drinking cool fluids, and there is no bleeding or frequent swallowing. Which response by the nurse is BEST?', '[{"id": "a", "text": "Go to the emergency room now, because this is a hemorrhage."}, {"id": "b", "text": "Pain peaks on day 5–7 as the clot separates; expect this."}, {"id": "c", "text": "Give warm soup and toast to coat the throat and ease the pain."}, {"id": "d", "text": "Have him gargle forcefully to clean the surgical area."}]'::jsonb, '["b"]', 'Pain peaks on day 5–7 when the clot separates, and the family is taught to expect this; without bleeding signs, this is not a hemorrhage. Hot foods and hard or crunchy foods are avoided for 2 weeks.', false),
  ('eent', 7, 'A parent calls 7 days after a 6-year-old''s tonsillectomy and says the child has started spitting out bright red blood. Which instruction by the nurse is the PRIORITY?', '[{"id": "a", "text": "Return to the emergency room immediately."}, {"id": "b", "text": "Offer ice chips and call back in 1 hour."}, {"id": "c", "text": "Give acetaminophen and apply the ice collar."}, {"id": "d", "text": "Have the child rinse with cool water and rest."}]'::jsonb, '["a"]', 'Spitting bright red blood after tonsillectomy is hemorrhage, which can be life-threatening, so the child must return to the ER immediately. Ice chips, analgesics and rest are comfort measures that delay emergency care.', false),
  ('eent', 8, 'The nurse plans home-care teaching for the parent of a 6-year-old after tonsillectomy. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Serve hot soup to soothe the throat"}, {"id": "b", "text": "Offer cool fluids such as popsicles and ice chips"}, {"id": "c", "text": "Use red sports drinks to replace fluids"}, {"id": "d", "text": "Avoid straws for 2 weeks"}, {"id": "e", "text": "Avoid strenuous activity for 2 weeks"}]'::jsonb, '["b", "d", "e"]', 'Cool fluids (popsicles, ice chips, cool water) are encouraged, straws are avoided because suction dislodges the clot, and strenuous activity is avoided for 2 weeks. Hot foods are avoided, and red or dark liquids look like blood if vomited.', true),
  ('eent', 9, 'Four days after tonsillectomy, a 9-year-old feels well and asks to rejoin the soccer team''s full practice tomorrow. Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes, as long as you drink through a straw during breaks."}, {"id": "b", "text": "Yes, since pain is usually gone by the fourth day."}, {"id": "c", "text": "Wait until you can eat crunchy foods without pain."}, {"id": "d", "text": "Avoid strenuous activity like that for 2 weeks."}]'::jsonb, '["d"]', 'Strenuous activity is avoided for 2 weeks after tonsillectomy. Pain actually peaks on day 5–7, and straws are avoided because suction dislodges the clot.', false),
  ('eent', 10, 'The nurse prepares to instill antibiotic ear drops for a 2-year-old. Which technique should the nurse use?', '[{"id": "a", "text": "Pull the pinna up and back"}, {"id": "b", "text": "Pull the pinna down and back"}, {"id": "c", "text": "Pull the pinna straight up"}, {"id": "d", "text": "Pull the earlobe down and forward"}]'::jsonb, '["b"]', 'For otic drops in children younger than 3 years, the pinna is pulled down and back. Pulling up and back is the technique for children 3 years and older.', false),
  ('eent', 11, 'An 8-year-old who swims daily has ear pain that worsens when the nurse gently pulls on the outer ear, along with itching and discharge. Topical antibiotic ear drops are prescribed. Which technique should the nurse use to instill the drops?', '[{"id": "a", "text": "Pull the pinna up and back"}, {"id": "b", "text": "Pull the pinna down and back"}, {"id": "c", "text": "Pull the earlobe down and forward"}, {"id": "d", "text": "Press the tragus firmly inward"}]'::jsonb, '["a"]', 'For children 3 years and older, the pinna is pulled up and back to instill otic drops. Pulling down and back is used in children younger than 3 years.', false),
  ('eent', 12, 'The nurse is reviewing ear-drop technique with parents of children of different ages. In which children should the parent pull the pinna down and back? Select all that apply.', '[{"id": "a", "text": "A child aged 3 years"}, {"id": "b", "text": "A child aged 6 months"}, {"id": "c", "text": "A child aged 5 years"}, {"id": "d", "text": "A child aged 18 months"}, {"id": "e", "text": "A child aged 2½ years"}]'::jsonb, '["b", "d", "e"]', 'In children younger than 3 years (6 months, 18 months, 2½ years), the pinna is pulled down and back. Children 3 years and older, including the 3-year-old and 5-year-old, need the pinna pulled up and back.', true),
  ('eent', 13, 'A nurse observes a student instilling ear drops for an 18-month-old with otitis media. Which action by the student requires correction?', '[{"id": "a", "text": "Positions the toddler with the affected ear up"}, {"id": "b", "text": "Plans acetaminophen for the toddler''s ear pain"}, {"id": "c", "text": "Explains the steps to the parent before starting"}, {"id": "d", "text": "Pulls the pinna up and back before instilling"}]'::jsonb, '["d"]', 'In children younger than 3 years, the pinna is pulled down and back; up and back is for children 3 years and older. Pain management with acetaminophen is appropriate.', false),
  ('eent', 14, 'A 10-month-old in daycare has had a temperature of 38.6°C (101.5°F) for a day, is irritable, sleeps poorly, feeds poorly, and keeps pulling at the right ear. Which condition does the nurse MOST likely suspect?', '[{"id": "a", "text": "Otitis externa"}, {"id": "b", "text": "Epiglottitis"}, {"id": "c", "text": "Otitis media"}, {"id": "d", "text": "Tonsillitis"}]'::jsonb, '["c"]', 'Ear tugging with fever, irritability, poor sleep and poor feeding in a non-verbal child indicates otitis media, which is most common from 6 months to 2 years. Otitis externa is typical of swimming and causes pain when the pinna is pulled, and epiglottitis presents with drooling and tripod position.', false),
  ('eent', 15, 'A 4-year-old is diagnosed with acute otitis media and is crying from ear pain. Which intervention should the nurse anticipate FIRST?', '[{"id": "a", "text": "Scheduling tympanostomy tube placement"}, {"id": "b", "text": "Instilling topical antibiotic ear drops"}, {"id": "c", "text": "Arranging a formal hearing evaluation"}, {"id": "d", "text": "Giving acetaminophen or ibuprofen"}]'::jsonb, '["d"]', 'Treatment of otitis media starts with pain management (acetaminophen or ibuprofen). Tympanostomy tubes are for recurrent otitis media, and topical antibiotic ear drops are the treatment for otitis externa.', false),
  ('eent', 16, 'A 5-year-old has mild ear pain in one ear and a low-grade fever, and the provider diagnoses mild otitis media. The parent asks why no antibiotic was prescribed. Which response by the nurse is BEST?', '[{"id": "a", "text": "Antibiotics are given after tubes are placed."}, {"id": "b", "text": "Middle ear infections are treated with ear drops."}, {"id": "c", "text": "Mild cases in older children may be watched 48–72h."}, {"id": "d", "text": "Antibiotics start once fluid drains from the ear."}]'::jsonb, '["c"]', 'Watchful waiting for 48–72 hours is used in mild cases in older children, with pain management first. Antibiotics are indicated for severe symptoms, bilateral infection, or failure to improve, and tympanostomy tubes are for recurrent otitis media.', false),
  ('eent', 17, 'The nurse reviews the history of a 14-month-old with repeated ear infections. Which factors in the history increase the risk for otitis media? Select all that apply.', '[{"id": "a", "text": "Breastfeeding since birth"}, {"id": "b", "text": "Exposure to secondhand smoke"}, {"id": "c", "text": "Bottle feeding in supine position"}, {"id": "d", "text": "Daycare attendance"}, {"id": "e", "text": "Repaired cleft palate"}]'::jsonb, '["b", "c", "d", "e"]', 'Secondhand smoke, bottle feeding in the supine position, daycare attendance and cleft palate are risk factors for otitis media. Formula feeding increases risk compared with breastfeeding, so breastfeeding is not a risk factor.', true),
  ('eent', 18, 'A 5-year-old with mild otitis media has been managed with watchful waiting and pain medication for 72 hours. The parent reports the ear pain and fever have not improved. Which action should the nurse anticipate NEXT?', '[{"id": "a", "text": "Continue watchful waiting for another week"}, {"id": "b", "text": "Begin antibiotics, since the child fails to improve"}, {"id": "c", "text": "Stop analgesics to see if the fever returns"}, {"id": "d", "text": "Place tympanostomy tubes after this first ear infection"}]'::jsonb, '["b"]', 'Antibiotics are indicated when the child fails to improve after watchful waiting of 48–72 hours. Tympanostomy tubes are for recurrent otitis media, not a first episode.', false),
  ('eent', 19, 'The nurse reviews four children with otitis media seen in clinic today. Which children does the nurse anticipate will need antibiotics rather than watchful waiting? Select all that apply.', '[{"id": "a", "text": "A 6-year-old with bilateral infection"}, {"id": "b", "text": "A 5-year-old with mild pain in one ear"}, {"id": "c", "text": "A 4-year-old with severe symptoms"}, {"id": "d", "text": "A 7-year-old who fails to improve after watchful waiting"}, {"id": "e", "text": "A 6-year-old with mild symptoms on day 1"}]'::jsonb, '["a", "c", "d"]', 'Antibiotics are indicated for bilateral infection, severe symptoms, or failure to improve. Mild cases in older children, such as mild unilateral pain or mild symptoms on day 1, are managed with watchful waiting for 48–72 hours.', true),
  ('eent', 20, 'During a home visit, the nurse observes the parent of a 9-month-old with repeated ear infections. Which observation requires the nurse to provide further teaching?', '[{"id": "a", "text": "The infant is bottle feeding in supine position in the crib."}, {"id": "b", "text": "The parent smokes only outdoors, well away from the infant."}, {"id": "c", "text": "The infant is held upright in a parent''s arms during feedings."}, {"id": "d", "text": "The parent gives ibuprofen for ear pain as prescribed."}]'::jsonb, '["a"]', 'Bottle feeding in the supine position is a risk factor for otitis media. Keeping smoke away from the infant, upright feeding and pain management are appropriate.', false),
  ('eent', 21, 'A 3-year-old with six ear infections this year is scheduled for tympanostomy tubes. Which statement by the parent indicates understanding of the procedure''s purpose?', '[{"id": "a", "text": "\"The tubes will drain fluid and ventilate the middle ear.\""}, {"id": "b", "text": "\"The tubes deliver antibiotics directly into the ear.\""}, {"id": "c", "text": "\"The tubes treat infection of the outer ear canal.\""}, {"id": "d", "text": "\"The tubes are placed so the tonsils can be removed safely.\""}]'::jsonb, '["a"]', 'Tympanostomy (PE) tubes are placed for recurrent otitis media to drain fluid and ventilate the middle ear. Infection of the external ear canal is otitis externa, which is treated with topical antibiotic drops.', false),
  ('eent', 22, 'A 9-year-old on the swim team has ear pain that worsens when the pinna is pulled, plus itching and discharge. Topical antibiotic ear drops are prescribed. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Keep the ear dry"}, {"id": "b", "text": "Pull the pinna down and back for the drops"}, {"id": "c", "text": "Swim with the ear dried well afterward"}, {"id": "d", "text": "No swimming until the infection has resolved"}, {"id": "e", "text": "Wait 48–72 hours before starting the drops"}]'::jsonb, '["a", "d"]', 'Otitis externa is treated with topical antibiotic ear drops, keeping the ear dry, and no swimming until resolved. For a child 3 years or older the pinna is pulled up and back, and watchful waiting for 48–72 hours applies to mild otitis media, not otitis externa.', true),
  ('eent', 23, 'A 10-year-old returns from summer camp with ear pain. The nurse finds that pain increases sharply when the outer ear is gently pulled, and the child reports itching. Which condition is MOST likely?', '[{"id": "a", "text": "Otitis media"}, {"id": "b", "text": "Tonsillitis"}, {"id": "c", "text": "Conductive hearing loss from tubes"}, {"id": "d", "text": "Otitis externa"}]'::jsonb, '["d"]', 'Ear pain worsened by pulling on the outer ear (pinna), with itching and discharge, indicates otitis externa (swimmer''s ear), an infection of the external ear canal. Otitis media involves fluid and infection behind the tympanic membrane and presents with fever and ear tugging.', false),
  ('eent', 24, 'The parent of a 14-month-old asks whether her child''s ear infection could be the cause of the child''s crankiness. Which findings would support otitis media in this non-verbal child? Select all that apply.', '[{"id": "a", "text": "Barking, seal-like cough"}, {"id": "b", "text": "Pulling and tugging at the ear"}, {"id": "c", "text": "Drooling with a tripod position"}, {"id": "d", "text": "Fever with poor sleep and irritability"}, {"id": "e", "text": "Pain only when the pinna is pulled"}]'::jsonb, '["b", "d"]', 'Otitis media in non-verbal children presents as pulling or tugging at the ear, fever, irritability and poor sleep. A barking cough is croup, drooling with tripod position is epiglottitis, and pain on pulling the pinna is otitis externa.', true),
  ('eent', 25, 'At a well-child visit, the nurse screens four infants for hearing concerns. Which infant requires follow-up FIRST?', '[{"id": "a", "text": "A 6-month-old who is not yet babbling"}, {"id": "b", "text": "A 10-month-old who does not yet respond to name"}, {"id": "c", "text": "A 9-month-old who is not babbling"}, {"id": "d", "text": "A 13-month-old who does not yet say words"}]'::jsonb, '["c"]', 'No babbling by 7 months is a hearing loss red flag, so the 9-month-old needs follow-up. The 6-month-old has not reached 7 months, no response to name is a red flag by 12 months, and no words is a red flag by 15 months.', false),
  ('eent', 26, 'The parent of an 8-month-old with frequent ear infections says, "She doesn''t babble yet, but she''s just a quiet baby." Which response by the nurse is BEST?', '[{"id": "a", "text": "Quiet babies often start babbling at 12 months."}, {"id": "b", "text": "No babbling by now is a red flag for hearing loss."}, {"id": "c", "text": "Babbling only matters if she has no words by 2 years."}, {"id": "d", "text": "Ear infections do not affect hearing in infants."}]'::jsonb, '["b"]', 'No babbling by 7 months is an infant red flag for hearing loss, and otitis media can decrease hearing. Hearing impairment is the leading cause of speech and language delays, so evaluation should not wait.', false),
  ('eent', 27, 'The nurse reviews developmental screening results for five infants. Which findings are hearing loss red flags that require referral? Select all that apply.', '[{"id": "a", "text": "A 5-month-old who is not yet babbling"}, {"id": "b", "text": "A 2-week-old with no startle to a loud sound"}, {"id": "c", "text": "A 9-month-old who is not babbling"}, {"id": "d", "text": "A 13-month-old with no response to name"}, {"id": "e", "text": "A 16-month-old with no words"}]'::jsonb, '["b", "c", "d", "e"]', 'Infant hearing red flags are no startle (Moro) to sound, no babbling by 7 months, no response to name by 12 months, and no words by 15 months. A 5-month-old has not yet reached the 7-month babbling cut-off.', true),
  ('eent', 28, 'A 3-year-old with recurrent otitis media has decreased hearing on screening. The parent asks what kind of hearing loss fluid in the middle ear causes. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Sensorineural loss, which involves the inner ear or nerve"}, {"id": "b", "text": "Sensorineural loss, which involves the outer ear canal"}, {"id": "c", "text": "Conductive loss, which involves the inner ear or nerve"}, {"id": "d", "text": "Conductive loss, which involves the outer or middle ear"}]'::jsonb, '["d"]', 'Otitis media is fluid and infection behind the tympanic membrane, in the middle ear; hearing loss from the outer or middle ear is conductive. Sensorineural loss involves the inner ear or nerve.', false),
  ('eent', 29, 'A 2-year-old with recurrent otitis media uses only a few words. The parent asks how ear problems could affect speech. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "Hearing impairment is a leading cause of speech/language delays."}, {"id": "b", "text": "Ear infections cause speech delay only when the eardrum ruptures."}, {"id": "c", "text": "Speech delay is caused by the antibiotics used for ear infections."}, {"id": "d", "text": "Speech delay is unrelated to hearing and will resolve on its own."}]'::jsonb, '["a"]', 'Otitis media can cause decreased hearing, and hearing impairment is the leading cause of speech and language delays. Antibiotics are a treatment, not a cause of speech delay.', false),
  ('eent', 30, 'A 7-year-old has sore throat, fever, difficulty swallowing, white patches on the tonsils, and tender cervical lymph nodes. A rapid strep test is positive. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll encourage fluids and give pain medicine as needed.\""}, {"id": "b", "text": "\"She''ll take the penicillin for the full 10 days.\""}, {"id": "c", "text": "\"I''ll stop the penicillin once her fever is gone.\""}, {"id": "d", "text": "\"She can have amoxicillin if that is what is prescribed.\""}]'::jsonb, '["c"]', 'Strep-positive tonsillitis is treated with penicillin (or amoxicillin) for a full 10-day course, so stopping when the fever resolves needs correction. Fluids and analgesics are part of treatment.', false),
  ('eent', 31, 'The nurse reviews five children who have sore throats. Which children should the nurse anticipate will be prescribed penicillin or amoxicillin? Select all that apply.', '[{"id": "a", "text": "A 4-year-old with a barking cough and low-grade fever"}, {"id": "b", "text": "A 6-year-old with a positive rapid strep test"}, {"id": "c", "text": "A 5-year-old with drooling, tripod position and high fever"}, {"id": "d", "text": "A 7-year-old with viral tonsillitis and a negative strep test"}, {"id": "e", "text": "A 9-year-old with a positive throat culture for Group A Strep"}]'::jsonb, '["b", "e"]', 'Penicillin (or amoxicillin) is given when the rapid strep test or throat culture is positive for Group A Strep. A barking cough is croup (cool mist, racemic epinephrine, dexamethasone), drooling with tripod position is epiglottitis (IV antibiotics and airway management), and viral tonsillitis is treated with fluids and analgesics.', true),
  ('eent', 32, 'A 6-year-old is seen for a sore throat. Which assessment findings would the nurse expect if the child has tonsillitis? Select all that apply.', '[{"id": "a", "text": "Tonsillar exudates (white patches)"}, {"id": "b", "text": "Tender cervical lymph nodes"}, {"id": "c", "text": "Difficulty swallowing"}, {"id": "d", "text": "Barking, seal-like cough"}, {"id": "e", "text": "Muffled voice"}]'::jsonb, '["a", "b", "c", "e"]', 'Tonsillitis causes sore throat, fever, difficulty swallowing, muffled voice, tonsillar exudates (white patches) and tender cervical lymph nodes. A barking, seal-like cough is the classic sign of croup.', true),
  ('eent', 33, 'The nurse reviews referrals for possible tonsillectomy. Which findings support the need for tonsillectomy? Select all that apply.', '[{"id": "a", "text": "Sleep apnea"}, {"id": "b", "text": "A single episode of viral tonsillitis"}, {"id": "c", "text": "Chronic airway obstruction"}, {"id": "d", "text": "Recurrent strep infections"}, {"id": "e", "text": "A barking cough with low-grade fever"}]'::jsonb, '["a", "c", "d"]', 'Tonsillectomy is indicated for recurrent strep, chronic airway obstruction and sleep apnea. A single viral episode is treated with fluids and analgesics, and a barking cough with low-grade fever is croup.', true),
  ('eent', 34, 'A 4-year-old arrives with a sudden onset of temperature 39.8°C (103.6°F), drooling, a muffled voice, and sitting in a tripod position. Which action by a student nurse requires IMMEDIATE intervention?', '[{"id": "a", "text": "Planning a throat exam to check for exudates"}, {"id": "b", "text": "Allowing the child to stay upright on the parent''s lap"}, {"id": "c", "text": "Gathering supplies for IV antibiotics"}, {"id": "d", "text": "Ensuring intubation equipment is at the bedside"}]'::jsonb, '["a"]', 'Sudden high fever, drooling, muffled voice and tripod position indicate epiglottitis; the throat must NEVER be examined because it may cause complete obstruction. Gathering IV antibiotics and having intubation ready are appropriate.', false),
  ('eent', 35, 'A 2-year-old developed a barking, seal-like cough over 2 days after a cold, with a temperature of 37.9°C (100.2°F) and no drooling. Which treatment does the nurse anticipate as MOST likely?', '[{"id": "a", "text": "IV antibiotics with intubation equipment kept ready"}, {"id": "b", "text": "Penicillin for a full 10-day course"}, {"id": "c", "text": "Topical antibiotic drops and a dry ear"}, {"id": "d", "text": "Cool mist, racemic epinephrine, and dexamethasone"}]'::jsonb, '["d"]', 'Gradual onset, a barking seal-like cough and low-grade fever indicate croup, treated with cool mist, racemic epinephrine and dexamethasone. IV antibiotics with intubation ready are for epiglottitis, which has a sudden onset, high fever and drooling.', false),
  ('eent', 36, 'Two children arrive in the emergency department with noisy breathing. Which finding MOST strongly suggests epiglottitis rather than croup?', '[{"id": "a", "text": "Barking cough that developed gradually over 2 days"}, {"id": "b", "text": "Low-grade fever that began after a cold"}, {"id": "c", "text": "Drooling while sitting in a tripod position"}, {"id": "d", "text": "Symptoms that improve quickly with cool mist"}]'::jsonb, '["c"]', 'Drooling, tripod position and muffled voice are classic signs of epiglottitis, which has a sudden, rapid onset and high fever over 39°C. Croup has a gradual onset, barking cough and low-grade fever and is treated with cool mist.', false),
  ('eent', 37, 'A 3-year-old is admitted with sudden high fever, drooling, muffled voice and a tripod position. Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Examine the throat with a tongue blade"}, {"id": "b", "text": "Keep intubation equipment ready"}, {"id": "c", "text": "Prepare to give IV antibiotics"}, {"id": "d", "text": "Treat with cool mist alone"}, {"id": "e", "text": "Prepare for airway management"}]'::jsonb, '["b", "c", "e"]', 'Epiglottitis is a bacterial emergency managed with IV antibiotics, airway management and intubation readiness. The throat is never examined because it may cause complete obstruction, and cool mist is a croup treatment.', true),
  ('eent', 38, 'A 2-year-old is brought to urgent care at night with noisy breathing. Which findings are consistent with croup? Select all that apply.', '[{"id": "a", "text": "Temperature of 40°C (104°F)"}, {"id": "b", "text": "Drooling and a muffled voice"}, {"id": "c", "text": "Barking (seal-like) cough"}, {"id": "d", "text": "Sudden, rapid progression"}, {"id": "e", "text": "Gradual onset over 2 days"}]'::jsonb, '["c", "e"]', 'Croup is viral (parainfluenza) with a gradual onset, barking seal-like cough and low-grade fever. A high fever over 39°C, drooling with muffled voice, and sudden rapid progression are features of epiglottitis.', true),
  ('eent', 39, 'At a preschool vision screening, the nurse notes that a 4-year-old''s left eye intermittently drifts outward. The parent asks whether the child will simply outgrow it. Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes, most children outgrow eye misalignment by school age."}, {"id": "b", "text": "No, untreated it can lead to amblyopia and permanent vision loss."}, {"id": "c", "text": "Yes, treatment is needed only if both eyes drift outward."}, {"id": "d", "text": "No, but treatment should wait until after age 7."}]'::jsonb, '["b"]', 'Strabismus (eye misalignment) can cause amblyopia if untreated, and untreated strabismus leads to amblyopia and permanent vision loss. Amblyopia is best treated before age 6–7, so treatment should not be delayed.', false),
  ('eent', 40, 'A 5-year-old has reduced vision in the right eye with a strong left eye and is prescribed patching. Which statement by the parent indicates understanding of the treatment?', '[{"id": "a", "text": "\"I will patch the right eye so it can rest and heal.\""}, {"id": "b", "text": "\"I will patch the left eye to force use of the right eye.\""}, {"id": "c", "text": "\"I will patch whichever eye looks more tired that day.\""}, {"id": "d", "text": "\"Patching can wait until she starts second grade.\""}]'::jsonb, '["b"]', 'Amblyopia is treated by patching the strong eye to force use of the weak eye, so the left (strong) eye is patched. Amblyopia is best treated before age 6–7, so treatment should not be delayed.', false),
  ('eent', 41, 'The nurse is following two children with amblyopia: a 4-year-old and a 10-year-old. Which statement BEST explains why early treatment matters?', '[{"id": "a", "text": "Amblyopia is best treated before age 6–7."}, {"id": "b", "text": "Amblyopia treatment works best after age 10."}, {"id": "c", "text": "Amblyopia always resolves on its own by age 6."}, {"id": "d", "text": "Amblyopia affects both eyes equally at any age."}]'::jsonb, '["a"]', 'Amblyopia is best treated before age 6–7, the critical visual development period, so the 4-year-old is in the best window. Amblyopia is reduced vision in one eye and does not resolve on its own if untreated.', false),
  ('eent', 42, 'A 5-year-old with amblyopia keeps pulling off the eye patch at preschool. Which nursing action is the PRIORITY?', '[{"id": "a", "text": "Recommend stopping patching until the child is older."}, {"id": "b", "text": "Educate the family on the importance of compliance with patching."}, {"id": "c", "text": "Suggest patching the weak eye, which the child may accept better."}, {"id": "d", "text": "Schedule eye muscle surgery to replace the patching."}]'::jsonb, '["b"]', 'Child compliance with patching is a nursing education priority, because amblyopia is best treated before age 6–7. The strong eye, not the weak eye, is patched.', false),
  ('eent', 43, 'The nurse teaches the parents of a 4-year-old with strabismus and early amblyopia. Which statements by the parents indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"Glasses may be part of treating the eye misalignment.\""}, {"id": "b", "text": "\"We will patch the weak eye to protect it.\""}, {"id": "c", "text": "\"Without treatment, she could have permanent vision loss.\""}, {"id": "d", "text": "\"Treatment can safely wait until she is 9 years old.\""}, {"id": "e", "text": "\"Eye muscle surgery is one possible treatment.\""}]'::jsonb, '["a", "c", "e"]', 'Strabismus is treated with corrective glasses, eye patching or eye muscle surgery, and untreated strabismus leads to amblyopia and permanent vision loss. The strong eye is patched, and amblyopia is best treated before age 6–7.', true),
  ('eent', 44, 'A 6-year-old has thick yellow pus with eyelids stuck together this morning and was started on antibiotic eye drops 8 hours ago. The parent asks when the child may return to school. Which response by the nurse is BEST?', '[{"id": "a", "text": "Return to school after 24h on antibiotics."}, {"id": "b", "text": "This afternoon, because the drops have been started."}, {"id": "c", "text": "In 1–2 weeks, once the infection resolves on its own."}, {"id": "d", "text": "Right away, because this type is not contagious."}]'::jsonb, '["a"]', 'Thick yellow pus with eyelids stuck together is bacterial conjunctivitis; the child returns to school after 24 hours on antibiotics. Resolution in 1–2 weeks describes viral conjunctivitis.', false),
  ('eent', 45, 'The nurse assesses five children with red eyes. Which findings suggest bacterial conjunctivitis? Select all that apply.', '[{"id": "a", "text": "Watery, clear discharge after a URI"}, {"id": "b", "text": "Thick yellow/green pus"}, {"id": "c", "text": "Intense itching in both eyes each spring"}, {"id": "d", "text": "Eyelids stuck together"}, {"id": "e", "text": "Lymphadenopathy with watery eyes"}]'::jsonb, '["b", "d"]', 'Bacterial conjunctivitis produces thick yellow/green pus with eyelids stuck together and may be unilateral initially. Watery, clear discharge after a URI with lymphadenopathy is viral, and intense bilateral itching that is seasonal is allergic.', true),
  ('eent', 46, 'A 7-year-old has watery, clear discharge in both eyes that began after a URI, with lymphadenopathy. The parent asks for antibiotic eye drops. Which response by the nurse is BEST?', '[{"id": "a", "text": "Antibiotic drops are needed before returning to school."}, {"id": "b", "text": "Antihistamine drops will stop the infection quickly."}, {"id": "c", "text": "Supportive care with cool compresses; it resolves in 1–2 weeks."}, {"id": "d", "text": "Keep the eyes covered with a patch until the discharge stops."}]'::jsonb, '["c"]', 'Watery, clear, bilateral discharge after a URI with lymphadenopathy indicates viral conjunctivitis, managed with supportive care, cool compresses and handwashing; it resolves in 1–2 weeks. Antibiotic drops are for bacterial and antihistamine drops for allergic conjunctivitis.', false),
  ('eent', 47, 'A 9-year-old has redness and intense itching in both eyes with watery discharge every spring. Which management plan should the nurse anticipate as MOST appropriate?', '[{"id": "a", "text": "Antibiotic eye drops and 24 hours home from school"}, {"id": "b", "text": "Antihistamine drops, avoiding allergens, and cool compresses"}, {"id": "c", "text": "Patching the stronger eye for several hours daily"}, {"id": "d", "text": "Supportive care only, expecting resolution in 1–2 weeks"}]'::jsonb, '["b"]', 'Bilateral, intense itching and redness that is seasonal indicates allergic conjunctivitis, managed with antihistamine drops, avoiding allergens and cool compresses. Antibiotics and school exclusion apply to bacterial conjunctivitis.', false),
  ('eent', 48, 'Three siblings share a bedroom, and one has conjunctivitis with thick yellow pus. The parent asks how to keep the others from getting it. Which instruction is the MOST important?', '[{"id": "a", "text": "Give all three children antibiotic eye drops."}, {"id": "b", "text": "Use cool compresses on the healthy siblings'' eyes."}, {"id": "c", "text": "Keep the healthy siblings home from school for 24 hours."}, {"id": "d", "text": "Frequent handwashing and no sharing of towels or pillowcases."}]'::jsonb, '["d"]', 'The most important teaching is frequent handwashing and not sharing towels, pillowcases or eye makeup. Antibiotic drops are for the child with bacterial conjunctivitis, not for healthy siblings.', false),
  ('eent', 49, 'A 4-year-old with recurrent otitis media has fluid draining from the left ear, fever, and decreased hearing. The parent asks whether the drainage matters. Which response by the nurse is BEST?', '[{"id": "a", "text": "Drainage means the infection is cured and no care is needed."}, {"id": "b", "text": "Drainage means swimmer''s ear, so the ear must be pulled down."}, {"id": "c", "text": "Drainage is a sign of a middle ear infection to report."}, {"id": "d", "text": "Drainage is expected after tonsillectomy and needs no care."}]'::jsonb, '["c"]', 'Fluid draining from the ear and decreased hearing are signs of otitis media, which is fluid and infection behind the tympanic membrane, and should be reported for treatment. A child aged 3 or older would have the pinna pulled up and back for drops.', false),
  ('eent', 50, 'A parent asks why a 16-month-old in daycare has had more ear infections than a 5-year-old sibling. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "Otitis media is most common from 6 months to 2 years."}, {"id": "b", "text": "Otitis media is most common after children start school."}, {"id": "c", "text": "Otitis media occurs mainly in children who swim often."}, {"id": "d", "text": "Otitis media is most common in breastfed infants."}]'::jsonb, '["a"]', 'Otitis media is most common from 6 months to 2 years, and daycare attendance is a risk factor. Swimming is linked to otitis externa, and formula feeding, not breastfeeding, increases risk.', false),
  ('cog_neuro', 1, 'A 3-year-old in the playroom suddenly stiffens, falls to the floor, and begins rhythmic jerking of all extremities. After calling for help, which action should the nurse take FIRST?', '[{"id": "a", "text": "Place a padded tongue blade between the teeth"}, {"id": "b", "text": "Turn the child side-lying to protect the airway"}, {"id": "c", "text": "Document the body parts involved in the seizure"}, {"id": "d", "text": "Leave to obtain lorazepam from the medication room"}]'::jsonb, '["b"]', 'Positioning side-lying (recovery position) protects the airway while the nurse stays with the child. Nothing should be put in the mouth, documentation comes after the seizure, and the child must never be left alone.', false),
  ('cog_neuro', 2, 'A 7-year-old with known epilepsy has had a generalized tonic-clonic seizure for 6 minutes. The child has no fever. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Keep observing, since seizures usually stop within 15 minutes"}, {"id": "b", "text": "Give an antipyretic to prevent another seizure"}, {"id": "c", "text": "Teach the parent about maintenance levetiracetam"}, {"id": "d", "text": "Prepare to give lorazepam to stop the active seizure"}]'::jsonb, '["d"]', 'A seizure lasting >5 min is status epilepticus, an emergency, and diazepam or lorazepam is given to stop an active seizure. The <15 min duration describes febrile seizures, and this afebrile child is already past the 5-minute emergency threshold.', false),
  ('cog_neuro', 3, 'A nurse observes an unlicensed assistive personnel (UAP) caring for a 6-year-old during a tonic-clonic seizure. Which actions by the UAP require correction? Select all that apply.', '[{"id": "a", "text": "Times the seizure from its start"}, {"id": "b", "text": "Puts something in the mouth to protect the tongue"}, {"id": "c", "text": "Leaves the child alone to get help"}, {"id": "d", "text": "Restrains the limbs to stop the jerking"}, {"id": "e", "text": "Clears the area of hard objects"}]'::jsonb, '["b", "c", "d"]', 'Nothing should be put in the mouth, the limbs must not be restrained, and the nurse must stay with the child and never leave the child alone, so these actions require correction. Clearing the area of hard objects and timing the seizure are correct seizure care.', true),
  ('cog_neuro', 4, 'A teacher reports that an 8-year-old often "daydreams": several times a day the child stops talking, stares blankly for about 10 seconds with subtle eye blinking, then resumes the activity right away without drowsiness. Which condition does the nurse MOST likely suspect?', '[{"id": "a", "text": "Absence seizures"}, {"id": "b", "text": "ADHD, predominantly inattentive"}, {"id": "c", "text": "Tonic-clonic seizures"}, {"id": "d", "text": "Febrile seizures"}]'::jsonb, '["a"]', 'Absence seizures are a brief blank stare (5–30 sec) with subtle eye blinking and no postictal phase, seen in school-age children and often mistaken for daydreaming. Tonic-clonic seizures cause stiffening, jerking, and postictal drowsiness.', false),
  ('cog_neuro', 5, 'An 18-month-old had a 3-minute tonic-clonic seizure as a high fever rose rapidly. The child is now alert and playful. The parent asks whether the child will need a daily seizure medicine. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Daily phenytoin will be started to prevent another one.\""}, {"id": "b", "text": "\"Lorazepam will be given each day until age 5.\""}, {"id": "c", "text": "\"Treat fever with antipyretics; no routine prophylaxis.\""}, {"id": "d", "text": "\"Valproate is needed because the seizure lasted over 1 minute.\""}]'::jsonb, '["c"]', 'Febrile seizures (6 months–5 years, rapid rise in fever) are generally benign and are managed by treating the fever with antipyretics, with no routine prophylaxis. Phenytoin and valproate are maintenance medications, not routine for febrile seizures.', false),
  ('cog_neuro', 6, 'A 3-month-old returns to the unit after placement of a ventriculoperitoneal (VP) shunt. Which actions should the nurse include in the plan of care? Select all that apply.', '[{"id": "a", "text": "Measure and document head circumference"}, {"id": "b", "text": "Watch for redness along the shunt tract"}, {"id": "c", "text": "Raise the head of the bed upright quickly"}, {"id": "d", "text": "Plan droplet isolation for 24 hours"}, {"id": "e", "text": "Position flat or slightly elevated per order"}]'::jsonb, '["a", "b", "e"]', 'After VP shunt placement, the infant is positioned flat or slightly elevated per order, head circumference is measured and documented, and the nurse watches for shunt infection such as redness along the shunt tract. Rapid position changes cause rapid pressure changes and are avoided, and droplet isolation is for bacterial meningitis.', true),
  ('cog_neuro', 7, 'A nurse in the emergency department reviews four children who each had a single tonic-clonic seizure with fever. Which child''s presentation is MOST consistent with a febrile seizure?', '[{"id": "a", "text": "A 3-month-old with a rapid rise in fever; seizure lasted 2 min"}, {"id": "b", "text": "A 2-year-old with a rapid rise in fever; seizure lasted 2 min"}, {"id": "c", "text": "A 7-year-old with a rapid rise in fever; seizure lasted 2 min"}, {"id": "d", "text": "A 4-year-old with a rapid rise in fever; seizure lasted 20 min"}]'::jsonb, '["b"]', 'Febrile seizures occur from 6 months to 5 years, are associated with a rapid rise in fever, and last <15 min. The 3-month-old and 7-year-old are outside the age range, and a 20-minute seizure exceeds the expected duration.', false),
  ('cog_neuro', 8, 'After a 9-year-old''s seizure ends, the nurse reviews four draft notes written by students. Which documentation entry is MOST complete?', '[{"id": "a", "text": "\"Seizure observed. Child now resting. Will continue to monitor.\""}, {"id": "b", "text": "\"Generalized jerking. Lorazepam given. Parent at the bedside.\""}, {"id": "c", "text": "\"Tonic-clonic, 3 min, all limbs, then drowsy for 20 min.\""}, {"id": "d", "text": "\"Seizure occurred. Airway clear. Area cleared of hard objects.\""}]'::jsonb, '["c"]', 'Documentation should include type, duration, body parts involved, and behavior after the seizure, which only the tonic-clonic entry provides. The other notes omit the type, duration, or postictal behavior.', false),
  ('cog_neuro', 9, 'A 3-year-old is recovering from meningococcal bacterial meningitis. For which complications should the nurse monitor? Select all that apply.', '[{"id": "a", "text": "Atlantoaxial instability"}, {"id": "b", "text": "SIADH"}, {"id": "c", "text": "Hearing loss"}, {"id": "d", "text": "Seizures"}, {"id": "e", "text": "Waterhouse-Friderichsen syndrome"}]'::jsonb, '["b", "c", "d", "e"]', 'Complications of meningitis include hearing loss, seizures, SIADH, and Waterhouse-Friderichsen syndrome with meningococcal infection. Atlantoaxial instability is associated with Down syndrome, not meningitis.', true),
  ('cog_neuro', 10, 'A 5-year-old''s tonic-clonic seizure stopped after 2 minutes. The child is now drowsy and lying on one side, and the area has been cleared. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Give diazepam to stop the seizure"}, {"id": "b", "text": "Restrain the limbs in case jerking returns"}, {"id": "c", "text": "Write the note before checking the child"}, {"id": "d", "text": "Assess LOC and breathing"}]'::jsonb, '["d"]', 'After a seizure the nurse assesses LOC and breathing during the postictal phase. Diazepam is for an active seizure, limbs are never restrained, and documentation follows assessment.', false),
  ('cog_neuro', 11, 'A 4-month-old is brought to the clinic with a bulging anterior fontanel, a high-pitched cry, projectile vomiting, eyes that deviate downward, and a rapidly increasing head circumference. The infant is afebrile. The nurse recognizes these findings as MOST consistent with which problem?', '[{"id": "a", "text": "Increased ICP from excess CSF"}, {"id": "b", "text": "Meningeal irritation from infection"}, {"id": "c", "text": "Absence seizures with no postictal phase"}, {"id": "d", "text": "Atlantoaxial instability at C1–C2"}]'::jsonb, '["a"]', 'Excess CSF raises ICP; in infants this causes a bulging anterior fontanel, high-pitched cry, projectile vomiting, increasing head circumference, and sunset eyes. Infant meningitis also causes a bulging fontanel, but this infant is afebrile and has sunset eyes with a growing head.', false),
  ('cog_neuro', 12, 'A newborn has hypotonia, a flat facial profile, upslanting palpebral fissures, small ears, and a single palmar crease. For which associated conditions should the nurse plan ongoing monitoring? Select all that apply.', '[{"id": "a", "text": "Scissors gait from spasticity"}, {"id": "b", "text": "Leukemia"}, {"id": "c", "text": "Hypothyroidism"}, {"id": "d", "text": "Absence seizures"}, {"id": "e", "text": "Hearing loss"}]'::jsonb, '["b", "c", "e"]', 'These findings suggest Down syndrome, whose associated conditions include hypothyroidism, leukemia, and hearing loss. Scissors gait from spasticity describes spastic cerebral palsy, and absence seizures are not listed as an associated condition.', true),
  ('cog_neuro', 13, 'A 9-year-old with a ventriculoperitoneal (VP) shunt has had 2 days of morning headaches, vomiting, blurred vision, and new irritability. Temperature is normal and the skin over the shunt tract is not red. Which problem does the nurse suspect?', '[{"id": "a", "text": "Shunt failure"}, {"id": "b", "text": "Shunt infection"}, {"id": "c", "text": "Absence seizures"}, {"id": "d", "text": "Bacterial meningitis"}]'::jsonb, '["a"]', 'Shunt failure is the return of increased ICP signs such as headache, vomiting, and irritability; in an older child these include morning headache and blurred vision. Shunt infection presents with fever and redness along the shunt tract, which are absent.', false),
  ('cog_neuro', 14, 'A 2-year-old who had a VP shunt placed 10 days ago now has a fever, redness along the shunt tract, neck stiffness, and is harder to arouse. The nurse recognizes these findings as MOST consistent with which complication?', '[{"id": "a", "text": "Shunt failure from blockage"}, {"id": "b", "text": "Febrile seizure"}, {"id": "c", "text": "Shunt infection"}, {"id": "d", "text": "Atlantoaxial instability"}]'::jsonb, '["c"]', 'Fever, redness along the shunt tract, neck stiffness, and altered LOC are signs of shunt infection. Shunt failure is the return of increased ICP signs without redness along the tract.', false),
  ('cog_neuro', 15, 'The parent of a 2-year-old reports concerns about the child''s behavior. Which findings should the nurse recognize as signs of autism spectrum disorder? Select all that apply.', '[{"id": "a", "text": "Hand flapping, rocking"}, {"id": "b", "text": "Brief blank stares with eye blinking"}, {"id": "c", "text": "Extreme distress with change"}, {"id": "d", "text": "Forgetful and loses items"}, {"id": "e", "text": "Does not respond to name"}]'::jsonb, '["a", "c", "e"]', 'ASD signs include failure to respond to name by 12 months, repetitive movements (stimming—hand flapping, rocking), and rigid routines with extreme distress with change. Brief blank stares with eye blinking describe absence seizures, and being forgetful and losing items describes ADHD inattention.', true),
  ('cog_neuro', 16, 'Before discharge, the nurse teaches the parents of a 6-month-old who has a new VP shunt. Which statement by a parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll call if she has vomiting, irritability, or a bulging fontanel.\""}, {"id": "b", "text": "\"The shunt won''t need revision as she grows.\""}, {"id": "c", "text": "\"I''ll watch for fever or redness along the shunt tract.\""}, {"id": "d", "text": "\"Her head circumference will be measured and recorded.\""}]'::jsonb, '["b"]', 'A shunt may require revision as the child grows, so this statement needs correction. Watching for return of ICP signs and shunt infection and measuring head circumference in infants are correct.', false),
  ('cog_neuro', 17, 'A 10-year-old has fever, headache, and photophobia. With the child supine, the nurse flexes the hip to 90° and then tries to extend the knee; the child cries out in pain and resists. How should the nurse interpret this finding?', '[{"id": "a", "text": "Positive Brudzinski''s sign"}, {"id": "b", "text": "Negative Kernig''s sign"}, {"id": "c", "text": "Negative Brudzinski''s sign"}, {"id": "d", "text": "Positive Kernig''s sign"}]'::jsonb, '["d"]', 'Flexing the hip to 90° and extending the knee tests Kernig''s sign; pain and resistance is positive and indicates meningeal irritation. Brudzinski''s sign is tested by flexing the neck.', false),
  ('cog_neuro', 18, 'A 9-year-old with ADHD is started on methylphenidate. Which assessments should the nurse plan to monitor regularly? Select all that apply.', '[{"id": "a", "text": "Blood pressure and heart rate"}, {"id": "b", "text": "Thyroid function"}, {"id": "c", "text": "Head circumference"}, {"id": "d", "text": "Height and weight"}, {"id": "e", "text": "Sleep"}]'::jsonb, '["a", "d", "e"]', 'Stimulant teaching includes monitoring height and weight (growth suppression risk), sleep (insomnia), and blood pressure and heart rate. Head circumference is measured in infants with hydrocephalus, and thyroid monitoring is part of Down syndrome care.', true),
  ('cog_neuro', 19, 'A 12-year-old reports a severe headache, fever, vomiting, and pain from light and loud noises. Which assessment should the nurse perform NEXT to check for meningeal irritation?', '[{"id": "a", "text": "Flex the neck and watch for knee and hip flexion"}, {"id": "b", "text": "Measure and document the head circumference"}, {"id": "c", "text": "Time any episodes of brief blank staring at school"}, {"id": "d", "text": "Observe the walking pattern for a scissors gait"}]'::jsonb, '["a"]', 'Flexing the neck and observing for involuntary flexion of the knees and hips tests Brudzinski''s sign for meningeal irritation. Head circumference is measured in infants, not in a 12-year-old.', false),
  ('cog_neuro', 20, 'A 6-year-old with fever, nuchal rigidity, and altered LOC is critically ill, and bacterial meningitis is suspected. The lumbar puncture (LP) will be delayed for at least an hour. Which action is the PRIORITY?', '[{"id": "a", "text": "Hold antibiotics until the LP is completed"}, {"id": "b", "text": "Give dexamethasone and hold antibiotics for results"}, {"id": "c", "text": "Give IV antibiotics as soon as possible"}, {"id": "d", "text": "Place the child on contact precautions only"}]'::jsonb, '["c"]', 'IV antibiotics are given ASAP for bacterial meningitis and are not delayed for the LP when the child is critically ill. Dexamethasone reduces inflammation but does not replace prompt antibiotics.', false),
  ('cog_neuro', 21, 'A school nurse talks with a 14-year-old who is being treated for depression. Which findings require IMMEDIATE intervention? Select all that apply.', '[{"id": "a", "text": "Says the family would be better off without them as a burden"}, {"id": "b", "text": "Is irritable rather than sad"}, {"id": "c", "text": "Has poor concentration in class"}, {"id": "d", "text": "Has stomach aches on school mornings"}, {"id": "e", "text": "Has been researching methods online"}]'::jsonb, '["a", "e"]', 'Researching methods and talking about being a burden are suicide red flags requiring immediate action. Somatic complaints suggest anxiety, and irritability and poor concentration are depression signs that do not by themselves signal immediate danger.', true),
  ('cog_neuro', 22, 'A 4-year-old with bacterial meningitis started IV antibiotics 12 hours ago and is now more alert. The parent asks whether isolation can end. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Isolation can end now that antibiotics have started.\""}, {"id": "b", "text": "\"Droplet isolation lasts until 24h on antibiotics.\""}, {"id": "c", "text": "\"Airborne isolation continues for the entire stay.\""}, {"id": "d", "text": "\"Isolation isn''t needed once the child is more alert.\""}]'::jsonb, '["b"]', 'Bacterial meningitis requires droplet isolation until 24 hours on antibiotics, so at 12 hours isolation continues. Improvement in alertness does not change the 24-hour requirement.', false),
  ('cog_neuro', 23, 'A 7-year-old with bacterial meningitis is receiving IV antibiotics. The provider adds IV dexamethasone, and the parent asks why another medicine is needed if the antibiotics are working. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"IV steroids reduce inflammation.\""}, {"id": "b", "text": "\"It is given to stop an active seizure.\""}, {"id": "c", "text": "\"It treats the bacterial infection itself.\""}, {"id": "d", "text": "\"It drains excess CSF from the brain.\""}]'::jsonb, '["a"]', 'IV steroids (dexamethasone) are given to reduce inflammation in bacterial meningitis. Stopping an active seizure is the role of diazepam or lorazepam, and draining excess CSF is the role of a VP shunt.', false),
  ('cog_neuro', 24, 'A nurse teaches the parents of a 2-year-old who had a brief febrile seizure. Which statements by the parents indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"A seizure over 5 minutes is an emergency.\""}, {"id": "b", "text": "\"She''ll need daily phenytoin to prevent more.\""}, {"id": "c", "text": "\"I''ll treat her fever with an antipyretic.\""}, {"id": "d", "text": "\"I''ll place her side-lying during a seizure.\""}, {"id": "e", "text": "\"I''ll put a spoon in her mouth during a seizure.\""}]'::jsonb, '["a", "c", "d"]', 'Febrile seizures are managed by treating fever with antipyretics, a seizure >5 min is status epilepticus (an emergency), and the child is placed side-lying. Nothing is put in the mouth, and there is no routine prophylaxis such as daily phenytoin.', true),
  ('cog_neuro', 25, 'A 4-year-old has a permanent, non-progressive movement disorder from a brain injury at birth. The nurse observes involuntary, uncontrolled slow writhing and twisting movements of the arms. Which type of cerebral palsy do these findings MOST likely represent?', '[{"id": "a", "text": "Spastic"}, {"id": "b", "text": "Ataxic"}, {"id": "c", "text": "Tonic-clonic"}, {"id": "d", "text": "Dyskinetic"}]'::jsonb, '["d"]', 'Dyskinetic CP features involuntary, uncontrolled slow writhing (athetosis) or twisting movements. Spastic CP causes muscle stiffness and scissors gait, and ataxic CP causes poor balance and a wide-based gait.', false),
  ('cog_neuro', 26, 'A 6-year-old with spastic quadriplegic cerebral palsy coughs and chokes repeatedly while being fed lunch. Which nursing action is the PRIORITY?', '[{"id": "a", "text": "Use safe feeding techniques"}, {"id": "b", "text": "Give the baclofen dose before each meal"}, {"id": "c", "text": "Apply the AFOs before the next meal"}, {"id": "d", "text": "Schedule physical therapy after meals"}]'::jsonb, '["a"]', 'Children with CP have aspiration risk, so safe feeding techniques and monitoring swallowing are the priority. Baclofen treats spasticity and AFOs are assistive devices; neither addresses aspiration during feeding.', false),
  ('cog_neuro', 27, 'The parent of an 8-year-old with Down syndrome wants to enroll the child in a tumbling and diving program. Which statements by the parent indicate understanding of the nurse''s teaching? Select all that apply.', '[{"id": "a", "text": "\"He should avoid tumbling and diving.\""}, {"id": "b", "text": "\"He should be screened before starting sports.\""}, {"id": "c", "text": "\"The instability is in his lower back.\""}, {"id": "d", "text": "\"Screening is only needed if he has neck pain.\""}, {"id": "e", "text": "\"Gymnastics is fine once his heart is checked.\""}]'::jsonb, '["a", "b"]', 'Atlantoaxial instability (C1–C2) requires screening before sports/surgery and avoiding high-risk neck flexion activities such as tumbling, diving, and certain gymnastic moves. Screening is not limited to children with neck pain, the instability is at C1–C2 (not the lower back), and a heart check does not make gymnastics safe.', true),
  ('cog_neuro', 28, 'The parent of a 3-year-old recently diagnosed with cerebral palsy after a brain injury at birth asks, "Will the damage in her brain keep getting worse as she grows?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Yes, so she will slowly lose the skills she has.\""}, {"id": "b", "text": "\"It depends on whether she needs a VP shunt.\""}, {"id": "c", "text": "\"No, the brain injury in CP is non-progressive.\""}, {"id": "d", "text": "\"Yes, unless baclofen is started right away.\""}]'::jsonb, '["c"]', 'CP is a group of permanent movement/posture disorders caused by non-progressive brain injury before, during, or after birth. Baclofen treats spasticity but does not determine whether the injury progresses.', false),
  ('cog_neuro', 29, 'A 10-year-old with the most common type of cerebral palsy has a scissors gait and severe spasticity that interferes with daily care despite PT. Oral medication has not helped. The nurse anticipates teaching about which intervention?', '[{"id": "a", "text": "Ventriculoperitoneal shunt placement"}, {"id": "b", "text": "Intrathecal baclofen pump"}, {"id": "c", "text": "Methylphenidate given after meals"}, {"id": "d", "text": "IV dexamethasone to reduce inflammation"}]'::jsonb, '["b"]', 'An intrathecal baclofen pump is used for severe spasticity in CP. A VP shunt drains excess CSF in hydrocephalus and does not treat spasticity.', false),
  ('cog_neuro', 30, 'A 6-year-old with autism spectrum disorder is admitted for 3 days of IV antibiotics. Which interventions should the nurse include in the plan of care? Select all that apply.', '[{"id": "a", "text": "Use visual schedules and simple language"}, {"id": "b", "text": "Create a calm, low-stimulation environment"}, {"id": "c", "text": "Give advance warning before transitions"}, {"id": "d", "text": "Keep consistent, predictable routines"}, {"id": "e", "text": "Rotate different nurses each shift for flexibility"}]'::jsonb, '["a", "b", "c", "d"]', 'ASD care includes consistent, predictable routines, visual aids and simple direct language with visual schedules, advance warning before transitions, and calm, low-stimulation environments. Rotating caregivers disrupts routines, and children with ASD have extreme distress with change.', true),
  ('cog_neuro', 31, 'A 6-year-old with Down syndrome (trisomy 21) is scheduled for elective dental surgery under general anesthesia. Which preoperative nursing action is MOST important?', '[{"id": "a", "text": "Check the palms for a single palmar crease"}, {"id": "b", "text": "Teach the family about Alzheimer''s risk"}, {"id": "c", "text": "Assess for upslanting palpebral fissures"}, {"id": "d", "text": "Screen for atlantoaxial instability"}]'::jsonb, '["d"]', 'Atlantoaxial instability at C1–C2 occurs in ~15% of children with Down syndrome, so screening is needed before sports or surgery. A single palmar crease and upslanting palpebral fissures are expected features, not surgical safety issues.', false),
  ('cog_neuro', 32, 'The nurse reviews follow-up care with the parent of a 3-year-old with Down syndrome. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"She will keep having her hearing and vision checked.\""}, {"id": "b", "text": "\"Early intervention with PT, OT, and speech will help her.\""}, {"id": "c", "text": "\"She doesn''t need thyroid checks because she seems fine.\""}, {"id": "d", "text": "\"Her heart will be monitored because of her heart defect.\""}]'::jsonb, '["c"]', 'Nursing support includes monitoring growth, hearing, vision, thyroid, and heart, because hypothyroidism is an associated condition; skipping thyroid checks is incorrect. Early intervention with PT, OT, and speech is appropriate.', false),
  ('cog_neuro', 33, 'A 7-year-old with spastic cerebral palsy is seen in the clinic for care planning. Which interventions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Restricting activity to slow progression"}, {"id": "b", "text": "Assistive devices such as AFOs"}, {"id": "c", "text": "Safe feeding techniques for aspiration risk"}, {"id": "d", "text": "PT, OT, and speech therapy"}, {"id": "e", "text": "Methylphenidate after meals for spasticity"}]'::jsonb, '["b", "c", "d"]', 'CP care includes PT/OT/speech therapy, safe feeding techniques because of aspiration risk, and assistive devices such as AFOs. The brain injury in CP is non-progressive, and baclofen (not methylphenidate) treats spasticity.', true),
  ('cog_neuro', 34, 'A 7-year-old with autism spectrum disorder (ASD) is calmly lining up toy cars in the hospital room. The child must go to radiology in a few minutes. Which action by the nurse is BEST?', '[{"id": "a", "text": "Say, \"In 5 minutes we will go to X-ray.\""}, {"id": "b", "text": "Take the child right away to avoid a long wait"}, {"id": "c", "text": "Have an unfamiliar nurse take the child as a surprise"}, {"id": "d", "text": "Bring the child to the busy playroom while waiting"}]'::jsonb, '["a"]', 'Children with ASD need advance warning before transitions ("In 5 minutes we will…") because rigid routines mean extreme distress with change. Sudden or surprise transitions and busy environments increase distress.', false),
  ('cog_neuro', 35, 'A 5-year-old with autism spectrum disorder who covers the ears and screams at loud sounds and bright lights is being admitted. Which room assignment is MOST appropriate?', '[{"id": "a", "text": "A room near the busy nurses'' station"}, {"id": "b", "text": "A calm, low-stimulation room"}, {"id": "c", "text": "A shared room with a talkative peer"}, {"id": "d", "text": "A room next to the playroom"}]'::jsonb, '["b"]', 'Nursing care for ASD includes creating calm, low-stimulation environments, especially with sensory sensitivities to sound and light. A room near the busy nurses'' station increases stimulation.', false),
  ('cog_neuro', 36, 'An 11-year-old is brought to the clinic, and the nurse suspects an anxiety disorder. Which findings support this suspicion? Select all that apply.', '[{"id": "a", "text": "School refusal"}, {"id": "b", "text": "Brief blank stares lasting seconds"}, {"id": "c", "text": "Headaches and stomach aches"}, {"id": "d", "text": "Hand flapping and rocking"}, {"id": "e", "text": "Fidgets and talks excessively"}]'::jsonb, '["a", "c"]', 'Anxiety disorders in children often include school refusal and somatic complaints such as stomach aches and headaches. Hand flapping and rocking are ASD stimming, brief blank stares are absence seizures, and fidgeting and talking excessively are ADHD hyperactivity.', true),
  ('cog_neuro', 37, 'The parent of a 4-year-old newly diagnosed with autism spectrum disorder asks, "Is there a pill that will fix his autism?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Stimulants treat the core symptoms of autism.\""}, {"id": "b", "text": "\"Fluoxetine is approved for autism after age 8.\""}, {"id": "c", "text": "\"Baclofen will reduce his repetitive movements.\""}, {"id": "d", "text": "\"No single medication treats core symptoms.\""}]'::jsonb, '["d"]', 'There is no single medication for the core symptoms of ASD; comorbidities such as anxiety, ADHD, and seizures are treated. Fluoxetine is FDA-approved for depression in children ≥8 years, not for ASD.', false),
  ('cog_neuro', 38, 'Both the teacher and the parents of a 7-year-old report that the child is easily distracted, loses items, fidgets, can''t sit still, blurts out answers, and can''t wait for a turn. Which ADHD subtype do these findings MOST likely represent?', '[{"id": "a", "text": "Predominantly Inattentive"}, {"id": "b", "text": "Predominantly Hyperactive-Impulsive"}, {"id": "c", "text": "Combined"}, {"id": "d", "text": "None, since signs must start before age 6"}]'::jsonb, '["c"]', 'The child has inattention (easily distracted, loses items), hyperactivity (fidgets), and impulsivity (blurts out, can''t wait turn), which is the Combined subtype, the most common. Signs must appear before age 12, not age 6.', false),
  ('cog_neuro', 39, 'A teacher describes the behavior of a 7-year-old to the school nurse. Which reported behaviors are consistent with hyperactivity or impulsivity? Select all that apply.', '[{"id": "a", "text": "Interrupts and can''t wait turn"}, {"id": "b", "text": "Fidgets and can''t sit still"}, {"id": "c", "text": "Blank stare with eye blinking"}, {"id": "d", "text": "Talks excessively"}, {"id": "e", "text": "Rigid routines; distress with change"}]'::jsonb, '["a", "b", "d"]', 'Hyperactivity includes fidgeting, can''t sit still, and talking excessively; impulsivity includes interrupting and can''t wait turn. Rigid routines with extreme distress with change are ASD signs, and a blank stare with eye blinking is an absence seizure.', true),
  ('cog_neuro', 40, 'A 10-year-old''s teacher reports inattention and impulsivity in class since age 7, but the parents report no such behaviors at home or anywhere else. Which fact is MOST important for the nurse to consider?', '[{"id": "a", "text": "Signs must be present in 2 or more settings"}, {"id": "b", "text": "ADHD signs must appear before age 6"}, {"id": "c", "text": "Signs that begin after age 5 rule out ADHD"}, {"id": "d", "text": "School-only signs indicate the combined subtype"}]'::jsonb, '["a"]', 'ADHD signs appear before age 12 and are present in ≥2 settings (home AND school), so symptoms seen only at school do not meet this criterion. Onset at age 7 is within the before-12 requirement.', false),
  ('cog_neuro', 41, 'A 9-year-old with ADHD is starting methylphenidate, and the parent mentions the child is already a picky eater. Which instruction by the nurse is MOST appropriate?', '[{"id": "a", "text": "Give it at bedtime so it lasts into the next school day"}, {"id": "b", "text": "Give it after meals to reduce appetite suppression"}, {"id": "c", "text": "Give it before breakfast on an empty stomach"}, {"id": "d", "text": "Stop weighing the child once the dose is stable"}]'::jsonb, '["b"]', 'Stimulants are given AFTER meals to reduce appetite suppression. Bedtime dosing is wrong because stimulants can cause insomnia, and height and weight are monitored regularly.', false),
  ('cog_neuro', 42, 'A 9-month-old is admitted critically ill with fever, a bulging fontanel, a high-pitched cry, poor feeding, and a seizure in triage. A bacterial cause is suspected. Which orders should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Delay antibiotics until LP results"}, {"id": "b", "text": "Droplet isolation"}, {"id": "c", "text": "IV antibiotics as soon as possible"}, {"id": "d", "text": "Daily phenytoin as febrile prophylaxis"}, {"id": "e", "text": "IV dexamethasone"}]'::jsonb, '["b", "c", "e"]', 'These infant findings with fever suggest bacterial meningitis, treated with IV antibiotics ASAP (not delayed for LP if critically ill), IV dexamethasone to reduce inflammation, and droplet isolation until 24h on antibiotics. Delaying antibiotics is unsafe, and routine seizure prophylaxis is not used for febrile seizures.', true),
  ('cog_neuro', 43, 'The nurse reviews medication teaching with the parent of an 8-year-old taking amphetamine salts (Adderall) for ADHD. Which statement by the parent indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll have his height and weight checked regularly.\""}, {"id": "b", "text": "\"His blood pressure and heart rate need monitoring.\""}, {"id": "c", "text": "\"We may use drug holidays in the summer to help growth.\""}, {"id": "d", "text": "\"Stimulants can''t cause insomnia, so bedtime is fine.\""}]'::jsonb, '["d"]', 'Stimulants can cause insomnia, so the belief that they cannot and that bedtime dosing is fine needs correction. Monitoring height, weight, blood pressure, and heart rate and using drug holidays to promote growth are correct.', false),
  ('cog_neuro', 44, 'A 5-year-old has just been diagnosed with ADHD, combined type. The parent asks which treatment is usually tried FIRST at this age. Which response by the nurse is BEST?', '[{"id": "a", "text": "Methylphenidate given after meals"}, {"id": "b", "text": "Atomoxetine, a non-stimulant"}, {"id": "c", "text": "Behavioral therapy"}, {"id": "d", "text": "Fluoxetine, an SSRI"}]'::jsonb, '["c"]', 'Behavioral therapy is first-line in young children <6 years, so it is preferred for a 5-year-old. Stimulants such as methylphenidate are treatment options but are not the first-line choice in this age group.', false),
  ('cog_neuro', 45, 'A 15-year-old in the emergency department admits to having thoughts of suicide. Which actions should the nurse take? Select all that apply.', '[{"id": "a", "text": "Avoid asking about plans so as not to plant the idea"}, {"id": "b", "text": "Ask directly about suicidal ideation"}, {"id": "c", "text": "Involve the family"}, {"id": "d", "text": "Do not leave the teen alone"}, {"id": "e", "text": "Initiate a safety plan"}]'::jsonb, '["b", "c", "d", "e"]', 'The nurse should always ask directly about suicidal ideation, initiate a safety plan, involve the family, and not leave the teen alone. Asking directly does NOT plant the idea, so avoiding questions is wrong.', true),
  ('cog_neuro', 46, 'A 9-year-old has missed 8 school days this month because of stomach aches and headaches on school mornings, has trouble sleeping, and worries excessively about many things. Physical causes have been ruled out. Which treatment does the nurse anticipate FIRST?', '[{"id": "a", "text": "Cognitive-behavioral therapy (CBT)"}, {"id": "b", "text": "Fluoxetine, an SSRI, as the first treatment"}, {"id": "c", "text": "Methylphenidate after meals"}, {"id": "d", "text": "Behavioral therapy (ABA)"}]'::jsonb, '["a"]', 'These findings (excessive worry, somatic complaints, school refusal, sleep disturbance) suggest an anxiety disorder, for which CBT is first-line; SSRIs (fluoxetine) are added if moderate-severe. ABA is a behavioral therapy for ASD.', false),
  ('cog_neuro', 47, 'Over the past 2 months, a 10-year-old has become irritable and angry, stopped wanting to play soccer, sleeps poorly, eats less, and has declining school performance. The child denies feeling sad. Which condition should the nurse suspect?', '[{"id": "a", "text": "ADHD, combined type"}, {"id": "b", "text": "Depression"}, {"id": "c", "text": "Absence seizures"}, {"id": "d", "text": "Separation anxiety"}]'::jsonb, '["b"]', 'Depression in children may present as irritability rather than sadness, with loss of interest, sleep/appetite changes, and declining school performance. ADHD signs appear in ≥2 settings as inattention, hyperactivity, and impulsivity, not loss of interest and appetite change.', false),
  ('cog_neuro', 48, 'A 15-year-old being treated for depression gave away a prized guitar last week and texted friends "goodbye." Which action should the nurse take FIRST?', '[{"id": "a", "text": "Avoid mentioning suicide so the idea isn''t planted"}, {"id": "b", "text": "Ask the parents whether the teen seems sad at home"}, {"id": "c", "text": "Ask the teen directly about suicidal ideation"}, {"id": "d", "text": "Schedule a follow-up visit for next week"}]'::jsonb, '["c"]', 'Giving away prized possessions and saying goodbye are red flags; the nurse should always ask directly about suicidal ideation, which does NOT plant the idea. Delaying with a follow-up visit leaves the risk unassessed.', false),
  ('cog_neuro', 49, 'A 16-year-old started fluoxetine 10 days ago for depression. At a follow-up visit the teen reports several findings. Which finding requires IMMEDIATE follow-up?', '[{"id": "a", "text": "Ongoing fatigue during the day"}, {"id": "b", "text": "Irritability with siblings at home"}, {"id": "c", "text": "Poor concentration during class"}, {"id": "d", "text": "Talking about being a burden"}]'::jsonb, '["d"]', 'Talking about being a burden is a suicide red flag, and adolescents starting SSRIs must be monitored for increased suicidal ideation (FDA black-box warning). Fatigue, irritability, and poor concentration are signs of depression that do not signal immediate danger.', false),
  ('cog_neuro', 50, 'The nurse receives report on four children on a pediatric neuro unit. Which child should the nurse assess FIRST?', '[{"id": "a", "text": "A 6-month-old with a VP shunt who has a high-pitched cry and projectile vomiting"}, {"id": "b", "text": "A 7-year-old with Down syndrome who has low muscle tone and a protruding tongue"}, {"id": "c", "text": "An 8-year-old taking methylphenidate for ADHD who has a decreased appetite at lunch"}, {"id": "d", "text": "A 5-year-old with spastic CP who walks with a scissors gait and uses AFOs"}]'::jsonb, '["a"]', 'A high-pitched cry and projectile vomiting in an infant with a VP shunt signal return of increased ICP (shunt failure). Hypotonia and a protruding tongue are expected Down syndrome features, decreased appetite is an expected stimulant effect, and scissors gait is expected in spastic CP.', false)
  ) AS v(source_key, display_order, stem, options, correct_answer, rationale, is_multi)
  JOIN _peds_seed_map m USING (source_key)
 CROSS JOIN _peds_seed_config c;

DO $$
DECLARE
  v_bad text;
BEGIN
  SELECT string_agg(format('%s=%s', m.source_key, coalesce(n.cnt, 0)), ', ')
    INTO v_bad
    FROM _peds_seed_map m
    LEFT JOIN (SELECT category, count(*) AS cnt FROM test_questions GROUP BY category) n
      ON n.category = m.category
   WHERE coalesce(n.cnt, 0) <> 50;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'Pediatrics seed post-check failed (expected 50 per topic): %', v_bad;
  END IF;
END $$;

COMMIT;
